CREATE FUNCTION public._assert_concepto_no_proformado() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_setting('app.bypass_cierre', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.proforma_id IS NOT NULL THEN
      RAISE EXCEPTION
        'LC_CONCEPTO_PROFORMADO: el concepto ya está incluido en una proforma y no puede eliminarse'
        USING ERRCODE = 'P0001';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.proforma_id IS NOT NULL
     AND (NEW.descripcion       IS DISTINCT FROM OLD.descripcion
       OR NEW.cantidad          IS DISTINCT FROM OLD.cantidad
       OR NEW.precio_unitario   IS DISTINCT FROM OLD.precio_unitario
       OR NEW.moneda            IS DISTINCT FROM OLD.moneda
       OR NEW.aplica_iva        IS DISTINCT FROM OLD.aplica_iva
       OR NEW.tasa_iva_aplicada IS DISTINCT FROM OLD.tasa_iva_aplicada) THEN
    RAISE EXCEPTION
      'LC_CONCEPTO_PROFORMADO: el concepto ya está incluido en una proforma; libéralo de la proforma antes de editarlo'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._assert_email_unico_org() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dup int;
BEGIN
  IF NEW.email IS NULL OR btrim(NEW.email) = '' OR NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.email IS NOT DISTINCT FROM NEW.email THEN
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME = 'clientes' THEN
    SELECT count(*) INTO v_dup
    FROM public.clientes c
    WHERE c.organization_id = NEW.organization_id
      AND c.deleted_at IS NULL
      AND c.id <> NEW.id
      AND lower(btrim(coalesce(c.email, ''))) = lower(btrim(NEW.email));
  ELSE
    SELECT count(*) INTO v_dup
    FROM public.contactos_cliente c
    WHERE c.organization_id = NEW.organization_id
      AND c.deleted_at IS NULL
      AND c.id <> NEW.id
      AND lower(btrim(coalesce(c.email, ''))) = lower(btrim(NEW.email));
  END IF;
  IF v_dup > 0 THEN
    RAISE EXCEPTION 'LC_EMAIL_DUPLICADO: el correo % ya está registrado en esta organización.', NEW.email
      USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._assert_facturapi_admin(p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'no_auth' USING ERRCODE = '28000';
  END IF;
  -- super_admin o contador (roles globales) siempre pueden
  IF public.has_role(v_uid, 'super_admin'::public.app_role)
     OR public.has_role(v_uid, 'contador'::public.app_role) THEN
    RETURN;
  END IF;
  -- admin_org / admin dentro de la organización también
  IF NOT EXISTS (
    SELECT 1
      FROM public.organization_members om
     WHERE om.user_id = v_uid
       AND om.organization_id = p_org_id
       AND om.role IN ('admin_org','admin')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
END;
$$;
CREATE FUNCTION public._assert_internal_reader(p_org uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := public.current_user_org_id();
  v_super boolean := public.has_role(auth.uid(), 'super_admin'::app_role);
BEGIN
  IF NOT v_super AND (v_org IS NULL OR p_org IS NULL) THEN
    RAISE EXCEPTION 'LC_SIN_ORG: tu usuario no tiene organización asignada' USING ERRCODE = '42501';
  END IF;
  IF NOT (
    v_super
    OR (
      p_org = v_org
      AND (
        public.has_role(auth.uid(), 'admin'::app_role)
        OR public.has_role(auth.uid(), 'operador'::app_role)
        OR public.has_role(auth.uid(), 'contador'::app_role)
      )
    )
  ) THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;
END;
$$;
CREATE FUNCTION public._assert_medidas_embarque(p_embarque jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE((p_embarque->>'peso_kg')::numeric, 0) < 0 THEN
    RAISE EXCEPTION 'LC_EMBARQUE_PESO_INVALIDO: el peso no puede ser negativo' USING ERRCODE = '22023';
  END IF;
  IF COALESCE((p_embarque->>'volumen_m3')::numeric, 0) < 0 THEN
    RAISE EXCEPTION 'LC_EMBARQUE_VOLUMEN_INVALIDO: el volumen no puede ser negativo' USING ERRCODE = '22023';
  END IF;
  IF COALESCE((p_embarque->>'piezas')::numeric, 0) < 0 THEN
    RAISE EXCEPTION 'LC_EMBARQUE_PIEZAS_INVALIDO: las piezas no pueden ser negativas' USING ERRCODE = '22023';
  END IF;
END;
$$;
CREATE FUNCTION public._assert_nc_prov_no_excede_saldo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total  numeric;
  v_moneda text;
  v_pagado numeric;
  v_otras  numeric;
  v_esta   numeric;
  v_saldo  numeric;
BEGIN
  IF NEW.estado::text <> 'Aplicada' OR NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE'
     AND OLD.estado::text = 'Aplicada'
     AND OLD.monto IS NOT DISTINCT FROM NEW.monto
     AND OLD.moneda IS NOT DISTINCT FROM NEW.moneda
     AND OLD.tipo_cambio IS NOT DISTINCT FROM NEW.tipo_cambio
     AND OLD.deleted_at IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT pf.total, pf.moneda::text
    INTO v_total, v_moneda
    FROM public.proveedor_facturas pf
   WHERE pf.id = NEW.proveedor_factura_id
   FOR UPDATE;
  IF v_total IS NULL THEN
    RETURN NEW;
  END IF;
  v_esta := public.monto_pago_en_moneda_factura(
    NEW.monto, NEW.moneda::text, NEW.tipo_cambio, v_moneda);
  IF v_esta IS NULL THEN
    RAISE EXCEPTION 'LC_NC_PROV_TC_REQUERIDO: no se pudo convertir la nota de crédito a la moneda de la factura; captura el tipo de cambio'
      USING ERRCODE = '22023';
  END IF;
  SELECT COALESCE(SUM(COALESCE(pp.monto_en_moneda_factura, pp.monto)), 0)
    INTO v_pagado
    FROM public.pagos_proveedor pp
   WHERE pp.proveedor_factura_id = NEW.proveedor_factura_id
     AND pp.deleted_at IS NULL;
  SELECT COALESCE(SUM(
           public.monto_pago_en_moneda_factura(
             nc.monto, nc.moneda::text, nc.tipo_cambio, v_moneda)), 0)
    INTO v_otras
    FROM public.proveedor_notas_credito nc
   WHERE nc.proveedor_factura_id = NEW.proveedor_factura_id
     AND nc.deleted_at IS NULL
     AND nc.estado::text = 'Aplicada'
     AND nc.id <> NEW.id;
  v_saldo := COALESCE(v_total,0) - v_pagado - v_otras;
  IF v_esta > v_saldo + 0.01 THEN
    RAISE EXCEPTION 'LC_NC_PROV_EXCEDE_SALDO: la nota de crédito (%) excede el saldo disponible (%) de la factura de proveedor',
      round(v_esta, 2), round(v_saldo, 2)
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._assert_padre_misma_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_col    text := TG_ARGV[0];
  v_padre  text := TG_ARGV[1];
  v_id     uuid;
  v_org    uuid;
BEGIN
  v_id  := (to_jsonb(NEW) ->> v_col)::uuid;
  v_org := (to_jsonb(NEW) ->> 'organization_id')::uuid;
  IF v_id IS NULL OR v_org IS NULL THEN
    RETURN NEW;
  END IF;
  EXECUTE format(
    'SELECT organization_id FROM public.%I WHERE id = $1', v_padre
  ) INTO v_org USING v_id;
  IF v_org IS NULL THEN
    RETURN NEW; -- la FK se encarga de la existencia
  END IF;
  IF v_org <> (to_jsonb(NEW) ->> 'organization_id')::uuid THEN
    RAISE EXCEPTION
      'LC_ORG_CRUZADA: %.% apunta a un registro de otra organización (%)',
      TG_TABLE_NAME, v_col, v_padre
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$_$;
CREATE FUNCTION public._assert_pago_pue_exhibicion_unica() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_metodo text;
  v_total  numeric;
  v_otros  integer;
BEGIN
  SELECT f.metodo_pago, f.total
    INTO v_metodo, v_total
    FROM public.facturas f
   WHERE f.id = NEW.factura_id;
  -- Factura inexistente (lo resuelve la FK) o PPD: sin restricción extra.
  IF NOT FOUND OR v_metodo IS DISTINCT FROM 'PUE' THEN
    RETURN NEW;
  END IF;
  -- Una sola exhibición: no puede coexistir con otro pago vivo de la factura.
  SELECT count(*) INTO v_otros
    FROM public.pagos_factura p
   WHERE p.factura_id = NEW.factura_id
     AND p.deleted_at IS NULL
     AND p.id IS DISTINCT FROM NEW.id;
  IF v_otros > 0 THEN
    RAISE EXCEPTION 'LC_PAGO_PUE_EXHIBICION_UNICA: la factura es PUE y ya tiene un pago registrado; PUE exige liquidar en una sola exhibición. Cancela el pago previo si fue un error.'
      USING ERRCODE = 'P0001';
  END IF;
  -- El pago debe liquidar el total de la factura (tolerancia 0.05 por redondeo).
  IF COALESCE(NEW.monto_aplicado_factura, NEW.monto) < v_total - 0.05 THEN
    RAISE EXCEPTION 'LC_PAGO_PUE_DEBE_LIQUIDAR_TOTAL: la factura es PUE; registra el cobro por el total (%) en una sola exhibición. Si el cliente abona, cambia la factura a PPD.', v_total
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END
$$;
CREATE FUNCTION public._assert_periodo_abierto() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_col    text := TG_ARGV[0];
  v_cierre date;
  v_new    date;
  v_old    date;
BEGIN
  IF current_setting('app.bypass_cierre_periodo', true) = '1' THEN
    RETURN NEW;
  END IF;
  v_new := NULLIF(to_jsonb(NEW) ->> v_col, '')::date;
  IF TG_OP = 'UPDATE' THEN
    v_old := NULLIF(to_jsonb(OLD) ->> v_col, '')::date;
    IF v_new IS NOT DISTINCT FROM v_old THEN
      RETURN NEW;  -- la fecha no cambió: los recálculos de estado siguen libres
    END IF;
  END IF;
  v_cierre := public.cierre_periodo_fecha(NEW.organization_id);
  IF v_cierre IS NULL THEN
    RETURN NEW;
  END IF;
  IF v_new IS NOT NULL AND v_new <= v_cierre THEN
    RAISE EXCEPTION
      'LC_PERIODO_CERRADO: el periodo contable está cerrado hasta el %; la fecha % no es válida',
      v_cierre, v_new USING ERRCODE = 'P0001';
  END IF;
  IF v_old IS NOT NULL AND v_old <= v_cierre THEN
    RAISE EXCEPTION
      'LC_PERIODO_CERRADO: el periodo contable está cerrado hasta el %; no se puede mover la fecha % de un registro ya cerrado',
      v_cierre, v_old USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._assert_receptor_fiscal_valido(p_cliente_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v public.clientes%ROWTYPE;
  v_faltantes text[] := ARRAY[]::text[];
  v_cp text;
BEGIN
  SELECT * INTO v FROM public.clientes WHERE id = p_cliente_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_CLIENTE_DESTINO: el cliente destino no existe' USING ERRCODE = 'P0002';
  END IF;
  IF btrim(COALESCE(v.nombre, '')) = '' THEN
    v_faltantes := v_faltantes || 'razón social';
  END IF;
  IF NOT public._rfc_valido(v.rfc, false) THEN
    RAISE EXCEPTION 'LC_REFACT_RFC_INVALIDO: el RFC del receptor (%) no tiene formato válido del SAT o es genérico',
      COALESCE(v.rfc, '(vacío)') USING ERRCODE = 'P0001';
  END IF;
  IF btrim(COALESCE(v.regimen_fiscal, '')) = '' THEN
    v_faltantes := v_faltantes || 'régimen fiscal';
  END IF;
  v_cp := btrim(COALESCE(NULLIF(btrim(COALESCE(v.codigo_postal, '')), ''), COALESCE(v.cp, '')));
  IF v_cp !~ '^[0-9]{5}$' THEN
    v_faltantes := v_faltantes || 'código postal (5 dígitos)';
  END IF;
  IF array_length(v_faltantes, 1) > 0 THEN
    RAISE EXCEPTION 'LC_REFACT_RECEPTOR_INCOMPLETO: faltan datos fiscales del receptor: %',
      array_to_string(v_faltantes, ', ') USING ERRCODE = 'P0001';
  END IF;
END;
$_$;
CREATE FUNCTION public._assert_refacturador(p_org uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF public.has_role(v_uid, 'super_admin'::app_role) THEN
    RETURN;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = v_uid
      AND organization_id = p_org
      AND role IN ('admin_org','admin','contador','auxiliar_contable')
  ) THEN
    RAISE EXCEPTION 'LC_REFACT_FORBIDDEN: se requiere rol de administrador de la organización o un rol contable'
      USING ERRCODE = '42501';
  END IF;
END;
$$;
CREATE FUNCTION public._assert_relaciones_embarque(p_org uuid, p_cliente_id uuid, p_cotizacion_id uuid, p_conceptos_costo jsonb) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cot record;
  v_prov uuid;
BEGIN
  IF p_cliente_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.clientes c
     WHERE c.id = p_cliente_id AND c.organization_id = p_org AND c.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'LC_EMB_CLIENTE_INVALIDO: el cliente no existe en tu organización o fue eliminado.'
      USING ERRCODE = '42501';
  END IF;
  IF p_cotizacion_id IS NOT NULL THEN
    SELECT id, cliente_id, estado INTO v_cot
      FROM public.cotizaciones
     WHERE id = p_cotizacion_id AND organization_id = p_org AND deleted_at IS NULL;
    IF v_cot.id IS NULL THEN
      RAISE EXCEPTION 'LC_EMB_COTIZACION_INVALIDA: la cotización no existe en tu organización o fue eliminada.'
        USING ERRCODE = '42501';
    END IF;
    IF p_cliente_id IS NOT NULL AND v_cot.cliente_id IS NOT NULL
       AND v_cot.cliente_id <> p_cliente_id THEN
      RAISE EXCEPTION 'LC_EMB_COTIZACION_CLIENTE: la cotización pertenece a otro cliente.'
        USING ERRCODE = '42501';
    END IF;
    IF v_cot.estado NOT IN ('Aceptada'::estado_cotizacion, 'En operación'::estado_cotizacion) THEN
      RAISE EXCEPTION 'LC_COT_ESTADO_INVALIDO: la cotización debe estar Aceptada o En operación (actual: %)', v_cot.estado
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  FOR v_prov IN
    SELECT DISTINCT NULLIF(elem->>'proveedor_id', '')::uuid
      FROM jsonb_array_elements(COALESCE(p_conceptos_costo, '[]'::jsonb)) elem
     WHERE NULLIF(elem->>'proveedor_id', '') IS NOT NULL
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.proveedores pr
       WHERE pr.id = v_prov AND pr.organization_id = p_org AND pr.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'LC_EMB_PROVEEDOR_INVALIDO: un proveedor de los costos no existe en tu organización o fue eliminado.'
        USING ERRCODE = '42501';
    END IF;
  END LOOP;
END;
$$;
CREATE FUNCTION public._assert_soft_delete_factura_sin_hijos() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.deleted_at IS NULL OR OLD.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  -- Sólo las facturas que nunca se emitieron pueden mandarse a la basura.
  IF OLD.snapshot_emision IS NULL AND OLD.estado = 'Borrador' THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.pagos_factura p
    WHERE p.factura_id = OLD.id AND p.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'LC_FACTURA_DELETE_CON_PAGOS: la factura % tiene pagos registrados; elimina o cancela los pagos antes de borrarla', OLD.numero
      USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.factura_notas_credito nc
    WHERE nc.factura_id = OLD.id
      AND nc.deleted_at IS NULL
      AND nc.estado <> 'Cancelada'
  ) THEN
    RAISE EXCEPTION 'LC_FACTURA_DELETE_CON_NC: la factura % tiene notas de crédito vivas; cancélalas antes de borrarla', OLD.numero
      USING ERRCODE = 'P0001';
  END IF;
  IF OLD.snapshot_emision IS NOT NULL AND OLD.estado <> 'Cancelada' THEN
    RAISE EXCEPTION 'LC_FACTURA_DELETE_EMITIDA: la factura % ya fue emitida; cancélala en el SAT antes de borrarla', OLD.numero
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._assert_tc_banda() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row jsonb := to_jsonb(NEW);
  v_tc numeric;
  v_moneda text := v_row->>'moneda';
  v_moneda_doc text;
BEGIN
  v_tc := COALESCE(
    NULLIF(v_row->>'tipo_cambio_usd', '')::numeric,
    NULLIF(v_row->>'tipo_cambio', '')::numeric
  );
  IF v_tc IS NULL OR v_moneda IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME = 'pagos_proveedor' THEN
    SELECT pf.moneda::text INTO v_moneda_doc
    FROM public.proveedor_facturas pf
    WHERE pf.id = (v_row->>'proveedor_factura_id')::uuid;
  ELSE
    SELECT f.moneda::text INTO v_moneda_doc
    FROM public.facturas f
    WHERE f.id = (v_row->>'factura_id')::uuid;
  END IF;
  -- Sin conversión de moneda (pago y documento en la misma divisa) el factor
  -- neutro 1 es correcto y no se evalúa la banda.
  IF v_moneda_doc IS NOT NULL AND v_moneda_doc = v_moneda THEN
    RETURN NEW;
  END IF;
  IF (v_moneda <> 'MXN' OR COALESCE(v_moneda_doc, 'MXN') <> 'MXN')
     AND (v_tc < 5 OR v_tc > 40) THEN
    RAISE EXCEPTION
      'LC_TC_FUERA_DE_BANDA: el tipo de cambio (%) está fuera de la banda razonable (5 a 40 MXN por divisa).',
      v_tc
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._assert_uuid_fiscal_single_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.uuid_fiscal IS NOT NULL
     AND NEW.uuid_fiscal IS DISTINCT FROM OLD.uuid_fiscal THEN
    RAISE EXCEPTION
      'LC_UUID_FISCAL_INMUTABLE: el folio fiscal de la factura % ya fue asignado y no puede cambiarse',
      OLD.numero USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._assert_writer(p_org uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := public.current_user_org_id();
  v_super boolean := public.has_role(auth.uid(), 'super_admin'::app_role);
BEGIN
  IF NOT v_super AND (v_org IS NULL OR p_org IS NULL) THEN
    RAISE EXCEPTION 'LC_SIN_ORG: tu usuario no tiene organización asignada' USING ERRCODE = '42501';
  END IF;
  IF NOT (
    v_super
    OR (
      p_org = v_org
      AND (
        public.has_role(auth.uid(), 'admin'::app_role)
        OR public.has_role(auth.uid(), 'operador'::app_role)
        OR public.has_role(auth.uid(), 'contador'::app_role)
      )
    )
  ) THEN
    RAISE EXCEPTION 'Permisos insuficientes' USING ERRCODE = '42501';
  END IF;
END;
$$;
CREATE FUNCTION public._assert_writer_cotizacion(p_org uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := public.current_user_org_id();
  v_super boolean := public.has_role(auth.uid(), 'super_admin'::app_role);
BEGIN
  IF NOT v_super AND (v_org IS NULL OR p_org IS NULL) THEN
    RAISE EXCEPTION 'LC_SIN_ORG: tu usuario no tiene organización asignada' USING ERRCODE = '42501';
  END IF;
  IF NOT (
    v_super
    OR (p_org = v_org AND public.puede_escribir_cotizaciones(auth.uid()))
  ) THEN
    RAISE EXCEPTION 'Permisos insuficientes' USING ERRCODE = '42501';
  END IF;
END;
$$;
CREATE FUNCTION public._audit_costos_repetidos(p_organization_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH emb AS (
    SELECT e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
    FROM embarques e
    WHERE e.organization_id = p_organization_id
      AND e.deleted_at IS NULL
      AND e.estado::text <> 'Cancelado'
  ),
  n_conts AS (
    SELECT ec.embarque_id, COUNT(*) AS n
    FROM embarque_contenedores ec
    WHERE ec.deleted_at IS NULL
      AND ec.embarque_id IN (SELECT id FROM emb)
    GROUP BY ec.embarque_id
  ),
  grupos AS (
    SELECT cc.embarque_id, cc.concepto, cc.monto, cc.moneda::text AS moneda, COUNT(*) AS copias
    FROM conceptos_costo cc
    WHERE cc.deleted_at IS NULL
      AND cc.embarque_id IN (SELECT id FROM emb)
    GROUP BY cc.embarque_id, cc.concepto, cc.monto, cc.moneda, COALESCE(cc.contenedor_id::text, '-')
    HAVING COUNT(*) > 1
  ),
  sospechosos AS (
    SELECT g.embarque_id, COUNT(*) AS n_grupos, SUM(g.copias - 1) AS n_extras
    FROM grupos g
    LEFT JOIN n_conts nc ON nc.embarque_id = g.embarque_id
    WHERE g.copias <> COALESCE(nc.n, 0)
    GROUP BY g.embarque_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'embarque_id', e.id, 'expediente', e.expediente,
    'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
    'regla', 'costos_repetidos', 'severidad', 'alto',
    'detalle', s.n_grupos || ' grupo(s) de costos idénticos repetidos (' || s.n_extras ||
               ' renglón(es) de más) que no corresponden al número de contenedores; revisa si son duplicados',
    'documentos_faltantes', '[]'::jsonb
  )), '[]'::jsonb)
  FROM sospechosos s
  JOIN emb e ON e.id = s.embarque_id;
$$;
CREATE FUNCTION public._audit_embarques_agregar(p_hallazgos jsonb, p_umbrales jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'generated_at', now(),
    'total_hallazgos', COUNT(*),
    'por_severidad', jsonb_build_object(
      'critico', COUNT(*) FILTER (WHERE h->>'severidad' = 'critico'),
      'alto',    COUNT(*) FILTER (WHERE h->>'severidad' = 'alto'),
      'medio',   COUNT(*) FILTER (WHERE h->>'severidad' = 'medio')
    ),
    'por_regla', jsonb_build_object(
      'docs_faltantes',                COUNT(*) FILTER (WHERE h->>'regla' = 'docs_faltantes'),
      'docs_pendientes_avanzado',      COUNT(*) FILTER (WHERE h->>'regla' = 'docs_pendientes_avanzado'),
      'fechas',                        COUNT(*) FILTER (WHERE h->>'regla' = 'fechas'),
      'ventas_sin_facturar',           COUNT(*) FILTER (WHERE h->>'regla' = 'ventas_sin_facturar'),
      'margen_negativo',               COUNT(*) FILTER (WHERE h->>'regla' = 'margen_negativo'),
      'margen_bajo',                   COUNT(*) FILTER (WHERE h->>'regla' = 'margen_bajo'),
      'venta_sin_costo',               COUNT(*) FILTER (WHERE h->>'regla' = 'venta_sin_costo'),
      'costo_sin_venta',               COUNT(*) FILTER (WHERE h->>'regla' = 'costo_sin_venta'),
      'proforma_vencida',              COUNT(*) FILTER (WHERE h->>'regla' = 'proforma_vencida'),
      'proforma_borrador_abandonada',  COUNT(*) FILTER (WHERE h->>'regla' = 'proforma_borrador_abandonada'),
      'proforma_inconsistente',        COUNT(*) FILTER (WHERE h->>'regla' = 'proforma_inconsistente'),
      'embarque_huerfano',             COUNT(*) FILTER (WHERE h->>'regla' = 'embarque_huerfano'),
      'factura_sin_timbrar',           COUNT(*) FILTER (WHERE h->>'regla' = 'factura_sin_timbrar'),
      'rep_pendiente',                 COUNT(*) FILTER (WHERE h->>'regla' = 'rep_pendiente'),
      'factura_cancelada_sin_sustitucion', COUNT(*) FILTER (WHERE h->>'regla' = 'factura_cancelada_sin_sustitucion'),
      'cxc_vencida',                   COUNT(*) FILTER (WHERE h->>'regla' = 'cxc_vencida'),
      'cxp_por_capturar_estancada',    COUNT(*) FILTER (WHERE h->>'regla' = 'cxp_por_capturar_estancada'),
      'cxp_vencida',                   COUNT(*) FILTER (WHERE h->>'regla' = 'cxp_vencida'),
      'contenedor_datos_incompletos',  COUNT(*) FILTER (WHERE h->>'regla' = 'contenedor_datos_incompletos'),
      'contenedor_fechas_incompletas', COUNT(*) FILTER (WHERE h->>'regla' = 'contenedor_fechas_incompletas'),
      'tipo_cambio_faltante',          COUNT(*) FILTER (WHERE h->>'regla' = 'tipo_cambio_faltante'),
      'venta_total_descuadrado',       COUNT(*) FILTER (WHERE h->>'regla' = 'venta_total_descuadrado'),
      'contenedores_totales_descuadrados', COUNT(*) FILTER (WHERE h->>'regla' = 'contenedores_totales_descuadrados')
    ),
    'umbrales', p_umbrales,
    'hallazgos', COALESCE(jsonb_agg(h ORDER BY
      CASE h->>'severidad' WHEN 'critico' THEN 1 WHEN 'alto' THEN 2 ELSE 3 END,
      h->>'expediente'
    ), '[]'::jsonb)
  )
  FROM jsonb_array_elements(COALESCE(p_hallazgos, '[]'::jsonb)) AS t(h);
$$;
CREATE FUNCTION public._audit_embarques_umbrales(p_organization_id uuid) RETURNS TABLE(margen_min_pct numeric, dias_prof_venc integer, dias_huerfano integer, dias_borrador_abandonado integer, dias_cxc_vencida integer, dias_cxp_captura integer, dias_cxp_vencida integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH cfg AS (
    SELECT clave, (valor #>> '{}') AS v
    FROM configuracion
    WHERE organization_id = p_organization_id
      AND categoria = 'auditoria'
      AND clave IN (
        'margen_minimo_pct',
        'dias_proforma_vencida',
        'dias_huerfano',
        'dias_borrador_abandonado',
        'dias_cxc_vencida',
        'dias_cxp_captura',
        'dias_cxp_vencida'
      )
  )
  SELECT
    COALESCE((SELECT NULLIF(v,'')::numeric FROM cfg WHERE clave = 'margen_minimo_pct'), 5)::numeric               AS margen_min_pct,
    COALESCE((SELECT NULLIF(v,'')::int     FROM cfg WHERE clave = 'dias_proforma_vencida'), 30)::int              AS dias_prof_venc,
    COALESCE((SELECT NULLIF(v,'')::int     FROM cfg WHERE clave = 'dias_huerfano'), 5)::int                       AS dias_huerfano,
    GREATEST(COALESCE((SELECT NULLIF(v,'')::int FROM cfg WHERE clave = 'dias_borrador_abandonado'), 15), 1)::int  AS dias_borrador_abandonado,
    GREATEST(COALESCE((SELECT NULLIF(v,'')::int FROM cfg WHERE clave = 'dias_cxc_vencida'), 0), 0)::int           AS dias_cxc_vencida,
    GREATEST(COALESCE((SELECT NULLIF(v,'')::int FROM cfg WHERE clave = 'dias_cxp_captura'), 7), 1)::int           AS dias_cxp_captura,
    GREATEST(COALESCE((SELECT NULLIF(v,'')::int FROM cfg WHERE clave = 'dias_cxp_vencida'), 0), 0)::int           AS dias_cxp_vencida;
$$;
CREATE FUNCTION public._auditoria_embarques_org_base(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_margen_min_pct numeric;
  v_dias_prof_venc int;
  v_dias_huerfano int;
  v_dias_borrador_abandonado int;
  v_dias_cxc_vencida int;
  v_dias_cxp_captura int;
  v_dias_cxp_vencida int;
  v_fecha_corte_facturacion constant date := DATE '2026-04-01';
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'p_organization_id es obligatorio';
  END IF;
  PERFORM public._assert_internal_reader(p_organization_id);
  SELECT u.margen_min_pct, u.dias_prof_venc, u.dias_huerfano,
         u.dias_borrador_abandonado, u.dias_cxc_vencida,
         u.dias_cxp_captura, u.dias_cxp_vencida
    INTO v_margen_min_pct, v_dias_prof_venc, v_dias_huerfano,
         v_dias_borrador_abandonado, v_dias_cxc_vencida,
         v_dias_cxp_captura, v_dias_cxp_vencida
    FROM public._audit_embarques_umbrales(p_organization_id) u;
  WITH
  emb AS (
    SELECT id, expediente, cliente_nombre, modo, estado, etd, eta,
           fecha_llegada_real, tipo_servicio, tipo_carga, operador,
           tipo_cambio_usd, tipo_cambio_eur, fecha_creacion
    FROM embarques
    WHERE estado <> 'Cancelado'
      AND deleted_at IS NULL
      AND organization_id = p_organization_id
  ),
  docs_existentes AS (
    SELECT embarque_id, nombre,
           bool_or(archivo IS NOT NULL OR estado = 'No aplica') AS satisfecho
    FROM documentos_embarque
    WHERE embarque_id IN (SELECT id FROM emb) AND deleted_at IS NULL
    GROUP BY embarque_id, nombre
  ),
  exigidos AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           d.doc_nombre
    FROM emb e
    CROSS JOIN LATERAL unnest(
      public._docs_requeridos_por_estado(e.modo::text, e.estado::text)
    ) AS d(doc_nombre)
  ),
  hall_docs_faltantes AS (
    SELECT jsonb_build_object(
      'embarque_id', x.embarque_id, 'expediente', x.expediente,
      'cliente_nombre', x.cliente_nombre, 'modo', x.modo::text, 'estado', x.estado::text, 'eta', x.eta,
      'regla', 'docs_faltantes', 'severidad', 'critico',
      'detalle', 'Documentos faltantes para estado ' || x.estado::text || ': ' || string_agg(x.doc_nombre, ', '),
      'documentos_faltantes', to_jsonb(array_agg(x.doc_nombre))
    ) AS h
    FROM exigidos x
    LEFT JOIN docs_existentes de
      ON de.embarque_id = x.embarque_id AND de.nombre = x.doc_nombre
    WHERE COALESCE(de.satisfecho, false) = false
    GROUP BY x.embarque_id, x.expediente, x.cliente_nombre, x.modo, x.estado, x.eta
  ),
  hall_docs_pendientes AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'docs_pendientes_avanzado', 'severidad', 'alto',
      'detalle', 'Documentos en estado Pendiente: ' || string_agg(d.nombre, ', '),
      'documentos_faltantes', to_jsonb(array_agg(d.nombre))
    ) AS h
    FROM emb e
    JOIN documentos_embarque d ON d.embarque_id = e.id AND d.deleted_at IS NULL
    WHERE e.estado IN ('En Aduana','Llegada','Arribo','Entregado','Cerrado')
      AND d.estado = 'Pendiente'
      AND d.nombre = ANY(public._docs_requeridos_por_estado(e.modo::text, e.estado::text))
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  hall_fechas AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'fechas', 'severidad', 'alto',
      'detalle', e.detalle,
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM (
      SELECT e.*, CASE
          WHEN e.estado = 'En Tránsito' AND e.etd IS NULL THEN 'Embarque En Tránsito sin ETD'
          WHEN e.estado = 'En Tránsito' AND e.eta IS NULL THEN 'Embarque En Tránsito sin ETA'
          WHEN e.estado IN ('Entregado','Cerrado') AND e.fecha_llegada_real IS NULL
            THEN 'Embarque ' || e.estado::text || ' sin fecha de llegada real'
        END AS detalle
      FROM emb e
    ) e
    WHERE detalle IS NOT NULL
  ),
  hall_ventas AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'ventas_sin_facturar', 'severidad', 'critico',
      'detalle', COUNT(cv.id) || ' concepto(s) de venta pendientes de facturar (' || to_char(SUM(cv.total),'FM999,999,990.00') || ' ' || COALESCE(MAX(cv.moneda::text),'MXN') || ')',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN conceptos_venta cv ON cv.embarque_id = e.id AND cv.deleted_at IS NULL
    WHERE e.estado IN ('Entregado','Cerrado')
      AND cv.estado_facturacion = 'pendiente'
      AND (e.etd IS NULL OR e.etd >= v_fecha_corte_facturacion)
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  emb_sin_tc AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           bool_or(cv.moneda::text = 'USD') AS tiene_usd_venta,
           bool_or(cv.moneda::text = 'EUR') AS tiene_eur_venta
    FROM emb e
    JOIN conceptos_venta cv ON cv.embarque_id = e.id AND cv.deleted_at IS NULL
    WHERE cv.moneda::text IN ('USD','EUR')
      AND (
        (cv.moneda::text = 'USD' AND COALESCE(NULLIF(CASE WHEN e.tipo_cambio_usd > 1 THEN e.tipo_cambio_usd END,0),0) = 0)
        OR (cv.moneda::text = 'EUR' AND COALESCE(NULLIF(e.tipo_cambio_eur,0),0) = 0)
      )
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  emb_sin_tc_costo AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           bool_or(cc.moneda::text = 'USD') AS tiene_usd_costo,
           bool_or(cc.moneda::text = 'EUR') AS tiene_eur_costo
    FROM emb e
    JOIN conceptos_costo cc ON cc.embarque_id = e.id AND cc.deleted_at IS NULL
    WHERE cc.moneda::text IN ('USD','EUR')
      AND (
        (cc.moneda::text = 'USD' AND COALESCE(NULLIF(CASE WHEN e.tipo_cambio_usd > 1 THEN e.tipo_cambio_usd END,0),0) = 0)
        OR (cc.moneda::text = 'EUR' AND COALESCE(NULLIF(e.tipo_cambio_eur,0),0) = 0)
      )
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  emb_falta_tc AS (
    SELECT COALESCE(v.embarque_id, c.embarque_id) AS embarque_id,
           COALESCE(v.expediente, c.expediente) AS expediente,
           COALESCE(v.cliente_nombre, c.cliente_nombre) AS cliente_nombre,
           COALESCE(v.modo, c.modo) AS modo,
           COALESCE(v.estado, c.estado) AS estado,
           COALESCE(v.eta, c.eta) AS eta,
           COALESCE(v.tiene_usd_venta, false) OR COALESCE(c.tiene_usd_costo, false) AS falta_usd,
           COALESCE(v.tiene_eur_venta, false) OR COALESCE(c.tiene_eur_costo, false) AS falta_eur
    FROM emb_sin_tc v
    FULL OUTER JOIN emb_sin_tc_costo c ON c.embarque_id = v.embarque_id
  ),
  hall_tipo_cambio_faltante AS (
    SELECT jsonb_build_object(
      'embarque_id', f.embarque_id, 'expediente', f.expediente,
      'cliente_nombre', f.cliente_nombre, 'modo', f.modo::text, 'estado', f.estado::text, 'eta', f.eta,
      'regla', 'tipo_cambio_faltante', 'severidad', 'medio',
      'detalle', 'Embarque tiene conceptos en ' ||
        CASE
          WHEN f.falta_usd AND f.falta_eur THEN 'USD y EUR'
          WHEN f.falta_usd THEN 'USD'
          ELSE 'EUR'
        END || ' sin tipo de cambio capturado; el margen no se calcula hasta corregir.',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb_falta_tc f
  ),
  ventas_mxn AS (
    SELECT cv.embarque_id,
           SUM(cv.total * CASE
             WHEN cv.moneda::text = 'USD' THEN NULLIF(CASE WHEN e.tipo_cambio_usd > 1 THEN e.tipo_cambio_usd END,0)
             WHEN cv.moneda::text = 'EUR' THEN NULLIF(e.tipo_cambio_eur,0)
             ELSE 1
           END) AS total_mxn,
           COUNT(*) AS n,
           bool_or(
             (cv.moneda::text = 'USD' AND COALESCE(NULLIF(CASE WHEN e.tipo_cambio_usd > 1 THEN e.tipo_cambio_usd END,0),0) = 0)
             OR (cv.moneda::text = 'EUR' AND COALESCE(NULLIF(e.tipo_cambio_eur,0),0) = 0)
           ) AS tc_incompleto
    FROM conceptos_venta cv
    JOIN emb e ON e.id = cv.embarque_id
    WHERE cv.deleted_at IS NULL
    GROUP BY cv.embarque_id
  ),
  costos_mxn AS (
    SELECT cc.embarque_id,
           SUM(cc.monto * CASE
             WHEN cc.moneda::text = 'USD' THEN NULLIF(CASE WHEN e.tipo_cambio_usd > 1 THEN e.tipo_cambio_usd END,0)
             WHEN cc.moneda::text = 'EUR' THEN NULLIF(e.tipo_cambio_eur,0)
             ELSE 1
           END) AS total_mxn,
           COUNT(*) AS n,
           bool_or(
             (cc.moneda::text = 'USD' AND COALESCE(NULLIF(CASE WHEN e.tipo_cambio_usd > 1 THEN e.tipo_cambio_usd END,0),0) = 0)
             OR (cc.moneda::text = 'EUR' AND COALESCE(NULLIF(e.tipo_cambio_eur,0),0) = 0)
           ) AS tc_incompleto
    FROM conceptos_costo cc
    JOIN emb e ON e.id = cc.embarque_id
    WHERE cc.deleted_at IS NULL
    GROUP BY cc.embarque_id
  ),
  margenes AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo::text AS modo,
           e.estado::text AS estado, e.eta,
           COALESCE(v.total_mxn, 0) AS venta_mxn,
           COALESCE(c.total_mxn, 0) AS costo_mxn,
           COALESCE(v.total_mxn, 0) - COALESCE(c.total_mxn, 0) AS utilidad_mxn,
           CASE WHEN COALESCE(v.total_mxn, 0) = 0 THEN NULL
                ELSE ((COALESCE(v.total_mxn,0) - COALESCE(c.total_mxn,0)) / v.total_mxn) * 100
           END AS margen_pct,
           COALESCE(v.n, 0) AS n_ventas,
           COALESCE(c.n, 0) AS n_costos,
           COALESCE(v.tc_incompleto, false) OR COALESCE(c.tc_incompleto, false) AS tc_incompleto
    FROM emb e
    LEFT JOIN ventas_mxn v ON v.embarque_id = e.id
    LEFT JOIN costos_mxn c ON c.embarque_id = e.id
    WHERE e.estado IN ('Entregado','Cerrado','En Proceso','Llegada','Arribo')
  ),
  hall_margen_neg AS (
    SELECT jsonb_build_object(
      'embarque_id', m.embarque_id, 'expediente', m.expediente,
      'cliente_nombre', m.cliente_nombre, 'modo', m.modo, 'estado', m.estado, 'eta', m.eta,
      'regla', 'margen_negativo', 'severidad', 'critico',
      'detalle', 'Margen negativo: ' || to_char(m.utilidad_mxn,'FM999,999,990.00') || ' MXN',
      'monto_mxn', m.utilidad_mxn,
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM margenes m
    WHERE m.utilidad_mxn < 0
      AND NOT m.tc_incompleto
  ),
  hall_margen_bajo AS (
    SELECT jsonb_build_object(
      'embarque_id', m.embarque_id, 'expediente', m.expediente,
      'cliente_nombre', m.cliente_nombre, 'modo', m.modo, 'estado', m.estado, 'eta', m.eta,
      'regla', 'margen_bajo', 'severidad', 'medio',
      'detalle', 'Margen ' || to_char(m.margen_pct,'FM990.0') || '% por debajo del mínimo (' || v_margen_min_pct || '%)',
      'monto_mxn', m.utilidad_mxn,
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM margenes m
    WHERE m.margen_pct IS NOT NULL
      AND m.margen_pct >= 0
      AND m.margen_pct < v_margen_min_pct
      AND NOT m.tc_incompleto
  ),
  hall_venta_sin_costo AS (
    SELECT jsonb_build_object(
      'embarque_id', m.embarque_id, 'expediente', m.expediente,
      'cliente_nombre', m.cliente_nombre, 'modo', m.modo, 'estado', m.estado, 'eta', m.eta,
      'regla', 'venta_sin_costo', 'severidad', 'alto',
      'detalle', 'Embarque tiene ventas pero ningún costo registrado',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM margenes m
    WHERE m.n_ventas > 0 AND m.n_costos = 0
  ),
  hall_costo_sin_venta AS (
    SELECT jsonb_build_object(
      'embarque_id', m.embarque_id, 'expediente', m.expediente,
      'cliente_nombre', m.cliente_nombre, 'modo', m.modo, 'estado', m.estado, 'eta', m.eta,
      'regla', 'costo_sin_venta', 'severidad', 'alto',
      'detalle', 'Embarque tiene costos pero ninguna venta registrada',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM margenes m
    WHERE m.n_costos > 0 AND m.n_ventas = 0
  ),
  proforma_pend AS (
    SELECT p.embarque_id, p.id AS proforma_id, p.numero, p.created_at
    FROM proformas p
    WHERE p.embarque_id IN (SELECT id FROM emb)
      AND p.deleted_at IS NULL
      AND p.estado_proforma = 'pendiente'
      AND COALESCE(p.estado_aprobacion, 'aprobada') <> 'borrador'
      AND COALESCE(p.total_mxn, 0) > 0
      AND EXISTS (
        SELECT 1 FROM conceptos_venta cv
        WHERE cv.proforma_id = p.id AND cv.deleted_at IS NULL
      )
      AND p.created_at < (now() - (v_dias_prof_venc || ' days')::interval)
  ),
  hall_proforma_vencida AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'proforma_vencida', 'severidad', 'alto',
      'detalle', 'Proforma ' || pp.numero || ' lleva más de ' || v_dias_prof_venc || ' días sin facturar',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN proforma_pend pp ON pp.embarque_id = e.id
  ),
  proforma_borrador AS (
    SELECT p.embarque_id, p.id AS proforma_id, p.numero, p.created_at,
           EXTRACT(DAY FROM (now() - p.created_at))::int AS dias
    FROM proformas p
    WHERE p.embarque_id IN (SELECT id FROM emb)
      AND p.deleted_at IS NULL
      AND p.estado_proforma = 'pendiente'
      AND COALESCE(p.estado_aprobacion, 'aprobada') = 'borrador'
      AND p.created_at < (now() - (v_dias_borrador_abandonado || ' days')::interval)
      AND (
        COALESCE(p.total_mxn, 0) = 0
        OR NOT EXISTS (
          SELECT 1 FROM conceptos_venta cv
          WHERE cv.proforma_id = p.id AND cv.deleted_at IS NULL
        )
      )
  ),
  hall_borrador_abandonado AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'proforma_borrador_abandonada', 'severidad', 'medio',
      'detalle', 'Proforma borrador ' || pb.numero || ' abandonada hace ' || pb.dias || ' días (sin conceptos / total cero)',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN proforma_borrador pb ON pb.embarque_id = e.id
  ),
  proforma_inconsistente AS (
    SELECT DISTINCT p.embarque_id, p.id AS proforma_id, p.numero,
           (SELECT COUNT(*) FROM conceptos_venta cv2
              WHERE cv2.embarque_id = p.embarque_id
                AND cv2.deleted_at IS NULL
                AND cv2.estado_facturacion = 'pendiente'
                AND cv2.proforma_id IS NULL) AS n_pendientes
    FROM proformas p
    WHERE p.embarque_id IN (SELECT id FROM emb)
      AND p.deleted_at IS NULL
      AND p.estado_proforma = 'pendiente'
      AND COALESCE(p.estado_aprobacion, 'aprobada') = 'borrador'
      AND (
        COALESCE(p.total_mxn, 0) = 0
        OR NOT EXISTS (
          SELECT 1 FROM conceptos_venta cv
          WHERE cv.proforma_id = p.id AND cv.deleted_at IS NULL
        )
      )
      AND EXISTS (
        SELECT 1 FROM conceptos_venta cv3
        WHERE cv3.embarque_id = p.embarque_id
          AND cv3.deleted_at IS NULL
          AND cv3.estado_facturacion = 'pendiente'
          AND cv3.proforma_id IS NULL
      )
  ),
  hall_proforma_inconsistente AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'proforma_borrador_inconsistente', 'severidad', 'alto',
      'detalle', 'Existen ' || pi.n_pendientes || ' concepto(s) sin proforma mientras la proforma borrador ' || pi.numero || ' está vacía',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN proforma_inconsistente pi ON pi.embarque_id = e.id
    WHERE pi.n_pendientes > 0
  ),
  cxc_facturas_vencidas AS (
    SELECT f.embarque_id,
           COUNT(*) AS n,
           SUM(f.total - COALESCE(p.pagado, 0)) AS pendiente
    FROM facturas f
    LEFT JOIN LATERAL (
      SELECT SUM(COALESCE(pf2.monto_aplicado_factura, pf2.monto)) AS pagado
      FROM pagos_factura pf2
      WHERE pf2.factura_id = f.id AND pf2.deleted_at IS NULL
    ) p ON true
    WHERE f.embarque_id IN (SELECT id FROM emb)
      AND f.deleted_at IS NULL
      AND f.estado NOT IN ('Cancelada','Sustituida','Pagada')
      AND f.fecha_vencimiento IS NOT NULL
      AND f.fecha_vencimiento < CURRENT_DATE - v_dias_cxc_vencida
    GROUP BY f.embarque_id
  ),
  hall_cxc_vencida AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'cxc_vencida', 'severidad', 'alto',
      'detalle', v.n || ' factura(s) vencida(s) > ' || v_dias_cxc_vencida || ' días · pendiente ' || to_char(v.pendiente,'FM999,999,990.00') || ' MXN',
      'monto_mxn', v.pendiente,
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN cxc_facturas_vencidas v ON v.embarque_id = e.id
  ),
  cxp_capturas_lentas AS (
    SELECT pf.embarque_id, COUNT(*) AS n
    FROM proveedor_facturas pf
    WHERE pf.embarque_id IN (SELECT id FROM emb)
      AND pf.deleted_at IS NULL
      AND pf.estado_aprobacion = 'pendiente'
      AND pf.created_at < now() - (v_dias_cxp_captura || ' days')::interval
    GROUP BY pf.embarque_id
  ),
  hall_cxp_captura AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'cxp_captura_lenta', 'severidad', 'medio',
      'detalle', c.n || ' factura(s) de proveedor sin aprobar > ' || v_dias_cxp_captura || ' días',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN cxp_capturas_lentas c ON c.embarque_id = e.id
  ),
  cxp_vencidas AS (
    SELECT pf.embarque_id,
           COUNT(*) AS n,
           SUM(pf.total - COALESCE(p.pagado, 0)) AS pendiente
    FROM proveedor_facturas pf
    LEFT JOIN LATERAL (
      SELECT SUM(COALESCE(pp2.monto_en_moneda_factura, pp2.monto)) AS pagado
      FROM pagos_proveedor pp2
      WHERE pp2.proveedor_factura_id = pf.id AND pp2.deleted_at IS NULL
    ) p ON true
    WHERE pf.embarque_id IN (SELECT id FROM emb)
      AND pf.deleted_at IS NULL
      AND pf.estado_aprobacion = 'aprobada'
      AND pf.estado NOT IN ('Cancelada','Pagada')
      AND pf.fecha_vencimiento IS NOT NULL
      AND pf.fecha_vencimiento < CURRENT_DATE - v_dias_cxp_vencida
    GROUP BY pf.embarque_id
  ),
  hall_cxp_vencida AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'cxp_vencida', 'severidad', 'alto',
      'detalle', v.n || ' factura(s) de proveedor vencidas > ' || v_dias_cxp_vencida || ' días · pendiente ' || to_char(v.pendiente,'FM999,999,990.00') || ' MXN',
      'monto_mxn', v.pendiente,
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN cxp_vencidas v ON v.embarque_id = e.id
  ),
  todos_hallazgos AS (
    SELECT h FROM hall_docs_faltantes
    UNION ALL SELECT h FROM hall_docs_pendientes
    UNION ALL SELECT h FROM hall_fechas
    UNION ALL SELECT h FROM hall_ventas
    UNION ALL SELECT h FROM hall_tipo_cambio_faltante
    UNION ALL SELECT h FROM hall_margen_neg
    UNION ALL SELECT h FROM hall_margen_bajo
    UNION ALL SELECT h FROM hall_venta_sin_costo
    UNION ALL SELECT h FROM hall_costo_sin_venta
    UNION ALL SELECT h FROM hall_proforma_vencida
    UNION ALL SELECT h FROM hall_borrador_abandonado
    UNION ALL SELECT h FROM hall_proforma_inconsistente
    UNION ALL SELECT h FROM hall_cxc_vencida
    UNION ALL SELECT h FROM hall_cxp_captura
    UNION ALL SELECT h FROM hall_cxp_vencida
  )
  SELECT public._audit_embarques_agregar(
    (SELECT jsonb_agg(h) FROM todos_hallazgos),
    jsonb_build_object(
      'margen_min_pct', v_margen_min_pct,
      'dias_prof_venc', v_dias_prof_venc,
      'dias_huerfano', v_dias_huerfano,
      'dias_borrador_abandonado', v_dias_borrador_abandonado,
      'dias_cxc_vencida', v_dias_cxc_vencida,
      'dias_cxp_captura', v_dias_cxp_captura,
      'dias_cxp_vencida', v_dias_cxp_vencida
    )
  )
  INTO v_result;
  RETURN v_result;
END;
$$;
CREATE FUNCTION public._bbva_guard_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_interno boolean := public._es_rol_interno();
BEGIN
  -- Inmutabilidad de los datos financieros del movimiento importado/capturado.
  IF NOT v_interno THEN
    IF NEW.cargo IS DISTINCT FROM OLD.cargo
       OR NEW.abono IS DISTINCT FROM OLD.abono
       OR NEW.saldo IS DISTINCT FROM OLD.saldo
       OR NEW.fecha IS DISTINCT FROM OLD.fecha
       OR NEW.cuenta_bancaria_id IS DISTINCT FROM OLD.cuenta_bancaria_id
       OR NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_INMUTABLE: los importes, la fecha y la cuenta de un movimiento bancario no se pueden modificar; cancela el movimiento y captúralo de nuevo'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  -- Máquina de estados de conciliación (aplica a todos los flujos).
  IF NEW.estado_conciliacion IS DISTINCT FROM OLD.estado_conciliacion THEN
    IF NOT (
      (OLD.estado_conciliacion = 'Pendiente'  AND NEW.estado_conciliacion IN ('Conciliado','Ignorado'))
      OR (OLD.estado_conciliacion = 'Conciliado' AND NEW.estado_conciliacion = 'Pendiente')
      OR (OLD.estado_conciliacion = 'Ignorado'   AND NEW.estado_conciliacion = 'Pendiente')
    ) THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_TRANSICION_INVALIDA: no se permite pasar de % a %; regresa el movimiento a Pendiente primero',
        OLD.estado_conciliacion, NEW.estado_conciliacion
        USING ERRCODE = 'P0001';
    END IF;
    IF NEW.estado_conciliacion = 'Conciliado' AND NEW.conciliado_at IS NULL THEN
      NEW.conciliado_at := now();
    END IF;
    IF NEW.estado_conciliacion = 'Pendiente' THEN
      NEW.conciliado_at := NULL;
      NEW.conciliado_por := NULL;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._bitacora_cambio_financiero() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old jsonb := to_jsonb(OLD);
  v_new jsonb := to_jsonb(NEW);
  v_diff jsonb := '{}'::jsonb;
  v_col text;
  v_modulo text := TG_ARGV[0];
  v_nombre text;
  v_org uuid;
  i int;
BEGIN
  FOR i IN 1 .. (array_length(TG_ARGV, 1) - 1) LOOP
    v_col := TG_ARGV[i];
    IF (v_new -> v_col) IS DISTINCT FROM (v_old -> v_col) THEN
      v_diff := v_diff || jsonb_build_object(
        v_col, jsonb_build_object('antes', v_old -> v_col, 'despues', v_new -> v_col));
    END IF;
  END LOOP;
  IF v_diff = '{}'::jsonb THEN
    RETURN NEW;
  END IF;
  v_org := NULLIF(v_new ->> 'organization_id', '')::uuid;
  v_nombre := COALESCE(v_new ->> 'numero', v_new ->> 'expediente',
                       v_new ->> 'folio_interno', v_new ->> 'referencia', '');
  PERFORM public.registrar_bitacora(
    v_modulo,
    'cambio_financiero_' || TG_TABLE_NAME,
    NEW.id,
    v_nombre,
    jsonb_build_object('tabla', TG_TABLE_NAME, 'cambios', v_diff),
    v_org,
    auth.uid()
  );
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._bitacora_facturas_estado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado IS DISTINCT FROM OLD.estado
     AND NEW.estado IN ('Emitida', 'Cancelada', 'Sustituida') THEN
    PERFORM public.registrar_bitacora(
      'facturacion',
      CASE NEW.estado
        WHEN 'Emitida' THEN 'timbrar_factura'
        WHEN 'Cancelada' THEN 'cancelar_factura'
        ELSE 'sustituir_factura'
      END,
      NEW.id,
      COALESCE(NULLIF(TRIM(CONCAT_WS('-', NEW.serie, NEW.numero::text)), ''), ''),
      jsonb_build_object(
        'estado_anterior', OLD.estado::text,
        'estado_nuevo', NEW.estado::text,
        'uuid_fiscal', NEW.uuid_fiscal
      ),
      NEW.organization_id,
      auth.uid()
    );
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._bitacora_normalizar_modulo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v text := lower(trim(COALESCE(NEW.modulo, '')));
BEGIN
  NEW.modulo := CASE v
    WHEN 'facturas' THEN 'facturacion'
    WHEN 'proformas' THEN 'facturacion'
    WHEN 'facturacion emitida' THEN 'facturacion'
    WHEN 'compras' THEN 'cxp'
    WHEN 'cuentas por pagar' THEN 'cxp'
    WHEN 'facturapi_credenciales' THEN 'configuracion'
    WHEN 'crm_oportunidades' THEN 'crm'
    WHEN 'crm_leads' THEN 'crm'
    WHEN 'costeo agentes' THEN 'costeo'
    WHEN 'costeo_agentes' THEN 'costeo'
    WHEN 'tracking' THEN 'embarques'
    WHEN 'bancos' THEN 'tesoreria'
    WHEN 'conciliacion' THEN 'tesoreria'
    WHEN '' THEN 'otro'
    ELSE v
  END;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._bloquear_rol_legacy_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rol_texto text := NEW.role::text;
  v_moderno text;
BEGIN
  IF v_rol_texto NOT IN ('admin', 'operador', 'viewer') THEN
    RETURN NEW;
  END IF;
  v_moderno := CASE v_rol_texto
    WHEN 'admin'    THEN 'admin_org'
    WHEN 'operador' THEN 'coordinador_logistico'
    WHEN 'viewer'   THEN 'customer_service'
  END;
  RAISE EXCEPTION 'LC_ROL_LEGACY_BLOQUEADO: el rol "%" está deprecado; usa "%" en su lugar', v_rol_texto, v_moderno
    USING ERRCODE = 'check_violation';
END;
$$;
CREATE FUNCTION public._bloquear_rol_plataforma_om() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.role::text = 'super_admin' THEN
    RAISE EXCEPTION 'LC_ROL_PLATAFORMA_NO_PERMITIDO: el rol super_admin no puede asignarse desde la membresía de una organización'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._calcular_demoras_montos_contenedor(p_cond_id uuid, p_org uuid, p_tipo_cont_id uuid, p_dias_excedidos integer, p_moneda_default text) RETURNS TABLE(monto_costo numeric, moneda_costo text, monto_venta numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  monto_costo := 0;
  monto_venta := 0;
  moneda_costo := COALESCE(p_moneda_default, 'USD');
  IF p_dias_excedidos <= 0 OR p_tipo_cont_id IS NULL THEN
    RETURN NEXT;
    RETURN;
  END IF;
  IF p_cond_id IS NOT NULL THEN
    SELECT
      COALESCE(SUM(
        CASE WHEN d >= t.desde_dia AND (t.hasta_dia IS NULL OR d <= t.hasta_dia) THEN t.monto_por_dia ELSE 0 END
      ),0),
      COALESCE(MAX(t.moneda), COALESCE(p_moneda_default,'USD'))
    INTO monto_costo, moneda_costo
    FROM generate_series(1, p_dias_excedidos) d
    LEFT JOIN LATERAL (
      SELECT monto_por_dia, moneda, desde_dia, hasta_dia
      FROM public.costeo_naviera_demoras_tarifa
      WHERE naviera_condicion_id = p_cond_id
        AND tipo_contenedor_id = p_tipo_cont_id
        AND d >= desde_dia
        AND (hasta_dia IS NULL OR d <= hasta_dia)
      ORDER BY desde_dia DESC LIMIT 1
    ) t ON true;
  END IF;
  SELECT COALESCE(SUM(
    CASE WHEN d >= t.desde_dia AND (t.hasta_dia IS NULL OR d <= t.hasta_dia) THEN t.monto_por_dia_usd ELSE 0 END
  ),0)
  INTO monto_venta
  FROM generate_series(1, p_dias_excedidos) d
  LEFT JOIN LATERAL (
    SELECT monto_por_dia_usd, desde_dia, hasta_dia
    FROM public.costeo_demoras_venta_tarifa
    WHERE organization_id = p_org
      AND tipo_contenedor_id = p_tipo_cont_id
      AND (vigente_desde IS NULL OR vigente_desde <= CURRENT_DATE)
      AND (vigente_hasta IS NULL OR vigente_hasta >= CURRENT_DATE)
      AND d >= desde_dia
      AND (hasta_dia IS NULL OR d <= hasta_dia)
    ORDER BY desde_dia DESC LIMIT 1
  ) t ON true;
  RETURN NEXT;
END;
$$;
CREATE FUNCTION public._cerrar_entrantes_por_uuid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.uuid_fiscal IS NULL
     OR NEW.deleted_at IS NOT NULL
     OR NEW.estado = 'Cancelada'::estado_proveedor_factura THEN
    RETURN NEW;
  END IF;
  UPDATE public.embarque_facturas_entrantes e
     SET estado = 'capturada',
         proveedor_factura_id = NEW.id,
         capturado_por = COALESCE(auth.uid(), NEW.created_by, e.capturado_por)
   WHERE e.estado = 'por_capturar'
     AND e.deleted_at IS NULL
     AND e.organization_id = NEW.organization_id
     AND e.uuid_fiscal IS NOT NULL
     AND upper(btrim(e.uuid_fiscal)) = upper(btrim(NEW.uuid_fiscal));
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._ci_ensure_proformas_es_consolidada() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT objid::regclass::text AS rel
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag = 'CREATE TABLE'
  LOOP
    IF r.rel = 'proformas' OR r.rel = 'public.proformas' THEN
      EXECUTE 'ALTER TABLE public.proformas
               ADD COLUMN IF NOT EXISTS es_consolidada boolean NOT NULL DEFAULT false';
      -- 13.56.11: drift adicional descubierto al correr suites RLS local.
      -- Migración 20260617052908 hace COALESCE(p.estado_aprobacion, '') sin
      -- que ninguna migración previa la cree (añadida manualmente en prod).
      EXECUTE 'ALTER TABLE public.proformas
               ADD COLUMN IF NOT EXISTS estado_aprobacion text NOT NULL DEFAULT ''Aprobada''';
    END IF;
  END LOOP;
END;
$$;
CREATE FUNCTION public._convertir_proformas_insertar_conceptos(p_factura_id uuid, p_proforma_ids uuid[], p_org uuid, p_es_consolidada boolean, p_moneda public.moneda) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_es_consolidada THEN
    INSERT INTO public.conceptos_factura (
      factura_id, descripcion, cantidad, precio_unitario, moneda, total, organization_id, clave_sat,
      tipo_iva, tasa_iva_aplicada, embarque_id, proforma_id_origen
    )
    SELECT p_factura_id, pcc.descripcion, pcc.cantidad, pcc.precio_unitario,
           pcc.moneda, pcc.total, p_org,
           COALESCE(public.resolver_clave_sat(p_org, pcc.descripcion), '78101800'),
           CASE
             WHEN pcc.tasa_iva_aplicada IS NULL AND pcc.aplica_iva = false THEN 'exento'
             WHEN COALESCE(pcc.tasa_iva_aplicada, 0.16) = 0 THEN 'tasa_0'
             ELSE 'gravado_16'
           END,
           CASE
             WHEN pcc.tasa_iva_aplicada IS NULL AND pcc.aplica_iva = false THEN NULL
             ELSE COALESCE(pcc.tasa_iva_aplicada, 0.16)
           END,
           p.embarque_id, pcc.proforma_id
    FROM public.proforma_conceptos_consolidados pcc
    JOIN public.proformas p ON p.id = pcc.proforma_id
    WHERE pcc.proforma_id = ANY(p_proforma_ids)
      AND pcc.moneda = p_moneda
      AND pcc.deleted_at IS NULL;
  ELSE
    INSERT INTO public.conceptos_factura (
      factura_id, descripcion, cantidad, precio_unitario, moneda, total, organization_id, clave_sat,
      tipo_iva, tasa_iva_aplicada, embarque_id, proforma_id_origen
    )
    SELECT p_factura_id, cv.descripcion, cv.cantidad, cv.precio_unitario,
           -- BUG-17: el total del renglón se guarda redondeado a 2 decimales,
           -- igual que en la rama consolidada (pcc.total ya viene redondeado).
           cv.moneda, ROUND(cv.cantidad * cv.precio_unitario, 2), p_org,
           COALESCE(public.resolver_clave_sat(p_org, cv.descripcion), '78101800'),
           CASE
             WHEN cv.tasa_iva_aplicada IS NULL AND cv.aplica_iva = false THEN 'exento'
             WHEN COALESCE(cv.tasa_iva_aplicada, 0.16) = 0 THEN 'tasa_0'
             ELSE 'gravado_16'
           END,
           CASE
             WHEN cv.tasa_iva_aplicada IS NULL AND cv.aplica_iva = false THEN NULL
             ELSE COALESCE(cv.tasa_iva_aplicada, 0.16)
           END,
           p.embarque_id, cv.proforma_id
    FROM public.conceptos_venta cv
    JOIN public.proformas p ON p.id = cv.proforma_id
    WHERE cv.proforma_id = ANY(p_proforma_ids)
      AND cv.moneda = p_moneda
      AND cv.deleted_at IS NULL;
  END IF;
END;
$$;
CREATE FUNCTION public._cotizaciones_bloquear_auto_aceptacion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF NEW.estado = 'Aceptada'::estado_cotizacion
     AND COALESCE(OLD.estado, 'Borrador'::estado_cotizacion) <> 'Aceptada'::estado_cotizacion
     AND v_uid IS NOT NULL
     AND NEW.created_by IS NOT NULL
     AND NEW.created_by = v_uid
     AND NOT (
       public.has_role(v_uid, 'admin'::app_role)
       OR public.has_role(v_uid, 'admin_org'::app_role)
       OR public.has_role(v_uid, 'super_admin'::app_role)
     )
  THEN
    RAISE EXCEPTION 'LC_SOD_VIOLATION: quien creó la cotización no puede aceptarla'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._cotizaciones_bloquear_envio_sin_importes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_usd numeric := 0;
  v_total_mxn numeric := 0;
BEGIN
  IF NEW.estado = 'Enviada'::estado_cotizacion
     AND COALESCE(OLD.estado, 'Borrador'::estado_cotizacion) <> 'Enviada'::estado_cotizacion
  THEN
    SELECT t.total_usd, t.total_mxn
      INTO v_total_usd, v_total_mxn
      FROM public.cotizacion_totales_conceptos(NEW.conceptos_venta) t;
    IF COALESCE(v_total_usd, 0) <= 0 AND COALESCE(v_total_mxn, 0) <= 0 THEN
      RAISE EXCEPTION 'LC_COTIZACION_SIN_IMPORTES: la cotización no tiene importes de venta capturados'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._cotizaciones_bloquear_envio_sin_oportunidad() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado IN ('Enviada'::estado_cotizacion, 'Solicitada'::estado_cotizacion)
     AND COALESCE(OLD.estado, 'Borrador'::estado_cotizacion) <> NEW.estado
     AND COALESCE(NEW.es_prospecto, false) = true
     AND NEW.oportunidad_id IS NULL
  THEN
    RAISE EXCEPTION 'LC_COT_SIN_OPORTUNIDAD: liga la cotización a una oportunidad del CRM antes de enviarla'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._cotizaciones_sync_vigencia() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_base date;
BEGIN
  -- Día de emisión en zona CDMX (estándar de fechas del proyecto): nunca
  -- `now()::date` en UTC, que después de las 18:00 locales adelanta un día.
  v_base := COALESCE(
    (NEW.created_at AT TIME ZONE 'America/Mexico_City')::date,
    (now() AT TIME ZONE 'America/Mexico_City')::date
  );
  IF NEW.validez_propuesta IS NOT NULL THEN
    -- Fuente única de verdad: la fecha capturada por el usuario.
    NEW.fecha_vigencia := NEW.validez_propuesta;
    NEW.vigencia_dias := GREATEST(1, (NEW.validez_propuesta - v_base))::int;
  ELSE
    NEW.vigencia_dias := COALESCE(NEW.vigencia_dias, 15);
    NEW.fecha_vigencia := COALESCE(NEW.fecha_vigencia, v_base + NEW.vigencia_dias);
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._cotizaciones_validar_prospecto() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.es_prospecto, false) THEN
    -- Prospecto: jamás ligado a un cliente y siempre con empresa capturada.
    IF NEW.cliente_id IS NOT NULL THEN
      RAISE EXCEPTION 'LC_COT_PROSPECTO_CON_CLIENTE: una cotización de prospecto no puede tener cliente ligado';
    END IF;
    IF NULLIF(btrim(COALESCE(NEW.prospecto_empresa, '')), '') IS NULL THEN
      RAISE EXCEPTION 'LC_COT_PROSPECTO_SIN_EMPRESA: captura la empresa del prospecto';
    END IF;
  ELSIF NEW.cliente_id IS NULL AND NEW.estado <> 'Borrador' THEN
    -- Cliente: fuera de borrador, la cotización exige cliente ligado.
    RAISE EXCEPTION 'LC_COT_CLIENTE_REQUERIDO: una cotización de cliente requiere cliente ligado';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._crear_embarque_replicar_conceptos(p_cotizacion_id uuid, p_embarque_id uuid, p_org uuid, p_target_ids uuid[], p_conceptos_venta jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_costo public.cotizacion_costos%ROWTYPE;
  v_cid   uuid;
  v_venta jsonb;
  v_cant  numeric;
  v_total numeric;
  v_pu    numeric;
  v_tasa  numeric;
  v_base  numeric;
  v_n     integer;
  v_parte numeric;
  v_acum  numeric;
  v_i     integer;
  v_prov_nombre text;
  v_prov_id uuid;
BEGIN
  -- Idempotencia: si el embarque ya tiene conceptos vivos, no re-sembrar.
  IF EXISTS (
    SELECT 1 FROM public.conceptos_costo
    WHERE embarque_id = p_embarque_id AND deleted_at IS NULL
  ) OR EXISTS (
    SELECT 1 FROM public.conceptos_venta
    WHERE embarque_id = p_embarque_id AND deleted_at IS NULL
  ) THEN
    RETURN;
  END IF;
  v_n := COALESCE(array_length(p_target_ids, 1), 0);
  FOR v_costo IN
    SELECT * FROM public.cotizacion_costos
    WHERE cotizacion_id = p_cotizacion_id AND deleted_at IS NULL
  LOOP
    v_base := ROUND(COALESCE(v_costo.costo_total, v_costo.costo_unitario * v_costo.cantidad, 0), 2);
    v_prov_nombre := COALESCE(btrim(v_costo.proveedor), '');
    v_prov_id := public._resolver_proveedor_por_nombre(p_org, v_prov_nombre);
    IF v_prov_id IS NULL AND v_prov_nombre <> '' THEN
      SELECT a.proveedor_id INTO v_prov_id
        FROM public.proveedor_alias a
       WHERE a.organization_id = p_org
         AND upper(btrim(a.alias_normalizado)) = upper(v_prov_nombre)
       LIMIT 1;
    END IF;
    IF COALESCE(v_costo.unidad_medida, 'Contenedor') = 'BL' OR v_n = 0 THEN
      INSERT INTO public.conceptos_costo (embarque_id, contenedor_id, concepto, monto, moneda, proveedor_nombre, proveedor_id, organization_id)
      VALUES (p_embarque_id, NULL, v_costo.concepto, v_base,
              CASE WHEN v_costo.moneda = 'USD' THEN 'USD'::moneda ELSE 'MXN'::moneda END,
              v_prov_nombre, v_prov_id, p_org);
    ELSE
      -- Prorrateo: el importe total se reparte entre contenedores; el ajuste
      -- de centavos se aplica al último para que la suma cuadre exacto.
      v_parte := ROUND(v_base / v_n::numeric, 2);
      v_acum  := 0;
      v_i     := 0;
      FOREACH v_cid IN ARRAY p_target_ids LOOP
        v_i := v_i + 1;
        IF v_i = v_n THEN
          v_parte := ROUND(v_base - v_acum, 2);
        END IF;
        v_acum := v_acum + v_parte;
        INSERT INTO public.conceptos_costo (embarque_id, contenedor_id, concepto, monto, moneda, proveedor_nombre, proveedor_id, organization_id)
        VALUES (p_embarque_id, v_cid, v_costo.concepto, v_parte,
                CASE WHEN v_costo.moneda = 'USD' THEN 'USD'::moneda ELSE 'MXN'::moneda END,
                v_prov_nombre, v_prov_id, p_org);
      END LOOP;
    END IF;
  END LOOP;
  IF jsonb_typeof(p_conceptos_venta) = 'array' THEN
    FOR v_venta IN SELECT * FROM jsonb_array_elements(p_conceptos_venta) LOOP
      IF COALESCE(trim(v_venta->>'descripcion'), '') <> '' THEN
        v_cant := COALESCE(NULLIF((v_venta->>'cantidad')::numeric, 0), 1);
        v_pu   := COALESCE((v_venta->>'precio_unitario')::numeric, 0);
        v_tasa := GREATEST(COALESCE((v_venta->>'tasa_iva_aplicada')::numeric, 0), 0);
        -- C-1: la base gravable se DERIVA del unitario capturado. Fallback sólo
        -- si no hay unitario: se desinfla el `total` (que viene con IVA).
        IF v_pu = 0 THEN
          v_total := ROUND(COALESCE((v_venta->>'total')::numeric, 0) / (1 + v_tasa), 2);
          v_pu    := ROUND(v_total / v_cant, 6);
        END IF;
        v_total := ROUND(v_cant * v_pu, 2);
        INSERT INTO public.conceptos_venta (
          embarque_id, descripcion, cantidad, precio_unitario, moneda,
          aplica_iva, tasa_iva_aplicada, total, organization_id
        )
        VALUES (
          p_embarque_id, v_venta->>'descripcion', v_cant, v_pu,
          CASE WHEN v_venta->>'moneda' = 'USD' THEN 'USD'::moneda ELSE 'MXN'::moneda END,
          COALESCE((v_venta->>'aplica_iva')::boolean, v_tasa > 0),
          v_tasa,
          v_total, p_org
        );
      END IF;
    END LOOP;
  END IF;
END;
$$;
CREATE FUNCTION public._crm_actividad_toca_oportunidad() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.entidad_tipo = 'oportunidad'::public.crm_entidad_tipo AND NEW.entidad_id IS NOT NULL THEN
    UPDATE public.crm_oportunidades
       SET ultimo_movimiento_at = now()
     WHERE id = NEW.entidad_id;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._crm_lead_avanzar_por_cotizacion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lead_id uuid;
  v_destino text;
BEGIN
  IF NEW.oportunidad_id IS NULL OR COALESCE(NEW.es_prospecto, false) = false THEN
    RETURN NEW;
  END IF;
  IF NEW.estado::text = 'Aceptada' THEN
    v_destino := 'Pendiente de alta';
  ELSIF NEW.estado::text IN ('Solicitada', 'Enviada') THEN
    v_destino := 'Prospecto';
  ELSE
    RETURN NEW;
  END IF;
  SELECT o.lead_id INTO v_lead_id
  FROM public.crm_oportunidades o
  WHERE o.id = NEW.oportunidad_id
    AND o.organization_id = NEW.organization_id;
  IF v_lead_id IS NULL THEN
    RETURN NEW;
  END IF;
  UPDATE public.crm_leads l
     SET estado = v_destino::public.crm_lead_estado,
         updated_at = now()
   WHERE l.id = v_lead_id
     AND l.organization_id = NEW.organization_id
     AND l.deleted_at IS NULL
     -- Rediseño CRM: no se promueven leads sin calificar; sólo prospectos.
     AND l.estado::text IN ('Prospecto', 'Pendiente de alta')
     AND l.estado::text <> v_destino
     AND NOT (v_destino = 'Prospecto' AND l.estado::text = 'Pendiente de alta');
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._crm_oportunidad_requiere_origen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lead_org uuid;
  v_lead_estado public.crm_lead_estado;
  v_cliente_org uuid;
BEGIN
  IF NEW.lead_id IS NULL AND NEW.cliente_id IS NULL THEN
    RAISE EXCEPTION 'LC_OPORTUNIDAD_SIN_ORIGEN';
  END IF;
  IF NEW.lead_id IS NOT NULL THEN
    SELECT organization_id, estado INTO v_lead_org, v_lead_estado
      FROM public.crm_leads
     WHERE id = NEW.lead_id AND deleted_at IS NULL;
    IF v_lead_org IS NULL OR v_lead_org IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'LC_CRM_LEAD_AJENO';
    END IF;
    IF v_lead_estado IN (
      'Nuevo'::public.crm_lead_estado,
      'Contactado'::public.crm_lead_estado,
      'Descalificado'::public.crm_lead_estado
    ) THEN
      RAISE EXCEPTION 'LC_OPORTUNIDAD_ORIGEN_NO_CALIFICADO';
    END IF;
  END IF;
  IF NEW.cliente_id IS NOT NULL THEN
    SELECT organization_id INTO v_cliente_org
      FROM public.clientes
     WHERE id = NEW.cliente_id AND deleted_at IS NULL;
    IF v_cliente_org IS NULL OR v_cliente_org IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'LC_CRM_CLIENTE_AJENO';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._crm_registrar_cambio_etapa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.ultimo_movimiento_at := now();
  IF NEW.etapa_id IS DISTINCT FROM OLD.etapa_id THEN
    INSERT INTO public.crm_historial_etapas (
      organization_id, oportunidad_id, etapa_origen_id, etapa_destino_id,
      dias_en_etapa, usuario_id, usuario_email
    ) VALUES (
      NEW.organization_id, NEW.id, OLD.etapa_id, NEW.etapa_id,
      ROUND(EXTRACT(EPOCH FROM (now() - COALESCE(OLD.etapa_desde_at, OLD.created_at, now()))) / 86400.0, 2),
      auth.uid(),
      NULLIF(current_setting('request.jwt.claims', true), '')::json ->> 'email'
    );
    NEW.etapa_desde_at := now();
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._crm_sync_oportunidad_desde_cotizacion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.oportunidad_id IS NULL THEN
    RETURN NEW;
  END IF;
  UPDATE public.crm_oportunidades o
     SET monto_estimado = COALESCE(NULLIF(NEW.subtotal, 0), o.monto_estimado),
         moneda         = COALESCE(NEW.moneda::text, o.moneda),
         cliente_id     = COALESCE(o.cliente_id, NEW.cliente_id),
         updated_at     = now()
   WHERE o.id = NEW.oportunidad_id
     AND (
       COALESCE(o.monto_estimado, 0) <> COALESCE(NULLIF(NEW.subtotal, 0), o.monto_estimado, 0)
       OR COALESCE(o.moneda, '') <> COALESCE(NEW.moneda::text, o.moneda, '')
       OR (o.cliente_id IS NULL AND NEW.cliente_id IS NOT NULL)
     );
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._crm_validar_motivo_perdida() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipo public.crm_etapa_tipo;
BEGIN
  IF NEW.etapa_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT tipo INTO v_tipo
    FROM public.crm_etapas_pipeline
   WHERE id = NEW.etapa_id;
  IF v_tipo = 'perdida' AND NEW.motivo_perdida_id IS NULL THEN
    RAISE EXCEPTION
      'LC_MOTIVO_PERDIDA_REQUERIDO: indica el motivo de pérdida para cerrar la oportunidad'
      USING ERRCODE = '22023';
  END IF;
  IF v_tipo IS DISTINCT FROM 'perdida' AND NEW.motivo_perdida_id IS NOT NULL THEN
    NEW.motivo_perdida_id := NULL;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._crm_vincular_cotizacion_core(p_cotizacion_id uuid, p_prospecto jsonb DEFAULT '{}'::jsonb, p_lead_id uuid DEFAULT NULL::uuid, p_oportunidad_id uuid DEFAULT NULL::uuid, p_actor_email text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_folio text;
  v_modo text;
  v_op_existente uuid;
  v_etapa_id uuid;
  v_etapa_prob integer;
  v_lead_id uuid := NULL;
  v_op_id uuid;
  v_empresa text;
  v_email text;
  v_empresa_norm text;
  v_creado_lead boolean := false;
BEGIN
  SELECT organization_id, folio, modo, oportunidad_id
    INTO v_org, v_folio, v_modo, v_op_existente
  FROM public.cotizaciones
  WHERE id = p_cotizacion_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_COTIZACION_NO_ENCONTRADA: la cotización no existe';
  END IF;
  IF v_op_existente IS NOT NULL THEN
    SELECT lead_id INTO v_lead_id FROM public.crm_oportunidades WHERE id = v_op_existente;
    RETURN jsonb_build_object(
      'oportunidad_id', v_op_existente, 'lead_id', v_lead_id,
      'creado_lead', false, 'creado_oportunidad', false, 'ya_ligada', true
    );
  END IF;
  v_empresa := NULLIF(btrim(COALESCE(p_prospecto->>'empresa', '')), '');
  v_email := NULLIF(lower(btrim(COALESCE(p_prospecto->>'email', ''))), '');
  IF p_oportunidad_id IS NOT NULL THEN
    SELECT id, lead_id INTO v_op_id, v_lead_id
    FROM public.crm_oportunidades
    WHERE id = p_oportunidad_id AND organization_id = v_org AND deleted_at IS NULL;
    IF v_op_id IS NULL THEN
      RAISE EXCEPTION 'LC_CRM_OPORTUNIDAD_AJENA: la oportunidad no pertenece a la organización';
    END IF;
    UPDATE public.cotizaciones
       SET oportunidad_id = v_op_id, updated_at = now()
     WHERE id = p_cotizacion_id;
    RETURN jsonb_build_object(
      'oportunidad_id', v_op_id, 'lead_id', v_lead_id,
      'creado_lead', false, 'creado_oportunidad', false, 'ya_ligada', false
    );
  END IF;
  SELECT id, probabilidad_default INTO v_etapa_id, v_etapa_prob
  FROM public.crm_etapas_pipeline
  WHERE organization_id = v_org AND activa = true AND tipo = 'abierta'::crm_etapa_tipo
  ORDER BY (nombre ILIKE '%cotiz%') DESC, orden ASC
  LIMIT 1;
  IF v_etapa_id IS NULL THEN
    RAISE EXCEPTION 'LC_CRM_SIN_ETAPA_ABIERTA: configura al menos una etapa abierta en el pipeline';
  END IF;
  IF p_lead_id IS NOT NULL THEN
    SELECT id INTO v_lead_id
    FROM public.crm_leads
    WHERE id = p_lead_id AND organization_id = v_org AND deleted_at IS NULL;
    IF v_lead_id IS NULL THEN
      RAISE EXCEPTION 'LC_CRM_LEAD_AJENO: el prospecto no pertenece a la organización';
    END IF;
  END IF;
  IF v_lead_id IS NULL AND v_email IS NOT NULL THEN
    SELECT id INTO v_lead_id
    FROM public.crm_leads
    WHERE organization_id = v_org AND deleted_at IS NULL
      AND lower(btrim(email)) = v_email
    ORDER BY created_at ASC
    LIMIT 1;
  END IF;
  IF v_lead_id IS NULL AND v_empresa IS NOT NULL THEN
    v_empresa_norm := upper(regexp_replace(btrim(v_empresa), '\s+', ' ', 'g'));
    SELECT id INTO v_lead_id
    FROM public.crm_leads
    WHERE organization_id = v_org AND deleted_at IS NULL
      AND upper(regexp_replace(btrim(empresa), '\s+', ' ', 'g')) = v_empresa_norm
    ORDER BY created_at ASC
    LIMIT 1;
  END IF;
  IF v_lead_id IS NULL THEN
    IF v_empresa IS NULL THEN
      RAISE EXCEPTION 'LC_CRM_PROSPECTO_SIN_EMPRESA: captura el nombre de la empresa del prospecto';
    END IF;
    INSERT INTO public.crm_leads (
      organization_id, empresa, contacto, email, telefono,
      rfc, direccion, ciudad, entidad_federativa, cp, pais, interes_modo
    ) VALUES (
      v_org, v_empresa,
      COALESCE(p_prospecto->>'contacto', ''),
      COALESCE(v_email, ''),
      COALESCE(p_prospecto->>'telefono', ''),
      COALESCE(p_prospecto->>'rfc', ''),
      COALESCE(p_prospecto->>'direccion', ''),
      COALESCE(p_prospecto->>'ciudad', ''),
      COALESCE(p_prospecto->>'entidad_federativa', ''),
      COALESCE(p_prospecto->>'cp', ''),
      COALESCE(p_prospecto->>'pais', ''),
      COALESCE(v_modo, '')
    )
    RETURNING id INTO v_lead_id;
    v_creado_lead := true;
  ELSE
    UPDATE public.crm_leads l
       SET rfc = CASE WHEN btrim(l.rfc) = '' THEN COALESCE(p_prospecto->>'rfc', '') ELSE l.rfc END,
           direccion = CASE WHEN btrim(l.direccion) = '' THEN COALESCE(p_prospecto->>'direccion', '') ELSE l.direccion END,
           cp = CASE WHEN btrim(l.cp) = '' THEN COALESCE(p_prospecto->>'cp', '') ELSE l.cp END,
           ciudad = CASE WHEN btrim(l.ciudad) = '' THEN COALESCE(p_prospecto->>'ciudad', '') ELSE l.ciudad END,
           entidad_federativa = CASE WHEN btrim(l.entidad_federativa) = '' THEN COALESCE(p_prospecto->>'entidad_federativa', '') ELSE l.entidad_federativa END,
           telefono = CASE WHEN btrim(l.telefono) = '' THEN COALESCE(p_prospecto->>'telefono', '') ELSE l.telefono END,
           email = CASE WHEN btrim(l.email) = '' THEN COALESCE(v_email, '') ELSE l.email END,
           updated_at = now()
     WHERE l.id = v_lead_id;
  END IF;
  INSERT INTO public.crm_oportunidades (
    organization_id, nombre, cliente_nombre, lead_id, etapa_id, probabilidad, modo,
    vendedor_id, vendedor_email
  ) VALUES (
    v_org,
    CASE WHEN v_folio IS NOT NULL AND btrim(v_folio) <> ''
         THEN COALESCE(v_empresa, 'Prospecto') || ' — ' || v_folio
         ELSE 'Cotización · ' || COALESCE(v_empresa, 'Prospecto') END,
    COALESCE(v_empresa, ''),
    v_lead_id,
    v_etapa_id,
    COALESCE(v_etapa_prob, 30),
    COALESCE(v_modo, ''),
    p_actor_id,
    COALESCE(p_actor_email, '')
  )
  RETURNING id INTO v_op_id;
  UPDATE public.cotizaciones
     SET oportunidad_id = v_op_id, updated_at = now()
   WHERE id = p_cotizacion_id;
  RETURN jsonb_build_object(
    'oportunidad_id', v_op_id, 'lead_id', v_lead_id,
    'creado_lead', v_creado_lead, 'creado_oportunidad', true, 'ya_ligada', false
  );
END;
$$;
CREATE FUNCTION public._cxp_anchor_fase_o() RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  p_aprobar boolean := false;
  p_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
BEGIN
  IF p_aprobar THEN
    PERFORM public._cxp_validar_aprobacion(p_id);
  END IF;
END;
$$;
CREATE FUNCTION public._cxp_desvincular_por_rechazo(p_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.proveedor_facturas;
  v_pagado numeric;
  v_vinculos int := 0;
  v_ajustes int := 0;
  v_entrantes int := 0;
BEGIN
  SELECT * INTO v_row FROM public.proveedor_facturas WHERE id = p_id FOR UPDATE;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Factura no encontrada' USING ERRCODE = 'P0002';
  END IF;
  SELECT COALESCE(SUM(monto), 0) INTO v_pagado
  FROM public.pagos_proveedor
  WHERE proveedor_factura_id = p_id AND deleted_at IS NULL;
  IF v_pagado > 0 OR v_row.estado = 'Pagada'::public.estado_proveedor_factura THEN
    RAISE EXCEPTION 'LC_CXP_RECHAZO_CON_PAGOS: la factura tiene pagos aplicados; anúlalos antes de rechazarla.'
      USING ERRCODE = '22023';
  END IF;
  -- Cancelar la factura: dispara la reversión de conceptos de ajuste
  -- (tg_reverse_ajustes_factura_proveedor) dentro de la misma transacción.
  IF v_row.estado <> 'Cancelada'::public.estado_proveedor_factura THEN
    PERFORM set_config('app.cancelando_cxp', '1', true);
    UPDATE public.proveedor_facturas
       SET estado = 'Cancelada'::public.estado_proveedor_factura,
           fecha_cancelacion = now(),
           motivo_cancelacion = COALESCE(NULLIF(btrim(p_motivo), ''), 'Factura rechazada'),
           cancelada_por = auth.uid(),
           updated_at = now()
     WHERE id = p_id;
    PERFORM set_config('app.cancelando_cxp', '0', true);
  END IF;
  SELECT count(*) INTO v_ajustes
  FROM public.conceptos_costo cc
  JOIN public.proveedor_facturas_conceptos pfc ON pfc.concepto_costo_id = cc.id
  WHERE pfc.proveedor_factura_id = p_id
    AND cc.origen = 'ajuste_factura_proveedor'
    AND cc.deleted_at IS NOT NULL;
  -- Romper el vínculo con los conceptos de costo: vuelven a "pendiente de factura".
  DELETE FROM public.proveedor_facturas_conceptos WHERE proveedor_factura_id = p_id;
  GET DIAGNOSTICS v_vinculos = ROW_COUNT;
  -- Soltar el embarque.
  UPDATE public.proveedor_facturas SET embarque_id = NULL, updated_at = now() WHERE id = p_id;
  -- Ola 6 · RG5-3: el archivo entrante queda rechazado Y SIN VÍNCULO a la
  -- factura cancelada, para que pueda retirarse o reactivarse después.
  UPDATE public.embarque_facturas_entrantes
     SET estado = 'rechazada',
         rechazo_motivo = COALESCE(NULLIF(btrim(p_motivo), ''), 'Factura rechazada'),
         proveedor_factura_id = NULL,
         capturado_por = NULL,
         updated_at = now()
   WHERE proveedor_factura_id = p_id
     AND deleted_at IS NULL;
  GET DIAGNOSTICS v_entrantes = ROW_COUNT;
  RETURN jsonb_build_object(
    'vinculos_eliminados', v_vinculos,
    'ajustes_revertidos', v_ajustes,
    'entrantes_rechazados', v_entrantes,
    'embarque_liberado', v_row.embarque_id
  );
END;
$$;
CREATE FUNCTION public._cxp_validar_aprobacion(p_factura_id uuid, p_justificacion text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.proveedor_facturas;
  v_conceptos_count integer;
  v_suma_conceptos numeric(18,4);
  v_suma_cantidades numeric(18,4);
  v_tolerancia numeric(18,4);
  v_diferencia numeric(18,4);
  v_emb_estado text;
  v_emb_org uuid;
  v_origen text;
  v_tiene_xml_lineas boolean;
  v_total_mxn numeric(18,4);
  v_umbral numeric;
  v_c record;
BEGIN
  SELECT * INTO v_row FROM public.proveedor_facturas WHERE id = p_factura_id;
  IF v_row.id IS NULL OR v_row.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'LC_CXP_NO_EXISTE: La factura no existe.';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.proveedor_facturas_conceptos
    WHERE proveedor_factura_id = p_factura_id AND concepto_costo_id IS NULL
  ) INTO v_tiene_xml_lineas;
  IF v_tiene_xml_lineas THEN
    SELECT COUNT(*),
           COALESCE(SUM(monto * COALESCE(NULLIF(cantidad,0),1)),0),
           COALESCE(SUM(COALESCE(NULLIF(cantidad,0),1)),0)
      INTO v_conceptos_count, v_suma_conceptos, v_suma_cantidades
      FROM public.proveedor_facturas_conceptos
      WHERE proveedor_factura_id = p_factura_id
        AND concepto_costo_id IS NULL;
  ELSE
    SELECT COUNT(*),
           COALESCE(SUM(monto * COALESCE(NULLIF(cantidad,0),1)),0),
           COALESCE(SUM(COALESCE(NULLIF(cantidad,0),1)),0)
      INTO v_conceptos_count, v_suma_conceptos, v_suma_cantidades
      FROM public.proveedor_facturas_conceptos
      WHERE proveedor_factura_id = p_factura_id;
  END IF;
  IF v_conceptos_count = 0 THEN
    RAISE EXCEPTION 'LC_CXP_SIN_CONCEPTOS: Captura los conceptos de la factura antes de aprobar.';
  END IF;
  v_tolerancia := GREATEST(0.01, 0.005 * COALESCE(v_suma_cantidades,0));
  v_diferencia := ABS(COALESCE(v_row.subtotal,0) - v_suma_conceptos);
  IF v_diferencia > v_tolerancia THEN
    RAISE EXCEPTION 'LC_CXP_DESCUADRE: Los conceptos (%) no cuadran con el subtotal (%) de la factura. Diferencia: % (tolerancia: %)',
      to_char(v_suma_conceptos,          'FM999,999,999,990.00'),
      to_char(COALESCE(v_row.subtotal,0),'FM999,999,999,990.00'),
      to_char(v_diferencia,              'FM999,999,999,990.00'),
      to_char(v_tolerancia,              'FM999,999,999,990.00');
  END IF;
  -- Tope de sobrecosto POR CONCEPTO, sumando todas las facturas vivas ligadas
  -- a ese concepto y normalizando ambos lados a MXN.
  FOR v_c IN
    SELECT cc.id,
           cc.concepto,
           public.a_mxn_doc(cc.monto, cc.moneda::text, v_row.fecha_emision,
                            NULL, emb.tipo_cambio_usd) AS comprometido_mxn,
           (
             SELECT COALESCE(SUM(
                      public.a_mxn_doc(p2.monto * COALESCE(NULLIF(p2.cantidad,0),1),
                                       pf2.moneda::text, pf2.fecha_emision,
                                       pf2.tipo_cambio_usd, emb.tipo_cambio_usd)
                    ), 0)
               FROM public.proveedor_facturas_conceptos p2
               JOIN public.proveedor_facturas pf2 ON pf2.id = p2.proveedor_factura_id
              WHERE p2.concepto_costo_id = cc.id
                AND pf2.deleted_at IS NULL
                AND pf2.estado <> 'Cancelada'::public.estado_proveedor_factura
                AND COALESCE(pf2.estado_aprobacion::text, 'pendiente') <> 'rechazada'
           ) AS facturado_mxn
      FROM public.proveedor_facturas_conceptos pfc
      JOIN public.conceptos_costo cc
        ON cc.id = pfc.concepto_costo_id AND cc.deleted_at IS NULL
      LEFT JOIN public.embarques emb ON emb.id = cc.embarque_id
     WHERE pfc.proveedor_factura_id = p_factura_id
       AND pfc.concepto_costo_id IS NOT NULL
     GROUP BY cc.id, cc.concepto, cc.monto, cc.moneda, emb.tipo_cambio_usd
  LOOP
    IF v_c.comprometido_mxn IS NULL THEN
      RAISE WARNING 'LC_CXP_SIN_TC: el concepto "%" no tiene tipo de cambio para comparar; se omite el control de sobrecosto.', v_c.concepto;
      CONTINUE;
    END IF;
    IF v_c.facturado_mxn - v_c.comprometido_mxn > 0.02
       AND v_c.comprometido_mxn > 0
       AND (v_c.facturado_mxn - v_c.comprometido_mxn) > v_c.comprometido_mxn * 0.05 THEN
      RAISE EXCEPTION 'LC_CXP_SOBRECOSTO: el concepto "%" ya tiene facturado % MXN contra % MXN comprometidos (incluyendo otras facturas del mismo costo). Revisa la vinculación antes de aprobar.',
        v_c.concepto,
        to_char(v_c.facturado_mxn,    'FM999,999,999,990.00'),
        to_char(v_c.comprometido_mxn, 'FM999,999,999,990.00');
    ELSIF v_c.facturado_mxn - v_c.comprometido_mxn > 0.02 THEN
      RAISE WARNING 'LC_CXP_SOBRECOSTO: el concepto "%" excede lo comprometido en % MXN (<= 5%%, se aprueba con advertencia).',
        v_c.concepto,
        to_char(v_c.facturado_mxn - v_c.comprometido_mxn, 'FM999,999,999,990.00');
    END IF;
  END LOOP;
  IF v_row.embarque_id IS NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.proveedor_facturas_conceptos
        WHERE proveedor_factura_id = p_factura_id
          AND concepto_costo_id IS NOT NULL
     )
  THEN
    -- Ola E1 · N-F3: antes `COALESCE(NULLIF(tipo_cambio_usd,0), 1)` valuaba una
    -- factura en USD como si fuera MXN y saltaba el umbral sin justificación.
    IF v_row.moneda = 'MXN'::public.moneda THEN
      v_total_mxn := COALESCE(v_row.total,0);
    ELSE
      IF COALESCE(NULLIF(v_row.tipo_cambio_usd,0), 0) <= 0 THEN
        RAISE EXCEPTION 'LC_CXP_TC_REQUERIDO: la factura está en % y no tiene tipo de cambio capturado; registra el T/C del DOF de la fecha de la factura antes de aprobar.',
          v_row.moneda;
      END IF;
      v_total_mxn := COALESCE(v_row.total,0) * v_row.tipo_cambio_usd;
    END IF;
    v_umbral := public.cxp_umbral_sin_vinculo(v_row.organization_id);
    IF v_total_mxn > v_umbral THEN
      RAISE EXCEPTION 'LC_CXP_SIN_RESPALDO_MONTO: La factura por % MXN no está ligada a un embarque ni a costos acordados y excede el umbral autorizado (%). Vincúlala al embarque o a sus conceptos de costo antes de aprobar.',
        to_char(v_total_mxn, 'FM999,999,999,990.00'),
        to_char(v_umbral,    'FM999,999,999,990.00');
    END IF;
    IF length(COALESCE(btrim(p_justificacion), '')) < 10 THEN
      RAISE EXCEPTION 'LC_CXP_SIN_RESPALDO: Esta factura no está ligada a un embarque ni a costos acordados. Escribe la justificación del gasto (mínimo 10 caracteres) para aprobarla.';
    END IF;
  END IF;
  IF v_row.embarque_id IS NOT NULL THEN
    SELECT estado, organization_id INTO v_emb_estado, v_emb_org
      FROM public.embarques WHERE id = v_row.embarque_id;
    IF v_emb_estado IS NULL THEN
      RAISE EXCEPTION 'LC_CXP_EMBARQUE_NO_EXISTE: El embarque asociado no existe.';
    END IF;
    IF v_emb_estado = 'Cancelado' THEN
      RAISE EXCEPTION 'LC_CXP_EMBARQUE_CANCELADO: El embarque asociado está cancelado.';
    END IF;
    IF v_emb_org IS DISTINCT FROM v_row.organization_id THEN
      RAISE EXCEPTION 'LC_CXP_EMBARQUE_ORG_MISMATCH: El embarque pertenece a otra organización.';
    END IF;
  END IF;
  SELECT origen_proveedor::text INTO v_origen
    FROM public.proveedores WHERE id = v_row.proveedor_id;
  IF COALESCE(v_origen,'Nacional') = 'Nacional'
     AND v_row.uuid_fiscal IS NOT NULL
     AND COALESCE(v_row.uuid_verificado,false) = false THEN
    RAISE EXCEPTION 'LC_CXP_UUID_NO_VERIFICADO: Verifica el UUID en el SAT antes de aprobar.';
  END IF;
END;
$$;
CREATE FUNCTION public._dashboard_details_calc() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hoy date := current_date;
  v_inicio_mes date := date_trunc('month', v_hoy)::date;
  v_fin_mes date := (date_trunc('month', v_hoy) + interval '1 month' - interval '1 day')::date;
  v_inicio_sig date := (date_trunc('month', v_hoy) + interval '1 month')::date;
  v_fin_sig date := (date_trunc('month', v_hoy) + interval '2 months' - interval '1 day')::date;
  v_dias_libres int := 7;
  v_nombre_mes text;
  v_meses text[] := ARRAY['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
BEGIN
  v_nombre_mes := v_meses[extract(month from v_inicio_sig)::int] || ' ' || extract(year from v_inicio_sig)::text;
  RETURN (
    WITH embarques_base AS (
      SELECT e.id, e.expediente, e.cliente_nombre, e.cliente_id, e.modo::text, e.tipo::text,
             e.estado::text, e.etd, e.eta, e.operador,
             e.puerto_origen, e.puerto_destino,
             e.aeropuerto_origen, e.aeropuerto_destino,
             e.ciudad_origen, e.ciudad_destino, e.contenedor, e.created_at,
             e.tipo_cambio_usd, e.tipo_cambio_eur,
        CASE
          -- Ola 4 · N10 (guard B-033): preservar Borrador.
          WHEN e.estado = 'Borrador' THEN 'Borrador'
          WHEN e.estado IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado') THEN e.estado::text
          WHEN e.modo = 'Marítimo' AND e.tipo = 'Importación' AND e.etd IS NOT NULL AND e.eta IS NOT NULL THEN
            CASE
              WHEN v_hoy < e.etd THEN 'Confirmado'
              WHEN v_hoy >= e.etd AND v_hoy < e.eta THEN 'En Tránsito'
              WHEN v_hoy >= e.eta THEN 'Arribo'
              ELSE e.estado::text
            END
          ELSE e.estado::text
        END AS estado_real
      FROM embarques e
      WHERE e.deleted_at IS NULL              -- FIX C5
        AND (e.organization_id = public.org_scope())
    ),
    profit AS (SELECT * FROM profit_por_embarque()),
    -- Ola 4 · N10 (B-033): Borrador ya no cuenta como activo operativo.
    activos AS (SELECT * FROM embarques_base WHERE estado_real NOT IN ('Borrador','EIR','Por liquidar','Cerrado','Cancelado')),
    alertas_src AS (
      SELECT a.* FROM activos a
      WHERE a.estado_real = 'Arribo' AND a.eta IS NOT NULL AND (v_hoy - a.eta) >= v_dias_libres
      ORDER BY (v_hoy - a.eta) DESC LIMIT 15
    ),
    alertas AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'expediente', a.expediente, 'cliente_nombre', a.cliente_nombre,
        'modo', a.modo, 'tipo', a.tipo, 'estado', a.estado, 'estadoReal', a.estado_real,
        'etd', a.etd, 'eta', a.eta, 'operador', a.operador,
        'puerto_origen', a.puerto_origen, 'puerto_destino', a.puerto_destino,
        'aeropuerto_origen', a.aeropuerto_origen, 'aeropuerto_destino', a.aeropuerto_destino,
        'ciudad_origen', a.ciudad_origen, 'ciudad_destino', a.ciudad_destino,
        'contenedor', a.contenedor, 'created_at', a.created_at,
        'diasDesdeEta', (v_hoy - a.eta),
        'diasDemora', (v_hoy - a.eta) - v_dias_libres
      )) AS val FROM alertas_src a
    ),
    proximos_src AS (
      SELECT a.* FROM activos a
      WHERE a.estado_real = 'En Tránsito' AND a.eta IS NOT NULL
        AND (a.eta - v_hoy) >= 0 AND (a.eta - v_hoy) <= 7
      ORDER BY (a.eta - v_hoy) ASC LIMIT 15
    ),
    proximos AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'expediente', a.expediente, 'cliente_nombre', a.cliente_nombre,
        'modo', a.modo, 'tipo', a.tipo, 'estado', a.estado, 'estadoReal', a.estado_real,
        'etd', a.etd, 'eta', a.eta, 'operador', a.operador,
        'puerto_origen', a.puerto_origen, 'puerto_destino', a.puerto_destino,
        'aeropuerto_origen', a.aeropuerto_origen, 'aeropuerto_destino', a.aeropuerto_destino,
        'ciudad_origen', a.ciudad_origen, 'ciudad_destino', a.ciudad_destino,
        'contenedor', a.contenedor, 'created_at', a.created_at,
        'diasRestantes', (a.eta - v_hoy)
      )) AS val FROM proximos_src a
    ),
    profit_este_mes_src AS (
      SELECT eb.*, p.venta_usd, p.costo_usd, p.venta_mxn, p.costo_mxn,
             p.venta_mxn_from_usd, p.costo_mxn_from_usd,
             p.venta_mxn_from_eur, p.costo_mxn_from_eur,
             p.venta_mxn_native, p.costo_mxn_native
      FROM activos eb LEFT JOIN profit p ON p.embarque_id = eb.id
      WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_mes AND eb.eta <= v_fin_mes
        AND (COALESCE(p.venta_mxn, 0) > 0 OR COALESCE(p.costo_mxn, 0) > 0)
      ORDER BY (COALESCE(p.venta_mxn, 0) - COALESCE(p.costo_mxn, 0)) DESC LIMIT 30
    ),
    profit_este_mes AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', eb.id, 'expediente', eb.expediente, 'cliente_nombre', eb.cliente_nombre,
        'modo', eb.modo, 'tipo', eb.tipo, 'estado', eb.estado, 'estadoReal', eb.estado_real,
        'etd', eb.etd, 'eta', eb.eta, 'operador', eb.operador,
        'puerto_origen', eb.puerto_origen, 'puerto_destino', eb.puerto_destino,
        'aeropuerto_origen', eb.aeropuerto_origen, 'aeropuerto_destino', eb.aeropuerto_destino,
        'ciudad_origen', eb.ciudad_origen, 'ciudad_destino', eb.ciudad_destino,
        'contenedor', eb.contenedor, 'created_at', eb.created_at,
        'tipoCambioUSD', eb.tipo_cambio_usd, 'tipoCambioEUR', eb.tipo_cambio_eur,
        'ventaUSD', COALESCE(eb.venta_usd, 0),
        'costoUSD', COALESCE(eb.costo_usd, 0),
        'ventaMXN', COALESCE(eb.venta_mxn, 0),
        'costoMXN', COALESCE(eb.costo_mxn, 0),
        'profitMXN', COALESCE(eb.venta_mxn, 0) - COALESCE(eb.costo_mxn, 0),
        'margenMXN', CASE WHEN COALESCE(eb.venta_mxn, 0) > 0
                          THEN ((COALESCE(eb.venta_mxn, 0) - COALESCE(eb.costo_mxn, 0)) / eb.venta_mxn) * 100
                          ELSE 0 END,
        'ventaMxnFromUsd', COALESCE(eb.venta_mxn_from_usd, 0),
        'costoMxnFromUsd', COALESCE(eb.costo_mxn_from_usd, 0),
        'ventaMxnFromEur', COALESCE(eb.venta_mxn_from_eur, 0),
        'costoMxnFromEur', COALESCE(eb.costo_mxn_from_eur, 0),
        'ventaMxnNative', COALESCE(eb.venta_mxn_native, 0),
        'costoMxnNative', COALESCE(eb.costo_mxn_native, 0),
        'profit', COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0),
        'margen', CASE WHEN COALESCE(eb.venta_usd, 0) > 0
                       THEN ((COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0)) / eb.venta_usd) * 100
                       ELSE 0 END
      )) AS val FROM profit_este_mes_src eb
    ),
    mes_sig_src AS (
      SELECT eb.*, p.venta_usd, p.costo_usd, p.venta_mxn, p.costo_mxn,
             p.venta_mxn_from_usd, p.costo_mxn_from_usd,
             p.venta_mxn_from_eur, p.costo_mxn_from_eur,
             p.venta_mxn_native, p.costo_mxn_native,
             EXISTS (
               SELECT 1 FROM facturas f
               WHERE f.embarque_id = eb.id
                 AND f.deleted_at IS NULL     -- FIX C5
                 -- Ola 5 · RG4-2 (N45): 'Sustituida' ya no es CFDI vigente;
                 -- excluirla del flag "facturado" (la definición vigente
                 -- sólo excluía Cancelada/Borrador).
                 AND f.estado::text NOT IN ('Cancelada','Borrador','Sustituida')
             ) AS facturado_flag
      FROM activos eb LEFT JOIN profit p ON p.embarque_id = eb.id
      WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_sig AND eb.eta <= v_fin_sig
      ORDER BY eb.eta ASC LIMIT 30
    ),
    mes_sig AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', eb.id, 'expediente', eb.expediente, 'cliente_nombre', eb.cliente_nombre,
        'modo', eb.modo, 'tipo', eb.tipo, 'estado', eb.estado, 'estadoReal', eb.estado_real,
        'etd', eb.etd, 'eta', eb.eta, 'operador', eb.operador,
        'puerto_origen', eb.puerto_origen, 'puerto_destino', eb.puerto_destino,
        'aeropuerto_origen', eb.aeropuerto_origen, 'aeropuerto_destino', eb.aeropuerto_destino,
        'ciudad_origen', eb.ciudad_origen, 'ciudad_destino', eb.ciudad_destino,
        'contenedor', eb.contenedor, 'created_at', eb.created_at,
        'tipoCambioUSD', eb.tipo_cambio_usd, 'tipoCambioEUR', eb.tipo_cambio_eur,
        'ventaUSD', COALESCE(eb.venta_usd, 0),
        'costoUSD', COALESCE(eb.costo_usd, 0),
        'ventaMXN', COALESCE(eb.venta_mxn, 0),
        'costoMXN', COALESCE(eb.costo_mxn, 0),
        'profitMXN', COALESCE(eb.venta_mxn, 0) - COALESCE(eb.costo_mxn, 0),
        'margenMXN', CASE WHEN COALESCE(eb.venta_mxn, 0) > 0
                          THEN ((COALESCE(eb.venta_mxn, 0) - COALESCE(eb.costo_mxn, 0)) / eb.venta_mxn) * 100
                          ELSE 0 END,
        'ventaMxnFromUsd', COALESCE(eb.venta_mxn_from_usd, 0),
        'costoMxnFromUsd', COALESCE(eb.costo_mxn_from_usd, 0),
        'ventaMxnFromEur', COALESCE(eb.venta_mxn_from_eur, 0),
        'costoMxnFromEur', COALESCE(eb.costo_mxn_from_eur, 0),
        'ventaMxnNative', COALESCE(eb.venta_mxn_native, 0),
        'costoMxnNative', COALESCE(eb.costo_mxn_native, 0),
        'profit', COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0),
        'margen', CASE WHEN COALESCE(eb.venta_usd, 0) > 0
                       THEN ((COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0)) / eb.venta_usd) * 100
                       ELSE 0 END,
        'facturado', eb.facturado_flag
      )) AS val FROM mes_sig_src eb
    ),
    mes_sig_resumen AS (
      SELECT jsonb_build_object(
        'totalEmbarques', count(*),
        'ventaUSD', COALESCE(sum(COALESCE(venta_usd, 0)), 0),
        'costoUSD', COALESCE(sum(COALESCE(costo_usd, 0)), 0),
        'profitUSD', COALESCE(sum(COALESCE(venta_usd, 0) - COALESCE(costo_usd, 0)), 0),
        'ventaMXN', COALESCE(sum(COALESCE(venta_mxn, 0)), 0),
        'costoMXN', COALESCE(sum(COALESCE(costo_mxn, 0)), 0),
        'profitMXN', COALESCE(sum(COALESCE(venta_mxn, 0) - COALESCE(costo_mxn, 0)), 0),
        'facturados', count(*) FILTER (WHERE facturado_flag),
        'nombreMes', v_nombre_mes
      ) AS val FROM mes_sig_src
    ),
    cargas_cliente AS (
      SELECT jsonb_agg(x ORDER BY (x->>'total')::int DESC) AS val
      FROM (
        SELECT jsonb_build_object(
          'clienteId', cliente_id,
          'clienteNombre', cliente_nombre,
          'total', count(*),
          'desglose', jsonb_build_object(
            'Confirmado',   count(*) FILTER (WHERE estado_real = 'Confirmado'),
            'En Tránsito',  count(*) FILTER (WHERE estado_real = 'En Tránsito'),
            'Arribo',       count(*) FILTER (WHERE estado_real = 'Arribo'),
            'En Aduana',    count(*) FILTER (WHERE estado_real = 'En Aduana'),
            'Entregado',    count(*) FILTER (WHERE estado_real = 'Entregado')
          )
        ) AS x
        FROM activos WHERE cliente_id IS NOT NULL
        GROUP BY cliente_id, cliente_nombre
        ORDER BY count(*) DESC LIMIT 10
      ) sub
    ),
    cargas_total AS (
      SELECT count(*) FILTER (
        WHERE cliente_id IS NOT NULL
          AND estado_real IN ('Confirmado','En Tránsito','Arribo','En Aduana','Entregado')
      )::int AS val
      FROM activos
    ),
    -- v13.303.13 · Listado ligero de EIR para el scope "mis embarques" del chip EIR.
    embarques_eir AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', eb.id,
        'operador', eb.operador,
        'estadoReal', eb.estado_real
      )) AS val
      FROM (
        SELECT id, operador, estado_real, created_at
        FROM embarques_base
        WHERE estado_real IN ('EIR','Por liquidar')
        ORDER BY created_at DESC
        LIMIT 500
      ) eb
    )
    SELECT jsonb_build_object(
      'alertasDemora', COALESCE((SELECT val FROM alertas), '[]'::jsonb),
      'proximosArribos', COALESCE((SELECT val FROM proximos), '[]'::jsonb),
      'profitArribosEsteMes', COALESCE((SELECT val FROM profit_este_mes), '[]'::jsonb),
      'embarquesMesSiguiente', COALESCE((SELECT val FROM mes_sig), '[]'::jsonb),
      'resumenMesSiguiente', COALESCE((SELECT val FROM mes_sig_resumen), jsonb_build_object(
        'totalEmbarques', 0, 'ventaUSD', 0, 'costoUSD', 0, 'profitUSD', 0,
        'ventaMXN', 0, 'costoMXN', 0, 'profitMXN', 0,
        'facturados', 0, 'nombreMes', v_nombre_mes
      )),
      'cargasPorCliente', COALESCE((SELECT val FROM cargas_cliente), '[]'::jsonb),
      'cargasActivasTotal', COALESCE((SELECT val FROM cargas_total), 0),
      'embarquesEir', COALESCE((SELECT val FROM embarques_eir), '[]'::jsonb)
    )
  );
END;
$$;
CREATE FUNCTION public._dashboard_summary_calc() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hoy date := current_date;
  v_inicio_mes date := date_trunc('month', v_hoy)::date;
  v_fin_mes date := (date_trunc('month', v_hoy) + interval '1 month' - interval '1 day')::date;
  v_inicio_sig date := (date_trunc('month', v_hoy) + interval '1 month')::date;
  v_fin_sig date := (date_trunc('month', v_hoy) + interval '2 months' - interval '1 day')::date;
BEGIN
  RETURN (
    WITH embarques_base AS (
      SELECT e.id, e.estado::text, e.modo, e.tipo, e.etd, e.eta,
        e.tipo_cambio_eur,
        CASE
          WHEN e.estado = 'Borrador' THEN 'Borrador'
          WHEN e.estado IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado') THEN e.estado::text
          WHEN e.modo = 'Marítimo' AND e.tipo = 'Importación' AND e.etd IS NOT NULL AND e.eta IS NOT NULL THEN
            CASE
              WHEN v_hoy < e.etd THEN 'Confirmado'
              WHEN v_hoy >= e.etd AND v_hoy < e.eta THEN 'En Tránsito'
              WHEN v_hoy >= e.eta THEN 'Arribo'
              ELSE e.estado::text
            END
          ELSE e.estado::text
        END AS estado_real
      FROM embarques e
      WHERE e.deleted_at IS NULL
        AND (e.organization_id = public.org_scope())
    ),
    profit AS (SELECT * FROM profit_por_embarque()),
    activos AS (SELECT * FROM embarques_base WHERE estado_real NOT IN ('Borrador','EIR','Por liquidar','Cerrado','Cancelado')),
    conteo AS (
      SELECT jsonb_build_object(
        'Confirmado', count(*) FILTER (WHERE estado_real = 'Confirmado'),
        'En Tránsito', count(*) FILTER (WHERE estado_real = 'En Tránsito'),
        'Arribo', count(*) FILTER (WHERE estado_real = 'Arribo'),
        'En Aduana', count(*) FILTER (WHERE estado_real = 'En Aduana'),
        'Entregado', count(*) FILTER (WHERE estado_real = 'Entregado'),
        'EIR', count(*) FILTER (WHERE estado_real = 'EIR'),
        'Por liquidar', count(*) FILTER (WHERE estado_real = 'Por liquidar')
      ) AS val
      FROM embarques_base
    ),
    gastos_op_facturas AS (
      -- FIX BL-11: EUR usa el TC del embarque ligado y, si no hay, el TC DOF
      -- vigente a fecha_emision (LEFT JOIN LATERAL sobre tipos_cambio_dof).
      SELECT COALESCE(SUM(
        CASE
          WHEN pf.moneda = 'MXN' THEN pf.total
          WHEN pf.moneda = 'USD' AND pf.tipo_cambio_usd > 1 THEN pf.total * pf.tipo_cambio_usd
          WHEN pf.moneda = 'EUR' AND COALESCE(eb.tipo_cambio_eur, dof.eur_mxn) > 1
               THEN pf.total * COALESCE(eb.tipo_cambio_eur, dof.eur_mxn)
          ELSE NULL
        END
      ), 0) AS val
      FROM proveedor_facturas pf
      JOIN presupuesto_categorias pc ON pc.id = pf.categoria_presupuesto_id
      LEFT JOIN embarques_base eb ON eb.id = pf.embarque_id
      LEFT JOIN LATERAL (
        SELECT d.eur_mxn
          FROM public.tipos_cambio_dof d
         WHERE d.fecha <= pf.fecha_emision
         ORDER BY d.fecha DESC
         LIMIT 1
      ) dof ON pf.moneda = 'EUR' AND eb.tipo_cambio_eur IS NULL
      WHERE pc.tipo_contable IN ('Venta','Administracion')
        AND pf.deleted_at IS NULL
        AND pf.fecha_emision BETWEEN v_inicio_mes AND v_fin_mes
        AND (pf.organization_id = public.org_scope())
    ),
    gastos_op_sin_tc AS (
      -- FIX BL-11: mismo fallback DOF — una factura EUR con TC DOF disponible ya
      -- no cuenta como "sin TC".
      SELECT COUNT(*) AS val
      FROM proveedor_facturas pf
      JOIN presupuesto_categorias pc ON pc.id = pf.categoria_presupuesto_id
      LEFT JOIN embarques_base eb ON eb.id = pf.embarque_id
      LEFT JOIN LATERAL (
        SELECT d.eur_mxn
          FROM public.tipos_cambio_dof d
         WHERE d.fecha <= pf.fecha_emision
         ORDER BY d.fecha DESC
         LIMIT 1
      ) dof ON pf.moneda = 'EUR' AND eb.tipo_cambio_eur IS NULL
      WHERE pc.tipo_contable IN ('Venta','Administracion')
        AND pf.deleted_at IS NULL
        AND pf.fecha_emision BETWEEN v_inicio_mes AND v_fin_mes
        AND (pf.organization_id = public.org_scope())
        AND pf.moneda <> 'MXN'
        AND NOT (pf.moneda = 'USD' AND pf.tipo_cambio_usd > 1)
        AND NOT (pf.moneda = 'EUR' AND COALESCE(eb.tipo_cambio_eur, dof.eur_mxn, 0) > 1)
    ),
    gastos_op_comisiones AS (
      SELECT COALESCE(SUM(total_mxn), 0) AS val
      FROM liquidaciones_comision
      WHERE periodo = to_char(v_inicio_mes, 'YYYY-MM')
        AND (organization_id = public.org_scope())
    ),
    arribos_mes AS (
      SELECT jsonb_build_object(
        'total', count(*),
        'yaLlegaron', count(*) FILTER (WHERE eb.estado_real IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado')),
        'enCamino', count(*) FILTER (WHERE eb.estado_real IN ('Confirmado','En Tránsito')),
        'ventaMXN', COALESCE(sum(COALESCE(p.venta_mxn, 0)), 0),
        'costoMXN', COALESCE(sum(COALESCE(p.costo_mxn, 0)), 0),
        'profitMXN', COALESCE(sum(COALESCE(p.venta_mxn, 0) - COALESCE(p.costo_mxn, 0)), 0),
        'ventaMxnFromUsd', COALESCE(sum(COALESCE(p.venta_mxn_from_usd, 0)), 0),
        'costoMxnFromUsd', COALESCE(sum(COALESCE(p.costo_mxn_from_usd, 0)), 0),
        'ventaMxnFromEur', COALESCE(sum(COALESCE(p.venta_mxn_from_eur, 0)), 0),
        'costoMxnFromEur', COALESCE(sum(COALESCE(p.costo_mxn_from_eur, 0)), 0),
        'ventaMxnNative', COALESCE(sum(COALESCE(p.venta_mxn_native, 0)), 0),
        'costoMxnNative', COALESCE(sum(COALESCE(p.costo_mxn_native, 0)), 0),
        'profitUSD', COALESCE(sum(COALESCE(p.venta_usd, 0) - COALESCE(p.costo_usd, 0)), 0),
        'gastosOperativosMXN',
          COALESCE((SELECT val FROM gastos_op_facturas), 0)
          + COALESCE((SELECT val FROM gastos_op_comisiones), 0),
        'gastosOperativosSinTC', COALESCE((SELECT val FROM gastos_op_sin_tc), 0)
      ) AS val
      FROM embarques_base eb
      LEFT JOIN profit p ON p.embarque_id = eb.id
      WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_mes AND eb.eta <= v_fin_mes
    ),
    resumen_sig AS (
      SELECT jsonb_build_object(
        'total', count(*),
        'ventaUSD', COALESCE(sum(COALESCE(p.venta_usd, 0)), 0),
        'costoUSD', COALESCE(sum(COALESCE(p.costo_usd, 0)), 0),
        'ventaMXN', COALESCE(sum(COALESCE(p.venta_mxn, 0)), 0),
        'costoMXN', COALESCE(sum(COALESCE(p.costo_mxn, 0)), 0),
        'profitMXN', COALESCE(sum(COALESCE(p.venta_mxn, 0) - COALESCE(p.costo_mxn, 0)), 0)
      ) AS val
      FROM activos eb
      LEFT JOIN profit p ON p.embarque_id = eb.id
      WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_sig AND eb.eta <= v_fin_sig
    )
    SELECT jsonb_build_object(
      'totalActivos', (SELECT count(*) FROM activos),
      'conteoPorEstado', COALESCE((SELECT val FROM conteo), '{}'::jsonb),
      'arribosEsteMes', COALESCE((SELECT val FROM arribos_mes), '{}'::jsonb),
      'resumenMesSiguiente', COALESCE((SELECT val FROM resumen_sig), '{}'::jsonb)
    )
  );
END;
$$;
CREATE FUNCTION public._docs_requeridos_por_estado(p_modo text, p_estado text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_estado
    WHEN 'Confirmado'  THEN ARRAY[]::text[]
    WHEN 'En Tránsito' THEN ARRAY[]::text[]
    WHEN 'En Aduana' THEN
      CASE p_modo
        WHEN 'Aéreo'     THEN ARRAY['Factura Comercial','Packing List','Air Waybill (AWB)']
        WHEN 'Terrestre' THEN ARRAY['Factura','Lista de Empaque','Carta Porte']
        ELSE                  ARRAY['Factura Comercial','Packing List','Bill of Lading (BL Master)','Bill of Lading (BL House)']
      END
    WHEN 'Llegada' THEN
      CASE p_modo
        WHEN 'Aéreo'     THEN ARRAY['Factura Comercial','Packing List','Air Waybill (AWB)']
        WHEN 'Terrestre' THEN ARRAY['Factura','Lista de Empaque','Carta Porte']
        ELSE                  ARRAY['Factura Comercial','Packing List','Bill of Lading (BL Master)','Bill of Lading (BL House)']
      END
    WHEN 'Arribo' THEN
      CASE p_modo
        WHEN 'Aéreo'     THEN ARRAY['Factura Comercial','Packing List','Air Waybill (AWB)']
        WHEN 'Terrestre' THEN ARRAY['Factura','Lista de Empaque','Carta Porte']
        ELSE                  ARRAY['Factura Comercial','Packing List','Bill of Lading (BL Master)','Bill of Lading (BL House)']
      END
    WHEN 'En Proceso' THEN
      CASE p_modo
        WHEN 'Aéreo'     THEN ARRAY['Factura Comercial','Packing List','Air Waybill (AWB)']
        WHEN 'Terrestre' THEN ARRAY['Factura','Lista de Empaque','Carta Porte']
        ELSE                  ARRAY['Factura Comercial','Packing List','Bill of Lading (BL Master)','Bill of Lading (BL House)']
      END
    WHEN 'Entregado' THEN
      CASE p_modo
        WHEN 'Aéreo'     THEN ARRAY['Factura Comercial','Packing List','Air Waybill (AWB)']
        WHEN 'Terrestre' THEN ARRAY['Factura','Lista de Empaque','Carta Porte']
        ELSE                  ARRAY['Factura Comercial','Packing List','Bill of Lading (BL Master)','Bill of Lading (BL House)']
      END
    WHEN 'EIR' THEN
      CASE p_modo
        WHEN 'Aéreo'     THEN ARRAY['Factura Comercial','Packing List','Air Waybill (AWB)']
        WHEN 'Terrestre' THEN ARRAY['Factura','Lista de Empaque','Carta Porte']
        ELSE                  ARRAY['Factura Comercial','Packing List','Bill of Lading (BL Master)','Bill of Lading (BL House)']
      END
    WHEN 'Por liquidar' THEN
      CASE p_modo
        WHEN 'Aéreo'     THEN ARRAY['Factura Comercial','Packing List','Air Waybill (AWB)']
        WHEN 'Terrestre' THEN ARRAY['Factura','Lista de Empaque','Carta Porte']
        ELSE                  ARRAY['Factura Comercial','Packing List','Bill of Lading (BL Master)','Bill of Lading (BL House)']
      END
    WHEN 'Cerrado' THEN
      CASE p_modo
        WHEN 'Aéreo'     THEN ARRAY['Factura Comercial','Packing List','Air Waybill (AWB)']
        WHEN 'Terrestre' THEN ARRAY['Factura','Lista de Empaque','Carta Porte']
        ELSE                  ARRAY['Factura Comercial','Packing List','Bill of Lading (BL Master)','Bill of Lading (BL House)']
      END
    ELSE ARRAY[]::text[]
  END;
$$;
CREATE FUNCTION public._embarques_sembrar_tc_dof() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tc RECORD;
BEGIN
  IF (NEW.tipo_cambio_usd IS NULL OR NEW.tipo_cambio_usd <= 0)
     OR (NEW.tipo_cambio_eur IS NULL OR NEW.tipo_cambio_eur <= 0) THEN
    SELECT * INTO v_tc FROM public.tc_dof_vigente(CURRENT_DATE);
    IF v_tc.usd_mxn IS NOT NULL AND v_tc.usd_mxn > 0
       AND (NEW.tipo_cambio_usd IS NULL OR NEW.tipo_cambio_usd <= 0) THEN
      NEW.tipo_cambio_usd := v_tc.usd_mxn;
    END IF;
    IF v_tc.eur_mxn IS NOT NULL AND v_tc.eur_mxn > 0
       AND (NEW.tipo_cambio_eur IS NULL OR NEW.tipo_cambio_eur <= 0) THEN
      NEW.tipo_cambio_eur := v_tc.eur_mxn;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._entrante_meta_cliente_no_verificada() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_setting('app.entrante_xml_verificado', true) IS DISTINCT FROM 'on' THEN
    NEW.metadatos_verificados := false;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._es_rol_interno() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT current_user IN ('postgres', 'service_role', 'supabase_admin');
$$;
CREATE FUNCTION public._factura_tc_dof_obligatorio() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tc numeric;
  v_fecha date;
BEGIN
  IF NEW.moneda::text = 'MXN' THEN
    -- M2-res: al volver a MXN el T/C heredado deja de aplicar.
    IF TG_OP = 'UPDATE' AND OLD.moneda::text <> 'MXN' THEN
      NEW.tipo_cambio := 1;
    END IF;
    RETURN NEW;
  END IF;
  -- M2-res: si la moneda cambió, el T/C anterior no sirve: se recalcula.
  IF TG_OP = 'UPDATE'
     AND OLD.moneda::text IS DISTINCT FROM NEW.moneda::text
     AND NEW.tipo_cambio IS NOT DISTINCT FROM OLD.tipo_cambio THEN
    NEW.tipo_cambio := NULL;
  END IF;
  IF COALESCE(NEW.tipo_cambio, 0) > 1 THEN
    RETURN NEW;
  END IF;
  v_fecha := COALESCE(NEW.fecha_emision, (now() AT TIME ZONE 'America/Mexico_City')::date);
  SELECT CASE
           WHEN NEW.moneda::text = 'USD' THEN d.usd_mxn
           WHEN NEW.moneda::text = 'EUR' THEN d.eur_mxn
         END
    INTO v_tc
  FROM public.tc_dof_vigente(v_fecha) d;
  IF COALESCE(v_tc, 0) <= 1 THEN
    RAISE EXCEPTION 'LC_FACTURA_SIN_TC_DOF: no hay tipo de cambio DOF para % al %; captúralo antes de generar la factura',
      NEW.moneda, v_fecha
      USING ERRCODE = '22023';
  END IF;
  NEW.tipo_cambio := v_tc;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._garantia_congelar_monto_trg() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.estado IN ('depositado','retenido','liberado')
     AND NEW.monto_deposito_usd IS DISTINCT FROM OLD.monto_deposito_usd THEN
    RAISE EXCEPTION 'LC_GARANTIA_MONTO_CONGELADO: no se puede modificar el monto en estado %', OLD.estado
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._garantia_fechas_requeridas_trg() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado = 'depositado' AND OLD.estado IS DISTINCT FROM 'depositado' THEN
    IF NEW.fecha_deposito IS NULL THEN
      RAISE EXCEPTION 'LC_GARANTIA_FECHA_DEPOSITO_REQUERIDA'
        USING ERRCODE = 'not_null_violation';
    END IF;
    IF COALESCE(NEW.monto_deposito_usd, 0) <= 0 THEN
      RAISE EXCEPTION 'LC_GARANTIA_MONTO_REQUERIDO'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.estado = 'liberado' AND OLD.estado IS DISTINCT FROM 'liberado' THEN
    IF NEW.fecha_liberacion IS NULL THEN
      RAISE EXCEPTION 'LC_GARANTIA_FECHA_LIBERACION_REQUERIDA'
        USING ERRCODE = 'not_null_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._garantia_historial_trg() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.embarque_garantias_historial
      (garantia_id, organization_id, estado_anterior, estado_nuevo,
       monto_deposito_usd, referencia_deposito, notas, changed_by)
    VALUES (NEW.id, NEW.organization_id, NULL, NEW.estado,
            NEW.monto_deposito_usd, NEW.referencia_deposito, NEW.notas, auth.uid());
    RETURN NEW;
  END IF;
  IF NEW.estado IS DISTINCT FROM OLD.estado
     OR NEW.monto_deposito_usd IS DISTINCT FROM OLD.monto_deposito_usd
     OR NEW.referencia_deposito IS DISTINCT FROM OLD.referencia_deposito
     OR NEW.notas IS DISTINCT FROM OLD.notas THEN
    INSERT INTO public.embarque_garantias_historial
      (garantia_id, organization_id, estado_anterior, estado_nuevo,
       monto_deposito_usd, referencia_deposito, notas, changed_by)
    VALUES (NEW.id, NEW.organization_id, OLD.estado, NEW.estado,
            NEW.monto_deposito_usd, NEW.referencia_deposito, NEW.notas, auth.uid());
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._garantia_transicion_valida_trg() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado IS DISTINCT FROM OLD.estado THEN
    IF NOT public.transicion_garantia_valida(OLD.estado, NEW.estado) THEN
      RAISE EXCEPTION 'LC_GARANTIA_TRANSICION_INVALIDA: % -> %', OLD.estado, NEW.estado
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._guard_soft_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new jsonb;
  v_uid uuid;
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;
  IF COALESCE(current_setting('app.papelera_restore', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF NEW.deleted_at IS NOT DISTINCT FROM OLD.deleted_at THEN
    RETURN NEW;
  END IF;
  IF OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL THEN
    RAISE EXCEPTION 'LC_RESTORE_DIRECTO: para restaurar este registro usa la Papelera'
      USING ERRCODE = 'P0001';
  END IF;
  IF OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'LC_DELETED_AT_INMUTABLE: la fecha de borrado de un registro en papelera no se puede modificar'
      USING ERRCODE = 'P0001';
  END IF;
  v_uid := auth.uid();
  v_new := to_jsonb(NEW) || jsonb_build_object('deleted_at', now());
  IF v_new ? 'deleted_by' AND v_uid IS NOT NULL THEN
    v_new := v_new || jsonb_build_object('deleted_by', v_uid);
  END IF;
  NEW := jsonb_populate_record(NEW, v_new);
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._liquidacion_guard_estado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado IS DISTINCT FROM OLD.estado THEN
    IF NOT (
      (OLD.estado = 'Generada' AND NEW.estado IN ('Pagada','Cancelada'))
      OR (OLD.estado = 'Pagada' AND NEW.estado = 'Cancelada')
    ) THEN
      RAISE EXCEPTION 'LC_LIQUIDACION_TRANSICION_INVALIDA: no se permite pasar la liquidación de % a %', OLD.estado, NEW.estado
        USING ERRCODE = 'P0001';
    END IF;
  ELSIF OLD.estado = 'Cancelada' AND NEW.deleted_at IS NOT DISTINCT FROM OLD.deleted_at THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_CANCELADA_INMUTABLE: una liquidación cancelada no se puede modificar'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._log_provisioning_step(p_org_id uuid, p_source text, p_accion text, p_entidad text, p_filas integer, p_detalles jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_filas IS NULL OR p_filas <= 0 THEN
    RETURN; -- nada que registrar
  END IF;
  INSERT INTO public.provisioning_log(
    organization_id, source, accion, entidad, filas_afectadas, detalles, created_by
  ) VALUES (
    p_org_id, p_source, p_accion, p_entidad, p_filas, coalesce(p_detalles,'{}'::jsonb), auth.uid()
  );
END;
$$;
CREATE FUNCTION public._log_role_change_om() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    INSERT INTO public.role_change_log
      (user_id, organization_id, source, from_role, to_role, changed_by)
    VALUES
      (NEW.user_id, NEW.organization_id, 'organization_members', OLD.role::text, NEW.role::text, auth.uid());
    PERFORM public.registrar_bitacora(
      'usuarios', 'cambiar_rol', NEW.user_id, '',
      jsonb_build_object('origen', 'organization_members', 'rol_anterior', OLD.role::text, 'rol_nuevo', NEW.role::text),
      NEW.organization_id, auth.uid());
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._log_role_change_ur() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    INSERT INTO public.role_change_log
      (user_id, organization_id, source, from_role, to_role, changed_by)
    VALUES
      (NEW.user_id, NULL, 'user_roles', OLD.role::text, NEW.role::text, auth.uid());
    PERFORM public.registrar_bitacora(
      'usuarios', 'cambiar_rol_global', NEW.user_id, '',
      jsonb_build_object('origen', 'user_roles', 'rol_anterior', OLD.role::text, 'rol_nuevo', NEW.role::text),
      NULL, auth.uid());
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._nc_alerta_retenciones_pagadas() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ret numeric;
BEGIN
  IF NEW.factura_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.estado::text NOT IN ('Aplicada','Timbrada') THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.estado::text = NEW.estado::text THEN RETURN NEW; END IF;
  SELECT COALESCE(SUM(COALESCE(p.ret_isr,0) + COALESCE(p.ret_iva,0)), 0)
    INTO v_ret
    FROM public.pagos_factura p
   WHERE p.factura_id = NEW.factura_id AND p.deleted_at IS NULL;
  IF v_ret > 0 THEN
    INSERT INTO public.alertas_sistema (severity, source, message, payload, dedupe_key)
    VALUES ('warning', 'retenciones_nc',
            'Nota de crédito aplicada a una factura con pagos que ya declararon retenciones: revisa el prorrateo.',
            jsonb_build_object('factura_id', NEW.factura_id, 'nota_credito_id', NEW.id,
                               'retenciones_pagadas', v_ret),
            'retenciones_nc:' || NEW.id::text)
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._nc_aplicadas_moneda_factura(p_factura_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(SUM(
    CASE
      WHEN nc.moneda::text = f.moneda::text THEN nc.monto
      WHEN f.moneda::text = 'MXN' AND nc.moneda::text <> 'MXN' AND nc.tipo_cambio > 1
        THEN nc.monto * nc.tipo_cambio
      WHEN f.moneda::text <> 'MXN' AND nc.moneda::text = 'MXN' AND f.tipo_cambio > 1
        THEN nc.monto / f.tipo_cambio
      WHEN f.moneda::text <> 'MXN' AND nc.moneda::text <> 'MXN'
           AND f.moneda::text <> nc.moneda::text
           AND nc.tipo_cambio > 1 AND f.tipo_cambio > 1
        THEN (nc.monto * nc.tipo_cambio) / f.tipo_cambio
      ELSE 0
    END), 0)
  FROM public.facturas f
  JOIN public.factura_notas_credito nc
    ON nc.factura_id = f.id
   AND nc.deleted_at IS NULL
   AND nc.estado = 'Aplicada'
  WHERE f.id = p_factura_id;
$$;
CREATE FUNCTION public._nc_cliente_recalcular_comisiones() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pago RECORD;
  v_contaba boolean;
  v_cuenta boolean;
BEGIN
  v_cuenta  := (NEW.estado::text = 'Aplicada' AND NEW.deleted_at IS NULL);
  v_contaba := (TG_OP = 'UPDATE'
                AND OLD.estado::text = 'Aplicada'
                AND OLD.deleted_at IS NULL);
  IF NOT v_cuenta AND NOT v_contaba THEN
    RETURN NEW;
  END IF;
  IF v_cuenta AND v_contaba
     AND COALESCE(OLD.monto, 0) = COALESCE(NEW.monto, 0) THEN
    RETURN NEW;
  END IF;
  FOR v_pago IN
    SELECT pf.id, pf.organization_id,
           EXISTS (
             SELECT 1 FROM public.comisiones_devengadas cd
              WHERE cd.pago_factura_id = pf.id
                AND cd.estado = 'Liquidada'
                AND cd.deleted_at IS NULL
           ) AS ya_liquidada
      FROM public.pagos_factura pf
     WHERE pf.factura_id = NEW.factura_id
       AND pf.deleted_at IS NULL
  LOOP
    IF v_pago.ya_liquidada THEN
      PERFORM public.registrar_comision_pendiente(
        v_pago.organization_id, v_pago.id, 'ajuste_nc_liquidada',
        CASE WHEN v_cuenta
          THEN 'Nota de crédito aplicada sobre comisión ya liquidada: descontar en la siguiente liquidación'
          ELSE 'Nota de crédito cancelada o en papelera sobre comisión ya liquidada: recalcular el ajuste en la siguiente liquidación'
        END,
        '', '');
    ELSE
      BEGIN
        PERFORM public.calcular_comision_pago(v_pago.id);
      EXCEPTION WHEN OTHERS THEN
        PERFORM public.registrar_comision_pendiente(
          v_pago.organization_id, v_pago.id, 'ajuste_nc',
          'No se pudo recalcular la comisión tras la nota de crédito',
          SQLSTATE, SQLERRM);
      END;
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._nc_prov_tc_moneda_convertible() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_moneda_factura text;
  v_moneda_ext text;
  v_fecha date;
  v_tc numeric;
BEGIN
  SELECT pf.moneda::text INTO v_moneda_factura
  FROM public.proveedor_facturas pf
  WHERE pf.id = NEW.proveedor_factura_id;
  IF v_moneda_factura IS NULL OR NEW.moneda::text = v_moneda_factura THEN
    NEW.tipo_cambio := NULL;
    RETURN NEW;
  END IF;
  IF NEW.moneda::text <> 'MXN' AND v_moneda_factura <> 'MXN' THEN
    RAISE EXCEPTION 'LC_NC_PROV_MONEDA_NO_CONVERTIBLE: no hay tipo de cambio cruzado entre % y %; captura la nota de crédito en % o en MXN',
      NEW.moneda, v_moneda_factura, v_moneda_factura
      USING ERRCODE = '22023';
  END IF;
  IF COALESCE(NEW.tipo_cambio, 0) > 1 THEN
    RETURN NEW;
  END IF;
  v_moneda_ext := CASE WHEN NEW.moneda::text = 'MXN' THEN v_moneda_factura ELSE NEW.moneda::text END;
  v_fecha := COALESCE(NEW.fecha, (now() AT TIME ZONE 'America/Mexico_City')::date);
  SELECT CASE
           WHEN v_moneda_ext = 'USD' THEN d.usd_mxn
           WHEN v_moneda_ext = 'EUR' THEN d.eur_mxn
         END
    INTO v_tc
  FROM public.tc_dof_vigente(v_fecha) d;
  IF COALESCE(v_tc, 0) <= 1 THEN
    RAISE EXCEPTION 'LC_NC_PROV_TC_REQUERIDO: falta tipo de cambio DOF para % al %; captúralo antes de registrar la nota de crédito',
      v_moneda_ext, v_fecha
      USING ERRCODE = '22023';
  END IF;
  NEW.tipo_cambio := v_tc;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._normalizar_email() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.email IS NOT NULL THEN
    NEW.email := NULLIF(lower(btrim(NEW.email)), '');
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._normalizar_razon_social() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.nombre IS NOT NULL THEN
    BEGIN
      NEW.nombre := upper(
        regexp_replace(btrim(NEW.nombre), '\s+', ' ', 'g') COLLATE "lc_unicode_upper"
      );
    EXCEPTION WHEN undefined_object OR undefined_function THEN
      NEW.nombre := upper(regexp_replace(btrim(NEW.nombre), '\s+', ' ', 'g'));
    END;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._normalizar_uuid_fiscal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.uuid_fiscal IS NOT NULL THEN
    NEW.uuid_fiscal := NULLIF(upper(btrim(NEW.uuid_fiscal)), '');
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._prohibir_delete_comisiones() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'LC_COMISION_DELETE_PROHIBIDO: las comisiones y liquidaciones no se borran; usa la cancelación oficial'
    USING ERRCODE = 'P0001';
END;
$$;
CREATE FUNCTION public._prohibir_delete_factura() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_setting('app.seed_demo', true) = '1'
     AND OLD.organization_id = 'de100000-0000-0000-0000-000000000001'::uuid THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'LC_FACTURA_DELETE_PROHIBIDO: las facturas no se borran físicamente; usa la baja lógica (soft_delete_record) o cancela/sustituye el CFDI'
    USING ERRCODE = '42501';
END;
$$;
CREATE FUNCTION public._proveedor_contacto_principal_unico() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.es_principal AND NEW.deleted_at IS NULL THEN
    UPDATE public.proveedor_contactos
       SET es_principal = false
     WHERE proveedor_id = NEW.proveedor_id
       AND id <> NEW.id
       AND es_principal
       AND deleted_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._reabrir_entrantes_factura() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.embarque_facturas_entrantes e
     SET estado = 'por_capturar',
         proveedor_factura_id = NULL,
         capturado_por = NULL
   WHERE e.proveedor_factura_id = NEW.id
     AND e.deleted_at IS NULL
     AND e.estado = 'capturada';
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._recalc_anticipo_saldo(p_anticipo_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.anticipos_proveedor;
  v_aplicado numeric(18,4);
  v_nuevo_saldo numeric(18,4);
  v_nuevo_estado text;
BEGIN
  SELECT * INTO v_row FROM public.anticipos_proveedor WHERE id = p_anticipo_id;
  IF v_row.id IS NULL THEN RETURN; END IF;
  -- Respeta cancelado, devuelto (N13) y soft-deleted.
  IF v_row.estado IN ('cancelado','devuelto') OR v_row.deleted_at IS NOT NULL THEN RETURN; END IF;
  SELECT COALESCE(SUM(monto_aplicado),0) INTO v_aplicado
    FROM public.anticipos_aplicaciones
    WHERE anticipo_id = p_anticipo_id
      AND deleted_at IS NULL
      AND moneda_aplicada = v_row.moneda;
  v_nuevo_saldo := v_row.monto - v_aplicado;
  IF v_aplicado <= 0.01 THEN
    v_nuevo_estado := 'disponible';
  ELSIF v_nuevo_saldo <= 0.01 THEN
    v_nuevo_estado := 'aplicado_total';
  ELSE
    v_nuevo_estado := 'aplicado_parcial';
  END IF;
  UPDATE public.anticipos_proveedor
    SET saldo_disponible = v_nuevo_saldo,
        estado = v_nuevo_estado,
        updated_at = now()
    WHERE id = p_anticipo_id
      AND (saldo_disponible IS DISTINCT FROM v_nuevo_saldo OR estado IS DISTINCT FROM v_nuevo_estado);
END;
$$;
CREATE FUNCTION public._recalc_estado_proveedor_factura(p_factura_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado text;
  v_captura text;
  v_saldo  numeric;
  v_nuevo  text;
  v_nueva_captura text;
BEGIN
  SELECT estado::text, estado_captura
    INTO v_estado, v_captura
  FROM public.proveedor_facturas
  WHERE id = p_factura_id;
  IF v_estado IS NULL THEN RETURN; END IF;
  IF v_estado IN ('Cancelada','Borrador') THEN RETURN; END IF;
  SELECT COALESCE(saldo, 0) INTO v_saldo
  FROM public.v_proveedor_facturas_saldo
  WHERE proveedor_factura_id = p_factura_id;
  IF v_saldo IS NULL THEN v_saldo := 0; END IF;
  IF v_saldo <= 0.01 THEN v_nuevo := 'Pagada'; ELSE v_nuevo := 'Vigente'; END IF;
  -- R2-32: sincroniza estado_captura con el estado financiero
  IF v_nuevo = 'Pagada' THEN
    v_nueva_captura := 'pagada';
  ELSIF v_captura = 'pagada' THEN
    -- Reabrió saldo: retrocede de 'pagada' → 'capturada'
    v_nueva_captura := 'capturada';
  ELSE
    v_nueva_captura := v_captura;
  END IF;
  IF v_nuevo IS DISTINCT FROM v_estado
     OR v_nueva_captura IS DISTINCT FROM v_captura THEN
    PERFORM set_config('app.recalc_cxp','1', true);
    BEGIN
      UPDATE public.proveedor_facturas
         SET estado         = v_nuevo::estado_proveedor_factura,
             estado_captura = v_nueva_captura,
             updated_at     = now()
       WHERE id = p_factura_id
         AND (estado::text IS DISTINCT FROM v_nuevo
              OR estado_captura IS DISTINCT FROM v_nueva_captura);
      PERFORM set_config('app.recalc_cxp','0', true);
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('app.recalc_cxp','0', true);
      RAISE;
    END;
  END IF;
END;
$$;
CREATE FUNCTION public._recompute_totales_embarque(p_embarque_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_peso numeric;
  v_total_vol numeric;
  v_total_piezas integer;
  v_primer record;
BEGIN
  IF p_embarque_id IS NULL THEN RETURN; END IF;
  SELECT COALESCE(SUM(peso_kg), 0), COALESCE(SUM(volumen_m3), 0), COALESCE(SUM(piezas), 0)
    INTO v_total_peso, v_total_vol, v_total_piezas
  FROM public.embarque_contenedores
  WHERE embarque_id = p_embarque_id AND deleted_at IS NULL;
  SELECT numero_contenedor, tipo_contenedor INTO v_primer
  FROM public.embarque_contenedores
  WHERE embarque_id = p_embarque_id AND deleted_at IS NULL
  ORDER BY orden ASC, created_at ASC
  LIMIT 1;
  UPDATE public.embarques
     SET contenedor = COALESCE(v_primer.numero_contenedor, ''),
         tipo_contenedor = COALESCE(v_primer.tipo_contenedor, ''),
         peso_kg = v_total_peso,
         volumen_m3 = v_total_vol,
         piezas = v_total_piezas
   WHERE id = p_embarque_id;
END;
$$;
CREATE FUNCTION public._refact_reps_bloqueantes(p_factura_id uuid) RETURNS TABLE(bloqueantes integer, en_verificacion integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    COUNT(*) FILTER (
      WHERE COALESCE(pf.rep_cancellation_status, '') NOT IN ('pending', 'verifying')
    )::int AS bloqueantes,
    COUNT(*) FILTER (
      WHERE COALESCE(pf.rep_cancellation_status, '') IN ('pending', 'verifying')
    )::int AS en_verificacion
  FROM public.pagos_factura pf
  WHERE pf.factura_id = p_factura_id
    AND pf.deleted_at IS NULL
    AND pf.uuid_rep IS NOT NULL
    AND pf.rep_cancelado_en IS NULL;
$$;
CREATE FUNCTION public._reprocesar_comisiones_org(p_org uuid) RETURNS TABLE(procesadas integer, resueltas integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row RECORD;
  v_procesadas integer := 0;
  v_resueltas integer := 0;
  v_comision numeric;
  v_estado text;
BEGIN
  IF p_org IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_INEXISTENTE: organización requerida'
      USING ERRCODE = '42501';
  END IF;
  FOR v_row IN
    SELECT id, pago_factura_id
      FROM public.comisiones_recalculo_pendiente
     WHERE organization_id = p_org AND resuelto_at IS NULL
       -- FIX B-4: el ajuste de una NC sobre comisión ya Liquidada NO se
       -- auto-resuelve; requiere descuento manual y debe permanecer visible.
       AND COALESCE(etapa, '') <> 'ajuste_nc_liquidada'
     ORDER BY created_at
  LOOP
    v_procesadas := v_procesadas + 1;
    BEGIN
      PERFORM public.calcular_comision_pago(v_row.pago_factura_id);
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.comisiones_recalculo_pendiente
         SET intentos = intentos + 1,
             sqlstate_code = SQLSTATE,
             sqlerrm_text = SQLERRM,
             updated_at = now()
       WHERE id = v_row.id;
      CONTINUE;
    END;
    -- Sólo se cierra el pendiente si el recálculo dejó una comisión sana.
    -- Una comisión ya 'Liquidada' se respeta tal cual (guarda del canon).
    SELECT comision_mxn, estado INTO v_comision, v_estado
      FROM public.comisiones_devengadas
     WHERE pago_factura_id = v_row.pago_factura_id;
    IF v_estado = 'Liquidada' OR COALESCE(v_comision, 0) <> 0 THEN
      UPDATE public.comisiones_recalculo_pendiente
         SET resuelto_at = now(),
             resultado_recalculo = 'Comisión recalculada: ' || COALESCE(v_comision, 0)::text,
             updated_at = now()
       WHERE id = v_row.id;
      v_resueltas := v_resueltas + 1;
    ELSE
      UPDATE public.comisiones_recalculo_pendiente
         SET intentos = intentos + 1,
             sqlerrm_text = 'Recálculo sigue dando 0 (faltan datos del embarque)',
             updated_at = now()
       WHERE id = v_row.id;
    END IF;
  END LOOP;
  RETURN QUERY SELECT v_procesadas, v_resueltas;
END;
$$;
CREATE FUNCTION public._resolver_proveedor_por_nombre(p_org uuid, p_nombre text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_nombre text := upper(btrim(COALESCE(p_nombre, '')));
  v_id uuid;
  v_n integer;
  v_txt text;
BEGIN
  IF v_nombre = '' THEN RETURN NULL; END IF;
  SELECT p.id INTO v_id
    FROM public.proveedores p
   WHERE p.organization_id = p_org
     AND p.deleted_at IS NULL
     AND upper(btrim(p.nombre)) = v_nombre
   ORDER BY p.created_at
   LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  SELECT count(*), min(p.id::text) INTO v_n, v_txt
    FROM public.proveedores p
   WHERE p.organization_id = p_org
     AND p.deleted_at IS NULL
     AND upper(btrim(p.nombre)) LIKE v_nombre || '%';
  IF v_n = 1 THEN RETURN v_txt::uuid; END IF;
  RETURN NULL;
END;
$$;
CREATE FUNCTION public._rfc_valido(p_rfc text, p_permitir_generico boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  v text := upper(btrim(COALESCE(p_rfc, '')));
BEGIN
  IF v = '' THEN
    RETURN false;
  END IF;
  IF NOT p_permitir_generico AND v IN ('XAXX010101000', 'XEXX010101000') THEN
    RETURN false;
  END IF;
  RETURN v ~ '^[A-ZÑ&]{3,4}[0-9]{6}[A-Z0-9]{3}$';
END;
$_$;
CREATE FUNCTION public._seed_demo_limpiar_financiero() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := 'de100000-0000-0000-0000-000000000001'::uuid;
BEGIN
  PERFORM set_config('app.seed_demo', '1', true);
  -- Los REPs vivos bloquean el borrado de pagos: en demo se limpian primero.
  UPDATE public.pagos_factura
     SET uuid_rep = NULL, estado_rep = NULL, rep_cancelado_en = now()
   WHERE organization_id = v_org
     AND uuid_rep IS NOT NULL;
  -- CxC y comisiones (dependen de facturas y embarques).
  DELETE FROM public.comisiones_recalculo_pendiente WHERE organization_id = v_org;
  DELETE FROM public.comisiones_excepciones WHERE organization_id = v_org;
  DELETE FROM public.comisiones_devengadas WHERE organization_id = v_org;
  DELETE FROM public.liquidaciones_comision WHERE organization_id = v_org;
  DELETE FROM public.cobranza_seguimiento WHERE organization_id = v_org;
  DELETE FROM public.factura_recordatorios WHERE organization_id = v_org;
  DELETE FROM public.factura_envios WHERE organization_id = v_org;
  DELETE FROM public.factura_notas_credito WHERE organization_id = v_org;
  DELETE FROM public.bbva_movimientos WHERE organization_id = v_org;
  DELETE FROM public.traspasos_bancarios WHERE organization_id = v_org;
  DELETE FROM public.pagos_factura WHERE organization_id = v_org;
  DELETE FROM public.pagos_factura_lote WHERE organization_id = v_org;
  DELETE FROM public.pagos_proveedor_lote WHERE organization_id = v_org;
  DELETE FROM public.refacturaciones WHERE organization_id = v_org;
  DELETE FROM public.factura_embarques WHERE organization_id = v_org;
  DELETE FROM public.conceptos_factura WHERE organization_id = v_org;
  DELETE FROM public.facturas WHERE organization_id = v_org;
  -- Proformas y conceptos de venta/costo.
  DELETE FROM public.proforma_envios WHERE organization_id = v_org;
  DELETE FROM public.proforma_conceptos_consolidados WHERE organization_id = v_org;
  DELETE FROM public.conceptos_venta WHERE organization_id = v_org;
  DELETE FROM public.conceptos_costo WHERE organization_id = v_org;
  DELETE FROM public.proformas WHERE organization_id = v_org;
  -- Operación del embarque.
  DELETE FROM public.embarque_facturas_entrantes_conceptos WHERE organization_id = v_org;
  DELETE FROM public.embarque_facturas_entrantes WHERE organization_id = v_org;
  DELETE FROM public.embarque_garantias_historial WHERE organization_id = v_org;
  DELETE FROM public.embarque_garantias_contenedor WHERE organization_id = v_org;
  DELETE FROM public.embarque_contenedores WHERE organization_id = v_org;
  DELETE FROM public.documentos_embarque WHERE organization_id = v_org;
  DELETE FROM public.notas_embarque WHERE organization_id = v_org;
  DELETE FROM public.seguros_embarque WHERE organization_id = v_org;
  DELETE FROM public.cierre_embarque_log WHERE organization_id = v_org;
  DELETE FROM public.tracking_externo WHERE organization_id = v_org;
  DELETE FROM public.tracking_links WHERE organization_id = v_org;
  DELETE FROM public.cotizacion_costos WHERE organization_id = v_org;
  DELETE FROM public.cotizacion_versiones WHERE organization_id = v_org;
  DELETE FROM public.cotizacion_envios WHERE organization_id = v_org;
  PERFORM set_config('app.seed_demo', '0', true);
END;
$$;
CREATE FUNCTION public._sync_user_roles_desde_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_excluidos text[] := ARRAY['super_admin', 'admin', 'operador', 'viewer'];
  v_old_role  app_role;
  v_user_id   uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_old_role := OLD.role;
    v_user_id  := OLD.user_id;
  ELSIF TG_OP = 'UPDATE' AND NEW.role IS DISTINCT FROM OLD.role THEN
    v_old_role := OLD.role;
    v_user_id  := OLD.user_id;
  END IF;
  -- Retira el espejo anterior sólo si ninguna otra membresía lo respalda.
  IF v_old_role IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.organization_members om
      WHERE om.user_id = v_user_id
        AND om.role = v_old_role
    ) THEN
      DELETE FROM public.user_roles ur
      WHERE ur.user_id = v_user_id
        AND ur.role = v_old_role;
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  -- Espejo del rol vigente (nunca roles de plataforma ni legacy deprecados).
  IF NOT (NEW.role::text = ANY (v_excluidos)) THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.user_id, NEW.role)
    ON CONFLICT (user_id) DO UPDATE
      SET role = EXCLUDED.role
      WHERE public.user_roles.role::text NOT IN ('super_admin', 'cliente')
        AND public.user_roles.role IS DISTINCT FROM EXCLUDED.role;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._tracking_link_vigencia_maxima() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_base timestamptz := COALESCE(NEW.created_at, now());
BEGIN
  IF NEW.expires_at IS NULL THEN
    NEW.expires_at := v_base + interval '30 days';
  END IF;
  IF NEW.expires_at > v_base + interval '90 days' THEN
    RAISE EXCEPTION 'LC_TRACKING_VIGENCIA_EXCEDIDA: un enlace público de rastreo no puede durar más de 90 días.'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public._trg_autocierre_por_liquidar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_embarque_id uuid;
  v_estado text;
BEGIN
  IF TG_TABLE_NAME = 'pagos_factura' THEN
    SELECT f.embarque_id INTO v_embarque_id
      FROM facturas f WHERE f.id = COALESCE(NEW.factura_id, OLD.factura_id);
  ELSE
    SELECT pf.embarque_id INTO v_embarque_id
      FROM proveedor_facturas pf WHERE pf.id = COALESCE(NEW.proveedor_factura_id, OLD.proveedor_factura_id);
  END IF;
  IF v_embarque_id IS NULL THEN RETURN NULL; END IF;
  SELECT estado::text INTO v_estado FROM embarques WHERE id = v_embarque_id;
  IF v_estado IS DISTINCT FROM 'Por liquidar' THEN RETURN NULL; END IF;
  BEGIN
    PERFORM set_config('app.cierre_automatico','on', true);
    PERFORM public.cerrar_embarque(v_embarque_id);
    PERFORM set_config('app.cierre_automatico','off', true);
  EXCEPTION WHEN OTHERS THEN
    -- Checklist incompleto o cualquier otro impedimento: el pago se guarda igual.
    PERFORM set_config('app.cierre_automatico','off', true);
  END;
  RETURN NULL;
END;
$$;
CREATE FUNCTION public._trg_promover_por_liquidar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_embarque_id uuid := COALESCE(NEW.embarque_id, OLD.embarque_id);
BEGIN
  BEGIN
    PERFORM public.promover_embarque_por_liquidar(v_embarque_id);
  EXCEPTION WHEN OTHERS THEN
    NULL; -- nunca romper la operación original por la promoción de estado
  END;
  RETURN NULL;
END;
$$;
CREATE FUNCTION public._trg_promover_por_liquidar_pfc() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_embarque_id uuid;
BEGIN
  SELECT cc.embarque_id INTO v_embarque_id
    FROM conceptos_costo cc
   WHERE cc.id = COALESCE(NEW.concepto_costo_id, OLD.concepto_costo_id);
  BEGIN
    PERFORM public.promover_embarque_por_liquidar(v_embarque_id);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN NULL;
END;
$$;
CREATE FUNCTION public._validar_cronologia_evento_embarque() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_zarpe timestamptz;
  v_arribo timestamptz;
  v_creado timestamptz;
  v_reales text[] := ARRAY[
    'Zarpe','Arribo a Puerto','Descarga','Despacho Aduanal','Liberación','Entrega'
  ];
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.tipo::text = ANY (v_reales) AND NEW.fecha > now() + interval '1 day' THEN
    RAISE EXCEPTION 'LC_EVENTO_FECHA_FUTURA: el evento "%" no puede registrarse con fecha futura.', NEW.tipo
      USING ERRCODE = 'check_violation';
  END IF;
  -- M5-res: margen de 1 día para embarques capturados con historia previa
  -- (el expediente se abre después de que el buque zarpó).
  SELECT e.created_at INTO v_creado
  FROM public.embarques e
  WHERE e.id = NEW.embarque_id;
  IF v_creado IS NOT NULL
     AND NEW.tipo::text = ANY (v_reales)
     AND NEW.fecha < (v_creado - interval '1 day') THEN
    RAISE EXCEPTION 'LC_EVENTO_ANTERIOR_A_EMBARQUE: el evento "%" (%) es anterior a la creación del embarque (%).',
      NEW.tipo, NEW.fecha, v_creado
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT min(e.fecha) INTO v_zarpe
  FROM public.eventos_embarque e
  WHERE e.embarque_id = NEW.embarque_id
    AND e.deleted_at IS NULL
    AND e.id <> NEW.id
    AND e.tipo = 'Zarpe';
  IF v_zarpe IS NOT NULL
     AND NEW.tipo::text IN ('Arribo a Puerto','Descarga','Despacho Aduanal','Liberación','Entrega')
     AND NEW.fecha < v_zarpe THEN
    RAISE EXCEPTION 'LC_EVENTO_ORDEN_INVALIDO: "%" no puede ser anterior al zarpe (%).', NEW.tipo, v_zarpe
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.tipo::text = 'Entrega' THEN
    SELECT min(e.fecha) INTO v_arribo
    FROM public.eventos_embarque e
    WHERE e.embarque_id = NEW.embarque_id
      AND e.deleted_at IS NULL
      AND e.id <> NEW.id
      AND e.tipo = 'Arribo a Puerto';
    IF v_arribo IS NOT NULL AND NEW.fecha < v_arribo THEN
      RAISE EXCEPTION 'LC_EVENTO_ORDEN_INVALIDO: la entrega no puede ser anterior al arribo (%).', v_arribo
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.a_mxn(p_monto numeric, p_moneda text, p_usd_mxn numeric, p_eur_mxn numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_monto IS NULL THEN NULL
    WHEN p_moneda = 'MXN' THEN p_monto
    -- M-8: > 1 (no > 0). En México el T/C se maneja como pesos por dólar/euro,
    -- así que 1 o menos nunca es un tipo de cambio real.
    WHEN p_moneda = 'USD' AND COALESCE(p_usd_mxn, 0) > 1 THEN round(p_monto * p_usd_mxn, 4)
    WHEN p_moneda = 'EUR' AND COALESCE(p_eur_mxn, 0) > 1 THEN round(p_monto * p_eur_mxn, 4)
    ELSE NULL
  END
$$;
CREATE FUNCTION public.a_mxn_doc(_monto numeric, _moneda text, _fecha date, _tc_documento numeric DEFAULT NULL::numeric, _tc_embarque numeric DEFAULT NULL::numeric) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _monto IS NULL THEN NULL
    WHEN UPPER(COALESCE(_moneda, 'MXN')) = 'MXN' THEN _monto
    WHEN t.tc IS NULL THEN NULL
    ELSE round(_monto * t.tc, 4)
  END
  FROM public.tc_para_documento(_fecha, _moneda, _tc_documento, _tc_embarque) t;
$$;
CREATE FUNCTION public.abrir_caso_refacturacion(p_factura_id uuid, p_cliente_destino_id uuid, p_ruta_fiscal text DEFAULT '02'::text, p_motivo text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_f public.facturas%ROWTYPE;
  v_dest_org uuid;
  v_id uuid;
BEGIN
  IF p_ruta_fiscal NOT IN ('01','02') THEN
    RAISE EXCEPTION 'LC_REFACT_RUTA: ruta fiscal inválida (01 o 02)' USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO v_f FROM public.facturas WHERE id = p_factura_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_FACTURA_NO_ENCONTRADA' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public._assert_refacturador(v_f.organization_id);
  IF v_f.uuid_fiscal IS NULL THEN
    RAISE EXCEPTION 'LC_REFACT_FACTURA_NO_TIMBRADA: la factura original no está timbrada'
      USING ERRCODE = 'P0001';
  END IF;
  IF v_f.estado IN ('Cancelada','Sustituida','Borrador') THEN
    RAISE EXCEPTION 'LC_REFACT_FACTURA_NO_VIVA: la factura está en estado %', v_f.estado
      USING ERRCODE = 'P0001';
  END IF;
  SELECT organization_id INTO v_dest_org
  FROM public.clientes WHERE id = p_cliente_destino_id AND deleted_at IS NULL;
  IF v_dest_org IS NULL OR v_dest_org <> v_f.organization_id THEN
    RAISE EXCEPTION 'LC_REFACT_CLIENTE_DESTINO: el cliente destino no existe en esta organización'
      USING ERRCODE = 'P0001';
  END IF;
  IF p_cliente_destino_id = v_f.cliente_id THEN
    RAISE EXCEPTION 'LC_REFACT_MISMO_CLIENTE: el cliente destino es el mismo de la factura'
      USING ERRCODE = 'P0001';
  END IF;
  PERFORM public._assert_receptor_fiscal_valido(p_cliente_destino_id);
  IF EXISTS (
    SELECT 1 FROM public.refacturaciones
    WHERE factura_original_id = p_factura_id AND estado = 'abierto'
  ) THEN
    RAISE EXCEPTION 'LC_REFACT_CASO_ABIERTO: ya existe un caso de refacturación abierto para esta factura'
      USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO public.refacturaciones (
    organization_id, factura_original_id, cliente_origen_id, cliente_destino_id,
    ruta_fiscal, motivo, embarque_id, pago_original_id, created_by
  ) VALUES (
    v_f.organization_id, p_factura_id, v_f.cliente_id, p_cliente_destino_id,
    p_ruta_fiscal, COALESCE(p_motivo, ''), v_f.embarque_id,
    (SELECT id FROM public.pagos_factura
      WHERE factura_id = p_factura_id AND deleted_at IS NULL
      ORDER BY fecha_pago DESC, created_at DESC LIMIT 1),
    auth.uid()
  )
  RETURNING id INTO v_id;
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_f.organization_id, auth.uid(),
    COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), ''),
    'refacturacion_abierta', 'facturacion', p_factura_id, COALESCE(v_f.numero, ''),
    jsonb_build_object('caso_id', v_id, 'ruta_fiscal', p_ruta_fiscal,
                       'cliente_destino_id', p_cliente_destino_id, 'motivo', COALESCE(p_motivo, ''))
  );
  RETURN v_id;
END;
$$;
CREATE FUNCTION public.aceptar_cotizacion_version(p_cotizacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_version INT; v_org UUID; v_folio TEXT;
  v_estado_actual TEXT; v_vigencia DATE;
  v_cliente_id UUID; v_requiere BOOLEAN; v_origen TEXT;
BEGIN
  SELECT version, organization_id, folio, estado::text, fecha_vigencia, cliente_id
    INTO v_version, v_org, v_folio, v_estado_actual, v_vigencia, v_cliente_id
    FROM cotizaciones WHERE id = p_cotizacion_id;
  IF v_version IS NULL THEN RAISE EXCEPTION 'Cotización no encontrada' USING ERRCODE='P0002'; END IF;
  IF NOT EXISTS (SELECT 1 FROM organization_members WHERE organization_id=v_org AND user_id=auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501';
  END IF;
  IF v_vigencia IS NOT NULL AND v_vigencia < CURRENT_DATE THEN
    RAISE EXCEPTION 'LC_COT_VENCIDA: la cotización venció el %, extienda la vigencia antes de aceptar', v_vigencia USING ERRCODE='P0001';
  END IF;
  v_requiere := public.cliente_requiere_autorizacion(v_cliente_id, 'cotizacion');
  v_origen := CASE WHEN v_requiere THEN 'autorizacion_cliente' ELSE 'interna_cliente_de_casa' END;
  IF v_requiere THEN
    IF v_estado_actual NOT IN ('Borrador','Enviada') THEN
      RAISE EXCEPTION 'LC_COTIZACION_ESTADO_INVALIDO: sólo se puede aceptar en Borrador/Enviada (actual: %, estados_permitidos: [Borrador, Enviada])', v_estado_actual
        USING ERRCODE='P0001', HINT='estados_permitidos=Borrador,Enviada';
    END IF;
  ELSE
    IF v_estado_actual NOT IN ('Borrador','Solicitada','Enviada') THEN
      RAISE EXCEPTION 'LC_COTIZACION_ESTADO_INVALIDO: sólo se puede aceptar en Borrador/Solicitada/Enviada (actual: %, estados_permitidos: [Borrador, Solicitada, Enviada])', v_estado_actual
        USING ERRCODE='P0001', HINT='estados_permitidos=Borrador,Solicitada,Enviada';
    END IF;
  END IF;
  UPDATE cotizaciones
     SET version_aceptada=v_version, aceptada_en=now(), aceptada_por=auth.uid(),
         estado='Aceptada', updated_at=now()
   WHERE id = p_cotizacion_id;
  INSERT INTO bitacora_actividad (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
  VALUES (v_org, auth.uid(),
    COALESCE((SELECT email FROM auth.users WHERE id=auth.uid()),''),
    'cotizacion.aceptada_version_fijada','cotizaciones',
    p_cotizacion_id, COALESCE(v_folio,''),
    jsonb_build_object('version_aceptada',v_version,'estado_previo',v_estado_actual,'origen_aceptacion',v_origen));
  RETURN jsonb_build_object('cotizacion_id',p_cotizacion_id,'version_aceptada',v_version,'origen_aceptacion',v_origen);
END;
$$;
CREATE FUNCTION public.aceptar_proforma_sin_autorizacion(p_proforma_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_p public.proformas%ROWTYPE;
  v_email text;
BEGIN
  SELECT * INTO v_p FROM public.proformas WHERE id = p_proforma_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_PROFORMA_NO_ENCONTRADA: la proforma no existe' USING ERRCODE='P0002';
  END IF;
  IF v_p.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'LC_PROFORMA_ELIMINADA: la proforma fue eliminada' USING ERRCODE='P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM organization_members WHERE organization_id=v_p.organization_id AND user_id=auth.uid()) THEN
    RAISE EXCEPTION 'LC_NO_AUTORIZADO: no perteneces a la organización de esta proforma' USING ERRCODE='42501';
  END IF;
  IF public.cliente_requiere_autorizacion(v_p.cliente_id, 'proforma') THEN
    RAISE EXCEPTION 'LC_PROFORMA_REQUIERE_AUTORIZACION: este cliente sí requiere autorización de proformas' USING ERRCODE='P0001';
  END IF;
  IF COALESCE(v_p.estado_cliente,'pendiente') = 'aceptada' THEN
    RETURN jsonb_build_object('proforma_id', p_proforma_id, 'estado_cliente', 'aceptada', 'sin_cambios', true);
  END IF;
  UPDATE public.proformas
     SET estado_cliente = 'aceptada',
         aceptada_at = now(),
         aceptada_por = 'auto:sin_autorizacion_requerida',
         rechazada_at = NULL,
         updated_at = now()
   WHERE id = p_proforma_id;
  v_email := COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), '');
  INSERT INTO bitacora_actividad (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
  VALUES (v_p.organization_id, auth.uid(), v_email,
    'proforma.aceptada_sin_autorizacion','proformas',
    p_proforma_id, COALESCE(v_p.numero,''),
    jsonb_build_object('estado_cliente_previo', COALESCE(v_p.estado_cliente,'pendiente'),
                       'origen_aceptacion','auto_cliente_de_casa'));
  RETURN jsonb_build_object('proforma_id', p_proforma_id, 'estado_cliente', 'aceptada', 'sin_cambios', false);
END;
$$;
CREATE FUNCTION public.actividad_embarque(p_embarque_id uuid) RETURNS TABLE(id text, categoria text, tipo text, fecha timestamp with time zone, usuario text, accion text, titulo text, descripcion text, monto numeric, moneda text, ref_tipo text, ref_id uuid, dedupe_key text, detalles jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_exp text;
  v_cot uuid;
  v_fin boolean;
BEGIN
  SELECT e.organization_id, e.expediente, e.cotizacion_id
    INTO v_org, v_exp, v_cot
  FROM public.embarques e
  WHERE e.id = p_embarque_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_NOT_FOUND: embarque inexistente' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (public.has_role(auth.uid(), 'super_admin'::app_role) OR public.is_org_member(v_org)) THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;
  v_fin := public.can_view_financials(auth.uid());
  RETURN QUERY
  WITH facturas_emb AS (
    SELECT f.*
    FROM public.facturas f
    JOIN public.factura_embarques fe ON fe.factura_id = f.id
    WHERE fe.embarque_id = p_embarque_id
      AND COALESCE(fe.activa, true)
      AND f.deleted_at IS NULL
  ),
  pf_emb AS (
    SELECT pf.* FROM public.proveedor_facturas pf
    WHERE pf.embarque_id = p_embarque_id AND pf.deleted_at IS NULL
  ),
  prof_emb AS (
    SELECT pr.* FROM public.proformas pr
    WHERE pr.embarque_id = p_embarque_id AND pr.deleted_at IS NULL
  ),
  gar_emb AS (
    SELECT g.id FROM public.embarque_garantias_contenedor g
    WHERE g.embarque_id = p_embarque_id AND g.deleted_at IS NULL
  ),
  feed (f_id, f_categoria, f_tipo, f_fecha, f_usuario, f_accion, f_titulo,
        f_descripcion, f_monto, f_moneda, f_ref_tipo, f_ref_id, f_dedupe, f_detalles) AS (
    SELECT ('nota-' || n.id)::text, 'operacion'::text, 'nota'::text, n.fecha,
           COALESCE(n.usuario, '')::text,
           CASE WHEN n.tipo = 'cambio_estado' THEN 'Cambio de estado' ELSE 'Nota' END::text,
           n.contenido::text, NULL::text, NULL::numeric, NULL::text,
           'embarque'::text, p_embarque_id,
           CASE WHEN n.tipo = 'cambio_estado'
                THEN 'estado|' || to_char(n.fecha, 'YYYYMMDDHH24MI') END::text,
           NULL::jsonb
    FROM public.notas_embarque n
    WHERE n.embarque_id = p_embarque_id AND n.deleted_at IS NULL
    UNION ALL
    SELECT ('ev-' || ev.id), 'operacion', 'evento', ev.fecha, COALESCE(ev.usuario, ''),
           ev.tipo::text, COALESCE(NULLIF(ev.descripcion, ''), ev.tipo::text),
           NULLIF(ev.ubicacion, ''), NULL, NULL, 'embarque', p_embarque_id,
           CASE WHEN ev.descripcion ILIKE 'Estado cambiado a%'
                THEN 'estado|' || to_char(ev.fecha, 'YYYYMMDDHH24MI') END,
           NULL
    FROM public.eventos_embarque ev
    WHERE ev.embarque_id = p_embarque_id
    UNION ALL
    SELECT ('doc-' || d.id), 'operacion', 'documento', d.created_at, '',
           'Documento', d.nombre, NULLIF(d.estado::text, ''), NULL, NULL,
           'documento', d.id, NULL, jsonb_build_object('archivo', d.archivo)
    FROM public.documentos_embarque d
    WHERE d.embarque_id = p_embarque_id AND d.deleted_at IS NULL
    UNION ALL
    SELECT ('bit-' || b.id), 'operacion', 'bitacora', b.created_at,
           COALESCE(b.usuario_email, ''), b.accion, b.accion, NULL, NULL, NULL,
           'embarque', p_embarque_id,
           CASE WHEN b.accion = 'cambiar_estado'
                THEN 'estado|' || to_char(b.created_at, 'YYYYMMDDHH24MI') END,
           b.detalles
    FROM public.bitacora_actividad b
    WHERE b.entidad_id = p_embarque_id
       OR (b.entidad_id IS NULL AND v_exp IS NOT NULL AND b.entidad_nombre = v_exp)
    UNION ALL
    SELECT ('trk-' || t.id), 'operacion', 'tracking', t.created_at,
           COALESCE(t.usuario_email, ''),
           t.accion, 'Consulta de rastreo (' || COALESCE(t.provider, 'n/d') || ')',
           NULLIF(t.mensaje, ''), NULL, NULL, 'embarque', p_embarque_id, NULL, t.detalle
    FROM public.tracking_intentos t
    WHERE t.embarque_id = p_embarque_id
    UNION ALL
    SELECT ('cot-' || c.id), 'comercial', 'cotizacion', c.created_at, '',
           'Cotización creada', 'Cotización ' || COALESCE(c.folio, ''), NULL,
           CASE WHEN v_fin THEN c.subtotal END, c.moneda::text, 'cotizacion', c.id, NULL, NULL
    FROM public.cotizaciones c
    WHERE v_cot IS NOT NULL AND c.id = v_cot
    UNION ALL
    SELECT ('cot-ac-' || c.id), 'comercial', 'cotizacion', c.fecha_aceptacion, '',
           'Cotización aceptada', 'Cotización ' || COALESCE(c.folio, ''), NULL,
           NULL, NULL, 'cotizacion', c.id, NULL, NULL
    FROM public.cotizaciones c
    WHERE v_cot IS NOT NULL AND c.id = v_cot AND c.fecha_aceptacion IS NOT NULL
    UNION ALL
    SELECT ('bitc-' || b.id), 'comercial', 'bitacora', b.created_at,
           COALESCE(b.usuario_email, ''), b.accion, 'Cotización: ' || b.accion, NULL,
           NULL, NULL, 'cotizacion', v_cot, NULL, b.detalles
    FROM public.bitacora_actividad b
    WHERE v_cot IS NOT NULL AND b.entidad_id = v_cot
    UNION ALL
    SELECT ('prof-' || pr.id), 'finanzas', 'proforma', pr.created_at, COALESCE(u.email, ''),
           'Proforma generada', 'Proforma ' || COALESCE(pr.numero, ''), NULL,
           CASE WHEN v_fin THEN pr.total_usd END, 'USD', 'proforma', pr.id, NULL, NULL
    FROM prof_emb pr LEFT JOIN auth.users u ON u.id = pr.created_by
    UNION ALL
    SELECT ('prof-env-' || pr.id), 'finanzas', 'proforma', pr.enviada_at,
           COALESCE(u.email, ''), 'Proforma enviada',
           'Proforma ' || COALESCE(pr.numero, '') || ' enviada al cliente', NULL,
           NULL, NULL, 'proforma', pr.id, NULL, NULL
    FROM prof_emb pr LEFT JOIN auth.users u ON u.id = pr.enviada_por
    WHERE pr.enviada_at IS NOT NULL
    UNION ALL
    SELECT ('prof-res-' || pr.id), 'finanzas', 'proforma',
           COALESCE(pr.aceptada_at, pr.rechazada_at), COALESCE(pr.aceptada_por, ''),
           CASE WHEN pr.aceptada_at IS NOT NULL THEN 'Proforma aceptada' ELSE 'Proforma rechazada' END,
           'Proforma ' || COALESCE(pr.numero, ''), NULLIF(pr.motivo_rechazo, ''),
           NULL, NULL, 'proforma', pr.id, NULL, NULL
    FROM prof_emb pr WHERE pr.aceptada_at IS NOT NULL OR pr.rechazada_at IS NOT NULL
    UNION ALL
    SELECT ('bitp-' || b.id), 'finanzas', 'bitacora', b.created_at,
           COALESCE(b.usuario_email, ''), b.accion, 'Proforma: ' || b.accion, NULL,
           NULL, NULL, 'proforma', b.entidad_id, NULL, b.detalles
    FROM public.bitacora_actividad b
    WHERE b.entidad_id IN (SELECT pr.id FROM prof_emb pr)
    UNION ALL
    SELECT ('fac-' || f.id), 'finanzas', 'factura', f.created_at, '',
           'Factura creada',
           'Factura ' || COALESCE(f.serie, '') || COALESCE(f.numero::text, '') || ' · ' || f.estado::text,
           NULL, CASE WHEN v_fin THEN f.total END, f.moneda::text, 'factura', f.id, NULL, NULL
    FROM facturas_emb f
    UNION ALL
    SELECT ('fac-tim-' || f.id), 'finanzas', 'factura', f.timbrado_en,
           COALESCE(u.email, ''), 'Factura timbrada',
           'Factura ' || COALESCE(f.serie, '') || COALESCE(f.numero::text, ''),
           NULLIF(f.uuid_fiscal, ''), CASE WHEN v_fin THEN f.total END, f.moneda::text,
           'factura', f.id, NULL, NULL
    FROM facturas_emb f LEFT JOIN auth.users u ON u.id = f.timbrado_por
    WHERE f.timbrado_en IS NOT NULL
    UNION ALL
    SELECT ('fac-can-' || f.id), 'finanzas', 'factura', f.cancelado_en, '',
           'Factura cancelada',
           'Factura ' || COALESCE(f.serie, '') || COALESCE(f.numero::text, ''),
           NULLIF(f.cancelacion_motivo, ''), NULL, NULL, 'factura', f.id, NULL, NULL
    FROM facturas_emb f WHERE f.cancelado_en IS NOT NULL
    UNION ALL
    SELECT ('fac-mail-' || fe2.id), 'finanzas', 'email', fe2.created_at,
           COALESCE(u.email, ''), 'Factura enviada por correo',
           COALESCE(fe2.asunto, 'Envío de factura'),
           (SELECT string_agg(x.value #>> '{}', ', ')
              FROM jsonb_array_elements(
                     CASE WHEN jsonb_typeof(fe2.destinatarios) = 'array'
                          THEN fe2.destinatarios ELSE '[]'::jsonb END) x),
           NULL, NULL, 'factura', fe2.factura_id,
           NULL, jsonb_build_object('estado', fe2.estado, 'error', fe2.error)
    FROM public.factura_envios fe2
    LEFT JOIN auth.users u ON u.id = fe2.enviado_por
    WHERE fe2.factura_id IN (SELECT f.id FROM facturas_emb f)
    UNION ALL
    SELECT ('bitf-' || b.id), 'finanzas', 'bitacora', b.created_at,
           COALESCE(b.usuario_email, ''), b.accion, 'Factura: ' || b.accion, NULL,
           NULL, NULL, 'factura', b.entidad_id, NULL, b.detalles
    FROM public.bitacora_actividad b
    WHERE b.entidad_id IN (SELECT f.id FROM facturas_emb f)
    UNION ALL
    SELECT ('pag-' || pg.id), 'finanzas', 'pago', COALESCE(pg.fecha_pago::timestamptz, pg.created_at),
           COALESCE(u.email, ''), 'Pago recibido',
           'Pago ' || COALESCE(pg.forma_pago, '') || COALESCE(' · ref ' || NULLIF(pg.referencia, ''), ''),
           NULL, CASE WHEN v_fin THEN pg.monto END, pg.moneda::text, 'factura', pg.factura_id, NULL, NULL
    FROM public.pagos_factura pg
    LEFT JOIN auth.users u ON u.id = pg.created_by
    WHERE pg.deleted_at IS NULL
      AND (pg.embarque_id = p_embarque_id OR pg.factura_id IN (SELECT f.id FROM facturas_emb f))
    UNION ALL
    SELECT ('nc-' || nc.id), 'finanzas', 'nota_credito', nc.created_at,
           COALESCE(u.email, ''), 'Nota de crédito ' || nc.estado::text,
           'NC ' || COALESCE(nc.folio, '') || ' · ' || nc.motivo::text,
           NULLIF(nc.descripcion, ''), CASE WHEN v_fin THEN nc.monto END, nc.moneda::text,
           'factura', nc.factura_id, NULL, NULL
    FROM public.factura_notas_credito nc
    LEFT JOIN auth.users u ON u.id = nc.created_by
    WHERE nc.deleted_at IS NULL AND nc.factura_id IN (SELECT f.id FROM facturas_emb f)
    UNION ALL
    SELECT ('pf-' || pf.id), 'finanzas', 'cxp', pf.created_at, COALESCE(u.email, ''),
           'Factura de proveedor capturada',
           COALESCE(pf.folio_interno, pf.folio_proveedor, 'CxP') || ' · ' || COALESCE(pf.proveedor_nombre, ''),
           NULL, CASE WHEN v_fin THEN pf.total END, pf.moneda::text, 'cxp', pf.id, NULL, NULL
    FROM pf_emb pf LEFT JOIN auth.users u ON u.id = pf.created_by
    UNION ALL
    SELECT ('pf-apr-' || pf.id), 'finanzas', 'cxp', pf.aprobada_at, COALESCE(u.email, ''),
           'Factura de proveedor ' || pf.estado_aprobacion::text,
           COALESCE(pf.folio_interno, pf.folio_proveedor, 'CxP'),
           NULLIF(pf.motivo_rechazo, ''), NULL, NULL, 'cxp', pf.id, NULL, NULL
    FROM pf_emb pf LEFT JOIN auth.users u ON u.id = pf.aprobada_por
    WHERE pf.aprobada_at IS NOT NULL
    UNION ALL
    SELECT ('bitx-' || b.id), 'finanzas', 'bitacora', b.created_at,
           COALESCE(b.usuario_email, ''), b.accion, 'CxP: ' || b.accion, NULL,
           NULL, NULL, 'cxp', b.entidad_id, NULL, b.detalles
    FROM public.bitacora_actividad b
    WHERE b.entidad_id IN (SELECT pf.id FROM pf_emb pf)
    UNION ALL
    SELECT ('pp-' || pp.id), 'finanzas', 'pago_proveedor',
           COALESCE(pp.fecha_pago::timestamptz, pp.created_at), COALESCE(u.email, ''),
           'Pago a proveedor',
           COALESCE(pp.metodo_pago, '') || COALESCE(' · ref ' || NULLIF(pp.referencia, ''), ''),
           NULL, CASE WHEN v_fin THEN pp.monto END, pp.moneda::text, 'cxp', pp.proveedor_factura_id,
           NULL, NULL
    FROM public.pagos_proveedor pp
    LEFT JOIN auth.users u ON u.id = pp.created_by
    WHERE pp.deleted_at IS NULL AND pp.proveedor_factura_id IN (SELECT pf.id FROM pf_emb pf)
    UNION ALL
    SELECT ('fe-' || fe3.id), 'finanzas', 'buzon', fe3.created_at, COALESCE(u.email, ''),
           'Invoice recibido', COALESCE(fe3.nombre_archivo, 'Archivo'), NULLIF(fe3.nota, ''),
           CASE WHEN v_fin THEN fe3.total_detectado END, fe3.moneda_detectada,
           'buzon', fe3.id, NULL, NULL
    FROM public.embarque_facturas_entrantes fe3
    LEFT JOIN auth.users u ON u.id = fe3.subido_por
    WHERE fe3.embarque_id = p_embarque_id AND fe3.deleted_at IS NULL
    UNION ALL
    SELECT ('fe-cap-' || fe4.id), 'finanzas', 'buzon', fe4.updated_at, COALESCE(u.email, ''),
           CASE WHEN fe4.estado = 'rechazada' THEN 'Invoice rechazado' ELSE 'Invoice capturado' END,
           COALESCE(fe4.nombre_archivo, 'Archivo'), NULLIF(fe4.rechazo_motivo, ''),
           NULL, NULL, 'buzon', fe4.id, NULL, NULL
    FROM public.embarque_facturas_entrantes fe4
    LEFT JOIN auth.users u ON u.id = fe4.capturado_por
    WHERE fe4.embarque_id = p_embarque_id AND fe4.deleted_at IS NULL
      AND fe4.estado <> 'por_capturar'
    UNION ALL
    SELECT ('gar-' || gh.id), 'riesgo', 'garantia', gh.changed_at, COALESCE(u.email, ''),
           'Garantía: ' || COALESCE(gh.estado_anterior, 'nueva') || ' → ' || gh.estado_nuevo,
           'Garantía de contenedor', NULLIF(gh.notas, ''),
           CASE WHEN v_fin THEN gh.monto_deposito_usd END, 'USD', 'garantia', gh.garantia_id, NULL, NULL
    FROM public.embarque_garantias_historial gh
    LEFT JOIN auth.users u ON u.id = gh.changed_by
    WHERE gh.garantia_id IN (SELECT g.id FROM gar_emb g)
    UNION ALL
    SELECT ('seg-' || s.id), 'riesgo', 'seguro', s.created_at, COALESCE(u.email, ''),
           'Seguro registrado',
           COALESCE(s.aseguradora, 'Póliza') || COALESCE(' · ' || NULLIF(s.numero_poliza, ''), ''),
           NULLIF(s.cobertura_descripcion, ''), CASE WHEN v_fin THEN s.suma_asegurada END,
           s.moneda::text, 'seguro', s.id, NULL, NULL
    FROM public.seguros_embarque s
    LEFT JOIN auth.users u ON u.id = s.created_by
    WHERE s.embarque_id = p_embarque_id AND s.deleted_at IS NULL
    UNION ALL
    SELECT ('cie-' || cl.id), 'cierre', 'cierre', cl.created_at, COALESCE(u.email, ''),
           CASE WHEN cl.accion = 'cerrar' THEN 'Embarque cerrado' ELSE 'Embarque reabierto' END,
           CASE WHEN cl.accion = 'cerrar' THEN 'Cierre financiero' ELSE 'Reapertura' END,
           NULLIF(cl.motivo, ''), NULL, NULL, 'embarque', p_embarque_id, NULL, NULL
    FROM public.cierre_embarque_log cl
    LEFT JOIN auth.users u ON u.id = cl.usuario_id
    WHERE cl.embarque_id = p_embarque_id
  )
  SELECT f_id, f_categoria, f_tipo, f_fecha, f_usuario, f_accion, f_titulo,
         f_descripcion, f_monto, f_moneda, f_ref_tipo, f_ref_id, f_dedupe, f_detalles
  FROM feed
  WHERE f_fecha IS NOT NULL
  ORDER BY f_fecha DESC;
END;
$$;
CREATE FUNCTION public.actualizar_cotizacion_costos(p_cotizacion_id uuid, p_costos jsonb, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_resp jsonb;
  c jsonb;
  v_count int := 0;
BEGIN
  v_resp := public.idempotency_claim(p_request_id, 'actualizar_cotizacion_costos');
  IF v_resp IS NOT NULL THEN RETURN v_resp; END IF;
  SELECT organization_id INTO v_org_id FROM cotizaciones WHERE id = p_cotizacion_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Cotización no encontrada'; END IF;
  PERFORM public._assert_writer_cotizacion(v_org_id);
  DELETE FROM cotizacion_costos WHERE cotizacion_id = p_cotizacion_id;
  FOR c IN SELECT * FROM jsonb_array_elements(p_costos) LOOP
    INSERT INTO cotizacion_costos (
      cotizacion_id, concepto, moneda, proveedor, cantidad,
      costo_unitario, precio_venta, unidad_medida, notas, organization_id,
      costeo_tarifa_id, costeo_tarifa_recargo_id
    ) VALUES (
      p_cotizacion_id,
      c->>'concepto',
      c->>'moneda',
      COALESCE(c->>'proveedor', ''),
      (c->>'cantidad')::numeric,
      (c->>'costo_unitario')::numeric,
      COALESCE((c->>'precio_venta')::numeric, 0),
      COALESCE(c->>'unidad_medida', ''),
      COALESCE(c->>'notas', ''),
      v_org_id,
      NULLIF(c->>'costeo_tarifa_id', '')::uuid,
      NULLIF(c->>'costeo_tarifa_recargo_id', '')::uuid
    );
    v_count := v_count + 1;
  END LOOP;
  v_resp := jsonb_build_object('cotizacion_id', p_cotizacion_id, 'count', v_count);
  PERFORM public.idempotency_store(p_request_id, v_resp);
  RETURN v_resp;
END;
$$;
CREATE FUNCTION public.actualizar_datos_entrante(p_documento_id uuid, p_proveedor_id uuid, p_monto_declarado numeric, p_moneda_declarada text, p_nota text, p_sin_costo_capturado boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid := public.current_user_org_id();
  v_doc public.embarque_facturas_entrantes%ROWTYPE;
  v_filas int;
BEGIN
  SELECT * INTO v_doc FROM public.embarque_facturas_entrantes
   WHERE id = p_documento_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'LC_NOT_FOUND: documento no encontrado'; END IF;
  IF v_doc.organization_id <> v_caller_org AND NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: documento de otra organización';
  END IF;
  IF p_proveedor_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.proveedores p
     WHERE p.id = p_proveedor_id AND p.organization_id = v_doc.organization_id
  ) THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: proveedor de otra organización';
  END IF;
  UPDATE public.embarque_facturas_entrantes
     SET proveedor_id = COALESCE(p_proveedor_id, proveedor_id),
         monto_declarado = p_monto_declarado,
         moneda_declarada = CASE
           WHEN p_monto_declarado IS NULL THEN NULL
           ELSE COALESCE(NULLIF(btrim(p_moneda_declarada), ''), 'MXN')
         END,
         nota = NULLIF(btrim(COALESCE(p_nota, '')), ''),
         sin_costo_capturado = COALESCE(p_sin_costo_capturado, false)
   WHERE id = p_documento_id
     AND deleted_at IS NULL
     AND estado = 'por_capturar';
  GET DIAGNOSTICS v_filas = ROW_COUNT;
  IF v_filas = 0 THEN
    RAISE EXCEPTION 'LC_ESTADO_INVALIDO: sólo se pueden corregir documentos por capturar';
  END IF;
END;
$$;
CREATE FUNCTION public.actualizar_embarque_completo(p_embarque_id uuid, p_embarque jsonb, p_conceptos_venta jsonb DEFAULT '[]'::jsonb, p_conceptos_costo jsonb DEFAULT '[]'::jsonb, p_request_id uuid DEFAULT NULL::uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_resp jsonb;
  cv jsonb;
  cc jsonb;
  v_incoming_venta_ids uuid[];
  v_incoming_costo_ids uuid[];
  v_new_id uuid;
  v_current_updated_at timestamptz;
  v_cliente_actual uuid;
BEGIN
  SELECT organization_id, updated_at, cliente_id
    INTO v_org_id, v_current_updated_at, v_cliente_actual
    FROM embarques
   WHERE id = p_embarque_id
   FOR UPDATE;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Embarque no encontrado'; END IF;
  PERFORM public._assert_writer(v_org_id);
  IF p_expected_updated_at IS NOT NULL
     AND v_current_updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'LC_CONFLICTO_CONCURRENCIA: otro usuario modificó este embarque. Recarga y vuelve a intentar.'
      USING ERRCODE = '40001',
            HINT = json_build_object(
              'server_updated_at', v_current_updated_at,
              'client_expected_updated_at', p_expected_updated_at
            )::text;
  END IF;
  PERFORM public._assert_relaciones_embarque(
    v_org_id,
    COALESCE(NULLIF(p_embarque->>'cliente_id','')::uuid, v_cliente_actual),
    NULLIF(p_embarque->>'cotizacion_id','')::uuid,
    p_conceptos_costo
  );
  v_resp := public.idempotency_claim(p_request_id, 'actualizar_embarque_completo');
  IF v_resp IS NOT NULL THEN RETURN v_resp; END IF;
  UPDATE embarques SET
    cliente_id = COALESCE((p_embarque->>'cliente_id')::uuid, cliente_id),
    cliente_nombre = COALESCE(p_embarque->>'cliente_nombre', cliente_nombre),
    modo = COALESCE((p_embarque->>'modo')::modo_transporte, modo),
    tipo = COALESCE((p_embarque->>'tipo')::tipo_operacion, tipo),
    incoterm = COALESCE((p_embarque->>'incoterm')::incoterm, incoterm),
    bl_master = CASE WHEN p_embarque ? 'bl_master' THEN p_embarque->>'bl_master' ELSE bl_master END,
    bl_house = CASE WHEN p_embarque ? 'bl_house' THEN p_embarque->>'bl_house' ELSE bl_house END,
    naviera = CASE WHEN p_embarque ? 'naviera' THEN p_embarque->>'naviera' ELSE naviera END,
    naviera_id = CASE WHEN p_embarque ? 'naviera_id' THEN NULLIF(p_embarque->>'naviera_id','')::uuid ELSE naviera_id END,
    puerto_origen = CASE WHEN p_embarque ? 'puerto_origen' THEN p_embarque->>'puerto_origen' ELSE puerto_origen END,
    puerto_destino = CASE WHEN p_embarque ? 'puerto_destino' THEN p_embarque->>'puerto_destino' ELSE puerto_destino END,
    aeropuerto_origen = CASE WHEN p_embarque ? 'aeropuerto_origen' THEN p_embarque->>'aeropuerto_origen' ELSE aeropuerto_origen END,
    aeropuerto_destino = CASE WHEN p_embarque ? 'aeropuerto_destino' THEN p_embarque->>'aeropuerto_destino' ELSE aeropuerto_destino END,
    ciudad_origen = CASE WHEN p_embarque ? 'ciudad_origen' THEN p_embarque->>'ciudad_origen' ELSE ciudad_origen END,
    ciudad_destino = CASE WHEN p_embarque ? 'ciudad_destino' THEN p_embarque->>'ciudad_destino' ELSE ciudad_destino END,
    aerolinea = CASE WHEN p_embarque ? 'aerolinea' THEN p_embarque->>'aerolinea' ELSE aerolinea END,
    transportista = CASE WHEN p_embarque ? 'transportista' THEN p_embarque->>'transportista' ELSE transportista END,
    agente = CASE WHEN p_embarque ? 'agente' THEN p_embarque->>'agente' ELSE agente END,
    agente_id = CASE WHEN p_embarque ? 'agente_id' THEN NULLIF(p_embarque->>'agente_id','')::uuid ELSE agente_id END,
    shipper = COALESCE(p_embarque->>'shipper', shipper),
    consignatario = COALESCE(p_embarque->>'consignatario', consignatario),
    descripcion_mercancia = COALESCE(p_embarque->>'descripcion_mercancia', descripcion_mercancia),
    tipo_carga = COALESCE(p_embarque->>'tipo_carga', tipo_carga),
    tipo_servicio = CASE WHEN p_embarque ? 'tipo_servicio' THEN (p_embarque->>'tipo_servicio')::tipo_servicio_maritimo ELSE tipo_servicio END,
    operador = COALESCE(p_embarque->>'operador', operador),
    contenedor = CASE WHEN p_embarque ? 'contenedor' THEN p_embarque->>'contenedor' ELSE contenedor END,
    tipo_contenedor = CASE WHEN p_embarque ? 'tipo_contenedor' THEN p_embarque->>'tipo_contenedor' ELSE tipo_contenedor END,
    peso_kg = COALESCE((p_embarque->>'peso_kg')::numeric, peso_kg),
    volumen_m3 = COALESCE((p_embarque->>'volumen_m3')::numeric, volumen_m3),
    piezas = COALESCE((p_embarque->>'piezas')::int, piezas),
    mawb = CASE WHEN p_embarque ? 'mawb' THEN p_embarque->>'mawb' ELSE mawb END,
    hawb = CASE WHEN p_embarque ? 'hawb' THEN p_embarque->>'hawb' ELSE hawb END,
    carta_porte = CASE WHEN p_embarque ? 'carta_porte' THEN p_embarque->>'carta_porte' ELSE carta_porte END,
    etd = CASE WHEN p_embarque ? 'etd' THEN (p_embarque->>'etd')::date ELSE etd END,
    eta = CASE WHEN p_embarque ? 'eta' THEN (p_embarque->>'eta')::date ELSE eta END,
    tipo_cambio_usd = COALESCE(NULLIF(NULLIF(p_embarque->>'tipo_cambio_usd','')::numeric, 0), tipo_cambio_usd),
    tipo_cambio_eur = COALESCE(NULLIF(NULLIF(p_embarque->>'tipo_cambio_eur','')::numeric, 0), tipo_cambio_eur),
    msds_archivo = CASE WHEN p_embarque ? 'msds_archivo' THEN p_embarque->>'msds_archivo' ELSE msds_archivo END,
    updated_at = now()
  WHERE id = p_embarque_id;
  v_incoming_venta_ids := ARRAY(
    SELECT (elem->>'id')::uuid
      FROM jsonb_array_elements(p_conceptos_venta) elem
     WHERE elem ? 'id' AND elem->>'id' IS NOT NULL AND elem->>'id' <> ''
  );
  FOR cv IN SELECT * FROM jsonb_array_elements(p_conceptos_venta) LOOP
    IF cv ? 'id' AND cv->>'id' IS NOT NULL AND cv->>'id' <> '' THEN
      UPDATE conceptos_venta SET
        descripcion = COALESCE(cv->>'descripcion', descripcion),
        cantidad = COALESCE((cv->>'cantidad')::numeric, cantidad),
        precio_unitario = COALESCE((cv->>'precio_unitario')::numeric, precio_unitario),
        moneda = COALESCE((cv->>'moneda')::moneda, moneda),
        total = COALESCE((cv->>'total')::numeric, total)
      WHERE id = (cv->>'id')::uuid
        AND embarque_id = p_embarque_id
        AND estado_facturacion IN ('pendiente', 'en_proforma');
    ELSE
      INSERT INTO conceptos_venta (
        embarque_id, descripcion, cantidad, precio_unitario, moneda, total, contenedor_id, organization_id
      ) VALUES (
        p_embarque_id,
        cv->>'descripcion',
        COALESCE((cv->>'cantidad')::numeric, 1),
        COALESCE((cv->>'precio_unitario')::numeric, 0),
        COALESCE((cv->>'moneda')::moneda, 'MXN'::moneda),
        COALESCE((cv->>'total')::numeric, 0),
        NULLIF(cv->>'contenedor_id','')::uuid,
        v_org_id
      )
      RETURNING id INTO v_new_id;
      v_incoming_venta_ids := array_append(v_incoming_venta_ids, v_new_id);
    END IF;
  END LOOP;
  UPDATE conceptos_venta
     SET deleted_at = now()
   WHERE embarque_id = p_embarque_id
     AND deleted_at IS NULL
     AND estado_facturacion = 'pendiente'
     AND NOT (id = ANY(v_incoming_venta_ids));
  v_incoming_costo_ids := ARRAY(
    SELECT (elem->>'id')::uuid
      FROM jsonb_array_elements(p_conceptos_costo) elem
     WHERE elem ? 'id' AND elem->>'id' IS NOT NULL AND elem->>'id' <> ''
  );
  FOR cc IN SELECT * FROM jsonb_array_elements(p_conceptos_costo) LOOP
    IF cc ? 'id' AND cc->>'id' IS NOT NULL AND cc->>'id' <> '' THEN
      UPDATE conceptos_costo SET
        concepto = COALESCE(cc->>'concepto', concepto),
        proveedor_nombre = CASE
          WHEN cc ? 'proveedor_nombre' AND COALESCE(btrim(cc->>'proveedor_nombre'), '') <> ''
            THEN cc->>'proveedor_nombre'
          ELSE proveedor_nombre
        END,
        proveedor_id = CASE
          WHEN cc ? 'proveedor_id' AND cc->>'proveedor_id' IS NOT NULL AND cc->>'proveedor_id' <> ''
            THEN (cc->>'proveedor_id')::uuid
          ELSE proveedor_id
        END,
        moneda = COALESCE((cc->>'moneda')::moneda, moneda),
        monto = COALESCE((cc->>'monto')::numeric, monto)
      WHERE id = (cc->>'id')::uuid
        AND embarque_id = p_embarque_id
        AND COALESCE(estado_liquidacion, 'Pendiente') <> 'Pagado';
    ELSE
      INSERT INTO conceptos_costo (
        embarque_id, concepto, proveedor_id, proveedor_nombre, moneda, monto, contenedor_id, organization_id
      ) VALUES (
        p_embarque_id,
        cc->>'concepto',
        NULLIF(cc->>'proveedor_id','')::uuid,
        COALESCE(cc->>'proveedor_nombre',''),
        COALESCE((cc->>'moneda')::moneda, 'MXN'::moneda),
        COALESCE((cc->>'monto')::numeric, 0),
        NULLIF(cc->>'contenedor_id','')::uuid,
        v_org_id
      )
      RETURNING id INTO v_new_id;
      v_incoming_costo_ids := array_append(v_incoming_costo_ids, v_new_id);
    END IF;
  END LOOP;
  UPDATE conceptos_costo
     SET deleted_at = now()
   WHERE embarque_id = p_embarque_id
     AND deleted_at IS NULL
     AND COALESCE(estado_liquidacion, 'Pendiente') <> 'Pagado'
     AND NOT EXISTS (
       SELECT 1 FROM public.proveedor_facturas_conceptos pfc
        WHERE pfc.concepto_costo_id = conceptos_costo.id
     )
     AND NOT (id = ANY(v_incoming_costo_ids));
  v_resp := jsonb_build_object('ok', true, 'embarque_id', p_embarque_id);
  PERFORM public.idempotency_store(p_request_id, v_resp);
  RETURN v_resp;
END;
$$;
CREATE FUNCTION public.actualizar_estado_cliente_proforma(p_proforma_id uuid, p_respuesta text, p_motivo text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_proforma      public.proformas%ROWTYPE;
  v_user_email    text;
  v_now           timestamptz := now();
  v_motivo        text;
  v_is_authorized boolean;
  v_liberados     integer := 0;
BEGIN
  IF p_respuesta NOT IN ('aceptada','rechazada','pendiente') THEN
    RAISE EXCEPTION 'Respuesta inválida.';
  END IF;
  SELECT * INTO v_proforma FROM public.proformas WHERE id = p_proforma_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Proforma no encontrada.'; END IF;
  IF v_proforma.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Esta proforma está en la papelera; restáurala antes de cambiar su estado.';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members om
     WHERE om.user_id = auth.uid()
       AND om.organization_id = v_proforma.organization_id
       AND om.role IN (
         'admin'::app_role,
         'admin_org'::app_role,
         'gerente_operaciones'::app_role,
         'gerente_comercial'::app_role
       )
  ) OR public.has_role(auth.uid(), 'super_admin'::app_role) INTO v_is_authorized;
  IF NOT v_is_authorized THEN
    RAISE EXCEPTION 'No tienes permisos para cambiar el estado del cliente en esta proforma.';
  END IF;
  v_motivo := NULLIF(trim(p_motivo), '');
  IF p_respuesta = 'rechazada' AND v_motivo IS NULL THEN
    RAISE EXCEPTION 'Es obligatorio indicar el motivo de rechazo.';
  END IF;
  IF p_respuesta = 'rechazada' AND v_proforma.estado_proforma = 'facturada' THEN
    RAISE EXCEPTION 'No puedes rechazar una proforma que ya fue facturada.';
  END IF;
  SELECT email INTO v_user_email FROM auth.users WHERE id = auth.uid();
  UPDATE public.proformas
     SET estado_cliente = p_respuesta,
         aceptada_at    = CASE WHEN p_respuesta='aceptada' THEN v_now
                               WHEN p_respuesta='pendiente' THEN NULL
                               ELSE aceptada_at END,
         rechazada_at   = CASE WHEN p_respuesta='rechazada' THEN v_now
                               WHEN p_respuesta='pendiente' THEN NULL
                               ELSE rechazada_at END,
         aceptada_por   = CASE WHEN p_respuesta='aceptada'
                                 THEN 'manual:' || COALESCE(v_user_email, auth.uid()::text)
                               WHEN p_respuesta='rechazada'
                                 THEN 'manual:' || COALESCE(v_user_email, auth.uid()::text)
                               WHEN p_respuesta='pendiente' THEN NULL
                               ELSE aceptada_por END,
         motivo_rechazo = CASE WHEN p_respuesta='rechazada' THEN v_motivo
                               WHEN p_respuesta='pendiente' THEN NULL
                               ELSE motivo_rechazo END,
         updated_at     = v_now
   WHERE id = p_proforma_id;
  IF p_respuesta = 'rechazada' AND v_proforma.estado_cliente <> 'rechazada' THEN
    v_liberados := public.liberar_conceptos_de_proforma(p_proforma_id);
  END IF;
  INSERT INTO public.bitacora_actividad (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
  VALUES (v_proforma.organization_id, auth.uid(), COALESCE(v_user_email,''),
          'proforma_estado_cliente_manual', 'proformas', p_proforma_id, COALESCE(v_proforma.numero,''),
          jsonb_build_object('proforma_id', p_proforma_id,
                             'estado_anterior', v_proforma.estado_cliente,
                             'estado_nuevo', p_respuesta,
                             'motivo', v_motivo,
                             'conceptos_liberados', v_liberados,
                             'origen','manual_interno'));
  RETURN jsonb_build_object(
    'id', p_proforma_id,
    'estado_cliente', p_respuesta,
    'at', v_now,
    'conceptos_liberados', v_liberados
  );
END;
$$;
CREATE FUNCTION public.actualizar_tarifa_con_recargos_rpc(p_id uuid, p_tarifa jsonb, p_recargos jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.costeo_tarifas WHERE id = p_id
  FOR UPDATE;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_TARIFA_NO_ENCONTRADA';
  END IF;
  IF auth.uid() IS NOT NULL AND NOT public.is_org_member(v_org) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  UPDATE public.costeo_tarifas SET
    -- Campos opcionales: solo se tocan si la llave viene en el payload;
    -- null/'' limpia el valor (RG16).
    agente_id = CASE WHEN p_tarifa ? 'agente_id'
      THEN NULLIF(p_tarifa->>'agente_id', '')::uuid ELSE agente_id END,
    naviera_id = CASE WHEN p_tarifa ? 'naviera_id'
      THEN NULLIF(p_tarifa->>'naviera_id', '')::uuid ELSE naviera_id END,
    ruta_id = CASE WHEN p_tarifa ? 'ruta_id'
      THEN NULLIF(p_tarifa->>'ruta_id', '')::uuid ELSE ruta_id END,
    tipo_contenedor_id = CASE WHEN p_tarifa ? 'tipo_contenedor_id'
      THEN NULLIF(p_tarifa->>'tipo_contenedor_id', '')::uuid ELSE tipo_contenedor_id END,
    flete_base = CASE WHEN p_tarifa ? 'flete_base'
      THEN NULLIF(p_tarifa->>'flete_base', '')::numeric ELSE flete_base END,
    dias_libres_demoras = CASE WHEN p_tarifa ? 'dias_libres_demoras'
      THEN NULLIF(p_tarifa->>'dias_libres_demoras', '')::integer ELSE dias_libres_demoras END,
    -- Campos NOT NULL: nunca se anulan en una actualización parcial.
    vigente_desde = COALESCE(NULLIF(p_tarifa->>'vigente_desde', '')::date, vigente_desde),
    vigente_hasta = COALESCE(NULLIF(p_tarifa->>'vigente_hasta', '')::date, vigente_hasta),
    -- Campos opcionales (patrón original).
    transit_time_dias = CASE WHEN p_tarifa ? 'transit_time_dias'
      THEN NULLIF(p_tarifa->>'transit_time_dias', '')::integer ELSE transit_time_dias END,
    notas = CASE WHEN p_tarifa ? 'notas'
      THEN NULLIF(p_tarifa->>'notas', '') ELSE notas END,
    moneda = 'USD',
    updated_at = now()
  WHERE id = p_id;
  DELETE FROM public.costeo_tarifa_recargos WHERE tarifa_id = p_id;
  INSERT INTO public.costeo_tarifa_recargos (
    tarifa_id, organization_id, concepto, lado, monto, moneda, incluido_en_total
  )
  SELECT
    p_id,
    v_org,
    btrim(r->>'concepto'),
    COALESCE(NULLIF(r->>'lado', ''), 'origen'),
    (r->>'monto')::numeric,
    'USD',
    COALESCE((r->>'incluido_en_total')::boolean, true)
  FROM jsonb_array_elements(COALESCE(p_recargos, '[]'::jsonb)) AS r
  WHERE NULLIF(btrim(COALESCE(r->>'concepto', '')), '') IS NOT NULL
    AND COALESCE((r->>'monto')::numeric, 0) > 0;
END;
$$;
CREATE FUNCTION public.actualizar_tc_embarque_dof(_embarque_id uuid, _fecha date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_estado text;
  v_usd_ant numeric; v_eur_ant numeric;
  v_tc RECORD;
BEGIN
  SELECT organization_id, estado::text, tipo_cambio_usd, tipo_cambio_eur
    INTO v_org, v_estado, v_usd_ant, v_eur_ant
  FROM public.embarques WHERE id = _embarque_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Embarque no encontrado' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public._assert_writer(v_org);
  IF v_estado IN ('Cerrado','Cancelado') THEN
    RAISE EXCEPTION 'El embarque está %: el tipo de cambio ya no puede modificarse.', lower(v_estado)
      USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_tc FROM public.tc_dof_vigente(_fecha);
  IF v_tc.usd_mxn IS NULL OR v_tc.usd_mxn <= 0 THEN
    RAISE EXCEPTION 'No hay tipo de cambio DOF publicado para el % o antes.', _fecha
      USING ERRCODE = 'P0002';
  END IF;
  UPDATE public.embarques
     SET tipo_cambio_usd = v_tc.usd_mxn,
         tipo_cambio_eur = COALESCE(NULLIF(v_tc.eur_mxn, 0), tipo_cambio_eur),
         updated_at = now()
   WHERE id = _embarque_id;
  RETURN jsonb_build_object(
    'embarque_id', _embarque_id,
    'fecha_dof', v_tc.fecha,
    'usd_anterior', v_usd_ant,
    'usd_nuevo', v_tc.usd_mxn,
    'eur_anterior', v_eur_ant,
    'eur_nuevo', COALESCE(NULLIF(v_tc.eur_mxn, 0), v_eur_ant)
  );
END;
$$;
CREATE FUNCTION public.adjuntar_xml_entrante_verificado(p_documento_id uuid, p_actor uuid, p_xml_path text, p_xml_nombre text, p_xml_hash text, p_uuid_fiscal text DEFAULT NULL::text, p_rfc_emisor text DEFAULT NULL::text, p_folio_serie text DEFAULT NULL::text, p_fecha_emision date DEFAULT NULL::date, p_total_detectado numeric DEFAULT NULL::numeric, p_moneda_detectada text DEFAULT NULL::text, p_subtotal_detectado numeric DEFAULT NULL::numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org uuid;
  v_rol public.app_role;
  c_permitidos public.app_role[] := ARRAY[
    'operador', 'coordinador_logistico', 'gerente_operaciones',
    'contador', 'auxiliar_contable', 'admin', 'admin_org', 'super_admin'
  ]::public.app_role[];
BEGIN
  IF p_actor IS NULL THEN
    RAISE EXCEPTION 'LC_NO_AUTORIZADO: actor requerido';
  END IF;
  SELECT organization_id INTO v_org
    FROM public.embarque_facturas_entrantes
   WHERE id = p_documento_id
     AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_ESTADO_INVALIDO: el documento no existe o fue eliminado';
  END IF;
  IF NOT public.has_role(p_actor, 'super_admin'::public.app_role)
     AND NOT EXISTS (
       SELECT 1 FROM public.organization_members
        WHERE user_id = p_actor AND organization_id = v_org
     ) THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: el usuario no pertenece a la organización del documento';
  END IF;
  v_rol := public.rol_efectivo(p_actor, v_org);
  IF NOT (v_rol = ANY (c_permitidos)
          OR public.has_role(p_actor, 'operador'::public.app_role)
          OR public.has_role(p_actor, 'coordinador_logistico'::public.app_role)
          OR public.has_role(p_actor, 'gerente_operaciones'::public.app_role)
          OR public.has_role(p_actor, 'contador'::public.app_role)
          OR public.has_role(p_actor, 'auxiliar_contable'::public.app_role)
          OR public.has_role(p_actor, 'admin'::public.app_role)
          OR public.has_role(p_actor, 'admin_org'::public.app_role)
          OR public.has_role(p_actor, 'super_admin'::public.app_role)) THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: sin permiso para adjuntar XML al buzón'
      USING ERRCODE = '42501';
  END IF;
  IF p_uuid_fiscal IS NOT NULL
     AND p_uuid_fiscal !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'LC_XML_UUID_INVALIDO: el UUID fiscal no tiene formato UUID válido'
      USING ERRCODE = '23514';
  END IF;
  IF p_total_detectado IS NOT NULL AND p_total_detectado <= 0 THEN
    RAISE EXCEPTION 'LC_XML_TOTAL_INVALIDO: el total detectado debe ser mayor a cero'
      USING ERRCODE = '23514';
  END IF;
  IF p_subtotal_detectado IS NOT NULL AND p_subtotal_detectado < 0 THEN
    RAISE EXCEPTION 'LC_XML_SUBTOTAL_INVALIDO: el subtotal detectado no puede ser negativo'
      USING ERRCODE = '23514';
  END IF;
  PERFORM set_config('app.entrante_xml_verificado', 'on', true);
  UPDATE public.embarque_facturas_entrantes
     SET xml_path = p_xml_path,
         xml_nombre = p_xml_nombre,
         xml_hash = p_xml_hash,
         uuid_fiscal = p_uuid_fiscal,
         rfc_emisor = p_rfc_emisor,
         folio_serie = p_folio_serie,
         fecha_emision = p_fecha_emision,
         total_detectado = p_total_detectado,
         subtotal_detectado = p_subtotal_detectado,
         moneda_detectada = p_moneda_detectada,
         metadatos_verificados = true
   WHERE id = p_documento_id
     AND organization_id = v_org
     AND estado = 'por_capturar'
     AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_ESTADO_INVALIDO: el documento no existe, ya fue capturado o pertenece a otra organización';
  END IF;
END;
$_$;
CREATE FUNCTION public.adjuntar_xml_factura_entrante(p_documento_id uuid, p_xml_path text, p_xml_nombre text, p_xml_hash text, p_uuid_fiscal text DEFAULT NULL::text, p_rfc_emisor text DEFAULT NULL::text, p_folio_serie text DEFAULT NULL::text, p_fecha_emision date DEFAULT NULL::date, p_total_detectado numeric DEFAULT NULL::numeric, p_moneda_detectada text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org uuid := public.org_scope();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'LC_NO_AUTORIZADO: sesión requerida';
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_SIN_ORG: no hay organización activa';
  END IF;
  IF NOT (public.has_role(auth.uid(), 'operador')
          OR public.has_role(auth.uid(), 'coordinador_logistico')
          OR public.has_role(auth.uid(), 'gerente_operaciones')
          OR public.has_role(auth.uid(), 'contador')
          OR public.has_role(auth.uid(), 'auxiliar_contable')
          OR public.has_role(auth.uid(), 'admin')
          OR public.has_role(auth.uid(), 'admin_org')
          OR public.has_role(auth.uid(), 'super_admin')) THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: sin permiso para adjuntar XML al buzón';
  END IF;
  -- BUG-18: los metadatos del CFDI llegan parseados desde el cliente y no se
  -- pueden recomputar en SQL puro (el XML vive en Storage; la referencia del
  -- parseo es la edge function `parse-cfdi-xml`). Validaciones mínimas
  -- server-side: formato del UUID fiscal y total positivo.
  -- TODO(BUG-18): validación fuerte — descargar el XML de Storage y re-parsear
  -- server-side (edge `parse-cfdi-xml` o pg_net + http) comparando UUID, RFC
  -- emisor y total contra lo declarado por el cliente antes de aceptarlos.
  IF p_uuid_fiscal IS NOT NULL
     AND p_uuid_fiscal !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'LC_XML_UUID_INVALIDO: el UUID fiscal no tiene formato UUID válido'
      USING ERRCODE = '23514';
  END IF;
  IF p_total_detectado IS NOT NULL AND p_total_detectado <= 0 THEN
    RAISE EXCEPTION 'LC_XML_TOTAL_INVALIDO: el total detectado debe ser mayor a cero'
      USING ERRCODE = '23514';
  END IF;
  -- Check-then-act cerrado: rol, organización y estado dentro del UPDATE.
  UPDATE public.embarque_facturas_entrantes
     SET xml_path = p_xml_path,
         xml_nombre = p_xml_nombre,
         xml_hash = p_xml_hash,
         uuid_fiscal = p_uuid_fiscal,
         rfc_emisor = p_rfc_emisor,
         folio_serie = p_folio_serie,
         fecha_emision = p_fecha_emision,
         total_detectado = p_total_detectado,
         moneda_detectada = p_moneda_detectada
   WHERE id = p_documento_id
     AND organization_id = v_org
     AND estado = 'por_capturar'
     AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_ESTADO_INVALIDO: el documento no existe, ya fue capturado o pertenece a otra organización';
  END IF;
END;
$_$;
CREATE FUNCTION public.agente_aprobar_tarifa(_tarifa_id uuid, _estado text, _motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_agente_id uuid;
  v_ruta_id uuid;
  v_agente_user uuid;
  v_ruta_txt text;
BEGIN
  IF _estado NOT IN ('vigente','rechazada','borrador') THEN
    RAISE EXCEPTION 'estado inválido: %', _estado;
  END IF;
  SELECT organization_id, agente_id, ruta_id
    INTO v_org, v_agente_id, v_ruta_id
    FROM public.costeo_tarifas WHERE id = _tarifa_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'tarifa no encontrada';
  END IF;
  IF NOT (
    public.has_role(auth.uid(), 'super_admin')
    OR EXISTS (SELECT 1 FROM public.organization_members om
      WHERE om.user_id = auth.uid()
        AND om.organization_id = v_org
        AND om.role IN ('admin','admin_org','gerente_operaciones','coordinador_logistico','ejecutivo_pricing'))
  ) THEN
    RAISE EXCEPTION 'no autorizado';
  END IF;
  IF _estado = 'rechazada' AND (coalesce(btrim(_motivo), '') = '' OR length(btrim(_motivo)) < 5) THEN
    RAISE EXCEPTION 'el motivo de rechazo es obligatorio (mínimo 5 caracteres)';
  END IF;
  IF _estado = 'vigente' THEN
    UPDATE public.costeo_tarifas
       SET estado_aprobacion = 'vigente',
           motivo_rechazo = NULL,
           aprobada_por = auth.uid(),
           aprobada_en = now(),
           updated_at = now()
     WHERE id = _tarifa_id;
  ELSIF _estado = 'rechazada' THEN
    UPDATE public.costeo_tarifas
       SET estado_aprobacion = 'rechazada',
           motivo_rechazo = btrim(_motivo),
           updated_at = now()
     WHERE id = _tarifa_id;
  ELSE
    UPDATE public.costeo_tarifas
       SET estado_aprobacion = 'borrador',
           motivo_rechazo = NULL,
           updated_at = now()
     WHERE id = _tarifa_id;
  END IF;
  SELECT user_id INTO v_agente_user
    FROM public.agente_users
   WHERE agente_id = v_agente_id
   ORDER BY created_at ASC, id ASC
   LIMIT 1;
  IF v_agente_user IS NOT NULL AND _estado IN ('vigente','rechazada') THEN
    SELECT (po.name || ' → ' || pd.name)
      INTO v_ruta_txt
      FROM public.costeo_rutas r
      JOIN public.puertos po ON po.id = r.puerto_origen_id
      JOIN public.puertos pd ON pd.id = r.puerto_destino_id
     WHERE r.id = v_ruta_id;
    -- B-066: la columna real es usuario_id (antes user_id → 42703).
    INSERT INTO public.notificaciones_internas (
      organization_id, usuario_id, tipo, titulo, mensaje, leida
    ) VALUES (
      v_org, v_agente_user,
      CASE WHEN _estado = 'vigente' THEN 'tarifa_aprobada' ELSE 'tarifa_rechazada' END,
      CASE WHEN _estado = 'vigente' THEN 'Tarifa aprobada' ELSE 'Tarifa rechazada' END,
      CASE WHEN _estado = 'vigente'
           THEN 'Tu tarifa ' || coalesce(v_ruta_txt,'') || ' fue aprobada y ya está vigente.'
           ELSE 'Tu tarifa ' || coalesce(v_ruta_txt,'') || ' fue rechazada. Motivo: ' || btrim(_motivo)
      END,
      false
    );
  END IF;
END;
$$;
CREATE FUNCTION public.alertas_sistema_pending_count() RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::INTEGER
  FROM public.alertas_sistema
  WHERE acknowledged_at IS NULL;
$$;
CREATE TABLE public.anticipos_aplicaciones (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    anticipo_id uuid NOT NULL,
    proveedor_factura_id uuid NOT NULL,
    pago_proveedor_id uuid NOT NULL,
    monto_aplicado numeric(18,4) NOT NULL,
    moneda_aplicada public.moneda NOT NULL,
    fecha_aplicacion date DEFAULT CURRENT_DATE NOT NULL,
    created_by uuid,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT anticipos_aplicaciones_monto_aplicado_check CHECK ((monto_aplicado > (0)::numeric))
);
ALTER TABLE ONLY public.anticipos_aplicaciones FORCE ROW LEVEL SECURITY;
CREATE FUNCTION public.aplicar_anticipo_a_factura(p_anticipo_id uuid, p_factura_id uuid, p_monto numeric, p_fecha_aplicacion date DEFAULT CURRENT_DATE, p_request_id uuid DEFAULT NULL::uuid) RETURNS public.anticipos_aplicaciones
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ant public.anticipos_proveedor;
  v_fact public.proveedor_facturas;
  v_pago public.pagos_proveedor;
  v_ap public.anticipos_aplicaciones;
  v_uid uuid := auth.uid();
  v_email text;
  v_monto_convertido numeric(18,4);
  v_monto_historico numeric(18,4);
  v_tc_aplicacion numeric;
  v_autorizado boolean;
  v_cached jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  v_cached := public.idempotency_claim(p_request_id, 'aplicar_anticipo_a_factura');
  IF v_cached IS NOT NULL THEN
    IF COALESCE((v_cached->>'__idempotency_pending')::boolean, false) THEN
      RAISE EXCEPTION 'LC_ANTICIPO_EN_PROCESO: Esta aplicación de anticipo ya está en proceso; espera unos segundos y verifica antes de reintentar.'
        USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_ap FROM public.anticipos_aplicaciones
     WHERE id = (v_cached->>'aplicacion_id')::uuid;
    IF v_ap.id IS NOT NULL THEN
      RETURN v_ap;
    END IF;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid
      AND ur.role::text = ANY (ARRAY['admin','admin_org','super_admin','contador','tesorero'])
  ) INTO v_autorizado;
  IF NOT v_autorizado THEN
    RAISE EXCEPTION 'LC_ANTICIPO_SIN_ROL: Sólo administradores, contabilidad o tesorería pueden aplicar anticipos.'
      USING ERRCODE = '42501';
  END IF;
  IF p_monto IS NULL OR p_monto <= 0 THEN
    RAISE EXCEPTION 'LC_ANTICIPO_MONTO_INVALIDO: El monto a aplicar debe ser mayor a cero.';
  END IF;
  SELECT * INTO v_ant FROM public.anticipos_proveedor WHERE id = p_anticipo_id FOR UPDATE;
  IF v_ant.id IS NULL OR v_ant.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'LC_ANTICIPO_NO_EXISTE: El anticipo no existe.';
  END IF;
  IF v_ant.organization_id IS DISTINCT FROM public.current_user_org_id()
     AND NOT public.has_role(v_uid, 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_ANTICIPO_OTRA_ORG: El anticipo pertenece a otra organización.'
      USING ERRCODE = '42501';
  END IF;
  IF v_ant.estado = 'cancelado' THEN
    RAISE EXCEPTION 'LC_ANTICIPO_YA_CANCELADO: El anticipo está cancelado.';
  END IF;
  IF v_ant.saldo_disponible + 0.01 < p_monto THEN
    RAISE EXCEPTION 'LC_ANTICIPO_SIN_SALDO: Saldo disponible (%.4f) insuficiente para aplicar %.4f.',
      v_ant.saldo_disponible, p_monto;
  END IF;
  SELECT * INTO v_fact FROM public.proveedor_facturas WHERE id = p_factura_id AND deleted_at IS NULL;
  IF v_fact.id IS NULL THEN
    RAISE EXCEPTION 'LC_ANTICIPO_FACTURA_INVALIDA: La factura no existe.';
  END IF;
  IF v_fact.estado_aprobacion <> 'aprobada' THEN
    RAISE EXCEPTION 'LC_ANTICIPO_FACTURA_INVALIDA: La factura debe estar aprobada antes de aplicar un anticipo.';
  END IF;
  IF v_fact.estado = 'Cancelada'::public.estado_proveedor_factura THEN
    RAISE EXCEPTION 'LC_ANTICIPO_FACTURA_NO_VIVA: La factura está Cancelada y no admite anticipos.'
      USING ERRCODE = '23514';
  END IF;
  IF v_fact.organization_id <> v_ant.organization_id THEN
    RAISE EXCEPTION 'LC_ANTICIPO_ORG_MISMATCH: Anticipo y factura pertenecen a organizaciones distintas.';
  END IF;
  IF v_fact.proveedor_id IS DISTINCT FROM v_ant.proveedor_id THEN
    RAISE EXCEPTION 'LC_ANTICIPO_PROVEEDOR_MISMATCH: Anticipo y factura pertenecen a proveedores distintos.';
  END IF;
  IF v_ant.moneda = v_fact.moneda THEN
    v_monto_convertido := p_monto;
    v_monto_historico := p_monto;
  ELSE
    v_monto_convertido := public.convertir_monto_dof(
      p_monto, v_ant.moneda::text, v_fact.moneda::text, p_fecha_aplicacion);
    BEGIN
      v_monto_historico := public.convertir_monto_pago_a_factura(
        p_monto, v_ant.moneda, v_ant.tipo_cambio_usd, v_fact.moneda, v_fact.tipo_cambio_usd);
    EXCEPTION WHEN OTHERS THEN
      v_monto_historico := NULL;
    END;
  END IF;
  -- F3: el anticipo MXN no tiene tipo_cambio_usd; si la factura está en otra
  -- moneda el pago debe llevar la paridad DOF del día de la aplicación.
  v_tc_aplicacion := CASE
    WHEN v_ant.moneda = v_fact.moneda THEN v_ant.tipo_cambio_usd
    WHEN v_ant.moneda = 'MXN'::public.moneda THEN
      COALESCE(public.tc_dof_moneda(p_fecha_aplicacion, v_fact.moneda::text), v_ant.tipo_cambio_usd)
    ELSE COALESCE(public.tc_dof_moneda(p_fecha_aplicacion, v_ant.moneda::text), v_ant.tipo_cambio_usd)
  END;
  INSERT INTO public.pagos_proveedor
    (organization_id, proveedor_factura_id, fecha_pago, monto, moneda,
     tipo_cambio_usd, metodo_pago, referencia, cuenta_bancaria_id, notas,
     created_by, es_anticipo_aplicado)
  VALUES
    (v_ant.organization_id, p_factura_id, p_fecha_aplicacion, p_monto, v_ant.moneda,
     v_tc_aplicacion,
     COALESCE(NULLIF(TRIM(v_ant.metodo_pago), ''), 'Transferencia'),
     COALESCE(v_ant.referencia,'') || ' (anticipo ' || v_ant.id::text || ')',
     v_ant.cuenta_bancaria_id, 'Aplicación de anticipo ' || v_ant.id::text,
     v_uid, true)
  RETURNING * INTO v_pago;
  INSERT INTO public.anticipos_aplicaciones
    (organization_id, anticipo_id, proveedor_factura_id, pago_proveedor_id,
     monto_aplicado, moneda_aplicada, fecha_aplicacion, created_by)
  VALUES
    (v_ant.organization_id, p_anticipo_id, p_factura_id, v_pago.id,
     p_monto, v_ant.moneda, p_fecha_aplicacion, v_uid)
  RETURNING * INTO v_ap;
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (v_ant.organization_id, v_uid, COALESCE(v_email,''), 'aplicar_anticipo_a_factura', 'cxp',
            v_ap.id, 'Aplicación ' || v_ap.id::text,
            jsonb_build_object('anticipo_id', p_anticipo_id, 'factura_id', p_factura_id,
                               'monto', p_monto, 'moneda', v_ant.moneda,
                               'monto_convertido', v_monto_convertido,
                               'tc_aplicacion_dof', v_tc_aplicacion,
                               'monto_tc_historico', v_monto_historico,
                               'diferencial_cambiario',
                                 CASE WHEN v_monto_historico IS NULL THEN NULL
                                      ELSE round(v_monto_convertido - v_monto_historico, 4) END,
                               'pago_id', v_pago.id));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en aplicar_anticipo_a_factura: % %', SQLSTATE, SQLERRM;
  END;
  PERFORM public.idempotency_store(p_request_id,
    jsonb_build_object('aplicacion_id', v_ap.id, 'pago_id', v_pago.id));
  RETURN v_ap;
END;
$$;
CREATE FUNCTION public.aplicar_plantilla_cotizacion(_plantilla_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.cotizacion_plantillas%ROWTYPE;
BEGIN
  SELECT * INTO _row
  FROM public.cotizacion_plantillas
  WHERE id = _plantilla_id AND deleted_at IS NULL;
  IF _row.id IS NULL THEN
    RAISE EXCEPTION 'Plantilla no encontrada';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members m
    WHERE m.organization_id = _row.organization_id AND m.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Sin acceso a esta plantilla';
  END IF;
  IF _row.visibilidad = 'yo' AND _row.usuario_id <> auth.uid() THEN
    RAISE EXCEPTION 'Sin acceso a esta plantilla';
  END IF;
  UPDATE public.cotizacion_plantillas
     SET veces_usada = veces_usada + 1,
         ultima_uso_at = now()
   WHERE id = _plantilla_id;
  RETURN _row.payload;
END;
$$;
CREATE FUNCTION public.app_logs_health_summary(p_hours integer DEFAULT 24) RETURNS TABLE(fn text, total bigint, errors bigint, warns bigint, p50_ms numeric, p95_ms numeric, last_ts timestamp with time zone, last_error_ts timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    l.fn,
    count(*)::bigint AS total,
    count(*) FILTER (WHERE l.level = 'error')::bigint AS errors,
    count(*) FILTER (WHERE l.level = 'warn')::bigint AS warns,
    percentile_cont(0.5) WITHIN GROUP (ORDER BY l.latency_ms)::numeric AS p50_ms,
    percentile_cont(0.95) WITHIN GROUP (ORDER BY l.latency_ms)::numeric AS p95_ms,
    max(l.ts) AS last_ts,
    max(l.ts) FILTER (WHERE l.level = 'error') AS last_error_ts
  FROM public.app_logs l
  WHERE l.ts >= now() - make_interval(hours => greatest(p_hours, 1))
  GROUP BY l.fn
  ORDER BY errors DESC, total DESC;
$$;
CREATE FUNCTION public.app_logs_health_timeline(p_hours integer DEFAULT 24, p_buckets integer DEFAULT 24) RETURNS TABLE(bucket timestamp with time zone, total bigint, errors bigint, warns bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH params AS (
    SELECT
      greatest(p_hours, 1) AS hours,
      greatest(p_buckets, 1) AS buckets
  ),
  series AS (
    SELECT generate_series(
      date_trunc('minute', now()) - make_interval(hours => (SELECT hours FROM params)),
      date_trunc('minute', now()),
      make_interval(secs => ((SELECT hours FROM params) * 3600.0 / (SELECT buckets FROM params))::int)
    ) AS bucket
  )
  SELECT
    s.bucket,
    count(l.id)::bigint AS total,
    count(l.id) FILTER (WHERE l.level = 'error')::bigint AS errors,
    count(l.id) FILTER (WHERE l.level = 'warn')::bigint AS warns
  FROM series s
  LEFT JOIN public.app_logs l
    ON l.ts >= s.bucket
   AND l.ts <  s.bucket + make_interval(secs => ((SELECT hours FROM params) * 3600.0 / (SELECT buckets FROM params))::int)
  GROUP BY s.bucket
  ORDER BY s.bucket;
$$;
CREATE FUNCTION public.current_user_org_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.default_user_org_id();
$$;
CREATE TABLE public.proveedor_facturas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    proveedor_id uuid NOT NULL,
    proveedor_nombre text DEFAULT ''::text NOT NULL,
    embarque_id uuid,
    folio_proveedor text NOT NULL,
    uuid_fiscal text,
    rfc_proveedor text,
    fecha_emision date DEFAULT CURRENT_DATE NOT NULL,
    fecha_vencimiento date,
    dias_credito integer DEFAULT 0 NOT NULL,
    moneda public.moneda DEFAULT 'MXN'::public.moneda NOT NULL,
    tipo_cambio_usd numeric DEFAULT 0 NOT NULL,
    subtotal numeric DEFAULT 0 NOT NULL,
    iva numeric DEFAULT 0 NOT NULL,
    retenciones numeric DEFAULT 0 NOT NULL,
    total numeric DEFAULT 0 NOT NULL,
    estado public.estado_proveedor_factura DEFAULT 'Borrador'::public.estado_proveedor_factura NOT NULL,
    archivo_pdf_url text,
    archivo_xml_url text,
    notas text DEFAULT ''::text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    categoria_presupuesto_id uuid NOT NULL,
    estado_captura text DEFAULT 'capturada'::text NOT NULL,
    estado_aprobacion public.estado_aprobacion_factura_proveedor DEFAULT 'pendiente'::public.estado_aprobacion_factura_proveedor NOT NULL,
    aprobada_por uuid,
    aprobada_at timestamp with time zone,
    motivo_rechazo text,
    folio_interno text NOT NULL,
    uuid_verificado boolean,
    uuid_verificado_fecha timestamp with time zone,
    uuid_estatus_sat text,
    fecha_programada_pago date,
    fecha_cancelacion timestamp with time zone,
    motivo_cancelacion text,
    cancelada_por uuid,
    ieps numeric DEFAULT 0 NOT NULL,
    origen_carga text DEFAULT 'manual'::text NOT NULL,
    justificacion_sin_vinculo text,
    aprobacion_heredada boolean DEFAULT false NOT NULL,
    CONSTRAINT proveedor_facturas_estado_captura_check CHECK ((estado_captura = ANY (ARRAY['pendiente_xml'::text, 'capturada'::text, 'conciliada'::text, 'pagada'::text]))),
    CONSTRAINT proveedor_facturas_origen_carga_check CHECK ((origen_carga = ANY (ARRAY['manual'::text, 'cfdi'::text, 'pdf_ia'::text])))
);
CREATE FUNCTION public.aprobar_factura_proveedor(p_id uuid, p_aprobar boolean, p_motivo text DEFAULT NULL::text) RETURNS public.proveedor_facturas
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.proveedor_facturas;
  v_uid uuid := auth.uid();
  v_email text;
  v_autorizado boolean;
  v_es_admin boolean;
  v_desvinculo jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid
      AND ur.role::text = ANY (ARRAY['admin','admin_org','super_admin','contador'])
  ) INTO v_autorizado;
  IF NOT v_autorizado THEN
    RAISE EXCEPTION 'LC_SOD_VIOLATION: Tu rol no puede aprobar ni rechazar facturas de proveedor.';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid
      AND ur.role::text = ANY (ARRAY['admin','admin_org','super_admin'])
  ) INTO v_es_admin;
  SELECT * INTO v_row FROM public.proveedor_facturas WHERE id = p_id AND deleted_at IS NULL;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Factura no encontrada';
  END IF;
  IF NOT public.has_role(v_uid, 'super_admin'::app_role)
     AND NOT EXISTS (
       SELECT 1 FROM public.organization_members om
        WHERE om.organization_id = v_row.organization_id
          AND om.user_id = v_uid
     )
  THEN
    RAISE EXCEPTION 'Factura no encontrada' USING ERRCODE = '42501';
  END IF;
  IF v_row.estado_aprobacion <> 'pendiente' THEN
    RAISE EXCEPTION 'La factura ya fue %', v_row.estado_aprobacion;
  END IF;
  -- SoD: quien capturó no aprueba su propia factura (salvo administradores)
  IF p_aprobar
     AND v_row.created_by IS NOT NULL
     AND v_row.created_by = v_uid
     AND NOT v_es_admin
  THEN
    RAISE EXCEPTION 'LC_SOD_VIOLATION: No puedes aprobar una factura que tú mismo capturaste. Pide la aprobación a otra persona.';
  END IF;
  -- Ola 4 (H2): al aprobar, `p_motivo` es la justificación del gasto sin respaldo.
  IF p_aprobar THEN
    PERFORM public._cxp_validar_aprobacion(p_id, p_motivo);
  END IF;
  -- RNF-07: marca de sesión requerida por trg_guard_aprobacion_proveedor_factura
  -- (transaction-local: se limpia sola si la transacción aborta).
  PERFORM set_config('app.aprobando_cxp', '1', true);
  IF p_aprobar THEN
    UPDATE public.proveedor_facturas
    SET estado_aprobacion = 'aprobada',
        aprobada_por = v_uid,
        aprobada_at = now(),
        motivo_rechazo = NULL,
        aprobacion_heredada = false,
        justificacion_sin_vinculo = NULLIF(btrim(COALESCE(p_motivo,'')), '')
    WHERE id = p_id RETURNING * INTO v_row;
  ELSE
    IF COALESCE(trim(p_motivo),'') = '' THEN
      RAISE EXCEPTION 'Motivo de rechazo requerido';
    END IF;
    UPDATE public.proveedor_facturas
    SET estado_aprobacion = 'rechazada', aprobada_por = v_uid, aprobada_at = now(), motivo_rechazo = p_motivo
    WHERE id = p_id RETURNING * INTO v_row;
    -- v13.493.0 — el rechazo rompe el vínculo con el embarque: los conceptos de
    -- costo vuelven a quedar pendientes de factura y la factura se cancela.
    v_desvinculo := public._cxp_desvincular_por_rechazo(p_id, p_motivo);
    SELECT * INTO v_row FROM public.proveedor_facturas WHERE id = p_id;
  END IF;
  PERFORM set_config('app.aprobando_cxp', '0', true);
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (
      v_row.organization_id,
      v_uid,
      COALESCE(v_email, ''),
      CASE WHEN p_aprobar THEN 'aprobar_factura_proveedor' ELSE 'rechazar_factura_proveedor' END,
      'cxp',
      v_row.id,
      'Factura ' || COALESCE(v_row.folio_proveedor,'') || ' de ' || COALESCE(v_row.proveedor_nombre,''),
      jsonb_build_object(
        'motivo', p_motivo,
        'total', v_row.total,
        'aprobada', p_aprobar,
        'justificacion_sin_vinculo', v_row.justificacion_sin_vinculo
      ) || v_desvinculo
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora_actividad insert failed in aprobar_factura_proveedor: % %', SQLSTATE, SQLERRM;
  END;
  RETURN v_row;
END;
$$;
CREATE FUNCTION public.aprobar_nota_credito_proveedor(_nc_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado public.estado_nota_credito_proveedor;
BEGIN
  IF NOT (has_role(auth.uid(),'admin') OR has_role(auth.uid(),'super_admin')) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;
  -- N18: serializa dos llamadas concurrentes sobre la misma nota.
  SELECT estado INTO v_estado
  FROM public.proveedor_notas_credito
  WHERE id = _nc_id AND organization_id = public.org_scope()
  FOR UPDATE;
  IF NOT FOUND OR v_estado <> 'Borrador' THEN
    RAISE EXCEPTION 'Nota de crédito no encontrada o no está en Borrador';
  END IF;
  UPDATE public.proveedor_notas_credito
  SET estado = 'Aprobada',
      aprobada_por = auth.uid(),
      aprobada_at = now(),
      updated_at = now()
  WHERE id = _nc_id;
END;
$$;
CREATE FUNCTION public.archivar_version_cotizacion(p_cotizacion_id uuid, p_motivo text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_version INT;
  v_org UUID;
  v_uid UUID := auth.uid();
BEGIN
  SELECT version, organization_id INTO v_version, v_org
  FROM public.cotizaciones WHERE id = p_cotizacion_id;
  IF v_version IS NULL THEN
    RAISE EXCEPTION 'Cotización % no encontrada', p_cotizacion_id USING ERRCODE = 'P0002';
  END IF;
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'LC_NO_AUTORIZADO: sesión requerida' USING ERRCODE = '42501';
    END IF;
    IF NOT public.is_org_member(v_org) THEN
      RAISE EXCEPTION 'LC_ORG_FORBIDDEN: la cotización pertenece a otra organización'
        USING ERRCODE = '42501';
    END IF;
    IF NOT public.puede_escribir_cotizaciones(v_uid) THEN
      RAISE EXCEPTION 'LC_COTIZACION_SIN_PERMISO: tu rol no puede archivar versiones de cotización'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  INSERT INTO public.cotizacion_costos_historico (
    cotizacion_id, version, organization_id, origen_costo_id, concepto, proveedor, cantidad, unidad_medida,
    costo_unitario, costo_total, precio_venta, precio_total, profit, porcentaje_profit, moneda, notas,
    costeo_tarifa_id, costeo_tarifa_recargo_id, archivada_por, motivo)
  SELECT cc.cotizacion_id, v_version, cc.organization_id, cc.id, cc.concepto, cc.proveedor, cc.cantidad, cc.unidad_medida,
    cc.costo_unitario, cc.costo_total, cc.precio_venta, cc.precio_total, cc.profit, cc.porcentaje_profit, cc.moneda, cc.notas,
    cc.costeo_tarifa_id, cc.costeo_tarifa_recargo_id, v_uid, p_motivo
  FROM public.cotizacion_costos cc
  WHERE cc.cotizacion_id = p_cotizacion_id AND cc.deleted_at IS NULL;
  PERFORM public.registrar_bitacora('cotizaciones','archivar_version_costos',p_cotizacion_id,'',
    jsonb_build_object('version', v_version, 'motivo', COALESCE(p_motivo,'')), v_org, v_uid);
  RETURN v_version;
END;
$$;
CREATE TABLE public.proformas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    numero text NOT NULL,
    embarque_id uuid,
    cliente_id uuid NOT NULL,
    cliente_nombre text NOT NULL,
    expediente text NOT NULL,
    bl_master text,
    subtotal_usd numeric DEFAULT 0 NOT NULL,
    iva_usd numeric DEFAULT 0 NOT NULL,
    total_usd numeric DEFAULT 0 NOT NULL,
    subtotal_mxn numeric DEFAULT 0 NOT NULL,
    iva_mxn numeric DEFAULT 0 NOT NULL,
    total_mxn numeric DEFAULT 0 NOT NULL,
    fecha_emision date DEFAULT CURRENT_DATE NOT NULL,
    notas text,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    es_consolidada boolean DEFAULT false NOT NULL,
    estado_aprobacion text DEFAULT 'borrador'::text NOT NULL,
    operador text,
    dias_credito integer,
    estado_proforma text DEFAULT 'pendiente'::text NOT NULL,
    folio_factura_externa text,
    fecha_facturacion date,
    factura_id uuid,
    estado_revision text DEFAULT 'pendiente'::text NOT NULL,
    proformas_origen uuid[],
    tasa_iva_aplicada numeric DEFAULT 0.16 NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    snapshot_emision jsonb,
    factura_secundaria_id uuid,
    estado_cliente text DEFAULT 'pendiente'::text NOT NULL,
    aceptada_at timestamp with time zone,
    rechazada_at timestamp with time zone,
    aceptada_por text,
    motivo_rechazo text,
    enviada_at timestamp with time zone,
    enviada_por uuid,
    ultimo_envio_email text,
    token_publico uuid,
    token_expira_at timestamp with time zone,
    origen text,
    consolidada_en uuid,
    embarques_ids uuid[],
    CONSTRAINT proformas_estado_cliente_check CHECK ((estado_cliente = ANY (ARRAY['pendiente'::text, 'aceptada'::text, 'rechazada'::text]))),
    CONSTRAINT proformas_estado_proforma_check CHECK ((estado_proforma = ANY (ARRAY['pendiente'::text, 'facturada'::text]))),
    CONSTRAINT proformas_estado_revision_check CHECK ((estado_revision = ANY (ARRAY['pendiente'::text, 'aprobada'::text, 'consolidada'::text]))),
    CONSTRAINT proformas_iva_mxn_nonneg CHECK ((iva_mxn >= (0)::numeric)),
    CONSTRAINT proformas_iva_usd_nonneg CHECK ((iva_usd >= (0)::numeric)),
    CONSTRAINT proformas_subtotal_mxn_nonneg CHECK ((subtotal_mxn >= (0)::numeric)),
    CONSTRAINT proformas_subtotal_usd_nonneg CHECK ((subtotal_usd >= (0)::numeric)),
    CONSTRAINT proformas_total_mxn_nonneg CHECK ((total_mxn >= (0)::numeric)),
    CONSTRAINT proformas_total_usd_nonneg CHECK ((total_usd >= (0)::numeric))
);
CREATE FUNCTION public.asignar_conceptos_a_proforma(p_proforma_id uuid, p_concepto_ids uuid[]) RETURNS public.proformas
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_proforma public.proformas;
  v_org uuid;
  v_n_asignados int;
BEGIN
  IF p_proforma_id IS NULL THEN
    RAISE EXCEPTION 'p_proforma_id es obligatorio';
  END IF;
  IF p_concepto_ids IS NULL OR array_length(p_concepto_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Se requiere al menos un concepto a asignar';
  END IF;
  SELECT * INTO v_proforma FROM public.proformas WHERE id = p_proforma_id;
  IF v_proforma.id IS NULL THEN
    RAISE EXCEPTION 'Proforma no encontrada';
  END IF;
  v_org := v_proforma.organization_id;
  PERFORM public._assert_writer(v_org);
  IF v_proforma.estado_proforma = 'facturada' THEN
    RAISE EXCEPTION 'No se pueden asignar conceptos a una proforma ya facturada';
  END IF;
  -- Sólo conceptos pendientes, del mismo embarque y de la misma organización.
  UPDATE public.conceptos_venta cv
  SET proforma_id = v_proforma.id,
      estado_facturacion = 'en_proforma'
  WHERE cv.id = ANY(p_concepto_ids)
    AND cv.organization_id = v_org
    AND cv.embarque_id = v_proforma.embarque_id
    AND cv.deleted_at IS NULL
    AND cv.estado_facturacion = 'pendiente'
    AND cv.proforma_id IS NULL;
  GET DIAGNOSTICS v_n_asignados = ROW_COUNT;
  IF v_n_asignados = 0 THEN
    RAISE EXCEPTION 'Ningún concepto elegible fue asignado (verifica estado y embarque)';
  END IF;
  -- Recalcular totales de la proforma con base en sus conceptos vinculados.
  WITH r AS (
    SELECT
      COALESCE(SUM(CASE WHEN cv.moneda::text='USD'
                        THEN cv.cantidad*cv.precio_unitario ELSE 0 END), 0) AS sub_usd,
      COALESCE(SUM(CASE WHEN cv.moneda::text='USD' AND cv.aplica_iva
                        THEN cv.cantidad*cv.precio_unitario*COALESCE(cv.tasa_iva_aplicada, v_proforma.tasa_iva_aplicada, 0.16)
                        ELSE 0 END), 0) AS iva_usd,
      COALESCE(SUM(CASE WHEN cv.moneda::text='MXN'
                        THEN cv.cantidad*cv.precio_unitario ELSE 0 END), 0) AS sub_mxn,
      COALESCE(SUM(CASE WHEN cv.moneda::text='MXN' AND cv.aplica_iva
                        THEN cv.cantidad*cv.precio_unitario*COALESCE(cv.tasa_iva_aplicada, v_proforma.tasa_iva_aplicada, 0.16)
                        ELSE 0 END), 0) AS iva_mxn
    FROM public.conceptos_venta cv
    WHERE cv.proforma_id = v_proforma.id AND cv.deleted_at IS NULL
  )
  UPDATE public.proformas p
  SET subtotal_usd = r.sub_usd,
      iva_usd = r.iva_usd,
      total_usd = r.sub_usd + r.iva_usd,
      subtotal_mxn = r.sub_mxn,
      iva_mxn = r.iva_mxn,
      total_mxn = r.sub_mxn + r.iva_mxn,
      updated_at = now()
  FROM r
  WHERE p.id = v_proforma.id
  RETURNING p.* INTO v_proforma;
  RETURN v_proforma;
END;
$$;
CREATE FUNCTION public.assert_factura_viva_para_pago() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado text;
  v_cancel text;
  v_total numeric;
  v_fecha_emision date;
  v_pagos_otros numeric;
  v_ncs numeric;
  v_saldo_disponible_previo numeric;
  v_saldo_post numeric;
  v_solo_metadatos boolean := false;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    v_solo_metadatos := (
      NEW.factura_id IS NOT DISTINCT FROM OLD.factura_id
      AND NEW.monto IS NOT DISTINCT FROM OLD.monto
      AND NEW.monto_aplicado_factura IS NOT DISTINCT FROM OLD.monto_aplicado_factura
      AND NEW.moneda IS NOT DISTINCT FROM OLD.moneda
      AND NEW.tipo_cambio IS NOT DISTINCT FROM OLD.tipo_cambio
      AND NEW.ret_isr IS NOT DISTINCT FROM OLD.ret_isr
      AND NEW.ret_iva IS NOT DISTINCT FROM OLD.ret_iva
      AND NEW.fecha_pago IS NOT DISTINCT FROM OLD.fecha_pago
      AND OLD.deleted_at IS NULL
    );
    IF v_solo_metadatos THEN
      RETURN NEW;
    END IF;
  END IF;
  IF NEW.fecha_pago IS NOT NULL AND NEW.fecha_pago > CURRENT_DATE THEN
    RAISE EXCEPTION 'LC_PAGO_FECHA_FUTURA: la fecha del cobro no puede ser futura'
      USING ERRCODE = 'check_violation',
            HINT    = json_build_object('fecha_pago', NEW.fecha_pago)::text;
  END IF;
  PERFORM 1 FROM public.facturas WHERE id = NEW.factura_id FOR UPDATE;
  SELECT estado::text, COALESCE(total, 0), COALESCE(cancellation_status, 'none'),
         fecha_emision
    INTO v_estado, v_total, v_cancel, v_fecha_emision
  FROM public.facturas
  WHERE id = NEW.factura_id;
  IF v_estado IN ('Cancelada','Sustituida','Borrador') THEN
    RAISE EXCEPTION 'LC_PAGO_FACTURA_NO_VIVA: la factura está en estado % y no admite pagos', v_estado
      USING ERRCODE = 'check_violation',
            HINT    = json_build_object('estado_factura', v_estado)::text;
  END IF;
  IF v_cancel IN ('pending','verifying') THEN
    RAISE EXCEPTION 'LC_FACTURA_EN_CANCELACION: la factura tiene una cancelación en trámite ante el SAT y no admite cobros'
      USING ERRCODE = 'check_violation',
            HINT    = json_build_object('cancellation_status', v_cancel)::text;
  END IF;
  IF NEW.fecha_pago IS NOT NULL
     AND v_fecha_emision IS NOT NULL
     AND NEW.fecha_pago < v_fecha_emision THEN
    RAISE EXCEPTION 'LC_PAGO_FECHA_PREVIA_EMISION: la fecha del cobro no puede ser anterior a la emisión de la factura'
      USING ERRCODE = 'check_violation',
            HINT    = json_build_object(
              'fecha_pago', NEW.fecha_pago,
              'fecha_emision', v_fecha_emision
            )::text;
  END IF;
  SELECT COALESCE(SUM(pf.monto_aplicado_factura), 0) INTO v_pagos_otros
  FROM public.pagos_factura pf
  WHERE pf.factura_id = NEW.factura_id
    AND pf.deleted_at IS NULL
    AND pf.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
  v_ncs := public.nc_aplicadas_en_moneda_factura(NEW.factura_id);
  v_saldo_disponible_previo := v_total - v_pagos_otros - v_ncs;
  v_saldo_post := v_saldo_disponible_previo - COALESCE(NEW.monto_aplicado_factura, 0);
  IF v_saldo_post < -0.005 THEN
    RAISE EXCEPTION 'LC_PAGO_SOBREPAGO: el pago excede el saldo pendiente'
      USING ERRCODE = 'check_violation',
            HINT    = json_build_object(
              'saldo_disponible', v_saldo_disponible_previo,
              'monto_intentado', NEW.monto_aplicado_factura,
              'notas_credito_aplicadas', v_ncs
            )::text;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.assert_factura_viva_para_rep() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado text;
  v_uuid_fiscal text;
BEGIN
  -- Sólo validamos cuando la fila realmente está timbrando un REP.
  -- Un pago sin uuid_rep ni facturapi_rep_id no timbra REP por definición,
  -- sin importar el valor de estado_rep (que puede ser 'NoAplica' por default).
  IF NEW.uuid_rep IS NULL AND NEW.facturapi_rep_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT estado::text, uuid_fiscal
    INTO v_estado, v_uuid_fiscal
  FROM public.facturas WHERE id = NEW.factura_id;
  IF v_uuid_fiscal IS NULL THEN
    RAISE EXCEPTION 'LC_REP_FACTURA_SIN_TIMBRAR: no se puede timbrar REP de una factura sin UUID fiscal'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_estado IN ('Cancelada','Sustituida','Borrador') THEN
    RAISE EXCEPTION 'LC_REP_FACTURA_NO_VIVA: la factura está en estado % y no admite REP', v_estado
      USING ERRCODE = 'check_violation',
            HINT    = json_build_object('estado_factura', v_estado)::text;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.assert_movimiento_pago_consistente() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pago_org uuid;
  v_pago_moneda text;
  v_pago_monto numeric;
  v_cuenta_moneda text;
  v_vinculos int;
  v_mov numeric;
  c_tol constant numeric := 1.00; -- tolerancia en la moneda del movimiento
BEGIN
  v_vinculos :=
      (CASE WHEN NEW.pago_factura_id IS NOT NULL THEN 1 ELSE 0 END)
    + (CASE WHEN NEW.pago_proveedor_id IS NOT NULL THEN 1 ELSE 0 END)
    + (CASE WHEN NEW.anticipo_proveedor_id IS NOT NULL THEN 1 ELSE 0 END)
    + (CASE WHEN NEW.pago_proveedor_lote_id IS NOT NULL THEN 1 ELSE 0 END)
    + (CASE WHEN NEW.pago_factura_lote_id IS NOT NULL THEN 1 ELSE 0 END)
    + (CASE WHEN NEW.traspaso_id IS NOT NULL THEN 1 ELSE 0 END);
  IF v_vinculos > 1 THEN
    RAISE EXCEPTION 'LC_MOVIMIENTO_DOBLE_VINCULO: un movimiento no puede vincularse a más de un origen (pago de factura, pago de proveedor, lote de pago, anticipo o traspaso)'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.cuenta_bancaria_id IS NOT NULL THEN
    SELECT moneda::text INTO v_cuenta_moneda
    FROM public.cuentas_bancarias
    WHERE id = NEW.cuenta_bancaria_id AND deleted_at IS NULL;
  END IF;
  IF NEW.pago_factura_id IS NOT NULL THEN
    SELECT organization_id, moneda::text, COALESCE(monto,0)
      INTO v_pago_org, v_pago_moneda, v_pago_monto
    FROM public.pagos_factura
    WHERE id = NEW.pago_factura_id AND deleted_at IS NULL;
    IF v_pago_org IS NULL THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_PAGO_INEXISTENTE: el pago de factura % no existe o está eliminado', NEW.pago_factura_id
        USING ERRCODE = 'P0001';
    END IF;
    IF v_pago_org IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_ORG_MISMATCH: el pago de factura pertenece a otra organización'
        USING ERRCODE = 'P0001';
    END IF;
    IF v_cuenta_moneda IS NOT NULL AND v_pago_moneda IS DISTINCT FROM v_cuenta_moneda THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_DIVISA_MISMATCH: la moneda del pago (%) no coincide con la cuenta bancaria (%)',
        v_pago_moneda, v_cuenta_moneda
        USING ERRCODE = 'P0001';
    END IF;
    -- N11: cobro ⇒ abono en la cuenta.
    v_mov := GREATEST(COALESCE(NEW.abono,0), COALESCE(NEW.cargo,0));
    IF v_mov > 0 AND v_pago_monto > 0 AND abs(v_mov - v_pago_monto) > c_tol THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_MONTO_MISMATCH: el movimiento por % no coincide con el pago por % (tolerancia %)',
        v_mov, v_pago_monto, c_tol
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF NEW.pago_proveedor_id IS NOT NULL THEN
    SELECT organization_id, moneda::text, COALESCE(monto,0)
      INTO v_pago_org, v_pago_moneda, v_pago_monto
    FROM public.pagos_proveedor
    WHERE id = NEW.pago_proveedor_id AND deleted_at IS NULL;
    IF v_pago_org IS NULL THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_PAGO_INEXISTENTE: el pago de proveedor % no existe o está eliminado', NEW.pago_proveedor_id
        USING ERRCODE = 'P0001';
    END IF;
    IF v_pago_org IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_ORG_MISMATCH: el pago de proveedor pertenece a otra organización'
        USING ERRCODE = 'P0001';
    END IF;
    IF v_cuenta_moneda IS NOT NULL AND v_pago_moneda IS DISTINCT FROM v_cuenta_moneda THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_DIVISA_MISMATCH: la moneda del pago (%) no coincide con la cuenta bancaria (%)',
        v_pago_moneda, v_cuenta_moneda
        USING ERRCODE = 'P0001';
    END IF;
    v_mov := GREATEST(COALESCE(NEW.cargo,0), COALESCE(NEW.abono,0));
    IF v_mov > 0 AND v_pago_monto > 0 AND abs(v_mov - v_pago_monto) > c_tol THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_MONTO_MISMATCH: el movimiento por % no coincide con el pago por % (tolerancia %)',
        v_mov, v_pago_monto, c_tol
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF NEW.pago_proveedor_lote_id IS NOT NULL THEN
    SELECT organization_id, moneda::text INTO v_pago_org, v_pago_moneda
    FROM public.pagos_proveedor_lote
    WHERE id = NEW.pago_proveedor_lote_id AND deleted_at IS NULL;
    IF v_pago_org IS NULL THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_LOTE_INEXISTENTE: el lote de pago % no existe o está eliminado', NEW.pago_proveedor_lote_id
        USING ERRCODE = 'P0001';
    END IF;
    IF v_pago_org IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_ORG_MISMATCH: el lote de pago pertenece a otra organización'
        USING ERRCODE = 'P0001';
    END IF;
    IF v_cuenta_moneda IS NOT NULL AND v_pago_moneda IS DISTINCT FROM v_cuenta_moneda THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_DIVISA_MISMATCH: la moneda del lote (%) no coincide con la cuenta bancaria (%)',
        v_pago_moneda, v_cuenta_moneda
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF NEW.pago_factura_lote_id IS NOT NULL THEN
    SELECT organization_id, moneda::text INTO v_pago_org, v_pago_moneda
    FROM public.pagos_factura_lote
    WHERE id = NEW.pago_factura_lote_id AND deleted_at IS NULL;
    IF v_pago_org IS NULL THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_LOTE_COBRO_INEXISTENTE: el lote de cobro % no existe o está eliminado', NEW.pago_factura_lote_id
        USING ERRCODE = 'P0001';
    END IF;
    IF v_pago_org IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_ORG_MISMATCH: el lote de cobro pertenece a otra organización'
        USING ERRCODE = 'P0001';
    END IF;
    IF v_cuenta_moneda IS NOT NULL AND v_pago_moneda IS DISTINCT FROM v_cuenta_moneda THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_DIVISA_MISMATCH: la moneda del lote de cobro (%) no coincide con la cuenta bancaria (%)',
        v_pago_moneda, v_cuenta_moneda
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF NEW.anticipo_proveedor_id IS NOT NULL THEN
    SELECT organization_id, moneda::text INTO v_pago_org, v_pago_moneda
    FROM public.anticipos_proveedor
    WHERE id = NEW.anticipo_proveedor_id;
    IF v_pago_org IS NULL THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_ANTICIPO_INEXISTENTE: el anticipo % no existe', NEW.anticipo_proveedor_id
        USING ERRCODE = 'P0001';
    END IF;
    IF v_pago_org IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_ORG_MISMATCH: el anticipo pertenece a otra organización'
        USING ERRCODE = 'P0001';
    END IF;
    IF v_cuenta_moneda IS NOT NULL AND v_pago_moneda IS DISTINCT FROM v_cuenta_moneda THEN
      RAISE EXCEPTION 'LC_MOVIMIENTO_DIVISA_MISMATCH: la moneda del anticipo (%) no coincide con la cuenta bancaria (%)',
        v_pago_moneda, v_cuenta_moneda
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.assert_nc_fecha_valida() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fecha_factura date;
  -- Techo tolerante: entre 18:00 y 24:00 hora de México el servidor (UTC) ya
  -- está en el día siguiente. Usar sólo la fecha de México rechazaba NC y
  -- facturas capturadas por la tarde. Tomamos la mayor de ambas fechas.
  v_hoy_max date := GREATEST((now() AT TIME ZONE 'America/Mexico_City')::date, CURRENT_DATE);
BEGIN
  SELECT f.fecha_emision INTO v_fecha_factura
  FROM public.facturas f
  WHERE f.id = NEW.factura_id;
  IF v_fecha_factura IS NULL OR NEW.fecha_emision IS NULL
     OR NEW.fecha_emision < v_fecha_factura OR NEW.fecha_emision > v_hoy_max THEN
    RAISE EXCEPTION 'LC_NC_FECHA_INVALIDA: la fecha debe estar entre la emisión de la factura y hoy'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END
$$;
CREATE FUNCTION public.assert_nc_no_excede_saldo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fac record;
  v_saldo_doc numeric;
  v_saldo_mxn numeric;
  v_ncs_previas_mxn numeric;
  v_nc_nueva_mxn numeric;
  v_total_ncs_mxn numeric;
  v_tol_mxn numeric;
BEGIN
  -- Sólo restringe NCs vivas y aplicadas (borradores y canceladas se permiten).
  IF NEW.deleted_at IS NOT NULL OR NEW.estado::text NOT IN ('Aplicada','Emitida') THEN
    RETURN NEW;
  END IF;
  SELECT f.moneda::text AS moneda, f.tipo_cambio, f.fecha_emision
    INTO v_fac
  FROM public.facturas f
  WHERE f.id = NEW.factura_id
    AND f.deleted_at IS NULL;
  -- Factura inexistente o en papelera: fuera del alcance del candado.
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;
  v_saldo_doc := public.saldo_factura_bruto(NEW.factura_id);
  v_saldo_mxn := public.a_mxn_doc(v_saldo_doc, v_fac.moneda, v_fac.fecha_emision, v_fac.tipo_cambio, NULL);
  v_nc_nueva_mxn := public.a_mxn_doc(
    COALESCE(NEW.monto, 0),
    COALESCE(NEW.moneda::text, v_fac.moneda),
    COALESCE(NEW.fecha_emision, v_fac.fecha_emision),
    NEW.tipo_cambio,
    v_fac.tipo_cambio
  );
  -- Fail-closed: sin tipo de cambio no se puede comparar dinero de forma segura.
  IF v_saldo_mxn IS NULL OR v_nc_nueva_mxn IS NULL THEN
    RAISE EXCEPTION 'LC_NC_SIN_TC: no hay tipo de cambio para validar la nota de crédito contra el saldo de la factura'
      USING ERRCODE = 'check_violation',
            HINT    = json_build_object(
              'moneda_factura', v_fac.moneda,
              'moneda_nota_credito', COALESCE(NEW.moneda::text, v_fac.moneda),
              'fecha_nota_credito', COALESCE(NEW.fecha_emision, v_fac.fecha_emision)
            )::text;
  END IF;
  SELECT COALESCE(SUM(
           public.a_mxn_doc(
             nc.monto,
             COALESCE(nc.moneda::text, v_fac.moneda),
             COALESCE(nc.fecha_emision, v_fac.fecha_emision),
             nc.tipo_cambio,
             v_fac.tipo_cambio
           )
         ), 0)
    INTO v_ncs_previas_mxn
  FROM public.factura_notas_credito nc
  WHERE nc.factura_id = NEW.factura_id
    AND nc.deleted_at IS NULL
    AND nc.estado::text IN ('Aplicada','Emitida')
    AND nc.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
  v_total_ncs_mxn := v_ncs_previas_mxn + v_nc_nueva_mxn;
  -- Tolerancia de un centavo expresada en la moneda de la factura.
  v_tol_mxn := GREATEST(
    0.01,
    COALESCE(public.a_mxn_doc(0.01, v_fac.moneda, v_fac.fecha_emision, v_fac.tipo_cambio, NULL), 0.01)
  );
  IF v_total_ncs_mxn > v_saldo_mxn + v_tol_mxn THEN
    RAISE EXCEPTION 'LC_NC_EXCEDE_SALDO: la nota de crédito excede el saldo pendiente'
      USING ERRCODE = 'check_violation',
            HINT    = json_build_object(
              'moneda_factura', v_fac.moneda,
              'saldo_disponible_mxn', round(v_saldo_mxn - v_ncs_previas_mxn, 2),
              'monto_intentado_mxn', round(v_nc_nueva_mxn, 2),
              'monto_intentado', NEW.monto,
              'moneda_nota_credito', COALESCE(NEW.moneda::text, v_fac.moneda)
            )::text;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.assert_pago_sin_rep_vivo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Sólo actuamos cuando se está haciendo soft-delete (deleted_at pasa de NULL a NOT NULL).
  IF NEW.deleted_at IS NULL THEN
    RETURN NEW;
  END IF;
  IF OLD.deleted_at IS NOT NULL THEN
    -- ya estaba borrado; no re-validamos
    RETURN NEW;
  END IF;
  IF OLD.uuid_rep IS NOT NULL AND OLD.rep_cancelado_en IS NULL THEN
    RAISE EXCEPTION 'LC_PAGO_CON_REP_VIVO'
      USING HINT = COALESCE(OLD.uuid_rep::text, ''),
            ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.assert_pago_sin_rep_vivo_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.uuid_rep IS NOT NULL
     AND COALESCE(OLD.estado_rep, 'Pendiente') IN ('Pendiente','Timbrado') THEN
    RAISE EXCEPTION 'LC_PAGO_CON_REP_VIVO: el pago tiene un REP vivo (%), cancele o descarte el REP antes de eliminar',
      COALESCE(OLD.estado_rep, 'Pendiente')
      USING ERRCODE='P0001';
  END IF;
  RETURN OLD;
END $$;
CREATE FUNCTION public.assert_proformas_moneda_soportada(p_proforma_ids uuid[]) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_no_sop text;
BEGIN
  SELECT string_agg(DISTINCT m::text, ', ') INTO v_no_sop FROM (
    SELECT cv.moneda::text AS m
      FROM public.conceptos_venta cv
     WHERE cv.proforma_id = ANY(p_proforma_ids)
       AND cv.deleted_at IS NULL
       AND cv.moneda::text NOT IN ('MXN','USD')
    UNION
    SELECT pcc.moneda::text
      FROM public.proforma_conceptos_consolidados pcc
     WHERE pcc.proforma_id = ANY(p_proforma_ids)
       AND pcc.deleted_at IS NULL
       AND pcc.moneda::text NOT IN ('MXN','USD')
  ) x;
  IF v_no_sop IS NOT NULL THEN
    RAISE EXCEPTION 'LC_PROFORMA_MONEDA_NO_SOPORTADA: la conversión sólo soporta MXN/USD hoy; conceptos en % detectados', v_no_sop
      USING ERRCODE='P0001',
            HINT='Elimine o convierta los conceptos en la moneda no soportada antes de facturar.';
  END IF;
END;
$$;
CREATE FUNCTION public.assert_proveedor_factura_viva_para_pago() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado text;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT estado::text INTO v_estado
  FROM public.proveedor_facturas WHERE id = NEW.proveedor_factura_id;
  IF v_estado = 'Cancelada' THEN
    RAISE EXCEPTION 'LC_PAGO_CXP_NO_VIVA: la factura de proveedor está cancelada'
      USING ERRCODE = 'check_violation',
            HINT    = json_build_object('estado_factura', v_estado)::text;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.assert_transicion_embarque(p_actual public.estado_embarque, p_nuevo public.estado_embarque, p_expediente text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_permitidas text;
BEGIN
  IF public.transicion_embarque_valida(p_actual, p_nuevo) THEN
    RETURN;
  END IF;
  -- Recolectar transiciones permitidas para el HINT (UX + debugging).
  SELECT COALESCE(string_agg(v::text, ',' ORDER BY v::text), '')
    INTO v_permitidas
  FROM unnest(enum_range(NULL::public.estado_embarque)) AS v
  WHERE public.transicion_embarque_valida(p_actual, v);
  RAISE EXCEPTION 'LC_TRANSICION_INVALIDA: no se permite pasar de % a %', p_actual, p_nuevo
    USING
      ERRCODE = 'P0001',
      HINT = jsonb_build_object(
        'estado_actual', p_actual::text,
        'estado_nuevo', p_nuevo::text,
        'expediente', COALESCE(p_expediente, ''),
        'transiciones_permitidas', v_permitidas
      )::text;
END;
$$;
CREATE FUNCTION public.auditoria_capturar_snapshot(p_organization_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reporte jsonb;
  v_total int := 0;
  v_pend  int := 0;
  v_crit  int := 0;
  v_alto  int := 0;
  v_med   int := 0;
  v_suma  int := 0;
  v_score int := 100;
  v_por_regla jsonb := '{}'::jsonb;
  v_id uuid;
BEGIN
  IF NOT (
    COALESCE(auth.role(), '') = 'service_role'
    OR has_role(auth.uid(), 'super_admin'::app_role)
    OR is_org_admin(auth.uid(), p_organization_id)
    OR has_org_role(auth.uid(), p_organization_id, 'admin'::app_role)
    OR has_org_role(auth.uid(), p_organization_id, 'operador'::app_role)
  ) THEN
    RAISE EXCEPTION 'No autorizado para capturar snapshot de esta organización';
  END IF;
  -- A-10: siempre por la org objetivo (la RPC ya es SECURITY DEFINER).
  v_reporte := public.auditoria_embarques_org(p_organization_id);
  v_total := COALESCE((v_reporte->>'total_hallazgos')::int, 0);
  -- M-6: pendientes = hallazgos sin revisión registrada (misma llave que el
  -- frontend: embarque_id + regla + detalle).
  WITH hallazgos AS (
    SELECT je.value AS j
      FROM jsonb_array_elements(COALESCE(v_reporte->'hallazgos', '[]'::jsonb)) je
  ), pendientes AS (
    SELECT h.j
      FROM hallazgos h
     WHERE NOT EXISTS (
       SELECT 1
         FROM public.auditoria_revisiones r
        WHERE r.organization_id = p_organization_id
          AND r.embarque_id = (h.j->>'embarque_id')::uuid
          AND r.regla = (h.j->>'regla')
          AND r.detalle = (h.j->>'detalle')
     )
  )
  SELECT
    COUNT(*)::int,
    COUNT(*) FILTER (WHERE j->>'severidad' = 'critico')::int,
    COUNT(*) FILTER (WHERE j->>'severidad' = 'alto')::int,
    COUNT(*) FILTER (WHERE j->>'severidad' = 'medio')::int,
    COALESCE(jsonb_object_agg(regla, cnt) FILTER (WHERE regla IS NOT NULL), '{}'::jsonb)
    INTO v_pend, v_crit, v_alto, v_med, v_por_regla
    FROM (
      SELECT p.j,
             (p.j->>'regla') AS regla,
             COUNT(*) OVER (PARTITION BY (p.j->>'regla'))::int AS cnt
        FROM pendientes p
    ) x;
  -- Higiene (espejo de `calcularScore` con riesgoMxn = 0).
  v_suma := v_crit * 5 + v_alto * 2 + v_med * 1;
  IF v_pend = 0 THEN
    v_score := 100;
  ELSE
    v_score := GREATEST(0, 100 - LEAST(100, v_suma * 2));
  END IF;
  INSERT INTO auditoria_snapshots (
    organization_id, fecha, total_hallazgos, total_pendientes,
    criticos, altos, medios, score, por_regla
  ) VALUES (
    p_organization_id, CURRENT_DATE, v_total, GREATEST(0, v_pend),
    v_crit, v_alto, v_med, v_score, COALESCE(v_por_regla, '{}'::jsonb)
  )
  ON CONFLICT (organization_id, fecha) DO UPDATE SET
    total_hallazgos  = EXCLUDED.total_hallazgos,
    total_pendientes = EXCLUDED.total_pendientes,
    criticos = EXCLUDED.criticos,
    altos    = EXCLUDED.altos,
    medios   = EXCLUDED.medios,
    score    = EXCLUDED.score,
    por_regla = EXCLUDED.por_regla
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;
CREATE FUNCTION public.auditoria_embarques_org() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid;
BEGIN
  v_caller_org := public.current_user_org_id();
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;
  PERFORM public._assert_internal_reader(v_caller_org);
  -- Delegar a la variante con parámetro (que ahora también valida).
  RETURN public.auditoria_embarques_org(v_caller_org);
END;
$$;
CREATE FUNCTION public.auditoria_embarques_org(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_margen_min_pct numeric;
  v_dias_prof_venc int;
  v_dias_huerfano int;
  v_dias_borrador_abandonado int;
  v_dias_cxc_vencida int;
  v_dias_cxp_captura int;
  v_dias_cxp_vencida int;
  v_fecha_corte_facturacion constant date := DATE '2026-04-01';
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'p_organization_id es obligatorio';
  END IF;
  PERFORM public._assert_internal_reader(p_organization_id);
  SELECT u.margen_min_pct, u.dias_prof_venc, u.dias_huerfano,
         u.dias_borrador_abandonado, u.dias_cxc_vencida,
         u.dias_cxp_captura, u.dias_cxp_vencida
    INTO v_margen_min_pct, v_dias_prof_venc, v_dias_huerfano,
         v_dias_borrador_abandonado, v_dias_cxc_vencida,
         v_dias_cxp_captura, v_dias_cxp_vencida
    FROM public._audit_embarques_umbrales(p_organization_id) u;
  WITH
  emb AS (
    SELECT id, expediente, cliente_nombre, modo, estado, etd, eta,
           fecha_llegada_real, tipo_servicio, tipo_carga, operador,
           tipo_cambio_usd, tipo_cambio_eur, fecha_creacion
    FROM embarques
    WHERE estado <> 'Cancelado'
      AND deleted_at IS NULL
      AND organization_id = p_organization_id
  ),
  docs_existentes AS (
    SELECT embarque_id, nombre,
           bool_or(archivo IS NOT NULL OR estado = 'No aplica') AS satisfecho
    FROM documentos_embarque
    WHERE embarque_id IN (SELECT id FROM emb) AND deleted_at IS NULL
    GROUP BY embarque_id, nombre
  ),
  exigidos AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           d.doc_nombre
    FROM emb e
    CROSS JOIN LATERAL unnest(
      public._docs_requeridos_por_estado(e.modo::text, e.estado::text)
    ) AS d(doc_nombre)
  ),
  hall_docs_faltantes AS (
    SELECT jsonb_build_object(
      'embarque_id', x.embarque_id, 'expediente', x.expediente,
      'cliente_nombre', x.cliente_nombre, 'modo', x.modo::text, 'estado', x.estado::text, 'eta', x.eta,
      'regla', 'docs_faltantes', 'severidad', 'critico',
      'detalle', 'Documentos faltantes para estado ' || x.estado::text || ': ' || string_agg(x.doc_nombre, ', '),
      'documentos_faltantes', to_jsonb(array_agg(x.doc_nombre))
    ) AS h
    FROM exigidos x
    LEFT JOIN docs_existentes de
      ON de.embarque_id = x.embarque_id AND de.nombre = x.doc_nombre
    WHERE COALESCE(de.satisfecho, false) = false
    GROUP BY x.embarque_id, x.expediente, x.cliente_nombre, x.modo, x.estado, x.eta
  ),
  hall_docs_pendientes AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'docs_pendientes_avanzado', 'severidad', 'alto',
      'detalle', 'Documentos en estado Pendiente: ' || string_agg(d.nombre, ', '),
      'documentos_faltantes', to_jsonb(array_agg(d.nombre))
    ) AS h
    FROM emb e
    JOIN documentos_embarque d ON d.embarque_id = e.id AND d.deleted_at IS NULL
    WHERE e.estado IN ('En Aduana','Llegada','Arribo','Entregado','Cerrado')
      AND d.estado = 'Pendiente'
      AND d.nombre = ANY(public._docs_requeridos_por_estado(e.modo::text, e.estado::text))
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  hall_fechas AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'fechas', 'severidad', 'alto',
      'detalle', e.detalle,
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM (
      SELECT e.*, CASE
          WHEN e.estado = 'En Tránsito' AND e.etd IS NULL THEN 'Embarque En Tránsito sin ETD'
          WHEN e.estado = 'En Tránsito' AND e.eta IS NULL THEN 'Embarque En Tránsito sin ETA'
          WHEN e.estado IN ('Entregado','Cerrado') AND e.fecha_llegada_real IS NULL
            THEN 'Embarque ' || e.estado::text || ' sin fecha de llegada real'
        END AS detalle
      FROM emb e
    ) e
    WHERE detalle IS NOT NULL
  ),
  hall_ventas AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'ventas_sin_facturar', 'severidad', 'critico',
      'detalle', COUNT(cv.id) || ' concepto(s) de venta pendientes de facturar (' || to_char(SUM(cv.total),'FM999,999,990.00') || ' ' || COALESCE(MAX(cv.moneda::text),'MXN') || ')',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN conceptos_venta cv ON cv.embarque_id = e.id AND cv.deleted_at IS NULL
    WHERE e.estado IN ('Entregado','Cerrado')
      AND cv.estado_facturacion = 'pendiente'
      AND (e.etd IS NULL OR e.etd >= v_fecha_corte_facturacion)
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  -- M-10 (auditoría v14): total de la línea que no cuadra con cantidad x precio.
  -- Detecta ediciones manuales del total sin recalcular (o al revés).
  ventas_descuadradas AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           COUNT(*) AS n_lineas,
           SUM(ABS(cv.total - ROUND(cv.cantidad * cv.precio_unitario, 2))) AS dif_total,
           MAX(cv.moneda::text) AS moneda
    FROM emb e
    JOIN conceptos_venta cv ON cv.embarque_id = e.id AND cv.deleted_at IS NULL
    WHERE ABS(cv.total - ROUND(cv.cantidad * cv.precio_unitario, 2)) > 0.02
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  hall_venta_descuadrada AS (
    SELECT jsonb_build_object(
      'embarque_id', vd.embarque_id, 'expediente', vd.expediente,
      'cliente_nombre', vd.cliente_nombre, 'modo', vd.modo::text, 'estado', vd.estado::text, 'eta', vd.eta,
      'regla', 'venta_total_descuadrado', 'severidad', 'alto',
      'detalle', vd.n_lineas || ' concepto(s) de venta con total distinto a cantidad x precio (diferencia '
        || to_char(vd.dif_total,'FM999,999,990.00') || ' ' || COALESCE(vd.moneda,'MXN') || ')',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM ventas_descuadradas vd
  ),
  contenedores_descuadrados AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           COUNT(ec.id) AS n_cont,
           ABS(COALESCE(e.peso_kg, 0) - COALESCE(SUM(ec.peso_kg), 0)) AS dif_peso,
           ABS(COALESCE(e.piezas, 0) - COALESCE(SUM(ec.piezas), 0)) AS dif_piezas
    FROM embarques e
    JOIN embarque_contenedores ec ON ec.embarque_id = e.id AND ec.deleted_at IS NULL
    WHERE e.organization_id = p_organization_id
      AND e.deleted_at IS NULL
      AND e.estado <> 'Cancelado'
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta, e.peso_kg, e.piezas
    HAVING (COALESCE(e.peso_kg, 0) > 0 AND COALESCE(SUM(ec.peso_kg), 0) > 0
            AND ABS(COALESCE(e.peso_kg, 0) - SUM(ec.peso_kg)) > GREATEST(1, COALESCE(e.peso_kg, 0) * 0.01))
        OR (COALESCE(e.piezas, 0) > 0 AND COALESCE(SUM(ec.piezas), 0) > 0
            AND COALESCE(e.piezas, 0) <> SUM(ec.piezas))
  ),
  hall_contenedores_descuadrados AS (
    SELECT jsonb_build_object(
      'embarque_id', cd.embarque_id, 'expediente', cd.expediente,
      'cliente_nombre', cd.cliente_nombre, 'modo', cd.modo::text,
      'estado', cd.estado::text, 'eta', cd.eta,
      'regla', 'contenedores_totales_descuadrados', 'severidad', 'medio',
      'detalle', 'Los totales del embarque no cuadran con la suma de sus ' || cd.n_cont
        || ' contenedor(es): diferencia de ' || to_char(cd.dif_peso, 'FM999,999,990.00')
        || ' kg y ' || cd.dif_piezas || ' pieza(s)',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM contenedores_descuadrados cd
  ),
  emb_sin_tc AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           bool_or(cv.moneda::text = 'USD') AS tiene_usd_venta,
           bool_or(cv.moneda::text = 'EUR') AS tiene_eur_venta
    FROM emb e
    JOIN conceptos_venta cv ON cv.embarque_id = e.id AND cv.deleted_at IS NULL
    WHERE cv.moneda::text IN ('USD','EUR')
      AND public.a_mxn(cv.total, cv.moneda::text, e.tipo_cambio_usd, e.tipo_cambio_eur) IS NULL
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  emb_sin_tc_costo AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           bool_or(cc.moneda::text = 'USD') AS tiene_usd_costo,
           bool_or(cc.moneda::text = 'EUR') AS tiene_eur_costo
    FROM emb e
    JOIN conceptos_costo cc ON cc.embarque_id = e.id AND cc.deleted_at IS NULL
    WHERE cc.moneda::text IN ('USD','EUR')
      AND public.a_mxn(cc.monto, cc.moneda::text, e.tipo_cambio_usd, e.tipo_cambio_eur) IS NULL
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  emb_falta_tc AS (
    SELECT COALESCE(v.embarque_id, c.embarque_id) AS embarque_id,
           COALESCE(v.expediente, c.expediente) AS expediente,
           COALESCE(v.cliente_nombre, c.cliente_nombre) AS cliente_nombre,
           COALESCE(v.modo, c.modo) AS modo,
           COALESCE(v.estado, c.estado) AS estado,
           COALESCE(v.eta, c.eta) AS eta,
           COALESCE(v.tiene_usd_venta, false) OR COALESCE(c.tiene_usd_costo, false) AS falta_usd,
           COALESCE(v.tiene_eur_venta, false) OR COALESCE(c.tiene_eur_costo, false) AS falta_eur
    FROM emb_sin_tc v
    FULL OUTER JOIN emb_sin_tc_costo c ON c.embarque_id = v.embarque_id
  ),
  hall_tipo_cambio_faltante AS (
    SELECT jsonb_build_object(
      'embarque_id', f.embarque_id, 'expediente', f.expediente,
      'cliente_nombre', f.cliente_nombre, 'modo', f.modo::text, 'estado', f.estado::text, 'eta', f.eta,
      'regla', 'tipo_cambio_faltante', 'severidad', 'medio',
      'detalle', 'Embarque tiene conceptos en ' ||
        CASE
          WHEN f.falta_usd AND f.falta_eur THEN 'USD y EUR'
          WHEN f.falta_usd THEN 'USD'
          ELSE 'EUR'
        END || ' sin tipo de cambio capturado; el margen no se calcula hasta corregir.',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb_falta_tc f
  ),
  -- M-8 (auditoría v14): la conversión usa la función canónica public.a_mxn
  -- (misma convención MXN por 1 USD / 1 EUR que el resto del sistema). Sin TC
  -- devuelve NULL: la línea no suma y `tc_incompleto` silencia las alertas de
  -- margen (nunca se inventa paridad 1:1).
  ventas_mxn AS (
    SELECT cv.embarque_id,
           SUM(public.a_mxn(cv.total, cv.moneda::text, e.tipo_cambio_usd, e.tipo_cambio_eur)) AS total_mxn,
           COUNT(*) AS n,
           bool_or(public.a_mxn(cv.total, cv.moneda::text, e.tipo_cambio_usd, e.tipo_cambio_eur) IS NULL) AS tc_incompleto
    FROM conceptos_venta cv
    JOIN emb e ON e.id = cv.embarque_id
    WHERE cv.deleted_at IS NULL
    GROUP BY cv.embarque_id
  ),
  costos_mxn AS (
    SELECT cc.embarque_id,
           SUM(public.a_mxn(cc.monto, cc.moneda::text, e.tipo_cambio_usd, e.tipo_cambio_eur)) AS total_mxn,
           COUNT(*) AS n,
           bool_or(public.a_mxn(cc.monto, cc.moneda::text, e.tipo_cambio_usd, e.tipo_cambio_eur) IS NULL) AS tc_incompleto
    FROM conceptos_costo cc
    JOIN emb e ON e.id = cc.embarque_id
    WHERE cc.deleted_at IS NULL
    GROUP BY cc.embarque_id
  ),
  margenes AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo::text AS modo,
           e.estado::text AS estado, e.eta,
           COALESCE(v.total_mxn, 0) AS venta_mxn,
           COALESCE(c.total_mxn, 0) AS costo_mxn,
           COALESCE(v.total_mxn, 0) - COALESCE(c.total_mxn, 0) AS utilidad_mxn,
           CASE WHEN COALESCE(v.total_mxn, 0) = 0 THEN NULL
                ELSE ((COALESCE(v.total_mxn,0) - COALESCE(c.total_mxn,0)) / v.total_mxn) * 100
           END AS margen_pct,
           COALESCE(v.n, 0) AS n_ventas,
           COALESCE(c.n, 0) AS n_costos,
           COALESCE(v.tc_incompleto, false) OR COALESCE(c.tc_incompleto, false) AS tc_incompleto
    FROM emb e
    LEFT JOIN ventas_mxn v ON v.embarque_id = e.id
    LEFT JOIN costos_mxn c ON c.embarque_id = e.id
    WHERE e.estado IN ('Entregado','Cerrado','En Proceso','Llegada','Arribo')
  ),
  hall_margen_neg AS (
    SELECT jsonb_build_object(
      'embarque_id', m.embarque_id, 'expediente', m.expediente,
      'cliente_nombre', m.cliente_nombre, 'modo', m.modo, 'estado', m.estado, 'eta', m.eta,
      'regla', 'margen_negativo', 'severidad', 'critico',
      'detalle', 'Margen negativo: ' || to_char(m.utilidad_mxn,'FM999,999,990.00') || ' MXN',
      'monto_mxn', m.utilidad_mxn,
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM margenes m
    WHERE m.utilidad_mxn < 0
      AND NOT m.tc_incompleto
  ),
  hall_margen_bajo AS (
    SELECT jsonb_build_object(
      'embarque_id', m.embarque_id, 'expediente', m.expediente,
      'cliente_nombre', m.cliente_nombre, 'modo', m.modo, 'estado', m.estado, 'eta', m.eta,
      'regla', 'margen_bajo', 'severidad', 'medio',
      'detalle', 'Margen ' || to_char(m.margen_pct,'FM990.0') || '% por debajo del mínimo (' || v_margen_min_pct || '%)',
      'monto_mxn', m.utilidad_mxn,
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM margenes m
    WHERE m.margen_pct IS NOT NULL
      AND m.margen_pct >= 0
      AND m.margen_pct < v_margen_min_pct
      AND NOT m.tc_incompleto
  ),
  hall_venta_sin_costo AS (
    SELECT jsonb_build_object(
      'embarque_id', m.embarque_id, 'expediente', m.expediente,
      'cliente_nombre', m.cliente_nombre, 'modo', m.modo, 'estado', m.estado, 'eta', m.eta,
      'regla', 'venta_sin_costo', 'severidad', 'alto',
      'detalle', 'Embarque tiene ventas pero ningún costo registrado',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM margenes m
    WHERE m.n_ventas > 0 AND m.n_costos = 0
  ),
  hall_costo_sin_venta AS (
    SELECT jsonb_build_object(
      'embarque_id', m.embarque_id, 'expediente', m.expediente,
      'cliente_nombre', m.cliente_nombre, 'modo', m.modo, 'estado', m.estado, 'eta', m.eta,
      'regla', 'costo_sin_venta', 'severidad', 'alto',
      'detalle', 'Embarque tiene costos pero ninguna venta registrada',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM margenes m
    WHERE m.n_costos > 0 AND m.n_ventas = 0
  ),
  proforma_pend AS (
    SELECT p.embarque_id, p.id AS proforma_id, p.numero, p.created_at
    FROM proformas p
    WHERE p.embarque_id IN (SELECT id FROM emb)
      AND p.deleted_at IS NULL
      AND p.estado_proforma = 'pendiente'
      AND COALESCE(p.estado_aprobacion, 'aprobada') <> 'borrador'
      AND COALESCE(p.total_mxn, 0) > 0
      AND EXISTS (
        SELECT 1 FROM conceptos_venta cv
        WHERE cv.proforma_id = p.id AND cv.deleted_at IS NULL
      )
      AND p.created_at < (now() - (v_dias_prof_venc || ' days')::interval)
  ),
  hall_proforma_vencida AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'proforma_vencida', 'severidad', 'alto',
      'detalle', 'Proforma ' || pp.numero || ' lleva más de ' || v_dias_prof_venc || ' días sin facturar',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN proforma_pend pp ON pp.embarque_id = e.id
  ),
  proforma_borrador AS (
    SELECT p.embarque_id, p.id AS proforma_id, p.numero, p.created_at,
           EXTRACT(DAY FROM (now() - p.created_at))::int AS dias
    FROM proformas p
    WHERE p.embarque_id IN (SELECT id FROM emb)
      AND p.deleted_at IS NULL
      AND p.estado_proforma = 'pendiente'
      AND COALESCE(p.estado_aprobacion, 'aprobada') = 'borrador'
      AND p.created_at < (now() - (v_dias_borrador_abandonado || ' days')::interval)
      AND (
        COALESCE(p.total_mxn, 0) = 0
        OR NOT EXISTS (
          SELECT 1 FROM conceptos_venta cv
          WHERE cv.proforma_id = p.id AND cv.deleted_at IS NULL
        )
      )
  ),
  hall_borrador_abandonado AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'proforma_borrador_abandonada', 'severidad', 'medio',
      'detalle', 'Proforma borrador ' || pb.numero || ' abandonada hace ' || pb.dias || ' días (sin conceptos / total cero)',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN proforma_borrador pb ON pb.embarque_id = e.id
  ),
  proforma_inconsistente AS (
    SELECT DISTINCT p.embarque_id, p.id AS proforma_id, p.numero,
           (SELECT COUNT(*) FROM conceptos_venta cv2
              WHERE cv2.embarque_id = p.embarque_id
                AND cv2.deleted_at IS NULL
                AND cv2.estado_facturacion = 'pendiente'
                AND cv2.proforma_id IS NULL) AS n_pendientes
    FROM proformas p
    WHERE p.embarque_id IN (SELECT id FROM emb)
      AND p.deleted_at IS NULL
      AND p.estado_proforma = 'pendiente'
      AND COALESCE(p.estado_aprobacion, 'aprobada') = 'borrador'
      AND (
        COALESCE(p.total_mxn, 0) = 0
        OR NOT EXISTS (
          SELECT 1 FROM conceptos_venta cv
          WHERE cv.proforma_id = p.id AND cv.deleted_at IS NULL
        )
      )
      AND EXISTS (
        SELECT 1 FROM conceptos_venta cv3
        WHERE cv3.embarque_id = p.embarque_id
          AND cv3.deleted_at IS NULL
          AND cv3.estado_facturacion = 'pendiente'
          AND cv3.proforma_id IS NULL
      )
  ),
  hall_proforma_inconsistente AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'proforma_inconsistente', 'severidad', 'alto',
      'detalle', 'Embarque con ' || pi.n_pendientes || ' concepto(s) pendiente(s) y proforma borrador vacía ' || pi.numero || ' (asignar conceptos o cancelar borrador)',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    JOIN proforma_inconsistente pi ON pi.embarque_id = e.id
  ),
  ult_evento AS (
    SELECT embarque_id, MAX(fecha) AS ult
    FROM eventos_embarque
    WHERE embarque_id IN (SELECT id FROM emb) AND deleted_at IS NULL
    GROUP BY embarque_id
  ),
  hall_huerfano AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'embarque_huerfano', 'severidad', 'medio',
      'detalle', CASE
        WHEN COALESCE(e.operador,'') = ''
          THEN 'Embarque sin operador asignado'
        ELSE 'Embarque sin movimientos en los últimos ' || v_dias_huerfano || ' días'
      END,
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM emb e
    LEFT JOIN ult_evento u ON u.embarque_id = e.id
    WHERE e.estado IN ('Confirmado','En Tránsito','En Aduana','Llegada','Arribo','En Proceso')
      AND (
        COALESCE(e.operador,'') = ''
        OR COALESCE(u.ult, e.fecha_creacion) < (now() - (v_dias_huerfano || ' days')::interval)
      )
  ),
  hall_factura_sin_timbrar AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'factura_sin_timbrar', 'severidad', 'alto',
      'detalle', 'Factura ' || f.numero || ' creada hace ' || EXTRACT(DAY FROM (now() - f.created_at))::int || ' día(s) sin timbrar (estado ' || f.estado::text || ')',
      'documentos_faltantes', '[]'::jsonb,
      'monto_mxn', (f.total * CASE WHEN f.moneda::text = 'MXN' THEN 1 ELSE COALESCE(NULLIF(f.tipo_cambio,0), 1) END)
    ) AS h
    FROM facturas f
    JOIN emb e ON e.id = f.embarque_id
    WHERE f.organization_id = p_organization_id AND f.deleted_at IS NULL
      AND f.uuid_fiscal IS NULL
      AND f.estado IN ('Borrador','Por timbrar')
      AND f.created_at < now() - INTERVAL '48 hours'
  ),
  hall_rep_pendiente AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'rep_pendiente', 'severidad', 'alto',
      'detalle', 'REP pendiente para pago de factura ' || f.numero || ' (registrado hace ' || EXTRACT(DAY FROM (now() - p.created_at))::int || ' día(s))',
      'documentos_faltantes', '[]'::jsonb,
      'monto_mxn', (p.monto_aplicado_factura * CASE WHEN p.moneda::text = 'MXN' THEN 1 ELSE COALESCE(NULLIF(p.tipo_cambio,0), 1) END)
    ) AS h
    FROM pagos_factura p
    JOIN facturas f ON f.id = p.factura_id
    JOIN emb e ON e.id = f.embarque_id
    WHERE p.organization_id = p_organization_id AND p.deleted_at IS NULL
      AND p.estado_rep = 'Pendiente' AND p.uuid_rep IS NULL
      AND p.created_at < now() - INTERVAL '72 hours'
  ),
  hall_factura_cancel_sin_sust AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'factura_cancelada_sin_sustitucion', 'severidad', 'critico',
      'detalle', 'Factura ' || f.numero || ' cancelada motivo 01 sin folio sustituto emitido',
      'documentos_faltantes', '[]'::jsonb,
      'monto_mxn', (f.total * CASE WHEN f.moneda::text = 'MXN' THEN 1 ELSE COALESCE(NULLIF(f.tipo_cambio,0), 1) END)
    ) AS h
    FROM facturas f
    JOIN emb e ON e.id = f.embarque_id
    WHERE f.organization_id = p_organization_id AND f.deleted_at IS NULL
      AND f.estado = 'Cancelada'
      AND f.cancelacion_motivo = '01'
      AND f.sustituida_por IS NULL
      AND COALESCE(f.cancelado_en, f.updated_at) < now() - INTERVAL '24 hours'
  ),
  facturas_saldo AS (
    SELECT f.id,
           f.total - COALESCE((
             SELECT SUM(p.monto_aplicado_factura)
             FROM pagos_factura p
             WHERE p.factura_id = f.id AND p.deleted_at IS NULL
           ), 0) AS saldo
    FROM facturas f
    WHERE f.organization_id = p_organization_id
      AND f.deleted_at IS NULL
      AND f.uuid_fiscal IS NOT NULL
      AND f.estado IN ('Emitida','Vencida','Parcialmente pagada')
  ),
  hall_cxc_vencida AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'cxc_vencida', 'severidad', 'critico',
      'detalle', 'Factura ' || f.numero || ' vencida hace ' || (CURRENT_DATE - f.fecha_vencimiento) || ' día(s); saldo ' || to_char(fs.saldo,'FM999,999,990.00') || ' ' || f.moneda::text,
      'documentos_faltantes', '[]'::jsonb,
      'monto_mxn', (fs.saldo * CASE WHEN f.moneda::text = 'MXN' THEN 1 ELSE COALESCE(NULLIF(f.tipo_cambio,0), 1) END)
    ) AS h
    FROM facturas f
    JOIN facturas_saldo fs ON fs.id = f.id
    JOIN emb e ON e.id = f.embarque_id
    WHERE f.fecha_vencimiento IS NOT NULL
      AND f.fecha_vencimiento < (CURRENT_DATE - (v_dias_cxc_vencida || ' days')::interval)
      AND fs.saldo > 0.01
  ),
  hall_cxp_captura AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'cxp_por_capturar_estancada', 'severidad', 'alto',
      'detalle', 'Factura proveedor ' || COALESCE(pf.folio_proveedor,'(s/folio)') || ' de ' || COALESCE(pf.proveedor_nombre,'(s/n)') || ' en captura hace ' || EXTRACT(DAY FROM (now() - pf.created_at))::int || ' día(s)',
      'documentos_faltantes', '[]'::jsonb,
      'monto_mxn', (pf.total * CASE WHEN pf.moneda::text = 'MXN' THEN 1 ELSE COALESCE(NULLIF(pf.tipo_cambio_usd,0), 1) END)
    ) AS h
    FROM proveedor_facturas pf
    JOIN emb e ON e.id = pf.embarque_id
    WHERE pf.organization_id = p_organization_id
      AND pf.deleted_at IS NULL
      AND pf.estado_captura = 'por_capturar'
      AND pf.created_at < now() - (v_dias_cxp_captura || ' days')::interval
  ),
  hall_cxp_vencida AS (
    SELECT jsonb_build_object(
      'embarque_id', e.id, 'expediente', e.expediente,
      'cliente_nombre', e.cliente_nombre, 'modo', e.modo::text, 'estado', e.estado::text, 'eta', e.eta,
      'regla', 'cxp_vencida', 'severidad', 'critico',
      'detalle', 'CXP ' || COALESCE(pf.folio_proveedor,'(s/folio)') || ' de ' || COALESCE(pf.proveedor_nombre,'(s/n)') || ' vencida hace ' || (CURRENT_DATE - pf.fecha_vencimiento) || ' día(s) por ' || to_char(pf.total,'FM999,999,990.00') || ' ' || pf.moneda::text,
      'documentos_faltantes', '[]'::jsonb,
      'monto_mxn', (pf.total * CASE WHEN pf.moneda::text = 'MXN' THEN 1 ELSE COALESCE(NULLIF(pf.tipo_cambio_usd,0), 1) END)
    ) AS h
    FROM proveedor_facturas pf
    JOIN emb e ON e.id = pf.embarque_id
    WHERE pf.organization_id = p_organization_id
      AND pf.deleted_at IS NULL
      AND pf.estado = 'Vigente'
      AND pf.fecha_vencimiento IS NOT NULL
      AND pf.fecha_vencimiento < (CURRENT_DATE - (v_dias_cxp_vencida || ' days')::interval)
  ),
  contenedores_incompletos AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           COUNT(ec.id) AS n_incompletos
    FROM emb e
    JOIN embarque_contenedores ec ON ec.embarque_id = e.id AND ec.deleted_at IS NULL
    WHERE e.modo = 'Marítimo'
      AND COALESCE(e.tipo_carga::text, '') ILIKE 'FCL%'
      AND e.estado::text IN ('En Tránsito','En Aduana','Llegada','Arribo','Entregado')
      AND (ec.peso_kg IS NULL OR ec.peso_kg <= 0 OR ec.volumen_m3 IS NULL OR ec.volumen_m3 <= 0)
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  hall_contenedor_datos AS (
    SELECT jsonb_build_object(
      'embarque_id', ci.embarque_id, 'expediente', ci.expediente,
      'cliente_nombre', ci.cliente_nombre, 'modo', ci.modo::text, 'estado', ci.estado::text, 'eta', ci.eta,
      'regla', 'contenedor_datos_incompletos', 'severidad', 'alto',
      'detalle', ci.n_incompletos || ' contenedor(es) sin peso o volumen capturado',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM contenedores_incompletos ci
  ),
  contenedores_sin_fechas AS (
    SELECT e.id AS embarque_id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta,
           COUNT(ec.id) AS n_sin_fechas
    FROM emb e
    JOIN embarque_contenedores ec ON ec.embarque_id = e.id AND ec.deleted_at IS NULL
    WHERE e.estado::text IN ('Entregado','Cerrado')
      AND (ec.fecha_descarga IS NULL OR ec.fecha_devolucion IS NULL)
    GROUP BY e.id, e.expediente, e.cliente_nombre, e.modo, e.estado, e.eta
  ),
  hall_contenedor_fechas AS (
    SELECT jsonb_build_object(
      'embarque_id', cf.embarque_id, 'expediente', cf.expediente,
      'cliente_nombre', cf.cliente_nombre, 'modo', cf.modo::text, 'estado', cf.estado::text, 'eta', cf.eta,
      'regla', 'contenedor_fechas_incompletas', 'severidad', 'medio',
      'detalle', cf.n_sin_fechas || ' contenedor(es) sin fecha de descarga o devolución',
      'documentos_faltantes', '[]'::jsonb
    ) AS h
    FROM contenedores_sin_fechas cf
  ),
  todos AS (
    SELECT h FROM hall_docs_faltantes
    UNION ALL SELECT h FROM hall_docs_pendientes
    UNION ALL SELECT h FROM hall_fechas
    UNION ALL SELECT h FROM hall_ventas
    UNION ALL SELECT h FROM hall_margen_neg
    UNION ALL SELECT h FROM hall_margen_bajo
    UNION ALL SELECT h FROM hall_venta_sin_costo
    UNION ALL SELECT h FROM hall_costo_sin_venta
    UNION ALL SELECT h FROM hall_proforma_vencida
    UNION ALL SELECT h FROM hall_borrador_abandonado
    UNION ALL SELECT h FROM hall_proforma_inconsistente
    UNION ALL SELECT h FROM hall_huerfano
    UNION ALL SELECT h FROM hall_factura_sin_timbrar
    UNION ALL SELECT h FROM hall_rep_pendiente
    UNION ALL SELECT h FROM hall_factura_cancel_sin_sust
    UNION ALL SELECT h FROM hall_cxc_vencida
    UNION ALL SELECT h FROM hall_cxp_captura
    UNION ALL SELECT h FROM hall_cxp_vencida
    UNION ALL SELECT h FROM hall_contenedor_datos
    UNION ALL SELECT h FROM hall_contenedor_fechas
    UNION ALL SELECT h FROM hall_tipo_cambio_faltante
    UNION ALL SELECT h FROM hall_venta_descuadrada
    UNION ALL SELECT h FROM hall_contenedores_descuadrados
  )
  SELECT public._audit_embarques_agregar(
    (SELECT COALESCE(jsonb_agg(h), '[]'::jsonb) FROM todos),
    jsonb_build_object(
      'margen_minimo_pct', v_margen_min_pct,
      'dias_proforma_vencida', v_dias_prof_venc,
      'dias_huerfano', v_dias_huerfano,
      'dias_borrador_abandonado', v_dias_borrador_abandonado,
      'dias_cxc_vencida', v_dias_cxc_vencida,
      'dias_cxp_captura', v_dias_cxp_captura,
      'dias_cxp_vencida', v_dias_cxp_vencida
    )
  )
  INTO v_result;
  RETURN v_result;
END;
$$;
CREATE FUNCTION public.auditoria_pfc_huerfanos() RETURNS TABLE(pfc_id uuid, proveedor_factura_id uuid, folio_interno text, embarque_id uuid, expediente text, descripcion text, monto numeric, concepto_costo_id_huerfano uuid, organization_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT pfc.id, pf.id, pf.folio_interno, pf.embarque_id, e.expediente,
         pfc.descripcion, pfc.monto, pfc.concepto_costo_id, pf.organization_id
  FROM public.proveedor_facturas_conceptos pfc
  JOIN public.proveedor_facturas pf ON pf.id = pfc.proveedor_factura_id
  LEFT JOIN public.embarques e ON e.id = pf.embarque_id
  LEFT JOIN public.conceptos_costo cc ON cc.id = pfc.concepto_costo_id
  WHERE pfc.concepto_costo_id IS NOT NULL
    AND cc.id IS NULL
    AND pf.deleted_at IS NULL
  ORDER BY pf.folio_interno, pfc.created_at;
$$;
CREATE FUNCTION public.avanzar_estado_embarque(p_embarque_id uuid, p_nuevo_estado text, p_usuario_email text, p_tipo_evento text, p_descripcion_evento text, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_resp jsonb;
  v_faltantes text[];
  v_flr date;
  v_estado_actual public.estado_embarque;
  v_expediente text;
  v_tipo public.tipo_operacion;
  v_actor_id uuid := auth.uid();
  v_actor_email text;
  v_estados_bloqueantes text[] := ARRAY['En Tránsito','En Aduana','Llegada','Arribo','Entregado','EIR','Cerrado'];
BEGIN
  SELECT email INTO v_actor_email FROM auth.users WHERE id = v_actor_id;
  v_actor_email := COALESCE(v_actor_email, 'usuario:' || COALESCE(v_actor_id::text, 'desconocido'));
  v_resp := public.idempotency_claim(p_request_id, 'avanzar_estado_embarque');
  IF v_resp IS NOT NULL THEN
    -- Claim en vuelo: otra petición con la misma llave la está ejecutando.
    IF v_resp ? '__idempotency_pending' THEN RETURN v_resp; END IF;
    -- Respuesta cacheada de una ejecución anterior: se marca como replay para
    -- que el frontend NO escriba bitácora ni la confunda con un avance real.
    RETURN jsonb_set(COALESCE(v_resp, '{}'::jsonb), '{replay}', 'true'::jsonb, true);
  END IF;
  -- BL-16: misma frase que cerrar_embarque — la papelera no avanza.
  SELECT organization_id, fecha_llegada_real, estado, expediente, tipo
    INTO v_org_id, v_flr, v_estado_actual, v_expediente, v_tipo
  FROM embarques WHERE id = p_embarque_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Embarque no encontrado'; END IF;
  PERFORM public._assert_writer(v_org_id);
  -- QA-R2 D-02: marca que el cambio de estado (incluida la cancelacion) viene
  -- de esta RPC; el trigger embarques_assert_cancelacion_sin_cxc_cxp exige la
  -- GUC para cancelar y aplica la misma validacion CxC/CxP en escritura directa.
  PERFORM set_config('app.via_rpc_estado', '1', true);
  -- B-01: no cancelar una operación que todavía conserva CxC o CxP vivas.
  IF p_nuevo_estado = 'Cancelado' THEN
    IF EXISTS (
      SELECT 1 FROM public.facturas f
      WHERE f.embarque_id = p_embarque_id
        AND f.deleted_at IS NULL
        AND f.estado IN ('Emitida', 'Vencida', 'Parcialmente pagada')
    ) THEN
      RAISE EXCEPTION 'LC_CANCEL_CON_CXC: cancela o sustituye las facturas de cliente antes de cancelar el embarque'
        USING ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.proveedor_facturas pf
      WHERE pf.embarque_id = p_embarque_id
        AND pf.deleted_at IS NULL
        AND pf.estado <> 'Cancelada'
    ) THEN
      RAISE EXCEPTION 'LC_CANCEL_CON_CXP: cancela las facturas de proveedor antes de cancelar el embarque'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  PERFORM public.assert_transicion_embarque(v_estado_actual, p_nuevo_estado::public.estado_embarque, v_expediente);
  -- v13.303.42: al confirmar un borrador sin folio, reservar expediente ahora.
  IF v_estado_actual = 'Borrador'::estado_embarque
     AND p_nuevo_estado = 'Confirmado'
     AND (v_expediente IS NULL OR v_expediente = '') THEN
    v_expediente := public.generar_expediente(coalesce(v_tipo::text, ''));
    UPDATE embarques SET expediente = v_expediente WHERE id = p_embarque_id;
  END IF;
  IF p_nuevo_estado = 'Cerrado' THEN
    PERFORM public.cerrar_embarque(p_embarque_id);
    PERFORM set_config('app.bypass_cierre','on', true);
    INSERT INTO notas_embarque (embarque_id, contenido, tipo, usuario, organization_id)
    VALUES (p_embarque_id, 'Estado cambiado a "Cerrado"', 'cambio_estado'::tipo_nota, v_actor_email, v_org_id);
    INSERT INTO eventos_embarque (embarque_id, tipo, descripcion, ubicacion, fecha, usuario, organization_id)
    VALUES (p_embarque_id, p_tipo_evento::tipo_evento_tracking, p_descripcion_evento, '', now(), v_actor_email, v_org_id);
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, modulo, accion, entidad_id, entidad_nombre, detalles)
    VALUES
      (v_org_id, v_actor_id, v_actor_email, 'Embarques', 'Cambio de estado', p_embarque_id,
       v_expediente, jsonb_build_object('estado_anterior', v_estado_actual, 'estado_nuevo', 'Cerrado'));
    PERFORM set_config('app.bypass_cierre','off', true);
    v_resp := jsonb_build_object('id', p_embarque_id, 'estado', 'Cerrado');
    PERFORM public.idempotency_store(p_request_id, v_resp);
    RETURN v_resp;
  END IF;
  IF p_nuevo_estado = 'Arribo' AND v_flr IS NULL THEN
    RAISE EXCEPTION 'fecha_llegada_real_requerida'
      USING ERRCODE = 'P0001';
  END IF;
  IF p_nuevo_estado = ANY(v_estados_bloqueantes) THEN
    v_faltantes := public.embarque_docs_faltantes(p_embarque_id, p_nuevo_estado);
    IF array_length(v_faltantes, 1) IS NOT NULL THEN
      RAISE EXCEPTION 'documentos_faltantes: %', array_to_string(v_faltantes, ', ')
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  -- BUG-10: guarda optimista — el FOR UPDATE del SELECT inicial bloquea la
  -- fila, pero se conserva el predicado de estado como segunda línea de defensa.
  UPDATE embarques
     SET estado = p_nuevo_estado::estado_embarque, updated_at = now()
   WHERE id = p_embarque_id
     AND estado = v_estado_actual;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_ESTADO_CONCURRENTE: el embarque cambió de estado durante la transición'
      USING ERRCODE = '40001';
  END IF;
  -- QA-R2 R-02: al cancelar, liberar las cotizaciones ligadas al embarque.
  -- La reversión 'En operación' → 'Aceptada' es housekeeping (mismo patrón
  -- que la papelera: GUC app.liberando_papelera ante guard_estado_cotizacion);
  -- no se tocan subtotal/moneda/conceptos, así que el guard de cotización
  -- congelada no aplica.
  IF p_nuevo_estado = 'Cancelado' THEN
    PERFORM set_config('app.liberando_papelera', 'on', true);
    UPDATE public.cotizaciones
       SET embarque_id = NULL,
           estado = CASE
             WHEN estado = 'En operación'::estado_cotizacion
               THEN 'Aceptada'::estado_cotizacion
             ELSE estado
           END,
           updated_at = now()
     WHERE embarque_id = p_embarque_id
       AND organization_id = v_org_id;
    PERFORM set_config('app.liberando_papelera', 'off', true);
  END IF;
  INSERT INTO notas_embarque (embarque_id, contenido, tipo, usuario, organization_id)
  VALUES (p_embarque_id, 'Estado cambiado a "' || p_nuevo_estado || '"', 'cambio_estado'::tipo_nota, v_actor_email, v_org_id);
  INSERT INTO eventos_embarque (embarque_id, tipo, descripcion, ubicacion, fecha, usuario, organization_id)
  VALUES (p_embarque_id, p_tipo_evento::tipo_evento_tracking, p_descripcion_evento, '', now(), v_actor_email, v_org_id);
  INSERT INTO public.bitacora_actividad
    (organization_id, usuario_id, usuario_email, modulo, accion, entidad_id, entidad_nombre, detalles)
  VALUES
    (v_org_id, v_actor_id, v_actor_email, 'Embarques', 'Cambio de estado', p_embarque_id,
     v_expediente, jsonb_build_object('estado_anterior', v_estado_actual, 'estado_nuevo', p_nuevo_estado));
  v_resp := jsonb_build_object('id', p_embarque_id, 'estado', p_nuevo_estado, 'expediente', v_expediente);
  PERFORM public.idempotency_store(p_request_id, v_resp);
  RETURN v_resp;
END;
$$;
CREATE FUNCTION public.backfill_conceptos_venta_facturados() RETURNS TABLE(organization_id uuid, conceptos_actualizados bigint, embarques_afectados bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM set_config('app.auditoria_backfill_legacy', 'on', true);
  RETURN QUERY
  WITH candidatos AS (
    SELECT cv.id AS concepto_id,
           cv.embarque_id,
           e.organization_id
    FROM public.conceptos_venta cv
    JOIN public.embarques e ON e.id = cv.embarque_id
    WHERE cv.estado_facturacion = 'pendiente'
      AND e.estado IN ('Entregado','Cerrado')
      AND EXISTS (
        SELECT 1
        FROM public.facturas f
        WHERE f.embarque_id = cv.embarque_id
          AND f.estado IN ('Emitida','Pagada','Parcialmente pagada')
      )
  ), actualizados AS (
    UPDATE public.conceptos_venta cv
       SET estado_facturacion = 'facturado'
      FROM candidatos c
     WHERE cv.id = c.concepto_id
    RETURNING cv.id, c.embarque_id, c.organization_id
  )
  SELECT a.organization_id,
         COUNT(*)::bigint AS conceptos_actualizados,
         COUNT(DISTINCT a.embarque_id)::bigint AS embarques_afectados
  FROM actualizados a
  GROUP BY a.organization_id;
  PERFORM set_config('app.auditoria_backfill_legacy', 'off', true);
END;
$$;
CREATE FUNCTION public.backfill_proformas_aceptadas() RETURNS TABLE(organization_id uuid, proformas_actualizadas bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH actualizadas AS (
    UPDATE public.proformas p
       SET estado_proforma = 'facturada'
      FROM public.embarques e
     WHERE p.embarque_id = e.id
       AND p.estado_proforma = 'pendiente'
       AND EXISTS (
         SELECT 1 FROM public.facturas f
         WHERE f.embarque_id = p.embarque_id
           AND f.estado IN ('Emitida','Pagada','Parcialmente pagada')
       )
    RETURNING p.id, e.organization_id
  )
  SELECT a.organization_id, COUNT(*)::bigint
  FROM actualizadas a
  GROUP BY a.organization_id;
END;
$$;
CREATE FUNCTION public.backfill_tc_dof_documentos(_simulacion boolean DEFAULT true) RETURNS TABLE(tabla text, actualizados integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := public.current_user_org_id();
  v_uid uuid := auth.uid();
  v_email text := COALESCE(auth.jwt() ->> 'email', 'sistema');
  v_fac integer := 0;
  v_pf integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_SIN_CONTEXTO: sesion requerida' USING ERRCODE = '42501';
  END IF;
  IF NOT (public.has_role(v_uid, 'super_admin'::app_role) OR public.can_admin_tenant()) THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: solo administradores pueden regularizar tipos de cambio'
      USING ERRCODE = '42501';
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_SIN_CONTEXTO: organizacion activa requerida' USING ERRCODE = '42501';
  END IF;
  WITH cand AS (
    SELECT f.id, t.tc
    FROM public.facturas f
    CROSS JOIN LATERAL public.tc_para_documento(f.fecha_emision, f.moneda::text, NULL, NULL) t
    WHERE f.deleted_at IS NULL
      AND f.organization_id = v_org
      AND f.moneda::text <> 'MXN'
      AND COALESCE(f.tipo_cambio, 0) <= 1
      AND t.origen = 'dof'
  ), upd AS (
    UPDATE public.facturas f
       SET tipo_cambio = c.tc
      FROM cand c
     WHERE f.id = c.id AND NOT _simulacion
    RETURNING f.id
  )
  SELECT CASE WHEN _simulacion THEN (SELECT count(*) FROM cand) ELSE (SELECT count(*) FROM upd) END
    INTO v_fac;
  WITH cand AS (
    SELECT pf.id, t.tc
    FROM public.proveedor_facturas pf
    CROSS JOIN LATERAL public.tc_para_documento(pf.fecha_emision, pf.moneda::text, NULL, NULL) t
    WHERE pf.deleted_at IS NULL
      AND pf.organization_id = v_org
      AND pf.moneda::text <> 'MXN'
      AND COALESCE(pf.tipo_cambio_usd, 0) <= 1
      AND t.origen = 'dof'
  ), upd AS (
    UPDATE public.proveedor_facturas pf
       SET tipo_cambio_usd = c.tc
      FROM cand c
     WHERE pf.id = c.id AND NOT _simulacion
    RETURNING pf.id
  )
  SELECT CASE WHEN _simulacion THEN (SELECT count(*) FROM cand) ELSE (SELECT count(*) FROM upd) END
    INTO v_pf;
  IF NOT _simulacion AND (v_fac > 0 OR v_pf > 0) THEN
    INSERT INTO public.bitacora_actividad
      (usuario_id, usuario_email, accion, modulo, entidad_nombre, detalles, organization_id)
    VALUES
      (v_uid, v_email, 'backfill_tc_dof', 'finanzas', 'Regularizacion de tipos de cambio DOF',
       jsonb_build_object('facturas', v_fac, 'proveedor_facturas', v_pf), v_org);
  END IF;
  RETURN QUERY SELECT 'facturas'::text, v_fac
               UNION ALL
               SELECT 'proveedor_facturas'::text, v_pf;
END;
$$;
CREATE FUNCTION public.bloquear_conceptos_en_embarque_cerrado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado text;
BEGIN
  IF current_setting('app.bypass_cierre', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  SELECT estado::text INTO v_estado
  FROM public.embarques
  WHERE id = COALESCE(NEW.embarque_id, OLD.embarque_id);
  IF v_estado = 'Cerrado' THEN
    IF TG_OP = 'UPDATE' AND NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
      RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE'
       AND current_setting('app.auditoria_backfill_legacy', true) = 'on'
       AND OLD.estado_facturacion = 'pendiente'
       AND NEW.estado_facturacion = 'facturado'
       AND (to_jsonb(NEW) - 'estado_facturacion') = (to_jsonb(OLD) - 'estado_facturacion') THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'No se pueden agregar ni modificar conceptos en un embarque Cerrado. Reabre el embarque antes de editar.'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.bloquear_modificacion_factura_emitida() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.snapshot_emision IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.estado = 'Cancelada' AND OLD.estado <> 'Cancelada' THEN
    RETURN NEW;
  END IF;
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
    RETURN NEW;
  END IF;
  -- OLA 1 · C8 + Ola E1 · C8-res: la identidad fiscal (UUID SAT, id del PAC,
  -- artefactos XML/PDF y fecha de timbrado) sólo puede escribirla el servidor
  -- (webhook/edge con credencial de servicio).
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF NEW.uuid_fiscal IS DISTINCT FROM OLD.uuid_fiscal
     OR NEW.facturapi_id IS DISTINCT FROM OLD.facturapi_id
     OR NEW.factura_xml_url IS DISTINCT FROM OLD.factura_xml_url
     OR NEW.factura_pdf_url IS DISTINCT FROM OLD.factura_pdf_url
     OR NEW.timbrado_en IS DISTINCT FROM OLD.timbrado_en
    THEN
      RAISE EXCEPTION 'factura_inmutable: la identidad fiscal de la factura % no puede modificarse desde la aplicación.', OLD.numero
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.numero        IS DISTINCT FROM OLD.numero
   OR NEW.subtotal     IS DISTINCT FROM OLD.subtotal
   OR NEW.iva          IS DISTINCT FROM OLD.iva
   OR NEW.total        IS DISTINCT FROM OLD.total
   OR NEW.moneda       IS DISTINCT FROM OLD.moneda
   OR NEW.tipo_cambio  IS DISTINCT FROM OLD.tipo_cambio
   OR NEW.fecha_emision IS DISTINCT FROM OLD.fecha_emision
   OR NEW.cliente_id   IS DISTINCT FROM OLD.cliente_id
   OR NEW.embarque_id  IS DISTINCT FROM OLD.embarque_id
   OR NEW.proforma_id  IS DISTINCT FROM OLD.proforma_id
  THEN
    RAISE EXCEPTION 'factura_inmutable: la factura % ya fue emitida y no puede modificarse. Emite una nota de crédito.', OLD.numero
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.buscar_factura_proveedor_por_uuid(p_uuid text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := public.current_user_org_id();
  v_uuid text := NULLIF(upper(btrim(COALESCE(p_uuid, ''))), '');
  v_out jsonb := NULL;
BEGIN
  IF v_uuid IS NULL THEN
    RETURN NULL;
  END IF;
  IF NOT (public.has_role(auth.uid(), 'contador')
          OR public.has_role(auth.uid(), 'auxiliar_contable')
          OR public.has_role(auth.uid(), 'tesorero')
          OR public.has_role(auth.uid(), 'admin')
          OR public.has_role(auth.uid(), 'admin_org')
          OR public.has_role(auth.uid(), 'super_admin')) THEN
    RETURN NULL;
  END IF;
  SELECT jsonb_build_object(
           'id', f.id,
           'folio_interno', f.folio_interno,
           'folio_proveedor', f.folio_proveedor,
           'proveedor_nombre', f.proveedor_nombre,
           'estado', f.estado,
           'estado_aprobacion', f.estado_aprobacion)
    INTO v_out
    FROM public.proveedor_facturas f
   WHERE upper(btrim(f.uuid_fiscal)) = v_uuid
     AND f.deleted_at IS NULL
     AND (f.organization_id = v_org OR public.has_role(auth.uid(), 'super_admin'))
   LIMIT 1;
  RETURN v_out;
END;
$$;
CREATE FUNCTION public.busqueda_global(termino text, limite integer DEFAULT 5) RETURNS TABLE(id uuid, label text, sublabel text, tipo text, url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
   (SELECT DISTINCT ON (e.expediente)
           e.id, e.expediente AS label,
           (e.cliente_nombre
             || CASE
                  WHEN e.bl_master IS NOT NULL AND e.bl_master ILIKE '%' || termino || '%' AND e.expediente NOT ILIKE '%' || termino || '%'
                    THEN ' · BL/M ' || e.bl_master
                  WHEN e.bl_house IS NOT NULL AND e.bl_house ILIKE '%' || termino || '%' AND e.expediente NOT ILIKE '%' || termino || '%'
                    THEN ' · BL/H ' || e.bl_house
                  WHEN COUNT(*) OVER (PARTITION BY e.expediente) > 1
                    THEN ' · ' || COUNT(*) OVER (PARTITION BY e.expediente) || ' contenedores'
                  ELSE ''
                END) AS sublabel,
           'embarque'::text AS tipo,
           '/embarques/' || e.id AS url
    FROM embarques e
    WHERE (e.expediente ILIKE '%' || termino || '%'
           OR e.bl_master ILIKE '%' || termino || '%'
           OR e.bl_house  ILIKE '%' || termino || '%')
      AND e.deleted_at IS NULL
      AND e.organization_id = public.org_scope()
    ORDER BY e.expediente, e.created_at ASC
    LIMIT limite)
   UNION ALL
   (SELECT cl.id, cl.nombre AS label, cl.rfc AS sublabel, 'cliente'::text AS tipo, '/clientes/' || cl.id AS url
    FROM clientes cl WHERE (cl.nombre ILIKE '%' || termino || '%' OR cl.rfc ILIKE '%' || termino || '%')
      AND cl.deleted_at IS NULL
      AND cl.organization_id = public.org_scope()
    LIMIT limite)
   UNION ALL
   (SELECT p.id, p.nombre AS label, p.rfc AS sublabel, 'proveedor'::text AS tipo, '/proveedores/' || p.id AS url
    FROM proveedores p WHERE (p.nombre ILIKE '%' || termino || '%' OR p.rfc ILIKE '%' || termino || '%')
      -- Ola 4 · N48: filtro que faltaba (las demás ramas ya lo tenían).
      AND p.deleted_at IS NULL
      AND p.organization_id = public.org_scope()
    LIMIT limite)
   UNION ALL
   (SELECT f.id, f.numero AS label, f.cliente_nombre AS sublabel, 'factura'::text AS tipo, '/facturacion/' || f.id AS url
    FROM facturas f WHERE (f.numero ILIKE '%' || termino || '%' OR f.cliente_nombre ILIKE '%' || termino || '%')
      AND f.deleted_at IS NULL
      AND f.organization_id = public.org_scope()
    LIMIT limite)
   UNION ALL
   (SELECT c.id, c.folio AS label, c.cliente_nombre AS sublabel, 'cotizacion'::text AS tipo, '/cotizaciones/' || c.id AS url
    FROM cotizaciones c WHERE (c.folio ILIKE '%' || termino || '%' OR c.cliente_nombre ILIKE '%' || termino || '%' OR c.prospecto_empresa ILIKE '%' || termino || '%')
      AND c.deleted_at IS NULL
      AND c.organization_id = public.org_scope()
    LIMIT limite)
   UNION ALL
   (SELECT pr.id, pr.numero AS label,
           (pr.cliente_nombre || ' · ' || pr.expediente) AS sublabel,
           'proforma'::text AS tipo,
           '/proformas/' || pr.id AS url
    FROM proformas pr
    WHERE (pr.numero ILIKE '%' || termino || '%'
           OR pr.cliente_nombre ILIKE '%' || termino || '%'
           OR pr.expediente ILIKE '%' || termino || '%')
      AND pr.deleted_at IS NULL
      AND pr.organization_id = public.org_scope()
    LIMIT limite)
   UNION ALL
   -- B-062: matchear también por folio_interno (FI-…) — es el folio que la UI
   -- muestra en todas las listas CxP; buscar por él antes devolvía vacío.
   (SELECT pf.id,
           COALESCE(pf.folio_interno, pf.folio_proveedor) AS label,
           (pf.proveedor_nombre
              || COALESCE(' · ' || pv.rfc, '')
              || CASE
                   WHEN pf.folio_interno IS NOT NULL AND pf.folio_proveedor IS NOT NULL
                        AND pf.folio_interno IS DISTINCT FROM pf.folio_proveedor
                     THEN ' · Prov ' || pf.folio_proveedor
                   ELSE ''
                 END) AS sublabel,
           'factura_proveedor'::text AS tipo,
           '/cxp?factura=' || pf.id AS url
    FROM proveedor_facturas pf
    LEFT JOIN proveedores pv ON pv.id = pf.proveedor_id
    WHERE pf.estado <> 'Cancelada'
      AND pf.deleted_at IS NULL
      AND (pf.folio_proveedor ILIKE '%' || termino || '%'
           OR pf.folio_interno ILIKE '%' || termino || '%'
           OR pf.proveedor_nombre ILIKE '%' || termino || '%'
           OR pv.rfc ILIKE '%' || termino || '%')
      AND pf.organization_id = public.org_scope()
    LIMIT limite);
$$;
CREATE FUNCTION public.buzon_localizar_duplicado(p_hash text DEFAULT NULL::text, p_columna text DEFAULT 'archivo_hash'::text, p_uuid_fiscal text DEFAULT NULL::text, p_embarque_id uuid DEFAULT NULL::uuid) RETURNS TABLE(caso text, factura_id uuid, embarque_id uuid, embarque_expediente text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := public.current_user_org_id();
  v_super boolean := public.has_role(auth.uid(), 'super_admin');
  v_uuid text := nullif(upper(btrim(coalesce(p_uuid_fiscal, ''))), '');
  v_hash text := nullif(btrim(coalesce(p_hash, '')), '');
  v_doc public.embarque_facturas_entrantes%ROWTYPE;
  v_fac public.proveedor_facturas%ROWTYPE;
  v_visible boolean;
  v_emb_id uuid;
  v_exp text;
BEGIN
  IF p_columna NOT IN ('archivo_hash', 'xml_hash') THEN
    RAISE EXCEPTION 'LC_ARG_INVALIDO: columna de hash no soportada';
  END IF;
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: sesión requerida';
  END IF;
  IF v_hash IS NULL AND v_uuid IS NULL THEN
    RETURN;
  END IF;
  SELECT * INTO v_doc
    FROM public.embarque_facturas_entrantes d
   WHERE d.deleted_at IS NULL
     AND (
       (v_hash IS NOT NULL AND p_columna = 'archivo_hash' AND d.archivo_hash = v_hash)
       OR (v_hash IS NOT NULL AND p_columna = 'xml_hash' AND d.xml_hash = v_hash)
       OR (v_uuid IS NOT NULL AND upper(btrim(d.uuid_fiscal)) = v_uuid)
     )
   ORDER BY (d.estado = 'capturada') DESC, d.created_at
   LIMIT 1;
  IF FOUND THEN
    v_visible := v_super OR v_doc.organization_id = v_org;
    IF NOT v_visible THEN
      RETURN QUERY SELECT 'ajeno'::text, NULL::uuid, NULL::uuid, NULL::text;
      RETURN;
    END IF;
    IF v_doc.estado <> 'capturada' THEN
      RETURN QUERY SELECT 'buzon_pendiente'::text, NULL::uuid, v_doc.embarque_id, NULL::text;
      RETURN;
    END IF;
    SELECT * INTO v_fac FROM public.proveedor_facturas f
      WHERE f.id = v_doc.proveedor_factura_id AND f.deleted_at IS NULL;
  END IF;
  IF v_fac.id IS NULL AND v_uuid IS NOT NULL THEN
    SELECT * INTO v_fac FROM public.proveedor_facturas f
      WHERE f.deleted_at IS NULL AND upper(btrim(f.uuid_fiscal)) = v_uuid
      LIMIT 1;
    IF FOUND AND NOT (v_super OR v_fac.organization_id = v_org) THEN
      RETURN QUERY SELECT 'ajeno'::text, NULL::uuid, NULL::uuid, NULL::text;
      RETURN;
    END IF;
  END IF;
  IF v_fac.id IS NULL THEN
    IF v_doc.id IS NOT NULL THEN
      RETURN QUERY SELECT 'sin_embarque'::text, NULL::uuid, NULL::uuid, NULL::text;
    END IF;
    RETURN;
  END IF;
  v_emb_id := coalesce(v_fac.embarque_id, v_doc.embarque_id);
  IF v_emb_id IS NULL THEN
    RETURN QUERY SELECT 'sin_embarque'::text, v_fac.id, NULL::uuid, NULL::text;
    RETURN;
  END IF;
  SELECT e.expediente INTO v_exp FROM public.embarques e
    WHERE e.id = v_emb_id AND e.deleted_at IS NULL
      AND (v_super OR e.organization_id = v_org);
  IF p_embarque_id IS NOT NULL AND v_emb_id = p_embarque_id THEN
    RETURN QUERY SELECT 'mismo_embarque'::text, v_fac.id, v_emb_id, v_exp;
  ELSE
    RETURN QUERY SELECT 'otro_embarque'::text, v_fac.id, v_emb_id, v_exp;
  END IF;
END;
$$;
CREATE FUNCTION public.calc_cancelacion_vence(p_solicitada timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fin timestamptz := p_solicitada + interval '72 hours';
  v_curr timestamptz := p_solicitada;
  v_extra_days int := 0;
BEGIN
  -- Aproximación: por cada finde en el rango original + 72 h, sumar 2 días
  WHILE v_curr < v_fin LOOP
    IF EXTRACT(dow FROM v_curr) IN (0, 6) THEN
      v_extra_days := v_extra_days + 1;
    END IF;
    v_curr := v_curr + interval '24 hours';
  END LOOP;
  RETURN v_fin + (v_extra_days || ' hours')::interval;
END;
$$;
CREATE FUNCTION public.calc_concepto_retenciones() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_subtotal numeric;
BEGIN
  v_subtotal := COALESCE(NEW.cantidad, 1) * COALESCE(NEW.precio_unitario, 0);
  NEW.monto_ret_isr := ROUND(v_subtotal * COALESCE(NEW.tasa_ret_isr, 0), 2);
  NEW.monto_ret_iva := ROUND(v_subtotal * COALESCE(NEW.tasa_ret_iva, 0), 2);
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.calc_fecha_limite_devolucion_garantia() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dias int;
  v_dias_tarifa int;
  v_org_id uuid;
  v_tarifa_id uuid;
BEGIN
  IF NEW.fecha_deposito IS NULL OR NEW.naviera_id IS NULL THEN
    NEW.fecha_limite_devolucion := NULL;
    RETURN NEW;
  END IF;
  SELECT e.organization_id, e.tarifa_id_aplicada INTO v_org_id, v_tarifa_id
  FROM embarques e WHERE e.id = NEW.embarque_id;
  IF v_tarifa_id IS NOT NULL THEN
    SELECT t.dias_libres_demoras INTO v_dias_tarifa
    FROM costeo_tarifas t WHERE t.id = v_tarifa_id;
  END IF;
  IF v_dias_tarifa IS NOT NULL AND v_dias_tarifa > 0 THEN
    v_dias := v_dias_tarifa;
  ELSE
    SELECT nc.dias_libres_demoras_default INTO v_dias
    FROM costeo_navieras_condiciones nc
    WHERE nc.naviera_id = NEW.naviera_id
      AND nc.organization_id = v_org_id
    LIMIT 1;
  END IF;
  IF v_dias IS NULL THEN
    NEW.fecha_limite_devolucion := NULL;
  ELSE
    NEW.fecha_limite_devolucion := NEW.fecha_deposito + (v_dias || ' days')::interval;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.calc_pago_retenciones() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fac_subtotal numeric; v_fac_iva numeric;
  v_fac_ret_isr numeric; v_fac_ret_iva numeric;
  v_ncs numeric; v_base numeric; v_ratio numeric; v_monto numeric;
  v_prev_isr numeric; v_prev_iva numeric; v_prev_monto numeric;
BEGIN
  IF COALESCE(NEW.ret_isr,0) > 0 OR COALESCE(NEW.ret_iva,0) > 0 THEN RETURN NEW; END IF;
  SELECT COALESCE(subtotal,0), COALESCE(iva,0), COALESCE(ret_isr,0), COALESCE(ret_iva,0)
    INTO v_fac_subtotal, v_fac_iva, v_fac_ret_isr, v_fac_ret_iva
    FROM public.facturas WHERE id = NEW.factura_id;
  IF COALESCE(v_fac_ret_isr,0) = 0 AND COALESCE(v_fac_ret_iva,0) = 0 THEN
    RETURN NEW;
  END IF;
  -- N10: la base debe ser neta de las NC ya aplicadas (misma moneda de la
  -- factura); antes se prorrateaba contra el total bruto y las retenciones
  -- sumaban más de lo retenido realmente.
  v_ncs := COALESCE(public.nc_aplicadas_en_moneda_factura(NEW.factura_id), 0);
  v_base := v_fac_subtotal + v_fac_iva - v_fac_ret_iva - v_fac_ret_isr - v_ncs;
  -- FIX-R4-05: si monto_aplicado_factura aún no llegó (otro trigger BEFORE lo poblará),
  -- usar NEW.monto como base para prorratear las retenciones.
  v_monto := COALESCE(NULLIF(NEW.monto_aplicado_factura,0), NEW.monto);
  IF v_base <= 0 OR COALESCE(v_monto,0) <= 0 THEN
    RETURN NEW;
  END IF;
  SELECT COALESCE(SUM(COALESCE(p.ret_isr,0)),0),
         COALESCE(SUM(COALESCE(p.ret_iva,0)),0),
         COALESCE(SUM(COALESCE(NULLIF(p.monto_aplicado_factura,0), p.monto)),0)
    INTO v_prev_isr, v_prev_iva, v_prev_monto
    FROM public.pagos_factura p
   WHERE p.factura_id = NEW.factura_id
     AND p.deleted_at IS NULL
     AND p.id IS DISTINCT FROM NEW.id;
  IF v_prev_monto + v_monto >= v_base - 0.01 THEN
    -- Pago liquidador: absorbe el residuo de centavos del prorrateo.
    NEW.ret_isr := GREATEST(ROUND(v_fac_ret_isr - v_prev_isr, 2), 0);
    NEW.ret_iva := GREATEST(ROUND(v_fac_ret_iva - v_prev_iva, 2), 0);
  ELSE
    v_ratio := v_monto / v_base;
    NEW.ret_isr := ROUND(v_fac_ret_isr * v_ratio, 2);
    NEW.ret_iva := ROUND(v_fac_ret_iva * v_ratio, 2);
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.calcular_comision_pago() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_factura public.facturas%ROWTYPE;
  v_emb public.embarques%ROWTYPE;
  v_tc numeric;
  v_moneda text;
  v_mxn numeric;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_factura FROM public.facturas WHERE id = NEW.factura_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  v_moneda := COALESCE(NEW.moneda::text, v_factura.moneda::text, 'MXN');
  v_tc := NULLIF(NEW.tipo_cambio, 0);
  -- FIX-R4-12: TC=1 en moneda extranjera es imposible; buscar TC real del embarque.
  IF v_moneda IN ('USD','EUR') AND (v_tc IS NULL OR v_tc = 1) THEN
    IF v_factura.embarque_id IS NOT NULL THEN
      SELECT * INTO v_emb FROM public.embarques WHERE id = v_factura.embarque_id;
      IF v_moneda = 'USD' THEN v_tc := NULLIF(v_emb.tipo_cambio_usd, 0); END IF;
      IF v_moneda = 'EUR' THEN v_tc := NULLIF(v_emb.tipo_cambio_eur, 0); END IF;
    END IF;
    IF v_tc IS NULL OR v_tc = 1 THEN
      v_tc := NULLIF(v_factura.tipo_cambio, 0);
    END IF;
  END IF;
  IF v_moneda = 'MXN' THEN
    v_mxn := COALESCE(NEW.monto, 0);
  ELSE
    v_mxn := COALESCE(NEW.monto, 0) * COALESCE(v_tc, 1);
  END IF;
  NEW.monto_cobrado_mxn := ROUND(v_mxn, 2);
  RETURN NEW;
END $$;
CREATE FUNCTION public.calcular_comision_pago(p_pago_factura_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pago RECORD; v_factura RECORD;
  v_emb_ids uuid[]; v_emb_vivos uuid[];
  v_embarque_id uuid; v_vendedora_id uuid; v_vendedoras uuid[];
  v_tc_usd numeric; v_tc_eur numeric;
  v_pct numeric(5,2); v_ingresos_mxn numeric(14,2); v_costos_mxn numeric(14,2);
  v_utilidad numeric(14,2); v_cobrado_mxn numeric(14,2);
  v_proporcion numeric(14,8); v_comision_mxn numeric(14,2); v_nota text;
  v_tc_pago numeric; v_tc_factura numeric;
  v_req_usd boolean := false; v_req_eur boolean := false;
  v_cliente_id uuid;
  v_venta_neta_mxn numeric(14,2);
  v_cobrado_acotado numeric(14,2);
BEGIN
  SELECT * INTO v_pago FROM pagos_factura WHERE id = p_pago_factura_id;
  IF NOT FOUND OR v_pago.deleted_at IS NOT NULL THEN
    UPDATE comisiones_devengadas
       SET estado = 'Cancelada', comision_mxn = 0
     WHERE pago_factura_id = p_pago_factura_id AND estado <> 'Liquidada';
    -- QA-R2 N-07: el pago (respaldo) desaparece pero la comision ya fue
    -- liquidada: no se cancela en silencio, se marca para recuperacion.
    UPDATE comisiones_devengadas
       SET estado = 'Por recuperar',
           nota = trim(both ' ' FROM COALESCE(nota,'') || ' [auto] pago eliminado con comision liquidada'),
           updated_at = now()
     WHERE pago_factura_id = p_pago_factura_id AND estado = 'Liquidada';
    RETURN;
  END IF;
  SELECT * INTO v_factura FROM facturas WHERE id = v_pago.factura_id;
  IF NOT FOUND THEN RETURN; END IF;
  -- O2.4: embarque directo o embarques del puente consolidado.
  v_emb_ids := COALESCE(public.comision_embarques_de_factura(v_factura.id), ARRAY[]::uuid[]);
  IF COALESCE(array_length(v_emb_ids, 1), 0) = 0 THEN
    -- Antes: comisión 0 en silencio. Ahora queda en la cola de recálculo.
    PERFORM public.registrar_comision_pendiente(
      v_pago.organization_id, v_pago.id, 'consolidada_sin_embarque',
      'La factura no tiene embarque directo ni vinculo activo en factura_embarques',
      '', '');
    INSERT INTO comisiones_devengadas (
      organization_id, pago_factura_id, embarque_id, factura_id, vendedora_id,
      monto_cobrado_mxn, utilidad_prorrateada_mxn, porcentaje_aplicado,
      comision_mxn, estado, nota)
    VALUES (
      v_pago.organization_id, v_pago.id, NULL, v_factura.id, NULL,
      0, 0, 0, 0, 'Devengada', 'Sin embarque asociado: pendiente de recálculo (ver cola)')
    ON CONFLICT (pago_factura_id) DO UPDATE
      SET nota = EXCLUDED.nota, updated_at = now()
      WHERE comisiones_devengadas.estado <> 'Liquidada';
    RETURN;
  END IF;
  SELECT COALESCE(ARRAY_AGG(e.id), ARRAY[]::uuid[]) INTO v_emb_vivos
    FROM embarques e
   WHERE e.id = ANY(v_emb_ids)
     AND NOT public.resolver_sin_comision(e.id);
  IF COALESCE(array_length(v_emb_vivos, 1), 0) = 0 THEN
    UPDATE comisiones_devengadas
       SET estado = 'Cancelada', comision_mxn = 0,
           nota = 'Embarque excluido de comisión', updated_at = now()
     WHERE pago_factura_id = p_pago_factura_id AND estado <> 'Liquidada';
    -- QA-R2 N-07: embarque excluido con comision ya liquidada -> por recuperar.
    UPDATE comisiones_devengadas
       SET estado = 'Por recuperar',
           nota = trim(both ' ' FROM COALESCE(nota,'') || ' [auto] embarque excluido con comision liquidada'),
           updated_at = now()
     WHERE pago_factura_id = p_pago_factura_id AND estado = 'Liquidada';
    RETURN;
  END IF;
  SELECT COALESCE(MAX(NULLIF(e.tipo_cambio_usd, 0)), 0),
         COALESCE(MAX(NULLIF(e.tipo_cambio_eur, 0)), 0)
    INTO v_tc_usd, v_tc_eur
    FROM embarques e WHERE e.id = ANY(v_emb_vivos);
  -- Embarque titular: el de mayor venta neta (ancla del renglón devengado).
  SELECT e.id INTO v_embarque_id
    FROM embarques e
   WHERE e.id = ANY(v_emb_vivos)
   ORDER BY public.venta_embarque_mxn_neta(e.id, NULLIF(v_tc_usd,0), NULLIF(v_tc_eur,0)) DESC,
            e.id
   LIMIT 1;
  SELECT COALESCE(ARRAY_AGG(DISTINCT e.vendedora_id), ARRAY[]::uuid[])
    INTO v_vendedoras
    FROM embarques e
   WHERE e.id = ANY(v_emb_vivos) AND e.vendedora_id IS NOT NULL;
  BEGIN
    v_tc_factura := NULLIF(v_factura.tipo_cambio, 0);
    IF v_pago.monto_aplicado_factura IS NOT NULL THEN
      IF v_factura.moneda::text = 'MXN' THEN
        v_cobrado_mxn := v_pago.monto_aplicado_factura;
      ELSE
        v_cobrado_mxn := public.convertir_a_mxn(
          v_pago.monto_aplicado_factura,
          v_factura.moneda::text,
          COALESCE(v_tc_factura, NULLIF(v_tc_usd, 0)),
          COALESCE(v_tc_factura, NULLIF(v_tc_eur, 0))
        );
      END IF;
    ELSIF v_pago.moneda::text = 'MXN' THEN
      v_cobrado_mxn := v_pago.monto;
    ELSE
      v_tc_pago := COALESCE(NULLIF(v_pago.tipo_cambio, 0), NULL);
      IF v_tc_pago IS NOT NULL AND v_tc_pago > 1 THEN
        v_cobrado_mxn := v_pago.monto * v_tc_pago;
      ELSE
        v_cobrado_mxn := public.convertir_a_mxn(
          v_pago.monto,
          v_pago.moneda::text, NULLIF(v_tc_usd, 0), NULLIF(v_tc_eur, 0)
        );
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_cobrado_mxn := 0;
    PERFORM public.registrar_comision_pendiente(
      v_pago.organization_id, v_pago.id, 'cobrado_mxn',
      'No se pudo valuar lo cobrado a MXN', SQLSTATE, SQLERRM);
  END;
  IF COALESCE(array_length(v_vendedoras, 1), 0) = 0 THEN
    INSERT INTO comisiones_devengadas (
      organization_id, pago_factura_id, embarque_id, factura_id, vendedora_id,
      monto_cobrado_mxn, utilidad_prorrateada_mxn, porcentaje_aplicado,
      comision_mxn, estado, nota)
    VALUES (
      v_pago.organization_id, v_pago.id, v_embarque_id, v_factura.id, NULL,
      v_cobrado_mxn, 0, 0, 0, 'Devengada', 'Sin vendedora asignada al embarque')
    ON CONFLICT (pago_factura_id) DO UPDATE
      SET monto_cobrado_mxn = EXCLUDED.monto_cobrado_mxn,
          utilidad_prorrateada_mxn = 0, porcentaje_aplicado = 0,
          comision_mxn = 0, nota = EXCLUDED.nota,
          embarque_id = EXCLUDED.embarque_id, updated_at = now()
      WHERE comisiones_devengadas.estado <> 'Liquidada';
    RETURN;
  END IF;
  IF array_length(v_vendedoras, 1) > 1 THEN
    -- Consolidada con vendedoras distintas: no se puede repartir en un solo
    -- renglón; se encola para resolución manual en lugar de grabar 0 mudo.
    PERFORM public.registrar_comision_pendiente(
      v_pago.organization_id, v_pago.id, 'consolidada_vendedoras_distintas',
      'La factura consolidada agrupa embarques con vendedoras distintas', '', '');
    INSERT INTO comisiones_devengadas (
      organization_id, pago_factura_id, embarque_id, factura_id, vendedora_id,
      monto_cobrado_mxn, utilidad_prorrateada_mxn, porcentaje_aplicado,
      comision_mxn, estado, nota)
    VALUES (
      v_pago.organization_id, v_pago.id, v_embarque_id, v_factura.id, NULL,
      v_cobrado_mxn, 0, 0, 0, 'Devengada',
      'Consolidada con vendedoras distintas: pendiente de recálculo (ver cola)')
    ON CONFLICT (pago_factura_id) DO UPDATE
      SET monto_cobrado_mxn = EXCLUDED.monto_cobrado_mxn,
          utilidad_prorrateada_mxn = 0, porcentaje_aplicado = 0,
          comision_mxn = 0, nota = EXCLUDED.nota,
          embarque_id = EXCLUDED.embarque_id, updated_at = now()
      WHERE comisiones_devengadas.estado <> 'Liquidada';
    RETURN;
  END IF;
  v_vendedora_id := v_vendedoras[1];
  v_cliente_id := v_factura.cliente_id;
  v_pct := COALESCE(public.resolver_porcentaje_comision(
             v_pago.organization_id, v_vendedora_id, v_cliente_id, v_embarque_id), 0);
  BEGIN
    SELECT COALESCE(SUM(public.convertir_a_mxn(
             cv.total, cv.moneda::text,
             NULLIF(v_tc_usd, 0), NULLIF(v_tc_eur, 0))), 0)
      INTO v_ingresos_mxn
      FROM conceptos_venta cv
     WHERE cv.embarque_id = ANY(v_emb_vivos) AND cv.deleted_at IS NULL;
    SELECT COALESCE(SUM(public.convertir_a_mxn(
             cc.monto, cc.moneda::text,
             NULLIF(v_tc_usd, 0), NULLIF(v_tc_eur, 0))), 0)
      INTO v_costos_mxn
      FROM conceptos_costo cc
     WHERE cc.embarque_id = ANY(v_emb_vivos) AND cc.deleted_at IS NULL;
    SELECT COALESCE(bool_or(m.moneda::text = 'USD'), false),
           COALESCE(bool_or(m.moneda::text = 'EUR'), false)
      INTO v_req_usd, v_req_eur
      FROM (
        SELECT moneda FROM conceptos_venta
         WHERE embarque_id = ANY(v_emb_vivos) AND deleted_at IS NULL
        UNION ALL
        SELECT moneda FROM conceptos_costo
         WHERE embarque_id = ANY(v_emb_vivos) AND deleted_at IS NULL
      ) m;
    v_utilidad := v_ingresos_mxn - v_costos_mxn;
    -- O2.1/O2.3: venta de los embarques, neta de notas de crédito.
    SELECT COALESCE(SUM(public.venta_embarque_mxn_neta(
             e.id, NULLIF(v_tc_usd, 0), NULLIF(v_tc_eur, 0))), 0)
      INTO v_venta_neta_mxn
      FROM embarques e WHERE e.id = ANY(v_emb_vivos);
    -- B-4: la nota de crédito debe acotar el NUMERADOR, no sólo el
    -- denominador. Antes, cobrar el 100% de una factura con NC del 20%
    -- daba proporción 1 (100/80 acotado a 1) e inflaba la comisión.
    -- Ahora: min(cobrado, venta neta) / venta bruta -> 80/100 = 0.8.
    v_cobrado_acotado := LEAST(COALESCE(v_cobrado_mxn, 0),
                               GREATEST(COALESCE(v_venta_neta_mxn, 0), 0));
    IF COALESCE(v_ingresos_mxn, 0) > 0 THEN
      v_proporcion := LEAST(v_cobrado_acotado / v_ingresos_mxn, 1);
    ELSIF COALESCE(v_venta_neta_mxn, 0) > 0 THEN
      v_proporcion := LEAST(COALESCE(v_cobrado_mxn, 0) / v_venta_neta_mxn, 1);
    ELSE
      v_proporcion := 0;
    END IF;
    -- QA-R2 N-07: la comision nunca es negativa.
    v_comision_mxn := GREATEST(0, ROUND(v_utilidad * v_proporcion * (v_pct / 100.0), 2));
    v_nota := CASE
      WHEN v_costos_mxn = 0 THEN 'Costos del embarque pendientes'
      WHEN (v_req_usd AND v_tc_usd = 0) OR (v_req_eur AND v_tc_eur = 0)
        THEN 'Tipos de cambio del embarque incompletos'
      WHEN COALESCE(v_venta_neta_mxn, 0) <= 0
        THEN 'Venta del embarque pendiente de captura'
      ELSE NULL
    END;
  EXCEPTION WHEN OTHERS THEN
    v_ingresos_mxn := 0;
    v_costos_mxn := 0;
    v_utilidad := 0;
    v_proporcion := 0;
    v_comision_mxn := 0;
    v_nota := 'Comisión en 0: pendiente de recálculo (ver cola)';
    PERFORM public.registrar_comision_pendiente(
      v_pago.organization_id, v_pago.id, 'utilidad_embarque',
      'No se pudo calcular la utilidad del embarque', SQLSTATE, SQLERRM);
  END;
  INSERT INTO comisiones_devengadas (
    organization_id, pago_factura_id, embarque_id, factura_id, vendedora_id,
    monto_cobrado_mxn, utilidad_prorrateada_mxn, porcentaje_aplicado,
    comision_mxn, estado, nota)
  VALUES (
    v_pago.organization_id, v_pago.id, v_embarque_id, v_factura.id, v_vendedora_id,
    v_cobrado_mxn, ROUND(v_utilidad * v_proporcion, 2), v_pct, v_comision_mxn,
    'Devengada', v_nota)
  ON CONFLICT (pago_factura_id) DO UPDATE
    SET monto_cobrado_mxn = EXCLUDED.monto_cobrado_mxn,
        utilidad_prorrateada_mxn = EXCLUDED.utilidad_prorrateada_mxn,
        porcentaje_aplicado = EXCLUDED.porcentaje_aplicado,
        comision_mxn = EXCLUDED.comision_mxn,
        nota = EXCLUDED.nota,
        embarque_id = EXCLUDED.embarque_id,
        vendedora_id = EXCLUDED.vendedora_id,
        updated_at = now()
    WHERE comisiones_devengadas.estado <> 'Liquidada';
END;
$$;
CREATE FUNCTION public.calcular_costo_demoras(p_naviera_condicion_id uuid, p_tipo_contenedor_id uuid, p_dias_excedidos integer) RETURNS TABLE(total numeric, moneda text, desglose jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  v_total numeric := 0;
  v_moneda text := 'USD';
  v_desglose jsonb := '[]'::jsonb;
  v_dias_en_tramo integer;
  v_top integer;
BEGIN
  IF p_dias_excedidos IS NULL OR p_dias_excedidos < 1 THEN
    RETURN QUERY SELECT 0::numeric, v_moneda, v_desglose;
    RETURN;
  END IF;
  FOR r IN
    SELECT desde_dia, hasta_dia, monto_por_dia, moneda
    FROM public.costeo_naviera_demoras_tarifa
    WHERE naviera_condicion_id = p_naviera_condicion_id
      AND tipo_contenedor_id = p_tipo_contenedor_id
      AND desde_dia <= p_dias_excedidos
    ORDER BY desde_dia
  LOOP
    v_top := LEAST(COALESCE(r.hasta_dia, p_dias_excedidos), p_dias_excedidos);
    v_dias_en_tramo := v_top - r.desde_dia + 1;
    IF v_dias_en_tramo > 0 THEN
      v_total := v_total + (v_dias_en_tramo * r.monto_por_dia);
      v_moneda := r.moneda;
      v_desglose := v_desglose || jsonb_build_object(
        'desde_dia', r.desde_dia,
        'hasta_dia', v_top,
        'dias', v_dias_en_tramo,
        'monto_por_dia', r.monto_por_dia,
        'subtotal', v_dias_en_tramo * r.monto_por_dia,
        'moneda', r.moneda
      );
    END IF;
  END LOOP;
  RETURN QUERY SELECT v_total, v_moneda, v_desglose;
END;
$$;
CREATE FUNCTION public.calcular_demoras_embarque(p_embarque_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_embarque record;
  v_org uuid;
  v_naviera_id uuid;
  v_cond record;
  v_cond_found boolean := false;
  v_cond_id uuid;
  v_moneda_costo text := 'USD';
  v_fecha_descarga_emb date;
  v_fecha_devolucion_emb date;
  v_dias_libres_default integer := 0;
  v_contenedor record;
  v_tipo_cont_id uuid;
  v_monto_costo numeric := 0;
  v_monto_venta numeric := 0;
  v_total_costo numeric := 0;
  v_total_venta numeric := 0;
  v_resultado jsonb := '[]'::jsonb;
  v_fecha_desc_c date;
  v_fecha_dev_c date;
  v_dias_libres_c integer;
  v_dias_puerto_c integer;
  v_dias_excedidos_c integer;
  v_bloqueados_venta jsonb;
  v_bloqueados_costo jsonb;
  v_moneda_tier text;
BEGIN
  SELECT * INTO v_embarque FROM public.embarques WHERE id = p_embarque_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','embarque no encontrado');
  END IF;
  v_org := v_embarque.organization_id;
  IF NOT (
    EXISTS (SELECT 1 FROM public.organization_members WHERE organization_id = v_org AND user_id = auth.uid())
    OR has_role(auth.uid(),'super_admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext(p_embarque_id::text));
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', cv.id, 'descripcion', cv.descripcion,
    'estado_facturacion', cv.estado_facturacion,
    'proforma_id', cv.proforma_id
  )), '[]'::jsonb)
  INTO v_bloqueados_venta
  FROM public.conceptos_venta cv
  WHERE cv.embarque_id = p_embarque_id
    AND cv.origen = 'demoras_auto'
    AND cv.deleted_at IS NULL
    AND COALESCE(cv.estado_facturacion, 'pendiente') IN ('en_proforma','facturado');
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', cc.id, 'concepto', cc.concepto,
    'estado_liquidacion', cc.estado_liquidacion
  )), '[]'::jsonb)
  INTO v_bloqueados_costo
  FROM public.conceptos_costo cc
  WHERE cc.embarque_id = p_embarque_id
    AND cc.origen = 'demoras_auto'
    AND cc.deleted_at IS NULL
    AND EXISTS (
      SELECT 1 FROM public.proveedor_facturas_conceptos pfc
      WHERE pfc.concepto_costo_id = cc.id
    );
  IF jsonb_array_length(v_bloqueados_venta) > 0 OR jsonb_array_length(v_bloqueados_costo) > 0 THEN
    RAISE EXCEPTION 'LC_DEMORAS_BLOQUEADAS: hay conceptos de demoras ya en proforma/factura/CxP'
      USING HINT = jsonb_build_object(
        'embarque_id', p_embarque_id,
        'expediente', v_embarque.expediente,
        'conceptos_venta_bloqueados', v_bloqueados_venta,
        'conceptos_costo_bloqueados', v_bloqueados_costo
      )::text;
  END IF;
  SELECT n.id INTO v_naviera_id FROM public.navieras n
  WHERE lower(n.name) = lower(v_embarque.naviera) LIMIT 1;
  SELECT min(fecha)::date INTO v_fecha_descarga_emb FROM public.eventos_embarque
  WHERE embarque_id = p_embarque_id AND tipo = 'Descarga' AND deleted_at IS NULL;
  SELECT max(fecha)::date INTO v_fecha_devolucion_emb FROM public.eventos_embarque
  WHERE embarque_id = p_embarque_id AND tipo = 'Entrega' AND deleted_at IS NULL;
  IF v_naviera_id IS NOT NULL THEN
    SELECT * INTO v_cond FROM public.costeo_navieras_condiciones
    WHERE organization_id = v_org AND naviera_id = v_naviera_id LIMIT 1;
    IF FOUND THEN
      v_cond_found := true;
      v_cond_id := v_cond.id;
      v_dias_libres_default := COALESCE(v_cond.dias_libres_demoras_default, 0);
      v_moneda_costo := COALESCE(v_cond.moneda_demoras, 'USD');
    END IF;
  END IF;
  UPDATE public.conceptos_costo
     SET deleted_at = now(), deleted_by = auth.uid()
   WHERE embarque_id = p_embarque_id AND origen = 'demoras_auto' AND deleted_at IS NULL;
  UPDATE public.conceptos_venta
     SET deleted_at = now(), deleted_by = auth.uid()
   WHERE embarque_id = p_embarque_id AND origen = 'demoras_auto' AND deleted_at IS NULL;
  FOR v_contenedor IN
    SELECT * FROM public.embarque_contenedores
    WHERE embarque_id = p_embarque_id AND deleted_at IS NULL
    ORDER BY orden
  LOOP
    SELECT id INTO v_tipo_cont_id FROM public.tipos_contenedor
    WHERE lower(code) = lower(v_contenedor.tipo_contenedor) OR lower(name) = lower(v_contenedor.tipo_contenedor)
    LIMIT 1;
    v_fecha_desc_c := COALESCE(v_contenedor.fecha_descarga, v_fecha_descarga_emb);
    v_fecha_dev_c := COALESCE(v_contenedor.fecha_devolucion, v_fecha_devolucion_emb);
    v_dias_libres_c := COALESCE(v_contenedor.dias_libres_override, v_dias_libres_default);
    v_dias_puerto_c := 0;
    v_dias_excedidos_c := 0;
    IF v_fecha_desc_c IS NOT NULL AND v_fecha_dev_c IS NOT NULL THEN
      v_dias_puerto_c := GREATEST(0, v_fecha_dev_c - v_fecha_desc_c);
      v_dias_excedidos_c := GREATEST(0, v_dias_puerto_c - v_dias_libres_c);
    END IF;
    -- Delegar cálculo de montos al helper privado.
    SELECT m.monto_costo, m.moneda_costo, m.monto_venta
      INTO v_monto_costo, v_moneda_tier, v_monto_venta
    FROM public._calcular_demoras_montos_contenedor(
      CASE WHEN v_cond_found THEN v_cond_id ELSE NULL END,
      v_org,
      v_tipo_cont_id,
      v_dias_excedidos_c,
      v_moneda_costo
    ) m;
    IF v_monto_costo > 0 THEN
      INSERT INTO public.conceptos_costo (
        embarque_id, organization_id, proveedor_nombre, concepto,
        monto, moneda, estado_liquidacion, contenedor_id, origen
      ) VALUES (
        p_embarque_id, v_org, COALESCE(v_embarque.naviera,'Naviera'),
        format('Demoras %s días — contenedor %s', v_dias_excedidos_c, COALESCE(NULLIF(v_contenedor.numero_contenedor,''), v_contenedor.orden::text)),
        v_monto_costo, COALESCE(v_moneda_tier,'USD')::moneda, 'Pendiente'::estado_liquidacion, v_contenedor.id, 'demoras_auto'
      );
      v_total_costo := v_total_costo + v_monto_costo;
    END IF;
    IF v_monto_venta > 0 THEN
      INSERT INTO public.conceptos_venta (
        embarque_id, organization_id, descripcion, cantidad,
        precio_unitario, moneda, total, aplica_iva, contenedor_id, origen
      ) VALUES (
        p_embarque_id, v_org,
        format('Demoras %s días — contenedor %s', v_dias_excedidos_c, COALESCE(NULLIF(v_contenedor.numero_contenedor,''), v_contenedor.orden::text)),
        1, v_monto_venta, 'USD'::moneda, v_monto_venta, true, v_contenedor.id, 'demoras_auto'
      );
      v_total_venta := v_total_venta + v_monto_venta;
    END IF;
    v_resultado := v_resultado || jsonb_build_object(
      'contenedor_id', v_contenedor.id,
      'numero_contenedor', v_contenedor.numero_contenedor,
      'tipo_contenedor', v_contenedor.tipo_contenedor,
      'fecha_descarga', v_fecha_desc_c,
      'fecha_devolucion', v_fecha_dev_c,
      'dias_libres', v_dias_libres_c,
      'dias_en_puerto', v_dias_puerto_c,
      'dias_excedidos', v_dias_excedidos_c,
      'monto_costo', v_monto_costo,
      'moneda_costo', COALESCE(v_moneda_tier,'USD'),
      'monto_venta_usd', v_monto_venta
    );
  END LOOP;
  RETURN jsonb_build_object(
    'embarque_id', p_embarque_id,
    'fecha_descarga_embarque', v_fecha_descarga_emb,
    'fecha_devolucion_embarque', v_fecha_devolucion_emb,
    'dias_libres_default', v_dias_libres_default,
    'total_costo', v_total_costo,
    'moneda_costo', v_moneda_costo,
    'total_venta_usd', v_total_venta,
    'contenedores', v_resultado
  );
END;
$$;
CREATE FUNCTION public.can_admin_tenant(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id
      AND role IN ('super_admin','admin_org','admin')
  )
$$;
CREATE FUNCTION public.can_manage_document_object(_object_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH parts AS (
    SELECT storage.foldername(ltrim(_object_name, '/')) AS folder_parts
  ), actor AS (
    SELECT
      auth.uid() AS user_id,
      public.has_role(auth.uid(), 'super_admin'::public.app_role) AS is_super_admin,
      public.has_role(auth.uid(), 'operador'::public.app_role) AS is_staff,
      public.current_user_org_id() AS org_id
  )
  SELECT COALESCE(
    (SELECT is_super_admin FROM actor)
    OR (
      -- Rama nueva: carpeta raíz = organización efectiva del usuario.
      (SELECT user_id FROM actor) IS NOT NULL
      AND (SELECT is_staff FROM actor)
      AND (SELECT org_id FROM actor) IS NOT NULL
      AND (SELECT folder_parts[1] FROM parts) = (SELECT org_id::text FROM actor)
      AND (SELECT folder_parts[2] FROM parts) IN ('embarques', 'msds', 'cotizaciones')
    )
    OR (
      (SELECT user_id FROM actor) IS NOT NULL
      AND (SELECT is_staff FROM actor)
      AND (SELECT folder_parts[1] FROM parts) = 'embarques'
      AND EXISTS (
        SELECT 1 FROM public.organization_members om
        JOIN public.embarques e ON e.organization_id = om.organization_id
        CROSS JOIN parts CROSS JOIN actor
        WHERE om.user_id = actor.user_id
          AND public.has_role(om.user_id, 'operador'::public.app_role)
          AND e.deleted_at IS NULL
          AND (
            parts.folder_parts[2] = e.expediente
            OR (
              parts.folder_parts[2] = e.id::text
              AND EXISTS (
                SELECT 1 FROM public.documentos_embarque d
                WHERE d.id::text = parts.folder_parts[3]
                  AND d.embarque_id = e.id
                  AND d.organization_id = e.organization_id
                  AND d.deleted_at IS NULL
              )
            )
          )
      )
    ),
    false
  );
$$;
CREATE FUNCTION public.can_view_financials(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id
      AND role IN ('super_admin','admin_org','admin','gerente_operaciones','contador','tesorero','ejecutivo_pricing')
  )
$$;
CREATE TABLE public.anticipos_proveedor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    proveedor_id uuid NOT NULL,
    fecha_anticipo date DEFAULT CURRENT_DATE NOT NULL,
    monto numeric(18,4) NOT NULL,
    moneda public.moneda DEFAULT 'MXN'::public.moneda NOT NULL,
    tipo_cambio_usd numeric(18,6),
    metodo_pago text,
    referencia text,
    cuenta_bancaria_id uuid,
    notas text,
    estado text DEFAULT 'disponible'::text NOT NULL,
    saldo_disponible numeric(18,4) NOT NULL,
    motivo_cancelacion text,
    created_by uuid,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    embarque_id uuid,
    devuelto_at timestamp with time zone,
    devuelto_by uuid,
    monto_devuelto numeric(18,4),
    motivo_devolucion text,
    CONSTRAINT anticipos_proveedor_estado_check CHECK ((estado = ANY (ARRAY['disponible'::text, 'aplicado_parcial'::text, 'aplicado_total'::text, 'cancelado'::text, 'devuelto'::text]))),
    CONSTRAINT anticipos_proveedor_monto_check CHECK ((monto > (0)::numeric)),
    CONSTRAINT anticipos_proveedor_saldo_rango_check CHECK (((saldo_disponible IS NULL) OR ((saldo_disponible >= (0)::numeric) AND (saldo_disponible <= (monto + 0.01)))))
);
ALTER TABLE ONLY public.anticipos_proveedor FORCE ROW LEVEL SECURITY;
CREATE FUNCTION public.cancelar_anticipo_proveedor(p_id uuid, p_motivo text) RETURNS public.anticipos_proveedor
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.anticipos_proveedor;
  v_uid uuid := auth.uid();
  v_email text;
  v_aplicaciones integer;
  v_autorizado boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid
      AND ur.role::text = ANY (ARRAY['admin','admin_org','super_admin','contador','tesorero'])
  ) INTO v_autorizado;
  IF NOT v_autorizado THEN
    RAISE EXCEPTION 'LC_ANTICIPO_SIN_ROL: Sólo administradores, contabilidad o tesorería pueden cancelar anticipos.'
      USING ERRCODE = '42501';
  END IF;
  IF COALESCE(trim(p_motivo),'') = '' OR length(trim(p_motivo)) < 3 THEN
    RAISE EXCEPTION 'LC_ANTICIPO_MOTIVO_REQUERIDO: Debes indicar un motivo de cancelación.';
  END IF;
  -- N18: candado de fila antes de validar estado (doble clic / doble pestaña).
  SELECT * INTO v_row FROM public.anticipos_proveedor
   WHERE id = p_id AND deleted_at IS NULL
   FOR UPDATE;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'LC_ANTICIPO_NO_EXISTE: El anticipo no existe.';
  END IF;
  IF v_row.organization_id IS DISTINCT FROM public.current_user_org_id()
     AND NOT public.has_role(v_uid, 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_ANTICIPO_OTRA_ORG: El anticipo pertenece a otra organización.'
      USING ERRCODE = '42501';
  END IF;
  IF v_row.estado = 'cancelado' THEN
    RAISE EXCEPTION 'LC_ANTICIPO_YA_CANCELADO: El anticipo ya está cancelado.';
  END IF;
  SELECT COUNT(*) INTO v_aplicaciones
    FROM public.anticipos_aplicaciones
    WHERE anticipo_id = p_id AND deleted_at IS NULL;
  IF v_aplicaciones > 0 THEN
    RAISE EXCEPTION 'LC_ANTICIPO_CON_APLICACIONES: No se puede cancelar un anticipo con aplicaciones vivas. Reversa las aplicaciones primero.';
  END IF;
  UPDATE public.anticipos_proveedor
    SET estado = 'cancelado',
        saldo_disponible = 0,
        motivo_cancelacion = p_motivo,
        deleted_at = now(),
        deleted_by = v_uid,
        updated_at = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
  UPDATE public.bbva_movimientos
    SET deleted_at = now(), deleted_by = v_uid
    WHERE anticipo_proveedor_id = p_id AND deleted_at IS NULL;
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (v_row.organization_id, v_uid, COALESCE(v_email,''), 'cancelar_anticipo_proveedor', 'cxp',
            v_row.id, 'Anticipo ' || v_row.id::text,
            jsonb_build_object('motivo', p_motivo, 'monto', v_row.monto, 'moneda', v_row.moneda));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en cancelar_anticipo_proveedor: % %', SQLSTATE, SQLERRM;
  END;
  RETURN v_row;
END;
$$;
CREATE FUNCTION public.cancelar_factura_proveedor(p_factura_id uuid, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado public.estado_proveedor_factura;
  v_deleted timestamptz;
  v_org uuid;
  v_pagado numeric;
  v_ncs_canceladas int;
  v_uid uuid := auth.uid();
  v_desvinculo jsonb := '{}'::jsonb;
  v_ent uuid[];
BEGIN
  IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
    RAISE EXCEPTION 'Debes indicar un motivo de cancelación.' USING ERRCODE = '22023';
  END IF;
  SELECT estado, deleted_at, organization_id
    INTO v_estado, v_deleted, v_org
  FROM public.proveedor_facturas
  WHERE id = p_factura_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'La factura no existe.' USING ERRCODE = 'P0002';
  END IF;
  IF v_deleted IS NOT NULL THEN
    RAISE EXCEPTION 'La factura está en la papelera; restáurala antes de cancelarla.' USING ERRCODE = '22023';
  END IF;
  IF v_estado = 'Cancelada'::public.estado_proveedor_factura THEN
    RAISE EXCEPTION 'La factura ya está cancelada.' USING ERRCODE = '22023';
  END IF;
  IF NOT public.is_org_member(v_org) THEN
    RAISE EXCEPTION 'No tienes permiso para cancelar esta factura.' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(SUM(monto), 0) INTO v_pagado
  FROM public.pagos_proveedor
  WHERE proveedor_factura_id = p_factura_id AND deleted_at IS NULL;
  IF v_pagado > 0 THEN
    RAISE EXCEPTION 'No puedes cancelar la factura: tiene pagos aplicados por %. Elimina o anula los pagos primero.', v_pagado
      USING ERRCODE = '22023';
  END IF;
  UPDATE public.proveedor_notas_credito
     SET estado = 'Cancelada'::public.estado_nota_credito_proveedor,
         updated_at = now()
   WHERE proveedor_factura_id = p_factura_id
     AND deleted_at IS NULL
     AND estado <> 'Cancelada'::public.estado_nota_credito_proveedor;
  GET DIAGNOSTICS v_ncs_canceladas = ROW_COUNT;
  -- v13.508.2 — capturamos los documentos del buzón ANTES de cancelar: el
  -- trigger _reabrir_entrantes_factura los devuelve a "por_capturar" y borra
  -- el vínculo, así que después ya no se pueden ubicar por factura.
  SELECT array_agg(id) INTO v_ent
  FROM public.embarque_facturas_entrantes
  WHERE proveedor_factura_id = p_factura_id AND deleted_at IS NULL;
  -- Marca de sesión para permitir la transición a Cancelada.
  PERFORM set_config('app.cancelando_cxp','1', true);
  UPDATE public.proveedor_facturas
     SET estado = 'Cancelada'::public.estado_proveedor_factura,
         fecha_cancelacion = now(),
         motivo_cancelacion = btrim(p_motivo),
         cancelada_por = v_uid,
         -- BL-03: una factura cancelada no puede conservar la aprobación;
         -- sin este reset quedaba 'aprobada' y admitía pagos/anticipos en
         -- cualquier path que sólo valide estado_aprobacion.
         estado_aprobacion = 'pendiente'::public.estado_aprobacion_factura_proveedor,
         updated_at = now()
   WHERE id = p_factura_id;
  PERFORM set_config('app.cancelando_cxp','0', true);
  -- v13.505.0 — cancelar también desvincula: los conceptos de costo del
  -- embarque vuelven a "sin factura" y el expediente se suelta.
  v_desvinculo := public._cxp_desvincular_por_rechazo(p_factura_id, btrim(p_motivo));
  -- El documento del buzón queda Rechazado (no "por capturar") y sin vínculo.
  IF v_ent IS NOT NULL THEN
    UPDATE public.embarque_facturas_entrantes
       SET estado = 'rechazada',
           rechazo_motivo = btrim(p_motivo),
           proveedor_factura_id = NULL,
           capturado_por = NULL,
           updated_at = now()
     WHERE id = ANY(v_ent)
       AND deleted_at IS NULL;
  END IF;
  IF to_regclass('public.bitacora_actividad') IS NOT NULL THEN
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES
      (v_org, v_uid, 'cxp.cancelada', 'compras', p_factura_id, NULL,
       jsonb_build_object('motivo', btrim(p_motivo), 'ncs_canceladas', v_ncs_canceladas) || v_desvinculo);
  END IF;
END;
$$;
CREATE TABLE public.liquidaciones_comision (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    vendedora_id uuid NOT NULL,
    periodo text NOT NULL,
    total_mxn numeric(14,2) DEFAULT 0 NOT NULL,
    fecha_pago date,
    metodo_pago text,
    referencia text,
    notas text,
    creada_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    estado text DEFAULT 'Generada'::text NOT NULL,
    cancelada_at timestamp with time zone,
    cancelada_por uuid,
    motivo_cancelacion text,
    CONSTRAINT liquidaciones_comision_estado_chk CHECK ((estado = ANY (ARRAY['Generada'::text, 'Pagada'::text, 'Cancelada'::text]))),
    CONSTRAINT liquidaciones_comision_total_chk CHECK ((total_mxn >= (0)::numeric))
);
CREATE FUNCTION public.cancelar_liquidacion_comision(p_liquidacion_id uuid, p_motivo text) RETURNS public.liquidaciones_comision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.liquidaciones_comision;
  v_email text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(TRIM(p_motivo), '') = '' THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_MOTIVO_REQUERIDO: Captura el motivo de la cancelación.'
      USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_row FROM public.liquidaciones_comision
  WHERE id = p_liquidacion_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_NO_EXISTE: La liquidación no existe.';
  END IF;
  IF v_row.organization_id IS DISTINCT FROM public.current_user_org_id()
     AND NOT public.has_role(v_uid,'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_OTRA_ORG: La liquidación pertenece a otra organización.';
  END IF;
  IF NOT public.has_any_role_in_org_exact(v_uid,
       ARRAY['admin','admin_org','super_admin','contador','tesorero']::public.app_role[],
       v_row.organization_id) THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_SIN_ROL: Sólo administración, contabilidad o tesorería pueden cancelar liquidaciones.'
      USING ERRCODE = '42501';
  END IF;
  IF v_row.estado = 'Cancelada' THEN
    RETURN v_row;
  END IF;
  IF v_row.fecha_pago IS NOT NULL THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_PAGADA_NO_CANCELABLE: La liquidación ya fue pagada; registra el ajuste en la siguiente liquidación.'
      USING ERRCODE = '42501';
  END IF;
  UPDATE public.comisiones_devengadas
     SET estado = 'Devengada', liquidacion_id = NULL, updated_at = now()
   WHERE liquidacion_id = p_liquidacion_id
     AND estado = 'Liquidada';
  UPDATE public.comisiones_devengadas
     SET estado = 'Por recuperar', liquidacion_id = NULL, updated_at = now()
   WHERE liquidacion_id = p_liquidacion_id
     AND estado = 'Cancelada';
  UPDATE public.liquidaciones_comision
     SET estado = 'Cancelada',
         cancelada_at = now(),
         cancelada_por = v_uid,
         motivo_cancelacion = TRIM(p_motivo),
         updated_at = now()
   WHERE id = p_liquidacion_id
  RETURNING * INTO v_row;
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (v_row.organization_id, v_uid, COALESCE(v_email,''), 'cancelar_liquidacion_comision', 'comisiones',
            v_row.id, 'Liquidación ' || v_row.periodo,
            jsonb_build_object('motivo', TRIM(p_motivo), 'total_mxn', v_row.total_mxn));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en cancelar_liquidacion_comision: % %', SQLSTATE, SQLERRM;
  END;
  RETURN v_row;
END;
$$;
CREATE FUNCTION public.cancelar_traspaso_bancario(p_traspaso_id uuid, p_motivo text DEFAULT ''::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_estado text;
BEGIN
  SELECT estado INTO v_estado
    FROM public.traspasos_bancarios
   WHERE id = p_traspaso_id AND deleted_at IS NULL;
  IF v_estado IS NULL THEN
    RAISE EXCEPTION 'LC_TRASPASO_INEXISTENTE: el traspaso no existe o no tienes acceso';
  END IF;
  IF v_estado = 'Cancelado' THEN
    RAISE EXCEPTION 'LC_TRASPASO_YA_CANCELADO: el traspaso ya está cancelado';
  END IF;
  UPDATE public.bbva_movimientos
     SET deleted_at = now(), deleted_by = v_uid
   WHERE traspaso_id = p_traspaso_id AND deleted_at IS NULL;
  UPDATE public.traspasos_bancarios
     SET estado = 'Cancelado',
         motivo_cancelacion = COALESCE(NULLIF(TRIM(p_motivo), ''), 'Cancelado por el usuario'),
         deleted_at = now()
   WHERE id = p_traspaso_id;
END;
$$;
CREATE FUNCTION public.capturar_factura_entrante(p_documento_id uuid, p_factura_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid := public.current_user_org_id();
  v_doc public.embarque_facturas_entrantes%ROWTYPE;
  v_fac_org uuid;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'contador')
          OR public.has_role(auth.uid(), 'auxiliar_contable')
          OR public.has_role(auth.uid(), 'admin')
          OR public.has_role(auth.uid(), 'super_admin')) THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: sin permiso para capturar facturas entrantes';
  END IF;
  SELECT * INTO v_doc FROM public.embarque_facturas_entrantes
   WHERE id = p_documento_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'LC_NOT_FOUND: documento no encontrado'; END IF;
  IF v_doc.organization_id IS DISTINCT FROM v_caller_org AND NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: documento de otra organización';
  END IF;
  -- Idempotencia: el trigger trg_cerrar_entrantes_por_uuid pudo cerrar ya este
  -- documento contra la misma factura. En ese caso no hay nada que hacer.
  IF v_doc.estado = 'capturada' AND v_doc.proveedor_factura_id = p_factura_id THEN
    RETURN;
  END IF;
  IF v_doc.estado = 'capturada' THEN
    RAISE EXCEPTION 'LC_ESTADO_INVALIDO: el documento ya está vinculado a otra factura de proveedor';
  END IF;
  IF v_doc.estado = 'rechazada' THEN
    RAISE EXCEPTION 'LC_ESTADO_INVALIDO: el documento fue rechazado; solicita que se vuelva a subir';
  END IF;
  IF v_doc.estado <> 'por_capturar' THEN
    RAISE EXCEPTION 'LC_ESTADO_INVALIDO: el documento no está disponible para captura';
  END IF;
  SELECT organization_id INTO v_fac_org FROM public.proveedor_facturas WHERE id = p_factura_id;
  IF v_fac_org IS NULL THEN RAISE EXCEPTION 'LC_NOT_FOUND: factura de proveedor no encontrada'; END IF;
  IF v_fac_org <> v_doc.organization_id THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: la factura pertenece a otra organización';
  END IF;
  UPDATE public.embarque_facturas_entrantes
     SET estado = 'capturada',
         proveedor_factura_id = p_factura_id,
         capturado_por = auth.uid()
   WHERE id = p_documento_id;
END;
$$;
CREATE FUNCTION public.cartera_pendiente() RETURNS TABLE(factura_id uuid, numero text, cliente_id uuid, cliente_nombre text, embarque_id uuid, expediente text, fecha_emision date, fecha_vencimiento date, dias_vencido integer, moneda text, total numeric, pagado numeric, saldo numeric, ultimo_contacto date, estado text, cancellation_status text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT f.id, f.numero, f.cliente_id, f.embarque_id, f.fecha_emision,
      f.fecha_vencimiento, f.moneda::text AS moneda, f.total,
      f.estado::text AS estado, f.cliente_nombre, f.tipo_cambio AS factura_tc,
      COALESCE(f.cancellation_status, 'none') AS cancellation_status,
      COALESCE((SELECT SUM(pf.monto_aplicado_factura) FROM public.pagos_factura pf
                 WHERE pf.factura_id=f.id AND pf.deleted_at IS NULL),0) AS pagado,
      COALESCE((
        SELECT SUM(
          CASE
            WHEN nc.moneda::text = f.moneda::text THEN nc.monto
            WHEN f.moneda::text = 'MXN' AND nc.moneda::text <> 'MXN' AND nc.tipo_cambio > 1
              THEN nc.monto * nc.tipo_cambio
            WHEN f.moneda::text <> 'MXN' AND nc.moneda::text = 'MXN' AND f.tipo_cambio > 1
              THEN nc.monto / f.tipo_cambio
            WHEN f.moneda::text <> 'MXN' AND nc.moneda::text <> 'MXN'
                 AND f.moneda::text <> nc.moneda::text
                 AND nc.tipo_cambio > 1 AND f.tipo_cambio > 1
              THEN (nc.monto * nc.tipo_cambio) / f.tipo_cambio
            ELSE 0
          END)
        FROM public.factura_notas_credito nc
        WHERE nc.factura_id = f.id
          AND nc.deleted_at IS NULL
          AND nc.estado = 'Aplicada'
      ), 0) AS nc_aplicadas
    FROM public.facturas f
    WHERE f.deleted_at IS NULL
      AND f.estado::text IN ('Emitida','Vencida','Parcialmente pagada')
  )
  SELECT b.id, b.numero, b.cliente_id, COALESCE(c.nombre, b.cliente_nombre),
    b.embarque_id, e.expediente,
    b.fecha_emision, b.fecha_vencimiento,
    ((now() AT TIME ZONE 'America/Mexico_City')::date - b.fecha_vencimiento)::int,
    b.moneda, b.total, b.pagado,
    (b.total - b.pagado - b.nc_aplicadas),
    (SELECT MAX(cs.fecha) FROM public.cobranza_seguimiento cs WHERE cs.factura_id=b.id),
    b.estado, b.cancellation_status
  FROM base b
  LEFT JOIN public.clientes c ON c.id = b.cliente_id
  LEFT JOIN public.embarques e ON e.id = b.embarque_id AND e.deleted_at IS NULL
  WHERE (b.total - b.pagado - b.nc_aplicadas) > 0.005
  ORDER BY b.fecha_vencimiento ASC NULLS LAST
  LIMIT 500
$$;
CREATE FUNCTION public.cerrar_caso_refacturacion(p_caso_id uuid, p_cancelar boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_c public.refacturaciones%ROWTYPE;
  v_val jsonb;
  v_estado_nueva text;
  v_uuid_nueva text;
  v_pago_ok boolean;
  v_mov_pendiente int;
BEGIN
  SELECT * INTO v_c FROM public.refacturaciones WHERE id = p_caso_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_CASO_NO_ENCONTRADO' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public._assert_refacturador(v_c.organization_id);
  IF NOT p_cancelar THEN
    IF v_c.factura_nueva_id IS NULL THEN
      RAISE EXCEPTION 'LC_REFACT_CIERRE_INCONSISTENTE: falta generar y timbrar la nueva factura'
        USING ERRCODE = 'P0001';
    END IF;
    SELECT estado::text, uuid_fiscal INTO v_estado_nueva, v_uuid_nueva
    FROM public.facturas WHERE id = v_c.factura_nueva_id;
    IF v_uuid_nueva IS NULL OR v_estado_nueva IN ('Borrador','Cancelada','Sustituida') THEN
      RAISE EXCEPTION 'LC_REFACT_CIERRE_INCONSISTENTE: la nueva factura debe estar timbrada y vigente'
        USING ERRCODE = 'P0001';
    END IF;
    v_val := public.refacturacion_validar_consistencia(p_caso_id);
    IF NOT (v_val->>'ok')::boolean THEN
      RAISE EXCEPTION 'LC_REFACT_CIERRE_INCONSISTENTE: %',
        COALESCE((v_val->'hallazgos'->0->>'mensaje'), 'la nueva factura no es consistente con la original')
        USING ERRCODE = 'P0001';
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM public.pagos_factura
      WHERE factura_id = v_c.factura_nueva_id AND deleted_at IS NULL
    ) INTO v_pago_ok;
    IF NOT v_pago_ok THEN
      RAISE EXCEPTION 'LC_REFACT_CIERRE_INCONSISTENTE: el pago recibido aún no está aplicado a la nueva factura'
        USING ERRCODE = 'P0001';
    END IF;
    IF v_c.pago_nuevo_id IS NOT NULL THEN
      SELECT COUNT(*) INTO v_mov_pendiente
      FROM public.bbva_movimientos
      WHERE pago_factura_id = v_c.pago_nuevo_id AND estado_conciliacion <> 'Conciliado';
      IF v_mov_pendiente > 0 THEN
        RAISE EXCEPTION 'LC_REFACT_CIERRE_INCONSISTENTE: el movimiento bancario quedó sin conciliar'
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
    -- Trazabilidad: la proforma origen debe apuntar a la factura viva
    UPDATE public.proformas
       SET factura_id = v_c.factura_nueva_id, updated_at = now()
     WHERE factura_id = v_c.factura_original_id
       AND organization_id = v_c.organization_id
       AND deleted_at IS NULL;
    UPDATE public.proformas
       SET factura_secundaria_id = v_c.factura_nueva_id, updated_at = now()
     WHERE factura_secundaria_id = v_c.factura_original_id
       AND organization_id = v_c.organization_id
       AND deleted_at IS NULL;
  END IF;
  UPDATE public.refacturaciones
     SET estado = CASE WHEN p_cancelar THEN 'cancelado' ELSE 'completado' END,
         paso_actual = CASE WHEN p_cancelar THEN paso_actual ELSE 5 END,
         cerrado_at = now()
   WHERE id = p_caso_id;
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_c.organization_id, auth.uid(),
    COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), ''),
    CASE WHEN p_cancelar THEN 'refacturacion_cancelada' ELSE 'refacturacion_completada' END,
    'facturacion', v_c.factura_original_id, '',
    jsonb_build_object('caso_id', p_caso_id, 'factura_nueva_id', v_c.factura_nueva_id)
  );
END;
$$;
CREATE FUNCTION public.cerrar_embarque(p_embarque_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emb embarques%ROWTYPE;
  v_uid uuid := auth.uid();
  v_validacion jsonb;
  v_snapshot jsonb;
  v_pnl jsonb;
  v_is_admin boolean;
  v_forzado boolean := false;
  v_automatico boolean := COALESCE(current_setting('app.cierre_automatico', true), 'off') = 'on';
  -- BL-09: cursor de recálculo de comisiones pendientes.
  v_pago_recalc uuid;
  v_recalculadas int := 0;
BEGIN
  IF v_uid IS NULL AND NOT v_automatico THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  v_is_admin :=
    has_role(v_uid,'super_admin') OR
    has_role(v_uid,'admin') OR
    has_role(v_uid,'admin_org');
  IF NOT v_automatico AND NOT (
    v_is_admin OR
    has_role(v_uid,'gerente_operaciones') OR
    has_role(v_uid,'coordinador_logistico')
  ) THEN
    RAISE EXCEPTION 'No autorizado para cerrar embarques. Esta acción es responsabilidad del coordinador logístico.';
  END IF;
  SELECT * INTO v_emb FROM embarques WHERE id = p_embarque_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Embarque no encontrado';
  END IF;
  IF v_emb.estado::text = 'Cerrado' THEN
    RAISE EXCEPTION 'El embarque ya está cerrado';
  END IF;
  IF v_emb.estado::text NOT IN ('Entregado','EIR','Por liquidar') THEN
    RAISE EXCEPTION 'Solo se pueden cerrar embarques en estado Entregado, EIR o Por liquidar (actual: %)', v_emb.estado::text;
  END IF;
  v_validacion := validar_cierre_embarque(p_embarque_id);
  IF NOT COALESCE((v_validacion->>'puede_cerrar')::boolean, false) THEN
    IF v_automatico THEN
      RAISE EXCEPTION 'LC_CIERRE_AUTOMATICO_NO_APLICA';
    ELSIF v_is_admin THEN
      v_forzado := true;
    ELSE
      RAISE EXCEPTION 'Validaciones de cierre no satisfechas: %', v_validacion::text;
    END IF;
  END IF;
  BEGIN
    v_pnl := pnl_financiero_embarque(p_embarque_id);
  EXCEPTION WHEN OTHERS THEN
    v_pnl := '{}'::jsonb;
  END;
  v_snapshot := jsonb_build_object(
    'cerrado_at', now(),
    'cerrado_por', v_uid,
    'forzado_admin', v_forzado,
    'automatico', v_automatico,
    'pnl', v_pnl,
    'validaciones', v_validacion,
    'totales', jsonb_build_object(
      'cxc_total', (SELECT COALESCE(sum(total),0) FROM facturas WHERE embarque_id = p_embarque_id AND deleted_at IS NULL AND estado <> 'Cancelada'),
      'cxp_total', (SELECT COALESCE(sum(total),0) FROM proveedor_facturas WHERE embarque_id = p_embarque_id AND deleted_at IS NULL AND estado <> 'Cancelada'),
      'seguros_prima_total', (SELECT COALESCE(sum(prima),0) FROM seguros_embarque WHERE embarque_id = p_embarque_id AND deleted_at IS NULL)
    )
  );
  PERFORM set_config('app.bypass_cierre','on', true);
  UPDATE embarques
     SET estado = 'Cerrado'::estado_embarque,
         cerrado_at = now(),
         cerrado_por = v_uid,
         cerrado_snapshot = v_snapshot,
         reabierto_at = NULL,
         reabierto_por = NULL,
         reabierto_motivo = NULL,
         updated_at = now()
   WHERE id = p_embarque_id;
  -- BL-09: recalcular las comisiones del embarque que quedaron en 0 con nota
  -- de pendiente (TC faltante / costos capturados tarde). La función es
  -- idempotente y omite las ya 'Liquidada'. Un fallo individual no aborta el
  -- cierre: queda WARNING y la nota sigue marcando la comisión como pendiente.
  FOR v_pago_recalc IN
    SELECT pf.id
      FROM pagos_factura pf
      JOIN facturas f ON f.id = pf.factura_id
      JOIN comisiones_devengadas cd ON cd.pago_factura_id = pf.id
     WHERE f.embarque_id = p_embarque_id
       AND pf.deleted_at IS NULL
       AND cd.estado = 'Devengada'
       AND cd.nota IS NOT NULL
     ORDER BY pf.id
  LOOP
    BEGIN
      PERFORM public.calcular_comision_pago(v_pago_recalc);
      v_recalculadas := v_recalculadas + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'BL-09: recálculo de comisión del pago % falló: % %', v_pago_recalc, SQLSTATE, SQLERRM;
    END;
  END LOOP;
  UPDATE comisiones_devengadas
     SET definitiva = true,
         pnl_base = COALESCE((v_pnl->>'utilidad_mxn')::numeric, (v_pnl->>'utilidad')::numeric, 0),
         calculo_snapshot = v_pnl,
         updated_at = now()
   WHERE embarque_id = p_embarque_id;
  PERFORM set_config('app.bypass_cierre','off', true);
  INSERT INTO cierre_embarque_log(embarque_id, organization_id, accion, usuario_id, motivo, snapshot)
  VALUES (
    p_embarque_id,
    v_emb.organization_id,
    CASE WHEN v_forzado THEN 'cerrar_forzado'
         WHEN v_automatico THEN 'cerrar_automatico'
         ELSE 'cerrar' END,
    v_uid,
    CASE WHEN v_forzado THEN 'Cierre forzado por administrador con checklist incompleto'
         WHEN v_automatico THEN 'Cierre automático: se liquidó el último saldo por cobrar y por pagar'
         ELSE NULL END,
    v_snapshot
  );
  PERFORM public.registrar_bitacora(
    'embarques',
    CASE WHEN v_forzado THEN 'cerrar_embarque_forzado'
         WHEN v_automatico THEN 'cerrar_embarque_automatico'
         ELSE 'cerrar_embarque' END,
    p_embarque_id,
    COALESCE(v_emb.expediente, ''),
    v_snapshot,
    v_emb.organization_id,
    v_uid
  );
  RETURN jsonb_build_object('ok', true, 'forzado_admin', v_forzado, 'automatico', v_automatico,
                            'comisiones_recalculadas', v_recalculadas,
                            'snapshot', v_snapshot);
END;
$$;
CREATE FUNCTION public.cerrar_factura_proveedor_sin_pago(p_factura_id uuid, p_motivo text, p_comentario text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_estado   public.estado_proveedor_factura;
  v_deleted  timestamptz;
  v_moneda   public.moneda;
  v_aprob    public.estado_aprobacion_factura_proveedor;
  v_saldo    numeric;
  v_pago_id  uuid;
  v_uid      uuid := auth.uid();
  v_rol_ejecutor text;
  v_valid_motivos text[] := ARRAY['compensacion', 'condonacion', 'ajuste_historico', 'duplicada'];
BEGIN
  IF p_motivo IS NULL OR NOT (p_motivo = ANY(v_valid_motivos)) THEN
    RAISE EXCEPTION 'Motivo inválido. Válidos: compensacion, condonacion, ajuste_historico, duplicada.'
      USING ERRCODE = '22023';
  END IF;
  SELECT pf.organization_id, pf.estado, pf.deleted_at, pf.moneda, pf.estado_aprobacion
    INTO v_org, v_estado, v_deleted, v_moneda, v_aprob
    FROM public.proveedor_facturas pf
   WHERE pf.id = p_factura_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'La factura no existe.' USING ERRCODE = 'P0002';
  END IF;
  IF v_deleted IS NOT NULL THEN
    RAISE EXCEPTION 'La factura está en la papelera; restáurala antes.' USING ERRCODE = '22023';
  END IF;
  IF v_estado = 'Cancelada'::public.estado_proveedor_factura THEN
    RAISE EXCEPTION 'La factura ya está cancelada.' USING ERRCODE = '22023';
  END IF;
  IF v_estado = 'Pagada'::public.estado_proveedor_factura THEN
    RAISE EXCEPTION 'La factura ya está pagada.' USING ERRCODE = '22023';
  END IF;
  IF v_aprob <> 'aprobada'::public.estado_aprobacion_factura_proveedor THEN
    RAISE EXCEPTION 'La factura debe estar aprobada antes de cerrarla.' USING ERRCODE = '22023';
  END IF;
  -- Fase M: gate de rol.
  -- Bypass super_admin; en caso normal exige que el usuario pertenezca a la org
  -- de la factura Y tenga uno de los roles autorizados.
  IF public.has_role(v_uid, 'super_admin'::public.app_role) THEN
    v_rol_ejecutor := 'super_admin';
  ELSIF v_org = public.current_user_org_id() AND public.has_role(v_uid, 'admin'::public.app_role) THEN
    v_rol_ejecutor := 'admin';
  ELSIF v_org = public.current_user_org_id() AND public.has_role(v_uid, 'admin_org'::public.app_role) THEN
    v_rol_ejecutor := 'admin_org';
  ELSIF v_org = public.current_user_org_id() AND public.has_role(v_uid, 'contador'::public.app_role) THEN
    v_rol_ejecutor := 'contador';
  ELSIF v_org = public.current_user_org_id() AND public.has_role(v_uid, 'tesorero'::public.app_role) THEN
    v_rol_ejecutor := 'tesorero';
  ELSE
    RAISE EXCEPTION 'LC_CERRAR_FACTURA_SIN_ROL: sólo admin, admin_org, contador o tesorero pueden cerrar una factura sin pago.'
      USING ERRCODE = '42501',
            HINT = json_build_object(
              'rol_requerido', array['admin','admin_org','contador','tesorero','super_admin'],
              'factura_id', p_factura_id
            )::text;
  END IF;
  SELECT saldo INTO v_saldo
    FROM public.v_proveedor_facturas_saldo
   WHERE proveedor_factura_id = p_factura_id;
  IF COALESCE(v_saldo, 0) <= 0 THEN
    RAISE EXCEPTION 'La factura no tiene saldo pendiente que cerrar.' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.pagos_proveedor(
    organization_id, proveedor_factura_id, fecha_pago, monto, moneda, tipo_cambio_usd,
    metodo_pago, referencia, notas, es_ajuste, motivo_ajuste, created_by
  ) VALUES (
    v_org, p_factura_id, CURRENT_DATE, v_saldo, v_moneda, 0,
    'Ajuste', 'Cierre sin pago: ' || p_motivo,
    COALESCE(p_comentario, ''), true, p_motivo, v_uid
  )
  RETURNING id INTO v_pago_id;
  UPDATE public.proveedor_facturas
     SET estado = 'Pagada'::public.estado_proveedor_factura,
         updated_at = now()
   WHERE id = p_factura_id;
  INSERT INTO public.bitacora_actividad(
    organization_id, usuario_id, modulo, accion, entidad_id, detalles
  ) VALUES (
    v_org, v_uid, 'cxp', 'cerrar_sin_pago', p_factura_id,
    jsonb_build_object(
      'motivo', p_motivo,
      'saldo_ajustado', v_saldo,
      'pago_ajuste_id', v_pago_id,
      'comentario', p_comentario,
      'rol_ejecutor', v_rol_ejecutor
    )
  );
  RETURN v_pago_id;
END;
$$;
CREATE FUNCTION public.check_ratelimit(p_key text, p_window_seconds integer DEFAULT 60, p_max integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bucket public.ratelimit_buckets;
  v_now timestamptz := now();
  v_retry int := 0;
BEGIN
  SELECT * INTO v_bucket FROM public.ratelimit_buckets WHERE bucket_key = p_key FOR UPDATE;
  IF NOT FOUND OR (v_now - v_bucket.window_start) > make_interval(secs => p_window_seconds) THEN
    INSERT INTO public.ratelimit_buckets(bucket_key, count, window_start, updated_at)
    VALUES (p_key, 1, v_now, v_now)
    ON CONFLICT (bucket_key) DO UPDATE SET count = 1, window_start = v_now, updated_at = v_now;
    RETURN jsonb_build_object('ok', true, 'retry_after', 0);
  END IF;
  IF v_bucket.count >= p_max THEN
    v_retry := GREATEST(1, p_window_seconds - EXTRACT(EPOCH FROM (v_now - v_bucket.window_start))::int);
    RETURN jsonb_build_object('ok', false, 'retry_after', v_retry);
  END IF;
  UPDATE public.ratelimit_buckets SET count = count + 1, updated_at = v_now WHERE bucket_key = p_key;
  RETURN jsonb_build_object('ok', true, 'retry_after', 0);
END;
$$;
CREATE FUNCTION public.cierre_periodo_actual() RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.cierre_periodo_fecha(public.current_user_org_id());
$$;
CREATE FUNCTION public.cierre_periodo_fecha(p_org uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT CASE
           WHEN v ~ '^\d{4}-\d{2}-\d{2}$' THEN v::date
           ELSE NULL
         END
  FROM (
    SELECT NULLIF(c.valor #>> '{}', '') AS v
    FROM public.configuracion c
    WHERE c.organization_id = p_org
      AND c.categoria = 'contabilidad'
      AND c.clave = 'cierre_periodo_fecha'
    LIMIT 1
  ) s;
$_$;
CREATE FUNCTION public.clear_facturapi_api_key(p_org_id uuid, p_ambiente text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'extensions'
    AS $$
DECLARE
  v_old_id uuid;
BEGIN
  PERFORM public._assert_facturapi_admin(p_org_id);
  IF p_ambiente NOT IN ('sandbox','live') THEN
    RAISE EXCEPTION 'ambiente_invalido' USING ERRCODE = '22023';
  END IF;
  IF p_ambiente = 'sandbox' THEN
    SELECT api_key_sandbox_vault_id INTO v_old_id FROM public.facturapi_credenciales WHERE organization_id = p_org_id;
    UPDATE public.facturapi_credenciales
       SET api_key_sandbox_vault_id = NULL,
           api_key_sandbox_last4    = NULL,
           updated_at               = now()
     WHERE organization_id = p_org_id;
  ELSE
    SELECT api_key_live_vault_id INTO v_old_id FROM public.facturapi_credenciales WHERE organization_id = p_org_id;
    UPDATE public.facturapi_credenciales
       SET api_key_live_vault_id = NULL,
           api_key_live_last4    = NULL,
           updated_at            = now()
     WHERE organization_id = p_org_id;
  END IF;
  IF v_old_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_old_id;
  END IF;
  INSERT INTO public.bitacora_actividad (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
  VALUES (
    p_org_id,
    auth.uid(),
    COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), ''),
    'facturapi_api_key_borrada',
    'facturapi_credenciales',
    p_org_id,
    '',
    jsonb_build_object('ambiente', p_ambiente)
  );
END;
$$;
CREATE FUNCTION public.cliente_requiere_autorizacion(p_cliente_id uuid, p_tipo text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_req boolean;
BEGIN
  IF p_cliente_id IS NULL THEN
    RETURN true; -- sin cliente asociado: se exige autorización (comportamiento actual)
  END IF;
  IF p_tipo NOT IN ('cotizacion','proforma') THEN
    RAISE EXCEPTION 'LC_TIPO_AUTORIZACION_INVALIDO: use cotizacion o proforma' USING ERRCODE = 'check_violation';
  END IF;
  IF p_tipo = 'cotizacion' THEN
    SELECT c.requiere_autorizacion_cotizacion INTO v_req
      FROM public.clientes c WHERE c.id = p_cliente_id;
  ELSE
    SELECT c.requiere_autorizacion_proforma INTO v_req
      FROM public.clientes c WHERE c.id = p_cliente_id;
  END IF;
  RETURN COALESCE(v_req, true);
END;
$$;
CREATE FUNCTION public.clientes_listado(p_organization_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, nombre text, rfc text, ciudad text, estado text, contacto text, telefono text, email text, dias_credito integer, limite_credito_mxn numeric, total_embarques bigint, total_cotizaciones bigint, deuda_pendiente numeric, saldo_pendiente_mxn numeric, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH filtered AS (
    SELECT c.*
    FROM clientes c
    WHERE c.deleted_at IS NULL
      AND ( p_organization_id IS NULL OR c.organization_id = p_organization_id )
      AND ( p_search IS NULL OR p_search = '' OR
            c.nombre ILIKE '%' || p_search || '%' OR
            c.rfc    ILIKE '%' || p_search || '%' )
  ),
  counted AS (
    SELECT f.*, count(*) OVER ()::bigint AS total_count
    FROM filtered f
    ORDER BY f.nombre ASC
    OFFSET p_offset LIMIT p_limit
  ),
  emb_agg AS (
    SELECT e.cliente_id, count(*)::bigint AS total_embarques
    FROM embarques e
    WHERE e.cliente_id IN (SELECT id FROM counted)
    GROUP BY e.cliente_id
  ),
  cot_agg AS (
    SELECT c.cliente_id, count(*)::bigint AS total_cotizaciones
    FROM cotizaciones c
    WHERE c.cliente_id IN (SELECT id FROM counted)
      AND c.deleted_at IS NULL
    GROUP BY c.cliente_id
  ),
  facturas_vivas AS (
    SELECT
      f.id,
      f.cliente_id,
      f.total,
      f.moneda,
      COALESCE(NULLIF(f.tipo_cambio, 0), 1) AS tc
    FROM facturas f
    WHERE f.cliente_id IN (SELECT id FROM counted)
      AND f.deleted_at IS NULL
      AND f.estado IN ('Emitida'::estado_factura, 'Vencida'::estado_factura, 'Parcialmente pagada'::estado_factura, 'Pagada'::estado_factura)
  ),
  pagos_agg AS (
    SELECT p.factura_id, COALESCE(SUM(p.monto_aplicado_factura),0) AS pagado
    FROM pagos_factura p
    WHERE p.deleted_at IS NULL
      AND p.factura_id IN (SELECT id FROM facturas_vivas)
    GROUP BY p.factura_id
  ),
  nc_agg AS (
    SELECT n.factura_id, COALESCE(SUM(n.monto),0) AS nc_aplicada
    FROM factura_notas_credito n
    WHERE n.deleted_at IS NULL
      AND n.estado = 'Aplicada'
      AND n.factura_id IN (SELECT id FROM facturas_vivas)
    GROUP BY n.factura_id
  ),
  saldo_agg AS (
    SELECT
      fv.cliente_id,
      SUM(
        GREATEST(0, COALESCE(fv.total,0) - COALESCE(pa.pagado,0) - COALESCE(na.nc_aplicada,0))
        * CASE WHEN fv.moneda = 'MXN' THEN 1 ELSE fv.tc END
      ) AS saldo_pendiente_mxn
    FROM facturas_vivas fv
    LEFT JOIN pagos_agg pa ON pa.factura_id = fv.id
    LEFT JOIN nc_agg   na ON na.factura_id = fv.id
    GROUP BY fv.cliente_id
  ),
  deuda_agg AS (
    SELECT f.cliente_id, COALESCE(sum(f.total),0)::numeric AS deuda_pendiente
    FROM facturas f
    WHERE f.cliente_id IN (SELECT id FROM counted)
      AND f.estado IN ('Emitida'::estado_factura, 'Vencida'::estado_factura)
    GROUP BY f.cliente_id
  )
  SELECT
    c.id, c.nombre, c.rfc, c.ciudad, c.estado, c.contacto, c.telefono, c.email,
    c.dias_credito,
    c.limite_credito_mxn,
    COALESCE(ea.total_embarques, 0),
    COALESCE(ca.total_cotizaciones, 0),
    COALESCE(da.deuda_pendiente, 0),
    ROUND(COALESCE(sa.saldo_pendiente_mxn, 0), 2),
    c.total_count
  FROM counted c
  LEFT JOIN emb_agg   ea ON ea.cliente_id = c.id
  LEFT JOIN cot_agg   ca ON ca.cliente_id = c.id
  LEFT JOIN deuda_agg da ON da.cliente_id = c.id
  LEFT JOIN saldo_agg sa ON sa.cliente_id = c.id
  ORDER BY c.nombre ASC;
$$;
CREATE FUNCTION public.clientes_sync_cp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF (NEW.cp IS NULL OR NEW.cp = '') AND NEW.codigo_postal IS NOT NULL AND NEW.codigo_postal <> '' THEN
      NEW.cp := NEW.codigo_postal;
    ELSIF (NEW.codigo_postal IS NULL OR NEW.codigo_postal = '') AND NEW.cp IS NOT NULL AND NEW.cp <> '' THEN
      NEW.codigo_postal := NEW.cp;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    -- Si cambió cp, propaga a codigo_postal
    IF NEW.cp IS DISTINCT FROM OLD.cp AND NEW.cp IS NOT NULL AND NEW.cp <> '' THEN
      NEW.codigo_postal := NEW.cp;
    -- Si cambió codigo_postal y cp quedó vacío o igual al anterior, propaga a cp
    ELSIF NEW.codigo_postal IS DISTINCT FROM OLD.codigo_postal
          AND NEW.codigo_postal IS NOT NULL AND NEW.codigo_postal <> '' THEN
      NEW.cp := NEW.codigo_postal;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.cobranza_agregados(p_cliente_id uuid DEFAULT NULL::uuid, p_moneda text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH cartera AS (
    SELECT
      f.moneda::text AS moneda,
      GREATEST(0, f.total - COALESCE(pg.pagado, 0) - COALESCE(nc.notas, 0)) AS saldo,
      ((now() AT TIME ZONE 'America/Mexico_City')::date - f.fecha_vencimiento) AS dias_vencido
    FROM facturas f
    LEFT JOIN LATERAL (
      SELECT SUM(pf.monto_aplicado_factura) AS pagado
      FROM pagos_factura pf
      WHERE pf.factura_id = f.id AND pf.deleted_at IS NULL
    ) pg ON true
    -- Ola v16 (2): canon único `nc_aplicadas_en_moneda_factura` — la suma
    -- cruda de `n.monto` mezclaba monedas (NC en USD restadas a facturas MXN)
    -- y devolvía saldos y KPIs de cartera incorrectos.
    LEFT JOIN LATERAL (
      SELECT public.nc_aplicadas_en_moneda_factura(f.id) AS notas
    ) nc ON true
    WHERE f.deleted_at IS NULL
      AND f.estado IN ('Emitida', 'Parcialmente pagada', 'Vencida')
      AND f.organization_id = public.org_scope()
      AND (p_cliente_id IS NULL OR f.cliente_id = p_cliente_id)
      AND (p_moneda IS NULL OR f.moneda::text = p_moneda)
  )
  SELECT jsonb_build_object(
    'total_mxn',          COALESCE(SUM(saldo) FILTER (WHERE moneda = 'MXN' AND saldo > 0), 0),
    'total_usd',          COALESCE(SUM(saldo) FILTER (WHERE moneda = 'USD' AND saldo > 0), 0),
    'vencido_mxn',        COALESCE(SUM(saldo) FILTER (WHERE moneda = 'MXN' AND saldo > 0 AND dias_vencido > 0), 0),
    'vencido_usd',        COALESCE(SUM(saldo) FILTER (WHERE moneda = 'USD' AND saldo > 0 AND dias_vencido > 0), 0),
    'por_vencer_7d_mxn',  COALESCE(SUM(saldo) FILTER (WHERE moneda = 'MXN' AND saldo > 0 AND dias_vencido BETWEEN -7 AND 0), 0),
    'por_vencer_7d_usd',  COALESCE(SUM(saldo) FILTER (WHERE moneda = 'USD' AND saldo > 0 AND dias_vencido BETWEEN -7 AND 0), 0),
    'facturas_vencidas',  COUNT(*) FILTER (WHERE moneda IN ('MXN','USD') AND saldo > 0 AND dias_vencido > 0),
    'facturas_con_saldo', COUNT(*) FILTER (WHERE saldo > 0)
  ) INTO v_result
  FROM cartera;
  RETURN v_result;
END;
$$;
CREATE FUNCTION public.cobranza_listado(p_cliente_id uuid DEFAULT NULL::uuid, p_moneda text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_estatus text DEFAULT NULL::text, p_limit integer DEFAULT 2000) RETURNS TABLE(id uuid, numero text, cliente_id uuid, cliente_nombre text, expediente text, moneda text, total numeric, pagado numeric, notas_credito_aplicadas numeric, saldo numeric, fecha_emision date, fecha_vencimiento date, dias_vencido integer, estatus_cobranza text, estado_factura text, tipo_cambio numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := public.org_scope();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 2000), 1), 5000);
BEGIN
  IF v_org IS NULL THEN
    RETURN;
  END IF;
  RETURN QUERY
  WITH cartera AS (
    SELECT
      f.id,
      f.numero,
      f.cliente_id,
      f.cliente_nombre,
      f.expediente,
      f.moneda::text AS moneda,
      f.total,
      COALESCE(pg.pagado, 0)::numeric AS pagado,
      COALESCE(nc.notas, 0)::numeric AS notas,
      GREATEST(0, f.total - COALESCE(pg.pagado, 0) - COALESCE(nc.notas, 0))::numeric AS saldo,
      f.fecha_emision,
      f.fecha_vencimiento,
      ((now() AT TIME ZONE 'America/Mexico_City')::date - f.fecha_vencimiento)::integer AS dias_vencido,
      f.estado::text AS estado_factura,
      f.tipo_cambio
    FROM facturas f
    LEFT JOIN LATERAL (
      SELECT SUM(pf.monto_aplicado_factura) AS pagado
      FROM pagos_factura pf
      WHERE pf.factura_id = f.id AND pf.deleted_at IS NULL
    ) pg ON true
    -- Ola v16 (2): canon único `nc_aplicadas_en_moneda_factura` — la suma
    -- cruda de `n.monto` mezclaba monedas (NC en USD restadas a facturas MXN)
    -- y devolvía saldos y KPIs de cartera incorrectos.
    LEFT JOIN LATERAL (
      SELECT public.nc_aplicadas_en_moneda_factura(f.id) AS notas
    ) nc ON true
    WHERE f.deleted_at IS NULL
      AND f.estado IN ('Emitida', 'Parcialmente pagada', 'Vencida')
      AND f.organization_id = v_org
      AND (p_cliente_id IS NULL OR f.cliente_id = p_cliente_id)
      AND (p_moneda IS NULL OR f.moneda::text = p_moneda)
      AND (
        p_search IS NULL OR p_search = ''
        OR f.numero ILIKE '%' || p_search || '%'
        OR f.cliente_nombre ILIKE '%' || p_search || '%'
      )
  ), clasificada AS (
    SELECT c.*,
      CASE
        WHEN c.saldo <= 0.01 THEN 'Sin saldo'
        WHEN c.dias_vencido > 0 THEN 'Vencida'
        WHEN c.dias_vencido BETWEEN -7 AND 0 THEN 'Por vencer'
        ELSE 'Vigente'
      END AS estatus
    FROM cartera c
  )
  SELECT
    cl.id, cl.numero, cl.cliente_id, cl.cliente_nombre, cl.expediente,
    cl.moneda, cl.total, cl.pagado, cl.notas, cl.saldo,
    cl.fecha_emision, cl.fecha_vencimiento, cl.dias_vencido,
    cl.estatus, cl.estado_factura, cl.tipo_cambio
  FROM clasificada cl
  WHERE p_estatus IS NULL OR p_estatus = '' OR p_estatus = 'todos'
     OR cl.estatus = p_estatus
  ORDER BY cl.fecha_vencimiento ASC
  LIMIT v_limit;
END;
$$;
CREATE FUNCTION public.comision_embarques_de_factura(p_factura_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN f.embarque_id IS NOT NULL THEN ARRAY[f.embarque_id]
    ELSE COALESCE((
      SELECT ARRAY_AGG(fe.embarque_id ORDER BY fe.embarque_id)
        FROM public.factura_embarques fe
       WHERE fe.factura_id = f.id
         AND COALESCE(fe.activa, true)
         AND fe.embarque_id IS NOT NULL
    ), ARRAY[]::uuid[])
  END
  FROM public.facturas f
  WHERE f.id = p_factura_id;
$$;
CREATE FUNCTION public.comisiones_sobre_devengadas() RETURNS TABLE(embarque_id uuid, facturas bigint, utilidad_prorrateada_mxn numeric, comision_mxn numeric, proporcion_total numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT cd.embarque_id,
         COUNT(DISTINCT cd.factura_id) AS facturas,
         ROUND(SUM(cd.utilidad_prorrateada_mxn), 2),
         ROUND(SUM(cd.comision_mxn), 2),
         ROUND(SUM(cd.monto_cobrado_mxn) / NULLIF(
           public.venta_embarque_mxn_neta(cd.embarque_id,
             (SELECT tipo_cambio_usd FROM public.embarques e WHERE e.id = cd.embarque_id),
             (SELECT tipo_cambio_eur FROM public.embarques e WHERE e.id = cd.embarque_id)), 0), 4)
  FROM public.comisiones_devengadas cd
  WHERE cd.embarque_id IS NOT NULL
    AND cd.estado <> 'Cancelada'
    AND cd.deleted_at IS NULL
    AND (cd.organization_id = public.current_user_org_id()
         OR public.has_role(auth.uid(),'super_admin'::app_role))
  GROUP BY cd.embarque_id
  HAVING SUM(cd.monto_cobrado_mxn) > 1.01 * COALESCE(NULLIF(
           public.venta_embarque_mxn_neta(cd.embarque_id,
             (SELECT tipo_cambio_usd FROM public.embarques e WHERE e.id = cd.embarque_id),
             (SELECT tipo_cambio_eur FROM public.embarques e WHERE e.id = cd.embarque_id)), 0), 0)
  ORDER BY 4 DESC;
$$;
CREATE FUNCTION public.complete_onboarding(_organization_id uuid, _rfc text, _direccion text, _moneda text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_id uuid;
  _rfc_clean text := upper(btrim(coalesce(_rfc, '')));
  _dir_clean text := btrim(coalesce(_direccion, ''));
  _mon_clean text := upper(btrim(coalesce(_moneda, 'MXN')));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'auth required';
  END IF;
  IF _rfc_clean <> '' AND (length(_rfc_clean) < 12 OR length(_rfc_clean) > 13) THEN
    RAISE EXCEPTION 'RFC inválido (debe tener 12 o 13 caracteres)';
  END IF;
  IF _dir_clean <> '' AND (length(_dir_clean) < 5 OR length(_dir_clean) > 500) THEN
    RAISE EXCEPTION 'Dirección inválida (5 a 500 caracteres)';
  END IF;
  IF _mon_clean NOT IN ('MXN','USD','EUR') THEN
    RAISE EXCEPTION 'Moneda no soportada';
  END IF;
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'LC_ONBOARDING_ORG_REQUERIDA: organización requerida'
      USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_role(auth.uid(), 'super_admin'::app_role)
     AND NOT EXISTS (
       SELECT 1 FROM public.organization_members om
       WHERE om.user_id = auth.uid()
         AND om.organization_id = _organization_id
         AND om.role IN ('admin','admin_org','super_admin')
     ) THEN
    RAISE EXCEPTION 'LC_ONBOARDING_ORG_AJENA: no administras esa organización'
      USING ERRCODE = '42501';
  END IF;
  _org_id := _organization_id;
  UPDATE public.organizations
  SET rfc = NULLIF(_rfc_clean, ''),
      direccion = NULLIF(_dir_clean, ''),
      moneda_preferida = _mon_clean,
      onboarding_completado = true,
      updated_at = now()
  WHERE id = _org_id;
  RETURN jsonb_build_object('ok', true, 'organization_id', _org_id);
END;
$$;
CREATE FUNCTION public.conceptos_factura_assert_borrador() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_factura_id uuid;
  v_estado public.estado_factura;
BEGIN
  IF TG_OP = 'DELETE' THEN v_factura_id := OLD.factura_id;
  ELSE v_factura_id := NEW.factura_id;
  END IF;
  SELECT f.estado INTO v_estado FROM public.facturas f WHERE f.id = v_factura_id AND f.deleted_at IS NULL;
  IF v_estado IS DISTINCT FROM 'Borrador'::public.estado_factura THEN
    RAISE EXCEPTION 'LC_FACTURA_INMUTABLE: los conceptos sólo se editan mientras la factura está en Borrador'
      USING ERRCODE = 'P0001';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END
$$;
CREATE FUNCTION public.conciliacion_resumen(p_cuenta_bancaria_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_movimientos',  COUNT(*),
    'pendientes',         COUNT(*) FILTER (WHERE m.estado_conciliacion = 'Pendiente'),
    'conciliados',        COUNT(*) FILTER (WHERE m.estado_conciliacion = 'Conciliado'),
    'ignorados',          COUNT(*) FILTER (WHERE m.estado_conciliacion = 'Ignorado'),
    'cargos_pendientes',  COALESCE(SUM(m.cargo) FILTER (WHERE m.estado_conciliacion = 'Pendiente'), 0),
    'abonos_pendientes',  COALESCE(SUM(m.abono) FILTER (WHERE m.estado_conciliacion = 'Pendiente'), 0)
  ) INTO v_result
  FROM public.bbva_movimientos m
  JOIN public.cuentas_bancarias cb ON cb.id = m.cuenta_bancaria_id AND cb.deleted_at IS NULL
  WHERE m.cuenta_bancaria_id = p_cuenta_bancaria_id
    AND m.deleted_at IS NULL
    AND m.fecha >= cb.fecha_saldo_inicial
    AND (m.organization_id = public.org_scope());
  RETURN v_result;
END;
$$;
CREATE FUNCTION public.conciliar_tesoreria_proveedor(p_proveedor_id uuid DEFAULT NULL::uuid, p_factura_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_revisadas int := 0;
  v_actualizadas int := 0;
  v_facturas jsonb := '[]'::jsonb;
  v_incidencias jsonb := '[]'::jsonb;
  v_proveedores jsonb := '[]'::jsonb;
  r record;
  v_estado_antes text;
  v_captura_antes text;
BEGIN
  IF p_proveedor_id IS NULL AND p_factura_id IS NULL THEN
    RAISE EXCEPTION 'LC_CONCILIACION_SIN_ALCANCE: indica un proveedor o una factura'
      USING ERRCODE = 'P0001';
  END IF;
  v_org := public.current_user_org_id();
  PERFORM public._assert_writer(v_org);
  -- 1) Recalcular estado/etapa de captura de cada factura en el alcance.
  FOR r IN
    SELECT pf.id, pf.estado::text AS estado, pf.estado_captura
    FROM public.proveedor_facturas pf
    WHERE pf.organization_id = v_org
      AND pf.deleted_at IS NULL
      AND (p_factura_id IS NULL OR pf.id = p_factura_id)
      AND (p_proveedor_id IS NULL OR pf.proveedor_id = p_proveedor_id)
  LOOP
    v_revisadas := v_revisadas + 1;
    v_estado_antes := r.estado;
    v_captura_antes := r.estado_captura;
    PERFORM public._recalc_estado_proveedor_factura(r.id);
    IF EXISTS (
      SELECT 1 FROM public.proveedor_facturas pf
      WHERE pf.id = r.id
        AND (pf.estado::text IS DISTINCT FROM v_estado_antes
             OR pf.estado_captura IS DISTINCT FROM v_captura_antes)
    ) THEN
      v_actualizadas := v_actualizadas + 1;
    END IF;
  END LOOP;
  -- 2) Detalle por factura con los importes recalculados.
  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'folio'), '[]'::jsonb) INTO v_facturas
  FROM (
    SELECT jsonb_build_object(
             'factura_id', pf.id,
             'folio', COALESCE(NULLIF(pf.folio_proveedor,''), pf.folio_interno),
             'moneda', pf.moneda::text,
             'total', ROUND(s.total, 2),
             'pagado', ROUND(s.pagado, 2),
             'notas_credito', ROUND(s.notas_credito_aplicadas, 2),
             'saldo', ROUND(s.saldo, 2),
             'estado', pf.estado::text,
             'pagos', (SELECT count(*) FROM public.pagos_proveedor pp
                        WHERE pp.proveedor_factura_id = pf.id AND pp.deleted_at IS NULL),
             'movimientos', (SELECT count(*) FROM public.bbva_movimientos bm
                              JOIN public.pagos_proveedor pp2 ON pp2.id = bm.pago_proveedor_id
                              WHERE pp2.proveedor_factura_id = pf.id
                                AND pp2.deleted_at IS NULL
                                AND bm.deleted_at IS NULL)
           ) AS x
    FROM public.proveedor_facturas pf
    JOIN public.v_proveedor_facturas_saldo s ON s.proveedor_factura_id = pf.id
    WHERE pf.organization_id = v_org
      AND pf.deleted_at IS NULL
      AND (p_factura_id IS NULL OR pf.id = p_factura_id)
      AND (p_proveedor_id IS NULL OR pf.proveedor_id = p_proveedor_id)
  ) q;
  -- 3) Incidencias: pagos sin movimiento de tesorería o con importe distinto.
  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'fecha_pago'), '[]'::jsonb) INTO v_incidencias
  FROM (
    SELECT jsonb_build_object(
             'pago_id', pp.id,
             'factura_id', pp.proveedor_factura_id,
             'folio', COALESCE(NULLIF(pf.folio_proveedor,''), pf.folio_interno),
             'fecha_pago', pp.fecha_pago,
             'monto', ROUND(pp.monto, 2),
             'moneda', pp.moneda::text,
             'monto_esperado_mxn', ROUND(
               CASE WHEN pp.moneda::text = 'MXN' THEN pp.monto
                    WHEN COALESCE(pp.tipo_cambio_usd,0) > 0 THEN pp.monto * pp.tipo_cambio_usd
                    ELSE pp.monto END, 2),
             'cargo_mxn', ROUND(COALESCE(m.cargo, 0), 2),
             'tipo', CASE WHEN m.id IS NULL THEN 'sin_movimiento' ELSE 'descuadre' END
           ) AS x, pp.fecha_pago
    FROM public.pagos_proveedor pp
    JOIN public.proveedor_facturas pf ON pf.id = pp.proveedor_factura_id
    LEFT JOIN public.bbva_movimientos m
           ON m.pago_proveedor_id = pp.id AND m.deleted_at IS NULL
    WHERE pf.organization_id = v_org
      AND pp.deleted_at IS NULL
      AND pf.deleted_at IS NULL
      AND (p_factura_id IS NULL OR pf.id = p_factura_id)
      AND (p_proveedor_id IS NULL OR pf.proveedor_id = p_proveedor_id)
      AND (
        (m.id IS NULL AND pp.cuenta_bancaria_id IS NOT NULL)
        OR (m.id IS NOT NULL AND abs(COALESCE(m.cargo,0) - (
             CASE WHEN pp.moneda::text = 'MXN' THEN pp.monto
                  WHEN COALESCE(pp.tipo_cambio_usd,0) > 0 THEN pp.monto * pp.tipo_cambio_usd
                  ELSE pp.monto END)) > 0.01)
      )
  ) q2;
  -- 4) Saldo pendiente del proveedor por moneda (facturas vivas y no canceladas).
  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'moneda'), '[]'::jsonb) INTO v_proveedores
  FROM (
    SELECT jsonb_build_object(
             'proveedor_id', pf.proveedor_id,
             'moneda', pf.moneda::text,
             'saldo_pendiente', ROUND(SUM(GREATEST(s.saldo, 0)), 2),
             'facturas_abiertas', COUNT(*) FILTER (WHERE s.saldo > 0.01)
           ) AS x
    FROM public.proveedor_facturas pf
    JOIN public.v_proveedor_facturas_saldo s ON s.proveedor_factura_id = pf.id
    WHERE pf.organization_id = v_org
      AND pf.deleted_at IS NULL
      AND pf.estado::text NOT IN ('Cancelada','Borrador')
      AND (p_proveedor_id IS NOT NULL OR pf.id = p_factura_id)
      AND (p_proveedor_id IS NULL OR pf.proveedor_id = p_proveedor_id)
    GROUP BY pf.proveedor_id, pf.moneda
  ) q3;
  RETURN jsonb_build_object(
    'facturas_revisadas', v_revisadas,
    'facturas_actualizadas', v_actualizadas,
    'facturas', v_facturas,
    'incidencias', v_incidencias,
    'proveedores', v_proveedores,
    'conciliado_at', now()
  );
END;
$$;
CREATE FUNCTION public.congelar_factura_al_emitir() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_conceptos jsonb;
  v_cliente jsonb;
  v_org jsonb;
  v_tasa_iva numeric;
BEGIN
  -- Sólo congelar al transicionar a Emitida/Pagada y si aún no hay snapshot
  IF NEW.estado NOT IN ('Emitida', 'Pagada') THEN
    RETURN NEW;
  END IF;
  -- QA-R2 D-05: no emitir una factura sin conceptos vivos. Sólo aplica en la
  -- transición normal de captura (Borrador/Por timbrar -> Emitida); en INSERT
  -- los conceptos aún no pueden existir por la FK y otras transiciones
  -- (reapertura de canceladas) tienen su propio candado.
  IF TG_OP = 'UPDATE'
     AND NEW.estado = 'Emitida'
     AND OLD.estado IN ('Borrador', 'Por timbrar')
     AND NOT EXISTS (
       SELECT 1 FROM public.conceptos_factura cf
       WHERE cf.factura_id = NEW.id AND cf.deleted_at IS NULL
     ) THEN
    RAISE EXCEPTION 'LC_FACTURA_SIN_CONCEPTOS: no se puede emitir una factura sin conceptos'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.snapshot_emision IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(cf)), '[]'::jsonb)
    INTO v_conceptos
    FROM public.conceptos_factura cf
   WHERE cf.factura_id = NEW.id
     AND cf.deleted_at IS NULL;
  SELECT jsonb_build_object(
           'id', c.id,
           'nombre', c.nombre,
           'rfc', c.rfc,
           'direccion', c.direccion,
           'ciudad', c.ciudad,
           'estado', c.estado,
           'cp', c.cp
         )
    INTO v_cliente
    FROM public.clientes c
   WHERE c.id = NEW.cliente_id;
  SELECT jsonb_build_object(
           'id', o.id,
           'nombre', o.nombre,
           'rfc', o.rfc
         )
    INTO v_org
    FROM public.organizations o
   WHERE o.id = NEW.organization_id;
  v_tasa_iva := CASE
    WHEN COALESCE(NEW.subtotal, 0) = 0 THEN 0
    ELSE round((NEW.iva / NEW.subtotal)::numeric, 4)
  END;
  NEW.snapshot_emision := jsonb_build_object(
    'version', 1,
    'congelado_at', now(),
    'estado_al_congelar', NEW.estado,
    'numero', NEW.numero,
    'moneda', NEW.moneda,
    'subtotal', NEW.subtotal,
    'iva', NEW.iva,
    'total', NEW.total,
    'tasa_iva', v_tasa_iva,
    'tipo_cambio', NEW.tipo_cambio,
    'fecha_emision', NEW.fecha_emision,
    'fecha_vencimiento', NEW.fecha_vencimiento,
    'expediente', NEW.expediente,
    'referencia_bl', NEW.referencia_bl,
    'cliente_snapshot', v_cliente,
    'organizacion_snapshot', v_org,
    'conceptos', v_conceptos
  );
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.congelar_proforma_al_aprobar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_conceptos jsonb;
  v_cliente jsonb;
  v_org jsonb;
BEGIN
  IF NEW.estado_proforma NOT IN ('aprobada', 'facturada') THEN
    RETURN NEW;
  END IF;
  IF NEW.snapshot_emision IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(cv)), '[]'::jsonb)
    INTO v_conceptos
    FROM public.conceptos_venta cv
   WHERE cv.proforma_id = NEW.id
     AND cv.deleted_at IS NULL;
  SELECT jsonb_build_object(
           'id', c.id,
           'nombre', c.nombre,
           'rfc', c.rfc,
           'direccion', c.direccion,
           'ciudad', c.ciudad,
           'estado', c.estado,
           'cp', c.cp
         )
    INTO v_cliente
    FROM public.clientes c
   WHERE c.id = NEW.cliente_id;
  SELECT jsonb_build_object(
           'id', o.id,
           'nombre', o.nombre,
           'rfc', o.rfc
         )
    INTO v_org
    FROM public.organizations o
   WHERE o.id = NEW.organization_id;
  NEW.snapshot_emision := jsonb_build_object(
    'version', 1,
    'congelado_at', now(),
    'estado_al_congelar', NEW.estado_proforma,
    'numero', NEW.numero,
    'expediente', NEW.expediente,
    'bl_master', NEW.bl_master,
    'tasa_iva_aplicada', NEW.tasa_iva_aplicada,
    'subtotal_usd', NEW.subtotal_usd,
    'iva_usd', NEW.iva_usd,
    'total_usd', NEW.total_usd,
    'subtotal_mxn', NEW.subtotal_mxn,
    'iva_mxn', NEW.iva_mxn,
    'total_mxn', NEW.total_mxn,
    'dias_credito', NEW.dias_credito,
    'fecha_emision', NEW.fecha_emision,
    'operador', NEW.operador,
    'cliente_snapshot', v_cliente,
    'organizacion_snapshot', v_org,
    'conceptos', v_conceptos
  );
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.consolidar_proformas(p_embarque_id uuid, p_cliente_id uuid, p_cliente_nombre text, p_expediente text, p_bl_master text, p_operador text, p_dias_credito integer, p_organization_id uuid, p_proforma_ids uuid[], p_tasa_iva numeric DEFAULT 0.16, p_request_id uuid DEFAULT NULL::uuid) RETURNS public.proformas
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_nueva          public.proformas;
  v_cached         jsonb;
  v_caller_org     uuid;
  v_org_efectiva   uuid;
  v_count          int;
  v_numero         text;
  v_subtotal_usd   numeric := 0;
  v_iva_usd        numeric := 0;
  v_total_usd      numeric := 0;
  v_subtotal_mxn   numeric := 0;
  v_iva_mxn        numeric := 0;
  v_total_mxn      numeric := 0;
  v_no_soportados  int;
BEGIN
  v_cached := public.idempotency_claim(p_request_id, 'consolidar_proformas');
  IF v_cached IS NOT NULL THEN
    SELECT * INTO v_nueva FROM public.proformas WHERE id = (v_cached->>'id')::uuid;
    IF FOUND THEN RETURN v_nueva; END IF;
  END IF;
  v_caller_org := public.current_user_org_id();
  IF public.has_role(auth.uid(), 'super_admin'::app_role) THEN
    v_org_efectiva := p_organization_id;
  ELSE
    v_org_efectiva := v_caller_org;
  END IF;
  PERFORM public._assert_writer(v_org_efectiva);
  IF p_proforma_ids IS NULL OR array_length(p_proforma_ids, 1) IS NULL OR array_length(p_proforma_ids, 1) < 2 THEN
    RAISE EXCEPTION 'Selecciona al menos 2 proformas para consolidar';
  END IF;
  SELECT count(*) INTO v_count
  FROM public.proformas
  WHERE id = ANY(p_proforma_ids) AND organization_id = v_org_efectiva;
  IF v_count <> array_length(p_proforma_ids, 1) THEN
    RAISE EXCEPTION 'Una o más proformas no existen o no pertenecen a la organización';
  END IF;
  -- Ola 3: la consolidación no puede cruzar embarques.
  IF EXISTS (
    SELECT 1 FROM public.proformas
    WHERE id = ANY(p_proforma_ids)
      AND embarque_id IS DISTINCT FROM p_embarque_id
  ) THEN
    RAISE EXCEPTION
      'LC_PROFORMA_EMBARQUE_AJENO: todas las proformas a consolidar deben pertenecer al mismo embarque'
      USING ERRCODE = 'P0001';
  END IF;
  -- Ola 2 · A: guard equivalente al de crear_proforma_atomica sobre los
  -- conceptos subyacentes (una moneda no soportada consolidaba en $0).
  SELECT COUNT(*) INTO v_no_soportados
  FROM public.conceptos_venta cv
  WHERE cv.proforma_id = ANY(p_proforma_ids)
    AND cv.organization_id = v_org_efectiva
    AND cv.deleted_at IS NULL
    AND cv.moneda NOT IN ('MXN', 'USD');
  IF v_no_soportados > 0 THEN
    RAISE EXCEPTION 'LC_MONEDA_VENTA_NO_SOPORTADA: % concepto(s) de venta tienen una moneda no soportada; sólo se puede facturar en MXN o USD', v_no_soportados
      USING ERRCODE = 'P0001';
  END IF;
  v_numero := public.generar_numero_proforma(v_org_efectiva);
  -- El encabezado nace en cero y se recalcula abajo como la suma EXACTA del
  -- detalle regenerado (A-1): copiar los totales persistidos de las proformas
  -- origen podía no cuadrar con el detalle.
  INSERT INTO public.proformas (
    numero, embarque_id, cliente_id, cliente_nombre, expediente, bl_master,
    subtotal_usd, iva_usd, total_usd, subtotal_mxn, iva_mxn, total_mxn,
    notas, operador, dias_credito, organization_id,
    estado_revision, es_consolidada, proformas_origen, tasa_iva_aplicada
  ) VALUES (
    v_numero, p_embarque_id, p_cliente_id, p_cliente_nombre, p_expediente, p_bl_master,
    0, 0, 0, 0, 0, 0,
    'Consolidación de ' || array_length(p_proforma_ids, 1) || ' proformas',
    p_operador, p_dias_credito, v_org_efectiva,
    'aprobada', true, p_proforma_ids, p_tasa_iva
  ) RETURNING * INTO v_nueva;
  -- A-1: cantidad SIN ::int (BL-1 permite decimales); IVA por LÍNEA con la
  -- tasa propia de cada concepto (canon resolverTasaConcepto: tasa explícita
  -- si existe; si no, la global cuando aplica_iva, y 0 en caso contrario) y
  -- redondeo por línea (BL-12). La tasa efectiva entra al GROUP BY para no
  -- mezclar líneas gravadas al 16% con líneas al 8% frontera.
  INSERT INTO public.proforma_conceptos_consolidados (
    proforma_id, embarque_id, contenedor, tipo_contenedor,
    descripcion, cantidad, precio_unitario, total, moneda, aplica_iva, iva,
    organization_id, tasa_iva_aplicada
  )
  SELECT
    v_nueva.id, cv.embarque_id,
    COALESCE(NULLIF(ec.numero_contenedor, ''), NULLIF(e.contenedor, ''), 'Sin contenedor'),
    COALESCE(NULLIF(ec.tipo_contenedor, ''), NULLIF(e.tipo_contenedor, '')),
    cv.descripcion, SUM(cv.cantidad), cv.precio_unitario,
    ROUND(SUM(cv.cantidad * cv.precio_unitario), 2), cv.moneda, cv.aplica_iva,
    ROUND(SUM(cv.cantidad * cv.precio_unitario)
          * COALESCE(cv.tasa_iva_aplicada, CASE WHEN cv.aplica_iva THEN p_tasa_iva ELSE 0 END), 2),
    v_org_efectiva,
    COALESCE(cv.tasa_iva_aplicada, CASE WHEN cv.aplica_iva THEN p_tasa_iva ELSE 0 END)
  FROM public.conceptos_venta cv
  LEFT JOIN public.embarques e ON e.id = cv.embarque_id
  LEFT JOIN public.embarque_contenedores ec ON ec.id = cv.contenedor_id
  WHERE cv.proforma_id = ANY(p_proforma_ids)
    AND cv.organization_id = v_org_efectiva
    AND cv.embarque_id = p_embarque_id
    AND cv.deleted_at IS NULL
  GROUP BY cv.embarque_id,
    COALESCE(NULLIF(ec.numero_contenedor, ''), NULLIF(e.contenedor, ''), 'Sin contenedor'),
    COALESCE(NULLIF(ec.tipo_contenedor, ''), NULLIF(e.tipo_contenedor, '')),
    cv.descripcion, cv.precio_unitario, cv.moneda, cv.aplica_iva,
    COALESCE(cv.tasa_iva_aplicada, CASE WHEN cv.aplica_iva THEN p_tasa_iva ELSE 0 END);
  -- Encabezado = Σ del detalle recién generado (alineado con
  -- calcularTotalesProforma: subtotal sin IVA, iva por línea, total = suma).
  SELECT
    COALESCE(SUM(pcc.total) FILTER (WHERE pcc.moneda = 'USD'), 0),
    COALESCE(SUM(pcc.iva)   FILTER (WHERE pcc.moneda = 'USD'), 0),
    COALESCE(SUM(pcc.total) FILTER (WHERE pcc.moneda = 'MXN'), 0),
    COALESCE(SUM(pcc.iva)   FILTER (WHERE pcc.moneda = 'MXN'), 0)
  INTO v_subtotal_usd, v_iva_usd, v_subtotal_mxn, v_iva_mxn
  FROM public.proforma_conceptos_consolidados pcc
  WHERE pcc.proforma_id = v_nueva.id;
  v_total_usd := v_subtotal_usd + v_iva_usd;
  v_total_mxn := v_subtotal_mxn + v_iva_mxn;
  UPDATE public.proformas
  SET subtotal_usd = v_subtotal_usd, iva_usd = v_iva_usd, total_usd = v_total_usd,
      subtotal_mxn = v_subtotal_mxn, iva_mxn = v_iva_mxn, total_mxn = v_total_mxn
  WHERE id = v_nueva.id
  RETURNING * INTO v_nueva;
  UPDATE public.proformas
  SET estado_revision = 'consolidada', consolidada_en = v_nueva.id
  WHERE id = ANY(p_proforma_ids);
  -- v13.301.69 FIX BUG 2: repuntar conceptos_venta a la proforma consolidada
  -- para que sync_conceptos_venta_facturado propague correctamente al
  -- facturar/cancelar. Bypass defensivo de los guards internos.
  PERFORM set_config('app.bypass_cierre', 'on', true);
  UPDATE public.conceptos_venta
     SET proforma_id = v_nueva.id
   WHERE proforma_id = ANY(p_proforma_ids)
     AND organization_id = v_org_efectiva
     AND deleted_at IS NULL;
  PERFORM set_config('app.bypass_cierre', 'off', true);
  PERFORM public.idempotency_store(p_request_id, jsonb_build_object('id', v_nueva.id));
  RETURN v_nueva;
END;
$_$;
CREATE FUNCTION public.convertir_a_mxn(_monto numeric, _moneda text, _tc_usd numeric, _tc_eur numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mon text := upper(COALESCE(_moneda,'MXN'));
  v_tc  numeric;
BEGIN
  IF _monto IS NULL THEN RETURN 0; END IF;
  IF v_mon = 'MXN' THEN
    RETURN round(_monto, 2);
  END IF;
  IF v_mon NOT IN ('USD','EUR') THEN
    RAISE EXCEPTION 'LC_MONEDA_NO_SOPORTADA: %', v_mon USING ERRCODE = 'P0001';
  END IF;
  v_tc := CASE v_mon WHEN 'USD' THEN _tc_usd ELSE _tc_eur END;
  IF v_tc IS NULL OR v_tc <= 0 THEN
    RAISE EXCEPTION 'LC_TC_REQUERIDO: tipo de cambio % no definido', v_mon
      USING ERRCODE = 'P0001';
  END IF;
  RETURN round(_monto * v_tc, 2);
END;
$$;
CREATE FUNCTION public.convertir_lead_rpc(p_lead_id uuid, p_crear_cliente boolean, p_cliente_id uuid, p_nombre_oportunidad text, p_monto_estimado numeric, p_moneda text, p_fecha_estimada_cierre date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lead public.crm_leads;
  v_cliente_id uuid;
  v_cliente_nombre text := '';
  v_etapa_id uuid;
  v_prob integer;
  v_op_id uuid;
  v_email_actual text;
BEGIN
  SELECT * INTO v_lead FROM public.crm_leads
   WHERE id = p_lead_id AND deleted_at IS NULL
   FOR UPDATE;
  IF v_lead.id IS NULL THEN
    RAISE EXCEPTION 'LC_LEAD_NO_ENCONTRADO';
  END IF;
  IF auth.uid() IS NOT NULL AND NOT public.is_org_member(v_lead.organization_id) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  IF v_lead.estado = 'Convertido'::crm_lead_estado AND v_lead.oportunidad_convertida_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'cliente_id', v_lead.cliente_convertido_id,
      'oportunidad_id', v_lead.oportunidad_convertida_id,
      'creado', false
    );
  END IF;
  IF NULLIF(btrim(COALESCE(p_nombre_oportunidad, '')), '') IS NULL THEN
    RAISE EXCEPTION 'LC_OPORTUNIDAD_SIN_NOMBRE';
  END IF;
  -- Candado: el alta de clientes vive sólo en el módulo de Clientes.
  IF COALESCE(p_crear_cliente, false) AND p_cliente_id IS NULL THEN
    RAISE EXCEPTION 'LC_LEAD_ALTA_CLIENTE_PROHIBIDA';
  END IF;
  IF p_cliente_id IS NOT NULL THEN
    SELECT id, nombre INTO v_cliente_id, v_cliente_nombre
    FROM public.clientes
    WHERE id = p_cliente_id AND organization_id = v_lead.organization_id AND deleted_at IS NULL;
    IF v_cliente_id IS NULL THEN
      RAISE EXCEPTION 'LC_CLIENTE_NO_ENCONTRADO';
    END IF;
  END IF;
  SELECT id, COALESCE(probabilidad_default, 0) INTO v_etapa_id, v_prob
  FROM public.crm_etapas_pipeline
  WHERE tipo = 'abierta' AND activa = true AND organization_id = v_lead.organization_id
  ORDER BY orden ASC
  LIMIT 1;
  IF v_etapa_id IS NULL THEN
    RAISE EXCEPTION 'LC_PIPELINE_SIN_ETAPAS';
  END IF;
  -- RG13: fallback al correo del usuario que convierte, en línea con
  -- `vendedor_id = COALESCE(v_lead.vendedor_id, auth.uid())`.
  SELECT email INTO v_email_actual FROM auth.users WHERE id = auth.uid();
  -- O6.2: la oportunidad hereda sector/origen/destino del lead.
  INSERT INTO public.crm_oportunidades (
    organization_id, nombre, lead_id, cliente_id, cliente_nombre, etapa_id, probabilidad,
    monto_estimado, moneda, fecha_estimada_cierre, vendedor_id, vendedor_email, modo,
    sector, origen, destino, created_by
  ) VALUES (
    v_lead.organization_id,
    btrim(p_nombre_oportunidad),
    v_lead.id,
    v_cliente_id,
    COALESCE(v_cliente_nombre, ''),
    v_etapa_id,
    v_prob,
    COALESCE(p_monto_estimado, 0),
    COALESCE(NULLIF(p_moneda, ''), 'MXN'),
    p_fecha_estimada_cierre,
    COALESCE(v_lead.vendedor_id, auth.uid()),
    COALESCE(NULLIF(btrim(COALESCE(v_lead.vendedor_email, '')), ''), v_email_actual, ''),
    COALESCE(v_lead.interes_modo, ''),
    v_lead.sector,
    COALESCE(v_lead.origen, ''),
    COALESCE(v_lead.destino, ''),
    auth.uid()
  )
  RETURNING id INTO v_op_id;
  UPDATE public.crm_leads
     SET estado = 'Convertido'::crm_lead_estado,
         cliente_convertido_id = v_cliente_id,
         oportunidad_convertida_id = v_op_id,
         updated_at = now()
   WHERE id = p_lead_id;
  RETURN jsonb_build_object('cliente_id', v_cliente_id, 'oportunidad_id', v_op_id, 'creado', true);
END;
$$;
CREATE FUNCTION public.convertir_monto_dof(p_monto numeric, p_moneda_origen text, p_moneda_destino text, p_fecha date) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_o numeric; v_d numeric;
BEGIN
  IF p_monto IS NULL THEN RETURN NULL; END IF;
  IF UPPER(COALESCE(p_moneda_origen,'MXN')) = UPPER(COALESCE(p_moneda_destino,'MXN')) THEN
    RETURN p_monto;
  END IF;
  v_o := public.tc_dof_moneda(p_fecha, p_moneda_origen);
  v_d := public.tc_dof_moneda(p_fecha, p_moneda_destino);
  IF v_o IS NULL OR v_d IS NULL OR v_o <= 0 OR v_d <= 0 THEN
    RAISE EXCEPTION 'LC_SIN_TC_DOF: no hay tipo de cambio DOF para % o % al %.',
      p_moneda_origen, p_moneda_destino, p_fecha
      USING ERRCODE = '22023';
  END IF;
  RETURN round(p_monto * v_o / v_d, 4);
END;
$$;
CREATE FUNCTION public.convertir_monto_pago_a_factura(p_monto numeric, p_moneda_pago public.moneda, p_tc_pago numeric, p_moneda_fact public.moneda, p_tc_fact numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tc numeric;
  v_tc_fact numeric;
  v_mxn numeric;
BEGIN
  IF p_monto IS NULL THEN RETURN NULL; END IF;
  IF p_moneda_pago = p_moneda_fact THEN RETURN p_monto; END IF;
  -- Ruta histórica MXN<->USD: idéntica (usa el TC del pago).
  IF (p_moneda_pago = 'MXN' AND p_moneda_fact = 'USD')
     OR (p_moneda_pago = 'USD' AND p_moneda_fact = 'MXN') THEN
    v_tc := NULLIF(p_tc_pago, 0);
    IF v_tc IS NULL OR v_tc <= 0 THEN
      RAISE EXCEPTION 'LC_PAGO_TC_REQUERIDO: capture el tipo de cambio del pago (%->%)',
        p_moneda_pago, p_moneda_fact USING ERRCODE = '22023';
    END IF;
    IF p_moneda_pago = 'MXN' THEN RETURN round(p_monto / v_tc, 4);
    ELSE                          RETURN round(p_monto * v_tc, 4);
    END IF;
  END IF;
  -- M-2: cruces con EUR (EUR<->MXN, EUR<->USD) pivotean en MXN.
  IF p_moneda_pago = 'MXN' THEN
    v_mxn := p_monto;
  ELSE
    v_tc := NULLIF(p_tc_pago, 0);
    IF v_tc IS NULL OR v_tc <= 0 THEN
      RAISE EXCEPTION 'LC_PAGO_TC_REQUERIDO: capture el tipo de cambio del pago (%->%)',
        p_moneda_pago, p_moneda_fact USING ERRCODE = '22023';
    END IF;
    v_mxn := p_monto * v_tc;
  END IF;
  IF p_moneda_fact = 'MXN' THEN RETURN round(v_mxn, 4); END IF;
  v_tc_fact := NULLIF(p_tc_fact, 0);
  IF v_tc_fact IS NULL OR v_tc_fact <= 0 THEN
    RAISE EXCEPTION 'LC_PAGO_TC_FACTURA_REQUERIDO: la factura en % necesita tipo de cambio para recibir un pago en %.',
      p_moneda_fact, p_moneda_pago USING ERRCODE = '22023';
  END IF;
  RETURN round(v_mxn / v_tc_fact, 4);
END;
$$;
CREATE TABLE public.facturas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    numero text NOT NULL,
    embarque_id uuid,
    expediente text DEFAULT ''::text NOT NULL,
    cliente_id uuid NOT NULL,
    cliente_nombre text DEFAULT ''::text NOT NULL,
    subtotal numeric DEFAULT 0 NOT NULL,
    iva numeric DEFAULT 0 NOT NULL,
    total numeric DEFAULT 0 NOT NULL,
    moneda public.moneda DEFAULT 'MXN'::public.moneda NOT NULL,
    tipo_cambio numeric,
    fecha_emision date DEFAULT CURRENT_DATE NOT NULL,
    fecha_vencimiento date NOT NULL,
    estado public.estado_factura DEFAULT 'Borrador'::public.estado_factura NOT NULL,
    referencia_bl text,
    notas text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    proforma_id uuid,
    factura_pdf_url text,
    factura_xml_url text,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    snapshot_emision jsonb,
    serie_id uuid,
    folio_fiscal bigint,
    rfc_cliente text,
    uso_cfdi text,
    forma_pago text,
    metodo_pago text,
    uuid_fiscal text,
    dias_credito integer,
    facturapi_id text,
    serie text,
    timbrado_en timestamp with time zone,
    timbrado_por uuid,
    cancelacion_motivo text,
    cancelado_en timestamp with time zone,
    enviada_cliente_at timestamp with time zone,
    cotizacion_id uuid,
    origen public.origen_factura DEFAULT 'proforma'::public.origen_factura NOT NULL,
    sustituye_a uuid,
    sustituida_por uuid,
    ambiente public.ambiente_facturapi,
    acuse_cancelacion_xml text,
    acuse_cancelacion_fecha timestamp with time zone,
    acuse_cancelacion_status text,
    factura_xml_backup_path text,
    ret_isr numeric DEFAULT 0 NOT NULL,
    ret_iva numeric DEFAULT 0 NOT NULL,
    uuid_verificado boolean DEFAULT false NOT NULL,
    uuid_estatus_sat text,
    uuid_verificado_fecha timestamp with time zone,
    cancellation_status text,
    cancelacion_solicitada_en timestamp with time zone,
    cancelacion_vence_en timestamp with time zone,
    facturapi_claim_at timestamp with time zone,
    CONSTRAINT facturas_cancelacion_motivo_sat CHECK (((cancelacion_motivo IS NULL) OR (cancelacion_motivo = ANY (ARRAY['01'::text, '02'::text, '03'::text, '04'::text])))),
    CONSTRAINT facturas_cancellation_status_check CHECK ((cancellation_status = ANY (ARRAY['none'::text, 'verifying'::text, 'pending'::text, 'accepted'::text, 'rejected'::text, 'expired'::text]))),
    CONSTRAINT facturas_iva_nonneg CHECK ((iva >= (0)::numeric)),
    CONSTRAINT facturas_subtotal_nonneg CHECK ((subtotal >= (0)::numeric)),
    CONSTRAINT facturas_tipo_cambio_pos CHECK (((tipo_cambio IS NULL) OR (tipo_cambio > (0)::numeric))),
    CONSTRAINT facturas_total_nonneg CHECK ((total >= (0)::numeric)),
    CONSTRAINT facturas_venc_despues_emision CHECK ((fecha_vencimiento >= fecha_emision))
);
ALTER TABLE ONLY public.facturas FORCE ROW LEVEL SECURITY;
CREATE FUNCTION public.convertir_proformas_a_factura(p_proforma_ids uuid[], p_serie_id uuid, p_metodo_pago text, p_forma_pago text, p_uso_cfdi text, p_dias_credito integer DEFAULT NULL::integer, p_notas text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.facturas
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cached jsonb; v_count int; v_first public.proformas;
  v_org uuid; v_caller_org uuid; v_cliente public.clientes;
  v_serie public.factura_series;
  v_subtotal_usd numeric := 0; v_iva_usd numeric := 0; v_total_usd numeric := 0;
  v_subtotal_mxn numeric := 0; v_iva_mxn numeric := 0; v_total_mxn numeric := 0;
  v_distinct_cli int; v_distinct_org int;
  v_factura_ids uuid[] := ARRAY[]::uuid[];
  v_factura_mxn_id uuid; v_factura_usd_id uuid;
  v_numero_tmp text; v_embarque_ids uuid[];
  v_dias int;
BEGIN
  v_cached := public.idempotency_claim(p_request_id, 'convertir_proformas_a_factura');
  IF v_cached IS NOT NULL AND (v_cached ? 'factura_ids') THEN
    RETURN QUERY SELECT * FROM public.facturas
      WHERE id = ANY(ARRAY(SELECT jsonb_array_elements_text(v_cached->'factura_ids'))::uuid[])
        AND deleted_at IS NULL;
    RETURN;
  END IF;
  IF p_proforma_ids IS NULL OR array_length(p_proforma_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Debes proporcionar al menos una proforma';
  END IF;
  IF p_metodo_pago NOT IN ('PUE', 'PPD') THEN
    RAISE EXCEPTION 'Método de pago inválido: %', p_metodo_pago;
  END IF;
  IF coalesce(p_forma_pago, '') = '' OR coalesce(p_uso_cfdi, '') = '' THEN
    RAISE EXCEPTION 'forma_pago y uso_cfdi son obligatorios';
  END IF;
  PERFORM public.convertir_proformas_a_factura_check_embarque_vivo(p_proforma_ids);
  v_caller_org := public.current_user_org_id();
  IF NOT (
    public.es_escritor_financiero(auth.uid())
    OR public.has_role(auth.uid(), 'super_admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'LC_PROFORMA_SIN_PERMISO: rol no autorizado para convertir proformas' USING ERRCODE='P0001';
  END IF;
  PERFORM 1 FROM public.proformas
    WHERE id = ANY(p_proforma_ids) AND deleted_at IS NULL FOR UPDATE;
  SELECT count(*), count(DISTINCT organization_id), count(DISTINCT cliente_id)
    INTO v_count, v_distinct_org, v_distinct_cli
  FROM public.proformas
  WHERE id = ANY(p_proforma_ids) AND deleted_at IS NULL;
  IF v_count <> array_length(p_proforma_ids, 1) THEN
    RAISE EXCEPTION 'Una o más proformas no existen o están eliminadas';
  END IF;
  IF v_distinct_org <> 1 THEN
    RAISE EXCEPTION 'Las proformas deben pertenecer a una sola organización';
  END IF;
  IF v_distinct_cli <> 1 THEN
    RAISE EXCEPTION 'Las proformas deben pertenecer a un solo cliente';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.proformas
    WHERE id = ANY(p_proforma_ids) AND estado_proforma = 'facturada'
  ) THEN
    RAISE EXCEPTION 'LC_PROFORMA_YA_FACTURADA: una o más proformas ya fueron facturadas' USING ERRCODE='P0002';
  END IF;
  SELECT * INTO v_first FROM public.proformas
    WHERE id = ANY(p_proforma_ids) ORDER BY created_at ASC LIMIT 1;
  v_org := v_first.organization_id;
  IF NOT public.has_role(auth.uid(), 'super_admin'::app_role) AND v_org IS DISTINCT FROM v_caller_org THEN
    RAISE EXCEPTION 'No puedes convertir proformas de otra organización';
  END IF;
  SELECT * INTO v_cliente FROM public.clientes WHERE id = v_first.cliente_id;
  IF v_cliente IS NULL THEN RAISE EXCEPTION 'Cliente no encontrado'; END IF;
  SELECT * INTO v_serie FROM public.factura_series WHERE id = p_serie_id AND organization_id = v_org;
  IF v_serie IS NULL THEN RAISE EXCEPTION 'Serie no encontrada'; END IF;
  -- Cascada de plazo de crédito: parámetro → proforma → ficha del cliente → 0.
  v_dias := COALESCE(NULLIF(p_dias_credito, 0), v_first.dias_credito, v_cliente.dias_credito, p_dias_credito, 0);
  SELECT array_agg(DISTINCT embarque_id) INTO v_embarque_ids
  FROM public.proformas
  WHERE id = ANY(p_proforma_ids) AND embarque_id IS NOT NULL;
  IF v_first.es_consolidada THEN
    SELECT
      COALESCE(SUM(CASE WHEN moneda = 'MXN'::public.moneda THEN total ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN moneda = 'USD'::public.moneda THEN total ELSE 0 END), 0)
    INTO v_subtotal_mxn, v_subtotal_usd
    FROM public.proforma_conceptos_consolidados
    WHERE proforma_id = ANY(p_proforma_ids) AND deleted_at IS NULL;
  ELSE
    SELECT
      COALESCE(SUM(CASE WHEN moneda = 'MXN'::public.moneda THEN cantidad * precio_unitario ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN moneda = 'USD'::public.moneda THEN cantidad * precio_unitario ELSE 0 END), 0)
    INTO v_subtotal_mxn, v_subtotal_usd
    FROM public.conceptos_venta
    WHERE proforma_id = ANY(p_proforma_ids) AND deleted_at IS NULL;
  END IF;
  IF v_subtotal_mxn > 0 THEN
    v_numero_tmp := 'BORRADOR-' || substring(replace(gen_random_uuid()::text, '-', '') from 1 for 12);
    INSERT INTO public.facturas (
      numero, embarque_id, expediente, cliente_id, cliente_nombre,
      subtotal, iva, total, moneda, tipo_cambio,
      fecha_emision, fecha_vencimiento, estado,
      organization_id, proforma_id,
      serie_id, folio_fiscal, serie,
      rfc_cliente, uso_cfdi, forma_pago, metodo_pago, dias_credito,
      notas, origen
    ) VALUES (
      v_numero_tmp, v_first.embarque_id, v_first.expediente, v_first.cliente_id, v_first.cliente_nombre,
      0, 0, 0, 'MXN'::public.moneda, 1,
      CURRENT_DATE,
      CURRENT_DATE + make_interval(days => v_dias),
      'Borrador'::estado_factura, v_org,
      CASE WHEN array_length(p_proforma_ids, 1) = 1 THEN p_proforma_ids[1] ELSE NULL END,
      p_serie_id, NULL, NULL,
      v_cliente.rfc, p_uso_cfdi, p_forma_pago, p_metodo_pago, v_dias,
      p_notas, 'conversion_proforma'
    ) RETURNING id INTO v_factura_mxn_id;
    PERFORM public._convertir_proformas_insertar_conceptos(
      v_factura_mxn_id, p_proforma_ids, v_org, v_first.es_consolidada, 'MXN'::public.moneda
    );
    -- BUG-17: recalcular desde el `total` guardado del renglón (pcc.total en
    -- consolidadas), no desde cantidad*precio_unitario que puede diverger.
    SELECT
      COALESCE(SUM(total), 0),
      COALESCE(SUM(total * COALESCE(tasa_iva_aplicada, 0)), 0)
    INTO v_subtotal_mxn, v_iva_mxn
    FROM public.conceptos_factura
    WHERE factura_id = v_factura_mxn_id AND deleted_at IS NULL;
    v_subtotal_mxn := round(v_subtotal_mxn, 2);
    v_iva_mxn := round(v_iva_mxn, 2);
    v_total_mxn := v_subtotal_mxn + v_iva_mxn;
    UPDATE public.facturas
    SET subtotal = v_subtotal_mxn, iva = v_iva_mxn, total = v_total_mxn
    WHERE id = v_factura_mxn_id;
    IF v_embarque_ids IS NOT NULL THEN
      INSERT INTO public.factura_embarques (factura_id, embarque_id, organization_id)
      SELECT v_factura_mxn_id, unnest(v_embarque_ids), v_org
      ON CONFLICT DO NOTHING;
    END IF;
    v_factura_ids := array_append(v_factura_ids, v_factura_mxn_id);
    INSERT INTO public.bitacora_actividad (
      organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles
    ) VALUES (
      v_org, auth.uid(),
      (SELECT email FROM auth.users WHERE id = auth.uid()),
      'factura.borrador_generado', 'facturacion', v_factura_mxn_id, v_numero_tmp,
      jsonb_build_object('proforma_ids', p_proforma_ids, 'serie_id', p_serie_id, 'moneda', 'MXN',
                        'embarque_ids', to_jsonb(v_embarque_ids),
                        'nota', 'Folio interno se asignará al timbrar (FacturAPI)')
    );
  END IF;
  IF v_subtotal_usd > 0 THEN
    v_numero_tmp := 'BORRADOR-' || substring(replace(gen_random_uuid()::text, '-', '') from 1 for 12);
    INSERT INTO public.facturas (
      numero, embarque_id, expediente, cliente_id, cliente_nombre,
      subtotal, iva, total, moneda, tipo_cambio,
      fecha_emision, fecha_vencimiento, estado,
      organization_id, proforma_id,
      serie_id, folio_fiscal, serie,
      rfc_cliente, uso_cfdi, forma_pago, metodo_pago, dias_credito,
      notas, origen
    ) VALUES (
      v_numero_tmp, v_first.embarque_id, v_first.expediente, v_first.cliente_id, v_first.cliente_nombre,
      0, 0, 0, 'USD'::public.moneda, 1,
      CURRENT_DATE,
      CURRENT_DATE + make_interval(days => v_dias),
      'Borrador'::estado_factura, v_org,
      CASE WHEN array_length(p_proforma_ids, 1) = 1 THEN p_proforma_ids[1] ELSE NULL END,
      p_serie_id, NULL, NULL,
      v_cliente.rfc, p_uso_cfdi, p_forma_pago, p_metodo_pago, v_dias,
      p_notas, 'conversion_proforma'
    ) RETURNING id INTO v_factura_usd_id;
    PERFORM public._convertir_proformas_insertar_conceptos(
      v_factura_usd_id, p_proforma_ids, v_org, v_first.es_consolidada, 'USD'::public.moneda
    );
    -- BUG-17: recalcular desde el `total` guardado del renglón (pcc.total en
    -- consolidadas), no desde cantidad*precio_unitario que puede diverger.
    SELECT
      COALESCE(SUM(total), 0),
      COALESCE(SUM(total * COALESCE(tasa_iva_aplicada, 0)), 0)
    INTO v_subtotal_usd, v_iva_usd
    FROM public.conceptos_factura
    WHERE factura_id = v_factura_usd_id AND deleted_at IS NULL;
    v_subtotal_usd := round(v_subtotal_usd, 2);
    v_iva_usd := round(v_iva_usd, 2);
    v_total_usd := v_subtotal_usd + v_iva_usd;
    UPDATE public.facturas
    SET subtotal = v_subtotal_usd, iva = v_iva_usd, total = v_total_usd
    WHERE id = v_factura_usd_id;
    IF v_embarque_ids IS NOT NULL THEN
      INSERT INTO public.factura_embarques (factura_id, embarque_id, organization_id)
      SELECT v_factura_usd_id, unnest(v_embarque_ids), v_org
      ON CONFLICT DO NOTHING;
    END IF;
    v_factura_ids := array_append(v_factura_ids, v_factura_usd_id);
    INSERT INTO public.bitacora_actividad (
      organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles
    ) VALUES (
      v_org, auth.uid(),
      (SELECT email FROM auth.users WHERE id = auth.uid()),
      'factura.borrador_generado', 'facturacion', v_factura_usd_id, v_numero_tmp,
      jsonb_build_object('proforma_ids', p_proforma_ids, 'serie_id', p_serie_id, 'moneda', 'USD',
                        'embarque_ids', to_jsonb(v_embarque_ids),
                        'nota', 'Folio interno se asignará al timbrar (FacturAPI)')
    );
  END IF;
  IF array_length(v_factura_ids, 1) > 0 THEN
    UPDATE public.proformas
    SET estado_proforma = 'facturada', fecha_facturacion = CURRENT_DATE
    WHERE id = ANY(p_proforma_ids) AND estado_proforma <> 'facturada';
  END IF;
  IF p_request_id IS NOT NULL THEN
    PERFORM public.idempotency_store(p_request_id, jsonb_build_object('factura_ids', to_jsonb(v_factura_ids)));
  END IF;
  RETURN QUERY SELECT * FROM public.facturas WHERE id = ANY(v_factura_ids);
END;
$$;
CREATE FUNCTION public.convertir_proformas_a_factura_check_embarque_vivo(p_proforma_ids uuid[]) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_expediente_muerto text;
BEGIN
  SELECT e.expediente INTO v_expediente_muerto
  FROM public.proformas p
  JOIN public.embarques e ON e.id = p.embarque_id
  WHERE p.id = ANY(p_proforma_ids)
    AND e.deleted_at IS NOT NULL
  LIMIT 1;
  IF v_expediente_muerto IS NOT NULL THEN
    RAISE EXCEPTION 'LC_EMBARQUE_ELIMINADO: el embarque % ya fue eliminado; no se puede facturar sus proformas', v_expediente_muerto
      USING ERRCODE = 'check_violation',
            HINT = v_expediente_muerto;
  END IF;
END;
$$;
CREATE FUNCTION public.convertir_prospecto_a_cliente_rpc(p_cotizacion_id uuid, p_cliente jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_es_prospecto boolean;
  v_cliente_id uuid;
  v_nombre text;
  v_rfc text;
  v_creado boolean := false;
  v_oportunidad_id uuid;
  v_lead_id uuid;
  v_empresa text;
  v_revinculadas int;
BEGIN
  SELECT organization_id, es_prospecto, cliente_id, oportunidad_id,
         NULLIF(btrim(COALESCE(prospecto_empresa, '')), '')
    INTO v_org, v_es_prospecto, v_cliente_id, v_oportunidad_id, v_empresa
  FROM public.cotizaciones WHERE id = p_cotizacion_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_COTIZACION_NO_ENCONTRADA';
  END IF;
  IF auth.uid() IS NOT NULL AND NOT public.is_org_member(v_org) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  -- Idempotencia: si ya se convirtió, devolver el cliente existente.
  IF v_cliente_id IS NOT NULL AND COALESCE(v_es_prospecto, false) = false THEN
    SELECT nombre INTO v_nombre FROM public.clientes WHERE id = v_cliente_id;
    RETURN jsonb_build_object('cliente_id', v_cliente_id, 'nombre', v_nombre, 'creado', false);
  END IF;
  v_nombre := NULLIF(btrim(COALESCE(p_cliente->>'nombre', '')), '');
  IF v_nombre IS NULL THEN
    RAISE EXCEPTION 'LC_CLIENTE_SIN_NOMBRE';
  END IF;
  v_rfc := NULLIF(btrim(upper(COALESCE(p_cliente->>'rfc', ''))), '');
  -- Reutiliza cliente existente con el mismo RFC dentro de la organización.
  -- RG2: los RFC genéricos del SAT (XAXX010101000 público en general,
  -- XEXX010101000 extranjeros) no identifican a nadie: nunca matchean.
  IF v_rfc IS NOT NULL AND v_rfc NOT IN ('XAXX010101000', 'XEXX010101000') THEN
    SELECT id INTO v_cliente_id
    FROM public.clientes
    WHERE organization_id = v_org AND upper(btrim(rfc)) = v_rfc AND deleted_at IS NULL
      AND upper(btrim(rfc)) NOT IN ('XAXX010101000', 'XEXX010101000')
    LIMIT 1;
  ELSE
    v_cliente_id := NULL;
  END IF;
  IF v_cliente_id IS NULL THEN
    INSERT INTO public.clientes (
      organization_id, nombre, contacto, email, telefono, rfc, direccion, ciudad, estado, cp
    ) VALUES (
      v_org,
      v_nombre,
      COALESCE(p_cliente->>'contacto', ''),
      COALESCE(p_cliente->>'email', ''),
      COALESCE(p_cliente->>'telefono', ''),
      COALESCE(v_rfc, ''),
      COALESCE(p_cliente->>'direccion', ''),
      COALESCE(p_cliente->>'ciudad', ''),
      COALESCE(p_cliente->>'estado', ''),
      COALESCE(p_cliente->>'cp', '')
    )
    RETURNING id INTO v_cliente_id;
    v_creado := true;
  END IF;
  UPDATE public.cotizaciones
     SET cliente_id = v_cliente_id,
         cliente_nombre = v_nombre,
         es_prospecto = false,
         updated_at = now()
   WHERE id = p_cotizacion_id;
  -- Re-vincula el historial: otras cotizaciones del mismo prospecto (misma
  -- empresa normalizada, misma org, aún sin cliente) pasan al cliente nuevo.
  v_revinculadas := 0;
  IF v_empresa IS NOT NULL THEN
    UPDATE public.cotizaciones
       SET cliente_id = v_cliente_id,
           cliente_nombre = v_nombre,
           es_prospecto = false,
           updated_at = now()
     WHERE organization_id = v_org
       AND id <> p_cotizacion_id
       AND deleted_at IS NULL
       AND COALESCE(es_prospecto, false) = true
       AND cliente_id IS NULL
       AND lower(btrim(prospecto_empresa)) = lower(v_empresa);
    GET DIAGNOSTICS v_revinculadas = ROW_COUNT;
  END IF;
  -- Propagación CRM atómica: oportunidad y lead quedan ligados al cliente.
  IF v_oportunidad_id IS NOT NULL THEN
    UPDATE public.crm_oportunidades
       SET cliente_id = v_cliente_id,
           cliente_nombre = v_nombre,
           updated_at = now()
     WHERE id = v_oportunidad_id AND organization_id = v_org
    RETURNING lead_id INTO v_lead_id;
    IF v_lead_id IS NOT NULL THEN
      UPDATE public.crm_leads
         SET estado = 'Convertido'::crm_lead_estado,
             cliente_convertido_id = v_cliente_id,
             oportunidad_convertida_id = v_oportunidad_id,
             updated_at = now()
       WHERE id = v_lead_id AND organization_id = v_org;
    END IF;
  END IF;
  RETURN jsonb_build_object(
    'cliente_id', v_cliente_id, 'nombre', v_nombre, 'creado', v_creado,
    'oportunidad_id', v_oportunidad_id, 'lead_id', v_lead_id,
    'cotizaciones_revinculadas', v_revinculadas
  );
END;
$$;
CREATE FUNCTION public.costeo_tarifa_estado_actual(p_estado text, p_vigente_hasta date) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
           WHEN p_estado IN ('borrador','reemplazada') THEN p_estado
           WHEN p_vigente_hasta IS NOT NULL
                AND p_vigente_hasta < (now() AT TIME ZONE 'America/Mexico_City')::date
             THEN 'vencida'
           ELSE 'vigente'
         END;
$$;
CREATE FUNCTION public.costeo_tarifas_agente_force_borrador() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.has_role(auth.uid(), 'agente_carga') THEN
    IF TG_OP = 'UPDATE' AND OLD.estado_aprobacion IN ('vigente','reemplazada') THEN
      RAISE EXCEPTION 'no se puede editar una tarifa % directamente; duplica para crear una nueva versión', OLD.estado_aprobacion;
    END IF;
    NEW.estado_aprobacion := 'borrador';
    NEW.motivo_rechazo := NULL;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.costeo_tarifas_marcar_reemplazadas() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hoy_mx date := (now() AT TIME ZONE 'America/Mexico_City')::date;
BEGIN
  IF NEW.estado <> 'vigente' OR NEW.estado_aprobacion <> 'vigente' THEN
    RETURN NEW;
  END IF;
  IF NEW.vigente_hasta IS NOT NULL AND NEW.vigente_hasta < v_hoy_mx THEN
    RETURN NEW;
  END IF;
  UPDATE public.costeo_tarifas
     SET estado = 'reemplazada',
         reemplazada_por = NEW.id,
         updated_at = now()
   WHERE organization_id = NEW.organization_id
     AND agente_id = NEW.agente_id
     AND naviera_id = NEW.naviera_id
     AND ruta_id = NEW.ruta_id
     AND tipo_contenedor_id = NEW.tipo_contenedor_id
     AND id <> NEW.id
     AND estado = 'vigente'
     AND reemplazada_por IS NULL
     AND vigente_desde <= NEW.vigente_desde
     AND vigente_hasta >= NEW.vigente_desde;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.costeo_tarifas_match_agente_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agente_org uuid;
BEGIN
  SELECT organization_id INTO v_agente_org
    FROM public.costeo_agentes
   WHERE id = NEW.agente_id;
  IF v_agente_org IS NULL THEN
    RAISE EXCEPTION 'Agente % no existe', NEW.agente_id;
  END IF;
  -- Si vino con org distinta, la corregimos silenciosamente.
  NEW.organization_id := v_agente_org;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.cotizacion_totales_conceptos(p_conceptos jsonb) RETURNS TABLE(subtotal_usd numeric, iva_usd numeric, total_usd numeric, subtotal_mxn numeric, iva_mxn numeric, total_mxn numeric)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_elem   jsonb;
  v_cant   numeric;
  v_precio numeric;
  v_tasa   numeric;
  v_moneda text;
  v_sub    numeric;
  v_iva    numeric;
BEGIN
  subtotal_usd := 0; iva_usd := 0; total_usd := 0;
  subtotal_mxn := 0; iva_mxn := 0; total_mxn := 0;
  IF p_conceptos IS NULL OR jsonb_typeof(p_conceptos) IS NULL THEN
    RETURN NEXT; RETURN;
  END IF;
  IF jsonb_typeof(p_conceptos) <> 'array' THEN
    RAISE EXCEPTION 'LC_COTIZACION_CONCEPTO_INVALIDO: conceptos_venta debe ser un arreglo jsonb'
      USING ERRCODE = '23514';
  END IF;
  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_conceptos)
  LOOP
    v_cant   := COALESCE((v_elem ->> 'cantidad')::numeric, 0);
    v_precio := COALESCE((v_elem ->> 'precio_unitario')::numeric, 0);
    v_tasa   := COALESCE(
                  (v_elem ->> 'tasa_iva_aplicada')::numeric,
                  CASE WHEN COALESCE((v_elem ->> 'aplica_iva')::boolean, false) THEN 0.16 ELSE 0 END
                );
    v_moneda := upper(COALESCE(NULLIF(v_elem ->> 'moneda', ''), 'USD'));
    IF v_cant < 0 OR v_precio < 0 OR v_tasa < 0 OR v_tasa > 1 THEN
      RAISE EXCEPTION 'LC_COTIZACION_CONCEPTO_INVALIDO: cantidad/precio negativos o tasa de IVA fuera de [0,1] en concepto "%"',
        COALESCE(v_elem ->> 'descripcion', '?')
        USING ERRCODE = '23514';
    END IF;
    v_sub := ROUND(v_cant * v_precio, 2);
    v_iva := ROUND(v_sub * v_tasa, 2);
    IF v_moneda = 'USD' THEN
      subtotal_usd := subtotal_usd + v_sub;
      iva_usd      := iva_usd + v_iva;
    ELSIF v_moneda = 'MXN' THEN
      subtotal_mxn := subtotal_mxn + v_sub;
      iva_mxn      := iva_mxn + v_iva;
    ELSE
      -- BUG-11: moneda no soportada — antes el concepto no sumaba ni fallaba
      -- (un concepto EUR quedaba en 0 en silencio y la cotización pasaba).
      RAISE EXCEPTION 'LC_COTIZACION_MONEDA_NO_SOPORTADA: moneda "%" no soportada en concepto "%" (soportadas: USD, MXN)',
        v_moneda, COALESCE(v_elem ->> 'descripcion', '?')
        USING ERRCODE = '23514';
    END IF;
  END LOOP;
  total_usd := subtotal_usd + iva_usd;
  total_mxn := subtotal_mxn + iva_mxn;
  RETURN NEXT;
END;
$$;
CREATE FUNCTION public.cotizaciones_guard_en_operacion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- QA-R2 R-04: procesos internos de sincronización (p.ej.
  -- recalcular_subtotal_cotizacion) levantan esta GUC transaccional.
  IF current_setting('app.cotizacion_sync', true) = '1' THEN
    RETURN NEW;
  END IF;
  IF (OLD.estado IN ('En operación'::public.estado_cotizacion,
                     'Aceptada'::public.estado_cotizacion)
      OR OLD.embarque_id IS NOT NULL)
     AND (NEW.subtotal IS DISTINCT FROM OLD.subtotal
       OR NEW.moneda IS DISTINCT FROM OLD.moneda
       OR NEW.conceptos_venta IS DISTINCT FROM OLD.conceptos_venta) THEN
    RAISE EXCEPTION
      'LC_COTIZACION_INMUTABLE: la cotización ya fue aceptada o está en operación; sus importes y conceptos no pueden cambiar (usa una nueva versión)'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.cotizaciones_listado(p_organization_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_estado text DEFAULT NULL::text, p_modo text DEFAULT NULL::text, p_cliente_id uuid DEFAULT NULL::uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, folio text, cliente_id uuid, cliente_nombre text, modo public.modo_transporte, origen text, destino text, subtotal numeric, moneda public.moneda, estado public.estado_cotizacion, fecha_vigencia date, created_at timestamp with time zone, descripcion_mercancia text, embarques_vinculados bigint, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH filtered AS (
    SELECT c.*
    FROM cotizaciones c
    WHERE c.deleted_at IS NULL
      AND ( p_organization_id IS NULL OR c.organization_id = p_organization_id )
      AND ( p_search IS NULL OR p_search = '' OR
            c.folio ILIKE '%' || p_search || '%' OR
            c.cliente_nombre ILIKE '%' || p_search || '%' OR
            c.descripcion_mercancia ILIKE '%' || p_search || '%' )
      AND ( p_estado IS NULL OR c.estado = p_estado::estado_cotizacion )
      AND ( p_modo IS NULL OR c.modo = p_modo::modo_transporte )
      AND ( p_cliente_id IS NULL OR c.cliente_id = p_cliente_id )
      AND ( p_fecha_desde IS NULL OR c.created_at >= p_fecha_desde )
      AND ( p_fecha_hasta IS NULL OR c.created_at <= (p_fecha_hasta + interval '1 day') )
  ),
  counted AS (
    SELECT f.*, count(*) OVER ()::bigint AS total_count
    FROM filtered f
    ORDER BY f.created_at DESC
    OFFSET p_offset LIMIT p_limit
  ),
  emb_agg AS (
    SELECT e.cotizacion_id, count(*)::bigint AS embarques_vinculados
    FROM embarques e
    WHERE e.cotizacion_id IN (SELECT id FROM counted)
    GROUP BY e.cotizacion_id
  )
  SELECT c.id, c.folio, c.cliente_id, c.cliente_nombre, c.modo, c.origen, c.destino,
         -- B-036 (v13.320.42): si el subtotal quedó en 0 (legado o guardado sin
         -- recalcular), recomponerlo desde los conceptos reales. Igual con la
         -- moneda dominante (la más cara del set).
         CASE
           WHEN COALESCE(c.subtotal, 0) > 0 THEN c.subtotal
           ELSE COALESCE((
             SELECT sum(cc.precio_venta)
             FROM cotizacion_costos cc
             WHERE cc.cotizacion_id = c.id AND cc.deleted_at IS NULL
           ), 0)
         END AS subtotal,
         CASE
           WHEN COALESCE(c.subtotal, 0) > 0 THEN c.moneda
           ELSE COALESCE((
             SELECT cc.moneda::moneda
             FROM cotizacion_costos cc
             WHERE cc.cotizacion_id = c.id AND cc.deleted_at IS NULL
             GROUP BY cc.moneda
             ORDER BY sum(cc.precio_venta) DESC NULLS LAST
             LIMIT 1
           ), c.moneda)
         END AS moneda,
         c.estado, c.fecha_vigencia, c.created_at, c.descripcion_mercancia,
         COALESCE(ea.embarques_vinculados, 0),
         c.total_count
  FROM counted c
  LEFT JOIN emb_agg ea ON ea.cotizacion_id = c.id
  ORDER BY c.created_at DESC;
$$;
CREATE FUNCTION public.crear_ajustes_factura_proveedor_rpc(p_factura_id uuid, p_ajustes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fact public.proveedor_facturas%ROWTYPE;
  v_count integer := 0;
  v_previos uuid[];
BEGIN
  SELECT * INTO v_fact
  FROM public.proveedor_facturas
  WHERE id = p_factura_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_fact.id IS NULL THEN
    RAISE EXCEPTION 'LC_FACTURA_PROVEEDOR_NO_ENCONTRADA';
  END IF;
  IF auth.uid() IS NOT NULL AND NOT public.is_org_member(v_fact.organization_id) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  -- N6: todo embarque_id del payload debe ser un embarque vigente de la
  -- MISMA organización que la factura.
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(COALESCE(p_ajustes, '[]'::jsonb)) AS a
    WHERE NULLIF(btrim(COALESCE(a->>'embarque_id', '')), '') IS NOT NULL
      AND abs(COALESCE((a->>'monto')::numeric, 0)) > 0.01
      AND NOT EXISTS (
        SELECT 1
        FROM public.embarques e
        WHERE e.id = (a->>'embarque_id')::uuid
          AND e.organization_id = v_fact.organization_id
          AND e.deleted_at IS NULL
      )
  ) THEN
    RAISE EXCEPTION 'LC_EMBARQUE_AJENO: todo ajuste debe referenciar un embarque vigente de la misma organización que la factura'
      USING ERRCODE = '42501';
  END IF;
  -- Ola 5 · RG4-3: capturar ANTES de cualquier DELETE los ids de todos los
  -- conceptos de ajuste de esta factura (vivos o ya soft-borrados).
  SELECT COALESCE(array_agg(pfc.concepto_costo_id), '{}'::uuid[])
    INTO v_previos
    FROM public.proveedor_facturas_conceptos pfc
    JOIN public.conceptos_costo cc ON cc.id = pfc.concepto_costo_id
   WHERE pfc.proveedor_factura_id = p_factura_id
     AND cc.origen = 'ajuste_factura_proveedor';
  -- Idempotencia (paso 1): soft-delete de los ajustes previos vivos.
  UPDATE public.conceptos_costo cc
     SET deleted_at = now(), deleted_by = auth.uid()
   WHERE cc.deleted_at IS NULL
     AND cc.id = ANY (v_previos);
  -- Idempotencia (paso 2): borrar los puentes de esos mismos ids.
  DELETE FROM public.proveedor_facturas_conceptos pfc
   WHERE pfc.proveedor_factura_id = p_factura_id
     AND pfc.concepto_costo_id = ANY (v_previos);
  -- Conceptos de ajuste + puentes, atómicos.
  WITH nuevos AS (
    INSERT INTO public.conceptos_costo (
      embarque_id, organization_id, proveedor_id, proveedor_nombre,
      concepto, monto, moneda, origen,
      estado_liquidacion, fecha_pago, referencia_pago
    )
    SELECT
      (a->>'embarque_id')::uuid,
      v_fact.organization_id,
      v_fact.proveedor_id,
      v_fact.proveedor_nombre,
      'Ajuste factura ' || COALESCE(v_fact.folio_proveedor, '') || ': ' || COALESCE(a->>'descripcion', ''),
      (a->>'monto')::numeric,
      v_fact.moneda,
      'ajuste_factura_proveedor',
      'Pagado'::estado_liquidacion,
      v_fact.fecha_emision,
      v_fact.folio_proveedor
    FROM jsonb_array_elements(COALESCE(p_ajustes, '[]'::jsonb)) AS a
    WHERE NULLIF(btrim(COALESCE(a->>'embarque_id', '')), '') IS NOT NULL
      AND abs(COALESCE((a->>'monto')::numeric, 0)) > 0.01
    RETURNING id, concepto, monto
  ),
  puentes AS (
    INSERT INTO public.proveedor_facturas_conceptos (
      proveedor_factura_id, organization_id, concepto_costo_id,
      descripcion, cantidad, monto
    )
    SELECT p_factura_id, v_fact.organization_id, n.id, n.concepto, 1, n.monto
    FROM nuevos n
    RETURNING id
  )
  SELECT count(*) INTO v_count FROM puentes;
  RETURN jsonb_build_object('ajustes_creados', v_count, 'folio', v_fact.folio_proveedor);
END;
$$;
CREATE TABLE public.clientes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nombre text NOT NULL,
    rfc text DEFAULT ''::text NOT NULL,
    direccion text DEFAULT ''::text NOT NULL,
    ciudad text DEFAULT ''::text NOT NULL,
    estado text DEFAULT ''::text NOT NULL,
    cp text DEFAULT ''::text NOT NULL,
    contacto text DEFAULT ''::text NOT NULL,
    email text DEFAULT ''::text NOT NULL,
    telefono text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    dias_credito integer,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    codigo_postal text,
    regimen_fiscal text,
    uso_cfdi_default text,
    forma_pago_default text,
    metodo_pago_default text,
    email_cc_default text[],
    email_destinatarios_default text[],
    limite_credito_mxn numeric(14,2),
    sin_comision boolean DEFAULT false NOT NULL,
    requiere_autorizacion_cotizacion boolean DEFAULT true NOT NULL,
    requiere_autorizacion_proforma boolean DEFAULT true NOT NULL,
    CONSTRAINT clientes_limite_credito_mxn_nonneg CHECK (((limite_credito_mxn IS NULL) OR (limite_credito_mxn >= (0)::numeric)))
);
CREATE FUNCTION public.crear_clientes(p_clientes jsonb) RETURNS SETOF public.clientes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_row jsonb;
  v_rfc text;
  v_nombre text;
  v_ids uuid[] := ARRAY[]::uuid[];
  v_id uuid;
BEGIN
  IF p_clientes IS NULL OR jsonb_typeof(p_clientes) <> 'array'
     OR jsonb_array_length(p_clientes) = 0 THEN
    RAISE EXCEPTION 'LC_CLIENTE_PAYLOAD_INVALIDO: se esperaba un arreglo de clientes'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_clientes) > 1000 THEN
    RAISE EXCEPTION 'LC_CLIENTE_LOTE_EXCEDIDO: máximo 1000 clientes por llamada'
      USING ERRCODE = '22023';
  END IF;
  IF NOT (
    public.has_any_role(v_uid, ARRAY['admin'::public.app_role, 'admin_org'::public.app_role,
                                     'operador'::public.app_role, 'contador'::public.app_role,
                                     'super_admin'::public.app_role])
  ) THEN
    RAISE EXCEPTION 'LC_CLIENTE_SIN_PERMISO: tu rol no puede dar de alta clientes'
      USING ERRCODE = '42501';
  END IF;
  v_org := public.current_user_org_id();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_CLIENTE_SIN_ORG: no hay organización activa'
      USING ERRCODE = '22023';
  END IF;
  FOR v_row IN SELECT * FROM jsonb_array_elements(p_clientes) LOOP
    v_nombre := btrim(COALESCE(v_row->>'nombre', ''));
    IF v_nombre = '' THEN
      RAISE EXCEPTION 'LC_CLIENTE_SIN_NOMBRE: la razón social es obligatoria'
        USING ERRCODE = '22023';
    END IF;
    v_rfc := upper(btrim(COALESCE(v_row->>'rfc', '')));
    -- Cliente facturable = trae RFC propio. Entonces el CFDI necesita datos
    -- fiscales completos desde el alta, no al momento de timbrar.
    IF v_rfc <> '' AND v_rfc NOT IN ('XEXX010101000', 'XAXX010101000') THEN
      IF btrim(COALESCE(v_row->>'regimen_fiscal', '')) = ''
         OR btrim(COALESCE(v_row->>'uso_cfdi_default', '')) = ''
         OR btrim(COALESCE(v_row->>'cp', '')) = ''
         OR btrim(COALESCE(v_row->>'direccion', '')) = '' THEN
        RAISE EXCEPTION 'LC_CLIENTE_FISCAL_INCOMPLETO: % lleva RFC, así que necesita régimen fiscal, uso de CFDI, código postal y dirección', v_nombre
          USING ERRCODE = '22023';
      END IF;
    END IF;
    INSERT INTO public.clientes (
      organization_id, nombre, rfc, direccion, ciudad, estado, cp, contacto,
      telefono, email, regimen_fiscal, uso_cfdi_default, dias_credito,
      limite_credito_mxn, sin_comision,
      requiere_autorizacion_cotizacion, requiere_autorizacion_proforma
    ) VALUES (
      v_org,
      v_nombre,
      NULLIF(v_rfc, ''),
      NULLIF(btrim(COALESCE(v_row->>'direccion', '')), ''),
      NULLIF(btrim(COALESCE(v_row->>'ciudad', '')), ''),
      NULLIF(btrim(COALESCE(v_row->>'estado', '')), ''),
      NULLIF(btrim(COALESCE(v_row->>'cp', '')), ''),
      NULLIF(btrim(COALESCE(v_row->>'contacto', '')), ''),
      NULLIF(btrim(COALESCE(v_row->>'telefono', '')), ''),
      NULLIF(lower(btrim(COALESCE(v_row->>'email', ''))), ''),
      NULLIF(btrim(COALESCE(v_row->>'regimen_fiscal', '')), ''),
      NULLIF(btrim(COALESCE(v_row->>'uso_cfdi_default', '')), ''),
      COALESCE((v_row->>'dias_credito')::int, 0),
      NULLIF(v_row->>'limite_credito_mxn', '')::numeric,
      COALESCE((v_row->>'sin_comision')::boolean, false),
      COALESCE((v_row->>'requiere_autorizacion_cotizacion')::boolean, false),
      COALESCE((v_row->>'requiere_autorizacion_proforma')::boolean, false)
    ) RETURNING id INTO v_id;
    v_ids := array_append(v_ids, v_id);
  END LOOP;
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, accion, modulo,
    entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_org, v_uid, (SELECT email FROM auth.users WHERE id = v_uid),
    'cliente.alta', 'clientes', v_ids[1],
    (SELECT nombre FROM public.clientes WHERE id = v_ids[1]),
    jsonb_build_object('cantidad', array_length(v_ids, 1))
  );
  RETURN QUERY SELECT * FROM public.clientes WHERE id = ANY(v_ids);
END;
$$;
CREATE FUNCTION public.crear_embarque_borrador_core(p_cotizacion_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_cot           public.cotizaciones%ROWTYPE;
  v_caller_org    uuid := current_user_org_id();
  v_is_super      boolean := has_role(auth.uid(), 'super_admin'::app_role);
  v_can_write     boolean;
  v_embarque_id   uuid;
  v_orphan_id     uuid;
  v_num           integer;
  v_peso_each     numeric;
  v_vol_each      numeric;
  v_piezas_base   integer;
  v_piezas_rest   integer;
  v_piezas_este   integer;
  v_first_hijo_id uuid;
  v_user_email    text;
  i               integer;
  v_target_ids    uuid[];
  v_cid           uuid;
  v_origen_code   text;
  v_destino_code  text;
  v_puerto_o      text;
  v_puerto_d      text;
  v_aero_o        text;
  v_aero_d        text;
  v_ciudad_o      text;
  v_ciudad_d      text;
  v_tipo_cont_code text;
  v_agente_id     uuid;
  v_naviera_id    uuid;
  v_agente_nombre text;
  v_naviera_nombre text;
BEGIN
  SELECT * INTO v_cot FROM public.cotizaciones WHERE id = p_cotizacion_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_COT_NO_ENCONTRADA: cotización % no existe', p_cotizacion_id USING ERRCODE = 'P0002';
  END IF;
  IF v_cot.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'LC_COT_ELIMINADA: la cotización % está eliminada', p_cotizacion_id USING ERRCODE = 'P0001';
  END IF;
  IF NOT v_is_super AND v_cot.organization_id IS DISTINCT FROM v_caller_org THEN
    RAISE EXCEPTION 'LC_NO_AUTORIZADO: la cotización pertenece a otra organización' USING ERRCODE = '42501';
  END IF;
  v_can_write := v_is_super
                 OR has_role(auth.uid(), 'admin'::app_role)
                 OR has_role(auth.uid(), 'operador'::app_role);
  IF NOT v_can_write THEN
    RAISE EXCEPTION 'LC_NO_AUTORIZADO: solo admin u operador pueden crear el borrador' USING ERRCODE = '42501';
  END IF;
  IF v_cot.estado NOT IN ('Aceptada'::estado_cotizacion, 'En operación'::estado_cotizacion) THEN
    RAISE EXCEPTION 'LC_COT_ESTADO_INVALIDO: la cotización debe estar Aceptada o En operación (actual: %)', v_cot.estado USING ERRCODE = 'P0001';
  END IF;
  IF v_cot.cliente_id IS NULL OR v_cot.es_prospecto THEN
    RAISE EXCEPTION 'LC_COT_SIN_CLIENTE: convierte el prospecto a cliente antes de crear el borrador' USING ERRCODE = 'P0001';
  END IF;
  IF v_cot.embarque_id IS NOT NULL THEN
    SELECT id INTO v_orphan_id FROM public.embarques WHERE id = v_cot.embarque_id AND deleted_at IS NULL;
    IF FOUND THEN
      RETURN v_orphan_id;
    END IF;
    UPDATE public.cotizaciones SET embarque_id = NULL WHERE id = v_cot.id;
  END IF;
  SELECT id INTO v_orphan_id
  FROM public.embarques
  WHERE cotizacion_id = v_cot.id AND deleted_at IS NULL
  ORDER BY created_at ASC
  LIMIT 1;
  IF v_orphan_id IS NOT NULL THEN
    RETURN v_orphan_id;
  END IF;
  v_origen_code := COALESCE(
    NULLIF(substring(v_cot.origen  FROM '\(([^)]+)\)'), ''),
    NULLIF(trim(v_cot.origen),  ''),
    NULL
  );
  v_destino_code := COALESCE(
    NULLIF(substring(v_cot.destino FROM '\(([^)]+)\)'), ''),
    NULLIF(trim(v_cot.destino), ''),
    NULL
  );
  IF v_origen_code IS NOT NULL THEN
    SELECT p.name INTO v_puerto_o FROM public.puertos p WHERE p.code = v_origen_code LIMIT 1;
  END IF;
  IF v_destino_code IS NOT NULL THEN
    SELECT p.name INTO v_puerto_d FROM public.puertos p WHERE p.code = v_destino_code LIMIT 1;
  END IF;
  IF v_cot.modo = 'Aéreo'::modo_transporte THEN
    v_aero_o := COALESCE(v_puerto_o, v_origen_code);
    v_aero_d := COALESCE(v_puerto_d, v_destino_code);
    v_puerto_o := NULL; v_puerto_d := NULL;
  ELSIF v_cot.modo = 'Terrestre'::modo_transporte THEN
    v_ciudad_o := COALESCE(v_puerto_o, v_origen_code);
    v_ciudad_d := COALESCE(v_puerto_d, v_destino_code);
    v_puerto_o := NULL; v_puerto_d := NULL;
  ELSE
    v_puerto_o := COALESCE(v_puerto_o, v_origen_code);
    v_puerto_d := COALESCE(v_puerto_d, v_destino_code);
  END IF;
  -- v13.320.4: usar columna real cotizaciones.tipo_contenedor (text).
  -- La versión viva anterior referenciaba `v_cot.tipo_contenedor_id`, columna que
  -- nunca existió en la tabla y hacía fallar toda la revalidación de tarifa.
  v_tipo_cont_code := v_cot.tipo_contenedor;
  IF v_tipo_cont_code IS NOT NULL AND v_tipo_cont_code ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    SELECT code INTO v_tipo_cont_code FROM public.tipos_contenedor WHERE id = v_cot.tipo_contenedor::uuid;
    v_tipo_cont_code := COALESCE(v_tipo_cont_code, v_cot.tipo_contenedor);
  END IF;
  v_agente_id  := v_cot.agente_id;
  v_naviera_id := v_cot.naviera_id;
  IF (v_agente_id IS NULL OR v_naviera_id IS NULL) AND v_cot.tarifa_id IS NOT NULL THEN
    SELECT COALESCE(v_agente_id, t.agente_id), COALESCE(v_naviera_id, t.naviera_id)
      INTO v_agente_id, v_naviera_id
    FROM public.costeo_tarifas t WHERE t.id = v_cot.tarifa_id;
  END IF;
  IF v_agente_id  IS NOT NULL THEN SELECT nombre INTO v_agente_nombre  FROM public.costeo_agentes WHERE id = v_agente_id; END IF;
  IF v_naviera_id IS NOT NULL THEN SELECT name   INTO v_naviera_nombre FROM public.navieras       WHERE id = v_naviera_id; END IF;
  INSERT INTO public.embarques (
    cotizacion_id, expediente, cliente_id, cliente_nombre,
    estado, modo, tipo, incoterm, descripcion_mercancia,
    peso_kg, volumen_m3, piezas, operador, tipo_carga, tipo_contenedor,
    organization_id,
    puerto_origen, puerto_destino,
    aeropuerto_origen, aeropuerto_destino,
    ciudad_origen, ciudad_destino,
    tarifa_id, tarifa_id_original, tarifa_id_aplicada,
    carta_garantia, dias_libres_destino,
    seguro, valor_seguro_usd,
    agente_id, naviera_id, agente, naviera
  )
  VALUES (
    v_cot.id, NULL, v_cot.cliente_id, v_cot.cliente_nombre,
    'Borrador'::estado_embarque, v_cot.modo, v_cot.tipo, v_cot.incoterm, v_cot.descripcion_mercancia,
    COALESCE(v_cot.peso_kg, 0), COALESCE(v_cot.volumen_m3, 0), COALESCE(v_cot.piezas, 0),
    v_cot.operador, v_cot.tipo_carga, v_tipo_cont_code,
    v_cot.organization_id,
    v_puerto_o, v_puerto_d,
    v_aero_o, v_aero_d,
    v_ciudad_o, v_ciudad_d,
    v_cot.tarifa_id, v_cot.tarifa_id, v_cot.tarifa_id,
    v_cot.carta_garantia, v_cot.dias_libres_destino,
    v_cot.seguro, v_cot.valor_seguro_usd,
    v_agente_id, v_naviera_id, v_agente_nombre, v_naviera_nombre
  )
  RETURNING id INTO v_embarque_id;
  v_num := GREATEST(1, COALESCE(v_cot.num_contenedores, 1));
  v_peso_each := COALESCE(v_cot.peso_kg, 0) / v_num;
  v_vol_each := COALESCE(v_cot.volumen_m3, 0) / v_num;
  v_piezas_base := COALESCE(v_cot.piezas, 0) / v_num;
  v_piezas_rest := COALESCE(v_cot.piezas, 0);
  v_target_ids := ARRAY[]::uuid[];
  FOR i IN 1..v_num LOOP
    IF i = v_num THEN v_piezas_este := v_piezas_rest;
    ELSE v_piezas_este := v_piezas_base; END IF;
    v_piezas_rest := v_piezas_rest - v_piezas_este;
    INSERT INTO public.embarque_contenedores (
      embarque_id, numero_contenedor, tipo_contenedor, bl_house,
      peso_kg, volumen_m3, piezas, orden
    )
    VALUES (
      v_embarque_id, '', COALESCE(v_tipo_cont_code, ''), '',
      v_peso_each, v_vol_each, v_piezas_este, i
    )
    RETURNING id INTO v_cid;
    v_target_ids := array_append(v_target_ids, v_cid);
    IF i = 1 THEN v_first_hijo_id := v_cid; END IF;
  END LOOP;
  PERFORM public._crear_embarque_replicar_conceptos(
    v_cot.id, v_embarque_id, v_cot.organization_id, v_target_ids, v_cot.conceptos_venta
  );
  UPDATE public.cotizaciones
  SET embarque_id = v_embarque_id, estado = 'En operación'::estado_cotizacion, updated_at = now()
  WHERE id = v_cot.id;
  SELECT email INTO v_user_email FROM auth.users WHERE id = auth.uid();
  INSERT INTO public.bitacora_actividad (organization_id, usuario_id, usuario_email, modulo, accion, entidad_id, entidad_nombre, detalles)
  VALUES (v_cot.organization_id, auth.uid(), COALESCE(v_user_email, ''),
          'Cotizaciones', 'Borrador de embarque creado', v_cot.id, v_cot.folio,
          jsonb_build_object('embarque_id', v_embarque_id, 'expediente', NULL));
  INSERT INTO public.notificaciones_internas (organization_id, usuario_id, tipo, titulo, mensaje, enlace)
  SELECT v_cot.organization_id, om.user_id, 'cotizacion_borrador_embarque',
         'Borrador de embarque creado',
         'Se generó un borrador de embarque desde la cotización ' || v_cot.folio,
         '/embarques/' || v_embarque_id::text
  FROM public.organization_members om
  WHERE om.organization_id = v_cot.organization_id
    AND om.role IN ('admin'::app_role, 'operador'::app_role)
    AND om.user_id <> auth.uid();
  RETURN v_embarque_id;
END;
$_$;
CREATE FUNCTION public.crear_embarque_borrador_desde_cotizacion(p_cotizacion_id uuid, p_decision text DEFAULT 'sin_cambios'::text, p_tarifa_id_aplicada uuid DEFAULT NULL::uuid, p_delta_jsonb jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_embarque_id UUID; v_cot public.cotizaciones%ROWTYPE;
BEGIN
  IF p_decision NOT IN ('sin_cambios','mantenida_por_operaciones','refrescada','sustituida','reaprobada_ventas') THEN
    RAISE EXCEPTION 'Decisión de tarifa inválida: %', p_decision USING ERRCODE='P0001';
  END IF;
  PERFORM public.enforce_cotizacion_vigente(p_cotizacion_id);
  IF p_decision='sin_cambios' THEN
    PERFORM public.enforce_revalidacion_sin_cambios(p_cotizacion_id);
  END IF;
  v_embarque_id := public.crear_embarque_borrador_core(p_cotizacion_id);
  SELECT * INTO v_cot FROM public.cotizaciones WHERE id=p_cotizacion_id;
  UPDATE public.embarques
     SET tarifa_id_original=v_cot.tarifa_id,
         tarifa_id_aplicada=COALESCE(p_tarifa_id_aplicada, v_cot.tarifa_id),
         tarifa_delta_jsonb=p_delta_jsonb,
         tarifa_decision=p_decision,
         tarifa_revalidada_en=now(),
         tarifa_revalidada_por=auth.uid()
   WHERE id=v_embarque_id;
  IF p_decision <> 'sin_cambios' AND v_cot.estado_revalidacion='pendiente_reaprobacion' THEN
    UPDATE public.cotizaciones
       SET estado_revalidacion='reaprobada', revalidacion_resuelta_en=now(), updated_at=now()
     WHERE id=p_cotizacion_id;
  END IF;
  INSERT INTO public.bitacora_actividad (organization_id, usuario_id, usuario_email, modulo, accion, entidad_id, entidad_nombre, detalles)
    SELECT v_cot.organization_id, auth.uid(),
      COALESCE((SELECT email FROM auth.users WHERE id=auth.uid()),''),
      'Embarques','tarifa_decision_aplicada', v_embarque_id, v_cot.folio,
      jsonb_build_object('decision',p_decision,
        'tarifa_id_original',v_cot.tarifa_id,
        'tarifa_id_aplicada',COALESCE(p_tarifa_id_aplicada, v_cot.tarifa_id),
        'delta',p_delta_jsonb);
  RETURN v_embarque_id;
END;
$$;
CREATE FUNCTION public.crear_embarque_completo(p_embarque jsonb, p_conceptos_venta jsonb DEFAULT '[]'::jsonb, p_conceptos_costo jsonb DEFAULT '[]'::jsonb, p_documentos jsonb DEFAULT '[]'::jsonb, p_request_id uuid DEFAULT NULL::uuid, p_contenedores jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  nuevo_id uuid := gen_random_uuid();
  v_org_id uuid; v_resp jsonb;
  cv jsonb; cc jsonb; doc jsonb; ct jsonb;
BEGIN
  PERFORM public._assert_medidas_embarque(p_embarque);
  v_org_id := current_user_org_id();
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'No organization context for caller'; END IF;
  PERFORM public._assert_writer(v_org_id);
  PERFORM public._assert_relaciones_embarque(
    v_org_id,
    NULLIF(p_embarque->>'cliente_id','')::uuid,
    NULLIF(p_embarque->>'cotizacion_id','')::uuid,
    p_conceptos_costo
  );
  v_resp := public.idempotency_claim(p_request_id, 'crear_embarque_completo');
  IF v_resp IS NOT NULL THEN RETURN v_resp; END IF;
  INSERT INTO embarques (
    id, expediente, cliente_id, cliente_nombre, modo, tipo,
    shipper, consignatario, incoterm, descripcion_mercancia,
    peso_kg, volumen_m3, piezas,
    puerto_origen, puerto_destino, naviera, agente,
    bl_master, bl_house, tipo_servicio, contenedor, tipo_contenedor,
    aeropuerto_origen, aeropuerto_destino, aerolinea,
    mawb, hawb, ciudad_origen, ciudad_destino,
    transportista, carta_porte, etd, eta,
    tipo_cambio_usd, tipo_cambio_eur,
    tipo_carga, msds_archivo, operador, organization_id, cotizacion_id
  ) VALUES (
    nuevo_id, p_embarque->>'expediente', (p_embarque->>'cliente_id')::uuid,
    COALESCE(p_embarque->>'cliente_nombre',''),
    (p_embarque->>'modo')::modo_transporte, (p_embarque->>'tipo')::tipo_operacion,
    COALESCE(p_embarque->>'shipper',''), COALESCE(p_embarque->>'consignatario',''),
    COALESCE((p_embarque->>'incoterm')::incoterm,'FOB'),
    COALESCE(p_embarque->>'descripcion_mercancia',''),
    COALESCE((p_embarque->>'peso_kg')::numeric,0),
    COALESCE((p_embarque->>'volumen_m3')::numeric,0),
    COALESCE((p_embarque->>'piezas')::int,0),
    p_embarque->>'puerto_origen', p_embarque->>'puerto_destino',
    p_embarque->>'naviera', p_embarque->>'agente',
    p_embarque->>'bl_master', p_embarque->>'bl_house',
    CASE WHEN p_embarque->>'tipo_servicio' IS NOT NULL THEN (p_embarque->>'tipo_servicio')::tipo_servicio_maritimo END,
    p_embarque->>'contenedor', p_embarque->>'tipo_contenedor',
    p_embarque->>'aeropuerto_origen', p_embarque->>'aeropuerto_destino',
    p_embarque->>'aerolinea', p_embarque->>'mawb', p_embarque->>'hawb',
    p_embarque->>'ciudad_origen', p_embarque->>'ciudad_destino',
    p_embarque->>'transportista', p_embarque->>'carta_porte',
    CASE WHEN p_embarque->>'etd' IS NOT NULL THEN (p_embarque->>'etd')::date END,
    CASE WHEN p_embarque->>'eta' IS NOT NULL THEN (p_embarque->>'eta')::date END,
    NULLIF(NULLIF(p_embarque->>'tipo_cambio_usd','')::numeric, 0),
    NULLIF(NULLIF(p_embarque->>'tipo_cambio_eur','')::numeric, 0),
    COALESCE(p_embarque->>'tipo_carga','Carga General'),
    p_embarque->>'msds_archivo', COALESCE(p_embarque->>'operador',''),
    v_org_id,
    CASE WHEN p_embarque->>'cotizacion_id' IS NOT NULL AND p_embarque->>'cotizacion_id' <> '' THEN (p_embarque->>'cotizacion_id')::uuid END
  );
  FOR cv IN SELECT * FROM jsonb_array_elements(p_conceptos_venta) LOOP
    INSERT INTO conceptos_venta (embarque_id, descripcion, cantidad, precio_unitario, moneda, total, organization_id)
    VALUES (nuevo_id, cv->>'descripcion', (cv->>'cantidad')::numeric, (cv->>'precio_unitario')::numeric,
            (cv->>'moneda')::moneda, (cv->>'total')::numeric, v_org_id);
  END LOOP;
  FOR cc IN SELECT * FROM jsonb_array_elements(p_conceptos_costo) LOOP
    INSERT INTO conceptos_costo (embarque_id, concepto, proveedor_nombre, proveedor_id, moneda, monto, organization_id)
    VALUES (nuevo_id, cc->>'concepto', COALESCE(cc->>'proveedor_nombre',''),
      CASE WHEN cc->>'proveedor_id' IS NOT NULL AND cc->>'proveedor_id' <> '' THEN (cc->>'proveedor_id')::uuid END,
      (cc->>'moneda')::moneda, (cc->>'monto')::numeric, v_org_id);
  END LOOP;
  FOR doc IN SELECT * FROM jsonb_array_elements(p_documentos) LOOP
    INSERT INTO documentos_embarque (embarque_id, nombre, archivo, estado, organization_id)
    VALUES (nuevo_id, doc->>'nombre', NULLIF(doc->>'archivo',''),
      CASE WHEN NULLIF(doc->>'archivo','') IS NOT NULL THEN 'Recibido'::estado_documento ELSE 'Pendiente'::estado_documento END,
      v_org_id);
  END LOOP;
  FOR ct IN SELECT * FROM jsonb_array_elements(COALESCE(p_contenedores, '[]'::jsonb)) LOOP
    INSERT INTO embarque_contenedores (
      embarque_id, numero_contenedor, tipo_contenedor, bl_house,
      peso_kg, volumen_m3, piezas, orden, organization_id
    ) VALUES (
      nuevo_id,
      COALESCE(ct->>'numero_contenedor',''),
      COALESCE(ct->>'tipo_contenedor',''),
      NULLIF(ct->>'bl_house',''),
      COALESCE(NULLIF(ct->>'peso_kg','')::numeric, 0),
      COALESCE(NULLIF(ct->>'volumen_m3','')::numeric, 0),
      COALESCE(NULLIF(ct->>'piezas','')::int, 0),
      COALESCE(NULLIF(ct->>'orden','')::int, 1),
      v_org_id
    );
  END LOOP;
  INSERT INTO notas_embarque (embarque_id, contenido, tipo, organization_id)
  VALUES (nuevo_id, 'Embarque creado', 'sistema', v_org_id);
  v_resp := jsonb_build_object('id', nuevo_id);
  PERFORM public.idempotency_store(p_request_id, v_resp);
  RETURN v_resp;
END;
$$;
CREATE FUNCTION public.crear_garantia_contenedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_naviera_id uuid;
  v_naviera_nombre text;
  v_org uuid;
  v_tarifa_id uuid;
  v_cond record;
  v_carta_vigente boolean := false;
  v_monto numeric(12,2) := 0;
  v_estado text := 'pendiente';
BEGIN
  SELECT e.naviera, e.organization_id, e.tarifa_id_aplicada
    INTO v_naviera_nombre, v_org, v_tarifa_id
  FROM public.embarques e WHERE e.id = NEW.embarque_id;
  -- 1) Preferir naviera de la tarifa aplicada
  IF v_tarifa_id IS NOT NULL THEN
    SELECT t.naviera_id INTO v_naviera_id
    FROM public.costeo_tarifas t
    WHERE t.id = v_tarifa_id;
  END IF;
  -- 2) Fallback: match por nombre en embarques.naviera
  IF v_naviera_id IS NULL AND v_naviera_nombre IS NOT NULL AND v_naviera_nombre <> '' THEN
    SELECT n.id INTO v_naviera_id FROM public.navieras n
    WHERE lower(n.name) = lower(v_naviera_nombre) LIMIT 1;
  END IF;
  IF v_naviera_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT * INTO v_cond FROM public.costeo_navieras_condiciones
  WHERE organization_id = v_org AND naviera_id = v_naviera_id LIMIT 1;
  IF FOUND THEN
    v_carta_vigente := v_cond.tiene_carta_garantia
      AND (v_cond.carta_garantia_vigente_hasta IS NULL OR v_cond.carta_garantia_vigente_hasta >= CURRENT_DATE);
    IF v_carta_vigente THEN
      v_monto := 0;
      v_estado := 'liberado';
    ELSE
      v_monto := COALESCE(v_cond.deposito_contenedor_usd, 0);
      v_estado := 'pendiente';
    END IF;
  END IF;
  INSERT INTO public.embarque_garantias_contenedor (
    organization_id, embarque_id, embarque_contenedor_id, naviera_id,
    monto_deposito_usd, tiene_carta_garantia, estado
  ) VALUES (
    v_org, NEW.embarque_id, NEW.id, v_naviera_id,
    v_monto, v_carta_vigente, v_estado
  )
  ON CONFLICT (embarque_contenedor_id) DO NOTHING;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.crear_proforma_atomica(p_organization_id uuid, p_embarque_id uuid, p_cliente_id uuid, p_cliente_nombre text, p_expediente text, p_bl_master text, p_concepto_ids uuid[], p_subtotal_usd numeric, p_iva_usd numeric, p_total_usd numeric, p_subtotal_mxn numeric, p_iva_mxn numeric, p_total_mxn numeric, p_notas text, p_operador text, p_dias_credito integer, p_tasa_iva numeric, p_iva_overrides jsonb DEFAULT '{}'::jsonb) RETURNS public.proformas
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_numero text;
  v_proforma public.proformas;
  v_override record;
  v_org uuid;
  v_sub_usd numeric := 0;
  v_iva_usd numeric := 0;
  v_sub_mxn numeric := 0;
  v_iva_mxn numeric := 0;
  v_tc numeric;
  v_ocupados int;
  v_actualizados int;
  v_ajenos int;
  v_no_soportados int;
BEGIN
  IF p_concepto_ids IS NULL OR array_length(p_concepto_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Debe seleccionar al menos un concepto';
  END IF;
  IF has_role(auth.uid(), 'super_admin'::app_role) THEN
    v_org := p_organization_id;
  ELSE
    v_org := current_user_org_id();
  END IF;
  PERFORM public._assert_writer(v_org);
  -- Ola E1 · C5: el embarque debe existir en la organización y coincidir con
  -- el cliente recibido; antes se confiaba en los argumentos del cliente.
  IF NOT EXISTS (
    SELECT 1 FROM public.embarques e
     WHERE e.id = p_embarque_id
       AND e.organization_id = v_org
       AND e.deleted_at IS NULL
       AND (p_cliente_id IS NULL OR e.cliente_id = p_cliente_id)
  ) THEN
    RAISE EXCEPTION 'LC_PROFORMA_EMBARQUE_INVALIDO: el embarque no existe en tu organización o no corresponde al cliente indicado'
      USING ERRCODE = 'P0001';
  END IF;
  -- Bloquea los conceptos y valida que estén libres antes de crear la proforma.
  PERFORM 1 FROM public.conceptos_venta
   WHERE id = ANY(p_concepto_ids) AND organization_id = v_org
   FOR UPDATE;
  -- Ola E1 · C5: ningún concepto puede venir de otro embarque ni estar borrado.
  SELECT COUNT(*) INTO v_ajenos
  FROM unnest(p_concepto_ids) AS s(id)
  WHERE NOT EXISTS (
    SELECT 1 FROM public.conceptos_venta cv
     WHERE cv.id = s.id
       AND cv.organization_id = v_org
       AND cv.embarque_id = p_embarque_id
       AND cv.deleted_at IS NULL
  );
  IF v_ajenos > 0 THEN
    RAISE EXCEPTION 'LC_CONCEPTOS_AJENOS: % concepto(s) no pertenecen a este embarque o fueron eliminados; recarga la pantalla', v_ajenos
      USING ERRCODE = 'P0001';
  END IF;
  -- Ola 2 · A: EUR (o cualquier moneda fuera de MXN/USD) no es soportado en
  -- venta; antes se proformaba y facturaba en $0 en silencio.
  SELECT COUNT(*) INTO v_no_soportados
  FROM public.conceptos_venta
  WHERE id = ANY(p_concepto_ids)
    AND organization_id = v_org
    AND moneda NOT IN ('MXN', 'USD');
  IF v_no_soportados > 0 THEN
    RAISE EXCEPTION 'LC_MONEDA_VENTA_NO_SOPORTADA: % concepto(s) de venta tienen una moneda no soportada; sólo se puede facturar en MXN o USD', v_no_soportados
      USING ERRCODE = 'P0001';
  END IF;
  SELECT COUNT(*) INTO v_ocupados
  FROM public.conceptos_venta
  WHERE id = ANY(p_concepto_ids)
    AND organization_id = v_org
    AND (proforma_id IS NOT NULL OR COALESCE(estado_facturacion, 'pendiente') <> 'pendiente');
  IF v_ocupados > 0 THEN
    RAISE EXCEPTION 'LC_CONCEPTOS_YA_ASIGNADOS: % concepto(s) ya están en otra proforma o facturados; recarga la pantalla', v_ocupados
      USING ERRCODE = 'P0001';
  END IF;
  IF p_iva_overrides IS NOT NULL AND p_iva_overrides <> '{}'::jsonb THEN
    FOR v_override IN
      SELECT key AS concepto_id, (value)::text::boolean AS aplica
      FROM jsonb_each(p_iva_overrides)
    LOOP
      UPDATE public.conceptos_venta
      SET aplica_iva = v_override.aplica
      WHERE id = v_override.concepto_id::uuid
        AND organization_id = v_org
        AND embarque_id = p_embarque_id;
    END LOOP;
  END IF;
  SELECT
    COALESCE(SUM(CASE WHEN moneda='USD' THEN cantidad*precio_unitario ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN moneda='USD' AND aplica_iva
                      THEN cantidad*precio_unitario*COALESCE(tasa_iva_aplicada, p_tasa_iva)
                      ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN moneda='MXN' THEN cantidad*precio_unitario ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN moneda='MXN' AND aplica_iva
                      THEN cantidad*precio_unitario*COALESCE(tasa_iva_aplicada, p_tasa_iva)
                      ELSE 0 END), 0)
  INTO v_sub_usd, v_iva_usd, v_sub_mxn, v_iva_mxn
  FROM public.conceptos_venta
  WHERE id = ANY(p_concepto_ids) AND organization_id = v_org;
  IF v_sub_usd > 0 THEN
    SELECT tipo_cambio_usd INTO v_tc
    FROM public.embarques
    WHERE id = p_embarque_id AND organization_id = v_org;
    IF v_tc IS NULL OR v_tc <= 0 THEN
      RAISE EXCEPTION 'LC_PROFORMA_TC_REQUERIDO: el embarque no tiene tipo de cambio USD para convertir los conceptos en dólares'
        USING ERRCODE='P0001';
    END IF;
    v_sub_mxn := v_sub_mxn + round(v_sub_usd * v_tc, 2);
    v_iva_mxn := v_iva_mxn + round(v_iva_usd * v_tc, 2);
  END IF;
  IF ABS(COALESCE(p_iva_usd,0) - v_iva_usd) > 0.01
     OR ABS(COALESCE(p_iva_mxn,0) - v_iva_mxn) > 0.01 THEN
    RAISE NOTICE 'crear_proforma_atomica: desfase cliente vs server';
  END IF;
  v_numero := public.generar_numero_proforma(v_org);
  INSERT INTO public.proformas (
    numero, embarque_id, cliente_id, cliente_nombre, expediente, bl_master,
    subtotal_usd, iva_usd, total_usd, subtotal_mxn, iva_mxn, total_mxn,
    notas, operador, dias_credito, organization_id, tasa_iva_aplicada
  ) VALUES (
    v_numero, p_embarque_id, p_cliente_id, p_cliente_nombre, p_expediente, p_bl_master,
    v_sub_usd, v_iva_usd, v_sub_usd + v_iva_usd,
    v_sub_mxn, v_iva_mxn, v_sub_mxn + v_iva_mxn,
    p_notas, p_operador, p_dias_credito, v_org, p_tasa_iva
  )
  RETURNING * INTO v_proforma;
  UPDATE public.conceptos_venta
  SET estado_facturacion = 'en_proforma', proforma_id = v_proforma.id
  WHERE id = ANY(p_concepto_ids)
    AND organization_id = v_org
    AND embarque_id = p_embarque_id
    AND proforma_id IS NULL
    AND COALESCE(estado_facturacion, 'pendiente') = 'pendiente';
  GET DIAGNOSTICS v_actualizados = ROW_COUNT;
  IF v_actualizados <> array_length(p_concepto_ids, 1) THEN
    RAISE EXCEPTION 'LC_CONCEPTOS_YA_ASIGNADOS: los conceptos cambiaron de estado durante la operación; recarga la pantalla'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN v_proforma;
END;
$_$;
CREATE FUNCTION public.credito_en_uso_mxn(p_cliente_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric := 0;
  v_saldo numeric;
  f record;
BEGIN
  FOR f IN
    SELECT id, COALESCE(total, 0) AS total, moneda::text AS moneda, tipo_cambio AS tc
      FROM public.facturas
     WHERE cliente_id = p_cliente_id
       AND deleted_at IS NULL
       AND estado::text IN ('Emitida', 'Vencida', 'Parcialmente pagada')
  LOOP
    SELECT GREATEST(
             0,
             f.total
               - COALESCE((SELECT SUM(p.monto_aplicado_factura)
                             FROM public.pagos_factura p
                            WHERE p.factura_id = f.id AND p.deleted_at IS NULL), 0)
               - public.nc_aplicadas_en_moneda_factura(f.id)
           )
      INTO v_saldo;
    IF f.moneda = 'MXN' THEN
      v_total := v_total + v_saldo;
    ELSIF v_saldo > 0 THEN
      IF f.tc IS NULL OR f.tc < 5 OR f.tc > 40 THEN
        RAISE EXCEPTION 'LC_CREDITO_TC_INVALIDO: la factura % está en % con un tipo de cambio no válido (%); no se puede calcular el crédito en uso.', f.id, f.moneda, COALESCE(f.tc, 0)
          USING ERRCODE = '22023';
      END IF;
      v_total := v_total + (v_saldo * f.tc);
    END IF;
  END LOOP;
  RETURN ROUND(COALESCE(v_total, 0), 2);
END;
$$;
CREATE FUNCTION public.crm_autorizar_margen(_oportunidad_id uuid, _margen_pct numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.crm_oportunidades
  WHERE id = _oportunidad_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_OPORTUNIDAD_INEXISTENTE';
  END IF;
  IF NOT (
    public.has_role(auth.uid(), 'super_admin')
    OR EXISTS (
      SELECT 1 FROM public.organization_members om
      WHERE om.user_id = auth.uid()
        AND om.organization_id = v_org
        AND om.role IN ('admin_org', 'gerente_comercial')
    )
  ) THEN
    RAISE EXCEPTION 'LC_SIN_PERMISO_AUTORIZAR_MARGEN';
  END IF;
  UPDATE public.crm_oportunidades
  SET margen_pct = _margen_pct,
      margen_autorizado_por = auth.uid(),
      margen_autorizado_at = now(),
      updated_at = now()
  WHERE id = _oportunidad_id;
END;
$$;
CREATE FUNCTION public.crm_avance_actividad(p_desde date, p_hasta date) RETURNS TABLE(vendedor_email text, contactos integer, contactos_efectivos integer, reuniones_calificadas integer, cotizaciones integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH act AS (
    SELECT COALESCE(a.responsable_email, 'sin asignar') AS vendedor_email,
           COUNT(*)::int AS contactos,
           COUNT(*) FILTER (WHERE a.contacto_efectivo)::int AS contactos_efectivos,
           COUNT(*) FILTER (WHERE a.reunion_calificada)::int AS reuniones_calificadas
      FROM public.crm_actividades a
     WHERE a.deleted_at IS NULL
       AND COALESCE(a.fecha_completada, a.fecha_programada, a.created_at)::date BETWEEN p_desde AND p_hasta
     GROUP BY 1
  ),
  cots AS (
    SELECT COALESCE(o.vendedor_email, 'sin asignar') AS vendedor_email, COUNT(*)::int AS cotizaciones
      FROM public.crm_oportunidades o
     WHERE o.deleted_at IS NULL
       AND o.created_at::date BETWEEN p_desde AND p_hasta
     GROUP BY 1
  )
  SELECT COALESCE(a.vendedor_email, c.vendedor_email) AS vendedor_email,
         COALESCE(a.contactos, 0), COALESCE(a.contactos_efectivos, 0),
         COALESCE(a.reuniones_calificadas, 0), COALESCE(c.cotizaciones, 0)
    FROM act a
    FULL OUTER JOIN cots c ON c.vendedor_email = a.vendedor_email
   ORDER BY 2 DESC;
$$;
CREATE FUNCTION public.crm_backfill_cotizaciones_sin_oportunidad() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  v_ok integer := 0;
  v_fail integer := 0;
  v_errores jsonb := '[]'::jsonb;
BEGIN
  FOR r IN
    SELECT id, prospecto_empresa, prospecto_contacto, prospecto_email, prospecto_telefono, cliente_nombre
    FROM public.cotizaciones
    WHERE es_prospecto = true AND oportunidad_id IS NULL AND deleted_at IS NULL
    ORDER BY created_at ASC
  LOOP
    BEGIN
      PERFORM public._crm_vincular_cotizacion_core(
        r.id,
        jsonb_build_object(
          'empresa', COALESCE(NULLIF(btrim(r.prospecto_empresa), ''), NULLIF(btrim(r.cliente_nombre), '')),
          'contacto', COALESCE(r.prospecto_contacto, ''),
          'email', COALESCE(r.prospecto_email, ''),
          'telefono', COALESCE(r.prospecto_telefono, '')
        ),
        NULL, NULL, NULL, NULL
      );
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      v_errores := v_errores || jsonb_build_object('cotizacion_id', r.id, 'error', SQLERRM);
    END;
  END LOOP;
  RETURN jsonb_build_object('ligadas', v_ok, 'fallidas', v_fail, 'errores', v_errores);
END;
$$;
CREATE FUNCTION public.crm_calificar_prospecto(p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lead public.crm_leads;
  v_email text;
  v_faltantes text[] := ARRAY[]::text[];
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'LC_NO_AUTENTICADO';
  END IF;
  SELECT * INTO v_lead
  FROM public.crm_leads
  WHERE id = p_lead_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_lead.id IS NULL THEN
    RAISE EXCEPTION 'LC_LEAD_NO_ENCONTRADO';
  END IF;
  IF NOT public.is_org_member(v_lead.organization_id) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  IF NOT public.has_role(auth.uid(), 'vendedor'::public.app_role) THEN
    RAISE EXCEPTION 'LC_LEAD_SIN_PERMISO_CALIFICAR';
  END IF;
  IF v_lead.estado::text IN ('Descalificado', 'Convertido') THEN
    RAISE EXCEPTION 'LC_LEAD_ESTADO_NO_CALIFICABLE';
  END IF;
  -- Idempotente: recalificar un prospecto no es error (doble click / retry).
  IF v_lead.estado::text IN ('Prospecto', 'Pendiente de alta') THEN
    RETURN jsonb_build_object(
      'lead_id', v_lead.id,
      'estado', v_lead.estado,
      'calificado', false
    );
  END IF;
  -- Perfil comercial mínimo (ICP) para poder cotizar.
  IF COALESCE(NULLIF(TRIM(v_lead.sector), ''), NULL) IS NULL THEN
    v_faltantes := v_faltantes || 'sector';
  END IF;
  IF COALESCE(NULLIF(TRIM(v_lead.mercancia), ''), NULL) IS NULL THEN
    v_faltantes := v_faltantes || 'mercancia';
  END IF;
  IF COALESCE(NULLIF(TRIM(v_lead.rutas), ''), NULL) IS NULL THEN
    v_faltantes := v_faltantes || 'rutas';
  END IF;
  IF COALESCE(NULLIF(TRIM(v_lead.volumen), ''), NULL) IS NULL THEN
    v_faltantes := v_faltantes || 'volumen';
  END IF;
  IF COALESCE(NULLIF(TRIM(v_lead.frecuencia), ''), NULL) IS NULL THEN
    v_faltantes := v_faltantes || 'frecuencia';
  END IF;
  IF COALESCE(NULLIF(TRIM(v_lead.dolor_explicito), ''), NULL) IS NULL THEN
    v_faltantes := v_faltantes || 'dolor_explicito';
  END IF;
  IF COALESCE(NULLIF(TRIM(v_lead.proveedor_actual), ''), NULL) IS NULL THEN
    v_faltantes := v_faltantes || 'proveedor_actual';
  END IF;
  IF array_length(v_faltantes, 1) IS NOT NULL THEN
    RAISE EXCEPTION 'LC_LEAD_PERFIL_INCOMPLETO: %', array_to_string(v_faltantes, ',');
  END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = auth.uid();
  UPDATE public.crm_leads
     SET estado = 'Prospecto'::public.crm_lead_estado,
         estatus_icp = 'calificado',
         updated_at = now()
   WHERE id = v_lead.id;
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, accion, modulo,
    entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_lead.organization_id, auth.uid(), COALESCE(v_email, ''),
    'crm_calificar_prospecto', 'crm', v_lead.id, COALESCE(v_lead.empresa, ''),
    jsonb_build_object('estado_anterior', v_lead.estado, 'estado_nuevo', 'Prospecto')
  );
  RETURN jsonb_build_object(
    'lead_id', v_lead.id,
    'estado', 'Prospecto',
    'calificado', true
  );
END;
$$;
CREATE FUNCTION public.crm_cierra_oportunidad_desde_cotizacion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_op_id uuid;
  v_op_org uuid;
  v_op_vendedor uuid;
  v_op_nombre text;
  v_etapa_actual_tipo crm_etapa_tipo;
  v_etapa_ganada_id uuid;
BEGIN
  -- Sólo nos interesa cuando la cotización entra a Aceptada o En operación
  IF NEW.oportunidad_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.estado NOT IN ('Aceptada'::estado_cotizacion, 'En operación'::estado_cotizacion) THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE'
     AND OLD.estado = NEW.estado
     AND COALESCE(OLD.embarque_id::text, '') = COALESCE(NEW.embarque_id::text, '') THEN
    RETURN NEW;
  END IF;
  SELECT o.id, o.organization_id, o.vendedor_id, o.nombre, e.tipo
    INTO v_op_id, v_op_org, v_op_vendedor, v_op_nombre, v_etapa_actual_tipo
  FROM public.crm_oportunidades o
  JOIN public.crm_etapas_pipeline e ON e.id = o.etapa_id
  WHERE o.id = NEW.oportunidad_id
    AND o.deleted_at IS NULL;
  IF v_op_id IS NULL THEN
    RETURN NEW;
  END IF;
  -- Sólo si la oportunidad sigue abierta
  IF v_etapa_actual_tipo <> 'abierta'::crm_etapa_tipo THEN
    RETURN NEW;
  END IF;
  -- Etapa ganada de la misma org (la primera por orden)
  SELECT id INTO v_etapa_ganada_id
  FROM public.crm_etapas_pipeline
  WHERE organization_id = v_op_org
    AND tipo = 'ganada'::crm_etapa_tipo
    AND activa = true
    AND deleted_at IS NULL
  ORDER BY orden ASC
  LIMIT 1;
  IF v_etapa_ganada_id IS NULL THEN
    -- No hay etapa ganada configurada; no rompemos la operación
    RETURN NEW;
  END IF;
  UPDATE public.crm_oportunidades
     SET etapa_id = v_etapa_ganada_id,
         probabilidad = 100,
         fecha_cierre_real = COALESCE(fecha_cierre_real, CURRENT_DATE),
         valor_real = COALESCE(valor_real, NEW.subtotal),
         cotizacion_ganadora_id = NEW.id,
         embarque_ganador_id = COALESCE(embarque_ganador_id, NEW.embarque_id),
         updated_at = now()
   WHERE id = v_op_id;
  -- Bitácora (best-effort)
  BEGIN
    INSERT INTO public.bitacora_actividad (
      organization_id, modulo, accion, entidad_id, entidad_nombre,
      usuario_id, usuario_email, detalles
    ) VALUES (
      v_op_org, 'crm', 'oportunidad_ganada_auto', v_op_id, v_op_nombre,
      COALESCE(auth.uid(), v_op_vendedor),
      COALESCE((auth.jwt() ->> 'email')::text, ''),
      jsonb_build_object(
        'cotizacion_id', NEW.id,
        'cotizacion_folio', NEW.folio,
        'embarque_id', NEW.embarque_id,
        'monto', NEW.subtotal
      )
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  -- Notificación al vendedor
  IF v_op_vendedor IS NOT NULL THEN
    BEGIN
      INSERT INTO public.crm_notificaciones (
        organization_id, user_id, tipo, titulo, mensaje, link
      ) VALUES (
        v_op_org, v_op_vendedor, 'oportunidad_ganada',
        '¡Oportunidad ganada!',
        '“' || v_op_nombre || '” se cerró automáticamente con la cotización ' || COALESCE(NEW.folio, ''),
        '/crm/oportunidades/' || v_op_id::text
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.crm_criterios_avance(p_oportunidad_ids uuid[]) RETURNS TABLE(oportunidad_id uuid, etapa_id uuid, total integer, cumplidos integer, obligatorios_pendientes integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    o.id AS oportunidad_id,
    o.etapa_id,
    COUNT(c.id)::int AS total,
    COUNT(oc.id)::int AS cumplidos,
    COUNT(*) FILTER (WHERE c.obligatorio AND oc.id IS NULL)::int AS obligatorios_pendientes
  FROM public.crm_oportunidades o
  LEFT JOIN public.crm_etapa_criterios c
    ON c.etapa_id = o.etapa_id AND c.activo AND c.deleted_at IS NULL
  LEFT JOIN public.crm_oportunidad_criterios oc
    ON oc.oportunidad_id = o.id AND oc.criterio_id = c.id
  WHERE o.id = ANY(p_oportunidad_ids)
    AND o.deleted_at IS NULL
  GROUP BY o.id, o.etapa_id
$$;
CREATE FUNCTION public.crm_embudo_conversion(p_desde date, p_hasta date) RETURNS TABLE(etapa_id uuid, etapa_nombre text, orden integer, probabilidad_default numeric, oportunidades integer, valor numeric, ponderado numeric, entradas integer, conversion_desde_anterior numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH etapas AS (
    SELECT e.id, e.nombre, e.orden, e.probabilidad_default
      FROM public.crm_etapas_pipeline e
     WHERE e.deleted_at IS NULL AND e.activa
  ),
  actuales AS (
    SELECT o.etapa_id,
           COUNT(*)::int AS oportunidades,
           COALESCE(SUM(o.monto_estimado), 0) AS valor,
           COALESCE(SUM(o.monto_estimado * COALESCE(o.probabilidad, 0) / 100.0), 0) AS ponderado
      FROM public.crm_oportunidades o
     WHERE o.deleted_at IS NULL
       AND o.created_at::date BETWEEN p_desde AND p_hasta
     GROUP BY o.etapa_id
  ),
  entradas AS (
    SELECT h.etapa_destino_id AS etapa_id, COUNT(DISTINCT h.oportunidad_id)::int AS entradas
      FROM public.crm_historial_etapas h
     WHERE h.created_at::date BETWEEN p_desde AND p_hasta
     GROUP BY h.etapa_destino_id
  ),
  agregado AS (
    SELECT e.id, e.nombre, e.orden, e.probabilidad_default,
           COALESCE(a.oportunidades, 0) AS oportunidades,
           COALESCE(a.valor, 0) AS valor,
           COALESCE(a.ponderado, 0) AS ponderado,
           GREATEST(COALESCE(en.entradas, 0), COALESCE(a.oportunidades, 0)) AS entradas
      FROM etapas e
      LEFT JOIN actuales a ON a.etapa_id = e.id
      LEFT JOIN entradas en ON en.etapa_id = e.id
  )
  SELECT g.id, g.nombre, g.orden, g.probabilidad_default, g.oportunidades, g.valor, g.ponderado, g.entradas,
         CASE
           WHEN LAG(g.entradas) OVER (ORDER BY g.orden) IS NULL
             OR LAG(g.entradas) OVER (ORDER BY g.orden) = 0 THEN NULL
           ELSE ROUND(g.entradas::numeric / LAG(g.entradas) OVER (ORDER BY g.orden), 4)
         END AS conversion_desde_anterior
    FROM agregado g
   ORDER BY g.orden;
$$;
CREATE FUNCTION public.crm_higiene_oportunidades() RETURNS TABLE(id uuid, nombre text, cliente_nombre text, etapa_id uuid, etapa_nombre text, vendedor_email text, monto_estimado numeric, moneda text, probabilidad numeric, fecha_estimada_cierre date, ultimo_movimiento_at timestamp with time zone, dias_sin_movimiento integer, sla_dias integer, estado_higiene text, registro_completo boolean, proxima_actividad_at timestamp with time zone, actividad_vencida boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT o.id, o.nombre, o.cliente_nombre, o.etapa_id, e.nombre AS etapa_nombre,
           o.vendedor_email, o.monto_estimado, o.moneda::text AS moneda, o.probabilidad,
           o.fecha_estimada_cierre,
           COALESCE(o.ultimo_movimiento_at, o.updated_at, o.created_at) AS ultimo_movimiento_at,
           COALESCE(NULLIF(e.sla_dias, 0), NULLIF(e.dias_seguimiento, 0), 7) AS sla_dias,
           (SELECT MIN(a.fecha_programada)
              FROM public.crm_actividades a
             WHERE a.entidad_tipo = 'oportunidad'::public.crm_entidad_tipo
               AND a.entidad_id = o.id
               AND a.deleted_at IS NULL
               AND a.fecha_completada IS NULL) AS proxima_actividad_at
      FROM public.crm_oportunidades o
      JOIN public.crm_etapas_pipeline e ON e.id = o.etapa_id
     WHERE o.deleted_at IS NULL
       AND e.tipo = 'abierta'::public.crm_etapa_tipo
  )
  SELECT b.id, b.nombre, b.cliente_nombre, b.etapa_id, b.etapa_nombre, b.vendedor_email,
         b.monto_estimado, b.moneda, b.probabilidad, b.fecha_estimada_cierre,
         b.ultimo_movimiento_at,
         GREATEST(0, (EXTRACT(EPOCH FROM (now() - b.ultimo_movimiento_at)) / 86400)::int) AS dias_sin_movimiento,
         b.sla_dias,
         CASE
           WHEN (EXTRACT(EPOCH FROM (now() - b.ultimo_movimiento_at)) / 86400) > b.sla_dias THEN 'vencida'
           WHEN (EXTRACT(EPOCH FROM (now() - b.ultimo_movimiento_at)) / 86400) >= (b.sla_dias * 0.7) THEN 'por_vencer'
           ELSE 'en_tiempo'
         END AS estado_higiene,
         (COALESCE(b.monto_estimado, 0) > 0
          AND b.fecha_estimada_cierre IS NOT NULL
          AND COALESCE(b.vendedor_email, '') <> ''
          AND b.proxima_actividad_at IS NOT NULL) AS registro_completo,
         b.proxima_actividad_at,
         (b.proxima_actividad_at IS NOT NULL AND b.proxima_actividad_at < now()) AS actividad_vencida
    FROM base b;
$$;
CREATE FUNCTION public.crm_higiene_pipeline() RETURNS TABLE(abiertas integer, registros_completos integer, higiene_pct numeric, seguimiento_oportuno_pct numeric, vencidas integer, sin_actividad_programada integer, pipeline_bruto numeric, pipeline_ponderado numeric, tc_fecha date, tc_estimado boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH h AS (SELECT * FROM public.crm_higiene_oportunidades()),
  tc AS (SELECT * FROM public.tc_dof_vigente(CURRENT_DATE)),
  m AS (
    SELECT
      h.*,
      CASE upper(COALESCE(h.moneda, 'MXN'))
        WHEN 'MXN' THEN COALESCE(h.monto_estimado, 0)
        WHEN 'USD' THEN COALESCE(h.monto_estimado, 0) * (SELECT usd_mxn FROM tc)
        WHEN 'EUR' THEN COALESCE(h.monto_estimado, 0) * (SELECT eur_mxn FROM tc)
        ELSE NULL
      END AS monto_mxn
    FROM h
  )
  SELECT COUNT(*)::int,
         COUNT(*) FILTER (WHERE registro_completo)::int,
         CASE WHEN COUNT(*) = 0 THEN 0
              ELSE ROUND(COUNT(*) FILTER (WHERE registro_completo)::numeric / COUNT(*), 4) END,
         CASE WHEN COUNT(*) = 0 THEN 0
              ELSE ROUND(COUNT(*) FILTER (WHERE NOT actividad_vencida)::numeric / COUNT(*), 4) END,
         COUNT(*) FILTER (WHERE estado_higiene = 'vencida')::int,
         COUNT(*) FILTER (WHERE proxima_actividad_at IS NULL)::int,
         ROUND(COALESCE(SUM(monto_mxn), 0), 2),
         ROUND(COALESCE(SUM(monto_mxn * COALESCE(probabilidad, 0) / 100.0), 0), 2),
         (SELECT fecha FROM tc),
         -- Estimado cuando hay montos en moneda extranjera que no se pudieron
         -- convertir (sin TC DOF publicado o moneda no soportada).
         EXISTS (
           SELECT 1 FROM m
           WHERE m.monto_mxn IS NULL
             AND COALESCE(m.monto_estimado, 0) <> 0
         )
    FROM m;
$$;
CREATE FUNCTION public.crm_leads_buscar_duplicados(p_claves jsonb) RETURNS TABLE(id uuid, empresa text, contacto text, email text, telefono text, estado public.crm_lead_estado, empresa_norm text, email_norm text, telefono_norm text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH claves AS (
    SELECT
      NULLIF(lower(regexp_replace(coalesce(c->>'empresa', ''), '[^a-z0-9]', '', 'gi')), '') AS empresa_norm,
      NULLIF(lower(trim(coalesce(c->>'email', ''))), '')                                   AS email_norm,
      NULLIF(regexp_replace(coalesce(c->>'telefono', ''), '\D', '', 'g'), '')               AS telefono_norm
    FROM jsonb_array_elements(coalesce(p_claves, '[]'::jsonb)) AS c
  )
  SELECT DISTINCT
    l.id, l.empresa, l.contacto, l.email, l.telefono, l.estado,
    lower(regexp_replace(coalesce(l.empresa, ''), '[^a-z0-9]', '', 'gi')) AS empresa_norm,
    lower(trim(coalesce(l.email, '')))                                   AS email_norm,
    regexp_replace(coalesce(l.telefono, ''), '\D', '', 'g')              AS telefono_norm
  FROM public.crm_leads l
  JOIN claves k ON (
       (k.email_norm    IS NOT NULL AND lower(trim(coalesce(l.email, ''))) = k.email_norm)
    OR (k.telefono_norm IS NOT NULL AND length(k.telefono_norm) >= 8
        AND right(regexp_replace(coalesce(l.telefono, ''), '\D', '', 'g'), 10) = right(k.telefono_norm, 10))
    OR (k.empresa_norm  IS NOT NULL AND length(k.empresa_norm) >= 4
        AND lower(regexp_replace(coalesce(l.empresa, ''), '[^a-z0-9]', '', 'gi')) = k.empresa_norm)
  )
  WHERE l.deleted_at IS NULL
    AND public.rls_tenant_scope_ok(l.organization_id);
$$;
CREATE FUNCTION public.crm_marcar_oportunidad_ganada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_etapa_ganada uuid;
BEGIN
  IF NEW.oportunidad_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.estado::text <> 'Aceptada' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.estado = NEW.estado THEN RETURN NEW; END IF;
  SELECT id INTO v_etapa_ganada
  FROM public.crm_etapas_pipeline
  WHERE organization_id = NEW.organization_id
    AND tipo = 'ganada'
    AND deleted_at IS NULL
  ORDER BY orden ASC LIMIT 1;
  IF v_etapa_ganada IS NULL THEN RETURN NEW; END IF;
  UPDATE public.crm_oportunidades
  SET etapa_id = v_etapa_ganada, probabilidad = 100,
      fecha_cierre_real = COALESCE(fecha_cierre_real, CURRENT_DATE)
  WHERE id = NEW.oportunidad_id AND organization_id = NEW.organization_id;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.crm_notify_comentario_oportunidad() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_vendedor_id uuid;
  v_op_nombre text;
BEGIN
  SELECT vendedor_id, nombre
    INTO v_vendedor_id, v_op_nombre
    FROM public.crm_oportunidades
   WHERE id = NEW.oportunidad_id;
  IF v_vendedor_id IS NOT NULL AND v_vendedor_id <> NEW.autor_id THEN
    INSERT INTO public.crm_notificaciones (
      organization_id, user_id, tipo, titulo, mensaje, link
    ) VALUES (
      NEW.organization_id,
      v_vendedor_id,
      'comentario_oportunidad',
      'Nuevo comentario en oportunidad',
      COALESCE(NEW.autor_email, 'Alguien') || ' comentó en "' || COALESCE(v_op_nombre, 'oportunidad') || '"',
      '/crm/oportunidades/' || NEW.oportunidad_id::text
    );
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.crm_propagar_conversion_cliente(p_oportunidad_id uuid, p_cliente_id uuid, p_cliente_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_op public.crm_oportunidades;
  v_lead_id uuid;
  v_cliente_org uuid;
  v_uid uuid := auth.uid();
  v_gerencial boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'LC_NO_AUTENTICADO';
  END IF;
  IF p_oportunidad_id IS NULL OR p_cliente_id IS NULL THEN
    RAISE EXCEPTION 'LC_PARAMETROS_INVALIDOS';
  END IF;
  -- M-2: el permiso primero; así un usuario sin rol no distingue entre
  -- "no existe" y "no es tuya".
  v_gerencial := public.has_any_role_efectivo(v_uid,
    ARRAY['admin','admin_org','super_admin','gerente_comercial','gerente_operaciones']::app_role[]);
  IF NOT v_gerencial
     AND NOT public.has_role(v_uid, 'vendedor'::public.app_role) THEN
    RAISE EXCEPTION 'LC_SIN_PERMISO';
  END IF;
  SELECT * INTO v_op
  FROM public.crm_oportunidades
  WHERE id = p_oportunidad_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_op.id IS NULL THEN
    RAISE EXCEPTION 'LC_OPORTUNIDAD_NO_ENCONTRADA';
  END IF;
  IF public.is_org_member(v_op.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  -- M-1: sólo el vendedor dueño (o un rol gerencial) propaga la conversión.
  IF NOT v_gerencial AND COALESCE(v_op.vendedor_id, v_op.created_by) IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'LC_OPORTUNIDAD_AJENA: la oportunidad está asignada a otra persona';
  END IF;
  -- M-1: no pisar una conversión previa hacia otro cliente.
  IF v_op.cliente_id IS NOT NULL AND v_op.cliente_id <> p_cliente_id THEN
    RAISE EXCEPTION 'LC_OPORTUNIDAD_YA_CONVERTIDA: la oportunidad ya está ligada a otro cliente';
  END IF;
  SELECT organization_id INTO v_cliente_org
  FROM public.clientes
  WHERE id = p_cliente_id AND deleted_at IS NULL;
  IF v_cliente_org IS NULL THEN
    RAISE EXCEPTION 'LC_CLIENTE_NO_ENCONTRADO';
  END IF;
  IF v_cliente_org <> v_op.organization_id THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  UPDATE public.crm_oportunidades
     SET cliente_id = p_cliente_id,
         cliente_nombre = COALESCE(NULLIF(p_cliente_nombre, ''), cliente_nombre),
         updated_at = now()
   WHERE id = p_oportunidad_id;
  v_lead_id := v_op.lead_id;
  IF v_lead_id IS NOT NULL THEN
    UPDATE public.crm_leads
       SET estado = 'Convertido'::public.crm_lead_estado,
           cliente_convertido_id = p_cliente_id,
           oportunidad_convertida_id = p_oportunidad_id,
           updated_at = now()
     WHERE id = v_lead_id
       AND organization_id = v_op.organization_id
       AND deleted_at IS NULL;
  END IF;
  RETURN jsonb_build_object(
    'oportunidad_id', p_oportunidad_id,
    'cliente_id', p_cliente_id,
    'lead_id', v_lead_id
  );
END;
$$;
CREATE FUNCTION public.crm_set_valor_real_on_aceptada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_previo numeric;
BEGIN
  IF NEW.oportunidad_id IS NOT NULL
     AND NEW.estado = 'Aceptada'::estado_cotizacion
     AND (OLD.estado IS DISTINCT FROM NEW.estado) THEN
    SELECT valor_real INTO v_previo FROM public.crm_oportunidades WHERE id = NEW.oportunidad_id;
    UPDATE public.crm_oportunidades
       SET valor_real = NEW.subtotal,
           fecha_cierre_real = CURRENT_DATE,
           updated_at = now()
     WHERE id = NEW.oportunidad_id;
    IF v_previo IS DISTINCT FROM NEW.subtotal THEN
      INSERT INTO public.bitacora_actividad (
        organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles
      ) VALUES (
        NEW.organization_id, auth.uid(),
        COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), ''),
        'crm.oportunidad.valor_real_actualizado',
        'crm_oportunidades',
        NEW.oportunidad_id,
        '',
        jsonb_build_object('valor_previo', v_previo, 'valor_nuevo', NEW.subtotal,
                          'cotizacion_id', NEW.id, 'version', NEW.version)
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.crm_tomar_lead(p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lead public.crm_leads;
  v_email text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'LC_NO_AUTENTICADO';
  END IF;
  -- FOR UPDATE: serializa tomas simultáneas del mismo lead; la segunda
  -- transacción espera el lock y luego ve vendedor_id ya poblado.
  SELECT * INTO v_lead
  FROM public.crm_leads
  WHERE id = p_lead_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_lead.id IS NULL THEN
    RAISE EXCEPTION 'LC_LEAD_NO_ENCONTRADO';
  END IF;
  IF NOT public.is_org_member(v_lead.organization_id) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  -- has_role('vendedor') incluye gerente_comercial/admin_org/super_admin por
  -- la jerarquía (roles_jerarquia), igual que la policy "Vendedor own".
  IF NOT public.has_role(auth.uid(), 'vendedor'::public.app_role) THEN
    RAISE EXCEPTION 'LC_LEAD_SIN_PERMISO_TOMA';
  END IF;
  -- Idempotente: re-tomar un lead ya propio no es error (doble click/retry).
  IF v_lead.vendedor_id = auth.uid() THEN
    RETURN jsonb_build_object(
      'lead_id', v_lead.id,
      'vendedor_id', v_lead.vendedor_id,
      'tomado', false
    );
  END IF;
  IF v_lead.vendedor_id IS NOT NULL THEN
    RAISE EXCEPTION 'LC_LEAD_YA_ASIGNADO';
  END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = auth.uid();
  UPDATE public.crm_leads
     SET vendedor_id = auth.uid(),
         vendedor_email = COALESCE(v_email, ''),
         updated_at = now()
   WHERE id = p_lead_id;
  RETURN jsonb_build_object(
    'lead_id', v_lead.id,
    'vendedor_id', auth.uid(),
    'tomado', true
  );
END;
$$;
CREATE FUNCTION public.crm_vincular_cotizacion(p_cotizacion_id uuid, p_prospecto jsonb DEFAULT '{}'::jsonb, p_lead_id uuid DEFAULT NULL::uuid, p_oportunidad_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_email text;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.cotizaciones WHERE id = p_cotizacion_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_COTIZACION_NO_ENCONTRADA: la cotización no existe';
  END IF;
  IF NOT public.is_org_member(v_org) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA: la cotización pertenece a otra organización';
  END IF;
  IF NOT public.rls_tenant_scope_ok(v_org) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA: la cotización pertenece a otra organización';
  END IF;
  IF NOT public.puede_escribir_cotizaciones() THEN
    RAISE EXCEPTION 'LC_COTIZACION_SIN_PERMISO_ESCRITURA: tu rol no puede modificar cotizaciones';
  END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = auth.uid();
  RETURN public._crm_vincular_cotizacion_core(
    p_cotizacion_id, COALESCE(p_prospecto, '{}'::jsonb), p_lead_id, p_oportunidad_id,
    v_email, auth.uid()
  );
END;
$$;
CREATE FUNCTION public.cron_try_lock(p_key text, p_ttl_seconds integer DEFAULT 3600, p_owner text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_n integer;
BEGIN
  INSERT INTO public.cron_locks (key, locked_at, owner)
  VALUES (p_key, now(), p_owner)
  ON CONFLICT (key) DO UPDATE
    SET locked_at = now(), owner = EXCLUDED.owner
    WHERE public.cron_locks.locked_at
          < now() - make_interval(secs => GREATEST(p_ttl_seconds, 60));
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n > 0;
END;
$$;
CREATE FUNCTION public.cron_unlock(p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  DELETE FROM public.cron_locks WHERE key = p_key;
END;
$$;
