CREATE FUNCTION public.cxc_aging_clientes(p_org uuid DEFAULT NULL::uuid, p_fecha date DEFAULT CURRENT_DATE) RETURNS TABLE(cliente_id uuid, cliente_nombre text, moneda text, saldo_total numeric, vigente numeric, d_1_30 numeric, d_31_60 numeric, d_61_90 numeric, mas_90 numeric, num_facturas integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid := public.current_user_org_id();
  v_org uuid;
  v_is_super boolean := public.has_role(auth.uid(), 'super_admin'::app_role);
BEGIN
  IF v_caller_org IS NULL AND NOT v_is_super THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: usuario sin organización activa' USING ERRCODE='42501';
  END IF;
  IF v_is_super THEN
    IF p_org IS NULL THEN
      RAISE EXCEPTION 'LC_ORG_REQUERIDA: selecciona una organización para ver este reporte' USING ERRCODE='42501';
    END IF;
    v_org := p_org;
  ELSIF p_org IS NOT NULL AND p_org IS DISTINCT FROM v_caller_org THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: no puedes consultar el aging de otra organización' USING ERRCODE='42501';
  ELSE
    v_org := v_caller_org;
  END IF;
  RETURN QUERY
  WITH pagado AS (
    SELECT pf.factura_id, COALESCE(SUM(pf.monto_aplicado_factura), 0) AS pagado
    FROM public.pagos_factura pf
    JOIN public.facturas f ON f.id = pf.factura_id AND f.deleted_at IS NULL
    WHERE pf.deleted_at IS NULL
      AND (v_org IS NULL OR f.organization_id = v_org)
    GROUP BY pf.factura_id
  ),
  nc AS (
    SELECT ncf.factura_id, COALESCE(SUM(ncf.monto), 0) AS aplicado
    FROM public.factura_notas_credito ncf
    JOIN public.facturas f ON f.id = ncf.factura_id AND f.deleted_at IS NULL
    WHERE ncf.estado = 'Aplicada' AND ncf.deleted_at IS NULL
      AND (v_org IS NULL OR f.organization_id = v_org)
    GROUP BY ncf.factura_id
  ),
  saldos AS (
    SELECT
      f.cliente_id,
      f.cliente_nombre,
      UPPER(COALESCE(f.moneda::text, 'MXN')) AS moneda,
      f.id AS factura_id,
      GREATEST(f.total - COALESCE(pg.pagado, 0) - COALESCE(nc.aplicado, 0), 0) AS saldo,
      (p_fecha - COALESCE(f.fecha_vencimiento, f.fecha_emision))::int AS dias_vencido
    FROM public.facturas f
    LEFT JOIN pagado pg ON pg.factura_id = f.id
    LEFT JOIN nc ON nc.factura_id = f.id
    WHERE f.deleted_at IS NULL
      AND f.estado IN ('Emitida', 'Parcialmente pagada', 'Vencida')
      AND COALESCE(f.cancellation_status, 'none') NOT IN ('pending','verifying','accepted')
      AND f.sustituida_por IS NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.refacturaciones r
        WHERE r.factura_original_id = f.id AND r.estado = 'completado'
      )
      AND (v_org IS NULL OR f.organization_id = v_org)
  )
  SELECT
    s.cliente_id,
    MAX(s.cliente_nombre),
    s.moneda,
    SUM(s.saldo),
    SUM(CASE WHEN s.dias_vencido <= 0 THEN s.saldo ELSE 0 END),
    SUM(CASE WHEN s.dias_vencido BETWEEN 1 AND 30 THEN s.saldo ELSE 0 END),
    SUM(CASE WHEN s.dias_vencido BETWEEN 31 AND 60 THEN s.saldo ELSE 0 END),
    SUM(CASE WHEN s.dias_vencido BETWEEN 61 AND 90 THEN s.saldo ELSE 0 END),
    SUM(CASE WHEN s.dias_vencido > 90 THEN s.saldo ELSE 0 END),
    COUNT(*)::int
  FROM saldos s
  WHERE s.saldo > 0.005
  GROUP BY s.cliente_id, s.moneda
  ORDER BY SUM(s.saldo) DESC;
END;
$$;
CREATE FUNCTION public.cxp_aging_proveedores(p_org uuid DEFAULT NULL::uuid, p_fecha date DEFAULT CURRENT_DATE) RETURNS TABLE(proveedor_id uuid, proveedor_nombre text, moneda text, saldo_total numeric, vigente numeric, d_1_30 numeric, d_31_60 numeric, d_61_90 numeric, mas_90 numeric, num_facturas integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid := public.current_user_org_id();
  v_org uuid;
  v_is_super boolean := public.has_role(auth.uid(), 'super_admin'::app_role);
BEGIN
  IF v_caller_org IS NULL AND NOT v_is_super THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: usuario sin organización activa' USING ERRCODE='42501';
  END IF;
  IF v_is_super THEN
    IF p_org IS NULL THEN
      RAISE EXCEPTION 'LC_ORG_REQUERIDA: selecciona una organización para ver este reporte' USING ERRCODE='42501';
    END IF;
    v_org := p_org;
  ELSIF p_org IS NOT NULL AND p_org IS DISTINCT FROM v_caller_org THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: no puedes consultar el aging de otra organización' USING ERRCODE='42501';
  ELSE
    v_org := v_caller_org;
  END IF;
  RETURN QUERY
  WITH pagado AS (
    SELECT pp.proveedor_factura_id,
           COALESCE(SUM(COALESCE(pp.monto_en_moneda_factura, pp.monto)), 0) AS pagado
      FROM public.pagos_proveedor pp
      JOIN public.proveedor_facturas pf ON pf.id = pp.proveedor_factura_id AND pf.deleted_at IS NULL
     WHERE pp.deleted_at IS NULL
       AND (v_org IS NULL OR pf.organization_id = v_org)
     GROUP BY pp.proveedor_factura_id
  ), nc AS (
    SELECT pnc.proveedor_factura_id, COALESCE(SUM(pnc.monto), 0) AS aplicado
      FROM public.proveedor_notas_credito pnc
      JOIN public.proveedor_facturas pf ON pf.id = pnc.proveedor_factura_id AND pf.deleted_at IS NULL
     WHERE pnc.estado = 'Aplicada' AND pnc.deleted_at IS NULL
       AND (v_org IS NULL OR pf.organization_id = v_org)
     GROUP BY pnc.proveedor_factura_id
  ), saldos AS (
    SELECT pf.proveedor_id,
           pf.proveedor_nombre,
           COALESCE(pf.moneda, 'MXN')::text AS moneda,
           pf.id AS factura_id,
           GREATEST(pf.total - COALESCE(pg.pagado, 0) - COALESCE(nc.aplicado, 0), 0) AS saldo,
           (p_fecha - COALESCE(pf.fecha_vencimiento, pf.fecha_emision))::int AS dias_vencido
      FROM public.proveedor_facturas pf
      LEFT JOIN pagado pg ON pg.proveedor_factura_id = pf.id
      LEFT JOIN nc       ON nc.proveedor_factura_id = pf.id
     WHERE pf.deleted_at IS NULL
       AND pf.estado <> 'Cancelada'
       AND (v_org IS NULL OR pf.organization_id = v_org)
  )
  SELECT s.proveedor_id,
         MAX(s.proveedor_nombre),
         s.moneda,
         SUM(s.saldo),
         SUM(CASE WHEN s.dias_vencido <= 0                       THEN s.saldo ELSE 0 END),
         SUM(CASE WHEN s.dias_vencido BETWEEN 1  AND 30           THEN s.saldo ELSE 0 END),
         SUM(CASE WHEN s.dias_vencido BETWEEN 31 AND 60           THEN s.saldo ELSE 0 END),
         SUM(CASE WHEN s.dias_vencido BETWEEN 61 AND 90           THEN s.saldo ELSE 0 END),
         SUM(CASE WHEN s.dias_vencido > 90                        THEN s.saldo ELSE 0 END),
         COUNT(*)::int
    FROM saldos s
   WHERE s.saldo > 0.005
   GROUP BY s.proveedor_id, s.moneda
   ORDER BY SUM(s.saldo) DESC;
END;
$$;
CREATE FUNCTION public.is_org_member(p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(public.current_user_org_id() = p_org, false)
      OR COALESCE(public.has_role(auth.uid(), 'super_admin'::app_role), false);
$$;
CREATE FUNCTION public.monto_pago_en_moneda_factura(p_monto numeric, p_moneda_pago text, p_tc_pago numeric, p_moneda_factura text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_monto IS NULL THEN RETURN NULL; END IF;
  IF p_moneda_pago = p_moneda_factura THEN RETURN p_monto; END IF;
  IF COALESCE(p_tc_pago, 0) <= 0 THEN RETURN NULL; END IF;
  IF p_moneda_pago = 'MXN' THEN RETURN round(p_monto / p_tc_pago, 4); END IF;
  IF p_moneda_factura = 'MXN' THEN RETURN round(p_monto * p_tc_pago, 4); END IF;
  -- Cruce USD<->EUR: pagos_proveedor no almacena TC cruzado; se excluye.
  RETURN NULL;
END;
$$;
CREATE TABLE public.pagos_proveedor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    proveedor_factura_id uuid NOT NULL,
    fecha_pago date DEFAULT CURRENT_DATE NOT NULL,
    monto numeric DEFAULT 0 NOT NULL,
    moneda public.moneda DEFAULT 'MXN'::public.moneda NOT NULL,
    tipo_cambio_usd numeric,
    diferencia_cambiaria_mxn numeric,
    metodo_pago text DEFAULT 'Transferencia'::text NOT NULL,
    referencia text DEFAULT ''::text NOT NULL,
    cuenta_bancaria_id uuid,
    notas text DEFAULT ''::text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    es_ajuste boolean DEFAULT false NOT NULL,
    motivo_ajuste text,
    monto_en_moneda_factura numeric(18,4),
    es_anticipo_aplicado boolean DEFAULT false NOT NULL,
    lote_id uuid,
    client_request_id uuid,
    CONSTRAINT pagos_proveedor_monto_convertido_no_null CHECK (((deleted_at IS NOT NULL) OR (monto_en_moneda_factura IS NOT NULL))),
    CONSTRAINT pagos_proveedor_monto_escala CHECK ((scale(monto) <= 2)),
    CONSTRAINT pagos_proveedor_monto_pos CHECK (((deleted_at IS NOT NULL) OR (monto > (0)::numeric)))
);
ALTER TABLE ONLY public.pagos_proveedor FORCE ROW LEVEL SECURITY;
CREATE TABLE public.proveedor_notas_credito (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    proveedor_factura_id uuid NOT NULL,
    folio_nc text DEFAULT ''::text NOT NULL,
    fecha date DEFAULT CURRENT_DATE NOT NULL,
    monto numeric DEFAULT 0 NOT NULL,
    moneda public.moneda DEFAULT 'MXN'::public.moneda NOT NULL,
    motivo public.motivo_nota_credito_proveedor DEFAULT 'Otro'::public.motivo_nota_credito_proveedor NOT NULL,
    descripcion text DEFAULT ''::text NOT NULL,
    estado public.estado_nota_credito_proveedor DEFAULT 'Borrador'::public.estado_nota_credito_proveedor NOT NULL,
    aprobada_por uuid,
    aprobada_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    archivo_xml_url text,
    archivo_pdf_url text,
    uuid_fiscal text,
    uuid_estatus_sat text,
    uuid_verificado_fecha timestamp with time zone,
    tipo_cambio numeric
);
CREATE VIEW public.v_proveedor_facturas_saldo WITH (security_invoker='true') AS
 SELECT id AS proveedor_factura_id,
    organization_id,
    total,
    COALESCE(( SELECT sum(pp.monto_en_moneda_factura) AS sum
           FROM public.pagos_proveedor pp
          WHERE ((pp.proveedor_factura_id = pf.id) AND (pp.deleted_at IS NULL))), (0)::numeric) AS pagado,
    COALESCE(( SELECT sum(public.monto_pago_en_moneda_factura(nc.monto, (nc.moneda)::text, nc.tipo_cambio, (pf.moneda)::text)) AS sum
           FROM public.proveedor_notas_credito nc
          WHERE ((nc.proveedor_factura_id = pf.id) AND (nc.estado = 'Aplicada'::public.estado_nota_credito_proveedor) AND (nc.deleted_at IS NULL))), (0)::numeric) AS notas_credito_aplicadas,
    ((total - COALESCE(( SELECT sum(pp.monto_en_moneda_factura) AS sum
           FROM public.pagos_proveedor pp
          WHERE ((pp.proveedor_factura_id = pf.id) AND (pp.deleted_at IS NULL))), (0)::numeric)) - COALESCE(( SELECT sum(public.monto_pago_en_moneda_factura(nc.monto, (nc.moneda)::text, nc.tipo_cambio, (pf.moneda)::text)) AS sum
           FROM public.proveedor_notas_credito nc
          WHERE ((nc.proveedor_factura_id = pf.id) AND (nc.estado = 'Aplicada'::public.estado_nota_credito_proveedor) AND (nc.deleted_at IS NULL))), (0)::numeric)) AS saldo
   FROM public.proveedor_facturas pf
  WHERE (deleted_at IS NULL);
CREATE VIEW public.cxp_alertas_vencimiento WITH (security_invoker='on') AS
 SELECT pf.id AS proveedor_factura_id,
    pf.organization_id,
    pf.proveedor_id,
    pf.proveedor_nombre,
    pf.folio_proveedor,
    pf.folio_interno,
    pf.moneda,
    pf.fecha_vencimiento,
    (pf.fecha_vencimiento - CURRENT_DATE) AS dias_a_vencer,
    vs.saldo,
    (pf.estado)::text AS estado
   FROM (public.proveedor_facturas pf
     LEFT JOIN public.v_proveedor_facturas_saldo vs ON ((vs.proveedor_factura_id = pf.id)))
  WHERE ((pf.deleted_at IS NULL) AND ((pf.estado)::text <> ALL (ARRAY['Cancelada'::text, 'Borrador'::text, 'Pagada'::text, 'Rechazada'::text])) AND (pf.fecha_vencimiento IS NOT NULL) AND (COALESCE(vs.saldo, (0)::numeric) > 0.01) AND public.is_org_member(pf.organization_id));
CREATE FUNCTION public.cxp_alertas_vencimiento(p_dias integer DEFAULT 7) RETURNS SETOF public.cxp_alertas_vencimiento
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT *
  FROM public.cxp_alertas_vencimiento
  WHERE dias_a_vencer <= p_dias
  ORDER BY dias_a_vencer ASC, fecha_vencimiento ASC;
$$;
CREATE FUNCTION public.cxp_pendientes_aprobacion_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::int
  FROM public.proveedor_facturas pf
  WHERE pf.deleted_at IS NULL
    AND pf.estado <> 'Cancelada'
    AND pf.estado_aprobacion = 'pendiente'
    AND EXISTS (
      SELECT 1 FROM public.organization_members om
      WHERE om.organization_id = pf.organization_id
        AND om.user_id = auth.uid()
    );
$$;
CREATE FUNCTION public.cxp_por_capturar() RETURNS TABLE(embarque_id uuid, expediente text, cliente_nombre text, presupuestado_mxn numeric, presupuestado_usd numeric, facturado_mxn numeric, facturado_usd numeric, facturas_capturadas integer, ultima_factura_fecha date, dias_desde_ultima_factura integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    e.id,
    e.expediente,
    c.nombre,
    COALESCE(SUM(cc.monto) FILTER (WHERE cc.moneda::text = 'MXN'), 0),
    COALESCE(SUM(cc.monto) FILTER (WHERE cc.moneda::text = 'USD'), 0),
    COALESCE((
      SELECT SUM(pf.total) FILTER (WHERE pf.moneda::text = 'MXN')
      FROM public.proveedor_facturas pf
      WHERE pf.embarque_id = e.id
        AND pf.deleted_at IS NULL
        AND pf.estado::text <> 'Cancelada'
    ), 0),
    COALESCE((
      SELECT SUM(pf.total) FILTER (WHERE pf.moneda::text = 'USD')
      FROM public.proveedor_facturas pf
      WHERE pf.embarque_id = e.id
        AND pf.deleted_at IS NULL
        AND pf.estado::text <> 'Cancelada'
    ), 0),
    (SELECT COUNT(*)::int FROM public.proveedor_facturas pf
       WHERE pf.embarque_id = e.id AND pf.deleted_at IS NULL),
    (SELECT MAX(pf.fecha_emision) FROM public.proveedor_facturas pf
       WHERE pf.embarque_id = e.id AND pf.deleted_at IS NULL),
    (CURRENT_DATE - (SELECT MAX(pf.fecha_emision) FROM public.proveedor_facturas pf
       WHERE pf.embarque_id = e.id AND pf.deleted_at IS NULL))::int
  FROM public.embarques e
  LEFT JOIN public.clientes c ON c.id = e.cliente_id
  LEFT JOIN public.conceptos_costo cc ON cc.embarque_id = e.id AND cc.deleted_at IS NULL
  WHERE e.deleted_at IS NULL
    AND e.estado::text <> 'Cerrado'
  GROUP BY e.id, e.expediente, c.nombre
  HAVING COALESCE(SUM(cc.monto), 0) > 0
  ORDER BY e.created_at DESC
  LIMIT 500;
$$;
CREATE FUNCTION public.cxp_por_pagar() RETURNS TABLE(factura_id uuid, proveedor_id uuid, proveedor_nombre text, proveedor_origen text, folio_proveedor text, embarque_id uuid, expediente text, fecha_emision date, fecha_vencimiento date, dias_para_vencer integer, moneda text, total numeric, pagado numeric, saldo numeric, estado_captura text, tipo_cambio_usd numeric, fecha_programada_pago date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH pagos_conv AS (
    SELECT pp.proveedor_factura_id,
           SUM(COALESCE(pp.monto_en_moneda_factura, pp.monto)) AS pagado
      FROM public.pagos_proveedor pp
     WHERE pp.deleted_at IS NULL
     GROUP BY pp.proveedor_factura_id
  )
  SELECT pf.id, pf.proveedor_id, pf.proveedor_nombre, p.origen_proveedor::text,
    pf.folio_proveedor,
    pf.embarque_id, e.expediente,
    pf.fecha_emision, pf.fecha_vencimiento,
    (pf.fecha_vencimiento - CURRENT_DATE)::int,
    pf.moneda::text, pf.total,
    COALESCE(pc.pagado,0),
    pf.total - COALESCE(pc.pagado,0),
    pf.estado_captura, pf.tipo_cambio_usd, pf.fecha_programada_pago
  FROM public.proveedor_facturas pf
  LEFT JOIN public.embarques e ON e.id = pf.embarque_id
  LEFT JOIN public.proveedores p ON p.id = pf.proveedor_id
  LEFT JOIN pagos_conv pc ON pc.proveedor_factura_id = pf.id
  WHERE pf.deleted_at IS NULL AND pf.estado::text = 'Vigente'
  ORDER BY pf.fecha_vencimiento NULLS LAST, pf.created_at DESC
  LIMIT 500;
$$;
CREATE FUNCTION public.cxp_umbral_sin_vinculo(p_org uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT COALESCE((
    SELECT CASE
             WHEN NULLIF(c.valor #>> '{}', '') ~ '^[0-9]+(\.[0-9]+)?$'
               THEN (c.valor #>> '{}')::numeric
             ELSE NULL
           END
    FROM public.configuracion c
    WHERE c.organization_id = p_org
      AND c.categoria = 'compras'
      AND c.clave = 'umbral_aprobacion_sin_vinculo'
    LIMIT 1
  ), 50000)::numeric;
$_$;
CREATE FUNCTION public.cxp_umbral_sin_vinculo_actual() RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.cxp_umbral_sin_vinculo(public.current_user_org_id());
$$;
CREATE FUNCTION public.dashboard_details() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_out jsonb;
BEGIN
  v_out := public.dashboard_details_datos();
  IF NOT public.puede_ver_costos_dashboard(auth.uid()) THEN
    v_out := public.enmascarar_costos_jsonb(v_out);
  END IF;
  RETURN v_out;
END;
$$;
CREATE FUNCTION public.dashboard_details_datos() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  -- Ola 17 · H8-A: el servidor corre en UTC; el tablero debe razonar en hora
  -- de México o los días de demora se adelantan a partir de las 18:00 CDMX.
  v_hoy date := (now() AT TIME ZONE 'America/Mexico_City')::date;
  v_inicio_mes date := date_trunc('month', v_hoy)::date;
  v_fin_mes date := (date_trunc('month', v_hoy) + interval '1 month' - interval '1 day')::date;
  v_inicio_sig date := (date_trunc('month', v_hoy) + interval '1 month')::date;
  v_fin_sig date := (date_trunc('month', v_hoy) + interval '2 months' - interval '1 day')::date;
  -- Fallback SÓLO cuando la naviera no tiene condiciones capturadas.
  v_dias_libres_fallback int := 7;
  v_nombre_mes text;
  v_meses text[] := ARRAY['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
BEGIN
  v_nombre_mes := v_meses[extract(month from v_inicio_sig)::int] || ' ' || extract(year from v_inicio_sig)::text;
  RETURN (
    WITH embarques_base AS (
      SELECT e.id, e.expediente, e.cliente_nombre, e.cliente_id, e.modo::text, e.tipo::text,
             e.estado::text, e.etd, e.eta, e.operador,
             e.puerto_origen, e.puerto_destino,
             e.aeropuerto_origen, e.aeropuerto_destino,
             e.ciudad_origen, e.ciudad_destino, e.contenedor, e.created_at,
             e.naviera, e.organization_id,
             e.tipo_cambio_usd, e.tipo_cambio_eur,
        CASE
          -- Ola 4 · N10 (guard B-033): preservar Borrador.
          WHEN e.estado = 'Borrador' THEN 'Borrador'
          WHEN e.estado IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado') THEN e.estado::text
          WHEN e.modo = 'Marítimo' AND e.tipo = 'Importación' AND e.etd IS NOT NULL AND e.eta IS NOT NULL THEN
            CASE
              WHEN v_hoy < e.etd THEN 'Confirmado'
              WHEN v_hoy >= e.etd AND v_hoy < e.eta THEN 'En Tránsito'
              WHEN v_hoy >= e.eta THEN 'Arribo'
              ELSE e.estado::text
            END
          ELSE e.estado::text
        END AS estado_real
      FROM embarques e
      WHERE e.deleted_at IS NULL              -- FIX C5
        AND (e.organization_id = public.org_scope())
    ),
    profit AS (SELECT * FROM profit_por_embarque()),
    -- Ola 4 · N10 (B-033): Borrador ya no cuenta como activo operativo.
    activos AS (SELECT * FROM embarques_base WHERE estado_real NOT IN ('Borrador','EIR','Por liquidar','Cerrado','Cancelado')),
    -- Ola 17 · H8-A: los días de demora se calculan con la MISMA base que
    -- factura calcular_demoras_embarque: fecha real de descarga (evento o
    -- contenedor) y días libres reales (override del contenedor → condiciones
    -- de la naviera → fallback). La ETA sólo se usa como estimación.
    demoras_ctx AS (
      SELECT a.id,
        (SELECT min((ev.fecha AT TIME ZONE 'America/Mexico_City')::date)
           FROM eventos_embarque ev
          WHERE ev.embarque_id = a.id AND ev.tipo = 'Descarga' AND ev.deleted_at IS NULL) AS fecha_desc_evento,
        (SELECT min(ec.fecha_descarga)
           FROM embarque_contenedores ec
          WHERE ec.embarque_id = a.id AND ec.deleted_at IS NULL) AS fecha_desc_cont,
        (SELECT max(ec.dias_libres_override)
           FROM embarque_contenedores ec
          WHERE ec.embarque_id = a.id AND ec.deleted_at IS NULL
            AND ec.dias_libres_override IS NOT NULL) AS dias_libres_cont,
        (SELECT cnc.dias_libres_demoras_default
           FROM costeo_navieras_condiciones cnc
           JOIN navieras n ON n.id = cnc.naviera_id
          WHERE cnc.organization_id = a.organization_id
            AND a.naviera IS NOT NULL
            AND lower(n.name) = lower(a.naviera)
          LIMIT 1) AS dias_libres_naviera
      FROM activos a
      WHERE a.estado_real = 'Arribo'
    ),
    demoras_calc AS (
      SELECT a.*,
        COALESCE(c.fecha_desc_evento, c.fecha_desc_cont, a.eta) AS fecha_base,
        (c.fecha_desc_evento IS NOT NULL OR c.fecha_desc_cont IS NOT NULL) AS base_real,
        COALESCE(c.dias_libres_cont, c.dias_libres_naviera, v_dias_libres_fallback) AS dias_libres
      FROM activos a
      JOIN demoras_ctx c ON c.id = a.id
    ),
    alertas_src AS (
      SELECT d.* FROM demoras_calc d
      WHERE d.fecha_base IS NOT NULL AND (v_hoy - d.fecha_base) >= d.dias_libres
      ORDER BY ((v_hoy - d.fecha_base) - d.dias_libres) DESC LIMIT 15
    ),
    alertas AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'expediente', a.expediente, 'cliente_nombre', a.cliente_nombre,
        'modo', a.modo, 'tipo', a.tipo, 'estado', a.estado, 'estadoReal', a.estado_real,
        'etd', a.etd, 'eta', a.eta, 'operador', a.operador,
        'puerto_origen', a.puerto_origen, 'puerto_destino', a.puerto_destino,
        'aeropuerto_origen', a.aeropuerto_origen, 'aeropuerto_destino', a.aeropuerto_destino,
        'ciudad_origen', a.ciudad_origen, 'ciudad_destino', a.ciudad_destino,
        'contenedor', a.contenedor, 'created_at', a.created_at,
        'diasDesdeEta', COALESCE(v_hoy - a.eta, 0),
        'diasLibres', a.dias_libres,
        'baseDemora', CASE WHEN a.base_real THEN 'real' ELSE 'estimada' END,
        'fechaBaseDemora', a.fecha_base,
        'diasDemora', (v_hoy - a.fecha_base) - a.dias_libres
      )) AS val FROM alertas_src a
    ),
    proximos_src AS (
      SELECT a.* FROM activos a
      WHERE a.estado_real = 'En Tránsito' AND a.eta IS NOT NULL
        AND (a.eta - v_hoy) >= 0 AND (a.eta - v_hoy) <= 7
      ORDER BY (a.eta - v_hoy) ASC LIMIT 15
    ),
    proximos AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'expediente', a.expediente, 'cliente_nombre', a.cliente_nombre,
        'modo', a.modo, 'tipo', a.tipo, 'estado', a.estado, 'estadoReal', a.estado_real,
        'etd', a.etd, 'eta', a.eta, 'operador', a.operador,
        'puerto_origen', a.puerto_origen, 'puerto_destino', a.puerto_destino,
        'aeropuerto_origen', a.aeropuerto_origen, 'aeropuerto_destino', a.aeropuerto_destino,
        'ciudad_origen', a.ciudad_origen, 'ciudad_destino', a.ciudad_destino,
        'contenedor', a.contenedor, 'created_at', a.created_at,
        'diasRestantes', (a.eta - v_hoy)
      )) AS val FROM proximos_src a
    ),
    profit_este_mes_src AS (
      SELECT eb.*, p.venta_usd, p.costo_usd, p.venta_mxn, p.costo_mxn,
             p.venta_mxn_from_usd, p.costo_mxn_from_usd,
             p.venta_mxn_from_eur, p.costo_mxn_from_eur,
             p.venta_mxn_native, p.costo_mxn_native
      FROM activos eb LEFT JOIN profit p ON p.embarque_id = eb.id
      WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_mes AND eb.eta <= v_fin_mes
        AND (COALESCE(p.venta_mxn, 0) > 0 OR COALESCE(p.costo_mxn, 0) > 0)
      ORDER BY (COALESCE(p.venta_mxn, 0) - COALESCE(p.costo_mxn, 0)) DESC LIMIT 30
    ),
    profit_este_mes AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', eb.id, 'expediente', eb.expediente, 'cliente_nombre', eb.cliente_nombre,
        'modo', eb.modo, 'tipo', eb.tipo, 'estado', eb.estado, 'estadoReal', eb.estado_real,
        'etd', eb.etd, 'eta', eb.eta, 'operador', eb.operador,
        'puerto_origen', eb.puerto_origen, 'puerto_destino', eb.puerto_destino,
        'aeropuerto_origen', eb.aeropuerto_origen, 'aeropuerto_destino', eb.aeropuerto_destino,
        'ciudad_origen', eb.ciudad_origen, 'ciudad_destino', eb.ciudad_destino,
        'contenedor', eb.contenedor, 'created_at', eb.created_at,
        'tipoCambioUSD', eb.tipo_cambio_usd, 'tipoCambioEUR', eb.tipo_cambio_eur,
        'ventaUSD', COALESCE(eb.venta_usd, 0),
        'costoUSD', COALESCE(eb.costo_usd, 0),
        'ventaMXN', COALESCE(eb.venta_mxn, 0),
        'costoMXN', COALESCE(eb.costo_mxn, 0),
        'profitMXN', COALESCE(eb.venta_mxn, 0) - COALESCE(eb.costo_mxn, 0),
        'margenMXN', CASE WHEN COALESCE(eb.venta_mxn, 0) > 0
                          THEN ((COALESCE(eb.venta_mxn, 0) - COALESCE(eb.costo_mxn, 0)) / eb.venta_mxn) * 100
                          ELSE 0 END,
        'ventaMxnFromUsd', COALESCE(eb.venta_mxn_from_usd, 0),
        'costoMxnFromUsd', COALESCE(eb.costo_mxn_from_usd, 0),
        'ventaMxnFromEur', COALESCE(eb.venta_mxn_from_eur, 0),
        'costoMxnFromEur', COALESCE(eb.costo_mxn_from_eur, 0),
        'ventaMxnNative', COALESCE(eb.venta_mxn_native, 0),
        'costoMxnNative', COALESCE(eb.costo_mxn_native, 0),
        'profit', COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0),
        'margen', CASE WHEN COALESCE(eb.venta_usd, 0) > 0
                       THEN ((COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0)) / eb.venta_usd) * 100
                       ELSE 0 END
      )) AS val FROM profit_este_mes_src eb
    ),
    mes_sig_src AS (
      SELECT eb.*, p.venta_usd, p.costo_usd, p.venta_mxn, p.costo_mxn,
             p.venta_mxn_from_usd, p.costo_mxn_from_usd,
             p.venta_mxn_from_eur, p.costo_mxn_from_eur,
             p.venta_mxn_native, p.costo_mxn_native,
             EXISTS (
               SELECT 1 FROM facturas f
               WHERE f.embarque_id = eb.id
                 AND f.deleted_at IS NULL     -- FIX C5
                 -- Ola 5 · RG4-2 (N45): 'Sustituida' ya no es CFDI vigente;
                 -- excluirla del flag "facturado" (la definición vigente
                 -- sólo excluía Cancelada/Borrador).
                 AND f.estado::text NOT IN ('Cancelada','Borrador','Sustituida')
             ) AS facturado_flag
      FROM activos eb LEFT JOIN profit p ON p.embarque_id = eb.id
      WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_sig AND eb.eta <= v_fin_sig
      ORDER BY eb.eta ASC LIMIT 30
    ),
    mes_sig AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', eb.id, 'expediente', eb.expediente, 'cliente_nombre', eb.cliente_nombre,
        'modo', eb.modo, 'tipo', eb.tipo, 'estado', eb.estado, 'estadoReal', eb.estado_real,
        'etd', eb.etd, 'eta', eb.eta, 'operador', eb.operador,
        'puerto_origen', eb.puerto_origen, 'puerto_destino', eb.puerto_destino,
        'aeropuerto_origen', eb.aeropuerto_origen, 'aeropuerto_destino', eb.aeropuerto_destino,
        'ciudad_origen', eb.ciudad_origen, 'ciudad_destino', eb.ciudad_destino,
        'contenedor', eb.contenedor, 'created_at', eb.created_at,
        'tipoCambioUSD', eb.tipo_cambio_usd, 'tipoCambioEUR', eb.tipo_cambio_eur,
        'ventaUSD', COALESCE(eb.venta_usd, 0),
        'costoUSD', COALESCE(eb.costo_usd, 0),
        'ventaMXN', COALESCE(eb.venta_mxn, 0),
        'costoMXN', COALESCE(eb.costo_mxn, 0),
        'profitMXN', COALESCE(eb.venta_mxn, 0) - COALESCE(eb.costo_mxn, 0),
        'margenMXN', CASE WHEN COALESCE(eb.venta_mxn, 0) > 0
                          THEN ((COALESCE(eb.venta_mxn, 0) - COALESCE(eb.costo_mxn, 0)) / eb.venta_mxn) * 100
                          ELSE 0 END,
        'ventaMxnFromUsd', COALESCE(eb.venta_mxn_from_usd, 0),
        'costoMxnFromUsd', COALESCE(eb.costo_mxn_from_usd, 0),
        'ventaMxnFromEur', COALESCE(eb.venta_mxn_from_eur, 0),
        'costoMxnFromEur', COALESCE(eb.costo_mxn_from_eur, 0),
        'ventaMxnNative', COALESCE(eb.venta_mxn_native, 0),
        'costoMxnNative', COALESCE(eb.costo_mxn_native, 0),
        'profit', COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0),
        'margen', CASE WHEN COALESCE(eb.venta_usd, 0) > 0
                       THEN ((COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0)) / eb.venta_usd) * 100
                       ELSE 0 END,
        'facturado', eb.facturado_flag
      )) AS val FROM mes_sig_src eb
    ),
    mes_sig_resumen AS (
      SELECT jsonb_build_object(
        'totalEmbarques', count(*),
        'ventaUSD', COALESCE(sum(COALESCE(venta_usd, 0)), 0),
        'costoUSD', COALESCE(sum(COALESCE(costo_usd, 0)), 0),
        'profitUSD', COALESCE(sum(COALESCE(venta_usd, 0) - COALESCE(costo_usd, 0)), 0),
        'ventaMXN', COALESCE(sum(COALESCE(venta_mxn, 0)), 0),
        'costoMXN', COALESCE(sum(COALESCE(costo_mxn, 0)), 0),
        'profitMXN', COALESCE(sum(COALESCE(venta_mxn, 0) - COALESCE(costo_mxn, 0)), 0),
        'facturados', count(*) FILTER (WHERE facturado_flag),
        'nombreMes', v_nombre_mes
      ) AS val FROM mes_sig_src
    ),
    cargas_cliente AS (
      SELECT jsonb_agg(x ORDER BY (x->>'total')::int DESC) AS val
      FROM (
        SELECT jsonb_build_object(
          'clienteId', cliente_id,
          'clienteNombre', cliente_nombre,
          'total', count(*),
          'desglose', jsonb_build_object(
            'Confirmado',   count(*) FILTER (WHERE estado_real = 'Confirmado'),
            'En Tránsito',  count(*) FILTER (WHERE estado_real = 'En Tránsito'),
            'Arribo',       count(*) FILTER (WHERE estado_real = 'Arribo'),
            'En Aduana',    count(*) FILTER (WHERE estado_real = 'En Aduana'),
            'Entregado',    count(*) FILTER (WHERE estado_real = 'Entregado')
          )
        ) AS x
        FROM activos WHERE cliente_id IS NOT NULL
        GROUP BY cliente_id, cliente_nombre
        ORDER BY count(*) DESC LIMIT 10
      ) sub
    ),
    cargas_total AS (
      SELECT count(*) FILTER (
        WHERE cliente_id IS NOT NULL
          AND estado_real IN ('Confirmado','En Tránsito','Arribo','En Aduana','Entregado')
      )::int AS val
      FROM activos
    ),
    -- v13.303.13 · Listado ligero de EIR para el scope "mis embarques" del chip EIR.
    embarques_eir AS (
      SELECT jsonb_agg(jsonb_build_object(
        'id', eb.id,
        'operador', eb.operador,
        'estadoReal', eb.estado_real
      )) AS val
      FROM (
        SELECT id, operador, estado_real, created_at
        FROM embarques_base
        WHERE estado_real IN ('EIR','Por liquidar')
        ORDER BY created_at DESC
        LIMIT 500
      ) eb
    )
    SELECT jsonb_build_object(
      'alertasDemora', COALESCE((SELECT val FROM alertas), '[]'::jsonb),
      'proximosArribos', COALESCE((SELECT val FROM proximos), '[]'::jsonb),
      'profitArribosEsteMes', COALESCE((SELECT val FROM profit_este_mes), '[]'::jsonb),
      'embarquesMesSiguiente', COALESCE((SELECT val FROM mes_sig), '[]'::jsonb),
      'resumenMesSiguiente', COALESCE((SELECT val FROM mes_sig_resumen), jsonb_build_object(
        'totalEmbarques', 0, 'ventaUSD', 0, 'costoUSD', 0, 'profitUSD', 0,
        'ventaMXN', 0, 'costoMXN', 0, 'profitMXN', 0,
        'facturados', 0, 'nombreMes', v_nombre_mes
      )),
      'cargasPorCliente', COALESCE((SELECT val FROM cargas_cliente), '[]'::jsonb),
      'cargasActivasTotal', COALESCE((SELECT val FROM cargas_total), 0),
      'embarquesEir', COALESCE((SELECT val FROM embarques_eir), '[]'::jsonb)
    )
  );
END;
$$;
CREATE FUNCTION public.dashboard_facturacion_kpis(p_meses integer DEFAULT 6, p_fallback_usd numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hoy date := (now() AT TIME ZONE 'America/Mexico_City')::date;
  v_desde date := (date_trunc('month', v_hoy) - make_interval(months => GREATEST(p_meses, 1) - 1))::date;
  v_result jsonb;
BEGIN
  WITH meses AS (
    SELECT generate_series(v_desde, date_trunc('month', v_hoy)::date, '1 month'::interval)::date AS inicio
  ),
  fact AS (
    SELECT
      date_trunc('month', f.fecha_emision)::date AS mes,
      CASE
        WHEN f.moneda = 'MXN' THEN f.total
        WHEN f.tipo_cambio IS NOT NULL AND f.tipo_cambio > 1 THEN f.total * f.tipo_cambio
        WHEN f.moneda = 'USD' AND p_fallback_usd IS NOT NULL AND p_fallback_usd > 0 THEN f.total * p_fallback_usd
        ELSE NULL
      END AS total_mxn,
      (
        f.moneda <> 'MXN'
        AND NOT (f.tipo_cambio IS NOT NULL AND f.tipo_cambio > 1)
        AND NOT (f.moneda = 'USD' AND p_fallback_usd IS NOT NULL AND p_fallback_usd > 0)
      ) AS sin_tc
    FROM facturas f
    WHERE f.deleted_at IS NULL
      AND f.estado IN ('Emitida', 'Parcialmente pagada', 'Vencida', 'Pagada')
      AND f.fecha_emision >= v_desde
      AND f.organization_id = public.org_scope()
  ),
  fact_mes AS (
    SELECT mes, SUM(total_mxn) AS facturado_mxn FROM fact WHERE total_mxn IS NOT NULL GROUP BY mes
  ),
  pagos AS (
    SELECT
      date_trunc('month', pf.fecha_pago)::date AS mes,
      CASE
        WHEN f.moneda = 'MXN' THEN pf.monto_aplicado_factura
        WHEN f.tipo_cambio IS NOT NULL AND f.tipo_cambio > 1 THEN pf.monto_aplicado_factura * f.tipo_cambio
        WHEN f.moneda = 'USD' AND p_fallback_usd IS NOT NULL AND p_fallback_usd > 0 THEN pf.monto_aplicado_factura * p_fallback_usd
        ELSE NULL
      END AS cobrado_mxn
    FROM pagos_factura pf
    JOIN facturas f ON f.id = pf.factura_id
    WHERE pf.deleted_at IS NULL
      AND f.deleted_at IS NULL
      AND pf.fecha_pago >= v_desde
      AND pf.organization_id = public.org_scope()
  ),
  pagos_mes AS (
    SELECT mes, SUM(cobrado_mxn) AS cobrado_mxn FROM pagos WHERE cobrado_mxn IS NOT NULL GROUP BY mes
  )
  SELECT jsonb_build_object(
    'tendencia', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'mes', to_char(m.inicio, 'YYYY-MM'),
        'facturado_mxn', COALESCE(fm.facturado_mxn, 0),
        'cobrado_mxn', COALESCE(pm.cobrado_mxn, 0)
      ) ORDER BY m.inicio)
      FROM meses m
      LEFT JOIN fact_mes fm ON fm.mes = m.inicio
      LEFT JOIN pagos_mes pm ON pm.mes = m.inicio
    ), '[]'::jsonb),
    'facturas_sin_tc', COALESCE((
      SELECT COUNT(*) FROM fact
      WHERE sin_tc AND mes = date_trunc('month', v_hoy)::date
    ), 0)
  ) INTO v_result;
  RETURN v_result;
END;
$$;
CREATE FUNCTION public.dashboard_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  v_hoy date := current_date;
  v_inicio_mes date := date_trunc('month', v_hoy)::date;
  v_fin_mes date := (date_trunc('month', v_hoy) + interval '1 month' - interval '1 day')::date;
  v_inicio_sig date := (date_trunc('month', v_hoy) + interval '1 month')::date;
  v_fin_sig date := (date_trunc('month', v_hoy) + interval '2 months' - interval '1 day')::date;
  v_dias_libres int := 7;
BEGIN
  WITH embarques_base AS (
    SELECT e.id, e.expediente, e.cliente_nombre, e.cliente_id, e.modo::text, e.tipo::text,
           e.estado::text, e.etd, e.eta, e.operador,
           e.puerto_origen, e.puerto_destino,
           e.aeropuerto_origen, e.aeropuerto_destino,
           e.ciudad_origen, e.ciudad_destino, e.contenedor, e.created_at,
      CASE
        -- B-033 (v13.320.42): preservar Borrador para que no se cuente como Confirmado.
        WHEN e.estado = 'Borrador' THEN 'Borrador'
        WHEN e.estado IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado') THEN e.estado::text
        WHEN e.modo = 'Marítimo' AND e.tipo = 'Importación' AND e.etd IS NOT NULL AND e.eta IS NOT NULL THEN
          CASE
            WHEN v_hoy < e.etd THEN 'Confirmado'
            WHEN v_hoy >= e.etd AND v_hoy < e.eta THEN 'En Tránsito'
            WHEN v_hoy >= e.eta THEN 'Arribo'
            ELSE e.estado::text
          END
        ELSE e.estado::text
      END AS estado_real
    FROM embarques e
    WHERE (e.organization_id = public.org_scope())
      AND e.deleted_at IS NULL
  ),
  profit AS (
    SELECT p.embarque_id, p.venta_usd, p.costo_usd
    FROM profit_por_embarque() p
  ),
  activos AS (
    SELECT * FROM embarques_base
    -- B-033: Borrador ya no cuenta como activo operativo.
    WHERE estado_real NOT IN ('Borrador','EIR','Por liquidar','Cerrado','Cancelado')
  ),
  conteo AS (
    SELECT jsonb_build_object(
      'Confirmado', count(*) FILTER (WHERE estado_real = 'Confirmado'),
      'En Tránsito', count(*) FILTER (WHERE estado_real = 'En Tránsito'),
      'Arribo', count(*) FILTER (WHERE estado_real = 'Arribo'),
      'En Aduana', count(*) FILTER (WHERE estado_real = 'En Aduana'),
      'Entregado', count(*) FILTER (WHERE estado_real = 'Entregado')
    ) AS val
    FROM activos
  ),
  alertas_src AS (
    SELECT a.* FROM activos a
    WHERE a.estado_real = 'Arribo' AND a.eta IS NOT NULL AND (v_hoy - a.eta) >= v_dias_libres
    ORDER BY (v_hoy - a.eta) DESC
    LIMIT 15
  ),
  alertas AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', a.id, 'expediente', a.expediente, 'cliente_nombre', a.cliente_nombre,
        'modo', a.modo, 'tipo', a.tipo, 'estado', a.estado, 'estadoReal', a.estado_real,
        'etd', a.etd, 'eta', a.eta, 'operador', a.operador,
        'puerto_origen', a.puerto_origen, 'puerto_destino', a.puerto_destino,
        'aeropuerto_origen', a.aeropuerto_origen, 'aeropuerto_destino', a.aeropuerto_destino,
        'ciudad_origen', a.ciudad_origen, 'ciudad_destino', a.ciudad_destino,
        'contenedor', a.contenedor, 'created_at', a.created_at,
        'diasDesdeEta', (v_hoy - a.eta),
        'diasDemora', (v_hoy - a.eta) - v_dias_libres
      )
    ) AS val
    FROM alertas_src a
  ),
  proximos_src AS (
    SELECT a.* FROM activos a
    WHERE a.estado_real = 'En Tránsito' AND a.eta IS NOT NULL
      AND (a.eta - v_hoy) >= 0 AND (a.eta - v_hoy) <= 7
    ORDER BY (a.eta - v_hoy) ASC
    LIMIT 15
  ),
  proximos AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', a.id, 'expediente', a.expediente, 'cliente_nombre', a.cliente_nombre,
        'modo', a.modo, 'tipo', a.tipo, 'estado', a.estado, 'estadoReal', a.estado_real,
        'etd', a.etd, 'eta', a.eta, 'operador', a.operador,
        'puerto_origen', a.puerto_origen, 'puerto_destino', a.puerto_destino,
        'aeropuerto_origen', a.aeropuerto_origen, 'aeropuerto_destino', a.aeropuerto_destino,
        'ciudad_origen', a.ciudad_origen, 'ciudad_destino', a.ciudad_destino,
        'contenedor', a.contenedor, 'created_at', a.created_at,
        'diasRestantes', (a.eta - v_hoy)
      )
    ) AS val
    FROM proximos_src a
  ),
  profit_este_mes_src AS (
    SELECT eb.*, p.venta_usd, p.costo_usd
    FROM activos eb
    LEFT JOIN profit p ON p.embarque_id = eb.id
    WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_mes AND eb.eta <= v_fin_mes
      AND (COALESCE(p.venta_usd, 0) > 0 OR COALESCE(p.costo_usd, 0) > 0)
    ORDER BY (COALESCE(p.venta_usd, 0) - COALESCE(p.costo_usd, 0)) DESC
    LIMIT 30
  ),
  profit_este_mes AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', eb.id, 'expediente', eb.expediente, 'cliente_nombre', eb.cliente_nombre,
        'modo', eb.modo, 'tipo', eb.tipo, 'estado', eb.estado, 'estadoReal', eb.estado_real,
        'etd', eb.etd, 'eta', eb.eta, 'operador', eb.operador,
        'puerto_origen', eb.puerto_origen, 'puerto_destino', eb.puerto_destino,
        'aeropuerto_origen', eb.aeropuerto_origen, 'aeropuerto_destino', eb.aeropuerto_destino,
        'ciudad_origen', eb.ciudad_origen, 'ciudad_destino', eb.ciudad_destino,
        'contenedor', eb.contenedor, 'created_at', eb.created_at,
        'ventaUSD', COALESCE(eb.venta_usd, 0),
        'costoUSD', COALESCE(eb.costo_usd, 0),
        'profit', COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0),
        'margen', CASE WHEN COALESCE(eb.venta_usd, 0) > 0
          THEN round(((COALESCE(eb.venta_usd, 0) - COALESCE(eb.costo_usd, 0)) / eb.venta_usd * 100)::numeric, 1)
          ELSE 0 END
      )
    ) AS val
    FROM profit_este_mes_src eb
  ),
  arribos_mes AS (
    SELECT jsonb_build_object(
      'total', count(*),
      'yaLlegaron', count(*) FILTER (WHERE eb.estado_real IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado')),
      'enCamino', count(*) FILTER (WHERE eb.estado_real IN ('Confirmado','En Tránsito')),
      'profitUSD', COALESCE(sum(COALESCE(p.venta_usd, 0) - COALESCE(p.costo_usd, 0)), 0)
    ) AS val
    FROM embarques_base eb
    LEFT JOIN profit p ON p.embarque_id = eb.id
    WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_mes AND eb.eta <= v_fin_mes
      AND eb.estado_real <> 'Borrador'
  ),
  mes_sig_src AS (
    SELECT eb.*, p.venta_usd, p.costo_usd
    FROM activos eb
    LEFT JOIN profit p ON p.embarque_id = eb.id
    WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_sig AND eb.eta <= v_fin_sig
    ORDER BY eb.eta ASC
    LIMIT 30
  ),
  mes_sig AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', eb.id, 'expediente', eb.expediente, 'cliente_nombre', eb.cliente_nombre,
        'modo', eb.modo, 'tipo', eb.tipo, 'estado', eb.estado, 'estadoReal', eb.estado_real,
        'etd', eb.etd, 'eta', eb.eta, 'operador', eb.operador,
        'puerto_origen', eb.puerto_origen, 'puerto_destino', eb.puerto_destino,
        'aeropuerto_origen', eb.aeropuerto_origen, 'aeropuerto_destino', eb.aeropuerto_destino,
        'ciudad_origen', eb.ciudad_origen, 'ciudad_destino', eb.ciudad_destino,
        'contenedor', eb.contenedor, 'created_at', eb.created_at,
        'ventaUSD', COALESCE(eb.venta_usd, 0),
        'costoUSD', COALESCE(eb.costo_usd, 0)
      )
    ) AS val
    FROM mes_sig_src eb
  ),
  resumen_sig AS (
    SELECT jsonb_build_object(
      'total', count(*),
      'ventaUSD', COALESCE(sum(COALESCE(p.venta_usd, 0)), 0),
      'costoUSD', COALESCE(sum(COALESCE(p.costo_usd, 0)), 0)
    ) AS val
    FROM activos eb
    LEFT JOIN profit p ON p.embarque_id = eb.id
    WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_sig AND eb.eta <= v_fin_sig
  ),
  cargas_cliente AS (
    SELECT jsonb_agg(x ORDER BY (x->>'total')::int DESC) AS val
    FROM (
      SELECT jsonb_build_object(
        'clienteId', cliente_id,
        'clienteNombre', cliente_nombre,
        'total', count(*),
        'desglose', jsonb_build_object(
          'Confirmado', count(*) FILTER (WHERE estado_real = 'Confirmado'),
          'En Tránsito', count(*) FILTER (WHERE estado_real = 'En Tránsito'),
          'Arribo', count(*) FILTER (WHERE estado_real = 'Arribo'),
          'En Aduana', count(*) FILTER (WHERE estado_real = 'En Aduana'),
          'Entregado', count(*) FILTER (WHERE estado_real = 'Entregado')
        )
      ) AS x
      FROM activos
      WHERE cliente_id IS NOT NULL
      GROUP BY cliente_id, cliente_nombre
      ORDER BY count(*) DESC
      LIMIT 10
    ) sub
  )
  SELECT jsonb_build_object(
    'totalActivos', (SELECT count(*) FROM activos),
    'conteoPorEstado', COALESCE((SELECT val FROM conteo), '{}'::jsonb),
    'alertasDemora', COALESCE((SELECT val FROM alertas), '[]'::jsonb),
    'proximosArribos', COALESCE((SELECT val FROM proximos), '[]'::jsonb),
    'profitArribosEsteMes', COALESCE((SELECT val FROM profit_este_mes), '[]'::jsonb),
    'arribosEsteMes', COALESCE((SELECT val FROM arribos_mes), '{}'::jsonb),
    'embarquesMesSiguiente', COALESCE((SELECT val FROM mes_sig), '[]'::jsonb),
    'resumenMesSiguiente', COALESCE((SELECT val FROM resumen_sig), '{}'::jsonb),
    'cargasPorCliente', COALESCE((SELECT val FROM cargas_cliente), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;
CREATE FUNCTION public.dashboard_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_out jsonb;
BEGIN
  v_out := public.dashboard_summary_datos();
  IF NOT public.puede_ver_costos_dashboard(auth.uid()) THEN
    v_out := public.enmascarar_costos_jsonb(v_out);
  END IF;
  RETURN v_out;
END;
$$;
CREATE FUNCTION public.dashboard_summary_datos() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hoy date := current_date;
  v_inicio_mes date := date_trunc('month', v_hoy)::date;
  v_fin_mes date := (date_trunc('month', v_hoy) + interval '1 month' - interval '1 day')::date;
  v_inicio_sig date := (date_trunc('month', v_hoy) + interval '1 month')::date;
  v_fin_sig date := (date_trunc('month', v_hoy) + interval '2 months' - interval '1 day')::date;
BEGIN
  RETURN (
    WITH embarques_base AS (
      SELECT e.id, e.estado::text, e.modo, e.tipo, e.etd, e.eta,
        e.tipo_cambio_eur,
        CASE
          WHEN e.estado = 'Borrador' THEN 'Borrador'
          WHEN e.estado IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado') THEN e.estado::text
          WHEN e.modo = 'Marítimo' AND e.tipo = 'Importación' AND e.etd IS NOT NULL AND e.eta IS NOT NULL THEN
            CASE
              WHEN v_hoy < e.etd THEN 'Confirmado'
              WHEN v_hoy >= e.etd AND v_hoy < e.eta THEN 'En Tránsito'
              WHEN v_hoy >= e.eta THEN 'Arribo'
              ELSE e.estado::text
            END
          ELSE e.estado::text
        END AS estado_real
      FROM embarques e
      WHERE e.deleted_at IS NULL
        AND (e.organization_id = public.org_scope())
    ),
    profit AS (SELECT * FROM profit_por_embarque()),
    activos AS (SELECT * FROM embarques_base WHERE estado_real NOT IN ('Borrador','EIR','Por liquidar','Cerrado','Cancelado')),
    conteo AS (
      SELECT jsonb_build_object(
        'Confirmado', count(*) FILTER (WHERE estado_real = 'Confirmado'),
        'En Tránsito', count(*) FILTER (WHERE estado_real = 'En Tránsito'),
        'Arribo', count(*) FILTER (WHERE estado_real = 'Arribo'),
        'En Aduana', count(*) FILTER (WHERE estado_real = 'En Aduana'),
        'Entregado', count(*) FILTER (WHERE estado_real = 'Entregado'),
        'EIR', count(*) FILTER (WHERE estado_real = 'EIR'),
        'Por liquidar', count(*) FILTER (WHERE estado_real = 'Por liquidar')
      ) AS val
      FROM embarques_base
    ),
    gastos_op_facturas AS (
      -- FIX BL-11: EUR usa el TC del embarque ligado y, si no hay, el TC DOF
      -- vigente a fecha_emision (LEFT JOIN LATERAL sobre tipos_cambio_dof).
      SELECT COALESCE(SUM(
        CASE
          WHEN pf.moneda = 'MXN' THEN pf.total
          WHEN pf.moneda = 'USD' AND pf.tipo_cambio_usd > 1 THEN pf.total * pf.tipo_cambio_usd
          WHEN pf.moneda = 'EUR' AND COALESCE(eb.tipo_cambio_eur, dof.eur_mxn) > 1
               THEN pf.total * COALESCE(eb.tipo_cambio_eur, dof.eur_mxn)
          ELSE NULL
        END
      ), 0) AS val
      FROM proveedor_facturas pf
      JOIN presupuesto_categorias pc ON pc.id = pf.categoria_presupuesto_id
      LEFT JOIN embarques_base eb ON eb.id = pf.embarque_id
      LEFT JOIN LATERAL (
        SELECT d.eur_mxn
          FROM public.tipos_cambio_dof d
         WHERE d.fecha <= pf.fecha_emision
         ORDER BY d.fecha DESC
         LIMIT 1
      ) dof ON pf.moneda = 'EUR' AND eb.tipo_cambio_eur IS NULL
      WHERE pc.tipo_contable IN ('Venta','Administracion')
        AND pf.deleted_at IS NULL
        AND pf.fecha_emision BETWEEN v_inicio_mes AND v_fin_mes
        AND (pf.organization_id = public.org_scope())
    ),
    gastos_op_sin_tc AS (
      -- FIX BL-11: mismo fallback DOF — una factura EUR con TC DOF disponible ya
      -- no cuenta como "sin TC".
      SELECT COUNT(*) AS val
      FROM proveedor_facturas pf
      JOIN presupuesto_categorias pc ON pc.id = pf.categoria_presupuesto_id
      LEFT JOIN embarques_base eb ON eb.id = pf.embarque_id
      LEFT JOIN LATERAL (
        SELECT d.eur_mxn
          FROM public.tipos_cambio_dof d
         WHERE d.fecha <= pf.fecha_emision
         ORDER BY d.fecha DESC
         LIMIT 1
      ) dof ON pf.moneda = 'EUR' AND eb.tipo_cambio_eur IS NULL
      WHERE pc.tipo_contable IN ('Venta','Administracion')
        AND pf.deleted_at IS NULL
        AND pf.fecha_emision BETWEEN v_inicio_mes AND v_fin_mes
        AND (pf.organization_id = public.org_scope())
        AND pf.moneda <> 'MXN'
        AND NOT (pf.moneda = 'USD' AND pf.tipo_cambio_usd > 1)
        AND NOT (pf.moneda = 'EUR' AND COALESCE(eb.tipo_cambio_eur, dof.eur_mxn, 0) > 1)
    ),
    gastos_op_comisiones AS (
      SELECT COALESCE(SUM(total_mxn), 0) AS val
      FROM liquidaciones_comision
      WHERE periodo = to_char(v_inicio_mes, 'YYYY-MM')
        AND (organization_id = public.org_scope())
    ),
    arribos_mes AS (
      SELECT jsonb_build_object(
        'total', count(*),
        'yaLlegaron', count(*) FILTER (WHERE eb.estado_real IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado')),
        'enCamino', count(*) FILTER (WHERE eb.estado_real IN ('Confirmado','En Tránsito')),
        'ventaMXN', COALESCE(sum(COALESCE(p.venta_mxn, 0)), 0),
        'costoMXN', COALESCE(sum(COALESCE(p.costo_mxn, 0)), 0),
        'profitMXN', COALESCE(sum(COALESCE(p.venta_mxn, 0) - COALESCE(p.costo_mxn, 0)), 0),
        'ventaMxnFromUsd', COALESCE(sum(COALESCE(p.venta_mxn_from_usd, 0)), 0),
        'costoMxnFromUsd', COALESCE(sum(COALESCE(p.costo_mxn_from_usd, 0)), 0),
        'ventaMxnFromEur', COALESCE(sum(COALESCE(p.venta_mxn_from_eur, 0)), 0),
        'costoMxnFromEur', COALESCE(sum(COALESCE(p.costo_mxn_from_eur, 0)), 0),
        'ventaMxnNative', COALESCE(sum(COALESCE(p.venta_mxn_native, 0)), 0),
        'costoMxnNative', COALESCE(sum(COALESCE(p.costo_mxn_native, 0)), 0),
        'profitUSD', COALESCE(sum(COALESCE(p.venta_usd, 0) - COALESCE(p.costo_usd, 0)), 0),
        'gastosOperativosMXN',
          COALESCE((SELECT val FROM gastos_op_facturas), 0)
          + COALESCE((SELECT val FROM gastos_op_comisiones), 0),
        'gastosOperativosSinTC', COALESCE((SELECT val FROM gastos_op_sin_tc), 0)
      ) AS val
      FROM embarques_base eb
      LEFT JOIN profit p ON p.embarque_id = eb.id
      WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_mes AND eb.eta <= v_fin_mes
    ),
    resumen_sig AS (
      SELECT jsonb_build_object(
        'total', count(*),
        'ventaUSD', COALESCE(sum(COALESCE(p.venta_usd, 0)), 0),
        'costoUSD', COALESCE(sum(COALESCE(p.costo_usd, 0)), 0),
        'ventaMXN', COALESCE(sum(COALESCE(p.venta_mxn, 0)), 0),
        'costoMXN', COALESCE(sum(COALESCE(p.costo_mxn, 0)), 0),
        'profitMXN', COALESCE(sum(COALESCE(p.venta_mxn, 0) - COALESCE(p.costo_mxn, 0)), 0)
      ) AS val
      FROM activos eb
      LEFT JOIN profit p ON p.embarque_id = eb.id
      WHERE eb.eta IS NOT NULL AND eb.eta >= v_inicio_sig AND eb.eta <= v_fin_sig
    )
    SELECT jsonb_build_object(
      'totalActivos', (SELECT count(*) FROM activos),
      'conteoPorEstado', COALESCE((SELECT val FROM conteo), '{}'::jsonb),
      'arribosEsteMes', COALESCE((SELECT val FROM arribos_mes), '{}'::jsonb),
      'resumenMesSiguiente', COALESCE((SELECT val FROM resumen_sig), '{}'::jsonb)
    )
  );
END;
$$;
CREATE FUNCTION public.default_user_org_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_count int;
  v_org uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  SELECT count(*) INTO v_count FROM public.organization_members WHERE user_id = v_uid;
  IF v_count = 0 THEN RETURN NULL; END IF;
  IF v_count = 1 THEN
    SELECT organization_id INTO v_org FROM public.organization_members WHERE user_id = v_uid;
    RETURN v_org;
  END IF;
  SELECT m.organization_id INTO v_org
  FROM public.organization_members m
  LEFT JOIN public.organizations o ON o.id = m.organization_id
  WHERE m.user_id = v_uid
  ORDER BY
    (CASE WHEN EXISTS (SELECT 1 FROM public.embarques e WHERE e.organization_id = m.organization_id)
            OR EXISTS (SELECT 1 FROM public.cotizaciones c WHERE c.organization_id = m.organization_id)
          THEN 0 ELSE 1 END) ASC,
    (CASE WHEN coalesce(o.nombre, '') ILIKE '%demo%' THEN 1 ELSE 0 END) ASC,
    m.created_at ASC,
    m.organization_id ASC
  LIMIT 1;
  RETURN v_org;
END;
$$;
CREATE FUNCTION public.detectar_alertas_app_logs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted INTEGER := 0;
  v_row RECORD;
  v_dedupe TEXT;
BEGIN
  FOR v_row IN
    SELECT
      fn AS function_name,
      COUNT(*) AS errores,
      MAX(ts) AS last_error_at
    FROM public.app_logs
    WHERE ts > now() - INTERVAL '5 minutes'
      AND status_code >= 500
    GROUP BY fn
    HAVING COUNT(*) >= 5
  LOOP
    v_dedupe := 'app_logs:' || v_row.function_name || ':' ||
                to_char(date_trunc('hour', now()), 'YYYY-MM-DD-HH24');
    INSERT INTO public.alertas_sistema (severity, source, message, payload, dedupe_key)
    VALUES (
      CASE WHEN v_row.errores >= 20 THEN 'critical' ELSE 'error' END,
      'app_logs',
      format('Función %s: %s errores en los últimos 5 minutos',
             v_row.function_name, v_row.errores),
      jsonb_build_object(
        'function_name', v_row.function_name,
        'errores', v_row.errores,
        'last_error_at', v_row.last_error_at
      ),
      v_dedupe
    )
    ON CONFLICT (dedupe_key) WHERE acknowledged_at IS NULL AND dedupe_key IS NOT NULL
    DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
  END LOOP;
  RETURN v_inserted;
END;
$$;
CREATE FUNCTION public.devolver_anticipo_proveedor(p_id uuid, p_monto numeric, p_fecha date, p_cuenta_bancaria_id uuid, p_referencia text DEFAULT NULL::text, p_motivo text DEFAULT NULL::text) RETURNS public.anticipos_proveedor
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.anticipos_proveedor;
  v_uid uuid := auth.uid();
  v_email text;
  v_autorizado boolean;
  v_cuenta_org uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid
      AND ur.role::text = ANY (ARRAY['admin','admin_org','super_admin','contador','tesorero'])
  ) INTO v_autorizado;
  IF NOT v_autorizado THEN
    RAISE EXCEPTION 'LC_ANTICIPO_SIN_ROL: Sólo administradores, contabilidad o tesorería pueden registrar devoluciones de anticipo.'
      USING ERRCODE = '42501';
  END IF;
  IF COALESCE(trim(p_motivo),'') = '' OR length(trim(p_motivo)) < 3 THEN
    RAISE EXCEPTION 'LC_ANTICIPO_MOTIVO_REQUERIDO: Debes indicar el motivo de la devolución.';
  END IF;
  SELECT * INTO v_row FROM public.anticipos_proveedor
   WHERE id = p_id AND deleted_at IS NULL
   FOR UPDATE;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'LC_ANTICIPO_NO_EXISTE: El anticipo no existe.';
  END IF;
  IF v_row.organization_id IS DISTINCT FROM public.current_user_org_id()
     AND NOT public.has_role(v_uid, 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_ANTICIPO_OTRA_ORG: El anticipo pertenece a otra organización.'
      USING ERRCODE = '42501';
  END IF;
  IF v_row.estado = 'cancelado' THEN
    RAISE EXCEPTION 'LC_ANTICIPO_YA_CANCELADO: El anticipo está cancelado; no puede devolverse.';
  END IF;
  IF v_row.estado = 'devuelto' THEN
    RAISE EXCEPTION 'LC_ANTICIPO_YA_DEVUELTO: Este anticipo ya tiene una devolución registrada.';
  END IF;
  IF p_monto IS NULL OR p_monto <= 0 THEN
    RAISE EXCEPTION 'LC_ANTICIPO_MONTO_INVALIDO: El monto devuelto debe ser mayor a cero.';
  END IF;
  IF p_monto > COALESCE(v_row.saldo_disponible,0) + 0.01 THEN
    RAISE EXCEPTION 'LC_ANTICIPO_MONTO_EXCEDE_SALDO: La devolución (%) excede el saldo disponible (%).',
      p_monto, COALESCE(v_row.saldo_disponible,0);
  END IF;
  -- F2 (decisión 2026-08-29): sólo devolución TOTAL. Una parcial dejaba el
  -- remanente fuera del sistema (saldo forzado a 0 sin asiento contable).
  IF p_monto < COALESCE(v_row.saldo_disponible,0) - 0.01 THEN
    RAISE EXCEPTION 'LC_ANTICIPO_DEVOLUCION_TOTAL: La devolución debe ser por el saldo completo (%); no se permiten devoluciones parciales.',
      COALESCE(v_row.saldo_disponible,0);
  END IF;
  IF p_fecha IS NULL THEN
    RAISE EXCEPTION 'LC_ANTICIPO_FECHA_REQUERIDA: Indica la fecha de la devolución.';
  END IF;
  IF p_fecha < v_row.fecha_anticipo THEN
    RAISE EXCEPTION 'LC_ANTICIPO_FECHA_INVALIDA: La devolución no puede ser anterior a la fecha del anticipo (%).',
      v_row.fecha_anticipo;
  END IF;
  SELECT cb.organization_id INTO v_cuenta_org
    FROM public.cuentas_bancarias cb
   WHERE cb.id = p_cuenta_bancaria_id;
  IF v_cuenta_org IS NULL THEN
    RAISE EXCEPTION 'LC_ANTICIPO_CUENTA_REQUERIDA: Selecciona la cuenta bancaria donde entró el dinero.';
  END IF;
  IF v_cuenta_org IS DISTINCT FROM v_row.organization_id THEN
    RAISE EXCEPTION 'LC_ANTICIPO_CUENTA_OTRA_ORG: La cuenta bancaria pertenece a otra organización.'
      USING ERRCODE = '42501';
  END IF;
  UPDATE public.anticipos_proveedor
    SET estado = 'devuelto',
        saldo_disponible = 0,
        monto_devuelto = p_monto,
        motivo_devolucion = trim(p_motivo),
        devuelto_at = now(),
        devuelto_by = v_uid,
        updated_at = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
  -- F1: hash_dedupe es NOT NULL; sin él el INSERT lanzaba 23502 y toda la
  -- devolución hacía rollback.
  INSERT INTO public.bbva_movimientos
    (organization_id, cuenta_bancaria_id, fecha, concepto, referencia,
     cargo, abono, estado_conciliacion, anticipo_proveedor_id, importado_por, importado_en,
     hash_dedupe)
  VALUES
    (v_row.organization_id, p_cuenta_bancaria_id, p_fecha,
     'Devolución de anticipo ' || v_row.id::text, NULLIF(trim(COALESCE(p_referencia,'')),''),
     0, p_monto, 'Pendiente'::public.estado_conciliacion, v_row.id, v_uid, now(),
     'devolucion-' || v_row.id::text);
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (v_row.organization_id, v_uid, COALESCE(v_email,''), 'devolver_anticipo_proveedor', 'cxp',
            v_row.id, 'Anticipo ' || v_row.id::text,
            jsonb_build_object('motivo', trim(p_motivo), 'monto_devuelto', p_monto,
                               'moneda', v_row.moneda, 'fecha', p_fecha,
                               'cuenta_bancaria_id', p_cuenta_bancaria_id,
                               'referencia', p_referencia));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en devolver_anticipo_proveedor: % %', SQLSTATE, SQLERRM;
  END;
  RETURN v_row;
END;
$$;
CREATE FUNCTION public.direccion_totales(p_desde date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH emb AS (
    SELECT e.id
    FROM embarques e
    WHERE e.deleted_at IS NULL
      -- Ola 5 · N23: excluir Cancelado, alineado con el loader cliente
      -- del dashboard de Dirección.
      AND e.estado <> 'Cancelado'
      AND (e.cerrado_at >= p_desde OR e.eta >= p_desde)
      AND e.organization_id = public.org_scope()
  ),
  ventas AS (
    SELECT cv.moneda::text AS moneda, SUM(cv.total) AS total
    FROM conceptos_venta cv
    WHERE cv.deleted_at IS NULL AND cv.embarque_id IN (SELECT id FROM emb)
    GROUP BY cv.moneda
  ),
  costos AS (
    SELECT cc.moneda::text AS moneda, SUM(cc.monto) AS total
    FROM conceptos_costo cc
    WHERE cc.deleted_at IS NULL AND cc.embarque_id IN (SELECT id FROM emb)
    GROUP BY cc.moneda
  ),
  facturado AS (
    SELECT f.moneda::text AS moneda, SUM(f.total) AS total
    FROM facturas f
    WHERE f.deleted_at IS NULL
      AND f.estado IN ('Emitida', 'Parcialmente pagada', 'Vencida', 'Pagada')
      AND f.fecha_emision >= p_desde
      AND f.organization_id = public.org_scope()
    GROUP BY f.moneda
  ),
  cobrado AS (
    SELECT f.moneda::text AS moneda, SUM(pf.monto_aplicado_factura) AS total
    FROM pagos_factura pf
    JOIN facturas f ON f.id = pf.factura_id
    WHERE pf.deleted_at IS NULL
      AND f.deleted_at IS NULL
      AND pf.fecha_pago >= p_desde
      AND pf.organization_id = public.org_scope()
    GROUP BY f.moneda
  )
  SELECT jsonb_build_object(
    'embarques',  (SELECT COUNT(*) FROM emb),
    'ventas',     COALESCE((SELECT jsonb_object_agg(moneda, total) FROM ventas), '{}'::jsonb),
    'costos',     COALESCE((SELECT jsonb_object_agg(moneda, total) FROM costos), '{}'::jsonb),
    'facturado',  COALESCE((SELECT jsonb_object_agg(moneda, total) FROM facturado), '{}'::jsonb),
    'cobrado',    COALESCE((SELECT jsonb_object_agg(moneda, total) FROM cobrado), '{}'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$$;
CREATE FUNCTION public.duplicar_cotizacion(p_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_nueva_id uuid := gen_random_uuid();
  v_folio text;
BEGIN
  SELECT organization_id INTO v_org FROM public.cotizaciones WHERE id = p_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Cotización no encontrada' USING ERRCODE = 'P0002';
  END IF;
  IF v_org IS DISTINCT FROM public.current_user_org_id() THEN
    RAISE EXCEPTION 'No pertenece a tu organización' USING ERRCODE = '42501';
  END IF;
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'operador') OR public.has_role(auth.uid(), 'ejecutivo_pricing')) THEN
    RAISE EXCEPTION 'Rol insuficiente para duplicar cotizaciones' USING ERRCODE = '42501';
  END IF;
  v_folio := public.siguiente_folio_cotizacion();
  INSERT INTO public.cotizaciones AS c
  SELECT
    v_nueva_id           AS id,
    v_folio              AS folio,
    cliente_id, cliente_nombre, modo, tipo, incoterm, descripcion_mercancia,
    peso_kg, volumen_m3, piezas, origen, destino,
    conceptos_venta, subtotal, moneda, vigencia_dias,
    NULL::date           AS fecha_vigencia,
    notas,
    'Borrador'::estado_cotizacion AS estado,
    NULL::uuid           AS embarque_id,
    operador,
    now()                AS created_at,
    now()                AS updated_at
  FROM public.cotizaciones
  WHERE id = p_id;
  UPDATE public.cotizaciones
     SET organization_id = v_org,
         duplicada_de_id = p_id
   WHERE id = v_nueva_id;
  INSERT INTO public.cotizacion_costos
    (cotizacion_id, concepto, moneda, proveedor, cantidad,
     costo_unitario, precio_venta)
  SELECT v_nueva_id, concepto, moneda, proveedor, cantidad,
         costo_unitario, precio_venta
    FROM public.cotizacion_costos
   WHERE cotizacion_id = p_id;
  RETURN v_nueva_id;
END;
$$;
CREATE FUNCTION public.duplicar_embarque_completo(p_embarque_origen_id uuid, p_copias jsonb, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  origen embarques%ROWTYPE;
  copia jsonb;
  nuevo_id uuid;
  creados jsonb := '[]'::jsonb;
  v_resp jsonb;
  v_mapping jsonb;
BEGIN
  v_resp := public.idempotency_claim(p_request_id, 'duplicar_embarque_completo');
  IF v_resp IS NOT NULL THEN RETURN v_resp; END IF;
  SELECT * INTO origen FROM embarques WHERE id = p_embarque_origen_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Embarque origen no encontrado'; END IF;
  PERFORM public._assert_writer(origen.organization_id);
  FOR copia IN SELECT * FROM jsonb_array_elements(p_copias)
  LOOP
    INSERT INTO embarques (
      expediente, estado, cliente_id, cliente_nombre, modo, tipo, incoterm,
      bl_master, bl_house, naviera, puerto_origen, puerto_destino,
      aeropuerto_origen, aeropuerto_destino, ciudad_origen, ciudad_destino,
      aerolinea, transportista, agente, shipper, consignatario,
      descripcion_mercancia, tipo_carga, tipo_servicio, operador,
      mawb, hawb, carta_porte, etd, eta,
      tipo_cambio_usd, tipo_cambio_eur,
      contenedor, tipo_contenedor, peso_kg, volumen_m3, piezas, organization_id
    ) VALUES (
      origen.expediente, 'Confirmado', origen.cliente_id, origen.cliente_nombre,
      origen.modo, origen.tipo, origen.incoterm,
      origen.bl_master, origen.bl_house, origen.naviera,
      origen.puerto_origen, origen.puerto_destino,
      origen.aeropuerto_origen, origen.aeropuerto_destino,
      origen.ciudad_origen, origen.ciudad_destino,
      origen.aerolinea, origen.transportista, origen.agente,
      origen.shipper, origen.consignatario,
      origen.descripcion_mercancia, origen.tipo_carga, origen.tipo_servicio,
      origen.operador, origen.mawb, origen.hawb, origen.carta_porte,
      origen.etd, origen.eta,
      origen.tipo_cambio_usd, origen.tipo_cambio_eur,
      NULLIF(copia->>'num_contenedor', ''), NULLIF(copia->>'tipo_contenedor', ''),
      (copia->>'peso_kg')::numeric, (copia->>'volumen_m3')::numeric, (copia->>'piezas')::int,
      origen.organization_id
    ) RETURNING id INTO nuevo_id;
    WITH inserted AS (
      INSERT INTO embarque_contenedores (
        embarque_id, organization_id, numero_contenedor, tipo_contenedor,
        bl_house, peso_kg, volumen_m3, piezas, orden
      )
      SELECT
        nuevo_id, origen.organization_id, numero_contenedor, tipo_contenedor,
        bl_house, peso_kg, volumen_m3, piezas, orden
      FROM embarque_contenedores
      WHERE embarque_id = p_embarque_origen_id AND deleted_at IS NULL
      RETURNING id, orden
    ),
    paired AS (
      SELECT
        old.id AS old_id,
        new.id AS new_id
      FROM (
        SELECT id, orden FROM embarque_contenedores
        WHERE embarque_id = p_embarque_origen_id AND deleted_at IS NULL
      ) old
      JOIN inserted new ON new.orden = old.orden
    )
    SELECT COALESCE(jsonb_object_agg(old_id::text, new_id), '{}'::jsonb)
    INTO v_mapping
    FROM paired;
    INSERT INTO conceptos_venta (
      embarque_id, descripcion, cantidad, precio_unitario, moneda, total,
      organization_id, contenedor_id, aplica_iva
    )
    SELECT
      nuevo_id, descripcion, cantidad, precio_unitario, moneda, total,
      origen.organization_id,
      CASE
        WHEN contenedor_id IS NOT NULL AND v_mapping ? contenedor_id::text
          THEN (v_mapping->>contenedor_id::text)::uuid
        ELSE NULL
      END,
      aplica_iva
    FROM conceptos_venta
    WHERE embarque_id = p_embarque_origen_id AND deleted_at IS NULL;
    INSERT INTO conceptos_costo (
      embarque_id, concepto, proveedor_nombre, proveedor_id, moneda, monto,
      organization_id, contenedor_id
    )
    SELECT
      nuevo_id, concepto, proveedor_nombre, proveedor_id, moneda, monto,
      origen.organization_id,
      CASE
        WHEN contenedor_id IS NOT NULL AND v_mapping ? contenedor_id::text
          THEN (v_mapping->>contenedor_id::text)::uuid
        ELSE NULL
      END
    FROM conceptos_costo
    WHERE embarque_id = p_embarque_origen_id AND deleted_at IS NULL;
    INSERT INTO notas_embarque (embarque_id, contenido, tipo, organization_id)
    VALUES (nuevo_id, 'Embarque duplicado desde ' || origen.expediente, 'sistema', origen.organization_id);
    creados := creados || jsonb_build_object('id', nuevo_id, 'expediente', origen.expediente);
  END LOOP;
  PERFORM public.idempotency_store(p_request_id, creados);
  RETURN creados;
END;
$$;
CREATE FUNCTION public.duplicar_factura_para_refacturacion(p_caso_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_c public.refacturaciones%ROWTYPE;
  v_old public.facturas%ROWTYPE;
  v_cli public.clientes%ROWTYPE;
  v_new_id uuid := gen_random_uuid();
  v_new_numero text;
  v_estado_nueva text;
  v_tc_nuevo numeric;
  v_factor numeric;
BEGIN
  -- N18: FOR UPDATE serializa la duplicación del mismo caso (doble clic).
  SELECT * INTO v_c FROM public.refacturaciones WHERE id = p_caso_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_CASO_NO_ENCONTRADO' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public._assert_refacturador(v_c.organization_id);
  IF v_c.factura_nueva_id IS NOT NULL THEN
    SELECT estado::text INTO v_estado_nueva FROM public.facturas WHERE id = v_c.factura_nueva_id;
    IF v_estado_nueva IS NOT NULL AND v_estado_nueva <> 'Cancelada' THEN
      RETURN v_c.factura_nueva_id;
    END IF;
  END IF;
  SELECT * INTO v_old FROM public.facturas WHERE id = v_c.factura_original_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_FACTURA_NO_ENCONTRADA' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO v_cli FROM public.clientes WHERE id = v_c.cliente_destino_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_CLIENTE_DESTINO: el cliente destino no existe' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public._assert_receptor_fiscal_valido(v_c.cliente_destino_id);
  IF v_old.moneda <> 'MXN' AND COALESCE(v_old.tipo_cambio, 0) <= 0 THEN
    RAISE EXCEPTION 'LC_REFACT_TC_REQUERIDO: la factura original en % no tiene tipo de cambio', v_old.moneda
      USING ERRCODE = 'P0001';
  END IF;
  IF v_old.moneda::text = 'MXN' THEN
    v_tc_nuevo := v_old.tipo_cambio;
  ELSE
    SELECT CASE WHEN v_old.moneda::text = 'USD' THEN d.usd_mxn
                WHEN v_old.moneda::text = 'EUR' THEN d.eur_mxn END
      INTO v_tc_nuevo
    FROM public.tc_dof_vigente(CURRENT_DATE) d;
    IF v_tc_nuevo IS NULL OR v_tc_nuevo <= 1 THEN
      v_tc_nuevo := NULL;
    END IF;
  END IF;
  v_new_numero := v_old.numero || '-RF';
  WHILE EXISTS (
    SELECT 1 FROM public.facturas
    WHERE organization_id = v_old.organization_id AND numero = v_new_numero
  ) LOOP
    v_new_numero := v_new_numero || '1';
  END LOOP;
  INSERT INTO public.facturas (
    id, organization_id, cliente_id, cliente_nombre, expediente,
    cotizacion_id, embarque_id, proforma_id,
    numero, serie, serie_id,
    fecha_emision, fecha_vencimiento, dias_credito,
    moneda, tipo_cambio, subtotal, iva, ret_isr, ret_iva, total,
    metodo_pago, forma_pago, uso_cfdi, rfc_cliente,
    notas, referencia_bl, snapshot_emision, estado, origen, sustituye_a
  ) VALUES (
    v_new_id, v_old.organization_id, v_cli.id, v_cli.nombre, v_old.expediente,
    v_old.cotizacion_id, v_old.embarque_id, NULL,
    v_new_numero, v_old.serie, v_old.serie_id,
    CURRENT_DATE,
    CURRENT_DATE + COALESCE(v_cli.dias_credito, v_old.dias_credito, 0),
    COALESCE(v_cli.dias_credito, v_old.dias_credito, 0),
    v_old.moneda, v_tc_nuevo, v_old.subtotal, v_old.iva,
    COALESCE(v_old.ret_isr, 0), COALESCE(v_old.ret_iva, 0), v_old.total,
    COALESCE(v_cli.metodo_pago_default, v_old.metodo_pago),
    COALESCE(v_cli.forma_pago_default, v_old.forma_pago),
    COALESCE(v_cli.uso_cfdi_default, v_old.uso_cfdi),
    v_cli.rfc,
    COALESCE(v_old.notas, '') || E'\n[Refacturación de ' || v_old.numero || ' a ' || v_cli.nombre || ']',
    v_old.referencia_bl, NULL, 'Borrador', v_old.origen,
    CASE WHEN v_c.ruta_fiscal = '01' THEN v_old.id ELSE NULL END
  );
  IF v_c.ruta_fiscal = '01' THEN
    UPDATE public.facturas SET sustituida_por = v_new_id WHERE id = v_old.id;
  END IF;
  INSERT INTO public.conceptos_factura (
    factura_id, organization_id,
    descripcion, cantidad, precio_unitario, moneda, total,
    clave_sat, tipo_iva, tasa_iva_aplicada,
    tasa_ret_isr, tasa_ret_iva, monto_ret_isr, monto_ret_iva,
    clave_unidad, embarque_id, proforma_id_origen
  )
  SELECT
    v_new_id, v_old.organization_id,
    descripcion, cantidad, precio_unitario, moneda, total,
    clave_sat, tipo_iva, tasa_iva_aplicada,
    tasa_ret_isr, tasa_ret_iva, monto_ret_isr, monto_ret_iva,
    clave_unidad, embarque_id, proforma_id_origen
  FROM public.conceptos_factura
  WHERE factura_id = v_old.id AND deleted_at IS NULL;
  INSERT INTO public.factura_embarques (factura_id, embarque_id, organization_id, activa)
  SELECT v_new_id, embarque_id, organization_id, true
  FROM public.factura_embarques
  WHERE factura_id = v_old.id
  ON CONFLICT DO NOTHING;
  UPDATE public.refacturaciones
     SET factura_nueva_id = v_new_id, paso_actual = GREATEST(paso_actual, 3)
   WHERE id = p_caso_id;
  v_factor := CASE WHEN COALESCE(v_old.tipo_cambio, 0) > 0 AND v_tc_nuevo IS NOT NULL
                   THEN ROUND(v_tc_nuevo / v_old.tipo_cambio, 6) ELSE NULL END;
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_old.organization_id, auth.uid(),
    COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), ''),
    'refacturacion_borrador_creado', 'facturacion', v_new_id, COALESCE(v_new_numero, ''),
    jsonb_build_object('caso_id', p_caso_id, 'factura_original_id', v_old.id,
                       'cliente_destino_id', v_cli.id, 'rfc_destino', v_cli.rfc,
                       'ruta_fiscal', v_c.ruta_fiscal, 'proforma_origen_id', v_old.proforma_id,
                       'tc_original', v_old.tipo_cambio, 'tc_nuevo_dof', v_tc_nuevo,
                       'tc_factor', v_factor)
  );
  RETURN v_new_id;
END;
$$;
CREATE FUNCTION public.duplicar_factura_para_sustitucion(p_factura_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_old public.facturas%ROWTYPE;
  v_sust_estado text;
  v_new_id uuid := gen_random_uuid();
  v_new_numero text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  SELECT * INTO v_old FROM public.facturas WHERE id = p_factura_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'factura_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = v_caller
      AND organization_id = v_old.organization_id
      AND role IN ('admin_org','admin','super_admin','contador','auxiliar_contable','tesorero')
  ) THEN
    RAISE EXCEPTION 'forbidden: requiere rol admin, contador o tesorero' USING ERRCODE = '42501';
  END IF;
  IF v_old.uuid_fiscal IS NULL THEN
    RAISE EXCEPTION 'factura_sin_uuid: sólo se puede sustituir un CFDI timbrado' USING ERRCODE = 'P0001';
  END IF;
  IF v_old.sustituida_por IS NOT NULL THEN
    SELECT estado::text INTO v_sust_estado FROM public.facturas WHERE id = v_old.sustituida_por;
    IF v_sust_estado IS NOT NULL AND v_sust_estado NOT IN ('Cancelada','Sustituida') THEN
      RAISE EXCEPTION 'factura_ya_sustituida' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF v_old.estado = 'Cancelada' THEN
    RAISE EXCEPTION 'factura_ya_cancelada' USING ERRCODE = 'P0001';
  END IF;
  v_new_numero := v_old.numero || '-R';
  WHILE EXISTS (SELECT 1 FROM public.facturas WHERE organization_id = v_old.organization_id AND numero = v_new_numero) LOOP
    v_new_numero := v_new_numero || '1';
  END LOOP;
  INSERT INTO public.facturas (
    id, organization_id, cliente_id, cliente_nombre, expediente,
    cotizacion_id, embarque_id, proforma_id,
    numero, serie, serie_id,
    fecha_emision, fecha_vencimiento, dias_credito,
    moneda, tipo_cambio, subtotal, iva, total,
    metodo_pago, forma_pago, uso_cfdi, rfc_cliente,
    notas, referencia_bl,
    snapshot_emision,
    estado, origen,
    sustituye_a
  ) VALUES (
    v_new_id, v_old.organization_id, v_old.cliente_id, v_old.cliente_nombre, v_old.expediente,
    v_old.cotizacion_id, v_old.embarque_id, v_old.proforma_id,
    v_new_numero, v_old.serie, v_old.serie_id,
    CURRENT_DATE, CURRENT_DATE + COALESCE(v_old.dias_credito, 0), v_old.dias_credito,
    v_old.moneda, v_old.tipo_cambio, v_old.subtotal, v_old.iva, v_old.total,
    v_old.metodo_pago, v_old.forma_pago, v_old.uso_cfdi, v_old.rfc_cliente,
    COALESCE(v_old.notas, '') || E'\n[Sustituye a ' || v_old.numero || ']',
    v_old.referencia_bl,
    NULL,
    'Borrador', v_old.origen,
    v_old.id
  );
  UPDATE public.facturas SET sustituida_por = v_new_id WHERE id = v_old.id;
  INSERT INTO public.conceptos_factura (
    factura_id, organization_id,
    descripcion, cantidad, precio_unitario, moneda, total,
    clave_sat, tipo_iva, tasa_iva_aplicada,
    tasa_ret_isr, tasa_ret_iva, monto_ret_isr, monto_ret_iva,
    clave_unidad, embarque_id, proforma_id_origen
  )
  SELECT
    v_new_id, v_old.organization_id,
    descripcion, cantidad, precio_unitario, moneda, total,
    clave_sat, tipo_iva, tasa_iva_aplicada,
    tasa_ret_isr, tasa_ret_iva, monto_ret_isr, monto_ret_iva,
    clave_unidad, embarque_id, proforma_id_origen
  FROM public.conceptos_factura
  WHERE factura_id = v_old.id
    AND deleted_at IS NULL;
  -- Copiar los vínculos con embarques (tabla puente) al borrador sustituto.
  -- La original queda con activa=false al cancelarse; la nueva nace activa.
  INSERT INTO public.factura_embarques (factura_id, embarque_id, organization_id, activa)
  SELECT v_new_id, embarque_id, organization_id, true
  FROM public.factura_embarques
  WHERE factura_id = v_old.id
  ON CONFLICT DO NOTHING;
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_old.organization_id,
    v_caller,
    COALESCE((SELECT email FROM auth.users WHERE id = v_caller), ''),
    'factura_duplicada_para_sustitucion',
    'facturacion',
    v_new_id,
    COALESCE(v_new_numero, ''),
    jsonb_build_object('factura_original_id', v_old.id, 'factura_original_uuid', v_old.uuid_fiscal, 'numero_nuevo', v_new_numero)
  );
  RETURN v_new_id;
END;
$$;
CREATE FUNCTION public.eerr_resumen_anual(p_year integer, p_fuente text DEFAULT 'embarques'::text) RETURNS TABLE(mes integer, ingresos_mxn numeric, costos_mxn numeric, excluidos_sin_tc integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := public.org_scope();
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: usuario sin organizacion activa' USING ERRCODE='42501';
  END IF;
  IF p_fuente = 'embarques' THEN
    RETURN QUERY
    WITH meses AS (
      SELECT generate_series(1,12) AS mes
    ),
    emb AS (
      SELECT
        e.id,
        EXTRACT(month FROM e.eta)::int AS mes,
        (SELECT t.tc FROM public.tc_para_documento(e.eta, 'USD', e.tipo_cambio_usd, NULL) t) AS tc_usd,
        (SELECT t.tc FROM public.tc_para_documento(e.eta, 'EUR', e.tipo_cambio_eur, NULL) t) AS tc_eur
      FROM public.embarques e
      WHERE e.deleted_at IS NULL
        AND e.organization_id = v_org
        AND e.estado <> 'Cancelado'
        AND e.eta IS NOT NULL
        AND EXTRACT(year FROM e.eta) = p_year
    ),
    ing AS (
      SELECT em.mes,
        SUM(
          CASE UPPER(COALESCE(cv.moneda::text, 'MXN'))
            WHEN 'USD' THEN CASE WHEN em.tc_usd IS NOT NULL THEN COALESCE(cv.total, 0) * em.tc_usd END
            WHEN 'EUR' THEN CASE WHEN em.tc_eur IS NOT NULL THEN COALESCE(cv.total, 0) * em.tc_eur END
            ELSE COALESCE(cv.total, 0)
          END
        ) AS total,
        COUNT(*) FILTER (
          WHERE (UPPER(COALESCE(cv.moneda::text, 'MXN')) = 'USD' AND em.tc_usd IS NULL)
             OR (UPPER(COALESCE(cv.moneda::text, 'MXN')) = 'EUR' AND em.tc_eur IS NULL)
        ) AS sin_tc
      FROM public.conceptos_venta cv
      JOIN emb em ON em.id = cv.embarque_id
      WHERE cv.deleted_at IS NULL
      GROUP BY em.mes
    ),
    cst AS (
      SELECT em.mes,
        SUM(
          CASE UPPER(COALESCE(cc.moneda::text, 'MXN'))
            WHEN 'USD' THEN CASE WHEN em.tc_usd IS NOT NULL THEN COALESCE(cc.monto, 0) * em.tc_usd END
            WHEN 'EUR' THEN CASE WHEN em.tc_eur IS NOT NULL THEN COALESCE(cc.monto, 0) * em.tc_eur END
            ELSE COALESCE(cc.monto, 0)
          END
        ) AS total,
        COUNT(*) FILTER (
          WHERE (UPPER(COALESCE(cc.moneda::text, 'MXN')) = 'USD' AND em.tc_usd IS NULL)
             OR (UPPER(COALESCE(cc.moneda::text, 'MXN')) = 'EUR' AND em.tc_eur IS NULL)
        ) AS sin_tc
      FROM public.conceptos_costo cc
      JOIN emb em ON em.id = cc.embarque_id
      WHERE cc.deleted_at IS NULL
      GROUP BY em.mes
    )
    SELECT m.mes,
           COALESCE(i.total, 0)::numeric AS ingresos_mxn,
           COALESCE(c.total, 0)::numeric AS costos_mxn,
           (COALESCE(i.sin_tc, 0) + COALESCE(c.sin_tc, 0))::integer AS excluidos_sin_tc
    FROM meses m
    LEFT JOIN ing i ON i.mes = m.mes
    LEFT JOIN cst c ON c.mes = m.mes
    ORDER BY m.mes;
  ELSIF p_fuente = 'facturas' THEN
    RETURN QUERY
    WITH meses AS (
      SELECT generate_series(1,12) AS mes
    ),
    fact_src AS (
      SELECT
        f.fecha_emision, f.moneda::text AS moneda, f.total,
        (SELECT t.tc FROM public.tc_para_documento(f.fecha_emision, 'USD', f.tipo_cambio, e.tipo_cambio_usd) t) AS tc_usd,
        (SELECT t.tc FROM public.tc_para_documento(f.fecha_emision, 'EUR', f.tipo_cambio, e.tipo_cambio_eur) t) AS tc_eur
      FROM public.facturas f
      LEFT JOIN public.embarques e ON e.expediente = f.expediente
                                    AND e.organization_id = v_org
                                    AND e.deleted_at IS NULL
      WHERE f.deleted_at IS NULL
        AND f.organization_id = v_org
        AND f.estado IN ('Emitida', 'Pagada', 'Vencida', 'Parcialmente pagada')
        AND f.fecha_emision IS NOT NULL
        AND EXTRACT(year FROM f.fecha_emision) = p_year
    ),
    fact AS (
      SELECT
        EXTRACT(month FROM fecha_emision)::int AS mes,
        SUM(
          CASE UPPER(COALESCE(moneda, 'MXN'))
            WHEN 'USD' THEN CASE WHEN tc_usd IS NOT NULL THEN COALESCE(total, 0) * tc_usd END
            WHEN 'EUR' THEN CASE WHEN tc_eur IS NOT NULL THEN COALESCE(total, 0) * tc_eur END
            ELSE COALESCE(total, 0)
          END
        ) AS total,
        COUNT(*) FILTER (
          WHERE (UPPER(COALESCE(moneda, 'MXN')) = 'USD' AND tc_usd IS NULL)
             OR (UPPER(COALESCE(moneda, 'MXN')) = 'EUR' AND tc_eur IS NULL)
        ) AS sin_tc
      FROM fact_src
      GROUP BY EXTRACT(month FROM fecha_emision)
    ),
    ncs AS (
      SELECT
        EXTRACT(month FROM ncf.fecha_emision)::int AS mes,
        SUM(
          CASE UPPER(COALESCE(ncf.moneda::text, 'MXN'))
            WHEN 'USD' THEN ABS(COALESCE(ncf.monto, 0)) * (SELECT t.tc FROM public.tc_para_documento(ncf.fecha_emision, 'USD', ncf.tipo_cambio, NULL) t)
            WHEN 'EUR' THEN ABS(COALESCE(ncf.monto, 0)) * (SELECT t.tc FROM public.tc_para_documento(ncf.fecha_emision, 'EUR', ncf.tipo_cambio, NULL) t)
            ELSE ABS(COALESCE(ncf.monto, 0))
          END
        ) AS total,
        COUNT(*) FILTER (
          WHERE UPPER(COALESCE(ncf.moneda::text, 'MXN')) IN ('USD','EUR')
            AND (SELECT t.tc FROM public.tc_para_documento(ncf.fecha_emision, ncf.moneda::text, ncf.tipo_cambio, NULL) t) IS NULL
        ) AS sin_tc
      FROM public.factura_notas_credito ncf
      WHERE ncf.deleted_at IS NULL
        AND ncf.organization_id = v_org
        AND ncf.estado = 'Aplicada'
        AND ncf.fecha_emision IS NOT NULL
        AND EXTRACT(year FROM ncf.fecha_emision) = p_year
        -- Ola 14 · borrado logico estricto: la NC de una factura eliminada no
        -- puede seguir reduciendo el ingreso del mes.
        AND EXISTS (
          SELECT 1 FROM public.facturas f
          WHERE f.id = ncf.factura_id AND f.deleted_at IS NULL
        )
      GROUP BY EXTRACT(month FROM ncf.fecha_emision)
    ),
    pfact_src AS (
      SELECT
        pf.fecha_emision, pf.moneda::text AS moneda, pf.total,
        (SELECT t.tc FROM public.tc_para_documento(pf.fecha_emision, 'USD', pf.tipo_cambio_usd, e.tipo_cambio_usd) t) AS tc_usd,
        (SELECT t.tc FROM public.tc_para_documento(pf.fecha_emision, 'EUR', NULL, e.tipo_cambio_eur) t) AS tc_eur
      FROM public.proveedor_facturas pf
      LEFT JOIN public.embarques e ON e.id = pf.embarque_id
                                    AND e.organization_id = v_org
                                    AND e.deleted_at IS NULL
      WHERE pf.deleted_at IS NULL
        AND pf.organization_id = v_org
        AND pf.estado <> 'Cancelada'
        AND pf.fecha_emision IS NOT NULL
        AND EXTRACT(year FROM pf.fecha_emision) = p_year
    ),
    pfact AS (
      SELECT
        EXTRACT(month FROM fecha_emision)::int AS mes,
        SUM(
          CASE UPPER(COALESCE(moneda, 'MXN'))
            WHEN 'USD' THEN CASE WHEN tc_usd IS NOT NULL THEN COALESCE(total, 0) * tc_usd END
            WHEN 'EUR' THEN CASE WHEN tc_eur IS NOT NULL THEN COALESCE(total, 0) * tc_eur END
            ELSE COALESCE(total, 0)
          END
        ) AS total,
        COUNT(*) FILTER (
          WHERE (UPPER(COALESCE(moneda, 'MXN')) = 'USD' AND tc_usd IS NULL)
             OR (UPPER(COALESCE(moneda, 'MXN')) = 'EUR' AND tc_eur IS NULL)
        ) AS sin_tc
      FROM pfact_src
      GROUP BY EXTRACT(month FROM fecha_emision)
    ),
    ncp AS (
      SELECT
        EXTRACT(month FROM n.updated_at)::int AS mes,
        SUM(
          CASE UPPER(COALESCE(n.moneda::text, 'MXN'))
            WHEN 'USD' THEN CASE WHEN tc.tc_usd IS NOT NULL THEN ABS(COALESCE(n.monto, 0)) * tc.tc_usd END
            WHEN 'EUR' THEN CASE WHEN tc.tc_eur IS NOT NULL THEN ABS(COALESCE(n.monto, 0)) * tc.tc_eur END
            ELSE ABS(COALESCE(n.monto, 0))
          END
        ) AS total,
        COUNT(*) FILTER (
          WHERE (UPPER(COALESCE(n.moneda::text, 'MXN')) = 'USD' AND tc.tc_usd IS NULL)
             OR (UPPER(COALESCE(n.moneda::text, 'MXN')) = 'EUR' AND tc.tc_eur IS NULL)
        ) AS sin_tc
      FROM public.proveedor_notas_credito n
      -- Ola 14 · borrado logico estricto: si la factura de proveedor fue
      -- eliminada, su NC ya no descuenta el costo del mes.
      JOIN public.proveedor_facturas pf ON pf.id = n.proveedor_factura_id AND pf.deleted_at IS NULL
      LEFT JOIN LATERAL (
        SELECT
          (SELECT t.tc FROM public.tc_para_documento(pf.fecha_emision, 'USD', pf.tipo_cambio_usd, e.tipo_cambio_usd) t) AS tc_usd,
          (SELECT t.tc FROM public.tc_para_documento(pf.fecha_emision, 'EUR', NULL, e.tipo_cambio_eur) t) AS tc_eur
        FROM public.embarques e
        WHERE e.id = pf.embarque_id AND e.organization_id = v_org AND e.deleted_at IS NULL
      ) tc ON true
      WHERE n.deleted_at IS NULL
        AND n.organization_id = v_org
        AND n.estado = 'Aplicada'
        AND n.updated_at IS NOT NULL
        AND EXTRACT(year FROM n.updated_at) = p_year
      GROUP BY EXTRACT(month FROM n.updated_at)
    )
    SELECT m.mes,
           (COALESCE(f.total, 0) - COALESCE(n.total, 0))::numeric AS ingresos_mxn,
           (COALESCE(p.total, 0) - COALESCE(np.total, 0))::numeric AS costos_mxn,
           (COALESCE(f.sin_tc, 0) + COALESCE(n.sin_tc, 0) + COALESCE(p.sin_tc, 0) + COALESCE(np.sin_tc, 0))::integer AS excluidos_sin_tc
    FROM meses m
    LEFT JOIN fact f ON f.mes = m.mes
    LEFT JOIN ncs  n ON n.mes = m.mes
    LEFT JOIN pfact p ON p.mes = m.mes
    LEFT JOIN ncp np ON np.mes = m.mes
    ORDER BY m.mes;
  ELSE
    RAISE EXCEPTION 'LC_EERR_FUENTE_INVALIDA: fuente=% no reconocida (usa embarques|facturas)', p_fuente USING ERRCODE='22023';
  END IF;
END;
$$;
CREATE FUNCTION public.ejecutar_pago_programado(p_factura_id uuid, p_cuenta_bancaria_id uuid, p_fecha date, p_monto numeric, p_metodo_pago text DEFAULT 'Transferencia'::text, p_referencia text DEFAULT ''::text, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_autorizado boolean;
  v_org uuid;
  v_factura public.proveedor_facturas;
  v_cuenta public.cuentas_bancarias;
  v_saldo_cuenta numeric;
  v_pago public.pagos_proveedor;
  v_mov_id uuid;
  v_resp jsonb;
  v_cached jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  -- BL-04: reclamo atómico de la llave de idempotencia. Reintento del mismo
  -- submit → respuesta almacenada; ejecución aún en vuelo → rechazo claro.
  v_cached := public.idempotency_claim(p_request_id, 'ejecutar_pago_programado');
  IF v_cached IS NOT NULL THEN
    IF COALESCE((v_cached->>'__idempotency_pending')::boolean, false) THEN
      RAISE EXCEPTION 'LC_PAGO_PROGRAMADO_EN_PROCESO: Este pago programado ya está en proceso; espera unos segundos y verifica antes de reintentar.'
        USING ERRCODE = '42501';
    END IF;
    RETURN v_cached;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid
      AND ur.role::text = ANY (ARRAY['admin','admin_org','super_admin','tesorero'])
  ) INTO v_autorizado;
  IF NOT v_autorizado THEN
    RAISE EXCEPTION 'LC_SOD_VIOLATION: Tu rol no puede ejecutar pagos programados.';
  END IF;
  IF p_monto IS NULL OR p_monto <= 0 THEN
    RAISE EXCEPTION 'LC_PAGO_MONTO_INVALIDO: El monto del pago no es válido.';
  END IF;
  SELECT * INTO v_factura
    FROM public.proveedor_facturas
    WHERE id = p_factura_id AND deleted_at IS NULL
    FOR UPDATE;
  IF v_factura.id IS NULL THEN
    RAISE EXCEPTION 'LC_CXP_NO_EXISTE: La factura de proveedor no existe o fue eliminada.';
  END IF;
  v_org := v_factura.organization_id;
  IF NOT public.has_role(v_uid, 'super_admin'::app_role)
     AND NOT EXISTS (
       SELECT 1 FROM public.organization_members om
        WHERE om.organization_id = v_org AND om.user_id = v_uid
     )
  THEN
    RAISE EXCEPTION 'LC_CXP_EMBARQUE_ORG_MISMATCH: La factura pertenece a otra organización.';
  END IF;
  SELECT * INTO v_cuenta
    FROM public.cuentas_bancarias
    WHERE id = p_cuenta_bancaria_id AND deleted_at IS NULL
    FOR UPDATE;
  IF v_cuenta.id IS NULL THEN
    RAISE EXCEPTION 'LC_CUENTA_NO_EXISTE: La cuenta bancaria no existe o fue eliminada.';
  END IF;
  IF v_cuenta.organization_id <> v_org THEN
    RAISE EXCEPTION 'LC_CUENTA_ORG_MISMATCH: La cuenta bancaria pertenece a otra organización.';
  END IF;
  IF v_cuenta.moneda <> v_factura.moneda THEN
    RAISE EXCEPTION 'LC_PAGO_MONEDA_CUENTA_MISMATCH: La moneda de la cuenta (%) no coincide con la de la factura (%).',
      v_cuenta.moneda, v_factura.moneda;
  END IF;
  -- BL-04: cálculo alineado al canon de estado_cuenta_bancario (antes sumaba
  -- movimientos borrados y anteriores al corte del saldo inicial → doble
  -- conteo). La cuenta ya está bloqueada FOR UPDATE.
  v_saldo_cuenta := public.saldo_cuenta_bancaria(v_cuenta.id);
  IF p_monto > v_saldo_cuenta + 0.005 THEN
    RAISE EXCEPTION 'LC_CUENTA_SALDO_INSUFICIENTE: El saldo de la cuenta (%) es insuficiente para pagar %.',
      round(v_saldo_cuenta, 2), round(p_monto, 2);
  END IF;
  INSERT INTO public.pagos_proveedor (
    organization_id, proveedor_factura_id, fecha_pago, monto, moneda,
    metodo_pago, referencia, cuenta_bancaria_id, notas, created_by
  ) VALUES (
    v_org, p_factura_id, p_fecha, p_monto, v_factura.moneda,
    p_metodo_pago, COALESCE(p_referencia, ''), v_cuenta.id,
    'Ejecución de pago programado', v_uid
  )
  RETURNING * INTO v_pago;
  INSERT INTO public.bbva_movimientos (
    organization_id, cuenta_bancaria_id, fecha, concepto, referencia,
    cargo, abono, saldo, hash_dedupe, estado_conciliacion,
    pago_proveedor_id, conciliado_por, conciliado_at, importado_por
  ) VALUES (
    v_org, v_cuenta.id, p_fecha,
    'Pago programado: ' || COALESCE(v_factura.proveedor_nombre, ''),
    COALESCE(p_referencia, ''),
    p_monto, 0, v_saldo_cuenta - p_monto,
    'pago-programado-' || v_pago.id::text,
    'Conciliado', v_pago.id, v_uid, now(), v_uid
  )
  RETURNING id INTO v_mov_id;
  v_resp := jsonb_build_object(
    'pago_id', v_pago.id,
    'movimiento_id', v_mov_id,
    'saldo_cuenta_restante', v_saldo_cuenta - p_monto
  );
  -- BL-04: almacena la respuesta para los reintentos con la misma llave
  -- (no-op cuando p_request_id viene NULL).
  PERFORM public.idempotency_store(p_request_id, v_resp);
  RETURN v_resp;
END;
$$;
CREATE FUNCTION public.eliminar_embarque_completo(p_embarque_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_uemail text;
  v_now timestamptz := now();
  v_expediente text;
  v_org uuid;
  v_cotizacion_id uuid;
  v_estado text;
  v_cerrado_at timestamptz;
  v_facturas int;
  v_cxp int;
  v_pagos_cxc int;
  v_pagos_cxp int;
  v_ncs_cxc int;
  v_ncs_cxp int;
  v_comisiones int;
  v_proformas int;
  v_remaining int;
  v_motivos jsonb;
BEGIN
  SELECT expediente, organization_id, cotizacion_id, estado, cerrado_at
    INTO v_expediente, v_org, v_cotizacion_id, v_estado, v_cerrado_at
  FROM public.embarques WHERE id = p_embarque_id;
  IF v_expediente IS NULL THEN
    RAISE EXCEPTION 'Embarque no encontrado';
  END IF;
  -- FIX C1 · Guard de rol + tenant (S5-01).
  IF NOT (
    public.has_role(v_uid, 'super_admin'::app_role)
    OR (v_org = public.current_user_org_id()
        AND (public.has_role(v_uid, 'admin'::app_role)
             OR public.has_role(v_uid, 'operador'::app_role)))
  ) THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: permisos insuficientes para eliminar embarques (se requiere rol admin u operador de la organización del embarque)'
      USING ERRCODE = '42501';
  END IF;
  SELECT count(*) INTO v_facturas
  FROM public.facturas
  WHERE embarque_id = p_embarque_id AND deleted_at IS NULL AND estado NOT IN ('Cancelada','Sustituida');
  SELECT count(*) INTO v_cxp
  FROM public.proveedor_facturas
  WHERE embarque_id = p_embarque_id AND deleted_at IS NULL;
  SELECT count(*) INTO v_pagos_cxc
  FROM public.pagos_factura pf
  JOIN public.facturas f ON f.id = pf.factura_id
  WHERE f.embarque_id = p_embarque_id AND pf.deleted_at IS NULL;
  SELECT count(*) INTO v_pagos_cxp
  FROM public.pagos_proveedor pp
  JOIN public.proveedor_facturas pf ON pf.id = pp.proveedor_factura_id
  WHERE pf.embarque_id = p_embarque_id AND pp.deleted_at IS NULL;
  SELECT count(*) INTO v_ncs_cxc
  FROM public.factura_notas_credito nc
  JOIN public.facturas f ON f.id = nc.factura_id
  WHERE f.embarque_id = p_embarque_id AND nc.deleted_at IS NULL;
  SELECT count(*) INTO v_ncs_cxp
  FROM public.proveedor_notas_credito nc
  JOIN public.proveedor_facturas pf ON pf.id = nc.proveedor_factura_id
  WHERE pf.embarque_id = p_embarque_id AND nc.deleted_at IS NULL;
  SELECT count(*) INTO v_comisiones
  FROM public.comisiones_devengadas
  WHERE embarque_id = p_embarque_id
    AND definitiva = true;
  SELECT count(*) INTO v_proformas
  FROM public.proformas
  WHERE embarque_id = p_embarque_id
    AND deleted_at IS NULL
    AND COALESCE(estado_proforma, 'pendiente') NOT IN ('cancelada','facturada');
  IF v_facturas > 0
     OR v_cxp > 0
     OR v_pagos_cxc > 0
     OR v_pagos_cxp > 0
     OR v_ncs_cxc > 0
     OR v_ncs_cxp > 0
     OR v_comisiones > 0
     OR v_proformas > 0
     OR v_estado = 'Cerrado'
     OR v_cerrado_at IS NOT NULL
  THEN
    v_motivos := jsonb_build_object(
      'facturas', v_facturas,
      'cxp', v_cxp,
      'pagos_cxc', v_pagos_cxc,
      'pagos_cxp', v_pagos_cxp,
      'notas_credito_cxc', v_ncs_cxc,
      'notas_credito_cxp', v_ncs_cxp,
      'comisiones_definitivas', v_comisiones,
      'proformas', v_proformas,
      'cerrado', (v_estado = 'Cerrado' OR v_cerrado_at IS NOT NULL),
      'expediente', v_expediente
    );
    RAISE EXCEPTION 'LC_EMBARQUE_BLOQUEADO: el embarque % tiene dependencias fiscales o está cerrado', v_expediente
      USING HINT = v_motivos::text,
            ERRCODE = 'check_violation';
  END IF;
  UPDATE public.conceptos_venta        SET deleted_at = v_now, deleted_by = v_uid WHERE embarque_id = p_embarque_id AND deleted_at IS NULL;
  UPDATE public.conceptos_costo        SET deleted_at = v_now, deleted_by = v_uid WHERE embarque_id = p_embarque_id AND deleted_at IS NULL;
  UPDATE public.documentos_embarque    SET deleted_at = v_now, deleted_by = v_uid WHERE embarque_id = p_embarque_id AND deleted_at IS NULL;
  UPDATE public.notas_embarque         SET deleted_at = v_now, deleted_by = v_uid WHERE embarque_id = p_embarque_id AND deleted_at IS NULL;
  UPDATE public.eventos_embarque       SET deleted_at = v_now, deleted_by = v_uid WHERE embarque_id = p_embarque_id AND deleted_at IS NULL;
  UPDATE public.embarque_contenedores  SET deleted_at = v_now, deleted_by = v_uid WHERE embarque_id = p_embarque_id AND deleted_at IS NULL;
  UPDATE public.seguros_embarque       SET deleted_at = v_now                    WHERE embarque_id = p_embarque_id AND deleted_at IS NULL;
  UPDATE public.embarques
     SET deleted_at = v_now, deleted_by = v_uid
   WHERE id = p_embarque_id AND deleted_at IS NULL;
  IF v_cotizacion_id IS NOT NULL THEN
    SELECT count(*) INTO v_remaining
    FROM public.embarques
    WHERE cotizacion_id = v_cotizacion_id AND deleted_at IS NULL;
    IF v_remaining = 0 THEN
      UPDATE public.cotizaciones
         SET estado = 'Aceptada',
             embarque_id = NULL,
             updated_at = now()
       WHERE id = v_cotizacion_id
         AND (estado <> 'Aceptada' OR embarque_id IS NOT NULL);
      UPDATE public.embarques
         SET cotizacion_id = NULL
       WHERE id = p_embarque_id
         AND cotizacion_id IS NOT NULL;
    END IF;
  END IF;
  BEGIN
    SELECT email INTO v_uemail FROM auth.users WHERE id = v_uid;
  EXCEPTION WHEN OTHERS THEN v_uemail := NULL;
  END;
  IF v_uid IS NOT NULL THEN
    INSERT INTO public.bitacora_actividad
      (usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles, organization_id)
    VALUES
      (v_uid, v_uemail, 'eliminar_embarque', 'embarques', p_embarque_id, v_expediente,
       jsonb_build_object(
         'cotizacion_revertida', (v_cotizacion_id IS NOT NULL AND v_remaining = 0),
         'estado_previo', v_estado
       ),
       v_org);
  END IF;
END;
$$;
CREATE FUNCTION public.eliminar_factura_borrador(p_factura_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_factura                public.facturas;
  v_caller_org             uuid;
  v_candidatas             uuid[] := ARRAY[]::uuid[];
  v_revertidas             uuid[] := ARRAY[]::uuid[];
  v_conservadas            uuid[] := ARRAY[]::uuid[];
  v_pid                    uuid;
  v_tiene_hermano_vivo     boolean;
BEGIN
  IF p_factura_id IS NULL THEN
    RAISE EXCEPTION 'factura_id es obligatorio';
  END IF;
  SELECT * INTO v_factura FROM public.facturas WHERE id = p_factura_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Factura no encontrada';
  END IF;
  IF v_factura.estado <> 'Borrador'::estado_factura THEN
    RAISE EXCEPTION 'Sólo se pueden eliminar facturas en estado Borrador (estado actual: %)', v_factura.estado;
  END IF;
  IF v_factura.facturapi_id IS NOT NULL OR v_factura.uuid_fiscal IS NOT NULL THEN
    RAISE EXCEPTION 'La factura ya fue timbrada y no puede eliminarse';
  END IF;
  v_caller_org := public.current_user_org_id();
  IF NOT (public.has_role(auth.uid(), 'admin_org'::app_role)
          OR public.has_role(auth.uid(), 'contador'::app_role)
          OR public.has_role(auth.uid(), 'super_admin'::app_role)) THEN
    RAISE EXCEPTION 'No tienes permiso para eliminar borradores de factura';
  END IF;
  IF NOT public.has_role(auth.uid(), 'super_admin'::app_role)
     AND v_factura.organization_id IS DISTINCT FROM v_caller_org THEN
    RAISE EXCEPTION 'No puedes eliminar borradores de otra organización';
  END IF;
  PERFORM public._assert_writer(v_factura.organization_id);
  -- Fuente 1: link directo (proformas.factura_id) — reservado a futuro.
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
    INTO v_candidatas
  FROM public.proformas
  WHERE factura_id = p_factura_id;
  -- Fuente 2: link inverso (facturas.proforma_id) — caso 1:1.
  IF v_factura.proforma_id IS NOT NULL THEN
    v_candidatas := array(SELECT DISTINCT unnest(v_candidatas || ARRAY[v_factura.proforma_id]));
  END IF;
  -- Fuente 3 (H7): conceptos_factura.proforma_id_origen — fuente autoritativa
  -- para borradores consolidados. Reemplaza la lectura previa de bitacora_actividad,
  -- que era un log de auditoría inmutable, no una fuente de verdad.
  v_candidatas := array(
    SELECT DISTINCT x
    FROM unnest(
      v_candidatas || COALESCE(
        (
          SELECT array_agg(DISTINCT cf.proforma_id_origen)
          FROM public.conceptos_factura cf
          WHERE cf.factura_id = p_factura_id
            AND cf.proforma_id_origen IS NOT NULL
            AND cf.deleted_at IS NULL
        ),
        ARRAY[]::uuid[]
      )
    ) AS t(x)
    WHERE x IS NOT NULL
  );
  -- Bug 3: sibling-alive check por proforma.
  -- Sólo revertimos las que NO tienen otra factura viva consumiéndolas
  -- (directamente vía facturas.proforma_id o vía conceptos_factura.proforma_id_origen).
  IF array_length(v_candidatas, 1) IS NOT NULL THEN
    FOREACH v_pid IN ARRAY v_candidatas LOOP
      SELECT EXISTS (
        SELECT 1
        FROM public.facturas f
        WHERE f.id <> p_factura_id
          AND f.deleted_at IS NULL
          AND f.estado NOT IN ('Cancelada'::estado_factura, 'Sustituida'::estado_factura)
          AND (
            f.proforma_id = v_pid
            OR EXISTS (
              SELECT 1
              FROM public.conceptos_factura cf
              WHERE cf.factura_id = f.id
                AND cf.proforma_id_origen = v_pid
                AND cf.deleted_at IS NULL
            )
          )
      ) INTO v_tiene_hermano_vivo;
      IF v_tiene_hermano_vivo THEN
        v_conservadas := v_conservadas || v_pid;
      ELSE
        v_revertidas := v_revertidas || v_pid;
      END IF;
    END LOOP;
  END IF;
  IF array_length(v_revertidas, 1) IS NOT NULL THEN
    UPDATE public.proformas
       SET factura_id        = NULL,
           estado_proforma   = 'pendiente',
           fecha_facturacion = NULL,
           updated_at        = now()
     WHERE id = ANY(v_revertidas);
  END IF;
  DELETE FROM public.conceptos_factura WHERE factura_id = p_factura_id;
  DELETE FROM public.facturas WHERE id = p_factura_id;
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles
  )
  VALUES (
    v_factura.organization_id, auth.uid(),
    (SELECT email FROM auth.users WHERE id = auth.uid()),
    'factura.borrador_eliminado', 'facturacion', p_factura_id, v_factura.numero,
    jsonb_build_object(
      'proformas_revertidas', v_revertidas,
      'proformas_conservadas_por_sibling', v_conservadas,
      'origen', v_factura.origen
    )
  );
END $$;
CREATE FUNCTION public.eliminar_organizacion_vacia(p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF NOT public.has_role(auth.uid(), 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'No autorizado para eliminar organizaciones' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_org_id = '00000000-0000-0000-0000-000000000001' THEN
    RAISE EXCEPTION 'No se puede eliminar la organización principal del sistema' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id) THEN
    RAISE EXCEPTION 'Organización no encontrada' USING ERRCODE = 'no_data_found';
  END IF;
  SELECT COALESCE(SUM(n), 0) INTO v_count
  FROM (
    SELECT COUNT(*) AS n FROM public.embarques          WHERE organization_id = p_org_id AND deleted_at IS NULL
    UNION ALL SELECT COUNT(*) FROM public.clientes       WHERE organization_id = p_org_id AND deleted_at IS NULL
    UNION ALL SELECT COUNT(*) FROM public.proveedores    WHERE organization_id = p_org_id AND deleted_at IS NULL
    UNION ALL SELECT COUNT(*) FROM public.cotizaciones   WHERE organization_id = p_org_id AND deleted_at IS NULL
    UNION ALL SELECT COUNT(*) FROM public.proformas     WHERE organization_id = p_org_id AND deleted_at IS NULL
    UNION ALL SELECT COUNT(*) FROM public.facturas       WHERE organization_id = p_org_id AND deleted_at IS NULL
    UNION ALL SELECT COUNT(*) FROM public.pagos_proveedor WHERE organization_id = p_org_id AND deleted_at IS NULL
    UNION ALL SELECT COUNT(*) FROM public.pagos_factura  WHERE organization_id = p_org_id AND deleted_at IS NULL
    UNION ALL SELECT COUNT(*) FROM public.cuentas_bancarias WHERE organization_id = p_org_id
    UNION ALL SELECT COUNT(*) FROM public.crm_oportunidades WHERE organization_id = p_org_id AND deleted_at IS NULL
    UNION ALL SELECT COUNT(*) FROM public.crm_leads       WHERE organization_id = p_org_id AND deleted_at IS NULL
  ) t;
  IF v_count > 0 THEN
    RAISE EXCEPTION 'La organización tiene % registro(s) de negocio. Solo se pueden eliminar organizaciones vacías; desactívala en su lugar.', v_count
      USING ERRCODE = 'check_violation';
  END IF;
  DELETE FROM public.bitacora_actividad WHERE organization_id = p_org_id;
  DELETE FROM public.configuracion      WHERE organization_id = p_org_id;
  DELETE FROM public.organization_members WHERE organization_id = p_org_id;
  BEGIN
    DELETE FROM public.organizations WHERE id = p_org_id;
  EXCEPTION WHEN foreign_key_violation THEN
    RAISE EXCEPTION 'La organización tiene datos en otras tablas y no se puede eliminar. Desactívala en su lugar.'
      USING ERRCODE = 'foreign_key_violation';
  END;
END;
$$;
CREATE FUNCTION public.eliminar_pago_cliente(_pago_id uuid, _motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_pago record;
  v_baja int := 0;
  v_desvinculados int := 0;
BEGIN
  SELECT id, factura_id, organization_id, deleted_at, uuid_rep, rep_cancelado_en, monto, moneda
    INTO v_pago
  FROM public.pagos_factura
  WHERE id = _pago_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_PAGO_NO_ENCONTRADO: el pago % no existe', _pago_id USING ERRCODE = 'P0002';
  END IF;
  IF v_pago.deleted_at IS NOT NULL THEN
    -- Idempotente: no se vuelve a tocar el banco ni la bitacora.
    RETURN jsonb_build_object(
      'pago_id', _pago_id, 'ya_eliminado', true,
      'movimientos_baja', 0, 'movimientos_desvinculados', 0
    );
  END IF;
  IF NOT public.has_role(v_uid, 'super_admin'::app_role)
     AND v_pago.organization_id IS DISTINCT FROM public.current_user_org_id() THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: el pago pertenece a otra organizacion'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public.es_escritor_financiero(v_uid) THEN
    RAISE EXCEPTION 'LC_PAGO_SIN_PERMISO: tu rol no puede eliminar pagos'
      USING ERRCODE = '42501';
  END IF;
  IF v_pago.uuid_rep IS NOT NULL AND v_pago.rep_cancelado_en IS NULL THEN
    RAISE EXCEPTION 'LC_PAGO_CON_REP_VIVO: cancela el complemento de pago (REP) antes de eliminar el pago'
      USING ERRCODE = '42501';
  END IF;
  UPDATE public.pagos_factura
     SET deleted_at = now(), deleted_by = v_uid
   WHERE id = _pago_id AND deleted_at IS NULL;
  -- 1) Movimiento generado por el sistema: se da de baja con el pago.
  WITH baja AS (
    UPDATE public.bbva_movimientos
       SET deleted_at = now(), deleted_by = v_uid
     WHERE pago_factura_id = _pago_id
       AND deleted_at IS NULL
       AND hash_dedupe = 'cobro-' || _pago_id::text
    RETURNING 1
  )
  SELECT count(*) INTO v_baja FROM baja;
  -- 2) Movimiento importado del estado de cuenta: se conserva y se desvincula.
  WITH libre AS (
    UPDATE public.bbva_movimientos
       SET pago_factura_id = NULL,
           estado_conciliacion = 'Pendiente'::estado_conciliacion,
           conciliado_por = NULL,
           conciliado_at = NULL
     WHERE pago_factura_id = _pago_id
       AND deleted_at IS NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_desvinculados FROM libre;
  INSERT INTO public.bitacora_actividad
    (usuario_id, usuario_email, accion, modulo, entidad_id, detalles, organization_id)
  VALUES (
    COALESCE(v_uid, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE((SELECT u.email FROM auth.users u WHERE u.id = v_uid), 'sistema'),
    'eliminar_pago', 'facturacion', v_pago.factura_id,
    jsonb_build_object(
      'pago_id', _pago_id,
      'monto', v_pago.monto,
      'moneda', v_pago.moneda,
      'motivo', _motivo,
      'movimientos_baja', v_baja,
      'movimientos_desvinculados', v_desvinculados,
      'atomico', true
    ),
    v_pago.organization_id
  );
  RETURN jsonb_build_object(
    'pago_id', _pago_id,
    'factura_id', v_pago.factura_id,
    'ya_eliminado', false,
    'movimientos_baja', v_baja,
    'movimientos_desvinculados', v_desvinculados
  );
END;
$$;
CREATE FUNCTION public.eliminar_pago_proveedor(_pago_id uuid, _motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_pago record;
  v_baja int := 0;
  v_desvinculados int := 0;
  v_costos int := 0;
  v_anticipos int := 0;
BEGIN
  SELECT id, proveedor_factura_id, organization_id, deleted_at, monto, moneda
    INTO v_pago
  FROM public.pagos_proveedor
  WHERE id = _pago_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_PAGO_NO_ENCONTRADO: el pago % no existe', _pago_id USING ERRCODE = 'P0002';
  END IF;
  IF v_pago.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'pago_id', _pago_id, 'ya_eliminado', true,
      'movimientos_baja', 0, 'movimientos_desvinculados', 0, 'costos_recalculados', 0,
      'anticipos_revertidos', 0
    );
  END IF;
  IF NOT public.has_role(v_uid, 'super_admin'::app_role)
     AND v_pago.organization_id IS DISTINCT FROM public.current_user_org_id() THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: el pago pertenece a otra organizacion'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_any_role_in_org_exact(v_uid,
       ARRAY['super_admin','admin','admin_org','contador','tesorero','ejecutivo_cobranza']::public.app_role[],
       v_pago.organization_id) THEN
    RAISE EXCEPTION 'LC_PAGO_SIN_PERMISO: tu rol no puede eliminar pagos'
      USING ERRCODE = '42501';
  END IF;
  UPDATE public.pagos_proveedor
     SET deleted_at = now(), deleted_by = v_uid
   WHERE id = _pago_id AND deleted_at IS NULL;
  WITH rev AS (
    UPDATE public.anticipos_aplicaciones
       SET deleted_at = now(), deleted_by = v_uid, updated_at = now()
     WHERE pago_proveedor_id = _pago_id
       AND deleted_at IS NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_anticipos FROM rev;
  -- Ola E1 · N21: sólo los movimientos GENERADOS por el pago (hash_dedupe) se
  -- dan de baja; los movimientos bancarios reales del estado de cuenta se
  -- desvinculan más abajo (nunca se borran).
  WITH baja AS (
    UPDATE public.bbva_movimientos
       SET deleted_at = now(), deleted_by = v_uid
     WHERE deleted_at IS NULL
       AND hash_dedupe = 'pago-' || _pago_id::text
    RETURNING 1
  )
  SELECT count(*) INTO v_baja FROM baja;
  WITH libre AS (
    UPDATE public.bbva_movimientos
       SET pago_proveedor_id = NULL,
           estado_conciliacion = 'Pendiente'::estado_conciliacion,
           conciliado_por = NULL,
           conciliado_at = NULL
     WHERE pago_proveedor_id = _pago_id
       AND deleted_at IS NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_desvinculados FROM libre;
  SELECT count(DISTINCT pfc.concepto_costo_id) INTO v_costos
  FROM public.proveedor_facturas_conceptos pfc
  WHERE pfc.proveedor_factura_id = v_pago.proveedor_factura_id
    AND pfc.concepto_costo_id IS NOT NULL;
  INSERT INTO public.bitacora_actividad
    (usuario_id, usuario_email, accion, modulo, entidad_id, detalles, organization_id)
  VALUES (
    COALESCE(v_uid, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE((SELECT u.email FROM auth.users u WHERE u.id = v_uid), 'sistema'),
    'eliminar_pago', 'cxp', v_pago.proveedor_factura_id,
    jsonb_build_object(
      'pago_id', _pago_id,
      'monto', v_pago.monto,
      'moneda', v_pago.moneda,
      'motivo', _motivo,
      'movimientos_baja', v_baja,
      'movimientos_desvinculados', v_desvinculados,
      'costos_recalculados', v_costos,
      'anticipos_revertidos', v_anticipos,
      'atomico', true
    ),
    v_pago.organization_id
  );
  RETURN jsonb_build_object(
    'pago_id', _pago_id,
    'proveedor_factura_id', v_pago.proveedor_factura_id,
    'ya_eliminado', false,
    'movimientos_baja', v_baja,
    'movimientos_desvinculados', v_desvinculados,
    'costos_recalculados', v_costos,
    'anticipos_revertidos', v_anticipos
  );
END;
$$;
CREATE FUNCTION public.eliminar_proforma_rpc(p_proforma_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_numero text;
  v_estado text;
  v_factura uuid;
  v_factura2 uuid;
  v_folio_ext text;
  v_deleted timestamptz;
  v_embarque uuid;
BEGIN
  SELECT organization_id, numero, estado_proforma, factura_id, factura_secundaria_id,
         folio_factura_externa, deleted_at, embarque_id
    INTO v_org, v_numero, v_estado, v_factura, v_factura2, v_folio_ext, v_deleted, v_embarque
  FROM public.proformas WHERE id = p_proforma_id
  FOR UPDATE;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_PROFORMA_NO_ENCONTRADA';
  END IF;
  IF auth.uid() IS NOT NULL AND NOT public.is_org_member(v_org) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  IF v_deleted IS NOT NULL THEN
    RETURN jsonb_build_object('numero', v_numero, 'embarque_id', v_embarque, 'eliminada', false);
  END IF;
  -- RG10: el folio externo suelto ya NO bloquea.
  -- Ola 4 · N37: tampoco bloquea una factura MUERTA (borrada, cancelada o
  -- sustituida) — sólo una factura viva ligada o el estado 'facturada'.
  IF EXISTS (
       SELECT 1 FROM public.facturas f
       WHERE f.id IN (v_factura, v_factura2)
         AND f.deleted_at IS NULL
         AND f.estado NOT IN ('Cancelada','Sustituida')
     )
     OR lower(COALESCE(v_estado, '')) = 'facturada' THEN
    RAISE EXCEPTION 'LC_PROFORMA_FACTURADA';
  END IF;
  UPDATE public.conceptos_venta
     SET estado_facturacion = 'pendiente', proforma_id = NULL
   WHERE proforma_id = p_proforma_id;
  UPDATE public.proformas
     SET deleted_at = now(), deleted_by = auth.uid()
   WHERE id = p_proforma_id;
  RETURN jsonb_build_object('numero', v_numero, 'embarque_id', v_embarque, 'eliminada', true);
END;
$$;
CREATE FUNCTION public.email_queue_dispatch() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pgmq.q_auth_emails)
     AND NOT EXISTS (SELECT 1 FROM pgmq.q_transactional_emails) THEN
    BEGIN
      PERFORM pg_catalog.pg_advisory_xact_lock(7700000000000001);
      IF EXISTS (SELECT 1 FROM pgmq.q_auth_emails)
         OR EXISTS (SELECT 1 FROM pgmq.q_transactional_emails) THEN
        RETURN;
      END IF;
      PERFORM cron.unschedule('process-email-queue');
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'email_queue_dispatch: cron unschedule failed: %', SQLERRM;
    END;
    RETURN;
  END IF;
  IF (SELECT retry_after_until FROM public.email_send_state WHERE id = 1) > now() THEN
    RETURN;
  END IF;
  PERFORM net.http_post(
    url := 'https://eorqadkulqtneqjbsblk.supabase.co/functions/v1/process-email-queue',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Lovable-Context', 'cron',
      'Authorization', 'Bearer ' || (
        SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'email_queue_service_role_key'
      )
    ),
    body := '{}'::jsonb
  );
END;
$$;
CREATE FUNCTION public.email_send_log_touch(p_message_id text, p_template text, p_recipient text, p_status text, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO public.email_send_log
    (message_id, template_name, recipient_email, status, error_message, intentos)
  VALUES
    (p_message_id, p_template, p_recipient, p_status, p_error, 1)
  ON CONFLICT (message_id) DO UPDATE SET
    status = EXCLUDED.status,
    error_message = EXCLUDED.error_message,
    -- Sólo los estados de fallo consumen un intento (retry/DLQ de la cola).
    intentos = CASE
      WHEN EXCLUDED.status IN ('failed', 'rate_limited')
        THEN public.email_send_log.intentos + 1
      ELSE public.email_send_log.intentos
    END;
END;
$$;
CREATE FUNCTION public.embarque_admin_pendientes_resumen(p_embarque_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cxc_pendiente numeric := 0;
  v_cxp_pendiente numeric := 0;
  v_docs_faltantes int := 0;
  v_venta_no_facturada numeric := 0;
  v_pendientes int := 0;
BEGIN
  SELECT COALESCE(SUM(f.total),0) - COALESCE((
    SELECT SUM(pf.monto)
    FROM pagos_factura pf
    JOIN facturas fi ON fi.id = pf.factura_id
    WHERE fi.embarque_id = p_embarque_id AND fi.deleted_at IS NULL
      AND fi.estado NOT IN ('Cancelada','Pagada')
  ),0)
  INTO v_cxc_pendiente
  FROM facturas f
  WHERE f.embarque_id = p_embarque_id AND f.deleted_at IS NULL
    AND f.estado NOT IN ('Cancelada','Pagada');
  SELECT COALESCE(SUM(pf.total),0) - COALESCE((
    SELECT SUM(pp.monto)
    FROM pagos_proveedor pp
    JOIN proveedor_facturas pfx ON pfx.id = pp.proveedor_factura_id
    WHERE pfx.embarque_id = p_embarque_id AND pfx.deleted_at IS NULL AND pfx.estado <> 'Cancelada'
  ),0)
  INTO v_cxp_pendiente
  FROM proveedor_facturas pf
  WHERE pf.embarque_id = p_embarque_id AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada';
  SELECT COUNT(*) INTO v_docs_faltantes
  FROM documentos_embarque
  WHERE embarque_id = p_embarque_id
    AND deleted_at IS NULL
    AND (archivo IS NULL OR archivo = '')
    AND estado <> 'No aplica';
  SELECT GREATEST(
    COALESCE((SELECT SUM(total) FROM conceptos_venta WHERE embarque_id = p_embarque_id AND deleted_at IS NULL),0)
    - COALESCE((SELECT SUM(total) FROM facturas WHERE embarque_id = p_embarque_id AND deleted_at IS NULL AND estado <> 'Cancelada'),0),
  0)
  INTO v_venta_no_facturada;
  v_pendientes :=
    (CASE WHEN v_cxc_pendiente > 0.01 THEN 1 ELSE 0 END) +
    (CASE WHEN v_cxp_pendiente > 0.01 THEN 1 ELSE 0 END) +
    (CASE WHEN v_docs_faltantes > 0 THEN 1 ELSE 0 END) +
    (CASE WHEN v_venta_no_facturada > 0.01 THEN 1 ELSE 0 END);
  RETURN jsonb_build_object(
    'pendientes', v_pendientes,
    'cxc_pendiente', GREATEST(v_cxc_pendiente, 0),
    'cxp_pendiente', v_cxp_pendiente,
    'docs_faltantes', v_docs_faltantes,
    'venta_no_facturada', v_venta_no_facturada
  );
END;
$$;
CREATE FUNCTION public.embarque_docs_faltantes(p_embarque_id uuid, p_estado_destino text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_modo text;
  v_org_id uuid;
  v_required text[];
  v_faltantes text[];
BEGIN
  IF p_embarque_id IS NULL OR p_estado_destino IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;
  SELECT modo::text, organization_id INTO v_modo, v_org_id
  FROM embarques WHERE id = p_embarque_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Embarque no encontrado';
  END IF;
  PERFORM public._assert_internal_reader(v_org_id);
  v_required := public._docs_requeridos_por_estado(v_modo, p_estado_destino);
  IF v_required IS NULL OR array_length(v_required, 1) IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;
  SELECT COALESCE(array_agg(req ORDER BY req), ARRAY[]::text[])
  INTO v_faltantes
  FROM unnest(v_required) AS req
  WHERE NOT EXISTS (
    SELECT 1 FROM documentos_embarque d
    WHERE d.embarque_id = p_embarque_id
      AND d.nombre = req
      AND d.deleted_at IS NULL
      AND (d.archivo IS NOT NULL OR d.estado = 'No aplica')
  );
  RETURN v_faltantes;
END;
$$;
CREATE FUNCTION public.embarque_estado_financiero(_embarque_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_costo_pres numeric; v_costo_capturado numeric; v_costo_pagado numeric;
  v_tiene_proforma boolean; v_tiene_factura boolean; v_factura_pagada boolean;
  v_factura_total numeric; v_factura_cobrado numeric;
  v_semaforo_costo text; v_semaforo_facturacion text;
BEGIN
  SELECT COALESCE(SUM(monto),0) INTO v_costo_pres
    FROM public.conceptos_costo WHERE embarque_id=_embarque_id AND deleted_at IS NULL;
  SELECT COALESCE(SUM(total),0) INTO v_costo_capturado
    FROM public.proveedor_facturas
    WHERE embarque_id=_embarque_id AND deleted_at IS NULL AND estado <> 'Cancelada';
  SELECT COALESCE(SUM(COALESCE(pp.monto_en_moneda_factura, pp.monto)),0) INTO v_costo_pagado
    FROM public.pagos_proveedor pp
    JOIN public.proveedor_facturas pf ON pf.id=pp.proveedor_factura_id
    WHERE pf.embarque_id=_embarque_id AND pf.deleted_at IS NULL AND pp.deleted_at IS NULL;
  SELECT EXISTS(SELECT 1 FROM public.proformas
    WHERE embarque_id=_embarque_id AND deleted_at IS NULL
      AND lower(COALESCE(estado_aprobacion,''))='aprobada') INTO v_tiene_proforma;
  SELECT
    EXISTS(SELECT 1 FROM public.facturas
      WHERE embarque_id=_embarque_id AND deleted_at IS NULL
        AND estado::text NOT IN ('Cancelada','Sustituida')),
    COALESCE(SUM(total) FILTER (WHERE estado::text NOT IN ('Cancelada','Sustituida')),0)
    INTO v_tiene_factura, v_factura_total
  FROM public.facturas WHERE embarque_id=_embarque_id AND deleted_at IS NULL;
  SELECT COALESCE(SUM(pf.monto_aplicado_factura),0) INTO v_factura_cobrado
    FROM public.pagos_factura pf
    JOIN public.facturas f ON f.id=pf.factura_id
    WHERE f.embarque_id=_embarque_id AND f.deleted_at IS NULL
      AND pf.deleted_at IS NULL AND f.estado::text NOT IN ('Cancelada','Sustituida');
  v_factura_pagada := v_tiene_factura AND v_factura_cobrado >= v_factura_total AND v_factura_total > 0;
  v_semaforo_costo := CASE
    WHEN v_costo_pres = 0 THEN 'sin_costos'
    WHEN v_costo_capturado = 0 THEN 'pendiente'
    WHEN v_costo_pagado >= v_costo_capturado AND v_costo_capturado > 0 THEN 'pagado'
    WHEN v_costo_capturado > 0 THEN 'capturado'
    ELSE 'pendiente' END;
  v_semaforo_facturacion := CASE
    WHEN v_factura_pagada THEN 'cobrada'
    WHEN v_tiene_factura THEN 'facturada'
    WHEN v_tiene_proforma THEN 'proforma_lista'
    ELSE 'sin_proforma' END;
  RETURN jsonb_build_object(
    'costo', jsonb_build_object(
      'semaforo',v_semaforo_costo,'presupuestado',v_costo_pres,
      'capturado',v_costo_capturado,'pagado',v_costo_pagado),
    'facturacion', jsonb_build_object(
      'semaforo',v_semaforo_facturacion,'tiene_proforma',v_tiene_proforma,
      'tiene_factura',v_tiene_factura,'total_facturado',v_factura_total,
      'cobrado',v_factura_cobrado,'saldo',GREATEST(v_factura_total-v_factura_cobrado,0)));
END;
$$;
CREATE FUNCTION public.embarque_operativo_completo(p_embarque_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_docs_faltantes int;
  v_cont_sin_fechas int;
  v_costos_sin_factura int;
  v_buzon_pendiente int;
BEGIN
  IF p_embarque_id IS NULL THEN RETURN false; END IF;
  SELECT COUNT(*) INTO v_docs_faltantes
    FROM documentos_embarque de
   WHERE de.embarque_id = p_embarque_id
     AND de.deleted_at IS NULL
     AND (de.archivo IS NULL OR de.archivo = '')
     AND de.estado <> 'No aplica';
  SELECT COUNT(*) INTO v_cont_sin_fechas
    FROM embarque_contenedores ec
   WHERE ec.embarque_id = p_embarque_id
     AND ec.deleted_at IS NULL
     AND (ec.fecha_descarga IS NULL OR ec.fecha_devolucion IS NULL);
  -- Facturas de proveedor: cada concepto de costo debe estar respaldado.
  SELECT COUNT(*) INTO v_costos_sin_factura
    FROM conceptos_costo cc
   WHERE cc.embarque_id = p_embarque_id
     AND cc.deleted_at IS NULL
     AND NOT EXISTS (
       SELECT 1 FROM proveedor_facturas_conceptos pfc
        JOIN proveedor_facturas pf2 ON pf2.id = pfc.proveedor_factura_id
       WHERE pfc.concepto_costo_id = cc.id
         AND pf2.deleted_at IS NULL
         AND pf2.estado <> 'Cancelada');
  -- Buzón CxP: nada pendiente de capturar.
  SELECT COUNT(*) INTO v_buzon_pendiente
    FROM embarque_facturas_entrantes efe
   WHERE efe.embarque_id = p_embarque_id
     AND efe.deleted_at IS NULL
     AND efe.proveedor_factura_id IS NULL;
  RETURN v_docs_faltantes = 0
     AND v_cont_sin_fechas = 0
     AND v_costos_sin_factura = 0
     AND v_buzon_pendiente = 0;
END;
$$;
CREATE FUNCTION public.embarques_admin_pendientes_count() RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_count int := 0;
BEGIN
  v_org := public.current_user_org_id();
  IF v_org IS NULL THEN
    RETURN 0;
  END IF;
  SELECT COUNT(*) INTO v_count
  FROM embarques e
  WHERE e.organization_id = v_org
    AND e.estado IN ('Entregado', 'EIR', 'Por liquidar')
    AND e.deleted_at IS NULL
    AND (
      EXISTS (
        SELECT 1 FROM facturas f
        WHERE f.embarque_id = e.id AND f.deleted_at IS NULL
          AND f.estado NOT IN ('Cancelada','Pagada')
        GROUP BY f.embarque_id
        HAVING SUM(f.total) > COALESCE((
          SELECT SUM(pf.monto) FROM pagos_factura pf
          JOIN facturas fi ON fi.id = pf.factura_id
          WHERE fi.embarque_id = e.id AND fi.deleted_at IS NULL
            AND fi.estado NOT IN ('Cancelada','Pagada')
        ),0) + 0.01
      )
      OR EXISTS (
        SELECT 1 FROM proveedor_facturas pf
        WHERE pf.embarque_id = e.id AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada'
        GROUP BY pf.embarque_id
        HAVING SUM(pf.total) > COALESCE((
          SELECT SUM(pp.monto) FROM pagos_proveedor pp
          JOIN proveedor_facturas pfx ON pfx.id = pp.proveedor_factura_id
          WHERE pfx.embarque_id = e.id AND pfx.deleted_at IS NULL AND pfx.estado <> 'Cancelada'
        ),0) + 0.01
      )
      OR EXISTS (
        SELECT 1 FROM documentos_embarque de
        WHERE de.embarque_id = e.id AND de.deleted_at IS NULL
          AND (de.archivo IS NULL OR de.archivo = '')
          AND de.estado <> 'No aplica'
      )
      OR (
        COALESCE((SELECT SUM(total) FROM conceptos_venta WHERE embarque_id = e.id AND deleted_at IS NULL),0)
        > COALESCE((SELECT SUM(total) FROM facturas WHERE embarque_id = e.id AND deleted_at IS NULL AND estado <> 'Cancelada'),0) + 0.01
      )
    );
  RETURN v_count;
END;
$$;
CREATE FUNCTION public.embarques_alertas_ids() RETURNS TABLE(embarque_id uuid, tipo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.id, 'demora'::text AS tipo
  FROM embarques e
  WHERE e.deleted_at IS NULL
    AND e.eta IS NOT NULL
    AND (current_date - e.eta) >= 7
    AND CASE
       WHEN e.estado IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado') THEN e.estado::text
       WHEN e.modo = 'Marítimo' AND e.tipo = 'Importación'
            AND e.etd IS NOT NULL AND e.eta IS NOT NULL THEN
         CASE
           WHEN current_date < e.etd THEN 'Confirmado'
           WHEN current_date >= e.etd AND current_date < e.eta THEN 'En Tránsito'
           WHEN current_date >= e.eta THEN 'Arribo'
           ELSE e.estado::text
         END
       ELSE e.estado::text
     END = 'Arribo'
    AND (e.organization_id = public.org_scope())
  UNION ALL
  SELECT DISTINCT e.id, 'garantia'::text
  FROM embarque_garantias_contenedor g
  JOIN embarques e ON e.id = g.embarque_id
  WHERE g.estado = 'depositado'
    AND g.fecha_deposito IS NOT NULL
    AND (current_date - g.fecha_deposito) > 30
    AND e.deleted_at IS NULL
    AND (e.organization_id = public.org_scope())
  UNION ALL
  SELECT e.id,
         CASE WHEN e.estado = 'Por liquidar' THEN 'admin_pendiente' ELSE 'cierre_operativo' END::text
  FROM embarques e
  WHERE e.deleted_at IS NULL
    AND e.estado IN ('Entregado', 'EIR', 'Por liquidar')
    AND (e.organization_id = public.org_scope())
    AND (
      EXISTS (
        SELECT 1 FROM facturas f
        WHERE f.embarque_id = e.id AND f.deleted_at IS NULL
          AND f.estado NOT IN ('Cancelada','Pagada')
        GROUP BY f.embarque_id
        HAVING SUM(f.total) > COALESCE((
          SELECT SUM(pf.monto) FROM pagos_factura pf
          JOIN facturas fi ON fi.id = pf.factura_id
          WHERE fi.embarque_id = e.id AND fi.deleted_at IS NULL
            AND fi.estado NOT IN ('Cancelada','Pagada')
        ),0) + 0.01
      )
      OR EXISTS (
        SELECT 1 FROM proveedor_facturas pf
        WHERE pf.embarque_id = e.id AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada'
        GROUP BY pf.embarque_id
        HAVING SUM(pf.total) > COALESCE((
          SELECT SUM(pp.monto) FROM pagos_proveedor pp
          JOIN proveedor_facturas pfx ON pfx.id = pp.proveedor_factura_id
          WHERE pfx.embarque_id = e.id AND pfx.deleted_at IS NULL AND pfx.estado <> 'Cancelada'
        ),0) + 0.01
      )
      OR EXISTS (
        SELECT 1 FROM documentos_embarque de
        WHERE de.embarque_id = e.id AND de.deleted_at IS NULL
          AND (de.archivo IS NULL OR de.archivo = '')
          AND de.estado <> 'No aplica'
      )
      OR (
        COALESCE((SELECT SUM(total) FROM conceptos_venta WHERE embarque_id = e.id AND deleted_at IS NULL),0)
        > COALESCE((SELECT SUM(total) FROM facturas WHERE embarque_id = e.id AND deleted_at IS NULL AND estado <> 'Cancelada'),0) + 0.01
      )
    );
$$;
CREATE FUNCTION public.embarques_assert_cancelacion_sin_cxc_cxp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado = 'Cancelado'::public.estado_embarque
     AND OLD.estado NOT IN ('Cancelado'::public.estado_embarque, 'Cerrado'::public.estado_embarque)
     AND NEW.deleted_at IS NULL
     AND current_setting('app.via_rpc_estado', true) IS DISTINCT FROM '1' THEN
    IF EXISTS (
      SELECT 1 FROM public.facturas f
      WHERE f.embarque_id = NEW.id
        AND f.deleted_at IS NULL
        AND f.estado IN ('Emitida', 'Vencida', 'Parcialmente pagada')
    ) THEN
      RAISE EXCEPTION 'LC_CANCEL_CON_CXC: cancela o sustituye las facturas de cliente antes de cancelar el embarque'
        USING ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.proveedor_facturas pf
      WHERE pf.embarque_id = NEW.id
        AND pf.deleted_at IS NULL
        AND pf.estado <> 'Cancelada'
    ) THEN
      RAISE EXCEPTION 'LC_CANCEL_CON_CXP: cancela las facturas de proveedor antes de cancelar el embarque'
        USING ERRCODE = 'P0001';
    END IF;
    -- N15: facturas de cliente en Borrador y proformas vivas.
    IF EXISTS (
      SELECT 1 FROM public.facturas f
      WHERE f.embarque_id = NEW.id
        AND f.deleted_at IS NULL
        AND f.estado = 'Borrador'
    ) THEN
      RAISE EXCEPTION 'LC_CANCEL_CON_FACTURA_BORRADOR: elimina las facturas en borrador del embarque antes de cancelarlo'
        USING ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.proformas p
      WHERE p.embarque_id = NEW.id
        AND p.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'LC_CANCEL_CON_PROFORMA: cancela o elimina las proformas del embarque antes de cancelarlo'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE FUNCTION public.embarques_freeze_eta_original() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.eta_original := COALESCE(NEW.eta_original, NEW.eta);
    NEW.etd_original := COALESCE(NEW.etd_original, NEW.etd);
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.eta_original IS NOT NULL THEN
      NEW.eta_original := OLD.eta_original;
    ELSE
      NEW.eta_original := COALESCE(NEW.eta_original, NEW.eta);
    END IF;
    IF OLD.etd_original IS NOT NULL THEN
      NEW.etd_original := OLD.etd_original;
    ELSE
      NEW.etd_original := COALESCE(NEW.etd_original, NEW.etd);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.embarques_internos_src() RETURNS TABLE(id uuid, organization_id uuid, cerrado_snapshot jsonb, tarifa_delta_jsonb jsonb, reabierto_motivo text, created_by_email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.id,
         e.organization_id,
         e.cerrado_snapshot,
         e.tarifa_delta_jsonb,
         e.reabierto_motivo,
         e.created_by_email
  FROM public.embarques e
  WHERE public.is_org_member(e.organization_id)
    AND NOT public.has_role((SELECT auth.uid()), 'cliente'::app_role)
    AND NOT public.has_role((SELECT auth.uid()), 'agente_carga'::app_role);
$$;
CREATE FUNCTION public.embarques_list_extras(p_ids uuid[]) RETURNS TABLE(embarque_id uuid, costos_total bigint, costos_pagados bigint, docs_total bigint, docs_pendientes bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH permitidos AS (
    SELECT e.id FROM public.embarques e
      JOIN unnest(p_ids) AS u(id) ON u.id = e.id
     WHERE e.deleted_at IS NULL                -- FIX C5
       AND (e.organization_id = public.current_user_org_id()
        OR public.has_role(auth.uid(),'super_admin'::app_role))
  )
  SELECT p.id,
    COALESCE(cc.total,0), COALESCE(cc.pagados,0),
    COALESCE(dd.total,0), COALESCE(dd.pendientes,0)
  FROM permitidos p
  LEFT JOIN (
    SELECT c.embarque_id, count(*) AS total,
           count(*) FILTER (WHERE c.estado_liquidacion='Pagado') AS pagados
      FROM public.conceptos_costo c
     WHERE c.embarque_id IN (SELECT id FROM permitidos) AND c.deleted_at IS NULL
     GROUP BY c.embarque_id
  ) cc ON cc.embarque_id=p.id
  LEFT JOIN (
    SELECT d.embarque_id, count(*) AS total,
           count(*) FILTER (WHERE d.archivo IS NULL AND d.estado <> 'No aplica') AS pendientes
      FROM public.documentos_embarque d
     WHERE d.embarque_id IN (SELECT id FROM permitidos) AND d.deleted_at IS NULL
     GROUP BY d.embarque_id
  ) dd ON dd.embarque_id=p.id;
$$;
CREATE FUNCTION public.embarques_listado(p_organization_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_modo text DEFAULT NULL::text, p_cliente_id uuid DEFAULT NULL::uuid, p_operador text DEFAULT NULL::text, p_proforma text DEFAULT NULL::text, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_sort_by text DEFAULT 'expediente_num'::text, p_sort_dir text DEFAULT 'desc'::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, expediente text, bl_master text, cliente_id uuid, cliente_nombre text, modo public.modo_transporte, tipo public.tipo_operacion, estado public.estado_embarque, etd date, eta date, operador text, puerto_origen text, puerto_destino text, aeropuerto_origen text, aeropuerto_destino text, ciudad_origen text, ciudad_destino text, contenedor text, tipo_contenedor text, tipo_carga text, descripcion_mercancia text, created_at timestamp with time zone, tipo_cambio_usd numeric, tipo_cambio_eur numeric, tiene_proforma boolean, costos_total bigint, costos_pagados bigint, docs_total bigint, docs_pendientes bigint, total_count bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_sort text := lower(coalesce(p_sort_by, 'expediente_num'));
  v_dir text := CASE WHEN lower(coalesce(p_sort_dir,'desc')) = 'asc' THEN 'ASC' ELSE 'DESC' END;
  v_search text := CASE WHEN p_search IS NULL OR p_search = '' THEN NULL ELSE '%' || p_search || '%' END;
  v_order_expr text;
BEGIN
  IF v_sort NOT IN ('created_at','expediente','expediente_num','cliente_nombre','modo','estado','etd','eta','operador') THEN
    v_sort := 'expediente_num';
  END IF;
  IF v_sort IN ('expediente','expediente_num') THEN
    v_order_expr := format(
      'NULLIF(regexp_replace(coalesce(expediente,''''), ''\D'', '''', ''g''), '''')::bigint %s NULLS LAST, expediente %s NULLS LAST',
      v_dir, v_dir
    );
  ELSE
    v_order_expr := format('%I %s NULLS LAST', v_sort, v_dir);
  END IF;
  RETURN QUERY EXECUTE format($q$
    WITH filtered AS (
      -- HOTFIX R3-01: columnas explícitas (nunca e.*) para respetar el grant
      -- por columna que mantiene cerradas las 4 columnas internas.
      SELECT e.id, e.expediente, e.bl_master, e.cliente_id, e.cliente_nombre,
             e.modo, e.tipo, e.estado, e.etd, e.eta, e.operador,
             e.puerto_origen, e.puerto_destino, e.aeropuerto_origen, e.aeropuerto_destino,
             e.ciudad_origen, e.ciudad_destino, e.contenedor, e.tipo_contenedor,
             e.tipo_carga, e.descripcion_mercancia, e.created_at,
             e.tipo_cambio_usd, e.tipo_cambio_eur, e.tiene_proforma
      FROM embarques e
      WHERE e.deleted_at IS NULL              -- FIX C5
        AND e.organization_id = public.org_requerida($1)
        AND ( $2 IS NULL OR (
              e.expediente ILIKE $2 OR e.cliente_nombre ILIKE $2
              OR e.descripcion_mercancia ILIKE $2 OR e.bl_master ILIKE $2
            ))
        AND ( $3 IS NULL OR e.modo = $3::modo_transporte )
        AND ( $4 IS NULL OR e.cliente_id = $4 )
        AND ( $5 IS NULL OR e.operador = $5 )
        AND ( $6 IS NULL OR ($6 = 'con' AND e.tiene_proforma = true) OR ($6 = 'sin' AND e.tiene_proforma = false) )
        AND ( $7 IS NULL OR e.etd >= $7 )
        AND ( $8 IS NULL OR e.eta <= $8 )
    ),
    counted AS (
      SELECT f.*, count(*) OVER ()::bigint AS total_count
      FROM filtered f
      ORDER BY %s, f.created_at DESC, f.id DESC
      OFFSET $9 LIMIT $10
    ),
    cost_agg AS (
      SELECT cc.embarque_id,
             count(*)::bigint AS costos_total,
             count(*) FILTER (WHERE cc.estado_liquidacion = 'Pagado')::bigint AS costos_pagados
      FROM conceptos_costo cc
      WHERE cc.embarque_id IN (SELECT id FROM counted)
        AND cc.deleted_at IS NULL             -- FIX C5
      GROUP BY cc.embarque_id
    ),
    docs_agg AS (
      SELECT d.embarque_id,
             count(*)::bigint AS docs_total,
             count(*) FILTER (WHERE d.estado = 'Pendiente')::bigint AS docs_pendientes
      FROM documentos_embarque d
      WHERE d.embarque_id IN (SELECT id FROM counted)
        AND d.deleted_at IS NULL              -- FIX C5
      GROUP BY d.embarque_id
    )
    SELECT c.id, c.expediente, c.bl_master, c.cliente_id, c.cliente_nombre,
           c.modo, c.tipo, c.estado, c.etd, c.eta, c.operador,
           c.puerto_origen, c.puerto_destino, c.aeropuerto_origen, c.aeropuerto_destino,
           c.ciudad_origen, c.ciudad_destino, c.contenedor, c.tipo_contenedor,
           c.tipo_carga,
           c.descripcion_mercancia, c.created_at, c.tipo_cambio_usd, c.tipo_cambio_eur,
           c.tiene_proforma,
           COALESCE(ca.costos_total, 0),
           COALESCE(ca.costos_pagados, 0),
           COALESCE(da.docs_total, 0),
           COALESCE(da.docs_pendientes, 0),
           c.total_count
    FROM counted c
    LEFT JOIN cost_agg ca ON ca.embarque_id = c.id
    LEFT JOIN docs_agg da ON da.embarque_id = c.id
    ORDER BY %s, c.created_at DESC, c.id DESC
  $q$,
    v_order_expr,
    CASE WHEN v_sort IN ('expediente','expediente_num')
      THEN format('NULLIF(regexp_replace(coalesce(c.expediente,''''), ''\D'', '''', ''g''), '''')::bigint %s NULLS LAST, c.expediente %s NULLS LAST', v_dir, v_dir)
      ELSE format('c.%I %s NULLS LAST', v_sort, v_dir)
    END
  )
  USING p_organization_id, v_search, p_modo, p_cliente_id, p_operador,
        p_proforma, p_fecha_desde, p_fecha_hasta, p_offset, p_limit;
END;
$_$;
CREATE FUNCTION public.embarques_protect_creator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Si el operador anterior ya tenía valor (no vacío), no permitir cambio.
  IF OLD.operador IS NOT NULL AND length(trim(OLD.operador)) > 0 THEN
    NEW.operador := OLD.operador;
  END IF;
  -- Mismo principio con el correo del creador.
  IF OLD.created_by_email IS NOT NULL AND length(trim(OLD.created_by_email)) > 0 THEN
    NEW.created_by_email := OLD.created_by_email;
  END IF;
  -- Y con el uuid del creador.
  IF OLD.created_by IS NOT NULL THEN
    NEW.created_by := OLD.created_by;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.enforce_cotizacion_obligatoria() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_es_libre boolean := false;
BEGIN
  -- Si ya viene con cotización, todo OK
  IF NEW.cotizacion_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  -- Sin auth context (jobs internos / service_role) — permitir
  IF v_uid IS NULL THEN
    RETURN NEW;
  END IF;
  -- ¿Es super_admin global?
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = v_uid AND role = 'super_admin'
  ) INTO v_es_libre;
  IF v_es_libre THEN
    RETURN NEW;
  END IF;
  -- ¿Tiene rol admin/dirección en la organización del embarque?
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = v_uid
      AND organization_id = NEW.organization_id
      AND role IN ('admin_org', 'admin', 'gerente_operaciones')
  ) INTO v_es_libre;
  IF v_es_libre THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Tu rol requiere vincular una cotización Aceptada para crear el embarque.'
    USING ERRCODE = 'check_violation', HINT = 'Selecciona una cotización en el paso 1 del wizard.';
END;
$$;
CREATE FUNCTION public.enforce_cotizacion_vigente(p_cotizacion_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_vigencia date;
BEGIN
  SELECT fecha_vigencia INTO v_vigencia FROM public.cotizaciones WHERE id=p_cotizacion_id;
  IF v_vigencia IS NOT NULL AND v_vigencia < CURRENT_DATE THEN
    RAISE EXCEPTION 'LC_COT_VENCIDA: la cotización venció el %, extienda la vigencia antes de convertirla', v_vigencia USING ERRCODE='P0001';
  END IF;
END;
$$;
CREATE FUNCTION public.enforce_nc_proveedor_estado_transicion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old public.estado_nota_credito_proveedor;
  v_new public.estado_nota_credito_proveedor := NEW.estado;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF v_new IS DISTINCT FROM 'Borrador' THEN
      RAISE EXCEPTION 'LC_NC_PROV_INSERT_ESTADO_INVALIDO'
        USING HINT = 'Una nota de crédito de proveedor debe crearse en estado Borrador.',
              ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
  END IF;
  v_old := OLD.estado;
  IF v_old = v_new THEN
    RETURN NEW;
  END IF;
  IF v_old = 'Cancelada' THEN
    RAISE EXCEPTION 'LC_NC_PROV_ESTADO_TERMINAL'
      USING HINT = 'La nota de crédito está Cancelada y no admite cambios de estado.',
            ERRCODE = 'P0001';
  END IF;
  IF v_old = 'Borrador' AND v_new IN ('Aprobada','Cancelada') THEN
    RETURN NEW;
  END IF;
  IF v_old = 'Aprobada' AND v_new IN ('Aplicada','Cancelada') THEN
    RETURN NEW;
  END IF;
  IF v_old = 'Aplicada' AND v_new = 'Cancelada' THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'LC_NC_PROV_TRANSICION_INVALIDA'
    USING HINT = format('No se puede pasar de %s a %s.', v_old, v_new),
          ERRCODE = 'P0001';
END;
$$;
CREATE FUNCTION public.enforce_proforma_aceptada_before_factura() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (OLD.factura_id IS NULL AND NEW.factura_id IS NOT NULL)
     OR (COALESCE(OLD.estado_proforma,'') <> 'facturada' AND NEW.estado_proforma = 'facturada') THEN
    IF COALESCE(NEW.estado_cliente,'pendiente') <> 'aceptada' THEN
      RAISE EXCEPTION 'La proforma % no puede facturarse: el cliente no la ha aceptado (estado actual: %).',
        NEW.numero, COALESCE(NEW.estado_cliente,'pendiente');
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE FUNCTION public.enforce_proforma_no_soft_delete_facturada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.deleted_at IS NULL
     AND NEW.deleted_at IS NOT NULL
     AND OLD.estado_proforma = 'facturada' THEN
    RAISE EXCEPTION 'LC_PROFORMA_FACTURADA_NO_ELIMINABLE'
      USING HINT = 'No se puede eliminar una proforma facturada. Cancela primero la factura relacionada.',
            ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.enforce_revalidacion_sin_cambios(p_cotizacion_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_res jsonb;
  v_sev text;
  v_estado_rev text;
BEGIN
  SELECT estado_revalidacion INTO v_estado_rev
  FROM public.cotizaciones WHERE id = p_cotizacion_id;
  IF v_estado_rev = 'reaprobada' THEN
    RETURN;
  END IF;
  v_res := public.revalidar_tarifa_cotizacion(p_cotizacion_id);
  v_sev := v_res->>'severidad';
  IF v_sev = 'bloqueante' THEN
    RAISE EXCEPTION 'LC_TARIFA_REQUIERE_REVALIDACION severidad=% max_delta_pct=% — resuelve la revalidación (reaprobación o decisión de tarifa) antes de convertir',
      v_sev, COALESCE(v_res->>'max_delta_pct','0')
      USING ERRCODE = 'P0001';
  END IF;
END;
$$;
CREATE FUNCTION public.enmascarar_costos_jsonb(p_in jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_out jsonb;
  v_key text;
  v_val jsonb;
  v_elem jsonb;
  v_prefijos text[] := ARRAY['costo','costos','profit','utilidad','margen','gastosoperativos'];
  v_sensible boolean;
  v_pref text;
BEGIN
  IF p_in IS NULL THEN
    RETURN NULL;
  END IF;
  CASE jsonb_typeof(p_in)
    WHEN 'object' THEN
      v_out := '{}'::jsonb;
      FOR v_key, v_val IN SELECT key, value FROM jsonb_each(p_in) LOOP
        v_sensible := false;
        FOREACH v_pref IN ARRAY v_prefijos LOOP
          IF lower(v_key) LIKE v_pref || '%' THEN
            v_sensible := true;
            EXIT;
          END IF;
        END LOOP;
        IF v_sensible THEN
          v_out := v_out || jsonb_build_object(v_key, 'null'::jsonb);
        ELSE
          v_out := v_out || jsonb_build_object(v_key, public.enmascarar_costos_jsonb(v_val));
        END IF;
      END LOOP;
      RETURN v_out;
    WHEN 'array' THEN
      v_out := '[]'::jsonb;
      FOR v_elem IN SELECT value FROM jsonb_array_elements(p_in) LOOP
        v_out := v_out || jsonb_build_array(public.enmascarar_costos_jsonb(v_elem));
      END LOOP;
      RETURN v_out;
    ELSE
      RETURN p_in;
  END CASE;
END;
$$;
CREATE FUNCTION public.ensure_demo_membership(_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- OLA 1 · C7: privilegio de servicio obligatorio. Antes cualquier usuario
  -- autenticado podía reescribir el rol y la organización de otra persona.
  IF auth.role() IS DISTINCT FROM 'service_role' AND auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'LC_DEMO_SOLO_SERVICIO: la asignación demo sólo puede hacerse desde el servidor'
      USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.user_roles (user_id, role)
  VALUES (_user_id, 'admin_org'::app_role)
  ON CONFLICT (user_id) DO UPDATE SET role = 'admin_org'::app_role;
  INSERT INTO public.organization_members (user_id, organization_id, role)
  VALUES (_user_id, 'de100000-0000-0000-0000-000000000001'::uuid, 'admin_org'::app_role)
  ON CONFLICT (user_id) DO UPDATE
    SET organization_id = EXCLUDED.organization_id,
        role            = EXCLUDED.role;
END;
$$;
CREATE FUNCTION public.es_admin_catalogo(_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _uid AND role IN ('super_admin','admin','admin_org')
  );
$$;
CREATE FUNCTION public.es_escritor_financiero(_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _uid
      AND role IN ('super_admin','admin','admin_org','contador','tesorero','ejecutivo_cobranza')
  );
$$;
CREATE FUNCTION public.estado_cuenta_agregados(p_cliente_ids uuid[], p_desde date DEFAULT NULL::date, p_hasta date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_result jsonb;
  v_org uuid := public.org_scope();
  v_es_cliente boolean;
BEGIN
  -- M-9 (v14): los usuarios con rol cliente no son miembros de organización
  -- (org_scope() = NULL) y los KPIs salían en $0. El alcance se deriva de los
  -- clientes ligados al usuario.
  IF v_org IS NULL THEN
    SELECT EXISTS (SELECT 1 FROM public.client_users cu WHERE cu.user_id = auth.uid()) INTO v_es_cliente;
    IF NOT v_es_cliente THEN
      RAISE EXCEPTION 'LC_ESTADO_CUENTA_SIN_ACCESO: sin organización activa ni cliente ligado';
    END IF;
    IF EXISTS (
      SELECT 1 FROM unnest(COALESCE(p_cliente_ids, ARRAY[]::uuid[])) AS x(id)
      WHERE x.id NOT IN (SELECT public.current_user_client_ids())
    ) THEN
      RAISE EXCEPTION 'LC_ESTADO_CUENTA_SIN_ACCESO: cliente fuera de tu alcance';
    END IF;
  END IF;
  WITH cartera AS (
    SELECT
      f.id,
      f.moneda::text AS moneda,
      CASE
        WHEN f.estado::text = 'Pagada' THEN 0
        ELSE GREATEST(0, f.total - COALESCE(pg.pagado, 0) - COALESCE(nc.notas, 0))
      END AS saldo,
      ((now() AT TIME ZONE 'America/Mexico_City')::date - f.fecha_vencimiento) AS dias_vencido
    FROM facturas f
    LEFT JOIN LATERAL (
      SELECT SUM(pf.monto_aplicado_factura) AS pagado
      FROM pagos_factura pf
      WHERE pf.factura_id = f.id AND pf.deleted_at IS NULL
    ) pg ON true
    LEFT JOIN LATERAL (
      SELECT SUM(n.monto) AS notas
      FROM factura_notas_credito n
      WHERE n.factura_id = f.id AND n.deleted_at IS NULL AND n.estado = 'Aplicada'
    ) nc ON true
    WHERE f.deleted_at IS NULL
      AND f.estado IN ('Emitida', 'Parcialmente pagada', 'Vencida', 'Pagada')
      AND f.cliente_id = ANY(p_cliente_ids)
      AND (v_org IS NULL OR f.organization_id = v_org)
      AND (p_desde IS NULL OR f.fecha_emision >= p_desde)
      AND (p_hasta IS NULL OR f.fecha_emision <= p_hasta)
  ),
  anticipos AS (
    SELECT
      f.moneda::text AS moneda,
      GREATEST(0,
        pf.monto * CASE
          WHEN pf.moneda = f.moneda THEN 1
          WHEN pf.tipo_cambio IS NOT NULL AND pf.tipo_cambio > 0 THEN pf.tipo_cambio
          ELSE 0
        END - pf.monto_aplicado_factura
      ) AS no_aplicado
    FROM pagos_factura pf
    JOIN facturas f ON f.id = pf.factura_id
    WHERE pf.deleted_at IS NULL
      AND f.deleted_at IS NULL
      AND f.cliente_id = ANY(p_cliente_ids)
      AND (v_org IS NULL OR f.organization_id = v_org)
      AND (p_desde IS NULL OR f.fecha_emision >= p_desde)
      AND (p_hasta IS NULL OR f.fecha_emision <= p_hasta)
  )
  SELECT jsonb_build_object(
    'adeudado_mxn',      COALESCE((SELECT SUM(saldo) FROM cartera WHERE moneda = 'MXN' AND saldo > 0), 0),
    'adeudado_usd',      COALESCE((SELECT SUM(saldo) FROM cartera WHERE moneda = 'USD' AND saldo > 0), 0),
    'vencido_mxn',       COALESCE((SELECT SUM(saldo) FROM cartera WHERE moneda = 'MXN' AND saldo > 0 AND dias_vencido > 0), 0),
    'vencido_usd',       COALESCE((SELECT SUM(saldo) FROM cartera WHERE moneda = 'USD' AND saldo > 0 AND dias_vencido > 0), 0),
    'a_favor_mxn',       COALESCE((SELECT SUM(no_aplicado) FROM anticipos WHERE moneda = 'MXN'), 0),
    'a_favor_usd',       COALESCE((SELECT SUM(no_aplicado) FROM anticipos WHERE moneda = 'USD'), 0),
    'facturas_vencidas', (SELECT COUNT(*) FROM cartera WHERE saldo > 0 AND dias_vencido > 0),
    'facturas_adeudadas',(SELECT COUNT(*) FROM cartera WHERE saldo > 0)
  ) INTO v_result;
  RETURN v_result;
END;
$_$;
CREATE FUNCTION public.estado_cuenta_bancario(p_cuenta_bancaria_id uuid, p_desde date, p_hasta date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cuenta      record;
  v_desde       date;
  v_saldo_ini   numeric := 0;
  v_entradas    numeric := 0;
  v_salidas     numeric := 0;
  v_previos     integer := 0;
  v_movs        jsonb   := '[]'::jsonb;
BEGIN
  IF p_cuenta_bancaria_id IS NULL OR p_desde IS NULL OR p_hasta IS NULL THEN
    RAISE EXCEPTION 'LC_ESTADO_CUENTA_PARAMS: cuenta y periodo son obligatorios';
  END IF;
  IF p_hasta < p_desde THEN
    RAISE EXCEPTION 'LC_ESTADO_CUENTA_RANGO: la fecha final no puede ser anterior a la inicial';
  END IF;
  SELECT cb.id, cb.alias, cb.banco, cb.moneda,
         COALESCE(cb.saldo_inicial, 0) AS saldo_apertura,
         cb.fecha_saldo_inicial AS corte
    INTO v_cuenta
  FROM public.cuentas_bancarias cb
  WHERE cb.id = p_cuenta_bancaria_id
    AND cb.deleted_at IS NULL
    AND (cb.organization_id = public.org_scope());
  IF v_cuenta.id IS NULL THEN
    RAISE EXCEPTION 'LC_ESTADO_CUENTA_SIN_ACCESO: la cuenta no existe o no pertenece a tu organización';
  END IF;
  -- El periodo nunca puede empezar antes del corte del saldo inicial.
  v_desde := GREATEST(p_desde, v_cuenta.corte);
  IF p_hasta < v_desde THEN
    RETURN jsonb_build_object(
      'cuenta_id', v_cuenta.id,
      'alias', v_cuenta.alias,
      'banco', v_cuenta.banco,
      'moneda', v_cuenta.moneda,
      'desde', v_desde,
      'hasta', p_hasta,
      'fecha_saldo_inicial', v_cuenta.corte,
      'saldo_inicial', v_cuenta.saldo_apertura,
      'total_entradas', 0,
      'total_salidas', 0,
      'saldo_final', v_cuenta.saldo_apertura,
      'movimientos_previos_corte', 0,
      'movimientos', '[]'::jsonb
    );
  END IF;
  -- Saldo inicial del periodo = apertura + neto entre el corte y el inicio del periodo
  SELECT v_cuenta.saldo_apertura + COALESCE(SUM(m.abono - m.cargo), 0)
    INTO v_saldo_ini
  FROM public.bbva_movimientos m
  WHERE m.cuenta_bancaria_id = p_cuenta_bancaria_id
    AND m.deleted_at IS NULL
    AND m.fecha >= v_cuenta.corte
    AND m.fecha < v_desde;
  SELECT COUNT(*)
    INTO v_previos
  FROM public.bbva_movimientos m
  WHERE m.cuenta_bancaria_id = p_cuenta_bancaria_id
    AND m.deleted_at IS NULL
    AND m.fecha < v_cuenta.corte;
  WITH movs AS (
    SELECT
      m.id, m.fecha, m.concepto, m.referencia,
      COALESCE(m.cargo, 0) AS cargo,
      COALESCE(m.abono, 0) AS abono,
      m.estado_conciliacion::text AS estado_conciliacion,
      m.pago_factura_id, m.pago_proveedor_id,
      m.anticipo_proveedor_id, m.pago_proveedor_lote_id,
      v_saldo_ini + SUM(COALESCE(m.abono, 0) - COALESCE(m.cargo, 0))
        OVER (ORDER BY m.fecha, m.id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS saldo_corrido
    FROM public.bbva_movimientos m
    WHERE m.cuenta_bancaria_id = p_cuenta_bancaria_id
      AND m.deleted_at IS NULL
      AND m.fecha >= v_desde
      AND m.fecha <= p_hasta
  )
  SELECT
    COALESCE(jsonb_agg(to_jsonb(movs) ORDER BY movs.fecha, movs.id), '[]'::jsonb),
    COALESCE(SUM(movs.abono), 0),
    COALESCE(SUM(movs.cargo), 0)
  INTO v_movs, v_entradas, v_salidas
  FROM movs;
  RETURN jsonb_build_object(
    'cuenta_id',      v_cuenta.id,
    'alias',          v_cuenta.alias,
    'banco',          v_cuenta.banco,
    'moneda',         v_cuenta.moneda,
    'desde',          v_desde,
    'hasta',          p_hasta,
    'fecha_saldo_inicial', v_cuenta.corte,
    'saldo_inicial',  v_saldo_ini,
    'total_entradas', v_entradas,
    'total_salidas',  v_salidas,
    'saldo_final',    v_saldo_ini + v_entradas - v_salidas,
    'movimientos_previos_corte', v_previos,
    'movimientos',    v_movs
  );
END;
$$;
CREATE FUNCTION public.expirar_cotizaciones_job() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_borradores_vencidos int := 0;
  v_enviadas_vencidas   int := 0;
  v_archivadas          int := 0;
  v_error_archivado     text := NULL;
BEGIN
  -- 4a) Borradores con >7 días sin movimiento -> Vencida
  WITH upd AS (
    UPDATE public.cotizaciones
       SET estado_anterior = estado,
           estado = 'Vencida'::public.estado_cotizacion,
           updated_at = now()
     WHERE estado = 'Borrador'::public.estado_cotizacion
       AND updated_at < now() - interval '7 days'
       AND deleted_at IS NULL
       AND embarque_id IS NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_borradores_vencidos FROM upd;
  -- 4b) Enviadas cuya fecha_vigencia ya expiró -> Vencida
  WITH upd AS (
    UPDATE public.cotizaciones
       SET estado_anterior = estado,
           estado = 'Vencida'::public.estado_cotizacion,
           updated_at = now()
     WHERE estado = 'Enviada'::public.estado_cotizacion
       AND fecha_vigencia IS NOT NULL
       AND fecha_vigencia < CURRENT_DATE
       AND deleted_at IS NULL
       AND embarque_id IS NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_enviadas_vencidas FROM upd;
  -- 4c) Vencidas >90 días sin movimiento -> Archivada (aislado)
  BEGIN
    WITH upd AS (
      UPDATE public.cotizaciones
         -- Ola 4 · N53: conservar el estado_anterior real (p. ej. 'Enviada',
         -- puesto por 4b) y sólo caer a 'Vencida' si no había nada previo.
         SET estado_anterior = CASE
               WHEN estado = 'Vencida'::public.estado_cotizacion
                 THEN COALESCE(estado_anterior, estado)
               ELSE estado
             END,
             estado = 'Archivada'::public.estado_cotizacion,
             updated_at = now()
       WHERE estado = 'Vencida'::public.estado_cotizacion
         AND updated_at < now() - interval '90 days'
         AND deleted_at IS NULL
         AND embarque_id IS NULL
      RETURNING 1
    )
    SELECT count(*) INTO v_archivadas FROM upd;
  EXCEPTION WHEN OTHERS THEN
    v_archivadas := 0;
    v_error_archivado := SQLERRM;
  END;
  -- 4d) Registrar resumen en app_logs
  INSERT INTO public.app_logs (level, fn, msg, payload)
  VALUES (
    CASE WHEN v_error_archivado IS NULL THEN 'info' ELSE 'error' END,
    'expirar_cotizaciones_job',
    'Housekeeping de cotizaciones ejecutado',
    jsonb_build_object(
      'borradores_vencidos', v_borradores_vencidos,
      'enviadas_vencidas',   v_enviadas_vencidas,
      'archivadas',          v_archivadas,
      'error_archivado',     v_error_archivado
    )
  );
  RETURN jsonb_build_object(
    'borradores_vencidos', v_borradores_vencidos,
    'enviadas_vencidas',   v_enviadas_vencidas,
    'archivadas',          v_archivadas,
    'error_archivado',     v_error_archivado
  );
END;
$$;
CREATE FUNCTION public.facturacion_por_emitir() RETURNS TABLE(proforma_id uuid, numero_proforma text, cliente_id uuid, cliente_nombre text, embarque_id uuid, expediente text, total numeric, dias_desde_emision integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT p.id, p.numero, p.cliente_id, COALESCE(c.nombre, p.cliente_nombre),
    p.embarque_id, e.expediente,
    COALESCE(p.total_mxn, p.total_usd, 0),
    GREATEST(0,(CURRENT_DATE - p.fecha_emision))::int
  FROM public.proformas p
  LEFT JOIN public.clientes c ON c.id=p.cliente_id
  LEFT JOIN public.embarques e ON e.id=p.embarque_id
  WHERE p.deleted_at IS NULL
    AND lower(COALESCE(p.estado_aprobacion,''))='aprobada'
    AND p.factura_id IS NULL
    AND COALESCE(p.estado_proforma,'') <> 'Cancelada'
  ORDER BY p.fecha_emision ASC NULLS LAST
  LIMIT 500;
$$;
CREATE FUNCTION public.facturas_cartera_cliente(p_cliente_id uuid, p_desde date DEFAULT NULL::date, p_hasta date DEFAULT NULL::date) RETURNS TABLE(id uuid, organization_id uuid, numero text, serie text, folio text, cliente_id uuid, cliente_nombre text, total numeric, saldo numeric, moneda text, estado text, fecha_emision date, fecha_vencimiento date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_uid uuid := auth.uid();
  v_caller_org uuid;
BEGIN
  SELECT c.organization_id INTO v_org
  FROM public.clientes c WHERE c.id = p_cliente_id AND c.deleted_at IS NULL;
  IF v_org IS NULL THEN RETURN; END IF;
  -- Fail-closed para usuarios finales de otra organización.
  IF v_uid IS NOT NULL
     AND COALESCE(auth.role()::text, '') <> 'service_role'
     AND NOT public.has_role(v_uid, 'super_admin'::app_role) THEN
    v_caller_org := public.current_user_org_id();
    IF v_caller_org IS NULL OR v_org IS DISTINCT FROM v_caller_org THEN
      RETURN;
    END IF;
  END IF;
  RETURN QUERY
  SELECT f.id,
         f.organization_id,
         f.numero::text,
         f.serie::text,
         f.folio_fiscal::text,
         f.cliente_id,
         f.cliente_nombre::text,
         COALESCE(f.total, 0)::numeric,
         CASE
           WHEN f.estado::text = 'Pagada' THEN 0::numeric
           ELSE (COALESCE(f.total, 0)
             - COALESCE((SELECT SUM(p.monto_aplicado_factura) FROM public.pagos_factura p
                          WHERE p.factura_id = f.id AND p.deleted_at IS NULL), 0)
             -- Ola E1 · C1-res: antes `SUM(nc.monto)` en crudo mezclaba monedas.
             - public._nc_aplicadas_moneda_factura(f.id))::numeric
         END AS saldo,
         f.moneda::text,
         f.estado::text,
         f.fecha_emision,
         f.fecha_vencimiento
  FROM public.facturas f
  WHERE f.cliente_id = p_cliente_id
    AND f.deleted_at IS NULL
    AND f.estado NOT IN ('Borrador', 'Cancelada', 'Sustituida')
    AND (p_desde IS NULL OR f.fecha_emision >= p_desde)
    AND (p_hasta IS NULL OR f.fecha_emision <= p_hasta)
  ORDER BY f.fecha_emision;
END;
$$;
CREATE FUNCTION public.facturas_listado(p_organization_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_estado text DEFAULT NULL::text, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, numero text, cliente_nombre text, expediente text, total numeric, moneda public.moneda, fecha_emision date, fecha_vencimiento date, estado public.estado_factura, proforma_id uuid, proforma_numero text, factura_pdf_url text, factura_xml_url text, ambiente public.ambiente_facturapi, acuse_cancelacion_status text, cancellation_status text, enviada_cliente_at timestamp with time zone, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH filtered AS (
    SELECT f.*
    FROM facturas f
    WHERE f.deleted_at IS NULL                -- FIX C5
      AND f.organization_id = public.org_requerida(p_organization_id)
      AND ( p_search IS NULL OR p_search = '' OR
            f.numero ILIKE '%' || p_search || '%' OR
            f.cliente_nombre ILIKE '%' || p_search || '%' OR
            f.expediente ILIKE '%' || p_search || '%' )
      AND ( p_estado IS NULL OR f.estado = p_estado::estado_factura )
      AND ( p_fecha_desde IS NULL OR f.fecha_emision >= p_fecha_desde )
      AND ( p_fecha_hasta IS NULL OR f.fecha_emision <= p_fecha_hasta )
  ),
  counted AS (
    SELECT f.*, count(*) OVER ()::bigint AS total_count
    FROM filtered f
    ORDER BY f.created_at DESC
    OFFSET p_offset LIMIT p_limit
  )
  SELECT c.id, c.numero, c.cliente_nombre, c.expediente, c.total, c.moneda,
         c.fecha_emision, c.fecha_vencimiento, c.estado, c.proforma_id,
         p.numero AS proforma_numero,
         c.factura_pdf_url, c.factura_xml_url,
         c.ambiente,
         c.acuse_cancelacion_status,
         c.cancellation_status,
         c.enviada_cliente_at,
         c.total_count
  FROM counted c
  LEFT JOIN proformas p ON p.id = c.proforma_id
  ORDER BY c.fecha_emision DESC NULLS LAST;
$$;
CREATE FUNCTION public.facturas_set_fecha_vencimiento() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.fecha_emision IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.fecha_vencimiento IS NULL THEN
      NEW.fecha_vencimiento := NEW.fecha_emision + COALESCE(NEW.dias_credito, 0);
    END IF;
    RETURN NEW;
  END IF;
  -- UPDATE: si el caller fijó explícitamente un vencimiento distinto, se respeta.
  IF NEW.fecha_vencimiento IS DISTINCT FROM OLD.fecha_vencimiento THEN
    IF NEW.fecha_vencimiento IS NULL THEN
      NEW.fecha_vencimiento := NEW.fecha_emision + COALESCE(NEW.dias_credito, 0);
    END IF;
    RETURN NEW;
  END IF;
  -- Recalcular cuando cambia la emisión o los días de crédito.
  IF NEW.fecha_emision IS DISTINCT FROM OLD.fecha_emision
     OR NEW.dias_credito IS DISTINCT FROM OLD.dias_credito THEN
    NEW.fecha_vencimiento := NEW.fecha_emision + COALESCE(NEW.dias_credito, 0);
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.fn_admin_org_activity() RETURNS TABLE(id uuid, nombre text, embarques bigint, cotizaciones bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    o.id,
    o.nombre,
    COALESCE(e.cnt, 0) AS embarques,
    COALESCE(c.cnt, 0) AS cotizaciones
  FROM public.organizations o
  LEFT JOIN (
    SELECT organization_id, COUNT(*)::bigint AS cnt
    FROM public.embarques
    WHERE organization_id IS NOT NULL
    GROUP BY organization_id
  ) e ON e.organization_id = o.id
  LEFT JOIN (
    SELECT organization_id, COUNT(*)::bigint AS cnt
    FROM public.cotizaciones
    WHERE organization_id IS NOT NULL
    GROUP BY organization_id
  ) c ON c.organization_id = o.id
  WHERE public.has_role(auth.uid(), 'super_admin'::app_role)
  ORDER BY o.nombre
  LIMIT 500;
$$;
CREATE FUNCTION public.fn_admin_org_counts(_org uuid) RETURNS TABLE(miembros bigint, embarques bigint, clientes bigint, cotizaciones bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_SOLO_SUPER_ADMIN: telemetría de plataforma restringida';
  END IF;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_REQUERIDA: falta la organización';
  END IF;
  RETURN QUERY
  SELECT
    (SELECT count(*) FROM public.organization_members m WHERE m.organization_id = _org),
    (SELECT count(*) FROM public.embarques e WHERE e.organization_id = _org AND e.deleted_at IS NULL),
    (SELECT count(*) FROM public.clientes c WHERE c.organization_id = _org AND c.deleted_at IS NULL),
    (SELECT count(*) FROM public.cotizaciones q WHERE q.organization_id = _org AND q.deleted_at IS NULL);
END;
$$;
CREATE FUNCTION public.fn_admin_platform_stats() RETURNS TABLE(total_orgs bigint, total_users bigint, total_embarques bigint, total_cotizaciones bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_SOLO_SUPER_ADMIN: telemetría de plataforma restringida';
  END IF;
  RETURN QUERY
  SELECT
    (SELECT count(*) FROM public.organizations),
    (SELECT count(*) FROM public.organization_members),
    (SELECT count(*) FROM public.embarques WHERE deleted_at IS NULL),
    (SELECT count(*) FROM public.cotizaciones WHERE deleted_at IS NULL);
END;
$$;
CREATE FUNCTION public.garantia_auto_materializar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prov_id uuid;
  v_naviera_nombre text;
BEGIN
  IF NEW.estado <> 'retenido' OR OLD.estado = 'retenido' THEN
    RETURN NEW;
  END IF;
  IF NEW.proveedor_factura_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.naviera_id IS NULL THEN
    UPDATE public.embarque_garantias_contenedor
       SET notas = COALESCE(notas || E'\n', '') || '[Retención pendiente de materializar: sin naviera]'
     WHERE id = NEW.id AND (notas IS NULL OR notas NOT LIKE '%pendiente de materializar%');
    RETURN NEW;
  END IF;
  SELECT name INTO v_naviera_nombre FROM public.navieras WHERE id = NEW.naviera_id;
  SELECT id INTO v_prov_id
  FROM public.proveedores
  WHERE organization_id = NEW.organization_id
    AND lower(nombre) = lower(v_naviera_nombre)
  LIMIT 1;
  IF v_prov_id IS NULL THEN
    UPDATE public.embarque_garantias_contenedor
       SET notas = COALESCE(notas || E'\n', '') || '[Retención pendiente de materializar: naviera sin proveedor mapeado]'
     WHERE id = NEW.id AND (notas IS NULL OR notas NOT LIKE '%pendiente de materializar%');
    RETURN NEW;
  END IF;
  BEGIN
    PERFORM public.materializar_factura_retencion_garantia(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.embarque_garantias_contenedor
       SET notas = COALESCE(notas || E'\n', '') || '[Retención pendiente: ' || SQLERRM || ']'
     WHERE id = NEW.id AND (notas IS NULL OR notas NOT LIKE '%pendiente%');
  END;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.generar_expediente(tipo_op text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org       uuid;
  v_prefijo   text;
  v_consec    bigint;
  v_exp       text;
  v_intentos  int := 0;
BEGIN
  v_org := public.current_user_org_id();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'No hay organización activa para generar expediente';
  END IF;
  CASE tipo_op
    WHEN 'Importación' THEN v_prefijo := 'IMP';
    WHEN 'Exportación' THEN v_prefijo := 'EXP';
    WHEN 'Nacional'    THEN v_prefijo := 'NAC';
    ELSE                    v_prefijo := 'GEN';
  END CASE;
  LOOP
    INSERT INTO public.folio_secuencias (organization_id, tipo, ultimo_numero)
    VALUES (v_org, 'embarque', 1)
    ON CONFLICT (organization_id, tipo)
    DO UPDATE SET ultimo_numero = public.folio_secuencias.ultimo_numero + 1,
                  updated_at    = now()
    RETURNING ultimo_numero INTO v_consec;
    v_exp := 'EL' || v_prefijo || lpad(v_consec::text, 5, '0');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.embarques
       WHERE expediente = v_exp
         AND organization_id = v_org
         AND deleted_at IS NULL
    );
    v_intentos := v_intentos + 1;
    IF v_intentos > 1000 THEN
      RAISE EXCEPTION 'No se pudo generar un expediente único tras 1000 intentos';
    END IF;
  END LOOP;
  RETURN v_exp;
END;
$$;
CREATE FUNCTION public.generar_liquidacion_comision(p_vendedora_id uuid, p_periodo text, p_organization_id uuid, p_request_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric(14,2);
  v_liq_id uuid;
  v_org uuid;
  v_cached jsonb;
  v_disponible numeric(14,2);
  v_aplicado numeric(14,2) := 0;
  v_rec record;
BEGIN
  IF NOT has_any_role_efectivo(auth.uid(),
        ARRAY['admin','admin_org','contador','tesorero']::app_role[]) THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;
  v_cached := public.idempotency_claim(p_request_id, 'generar_liquidacion_comision');
  IF v_cached IS NOT NULL THEN
    IF COALESCE((v_cached->>'__idempotency_pending')::boolean, false) THEN
      RAISE EXCEPTION 'LC_LIQUIDACION_EN_PROCESO: Esta liquidación ya está en proceso; espera unos segundos y verifica antes de reintentar.'
        USING ERRCODE = '42501';
    END IF;
    RETURN (v_cached->>'liquidacion_id')::uuid;
  END IF;
  IF has_role(auth.uid(), 'super_admin'::app_role) THEN
    v_org := p_organization_id;
  ELSE
    v_org := current_user_org_id();
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_SIN_ORG: tu usuario no tiene organización asignada' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(SUM(comision_mxn), 0) INTO v_total
    FROM public.comisiones_devengadas
   WHERE organization_id = v_org
     AND vendedora_id = p_vendedora_id
     AND estado = 'Devengada'
     AND to_char(created_at AT TIME ZONE 'America/Mexico_City', 'YYYY-MM') = p_periodo;
  IF v_total <= 0 THEN
    RAISE EXCEPTION 'Sin comisiones devengadas para liquidar';
  END IF;
  -- Auditoría 2026-08-28 · Hallazgo 1: las comisiones "Por recuperar" (ya
  -- pagadas y cuyo respaldo se canceló/acreditó después) quedaban huérfanas.
  -- Se descuentan de esta liquidación, de la más antigua a la más reciente y
  -- sólo hasta donde alcance el devengo del periodo; el remanente sigue
  -- pendiente para la siguiente liquidación.
  v_disponible := v_total;
  FOR v_rec IN
    SELECT id, comision_mxn
      FROM public.comisiones_devengadas
     WHERE organization_id = v_org
       AND vendedora_id = p_vendedora_id
       AND estado = 'Por recuperar'
     ORDER BY created_at ASC
  LOOP
    EXIT WHEN v_disponible <= 0;
    CONTINUE WHEN v_rec.comision_mxn > v_disponible;
    v_disponible := v_disponible - v_rec.comision_mxn;
    v_aplicado := v_aplicado + v_rec.comision_mxn;
  END LOOP;
  INSERT INTO public.liquidaciones_comision (organization_id, vendedora_id, periodo, total_mxn, creada_por)
  VALUES (v_org, p_vendedora_id, p_periodo, ROUND(v_total - v_aplicado, 2), auth.uid())
  RETURNING id INTO v_liq_id;
  UPDATE public.comisiones_devengadas
     SET estado = 'Liquidada', liquidacion_id = v_liq_id, updated_at = now()
   WHERE organization_id = v_org
     AND vendedora_id = p_vendedora_id
     AND estado = 'Devengada'
     AND to_char(created_at AT TIME ZONE 'America/Mexico_City', 'YYYY-MM') = p_periodo;
  IF v_aplicado > 0 THEN
    v_disponible := v_total;
    FOR v_rec IN
      SELECT id, comision_mxn
        FROM public.comisiones_devengadas
       WHERE organization_id = v_org
         AND vendedora_id = p_vendedora_id
         AND estado = 'Por recuperar'
       ORDER BY created_at ASC
    LOOP
      EXIT WHEN v_disponible <= 0;
      CONTINUE WHEN v_rec.comision_mxn > v_disponible;
      v_disponible := v_disponible - v_rec.comision_mxn;
      UPDATE public.comisiones_devengadas
         SET estado = 'Cancelada',
             liquidacion_id = v_liq_id,
             nota = COALESCE(nota || ' · ', '')
                    || 'Recuperada al descontarse de la liquidación del periodo ' || p_periodo,
             updated_at = now()
       WHERE id = v_rec.id;
    END LOOP;
  END IF;
  PERFORM public.idempotency_store(p_request_id,
    jsonb_build_object('liquidacion_id', v_liq_id,
                       'total_mxn', ROUND(v_total - v_aplicado, 2),
                       'recuperado_mxn', v_aplicado));
  RETURN v_liq_id;
END;
$$;
CREATE FUNCTION public.generar_numero_proforma(p_org_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_year int := EXTRACT(YEAR FROM CURRENT_DATE)::int;
  v_prefix text := 'PRO-' || v_year::text || '-';
  v_max int;
  v_floor int;
  v_next int;
BEGIN
  IF p_org_id IS NULL
     OR (p_org_id IS DISTINCT FROM current_user_org_id()
         AND NOT has_role(auth.uid(), 'super_admin'::app_role)) THEN
    RAISE EXCEPTION 'Forbidden: organization mismatch';
  END IF;
  -- Serializa la generación de folios por (org, año) durante la transacción.
  PERFORM pg_advisory_xact_lock(hashtext('proforma_folio:' || p_org_id::text || ':' || v_year::text));
  SELECT COALESCE(MAX(
    NULLIF(regexp_replace(numero, '^PRO-\d{4}-', ''), '')::int
  ), 0)
  INTO v_max
  FROM public.proformas
  WHERE organization_id = p_org_id
    AND numero LIKE v_prefix || '%';
  SELECT COALESCE((valor #>> '{}')::int, 0)
  INTO v_floor
  FROM public.configuracion
  WHERE organization_id = p_org_id
    AND categoria = 'folios'
    AND clave = 'proforma_floor_' || v_year::text
  LIMIT 1;
  v_next := GREATEST(v_max, COALESCE(v_floor, 0)) + 1;
  RETURN v_prefix || lpad(v_next::text, 4, '0');
END;
$$;
CREATE FUNCTION public.generar_token_proforma(p_proforma_id uuid, p_dias_vigencia integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_proforma public.proformas%ROWTYPE;
  v_token uuid := gen_random_uuid();
  v_expira timestamptz := now() + make_interval(days => GREATEST(1, p_dias_vigencia));
BEGIN
  SELECT * INTO v_proforma FROM public.proformas WHERE id = p_proforma_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Proforma no encontrada.'; END IF;
  -- Solo miembros de la org pueden generar token
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.user_id = auth.uid() AND om.organization_id = v_proforma.organization_id
  ) THEN
    RAISE EXCEPTION 'No tienes acceso a esta proforma.';
  END IF;
  UPDATE public.proformas
     SET token_publico = v_token,
         token_expira_at = v_expira,
         updated_at = now()
   WHERE id = p_proforma_id;
  RETURN jsonb_build_object('token', v_token, 'expira_at', v_expira);
END $$;
CREATE FUNCTION public.get_agente_rutas() RETURNS TABLE(id uuid, organization_id uuid, puerto_origen_id uuid, puerto_destino_id uuid, activa boolean, puerto_origen_nombre text, puerto_destino_nombre text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT r.id, r.organization_id, r.puerto_origen_id, r.puerto_destino_id, r.activa,
         po.name AS puerto_origen_nombre,
         pd.name AS puerto_destino_nombre
    FROM public.costeo_rutas r
    JOIN public.agente_users au ON au.user_id = auth.uid()
    JOIN public.costeo_agentes a ON a.id = au.agente_id
                                 AND a.organization_id = r.organization_id
    LEFT JOIN public.puertos po ON po.id = r.puerto_origen_id
    LEFT JOIN public.puertos pd ON pd.id = r.puerto_destino_id
   WHERE r.activa = true;
$$;
CREATE FUNCTION public.get_current_agente_context() RETURNS TABLE(agente_id uuid, organization_id uuid, proveedor_id uuid, agente_nombre text, organizacion_nombre text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT au.agente_id,
         au.organization_id,
         ca.proveedor_id,
         ca.nombre,
         o.nombre
    FROM public.agente_users au
    LEFT JOIN public.costeo_agentes ca ON ca.id = au.agente_id
    LEFT JOIN public.organizations  o  ON o.id  = au.organization_id
   WHERE au.user_id = auth.uid()
   ORDER BY au.created_at ASC, au.id ASC
   LIMIT 1;
$$;
CREATE FUNCTION public.get_current_agente_org_nombre() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT o.nombre
  FROM public.organizations o
  WHERE o.id = public.current_agente_org()
  LIMIT 1;
$$;
CREATE FUNCTION public.get_embarque_full(p_embarque_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM embarques WHERE id = p_embarque_id) THEN NULL
    ELSE jsonb_build_object(
      'embarque', (
        SELECT to_jsonb(s)
               || COALESCE((
                    SELECT to_jsonb(i) - 'id' - 'organization_id'
                    FROM embarques_interno_v i WHERE i.id = s.id
                  ), '{}'::jsonb)
        FROM (
          SELECT e.id, e.expediente, e.cliente_id, e.cliente_nombre, e.modo, e.tipo,
                 e.shipper, e.consignatario, e.descripcion_mercancia, e.peso_kg,
                 e.volumen_m3, e.piezas, e.incoterm, e.estado, e.operador,
                 e.puerto_origen, e.puerto_destino, e.naviera, e.bl_master, e.bl_house,
                 e.tipo_servicio, e.contenedor, e.tipo_contenedor,
                 e.aeropuerto_origen, e.aeropuerto_destino, e.aerolinea, e.mawb, e.hawb,
                 e.ciudad_origen, e.ciudad_destino, e.transportista, e.carta_porte,
                 e.etd, e.eta, e.fecha_llegada_real, e.fecha_creacion,
                 e.tipo_cambio_usd, e.tipo_cambio_eur, e.created_at, e.updated_at,
                 e.tipo_carga, e.msds_archivo, e.agente, e.cotizacion_id,
                 e.organization_id, e.tiene_proforma, e.etd_original, e.eta_original,
                 e.deleted_at, e.deleted_by, e.created_by, e.vendedora_id, e.tarifa_id,
                 e.carta_garantia, e.dias_libres_destino, e.dias_almacenaje, e.seguro,
                 e.valor_seguro_usd, e.notas, e.cerrado_at, e.cerrado_por,
                 e.reabierto_at, e.reabierto_por, e.tarifa_id_original,
                 e.tarifa_id_aplicada, e.tarifa_decision, e.tarifa_revalidada_en,
                 e.tarifa_revalidada_por, e.facturado_historico,
                 e.cobro_cliente_status, e.cobro_cliente_actualizado_at,
                 e.agente_id, e.naviera_id, e.sin_comision
          FROM embarques e WHERE e.id = p_embarque_id
        ) s
      ),
      'conceptosVenta', COALESCE((
        SELECT jsonb_agg(to_jsonb(cv.*) ORDER BY cv.created_at, cv.id)
        FROM conceptos_venta cv
        WHERE cv.embarque_id = p_embarque_id
      ), '[]'::jsonb),
      'conceptosCosto', COALESCE((
        SELECT jsonb_agg(to_jsonb(cc.*) ORDER BY cc.created_at, cc.id)
        FROM conceptos_costo cc
        WHERE cc.embarque_id = p_embarque_id
      ), '[]'::jsonb),
      'documentos', COALESCE((
        SELECT jsonb_agg(to_jsonb(d.*) ORDER BY d.created_at, d.id)
        FROM documentos_embarque d
        WHERE d.embarque_id = p_embarque_id
      ), '[]'::jsonb),
      'notas', COALESCE((
        SELECT jsonb_agg(to_jsonb(n.*) ORDER BY n.fecha DESC)
        FROM notas_embarque n
        WHERE n.embarque_id = p_embarque_id
      ), '[]'::jsonb),
      'facturas', COALESCE((
        SELECT jsonb_agg(to_jsonb(f.*) ORDER BY f.created_at, f.id)
        FROM facturas f
        WHERE f.embarque_id = p_embarque_id
      ), '[]'::jsonb)
    )
  END;
$$;
CREATE FUNCTION public.get_exposicion_credito_cliente(p_cliente_id uuid) RETURNS TABLE(cliente_id uuid, organization_id uuid, dias_credito integer, limite_mxn numeric, en_uso_mxn numeric, disponible_mxn numeric, excedido boolean, facturas_vivas integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_dias integer;
  v_limite numeric;
  v_en_uso numeric := 0;
  v_facturas integer := 0;
BEGIN
  SELECT c.organization_id, c.dias_credito, c.limite_credito_mxn
    INTO v_org, v_dias, v_limite
  FROM public.clientes c
  WHERE c.id = p_cliente_id
    AND c.deleted_at IS NULL
    AND (
      c.organization_id = public.current_user_org_id()
      OR public.has_role(auth.uid(), 'super_admin'::app_role)
    );
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Cliente no encontrado o sin acceso'
      USING ERRCODE = '42501';
  END IF;
  WITH facturas_cliente AS (
    SELECT
      f.id,
      f.total,
      f.moneda,
      COALESCE(NULLIF(f.tipo_cambio, 0), 1) AS tc
    FROM public.facturas f
    WHERE f.cliente_id = p_cliente_id
      AND f.estado IN ('Emitida','Vencida','Parcialmente pagada','Pagada')
      AND f.deleted_at IS NULL
  ),
  pagos_por_factura AS (
    SELECT p.factura_id, COALESCE(SUM(p.monto_aplicado_factura), 0) AS pagado
    FROM public.pagos_factura p
    WHERE p.deleted_at IS NULL
      AND p.factura_id IN (SELECT id FROM facturas_cliente)
    GROUP BY p.factura_id
  ),
  nc_por_factura AS (
    SELECT n.factura_id, COALESCE(SUM(n.monto), 0) AS nc_aplicada
    FROM public.factura_notas_credito n
    WHERE n.deleted_at IS NULL
      AND n.estado = 'Aplicada'
      AND n.factura_id IN (SELECT id FROM facturas_cliente)
    GROUP BY n.factura_id
  )
  SELECT
    COALESCE(SUM(
      GREATEST(
        0,
        COALESCE(fc.total, 0)
        - COALESCE(pf.pagado, 0)
        - COALESCE(nc.nc_aplicada, 0)
      ) * CASE WHEN fc.moneda = 'MXN' THEN 1 ELSE fc.tc END
    ), 0),
    COUNT(*)
  INTO v_en_uso, v_facturas
  FROM facturas_cliente fc
  LEFT JOIN pagos_por_factura pf ON pf.factura_id = fc.id
  LEFT JOIN nc_por_factura nc ON nc.factura_id = fc.id;
  cliente_id      := p_cliente_id;
  organization_id := v_org;
  dias_credito    := v_dias;
  limite_mxn      := v_limite;
  en_uso_mxn      := ROUND(v_en_uso, 2);
  disponible_mxn  := CASE WHEN v_limite IS NULL THEN NULL ELSE ROUND(v_limite - v_en_uso, 2) END;
  excedido        := CASE WHEN v_limite IS NULL THEN false ELSE v_en_uso > v_limite END;
  facturas_vivas  := v_facturas;
  RETURN NEXT;
END;
$$;
CREATE FUNCTION public.get_facturapi_api_key_internal(p_org_id uuid, p_ambiente text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'extensions'
    AS $$
DECLARE
  v_vault_id uuid;
  v_secret text;
BEGIN
  IF p_ambiente NOT IN ('sandbox','live') THEN
    RAISE EXCEPTION 'ambiente_invalido' USING ERRCODE = '22023';
  END IF;
  IF p_ambiente = 'sandbox' THEN
    SELECT api_key_sandbox_vault_id INTO v_vault_id FROM public.facturapi_credenciales WHERE organization_id = p_org_id;
  ELSE
    SELECT api_key_live_vault_id INTO v_vault_id FROM public.facturapi_credenciales WHERE organization_id = p_org_id;
  END IF;
  IF v_vault_id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE id = v_vault_id;
  RETURN v_secret;
END;
$$;
CREATE FUNCTION public.get_operadores_para_cotizacion(p_cotizacion_id uuid) RETURNS TABLE(user_id uuid, email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.cotizaciones
  WHERE id = p_cotizacion_id
    AND cliente_id IN (SELECT public.current_user_client_ids());
  IF v_org IS NULL THEN
    RETURN;
  END IF;
  RETURN QUERY
  SELECT om.user_id, u.email::text
  FROM public.organization_members om
  JOIN auth.users u ON u.id = om.user_id
  WHERE om.organization_id = v_org
    AND om.role IN ('admin'::app_role, 'operador'::app_role)
    AND u.email IS NOT NULL;
END;
$$;
CREATE TABLE public.costeo_agentes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    proveedor_id uuid NOT NULL,
    nombre text NOT NULL,
    pais text DEFAULT 'CN'::text NOT NULL,
    dias_credito integer DEFAULT 0 NOT NULL,
    contacto_tarifario text,
    email text,
    activo boolean DEFAULT true NOT NULL,
    notas text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT costeo_agentes_dias_credito_check CHECK ((dias_credito >= 0))
);
CREATE TABLE public.costeo_naviera_demoras_tarifa (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    naviera_condicion_id uuid NOT NULL,
    tipo_contenedor_id uuid NOT NULL,
    desde_dia integer NOT NULL,
    hasta_dia integer,
    monto_por_dia numeric(12,2) NOT NULL,
    moneda text DEFAULT 'USD'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid NOT NULL,
    CONSTRAINT costeo_naviera_demoras_tarifa_check CHECK (((hasta_dia IS NULL) OR (hasta_dia >= desde_dia))),
    CONSTRAINT costeo_naviera_demoras_tarifa_desde_dia_check CHECK ((desde_dia >= 1)),
    CONSTRAINT costeo_naviera_demoras_tarifa_monto_por_dia_check CHECK ((monto_por_dia >= (0)::numeric))
);
CREATE TABLE public.costeo_navieras_condiciones (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    naviera_id uuid NOT NULL,
    proveedor_id uuid NOT NULL,
    tiene_carta_garantia boolean DEFAULT false NOT NULL,
    carta_garantia_vigente_hasta date,
    carta_garantia_folio text,
    carta_garantia_notas text,
    dias_libres_demoras_default integer DEFAULT 0 NOT NULL,
    moneda_demoras text DEFAULT 'USD'::text NOT NULL,
    notas text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deposito_contenedor_usd numeric(12,2) DEFAULT 0 NOT NULL,
    frecuencia text,
    CONSTRAINT carta_garantia_requires_fecha CHECK (((tiene_carta_garantia = false) OR (carta_garantia_vigente_hasta IS NOT NULL))),
    CONSTRAINT costeo_nav_cond_frecuencia_chk CHECK (((frecuencia IS NULL) OR (frecuencia = ANY (ARRAY['Diaria'::text, 'Semanal'::text, 'Quincenal'::text, 'Mensual'::text, 'Bajo demanda'::text])))),
    CONSTRAINT costeo_navieras_condiciones_deposito_contenedor_usd_check CHECK ((deposito_contenedor_usd >= (0)::numeric)),
    CONSTRAINT costeo_navieras_condiciones_dias_libres_demoras_default_check CHECK ((dias_libres_demoras_default >= 0))
);
CREATE TABLE public.costeo_rutas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    puerto_origen_id uuid NOT NULL,
    puerto_destino_id uuid NOT NULL,
    activa boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE public.costeo_tarifa_recargos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tarifa_id uuid NOT NULL,
    concepto text NOT NULL,
    lado text NOT NULL,
    monto numeric(12,2) DEFAULT 0 NOT NULL,
    moneda text DEFAULT 'USD'::text NOT NULL,
    incluido_en_total boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid NOT NULL,
    CONSTRAINT costeo_tarifa_recargos_lado_check CHECK ((lado = ANY (ARRAY['origen'::text, 'destino'::text]))),
    CONSTRAINT costeo_tarifa_recargos_monto_check CHECK ((monto >= (0)::numeric))
);
CREATE TABLE public.costeo_tarifas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    agente_id uuid NOT NULL,
    naviera_id uuid NOT NULL,
    ruta_id uuid NOT NULL,
    tipo_contenedor_id uuid NOT NULL,
    moneda text DEFAULT 'USD'::text NOT NULL,
    flete_base numeric(12,2) NOT NULL,
    dias_libres_demoras integer DEFAULT 0 NOT NULL,
    vigente_desde date NOT NULL,
    vigente_hasta date NOT NULL,
    transit_time_dias integer,
    notas text,
    estado text DEFAULT 'vigente'::text NOT NULL,
    creado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reemplazada_por uuid,
    frecuencia_override text,
    dias_libres_almacenaje_lcl integer,
    estado_aprobacion text DEFAULT 'vigente'::text NOT NULL,
    motivo_rechazo text,
    aprobada_por uuid,
    aprobada_en timestamp with time zone,
    CONSTRAINT costeo_tarifas_check CHECK ((vigente_hasta >= vigente_desde)),
    CONSTRAINT costeo_tarifas_dias_libres_almacenaje_lcl_chk CHECK (((dias_libres_almacenaje_lcl IS NULL) OR (dias_libres_almacenaje_lcl >= 0))),
    CONSTRAINT costeo_tarifas_dias_libres_demoras_check CHECK ((dias_libres_demoras >= 0)),
    CONSTRAINT costeo_tarifas_estado_aprobacion_check CHECK ((estado_aprobacion = ANY (ARRAY['borrador'::text, 'vigente'::text, 'rechazada'::text]))),
    CONSTRAINT costeo_tarifas_estado_check CHECK ((estado = ANY (ARRAY['borrador'::text, 'vigente'::text, 'vencida'::text, 'reemplazada'::text]))),
    CONSTRAINT costeo_tarifas_flete_base_check CHECK ((flete_base >= (0)::numeric)),
    CONSTRAINT costeo_tarifas_frecuencia_override_chk CHECK (((frecuencia_override IS NULL) OR (frecuencia_override = ANY (ARRAY['Diaria'::text, 'Semanal'::text, 'Quincenal'::text, 'Mensual'::text, 'Bajo demanda'::text]))))
);
CREATE TABLE public.navieras (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    tracking_url_template text
);
CREATE TABLE public.puertos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    country text NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE public.tipos_contenedor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE VIEW public.costeo_tarifas_vigentes_v WITH (security_invoker='on') AS
 SELECT t.id,
    t.organization_id,
    t.agente_id,
    a.nombre AS agente_nombre,
    a.dias_credito,
    t.naviera_id,
    n.name AS naviera_nombre,
    t.ruta_id,
    r.puerto_origen_id,
    r.puerto_destino_id,
    po.name AS puerto_origen_nombre,
    pd.name AS puerto_destino_nombre,
    t.tipo_contenedor_id,
    tc.name AS tipo_contenedor_nombre,
    t.moneda,
    t.flete_base,
    COALESCE(( SELECT sum(rc.monto) AS sum
           FROM public.costeo_tarifa_recargos rc
          WHERE ((rc.tarifa_id = t.id) AND rc.incluido_en_total)), (0)::numeric) AS recargos_total,
    (t.flete_base + COALESCE(( SELECT sum(rc.monto) AS sum
           FROM public.costeo_tarifa_recargos rc
          WHERE ((rc.tarifa_id = t.id) AND rc.incluido_en_total)), (0)::numeric)) AS total_comparable,
    t.dias_libres_demoras,
    t.transit_time_dias,
    t.vigente_desde,
    t.vigente_hasta,
    t.estado,
    nc.id AS naviera_condicion_id,
    COALESCE(nc.tiene_carta_garantia, false) AS naviera_tiene_carta_garantia,
    nc.carta_garantia_vigente_hasta AS naviera_carta_garantia_vigente_hasta,
    ((nc.tiene_carta_garantia = true) AND (nc.carta_garantia_vigente_hasta IS NOT NULL) AND (nc.carta_garantia_vigente_hasta >= ((now() AT TIME ZONE 'America/Mexico_City'::text))::date)) AS naviera_carta_garantia_activa,
    nc.dias_libres_demoras_default AS naviera_dias_libres_default,
    ( SELECT dt.monto_por_dia
           FROM public.costeo_naviera_demoras_tarifa dt
          WHERE ((dt.naviera_condicion_id = nc.id) AND (dt.tipo_contenedor_id = t.tipo_contenedor_id) AND (dt.desde_dia <= 6) AND ((dt.hasta_dia IS NULL) OR (dt.hasta_dia >= 6)))
          ORDER BY dt.desde_dia DESC
         LIMIT 1) AS naviera_demora_dia_6,
    t.dias_libres_almacenaje_lcl,
    COALESCE(t.frecuencia_override, nc.frecuencia) AS frecuencia_resuelta,
    nc.frecuencia AS naviera_frecuencia,
    t.frecuencia_override AS tarifa_frecuencia_override
   FROM (((((((public.costeo_tarifas t
     JOIN public.costeo_agentes a ON ((a.id = t.agente_id)))
     JOIN public.navieras n ON ((n.id = t.naviera_id)))
     JOIN public.costeo_rutas r ON ((r.id = t.ruta_id)))
     JOIN public.puertos po ON ((po.id = r.puerto_origen_id)))
     JOIN public.puertos pd ON ((pd.id = r.puerto_destino_id)))
     JOIN public.tipos_contenedor tc ON ((tc.id = t.tipo_contenedor_id)))
     LEFT JOIN public.costeo_navieras_condiciones nc ON (((nc.naviera_id = t.naviera_id) AND (nc.organization_id = t.organization_id))))
  WHERE ((t.estado_aprobacion = 'vigente'::text) AND (t.estado = 'vigente'::text) AND (a.activo = true) AND ((t.vigente_hasta IS NULL) OR (t.vigente_hasta >= ((now() AT TIME ZONE 'America/Mexico_City'::text))::date)));
CREATE FUNCTION public.get_top_tarifas(p_puerto_origen_id uuid, p_puerto_destino_id uuid, p_tipo_contenedor_id uuid, p_fecha date DEFAULT CURRENT_DATE, p_organization_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.costeo_tarifas_vigentes_v
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT v.*
    FROM public.costeo_tarifas_vigentes_v v
   WHERE v.puerto_origen_id  = p_puerto_origen_id
     AND v.puerto_destino_id = p_puerto_destino_id
     AND v.tipo_contenedor_id = p_tipo_contenedor_id
     AND v.estado = 'vigente'
     AND v.vigente_desde <= p_fecha
     AND v.vigente_hasta >= p_fecha
     AND (p_organization_id IS NULL OR v.organization_id = p_organization_id)
     -- Membresía SIEMPRE obligatoria, se pase o no p_organization_id.
     AND EXISTS (
       SELECT 1 FROM public.organization_members om
        WHERE om.organization_id = v.organization_id
          AND om.user_id = auth.uid()
     )
   ORDER BY v.total_comparable ASC,
            v.dias_credito DESC NULLS LAST,
            v.dias_libres_demoras DESC NULLS LAST
   LIMIT 3;
$$;
CREATE FUNCTION public.get_top_tarifas_por_codigo(p_origen_code text, p_destino_code text, p_contenedor_code text, p_fecha date DEFAULT CURRENT_DATE, p_organization_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.costeo_tarifas_vigentes_v
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT * FROM public.get_top_tarifas(
    public.resolver_puerto_id(p_origen_code),
    public.resolver_puerto_id(p_destino_code),
    public.resolver_tipo_contenedor_id(p_contenedor_code),
    p_fecha,
    p_organization_id
  );
$$;
CREATE FUNCTION public.get_tracking_public(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link RECORD;
  v_embarque jsonb;
  v_eventos jsonb;
  v_org jsonb;
  v_rl jsonb;
  v_docs jsonb;
  v_modo text;
  v_estado text;
BEGIN
  v_rl := public.check_ratelimit(
    'rpc:get_tracking_public:'
      || COALESCE(NULLIF(current_setting('request.headers', true)::jsonb->>'x-forwarded-for', ''), 'sin-ip')
      || ':' || COALESCE(auth.uid()::text, 'anon'),
    60, 60
  );
  IF (v_rl->>'ok') = 'false' THEN
    RAISE EXCEPTION 'Demasiadas solicitudes. Intenta de nuevo en % segundos.', COALESCE(v_rl->>'retry_after', '60')
      USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO v_link FROM public.tracking_links WHERE token = p_token;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF v_link.expires_at IS NOT NULL AND v_link.expires_at < now() THEN
    RETURN jsonb_build_object('error', 'expired');
  END IF;
  SELECT to_jsonb(e) - 'created_at' - 'updated_at' INTO v_embarque
  FROM (
    SELECT id, expediente, cliente_nombre, modo, tipo, estado, etd, eta,
           puerto_origen, puerto_destino, aeropuerto_origen, aeropuerto_destino,
           ciudad_origen, ciudad_destino, tipo_servicio, tipo_carga,
           naviera, aerolinea, transportista
    FROM public.embarques WHERE id = v_link.embarque_id AND deleted_at IS NULL
  ) e;
  IF v_embarque IS NULL THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  -- RUX-01: sólo hitos de negocio y sin marcas internas/semilla/E2E.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'tipo', tipo, 'descripcion', descripcion, 'ubicacion', ubicacion, 'fecha', fecha
  ) ORDER BY fecha DESC), '[]'::jsonb)
  INTO v_eventos
  FROM public.eventos_embarque
  WHERE embarque_id = v_link.embarque_id
    AND tipo::text IN (
      'Zarpe', 'Transbordo', 'Arribo a Puerto', 'Descarga',
      'Despacho Aduanal', 'Liberación', 'En Ruta Terrestre', 'Entrega',
      'Cambio de ETA'
    )
    AND lower(COALESCE(descripcion, '')) NOT LIKE '%[interno]%'
    AND lower(COALESCE(descripcion, '')) NOT LIKE '%harness%'
    AND lower(COALESCE(descripcion, '')) NOT LIKE '%e2e%'
    AND lower(COALESCE(descripcion, '')) NOT LIKE '%seed%'
    AND lower(COALESCE(descripcion, '')) NOT LIKE '%qa-%'
    AND lower(COALESCE(usuario, '')) NOT LIKE '%[interno]%'
    AND lower(COALESCE(usuario, '')) NOT LIKE '%harness%'
    AND lower(COALESCE(usuario, '')) NOT LIKE '%e2e%'
    AND lower(COALESCE(usuario, '')) NOT LIKE '%seed%'
    AND lower(COALESCE(usuario, '')) NOT LIKE '%qa-%';
  -- Avance documental visible al cliente: sólo nombre + si ya se recibió.
  -- Nunca se expone `archivo` ni `notas` (información interna).
  v_modo   := v_embarque->>'modo';
  v_estado := v_embarque->>'estado';
  WITH requeridos AS (
    SELECT unnest(public._docs_requeridos_por_estado(v_modo, v_estado)) AS nombre
  ),
  cargados AS (
    SELECT nombre, estado::text AS estado
    FROM public.documentos_embarque
    WHERE embarque_id = v_link.embarque_id
      AND deleted_at IS NULL
  ),
  unidos AS (
    SELECT COALESCE(r.nombre, c.nombre) AS nombre,
           COALESCE(c.estado, 'Pendiente') AS estado,
           (r.nombre IS NOT NULL) AS requerido
    FROM requeridos r
    FULL OUTER JOIN cargados c ON c.nombre = r.nombre
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'nombre', nombre,
    'estado', estado,
    'requerido', requerido,
    'recibido', estado IN ('Recibido', 'Validado')
  ) ORDER BY (estado IN ('Recibido', 'Validado')), nombre), '[]'::jsonb)
  INTO v_docs
  FROM unidos;
  SELECT jsonb_build_object('nombre', nombre, 'logo_url', logo_url) INTO v_org
  FROM public.organizations WHERE id = v_link.organization_id;
  RETURN jsonb_build_object(
    'embarque', v_embarque,
    'eventos', v_eventos,
    'documentos', COALESCE(v_docs, '[]'::jsonb),
    'organizacion', v_org
  );
END;
$$;
CREATE FUNCTION public.get_user_context() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'role', (
      SELECT role::text FROM public.user_roles
      WHERE user_id = auth.uid()
      ORDER BY CASE role::text
        WHEN 'super_admin' THEN 1 WHEN 'admin_org' THEN 2 WHEN 'admin' THEN 3
        WHEN 'gerente_operaciones' THEN 4 WHEN 'contador' THEN 5 WHEN 'tesorero' THEN 6
        WHEN 'ejecutivo_pricing' THEN 7 WHEN 'coordinador_logistico' THEN 8
        WHEN 'operador' THEN 9 WHEN 'vendedor' THEN 10 WHEN 'customer_service' THEN 11
        WHEN 'viewer' THEN 12 WHEN 'cliente' THEN 13 ELSE 99
      END LIMIT 1
    ),
    'orgRole', (
      SELECT role::text FROM public.organization_members
      WHERE user_id = auth.uid()
      ORDER BY CASE role::text
        WHEN 'super_admin' THEN 1 WHEN 'admin_org' THEN 2 WHEN 'admin' THEN 3
        WHEN 'gerente_operaciones' THEN 4 WHEN 'contador' THEN 5 WHEN 'tesorero' THEN 6
        WHEN 'ejecutivo_pricing' THEN 7 WHEN 'coordinador_logistico' THEN 8
        WHEN 'operador' THEN 9 WHEN 'vendedor' THEN 10 WHEN 'customer_service' THEN 11
        WHEN 'viewer' THEN 12 WHEN 'cliente' THEN 13 ELSE 99
      END LIMIT 1
    ),
    'organizationId', public.default_user_org_id(),
    'organization', (
      SELECT jsonb_build_object(
        'id', o.id, 'nombre', o.nombre, 'logo_url', o.logo_url, 'plan', o.plan,
        'rfc', o.rfc, 'activo', o.activo,
        'direccion', o.direccion,
        'moneda_preferida', o.moneda_preferida,
        'onboarding_completado', o.onboarding_completado
      )
      FROM public.organizations o
      WHERE o.id = public.default_user_org_id()
    )
  );
$$;
CREATE FUNCTION public.get_user_org_ids(_user_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT organization_id FROM public.organization_members WHERE user_id = _user_id;
$$;
CREATE FUNCTION public.guard_aprobacion_proveedor_factura() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado_aprobacion IS NOT DISTINCT FROM OLD.estado_aprobacion THEN
    RETURN NEW;
  END IF;
  -- Volver a 'pendiente' (re-aprobación tras editar la factura) no otorga
  -- aprobación: se permite por el canal normal de edición.
  IF NEW.estado_aprobacion = 'pendiente'::public.estado_aprobacion_factura_proveedor THEN
    RETURN NEW;
  END IF;
  IF current_setting('app.aprobando_cxp', true) IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'LC_CXP_APROBACION_DIRECTA: use aprobar_factura_proveedor()'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.guard_cuenta_bancaria_moneda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.moneda IS DISTINCT FROM OLD.moneda
     AND EXISTS (
       SELECT 1 FROM public.bbva_movimientos
       WHERE cuenta_bancaria_id = OLD.id
     ) THEN
    RAISE EXCEPTION 'LC_CUENTA_MONEDA_CON_MOVIMIENTOS: La cuenta ya tiene movimientos registrados en %; la moneda no se puede cambiar.',
      OLD.moneda
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.guard_cxp_cancelacion_rol_financiero() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_rol public.app_role;
  -- Roles financieros autorizados a cancelar una factura de proveedor.
  c_permitidos public.app_role[] := ARRAY[
    'admin', 'super_admin', 'admin_org', 'contador', 'auxiliar_contable', 'tesorero'
  ]::public.app_role[];
BEGIN
  IF NEW.estado IS NOT DISTINCT FROM OLD.estado THEN RETURN NEW; END IF;
  IF NEW.estado <> 'Cancelada'::public.estado_proveedor_factura THEN RETURN NEW; END IF;
  -- Procesos del sistema (crons, edge functions) siguen operando.
  IF v_uid IS NULL OR auth.role() = 'service_role' THEN RETURN NEW; END IF;
  -- El rol operativo vive en organization_members (rol_efectivo); user_roles es
  -- el fallback para roles de plataforma. Sólo mirar has_role bloqueaba a
  -- admin_org legítimos.
  v_rol := public.rol_efectivo(v_uid, NEW.organization_id);
  IF NOT (v_rol = ANY (c_permitidos)
          OR public.has_role(v_uid, 'admin'::app_role)
          OR public.has_role(v_uid, 'super_admin'::app_role)
          OR public.has_role(v_uid, 'admin_org'::app_role)
          OR public.has_role(v_uid, 'contador'::app_role)
          OR public.has_role(v_uid, 'auxiliar_contable'::app_role)
          OR public.has_role(v_uid, 'tesorero'::app_role)) THEN
    RAISE EXCEPTION 'LC_CXP_CANCELAR_FORBIDDEN: tu rol no puede cancelar facturas de proveedor.'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.guard_estado_cotizacion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old text := OLD.estado::text;
  v_new text := NEW.estado::text;
BEGIN
  IF v_old IS NULL OR v_new IS NULL OR v_old = v_new THEN
    RETURN NEW;
  END IF;
  -- Vencida siempre puede aplicarse desde cualquier estado no terminal
  IF v_new = 'Vencida' AND v_old IN ('Solicitada','Borrador','Enviada','Aceptada') THEN
    RETURN NEW;
  END IF;
  -- Housekeeping: Vencida >90 días → Archivada (C5)
  IF v_old = 'Vencida' AND v_new = 'Archivada' THEN
    RETURN NEW;
  END IF;
  -- Reactivación manual desde estados de housekeeping (A3).
  -- RG11: 'Aceptada' fuera de la lista (requiere snapshot del flujo normal).
  IF v_old IN ('Vencida','Archivada')
     AND v_new IN ('Solicitada','Borrador','Enviada') THEN
    RETURN NEW;
  END IF;
  -- Transiciones válidas
  IF (v_old = 'Solicitada'    AND v_new IN ('Borrador','Enviada','Aceptada','Rechazada'))
  OR (v_old = 'Borrador'      AND v_new IN ('Enviada','Aceptada','Rechazada'))
  OR (v_old = 'Enviada'       AND v_new IN ('Aceptada','Rechazada'))
  OR (v_old = 'Aceptada'      AND v_new IN ('En operación'))
  THEN
    RETURN NEW;
  END IF;
  -- FIX4 N-1: la papelera de embarques (sync_cotizacion_embarque_link)
  -- revierte 'En operación' → 'Aceptada' al liberar la cotización. Es la
  -- única transición admitida bajo la GUC transaccional
  -- app.liberando_papelera; sin ella, LC_COT_TRANSICION_INVALIDA.
  IF v_old = 'En operación' AND v_new = 'Aceptada'
     AND current_setting('app.liberando_papelera', true) = 'on' THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'LC_COT_TRANSICION_INVALIDA: no se puede pasar de % a %', v_old, v_new
    USING ERRCODE = 'P0001';
END;
$$;
CREATE FUNCTION public.guard_estado_factura() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_pagos_vivos int; v_bypass boolean;
BEGIN
  IF NEW.estado IS NOT DISTINCT FROM OLD.estado THEN RETURN NEW; END IF;
  IF OLD.estado = 'Cancelada'::estado_factura THEN
    RAISE EXCEPTION 'LC_FAC_REAPERTURA: una factura cancelada no puede reabrirse' USING ERRCODE='P0001';
  END IF;
  IF NEW.estado = 'Cancelada'::estado_factura THEN
    SELECT count(*) INTO v_pagos_vivos FROM public.pagos_factura
      WHERE factura_id=OLD.id AND deleted_at IS NULL;
    IF v_pagos_vivos > 0 THEN
      RAISE EXCEPTION 'LC_FAC_CANCEL_CON_PAGOS: revierta los % pagos vivos antes de cancelar', v_pagos_vivos USING ERRCODE='P0001';
    END IF;
  END IF;
  v_bypass := (current_setting('app.recalc_estado_factura', true) = '1')
              AND (
                COALESCE(auth.role()::text,'') = 'service_role'
                OR current_user = 'postgres'
                OR public.has_role(auth.uid(),'super_admin'::app_role)
              );
  IF NEW.estado IN ('Pagada'::estado_factura,'Parcialmente pagada'::estado_factura,'Vencida'::estado_factura)
     AND NOT v_bypass THEN
    RAISE EXCEPTION 'LC_FAC_ESTADO_CALCULADO: el estado % sólo puede fijarlo el recálculo automático', NEW.estado USING ERRCODE='P0001';
  END IF;
  RETURN NEW;
END; $$;
CREATE FUNCTION public.guard_estado_proveedor_factura() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado IS NOT DISTINCT FROM OLD.estado THEN
    RETURN NEW;
  END IF;
  -- Solo se permite pasar a Cancelada vía cancelar_factura_proveedor()
  IF NEW.estado = 'Cancelada'::public.estado_proveedor_factura
     AND current_setting('app.cancelando_cxp', true) IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'LC_CXP_CANCEL_DIRECTA: use cancelar_factura_proveedor()'
      USING ERRCODE = '42501';
  END IF;
  IF OLD.estado = 'Cancelada'::public.estado_proveedor_factura THEN
    RAISE EXCEPTION 'LC_CXP_REAPERTURA: una factura cancelada no puede reabrirse'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.estado = 'Pagada'::public.estado_proveedor_factura
     AND NEW.estado <> 'Pagada'::public.estado_proveedor_factura
     AND current_setting('app.recalc_cxp', true) IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'LC_CXP_PAGADA_INMUTABLE: factura pagada; ajuste vía flujo de pagos'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.guard_factura_totales_conceptos() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_n        int;
  v_subtotal numeric;
  v_iva      numeric;
  v_isr      numeric;
  v_iva_ret  numeric;
BEGIN
  SELECT
    count(*),
    COALESCE(SUM(ROUND(COALESCE(c.cantidad, 1) * COALESCE(c.precio_unitario, 0), 2)), 0),
    COALESCE(SUM(ROUND(
        COALESCE(c.cantidad, 1) * COALESCE(c.precio_unitario, 0)
        * COALESCE(c.tasa_iva_aplicada,
                   CASE WHEN c.tipo_iva = 'gravado_16' THEN 0.16
                        WHEN c.tipo_iva = 'gravado_8'  THEN 0.08
                        ELSE 0 END),
        2)), 0),
    COALESCE(SUM(COALESCE(c.monto_ret_isr, 0)), 0),
    COALESCE(SUM(COALESCE(c.monto_ret_iva, 0)), 0)
  INTO v_n, v_subtotal, v_iva, v_isr, v_iva_ret
  FROM public.conceptos_factura c
  WHERE c.factura_id = NEW.id
    AND c.deleted_at IS NULL;
  IF v_n > 0 THEN
    NEW.subtotal := v_subtotal;
    NEW.iva      := v_iva;
    NEW.ret_isr  := v_isr;
    NEW.ret_iva  := v_iva_ret;
    NEW.total    := v_subtotal + v_iva - v_isr - v_iva_ret;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.guard_nc_cliente_moneda_convertible() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_moneda text; v_tc numeric;
BEGIN
  IF NEW.estado <> 'Aplicada'::public.estado_nota_credito THEN RETURN NEW; END IF;
  SELECT f.moneda::text, f.tipo_cambio INTO v_moneda, v_tc
  FROM public.facturas f WHERE f.id = NEW.factura_id;
  IF v_moneda IS NULL OR NEW.moneda::text = v_moneda THEN RETURN NEW; END IF;
  IF NEW.moneda::text <> 'MXN' AND COALESCE(NEW.tipo_cambio, 0) <= 1 THEN
    RAISE EXCEPTION 'LC_NC_MONEDA_SIN_TC: captura el tipo de cambio de la nota de crédito en % antes de aplicarla', NEW.moneda
      USING ERRCODE = '22023';
  END IF;
  IF v_moneda <> 'MXN' AND COALESCE(v_tc, 0) <= 1 THEN
    RAISE EXCEPTION 'LC_NC_MONEDA_SIN_TC: la factura en % no tiene tipo de cambio para convertir la nota de crédito', v_moneda
      USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.guard_nc_cliente_transicion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old text;
  v_new text := NEW.estado::text;
BEGIN
  IF NEW.estado::text IN ('Timbrada','Aplicada')
     AND COALESCE(NULLIF(TRIM(NEW.uuid_fiscal), ''), NULL) IS NULL THEN
    RAISE EXCEPTION 'LC_NC_UUID_REQUERIDO: timbra la nota de crédito (folio fiscal UUID) antes de marcarla como %', v_new
      USING ERRCODE = '22023';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    v_old := OLD.estado::text;
    IF v_old IS DISTINCT FROM v_new THEN
      IF NOT (
        (v_old = 'Borrador'  AND v_new IN ('Timbrada','Cancelada')) OR
        (v_old = 'Timbrada'  AND v_new IN ('Aplicada','Cancelada')) OR
        (v_old = 'Aplicada'  AND v_new = 'Cancelada') OR
        (v_old = 'Aprobada'  AND v_new IN ('Timbrada','Cancelada'))
      ) THEN
        RAISE EXCEPTION 'LC_NC_TRANSICION_INVALIDA: no se puede pasar la nota de crédito de % a %', v_old, v_new
          USING ERRCODE = '22023';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.guard_pago_proveedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fact_moneda public.moneda;
  v_fact_tc     numeric;
  v_fact_total  numeric;
  v_fact_estado public.estado_proveedor_factura;
  v_fact_deleted timestamptz;
  v_ncs         numeric;
  v_pagos       numeric;
  v_saldo       numeric;
  v_solo_metadatos boolean := false;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    v_solo_metadatos := (
      NEW.proveedor_factura_id IS NOT DISTINCT FROM OLD.proveedor_factura_id
      AND NEW.monto IS NOT DISTINCT FROM OLD.monto
      AND NEW.moneda IS NOT DISTINCT FROM OLD.moneda
      AND NEW.tipo_cambio_usd IS NOT DISTINCT FROM OLD.tipo_cambio_usd
      AND OLD.deleted_at IS NULL
    );
    IF v_solo_metadatos THEN
      RETURN NEW;
    END IF;
  END IF;
  SELECT moneda, tipo_cambio_usd, COALESCE(total,0), estado, deleted_at
    INTO v_fact_moneda, v_fact_tc, v_fact_total, v_fact_estado, v_fact_deleted
    FROM public.proveedor_facturas
    WHERE id = NEW.proveedor_factura_id
    FOR UPDATE;
  IF v_fact_moneda IS NULL THEN
    RAISE EXCEPTION 'LC_FACTURA_PROV_NO_ENCONTRADA: factura % no existe', NEW.proveedor_factura_id
      USING ERRCODE = 'P0002';
  END IF;
  IF v_fact_estado = 'Cancelada'::public.estado_proveedor_factura
     OR v_fact_deleted IS NOT NULL THEN
    RAISE EXCEPTION 'LC_PAGO_PROV_FACTURA_NO_VIVA: la factura de proveedor está % y no admite pagos',
      CASE WHEN v_fact_deleted IS NOT NULL THEN 'en la papelera' ELSE 'Cancelada' END
      USING ERRCODE = '23514';
  END IF;
  -- F3: los pagos directos siguen exigiendo captura MXN<->USD. Cuando el pago
  -- nace de una APLICACIÓN DE ANTICIPO, la RPC ya valuó con paridad DOF del
  -- día (soporta EUR y cruces); el guard respeta esa valuación.
  BEGIN
    NEW.monto_en_moneda_factura := public.convertir_monto_pago_a_factura(
      NEW.monto, NEW.moneda, NEW.tipo_cambio_usd, v_fact_moneda, v_fact_tc);
  EXCEPTION WHEN OTHERS THEN
    IF COALESCE(NEW.es_anticipo_aplicado, false) THEN
      NEW.monto_en_moneda_factura := public.convertir_monto_dof(
        NEW.monto, NEW.moneda::text, v_fact_moneda::text,
        COALESCE(NEW.fecha_pago, CURRENT_DATE));
    ELSE
      RAISE;
    END IF;
  END;
  IF NEW.moneda = 'MXN'::public.moneda
     AND v_fact_moneda = 'USD'::public.moneda
     AND NEW.tipo_cambio_usd IS NOT NULL AND NEW.tipo_cambio_usd > 0
     AND v_fact_tc IS NOT NULL AND v_fact_tc > 0 THEN
    NEW.diferencia_cambiaria_mxn :=
      ROUND(NEW.monto_en_moneda_factura * (NEW.tipo_cambio_usd - v_fact_tc), 2);
  ELSIF NEW.moneda = 'USD'::public.moneda
     AND v_fact_moneda = 'MXN'::public.moneda
     AND NEW.tipo_cambio_usd IS NOT NULL AND NEW.tipo_cambio_usd > 0
     AND v_fact_tc IS NOT NULL AND v_fact_tc > 0 THEN
    NEW.diferencia_cambiaria_mxn :=
      ROUND(NEW.monto * (NEW.tipo_cambio_usd - v_fact_tc), 2);
  ELSE
    NEW.diferencia_cambiaria_mxn := NULL;
  END IF;
  -- F4: misma conversión canónica que la vista v_proveedor_facturas_saldo.
  SELECT COALESCE(SUM(
           public.monto_pago_en_moneda_factura(
             nc.monto, nc.moneda::text, nc.tipo_cambio, v_fact_moneda::text)), 0)
    INTO v_ncs
    FROM public.proveedor_notas_credito nc
   WHERE nc.proveedor_factura_id = NEW.proveedor_factura_id
     AND nc.deleted_at IS NULL
     AND nc.estado::text = 'Aplicada';
  SELECT COALESCE(SUM(monto_en_moneda_factura),0) INTO v_pagos
    FROM public.pagos_proveedor
   WHERE proveedor_factura_id = NEW.proveedor_factura_id
     AND deleted_at IS NULL
     AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
  v_saldo := v_fact_total - v_ncs - v_pagos;
  IF COALESCE(NEW.monto_en_moneda_factura,0) > v_saldo + 0.005 THEN
    RAISE EXCEPTION
      'LC_PAGO_EXCEDE_SALDO: pago % excede el saldo disponible % de la factura de proveedor',
      round(COALESCE(NEW.monto_en_moneda_factura,0),2), round(v_saldo,2)
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.guard_proveedor_factura_total() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pagado numeric;
  v_ncs    numeric;
BEGIN
  NEW.total := ROUND(
      COALESCE(NEW.subtotal, 0) + COALESCE(NEW.iva, 0)
      + COALESCE(NEW.ieps, 0) - COALESCE(NEW.retenciones, 0), 2);
  IF NEW.total < 0 THEN
    RAISE EXCEPTION 'LC_CXP_TOTAL_NEGATIVO: el total de la factura de proveedor no puede ser negativo (%)',
      NEW.total
      USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.total < COALESCE(OLD.total, 0) - 0.005 THEN
    SELECT COALESCE(SUM(COALESCE(pp.monto_en_moneda_factura, pp.monto)), 0)
      INTO v_pagado
    FROM public.pagos_proveedor pp
    WHERE pp.proveedor_factura_id = NEW.id
      AND pp.deleted_at IS NULL;
    -- F4: NCs convertidas a la moneda de la factura.
    SELECT COALESCE(SUM(
             public.monto_pago_en_moneda_factura(
               nc.monto, nc.moneda::text, nc.tipo_cambio, NEW.moneda::text)), 0)
      INTO v_ncs
    FROM public.proveedor_notas_credito nc
    WHERE nc.proveedor_factura_id = NEW.id
      AND nc.deleted_at IS NULL
      AND nc.estado::text = 'Aplicada';
    IF NEW.total + 0.005 < v_pagado + v_ncs THEN
      RAISE EXCEPTION 'LC_CXP_TOTAL_MENOR_PAGADO: el nuevo total % queda por debajo de lo ya pagado/aplicado %',
        ROUND(NEW.total, 2), ROUND(v_pagado + v_ncs, 2)
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.guard_sustitucion_ciclo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.sustituye_a IS NULL THEN RETURN NEW; END IF;
  -- Rechaza ciclos directos: la sustituta ya tiene sustituye_a = NEW.id
  IF EXISTS (
    SELECT 1 FROM public.facturas
    WHERE id = NEW.sustituye_a AND sustituye_a = NEW.id
  ) THEN
    RAISE EXCEPTION 'LC_SUSTITUCION_CICLO: la factura % ya sustituye a la nueva %',
      NEW.sustituye_a, NEW.id USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.handle_first_user_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  user_count int;
BEGIN
  SELECT count(*) INTO user_count FROM public.user_roles;
  IF user_count = 0 THEN
    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'admin');
  ELSE
    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'viewer');
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.handle_new_organization() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows integer;
BEGIN
  -- Serie de facturación por defecto
  INSERT INTO public.factura_series (organization_id, codigo, prefijo, folio_actual, folio_inicial, activa, es_default, descripcion)
  VALUES (NEW.id, 'A', 'A', 0, 1, true, true, 'Serie por defecto')
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  PERFORM public._log_provisioning_step(NEW.id, 'trigger', 'seed_factura_series', 'factura_series', v_rows);
  -- Pipeline CRM
  INSERT INTO public.crm_etapas_pipeline (organization_id, nombre, orden, probabilidad_default, color, tipo)
  VALUES
    (NEW.id, 'Prospecto',    1, 10,  '#94a3b8', 'abierta'),
    (NEW.id, 'Calificado',   2, 25,  '#38bdf8', 'abierta'),
    (NEW.id, 'Propuesta',    3, 50,  '#6366f1', 'abierta'),
    (NEW.id, 'Negociación',  4, 75,  '#f59e0b', 'abierta'),
    (NEW.id, 'Ganada',       5, 100, '#10b981', 'ganada'),
    (NEW.id, 'Perdida',      6, 0,   '#ef4444', 'perdida')
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  PERFORM public._log_provisioning_step(NEW.id, 'trigger', 'seed_crm_etapas_pipeline', 'crm_etapas_pipeline', v_rows);
  -- Motivos de pérdida
  INSERT INTO public.crm_motivos_perdida (organization_id, nombre)
  VALUES
    (NEW.id, 'Precio'),
    (NEW.id, 'Tiempo de tránsito'),
    (NEW.id, 'Competencia'),
    (NEW.id, 'No responde'),
    (NEW.id, 'Otro')
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  PERFORM public._log_provisioning_step(NEW.id, 'trigger', 'seed_crm_motivos_perdida', 'crm_motivos_perdida', v_rows);
  -- Categorías de presupuesto
  INSERT INTO public.presupuesto_categorias (organization_id, nombre, orden, tipo_contable)
  VALUES
    (NEW.id, 'Ventas',           1, 'Venta'),
    (NEW.id, 'Costo directo',    2, 'CostoDirectoEmbarque'),
    (NEW.id, 'Administración',   3, 'Administracion')
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  PERFORM public._log_provisioning_step(NEW.id, 'trigger', 'seed_presupuesto_categorias', 'presupuesto_categorias', v_rows);
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.handle_new_user_signup() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_company_name text;
  v_org_id uuid;
  v_user_count int;
  v_skip boolean := coalesce(NEW.raw_user_meta_data->>'skip_auto_org', 'false') = 'true';
BEGIN
  IF v_skip THEN
    RETURN NEW;
  END IF;
  -- FIX4 P3: serializa el bootstrap super_admin. Clave estable derivada del
  -- nombre lógico del candado (hashtextextended → bigint). Dos signups
  -- concurrentes ya no pueden leer count(*)=0 a la vez: el segundo espera al
  -- commit del primero y ve la corona ya puesta.
  PERFORM pg_advisory_xact_lock(hashtextextended('elogistix.bootstrap_super_admin', 0));
  -- Bootstrap: primer usuario del sistema recibe super_admin global.
  SELECT count(*) INTO v_user_count FROM public.user_roles;
  IF v_user_count = 0 THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.id, 'super_admin'::public.app_role)
    ON CONFLICT (user_id) DO NOTHING;
  END IF;
  -- Sólo crear organización si el usuario proporcionó nombre de empresa.
  v_company_name := trim(coalesce(NEW.raw_user_meta_data->>'company_name', ''));
  IF length(v_company_name) = 0 THEN
    -- Sin company_name: NO se crea org ni membresía; el rol/membresía se fijan
    -- vía onboarding o invitación posterior.
    RETURN NEW;
  END IF;
  IF length(v_company_name) > 120 THEN
    v_company_name := substring(v_company_name FROM 1 FOR 120);
  END IF;
  INSERT INTO public.organizations (nombre, plan, activo)
  VALUES (v_company_name, 'basic', true) RETURNING id INTO v_org_id;
  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (v_org_id, NEW.id, 'admin_org'::public.app_role)
  ON CONFLICT (organization_id, user_id) DO NOTHING;
  RETURN NEW;
END $$;
CREATE FUNCTION public.has_any_role(_user_id uuid, _roles public.app_role[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = _user_id
      AND ur.role = ANY (
        SELECT DISTINCT e
        FROM unnest(_roles) AS r,
             unnest(public.roles_jerarquia(r)) AS e
      )
  )
$$;
CREATE FUNCTION public.has_any_role_efectivo(_user_id uuid, _roles public.app_role[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.has_role(_user_id, 'super_admin'::app_role)
     OR (
       public.has_any_role(_user_id, _roles)
       AND (
         NOT EXISTS (
           SELECT 1 FROM public.organization_members om
            WHERE om.user_id = _user_id
              AND om.organization_id = public.current_user_org_id()
         )
         OR EXISTS (
           SELECT 1 FROM public.organization_members om
            WHERE om.user_id = _user_id
              AND om.organization_id = public.current_user_org_id()
              AND om.role = ANY (
                SELECT DISTINCT e
                FROM unnest(_roles) AS r, unnest(public.roles_jerarquia(r)) AS e
              )
         )
       )
     );
$$;
CREATE FUNCTION public.has_any_role_in_org(_user_id uuid, _roles public.app_role[], _org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _user_id IS NOT NULL
     AND _org IS NOT NULL
     AND (
       public.has_role(_user_id, 'super_admin'::app_role)
       OR EXISTS (
         SELECT 1
           FROM public.organization_members om
          WHERE om.user_id = _user_id
            AND om.organization_id = _org
            AND om.role = ANY (
              SELECT DISTINCT e
                FROM unnest(_roles) AS r,
                     unnest(public.roles_jerarquia(r)) AS e
            )
       )
     )
$$;
CREATE FUNCTION public.has_any_role_in_org_exact(_user_id uuid, _roles public.app_role[], _org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _user_id IS NOT NULL
     AND _org IS NOT NULL
     AND (
       public.has_role(_user_id, 'super_admin'::app_role)
       OR EXISTS (
         SELECT 1
           FROM public.organization_members om
          WHERE om.user_id = _user_id
            AND om.organization_id = _org
            AND om.role = ANY (_roles)
       )
     )
$$;
CREATE FUNCTION public.has_org_role(_user_id uuid, _org_id uuid, _role public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = _user_id
      AND organization_id = _org_id
      AND role = _role
  )
$$;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = _user_id
      AND ur.role = ANY (public.roles_jerarquia(_role))
  )
$$;
CREATE FUNCTION public.has_role_in_org(_user_id uuid, _role public.app_role, _org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.has_any_role_in_org(_user_id, ARRAY[_role], _org)
$$;
CREATE FUNCTION public.historial_factura(p_factura_id uuid, p_limite integer DEFAULT 50) RETURNS TABLE(id uuid, usuario_id uuid, usuario_email text, accion text, modulo text, entidad_id uuid, entidad_nombre text, detalles jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_factura_org uuid;
  v_cliente_id uuid;
  v_limite integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  SELECT f.organization_id, f.cliente_id
    INTO v_factura_org, v_cliente_id
    FROM public.facturas f
   WHERE f.id = p_factura_id
     AND f.deleted_at IS NULL;
  IF v_factura_org IS NULL THEN
    RAISE EXCEPTION 'factura_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (
    public.has_role(auth.uid(), 'super_admin')
    OR (
      v_factura_org = public.current_user_org_id()
      AND (
        public.has_role(auth.uid(), 'admin')
        OR public.has_role(auth.uid(), 'admin_org')
        OR public.has_role(auth.uid(), 'operador')
        OR public.has_role(auth.uid(), 'contador')
        OR public.has_role(auth.uid(), 'viewer')
        OR public.has_role(auth.uid(), 'vendedor')
        OR public.has_role(auth.uid(), 'gerente_operaciones')
        OR public.has_role(auth.uid(), 'coordinador_logistico')
        OR public.has_role(auth.uid(), 'customer_service')
        OR public.has_role(auth.uid(), 'gerente_visor')
        OR public.has_role(auth.uid(), 'gerente_comercial')
        OR public.has_role(auth.uid(), 'auxiliar_contable')
        OR public.has_role(auth.uid(), 'ejecutivo_cobranza')
        OR public.has_role(auth.uid(), 'tesorero')
      )
    )
    OR (
      public.has_role(auth.uid(), 'cliente')
      AND v_cliente_id IN (SELECT public.current_user_client_ids())
    )
  ) THEN
    RAISE EXCEPTION 'factura_forbidden' USING ERRCODE = '42501';
  END IF;
  v_limite := LEAST(GREATEST(COALESCE(p_limite, 50), 1), 100);
  RETURN QUERY
  SELECT
    ba.id,
    ba.usuario_id,
    ba.usuario_email,
    ba.accion,
    ba.modulo,
    ba.entidad_id,
    ba.entidad_nombre,
    COALESCE(ba.detalles, '{}'::jsonb) AS detalles,
    ba.created_at
  FROM public.bitacora_actividad ba
  WHERE ba.modulo IN ('facturas', 'facturacion')
    AND (
      ba.entidad_id = p_factura_id
      OR ba.detalles @> jsonb_build_object('factura_id', p_factura_id::text)
      OR ba.detalles @> jsonb_build_object('factura_original_id', p_factura_id::text)
      OR ba.detalles @> jsonb_build_object('sustituye_a_factura_id', p_factura_id::text)
      OR ba.detalles @> jsonb_build_object('sustituida_por_factura_id', p_factura_id::text)
    )
  ORDER BY ba.created_at DESC
  LIMIT v_limite;
END;
$$;
CREATE FUNCTION public.historial_proveedor_factura(p_id uuid) RETURNS TABLE(ts timestamp with time zone, tipo text, descripcion text, actor_email text, monto numeric, moneda text, detalles jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  SELECT organization_id INTO v_org
  FROM public.proveedor_facturas
  WHERE id = p_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Factura no encontrada';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.organization_id = v_org AND om.user_id = v_uid
  ) AND NOT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid AND ur.role::text = 'super_admin'
  ) THEN
    RAISE EXCEPTION 'Sin acceso a la factura';
  END IF;
  RETURN QUERY
  WITH eventos AS (
    SELECT
      pf.created_at AS ev_ts,
      'creada'::text AS ev_tipo,
      'Factura capturada'::text AS ev_descripcion,
      COALESCE(u.email, '')::text AS ev_actor_email,
      pf.total AS ev_monto,
      pf.moneda::text AS ev_moneda,
      jsonb_build_object('folio', pf.folio_proveedor) AS ev_detalles
    FROM public.proveedor_facturas pf
    LEFT JOIN auth.users u ON u.id = pf.created_by
    WHERE pf.id = p_id
    UNION ALL
    SELECT
      pf.aprobada_at,
      CASE pf.estado_aprobacion::text
        WHEN 'aprobada' THEN 'aprobada'
        WHEN 'rechazada' THEN 'rechazada'
        ELSE pf.estado_aprobacion::text
      END,
      CASE pf.estado_aprobacion::text
        WHEN 'aprobada' THEN 'Factura aprobada'
        WHEN 'rechazada' THEN 'Factura rechazada'
        ELSE 'Cambio de estado'
      END,
      COALESCE(u.email, '')::text,
      NULL::numeric,
      NULL::text,
      jsonb_build_object('motivo_rechazo', pf.motivo_rechazo)
    FROM public.proveedor_facturas pf
    LEFT JOIN auth.users u ON u.id = pf.aprobada_por
    WHERE pf.id = p_id AND pf.aprobada_at IS NOT NULL
    UNION ALL
    SELECT
      pp.fecha_pago::timestamptz,
      'pago'::text,
      ('Pago registrado' ||
        CASE WHEN pp.referencia IS NOT NULL AND pp.referencia <> ''
             THEN ' · ref ' || pp.referencia ELSE '' END)::text,
      COALESCE(u.email, '')::text,
      pp.monto,
      pp.moneda::text,
      jsonb_build_object('metodo_pago', pp.metodo_pago, 'referencia', pp.referencia)
    FROM public.pagos_proveedor pp
    LEFT JOIN auth.users u ON u.id = pp.created_by
    WHERE pp.proveedor_factura_id = p_id AND pp.deleted_at IS NULL
    UNION ALL
    SELECT
      nc.created_at,
      'nota_credito'::text,
      ('Nota de crédito ' || COALESCE(nc.folio_nc, '') ||
        CASE WHEN nc.motivo IS NOT NULL AND nc.motivo::text <> ''
             THEN ' · ' || nc.motivo::text ELSE '' END)::text,
      COALESCE(u.email, '')::text,
      nc.monto,
      nc.moneda::text,
      jsonb_build_object('folio', nc.folio_nc, 'estado', nc.estado)
    FROM public.proveedor_notas_credito nc
    LEFT JOIN auth.users u ON u.id = nc.created_by
    WHERE nc.proveedor_factura_id = p_id AND nc.deleted_at IS NULL
    UNION ALL
    SELECT
      pf.deleted_at,
      'eliminada'::text,
      'Factura enviada a papelera'::text,
      COALESCE(u.email, '')::text,
      NULL::numeric,
      NULL::text,
      '{}'::jsonb
    FROM public.proveedor_facturas pf
    LEFT JOIN auth.users u ON u.id = pf.deleted_by
    WHERE pf.id = p_id AND pf.deleted_at IS NOT NULL
    UNION ALL
    SELECT
      b.created_at,
      COALESCE(b.accion, 'evento')::text,
      COALESCE(b.entidad_nombre, b.accion)::text,
      COALESCE(b.usuario_email, '')::text,
      NULL::numeric,
      NULL::text,
      COALESCE(b.detalles, '{}'::jsonb)
    FROM public.bitacora_actividad b
    WHERE b.entidad_id = p_id
      AND b.modulo = 'cxp'
      AND b.accion NOT IN ('aprobar_factura_proveedor', 'rechazar_factura_proveedor')
  )
  SELECT
    e.ev_ts, e.ev_tipo, e.ev_descripcion, e.ev_actor_email,
    e.ev_monto, e.ev_moneda, e.ev_detalles
  FROM eventos e
  WHERE e.ev_ts IS NOT NULL
  ORDER BY e.ev_ts ASC;
END;
$$;
CREATE FUNCTION public.idempotency_claim(_key uuid, _fn text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted boolean;
  v_existing jsonb;
  v_fn_existente text;
  v_org uuid;
  v_user uuid;
BEGIN
  IF _key IS NULL THEN RETURN NULL; END IF;
  v_org := COALESCE(current_user_org_id(), '00000000-0000-0000-0000-000000000000'::uuid);
  v_user := COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
  INSERT INTO public.idempotency_keys(key, organization_id, user_id, fn, hits)
  VALUES (_key, v_org, v_user, _fn, 0)
  ON CONFLICT (key, organization_id, user_id) DO UPDATE
    SET hits = public.idempotency_keys.hits + 1
  RETURNING (xmax = 0), response, fn INTO v_inserted, v_existing, v_fn_existente;
  IF v_inserted THEN RETURN NULL; END IF;
  IF v_fn_existente IS DISTINCT FROM _fn THEN
    RAISE EXCEPTION 'LC_IDEMPOTENCIA_FN_DISTINTA: el identificador de la operación ya se usó en otra operación (%). Reintenta generando uno nuevo.', v_fn_existente
      USING ERRCODE = '22023';
  END IF;
  RETURN COALESCE(v_existing, jsonb_build_object('__idempotency_pending', true));
END;
$$;
CREATE FUNCTION public.idempotency_store(_key uuid, _response jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_user uuid;
BEGIN
  IF _key IS NULL THEN RETURN; END IF;
  v_org := COALESCE(current_user_org_id(), '00000000-0000-0000-0000-000000000000'::uuid);
  v_user := COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
  UPDATE public.idempotency_keys
     SET response = _response
   WHERE key = _key
     AND organization_id = v_org
     AND user_id = v_user;
END;
$$;
CREATE FUNCTION public.is_demo_user(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
