CREATE FUNCTION public.is_soft_delete_table(_table text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT _table = ANY(ARRAY[
    -- Existentes
    'clientes','contactos_cliente','embarques','documentos_embarque',
    'eventos_embarque','notas_embarque','cotizaciones','cotizacion_costos',
    'facturas','conceptos_factura','proformas','proforma_conceptos_consolidados',
    'conceptos_costo','conceptos_venta',
    -- CRM
    'crm_leads','crm_oportunidades','crm_actividades','crm_comentarios_oportunidad',
    'crm_etapas_pipeline','crm_motivos_perdida','crm_plantillas_mensaje',
    -- Finanzas
    'pagos_factura','pagos_proveedor','proveedor_facturas',
    'proveedor_notas_credito','factura_notas_credito','cuentas_bancarias',
    -- Operaciones
    'seguros_embarque','embarque_contenedores'
  ])
$$;
CREATE FUNCTION public.liberar_claim_facturapi_huerfano(p_factura_id uuid, p_min_edad_minutos integer DEFAULT 5) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_liberado boolean := false;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.facturas
  WHERE id = p_factura_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'factura no encontrada' USING ERRCODE = 'P0002';
  END IF;
  -- Autorización: sólo miembros de la organización pueden liberar claims.
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = auth.uid() AND organization_id = v_org
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  UPDATE public.facturas
  SET facturapi_id = NULL,
      facturapi_claim_at = NULL
  WHERE id = p_factura_id
    AND facturapi_id LIKE 'PENDING:%'
    AND facturapi_claim_at IS NOT NULL
    AND facturapi_claim_at < now() - make_interval(mins => GREATEST(p_min_edad_minutos, 1));
  GET DIAGNOSTICS v_liberado = ROW_COUNT;
  RETURN v_liberado;
END;
$$;
CREATE FUNCTION public.liberar_claim_rep_huerfano(p_pago_id uuid, p_min_edad_minutos integer DEFAULT 5) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_filas int := 0;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.pagos_factura
  WHERE id = p_pago_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'pago no encontrado' USING ERRCODE = 'P0002';
  END IF;
  -- Autorización: sólo miembros de la organización pueden liberar claims.
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = auth.uid() AND organization_id = v_org
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  UPDATE public.pagos_factura
  SET facturapi_rep_id = NULL,
      facturapi_rep_claim_at = NULL
  WHERE id = p_pago_id
    AND facturapi_rep_id LIKE 'PENDING:%'
    AND facturapi_rep_claim_at IS NOT NULL
    AND facturapi_rep_claim_at < now() - make_interval(mins => GREATEST(p_min_edad_minutos, 1));
  GET DIAGNOSTICS v_filas = ROW_COUNT;
  RETURN v_filas > 0;
END;
$$;
CREATE FUNCTION public.liberar_conceptos_de_proforma(p_proforma_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_embarque_id uuid;
  v_liberados   integer := 0;
BEGIN
  SELECT embarque_id INTO v_embarque_id FROM public.proformas WHERE id = p_proforma_id;
  IF v_embarque_id IS NULL THEN
    RETURN 0;
  END IF;
  WITH upd AS (
    UPDATE public.conceptos_venta
       SET proforma_id = NULL,
           estado_facturacion = 'pendiente'
     WHERE proforma_id = p_proforma_id
    RETURNING id
  )
  SELECT COUNT(*) INTO v_liberados FROM upd;
  -- Recalcula tiene_proforma: true solo si queda otra proforma viva en el embarque.
  UPDATE public.embarques e
     SET tiene_proforma = EXISTS (
       SELECT 1 FROM public.proformas p
        WHERE p.embarque_id = e.id
          AND p.id <> p_proforma_id
          AND COALESCE(p.estado_cliente, 'pendiente') <> 'rechazada'
     )
   WHERE e.id = v_embarque_id;
  RETURN v_liberados;
END;
$$;
CREATE FUNCTION public.libro_pagos(p_desde date, p_hasta date, p_org uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org       uuid;
  v_super     boolean;
  v_pagos     jsonb := '[]'::jsonb;
BEGIN
  IF p_desde IS NULL OR p_hasta IS NULL THEN
    RAISE EXCEPTION 'LC_LIBRO_PAGOS_PARAMS: el periodo es obligatorio';
  END IF;
  IF p_hasta < p_desde THEN
    RAISE EXCEPTION 'LC_LIBRO_PAGOS_RANGO: la fecha final no puede ser anterior a la inicial';
  END IF;
  v_org := current_user_org_id();
  v_super := has_role(auth.uid(), 'super_admin');
  IF v_super THEN
    IF p_org IS NULL THEN
      RAISE EXCEPTION 'LC_ORG_REQUERIDA: selecciona una organización para ver el libro de pagos' USING ERRCODE='42501';
    END IF;
    v_org := p_org;
    v_super := false;
  ELSIF p_org IS NOT NULL AND p_org IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'LC_ORG_AJENA: no puedes consultar el libro de pagos de otra organización' USING ERRCODE='42501';
  END IF;
  IF v_org IS NULL AND NOT v_super THEN
    RAISE EXCEPTION 'LC_LIBRO_PAGOS_SIN_ORG: no se pudo determinar tu organización';
  END IF;
  WITH cobros AS (
    SELECT
      pf.id,
      'cobro'::text                             AS tipo,
      pf.fecha_pago                             AS fecha,
      c.nombre                                  AS contraparte,
      f.cliente_id                              AS contraparte_id,
      f.id                                      AS documento_id,
      NULLIF(TRIM(COALESCE(f.serie, '') || COALESCE(f.numero::text, '')), '') AS documento_folio,
      pf.moneda::text                           AS moneda,
      COALESCE(pf.monto, 0)                     AS monto,
      COALESCE(pf.tipo_cambio, 1)               AS tipo_cambio,
      CASE WHEN pf.moneda::text = 'MXN'
           THEN COALESCE(pf.monto, 0)
           ELSE COALESCE(pf.monto, 0) * COALESCE(pf.tipo_cambio, 1) END AS monto_mxn,
      pf.forma_pago                             AS metodo_pago,
      pf.referencia,
      pf.cuenta_bancaria_id,
      pf.notas,
      pf.embarque_id,
      COALESCE(pf.diferencia_cambiaria_mxn, 0)  AS diferencia_cambiaria_mxn,
      pf.estado_rep,
      NULLIF(TRIM(COALESCE(pf.serie_rep, '') || COALESCE(pf.folio_rep::text, '')), '') AS folio_rep,
      false                                     AS es_ajuste,
      false                                     AS es_anticipo_aplicado,
      NULL::uuid                                AS lote_id,
      pf.created_by,
      pf.created_at
    FROM public.pagos_factura pf
    JOIN public.facturas f ON f.id = pf.factura_id AND f.deleted_at IS NULL
    LEFT JOIN public.clientes c ON c.id = f.cliente_id
    WHERE pf.deleted_at IS NULL
      AND pf.fecha_pago BETWEEN p_desde AND p_hasta
      AND (v_super OR pf.organization_id = v_org)
  ),
  pagos AS (
    SELECT
      pp.id,
      'pago'::text                              AS tipo,
      pp.fecha_pago                             AS fecha,
      pr.nombre                                 AS contraparte,
      pfa.proveedor_id                          AS contraparte_id,
      pfa.id                                    AS documento_id,
      COALESCE(pfa.folio_interno, pfa.folio_proveedor) AS documento_folio,
      pp.moneda::text                           AS moneda,
      COALESCE(pp.monto, 0)                     AS monto,
      COALESCE(pp.tipo_cambio_usd, 1)           AS tipo_cambio,
      CASE WHEN pp.moneda::text = 'MXN'
           THEN COALESCE(pp.monto, 0)
           ELSE COALESCE(pp.monto, 0) * COALESCE(pp.tipo_cambio_usd, 1) END AS monto_mxn,
      pp.metodo_pago,
      pp.referencia,
      pp.cuenta_bancaria_id,
      pp.notas,
      pfa.embarque_id,
      COALESCE(pp.diferencia_cambiaria_mxn, 0)  AS diferencia_cambiaria_mxn,
      NULL::text                                AS estado_rep,
      NULL::text                                AS folio_rep,
      COALESCE(pp.es_ajuste, false)             AS es_ajuste,
      COALESCE(pp.es_anticipo_aplicado, false)  AS es_anticipo_aplicado,
      pp.lote_id,
      pp.created_by,
      pp.created_at
    FROM public.pagos_proveedor pp
    JOIN public.proveedor_facturas pfa ON pfa.id = pp.proveedor_factura_id AND pfa.deleted_at IS NULL
    LEFT JOIN public.proveedores pr ON pr.id = pfa.proveedor_id
    WHERE pp.deleted_at IS NULL
      AND pp.fecha_pago BETWEEN p_desde AND p_hasta
      AND (v_super OR pp.organization_id = v_org)
  ),
  anticipos AS (
    SELECT
      ap.id,
      'anticipo'::text                          AS tipo,
      ap.fecha_anticipo                         AS fecha,
      pr.nombre                                 AS contraparte,
      ap.proveedor_id                           AS contraparte_id,
      NULL::uuid                                AS documento_id,
      NULL::text                                AS documento_folio,
      ap.moneda::text                           AS moneda,
      COALESCE(ap.monto, 0)                     AS monto,
      COALESCE(ap.tipo_cambio_usd, 1)           AS tipo_cambio,
      CASE WHEN ap.moneda::text = 'MXN'
           THEN COALESCE(ap.monto, 0)
           ELSE COALESCE(ap.monto, 0) * COALESCE(ap.tipo_cambio_usd, 1) END AS monto_mxn,
      ap.metodo_pago,
      ap.referencia,
      ap.cuenta_bancaria_id,
      ap.notas,
      ap.embarque_id,
      0::numeric                                AS diferencia_cambiaria_mxn,
      NULL::text                                AS estado_rep,
      NULL::text                                AS folio_rep,
      false                                     AS es_ajuste,
      false                                     AS es_anticipo_aplicado,
      NULL::uuid                                AS lote_id,
      ap.created_by,
      ap.created_at
    FROM public.anticipos_proveedor ap
    LEFT JOIN public.proveedores pr ON pr.id = ap.proveedor_id
    WHERE ap.deleted_at IS NULL
      AND COALESCE(ap.estado, 'Vigente') <> 'Cancelado'
      AND ap.fecha_anticipo BETWEEN p_desde AND p_hasta
      AND (v_super OR ap.organization_id = v_org)
  ),
  unidos AS (
    SELECT * FROM cobros
    UNION ALL SELECT * FROM pagos
    UNION ALL SELECT * FROM anticipos
  ),
  enriquecidos AS (
    SELECT
      u.*,
      cb.alias                                  AS cuenta_alias,
      cb.banco                                  AS cuenta_banco,
      mov.id                                    AS movimiento_id,
      (mov.id IS NOT NULL)                      AS conciliado
    FROM unidos u
    LEFT JOIN public.cuentas_bancarias cb ON cb.id = u.cuenta_bancaria_id AND cb.deleted_at IS NULL
    LEFT JOIN LATERAL (
      SELECT m.id
      FROM public.bbva_movimientos m
      WHERE m.deleted_at IS NULL
        AND m.estado_conciliacion = 'Conciliado'::estado_conciliacion
        AND (
          (u.tipo = 'cobro'    AND m.pago_factura_id = u.id)
          OR (u.tipo = 'pago'  AND (m.pago_proveedor_id = u.id
                                    OR (u.lote_id IS NOT NULL AND m.pago_proveedor_lote_id = u.lote_id)))
          OR (u.tipo = 'anticipo' AND m.anticipo_proveedor_id = u.id)
        )
      LIMIT 1
    ) mov ON true
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY e.fecha DESC, e.created_at DESC), '[]'::jsonb)
    INTO v_pagos
  FROM enriquecidos e;
  RETURN jsonb_build_object(
    'desde', p_desde,
    'hasta', p_hasta,
    'pagos', v_pagos
  );
END;
$$;
CREATE FUNCTION public.limpiar_cancellation_status_verificado(p_factura_id uuid, p_remote_cancellation_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_factura record;
  v_email text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(NULLIF(TRIM(p_remote_cancellation_status), ''), '') <> '' THEN
    RAISE EXCEPTION 'facturapi_reporta_cancelacion_activa' USING ERRCODE = '22023';
  END IF;
  SELECT id, organization_id, cancellation_status, cancelado_en, acuse_cancelacion_status, numero
    INTO v_factura
    FROM public.facturas
   WHERE id = p_factura_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'factura_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (
    public.has_role(v_user, 'admin'::public.app_role)
    OR public.has_role(v_user, 'admin_org'::public.app_role)
    OR public.has_role(v_user, 'super_admin'::public.app_role)
    OR public.has_role(v_user, 'contador'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden_role' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_org_member(v_factura.organization_id) THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: la factura pertenece a otra organización'
      USING ERRCODE = '42501';
  END IF;
  IF v_factura.cancelado_en IS NOT NULL OR v_factura.acuse_cancelacion_status IS NOT NULL THEN
    RAISE EXCEPTION 'factura_ya_cancelada' USING ERRCODE = '22023';
  END IF;
  IF v_factura.cancellation_status NOT IN ('pending', 'verifying') THEN
    RAISE EXCEPTION 'factura_no_esta_pendiente' USING ERRCODE = '22023';
  END IF;
  UPDATE public.facturas
     SET cancellation_status = NULL,
         cancelacion_solicitada_en = NULL,
         cancelacion_vence_en = NULL
   WHERE id = p_factura_id;
  SELECT email INTO v_email FROM auth.users WHERE id = v_user;
  INSERT INTO public.bitacora_actividad
    (organization_id, usuario_id, usuario_email, modulo, accion, entidad_id, detalles)
  VALUES (
    v_factura.organization_id,
    v_user,
    v_email,
    'facturacion',
    'facturapi_pending_limpiada_manual',
    v_factura.id,
    jsonb_build_object(
      'numero', v_factura.numero,
      'cancellation_status_previo', v_factura.cancellation_status,
      'verificado_via', 'facturapi-consultar (GET /invoices/{id})'
    )
  );
  RETURN jsonb_build_object('ok', true, 'factura_id', p_factura_id);
END;
$$;
CREATE FUNCTION public.list_idempotency_log(_limit integer DEFAULT 100, _offset integer DEFAULT 0) RETURNS TABLE(key uuid, fn text, hits integer, created_at timestamp with time zone, user_id uuid, user_email text, has_response boolean, pending boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scope uuid := public.org_scope();
BEGIN
  IF NOT (
    public.has_role(auth.uid(), 'admin'::app_role)
    OR public.has_role(auth.uid(), 'super_admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'Forbidden: requires admin role';
  END IF;
  IF v_scope IS NULL THEN
    RETURN;
  END IF;
  RETURN QUERY
  SELECT
    ik.key,
    ik.fn,
    ik.hits,
    ik.created_at,
    ik.user_id,
    u.email::text AS user_email,
    (ik.response IS NOT NULL AND NOT COALESCE((ik.response ? '__idempotency_pending'), false)) AS has_response,
    COALESCE((ik.response ? '__idempotency_pending'), ik.response IS NULL) AS pending
  FROM public.idempotency_keys ik
  LEFT JOIN auth.users u ON u.id = ik.user_id
  WHERE ik.organization_id = v_scope
  ORDER BY ik.created_at DESC
  LIMIT GREATEST(_limit, 1)
  OFFSET GREATEST(_offset, 0);
END;
$$;
CREATE FUNCTION public.list_trash(_table text, _limit integer DEFAULT 50, _offset integer DEFAULT 0) RETURNS TABLE(id uuid, organization_id uuid, deleted_at timestamp with time zone, deleted_by uuid, deleted_by_email text, label text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  _uid uuid := auth.uid();
  _scope uuid;
  _label_col text;
BEGIN
  IF NOT public.is_soft_delete_table(_table) THEN
    RAISE EXCEPTION 'Tabla no permitida: %', _table;
  END IF;
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  IF NOT (
    public.has_role(_uid, 'super_admin'::app_role)
    OR public.has_role(_uid, 'admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sólo admin / super_admin';
  END IF;
  _scope := public.org_scope();
  IF _scope IS NULL THEN
    RETURN;  -- super admin sin tenant activo: nunca mezclar organizaciones
  END IF;
  _label_col := CASE _table
    WHEN 'clientes' THEN 'nombre'
    WHEN 'contactos_cliente' THEN 'nombre'
    WHEN 'embarques' THEN 'expediente'
    WHEN 'documentos_embarque' THEN 'nombre'
    WHEN 'eventos_embarque' THEN 'descripcion'
    WHEN 'notas_embarque' THEN 'contenido'
    WHEN 'cotizaciones' THEN 'folio'
    WHEN 'cotizacion_costos' THEN 'concepto'
    WHEN 'facturas' THEN 'numero'
    WHEN 'conceptos_factura' THEN 'descripcion'
    WHEN 'proformas' THEN 'numero'
    WHEN 'proforma_conceptos_consolidados' THEN 'descripcion'
    WHEN 'conceptos_costo' THEN 'concepto'
    WHEN 'conceptos_venta' THEN 'descripcion'
    WHEN 'crm_leads' THEN 'empresa'
    WHEN 'crm_oportunidades' THEN 'nombre'
    WHEN 'crm_actividades' THEN 'asunto'
    WHEN 'crm_comentarios_oportunidad' THEN 'texto'
    WHEN 'crm_etapas_pipeline' THEN 'nombre'
    WHEN 'crm_motivos_perdida' THEN 'nombre'
    WHEN 'crm_plantillas_mensaje' THEN 'nombre'
    WHEN 'pagos_factura' THEN 'referencia'
    WHEN 'pagos_proveedor' THEN 'referencia'
    WHEN 'proveedor_facturas' THEN 'folio_interno'
    WHEN 'proveedor_notas_credito' THEN 'descripcion'
    WHEN 'factura_notas_credito' THEN 'folio'
    WHEN 'cuentas_bancarias' THEN 'alias'
    WHEN 'seguros_embarque' THEN 'poliza'
    WHEN 'embarque_contenedores' THEN 'numero_contenedor'
    ELSE 'id'
  END;
  RETURN QUERY EXECUTE format(
    'SELECT t.id, t.organization_id, t.deleted_at, t.deleted_by,
            (SELECT u.email::text FROM auth.users u WHERE u.id = t.deleted_by) AS deleted_by_email,
            COALESCE(NULLIF(t.%I::text, %L), %L) AS label
     FROM public.%I t
     WHERE t.deleted_at IS NOT NULL
       AND t.organization_id = $1
     ORDER BY t.deleted_at DESC
     LIMIT $2 OFFSET $3',
    _label_col, '', '(sin etiqueta)', _table
  ) USING _scope, _limit, _offset;
END $_$;
CREATE FUNCTION public.list_trash_counts() RETURNS TABLE(tabla text, total bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  _uid uuid := auth.uid();
  _scope uuid;
  _t text;
  _n bigint;
  _sql text;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  IF NOT (
    public.has_role(_uid, 'super_admin'::app_role)
    OR public.has_role(_uid, 'admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sólo admin / super_admin';
  END IF;
  _scope := public.org_scope();
  IF _scope IS NULL THEN
    RETURN;
  END IF;
  FOR _t IN
    SELECT unnest(ARRAY[
      'clientes','contactos_cliente','embarques','documentos_embarque',
      'eventos_embarque','notas_embarque','cotizaciones','cotizacion_costos',
      'facturas','conceptos_factura','proformas','proforma_conceptos_consolidados',
      'conceptos_costo','conceptos_venta',
      'crm_leads','crm_oportunidades','crm_actividades','crm_comentarios_oportunidad',
      'crm_etapas_pipeline','crm_motivos_perdida','crm_plantillas_mensaje',
      'pagos_factura','pagos_proveedor','proveedor_facturas',
      'proveedor_notas_credito','factura_notas_credito','cuentas_bancarias',
      'seguros_embarque','embarque_contenedores'
    ])
  LOOP
    _sql := format(
      'SELECT count(*)::bigint FROM public.%I WHERE deleted_at IS NOT NULL AND organization_id = $1',
      _t
    );
    EXECUTE _sql INTO _n USING _scope;
    tabla := _t;
    total := _n;
    RETURN NEXT;
  END LOOP;
END;
$_$;
CREATE FUNCTION public.log_client_error_v1(p_message text, p_stack text DEFAULT NULL::text, p_component_stack text DEFAULT NULL::text, p_route text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_user uuid := auth.uid();
  v_rl jsonb;
BEGIN
  v_rl := public.check_ratelimit(
    'rpc:log_client_error_v1:'
      || COALESCE(NULLIF(current_setting('request.headers', true)::jsonb->>'x-forwarded-for', ''), 'sin-ip')
      || ':' || COALESCE(v_user::text, 'anon'),
    60, 20
  );
  IF (v_rl->>'ok') = 'false' THEN
    RAISE EXCEPTION 'Demasiadas solicitudes. Intenta de nuevo en % segundos.', COALESCE(v_rl->>'retry_after', '60')
      USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO public.app_logs(level, fn, msg, request_id, user_id, status_code, latency_ms, payload)
  VALUES (
    'error', 'client',
    LEFT(COALESCE(p_message, '(sin mensaje)'), 1000),
    COALESCE(p_request_id, gen_random_uuid()),
    v_user,
    500, NULL,
    jsonb_build_object(
      'stack', LEFT(COALESCE(p_stack, ''), 8000),
      'component_stack', LEFT(COALESCE(p_component_stack, ''), 4000),
      'route', LEFT(COALESCE(p_route, ''), 500),
      'user_agent', LEFT(COALESCE(p_user_agent, ''), 500),
      'app_version', LEFT(COALESCE(p_app_version, ''), 50)
    )
  )
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;
CREATE FUNCTION public.marcar_facturas_vencidas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count     integer := 0;
  v_hoy_mx    date := (now() AT TIME ZONE 'America/Mexico_City')::date;
  v_prev_flag text;
BEGIN
  -- Bypass del guard `guard_estado_factura`: 'Vencida' es un estado
  -- calculado y sólo el recálculo automático puede fijarlo.
  v_prev_flag := current_setting('app.recalc_estado_factura', true);
  PERFORM set_config('app.recalc_estado_factura', '1', true);
  UPDATE public.facturas
     SET estado = 'Vencida'::estado_factura,
         updated_at = now()
   WHERE estado = 'Emitida'::estado_factura
     AND fecha_vencimiento IS NOT NULL
     AND fecha_vencimiento < v_hoy_mx
     AND deleted_at IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  PERFORM set_config('app.recalc_estado_factura', COALESCE(v_prev_flag, ''), true);
  INSERT INTO public.app_logs (level, fn, msg, payload)
  VALUES (
    'info',
    'marcar_facturas_vencidas',
    format('%s factura(s) marcada(s) como Vencida', v_count),
    jsonb_build_object('marcadas', v_count, 'fecha_negocio_mx', v_hoy_mx)
  );
  RETURN v_count;
END;
$$;
CREATE FUNCTION public.marcar_proforma_facturada(p_id uuid, p_folio text, p_fecha date, p_request_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cached jsonb;
  v_org_id uuid;
BEGIN
  v_cached := public.idempotency_claim(p_request_id, 'marcar_proforma_facturada');
  IF v_cached IS NOT NULL THEN RETURN; END IF;
  SELECT organization_id INTO v_org_id FROM public.proformas WHERE id = p_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Proforma no encontrada'; END IF;
  PERFORM public._assert_writer(v_org_id);
  UPDATE public.proformas
     SET estado_proforma = 'facturada',
         folio_factura_externa = p_folio,
         fecha_facturacion = p_fecha,
         updated_at = now()
   WHERE id = p_id;
  PERFORM public.idempotency_store(p_request_id, jsonb_build_object('ok', true));
END;
$$;
CREATE FUNCTION public.materializar_factura_retencion_garantia(p_garantia_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_garantia record;
  v_uid uuid := auth.uid();
  v_ok boolean := false;
  v_naviera_nombre text;
  v_proveedor_id uuid;
  v_proveedor_nombre text;
  v_categoria_id uuid;
  v_folio text;
  v_factura_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'LC_GARANTIA_SIN_ROL';
  END IF;
  IF public.has_role(v_uid, 'admin')
     OR public.has_role(v_uid, 'admin_org')
     OR public.has_role(v_uid, 'operador')
     OR public.has_role(v_uid, 'super_admin') THEN
    v_ok := true;
  END IF;
  IF NOT v_ok THEN
    RAISE EXCEPTION 'LC_GARANTIA_SIN_ROL';
  END IF;
  SELECT * INTO v_garantia
  FROM public.embarque_garantias_contenedor
  WHERE id = p_garantia_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_GARANTIA_NO_ENCONTRADA';
  END IF;
  IF v_garantia.estado <> 'retenido' THEN
    RAISE EXCEPTION 'LC_GARANTIA_NO_RETENIDA';
  END IF;
  IF v_garantia.proveedor_factura_id IS NOT NULL THEN
    RAISE EXCEPTION 'LC_GARANTIA_FACTURA_YA_MATERIALIZADA';
  END IF;
  IF v_garantia.naviera_id IS NULL THEN
    RAISE EXCEPTION 'LC_GARANTIA_SIN_NAVIERA';
  END IF;
  SELECT name INTO v_naviera_nombre FROM public.navieras WHERE id = v_garantia.naviera_id;
  SELECT id, nombre INTO v_proveedor_id, v_proveedor_nombre
  FROM public.proveedores
  WHERE organization_id = v_garantia.organization_id
    AND lower(nombre) = lower(v_naviera_nombre)
  LIMIT 1;
  IF v_proveedor_id IS NULL THEN
    RAISE EXCEPTION 'LC_GARANTIA_SIN_PROVEEDOR_NAVIERA';
  END IF;
  SELECT id INTO v_categoria_id
  FROM public.presupuesto_categorias
  WHERE organization_id = v_garantia.organization_id
    AND (lower(nombre) LIKE 'costo%' OR lower(nombre) LIKE '%cogs%')
  ORDER BY created_at ASC
  LIMIT 1;
  IF v_categoria_id IS NULL THEN
    SELECT id INTO v_categoria_id
    FROM public.presupuesto_categorias
    WHERE organization_id = v_garantia.organization_id
    ORDER BY created_at ASC
    LIMIT 1;
  END IF;
  IF v_categoria_id IS NULL THEN
    RAISE EXCEPTION 'LC_GARANTIA_SIN_CATEGORIA_PRESUPUESTO';
  END IF;
  v_folio := public.siguiente_folio_proveedor(v_garantia.organization_id);
  INSERT INTO public.proveedor_facturas (
    organization_id, proveedor_id, proveedor_nombre, embarque_id,
    folio_proveedor, fecha_emision, dias_credito,
    moneda, tipo_cambio_usd,
    subtotal, iva, retenciones, total,
    estado, notas, categoria_presupuesto_id, folio_interno, created_by
  ) VALUES (
    v_garantia.organization_id, v_proveedor_id, v_proveedor_nombre, v_garantia.embarque_id,
    'RET-GAR-' || substr(v_garantia.id::text, 1, 8),
    CURRENT_DATE, 0,
    'USD', 1,
    v_garantia.monto_deposito_usd, 0, 0, v_garantia.monto_deposito_usd,
    'Borrador',
    'Retención automática de garantía #' || v_garantia.id::text,
    v_categoria_id, v_folio, v_uid
  ) RETURNING id INTO v_factura_id;
  UPDATE public.embarque_garantias_contenedor
     SET proveedor_factura_id = v_factura_id,
         updated_at = now()
   WHERE id = v_garantia.id;
  RETURN v_factura_id;
END;
$$;
CREATE FUNCTION public.migrar_roles_legacy_dry_run() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_om jsonb;
  v_ur jsonb;
  v_total int;
BEGIN
  IF NOT public.has_role(auth.uid(), 'super_admin'::public.app_role) THEN
    RAISE EXCEPTION 'Solo super_admin puede ejecutar esta operación'
      USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(jsonb_agg(x), '[]'::jsonb) INTO v_om FROM (
    SELECT om.id,
           om.user_id,
           om.organization_id,
           om.role::text AS rol_actual,
           CASE om.role::text
             WHEN 'admin'    THEN 'admin_org'
             WHEN 'operador' THEN 'coordinador_logistico'
             WHEN 'viewer'   THEN 'customer_service'
           END AS rol_propuesto,
           o.nombre AS organizacion
    FROM public.organization_members om
    LEFT JOIN public.organizations o ON o.id = om.organization_id
    WHERE om.role::text IN ('admin','operador','viewer')
    ORDER BY om.created_at
  ) x;
  SELECT COALESCE(jsonb_agg(x), '[]'::jsonb) INTO v_ur FROM (
    SELECT ur.id,
           ur.user_id,
           ur.role::text AS rol_actual,
           CASE ur.role::text
             WHEN 'admin'    THEN 'admin_org'
             WHEN 'operador' THEN 'coordinador_logistico'
             WHEN 'viewer'   THEN 'customer_service'
           END AS rol_propuesto
    FROM public.user_roles ur
    WHERE ur.role::text IN ('admin','operador','viewer')
  ) x;
  v_total := jsonb_array_length(v_om) + jsonb_array_length(v_ur);
  RETURN jsonb_build_object(
    'total_afectados', v_total,
    'organization_members', v_om,
    'user_roles', v_ur,
    'mapa', jsonb_build_object(
      'admin', 'admin_org',
      'operador', 'coordinador_logistico',
      'viewer', 'customer_service'
    )
  );
END;
$$;
CREATE FUNCTION public.migrar_roles_legacy_ejecutar() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_om_admin int := 0;
  v_om_operador int := 0;
  v_om_viewer int := 0;
  v_ur_admin int := 0;
  v_ur_operador int := 0;
  v_ur_viewer int := 0;
  v_total int;
BEGIN
  IF NOT public.has_role(auth.uid(), 'super_admin'::public.app_role) THEN
    RAISE EXCEPTION 'Solo super_admin puede ejecutar esta operación'
      USING ERRCODE = '42501';
  END IF;
  -- organization_members
  WITH upd AS (
    UPDATE public.organization_members
       SET role = 'admin_org'::public.app_role
     WHERE role::text = 'admin'
     RETURNING 1
  ) SELECT COUNT(*) INTO v_om_admin FROM upd;
  WITH upd AS (
    UPDATE public.organization_members
       SET role = 'coordinador_logistico'::public.app_role
     WHERE role::text = 'operador'
     RETURNING 1
  ) SELECT COUNT(*) INTO v_om_operador FROM upd;
  WITH upd AS (
    UPDATE public.organization_members
       SET role = 'customer_service'::public.app_role
     WHERE role::text = 'viewer'
     RETURNING 1
  ) SELECT COUNT(*) INTO v_om_viewer FROM upd;
  -- user_roles
  WITH upd AS (
    UPDATE public.user_roles
       SET role = 'admin_org'::public.app_role
     WHERE role::text = 'admin'
     RETURNING 1
  ) SELECT COUNT(*) INTO v_ur_admin FROM upd;
  WITH upd AS (
    UPDATE public.user_roles
       SET role = 'coordinador_logistico'::public.app_role
     WHERE role::text = 'operador'
     RETURNING 1
  ) SELECT COUNT(*) INTO v_ur_operador FROM upd;
  WITH upd AS (
    UPDATE public.user_roles
       SET role = 'customer_service'::public.app_role
     WHERE role::text = 'viewer'
     RETURNING 1
  ) SELECT COUNT(*) INTO v_ur_viewer FROM upd;
  v_total := v_om_admin + v_om_operador + v_om_viewer
           + v_ur_admin + v_ur_operador + v_ur_viewer;
  -- Bitácora (best-effort; si la tabla no existe o falla, no rompemos la migración)
  BEGIN
    INSERT INTO public.bitacora_actividad (
      user_id, accion, entidad, entidad_id, detalles
    ) VALUES (
      auth.uid(),
      'migrar_roles_legacy',
      'roles',
      NULL,
      jsonb_build_object(
        'organization_members', jsonb_build_object(
          'admin_a_admin_org', v_om_admin,
          'operador_a_coordinador_logistico', v_om_operador,
          'viewer_a_customer_service', v_om_viewer
        ),
        'user_roles', jsonb_build_object(
          'admin_a_admin_org', v_ur_admin,
          'operador_a_coordinador_logistico', v_ur_operador,
          'viewer_a_customer_service', v_ur_viewer
        ),
        'total', v_total
      )
    );
  EXCEPTION WHEN OTHERS THEN
    -- No bloqueamos la migración por un fallo de bitácora.
    NULL;
  END;
  RETURN jsonb_build_object(
    'ejecutado_at', now(),
    'total_migrados', v_total,
    'organization_members', jsonb_build_object(
      'admin_a_admin_org', v_om_admin,
      'operador_a_coordinador_logistico', v_om_operador,
      'viewer_a_customer_service', v_om_viewer
    ),
    'user_roles', jsonb_build_object(
      'admin_a_admin_org', v_ur_admin,
      'operador_a_coordinador_logistico', v_ur_operador,
      'viewer_a_customer_service', v_ur_viewer
    )
  );
END;
$$;
CREATE FUNCTION public.nc_aplicadas_en_moneda_factura(p_factura_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_moneda text;
  v_tc numeric;
  v_ncs numeric;
BEGIN
  SELECT f.moneda::text, f.tipo_cambio INTO v_moneda, v_tc
  FROM public.facturas f WHERE f.id = p_factura_id;
  IF v_moneda IS NULL THEN RETURN 0; END IF;
  SELECT COALESCE(SUM(
      CASE
        WHEN nc.moneda::text = v_moneda THEN nc.monto
        WHEN v_moneda = 'MXN' AND nc.moneda::text <> 'MXN' AND nc.tipo_cambio > 1
          THEN nc.monto * nc.tipo_cambio
        WHEN v_moneda <> 'MXN' AND nc.moneda::text = 'MXN' AND v_tc > 1
          THEN nc.monto / v_tc
        WHEN v_moneda <> 'MXN' AND nc.moneda::text <> 'MXN'
             AND v_moneda <> nc.moneda::text
             AND nc.tipo_cambio > 1 AND v_tc > 1
          THEN (nc.monto * nc.tipo_cambio) / v_tc
        ELSE 0
      END), 0) INTO v_ncs
  FROM public.factura_notas_credito nc
  WHERE nc.factura_id = p_factura_id
    AND nc.deleted_at IS NULL
    AND nc.estado = 'Aplicada';
  RETURN COALESCE(v_ncs, 0);
END;
$$;
CREATE FUNCTION public.notif_cli_on_embarque_estado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.estado IS DISTINCT FROM OLD.estado AND NEW.cliente_id IS NOT NULL THEN
    INSERT INTO public.notificaciones_cliente (organization_id, cliente_id, embarque_id, tipo, titulo, mensaje, url)
    VALUES (
      NEW.organization_id,
      NEW.cliente_id,
      NEW.id,
      'embarque_estado',
      'Tu embarque ' || COALESCE(NEW.expediente, '') || ' está ahora en estado: ' || NEW.estado,
      'El estado de tu embarque cambió de "' || COALESCE(OLD.estado::text, '') || '" a "' || NEW.estado::text || '".',
      '/portal/embarques/' || NEW.id::text
    );
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.notificacion_cliente_marcar_leida(p_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE public.notificaciones_cliente
  SET leida_at = now()
  WHERE id = p_id
    AND cliente_id IN (SELECT current_user_client_ids())
    AND leida_at IS NULL;
$$;
CREATE FUNCTION public.notificaciones_cliente_marcar_todas_leidas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  WITH upd AS (
    UPDATE public.notificaciones_cliente
    SET leida_at = now()
    WHERE cliente_id IN (SELECT current_user_client_ids())
      AND leida_at IS NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM upd;
  RETURN v_count;
END;
$$;
CREATE FUNCTION public.notificar_asignacion_hallazgo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_titulo  text;
  v_msg     text;
  v_changed boolean;
BEGIN
  -- ¿Cambió el responsable a alguien distinto a quien asigna?
  IF TG_OP = 'INSERT' THEN
    v_changed := NEW.responsable_id IS NOT NULL
                 AND NEW.responsable_id <> COALESCE(NEW.asignado_por, '00000000-0000-0000-0000-000000000000'::uuid);
  ELSE
    v_changed := NEW.responsable_id IS NOT NULL
                 AND NEW.responsable_id IS DISTINCT FROM OLD.responsable_id
                 AND NEW.responsable_id <> COALESCE(NEW.asignado_por, '00000000-0000-0000-0000-000000000000'::uuid);
  END IF;
  IF NOT v_changed THEN
    RETURN NEW;
  END IF;
  v_titulo := 'Nuevo hallazgo asignado';
  v_msg := format(
    'Te asignaron un hallazgo (%s) en el embarque. %s',
    NEW.regla,
    CASE WHEN NEW.fecha_limite IS NOT NULL
         THEN 'Fecha límite: ' || to_char(NEW.fecha_limite, 'DD/MM/YYYY') || '.'
         ELSE '' END
  );
  INSERT INTO public.notificaciones_internas
    (organization_id, usuario_id, tipo, titulo, mensaje, enlace, entidad_tipo, entidad_id)
  VALUES
    (NEW.organization_id, NEW.responsable_id, 'auditoria_asignacion',
     v_titulo, v_msg, '/auditoria', 'embarque', NEW.embarque_id);
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Nunca bloquear la asignación por un fallo de notificación
  RAISE WARNING 'notificar_asignacion_hallazgo falló: %', SQLERRM;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.notificar_uuid_cancelado_sat(p_org uuid, p_facturas jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item jsonb;
  v_factura_id uuid;
  v_titulo text;
  v_mensaje text;
  v_insertadas integer := 0;
  v_n integer;
BEGIN
  IF p_org IS NULL OR p_facturas IS NULL OR jsonb_typeof(p_facturas) <> 'array' THEN
    RETURN 0;
  END IF;
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_facturas)
  LOOP
    BEGIN
      v_factura_id := (v_item->>'id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      CONTINUE;
    END;
    IF v_factura_id IS NULL THEN
      CONTINUE;
    END IF;
    -- Dedupe: no repetir el mismo aviso cada semana.
    IF EXISTS (
      SELECT 1 FROM public.notificaciones_internas ni
       WHERE ni.organization_id = p_org
         AND ni.tipo = 'sat_uuid_cancelado'
         AND ni.entidad_id = v_factura_id
         AND ni.created_at > now() - interval '30 days'
    ) THEN
      CONTINUE;
    END IF;
    v_titulo := 'CFDI cancelado ante el SAT: ' ||
                COALESCE(NULLIF(v_item->>'folio_interno', ''), NULLIF(v_item->>'folio_proveedor', ''), 'factura de proveedor');
    v_mensaje := 'El SAT reporta como CANCELADO el CFDI de ' ||
                 COALESCE(NULLIF(v_item->>'proveedor_nombre', ''), 'proveedor sin nombre') ||
                 '. UUID: ' || COALESCE(v_item->>'uuid_fiscal', 'N/D') ||
                 '. Total: ' || COALESCE(v_item->>'total', 'N/D') ||
                 '. Revisa la factura antes de pagarla o deducirla.';
    INSERT INTO public.notificaciones_internas
      (organization_id, usuario_id, tipo, titulo, mensaje, enlace, entidad_tipo, entidad_id)
    SELECT p_org, om.user_id, 'sat_uuid_cancelado', v_titulo, v_mensaje,
           '/compras/facturas/' || v_factura_id::text, 'proveedor_factura', v_factura_id
      FROM public.organization_members om
     WHERE om.organization_id = p_org
       AND om.role IN ('admin'::app_role, 'admin_org'::app_role,
                       'contador'::app_role, 'auxiliar_contable'::app_role,
                       'tesorero'::app_role);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_insertadas := v_insertadas + COALESCE(v_n, 0);
  END LOOP;
  RETURN v_insertadas;
END;
$$;
CREATE FUNCTION public.obtener_costos_cotizacion_version(p_cotizacion_id uuid, p_version integer DEFAULT NULL::integer) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org UUID; v_actual INT; v_target INT;
BEGIN
  SELECT organization_id, version INTO v_org, v_actual FROM cotizaciones WHERE id = p_cotizacion_id;
  IF v_org IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM organization_members WHERE organization_id=v_org AND user_id=auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
  v_target := COALESCE(p_version, v_actual);
  IF v_target = v_actual THEN
    RETURN QUERY SELECT to_jsonb(cc) FROM cotizacion_costos cc
      WHERE cc.cotizacion_id = p_cotizacion_id AND cc.deleted_at IS NULL;
  ELSE
    RETURN QUERY SELECT to_jsonb(ch) FROM cotizacion_costos_historico ch
      WHERE ch.cotizacion_id = p_cotizacion_id AND ch.version = v_target;
  END IF;
END $$;
CREATE FUNCTION public.obtener_defaults_facturacion_cliente(p_cliente_id uuid) RETURNS TABLE(uso_cfdi text, forma_pago text, metodo_pago text, cc_emails text[], destinatarios_emails text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_cli_uso text;
  v_cli_forma text;
  v_cli_metodo text;
  v_cli_cc text[];
  v_cli_dest text[];
  v_last_uso text;
  v_last_forma text;
  v_last_metodo text;
  v_last_cc text[];
  v_last_dest text[];
BEGIN
  SELECT c.organization_id, c.uso_cfdi_default, c.forma_pago_default, c.metodo_pago_default,
         c.email_cc_default, c.email_destinatarios_default
    INTO v_org, v_cli_uso, v_cli_forma, v_cli_metodo, v_cli_cc, v_cli_dest
  FROM public.clientes c
  WHERE c.id = p_cliente_id;
  IF v_org IS NULL THEN
    RETURN;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.organization_id = v_org AND om.user_id = auth.uid()
  ) THEN
    RETURN;
  END IF;
  SELECT f.uso_cfdi, f.forma_pago, f.metodo_pago
    INTO v_last_uso, v_last_forma, v_last_metodo
  FROM public.facturas f
  WHERE f.cliente_id = p_cliente_id
    AND f.organization_id = v_org
    AND f.deleted_at IS NULL
    AND f.uuid_fiscal IS NOT NULL
  ORDER BY f.fecha_emision DESC NULLS LAST, f.created_at DESC
  LIMIT 1;
  -- FIX (Sentry JAVASCRIPT-REACT-1M / 1V): fe.cc es jsonb, no text[].
  -- Antes: SELECT fe.cc INTO v_last_cc -> 22P02 "malformed array literal".
  -- Ahora: expandimos el array JSON a text[] correctamente.
  SELECT ARRAY(
    SELECT jsonb_array_elements_text(fe.cc)
  )
    INTO v_last_cc
  FROM public.factura_envios fe
  JOIN public.facturas f ON f.id = fe.factura_id AND f.deleted_at IS NULL
  WHERE f.cliente_id = p_cliente_id
    AND fe.organization_id = v_org
    AND fe.estado = 'enviado'
    AND fe.cc IS NOT NULL
    AND jsonb_typeof(fe.cc) = 'array'
  ORDER BY fe.created_at DESC
  LIMIT 1;
  SELECT ARRAY(
    SELECT DISTINCT lower(d->>'email')
    FROM public.factura_envios fe
    JOIN public.facturas f ON f.id = fe.factura_id AND f.deleted_at IS NULL
    CROSS JOIN LATERAL jsonb_array_elements(fe.destinatarios) d
    WHERE f.cliente_id = p_cliente_id
      AND fe.organization_id = v_org
      AND fe.estado = 'enviado'
      AND fe.created_at = (
        SELECT max(fe2.created_at)
        FROM public.factura_envios fe2
        JOIN public.facturas f2 ON f2.id = fe2.factura_id AND f2.deleted_at IS NULL
        WHERE f2.cliente_id = p_cliente_id
          AND fe2.organization_id = v_org
          AND fe2.estado = 'enviado'
      )
      AND (d->>'email') IS NOT NULL
      AND lower(d->>'email') NOT IN (
        SELECT lower(cc.email) FROM public.contactos_cliente cc
        WHERE cc.cliente_id = p_cliente_id AND cc.email IS NOT NULL
      )
      AND lower(d->>'email') NOT IN (
        SELECT lower(cli.email) FROM public.clientes cli
        WHERE cli.id = p_cliente_id AND cli.email IS NOT NULL
      )
  ) INTO v_last_dest;
  uso_cfdi := COALESCE(v_cli_uso, v_last_uso);
  forma_pago := COALESCE(v_cli_forma, v_last_forma);
  metodo_pago := COALESCE(v_cli_metodo, v_last_metodo);
  cc_emails := COALESCE(v_cli_cc, NULLIF(v_last_cc, ARRAY[]::text[]));
  destinatarios_emails := COALESCE(v_cli_dest, NULLIF(v_last_dest, ARRAY[]::text[]));
  RETURN NEXT;
END;
$$;
CREATE FUNCTION public.obtener_top_tarifas(p_ruta_id uuid, p_tipo_contenedor_id uuid, p_fecha date DEFAULT CURRENT_DATE, p_limit integer DEFAULT 3) RETURNS TABLE(tarifa_id uuid, agente_nombre text, naviera_nombre text, puerto_origen_nombre text, puerto_destino_nombre text, moneda text, flete_base numeric, recargos_total numeric, total_comparable numeric, dias_credito integer, dias_libres_demoras integer, transit_time_dias integer, vigente_hasta date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT v.id, v.agente_nombre, v.naviera_nombre, v.puerto_origen_nombre, v.puerto_destino_nombre,
         v.moneda, v.flete_base, v.recargos_total, v.total_comparable,
         v.dias_credito, v.dias_libres_demoras, v.transit_time_dias, v.vigente_hasta
  FROM public.costeo_tarifas_vigentes_v v
  WHERE v.ruta_id = p_ruta_id
    AND v.tipo_contenedor_id = p_tipo_contenedor_id
    AND v.estado = 'vigente'
    AND p_fecha BETWEEN v.vigente_desde AND v.vigente_hasta
  ORDER BY v.total_comparable ASC, v.dias_credito DESC, v.dias_libres_demoras DESC, v.vigente_hasta DESC
  LIMIT p_limit;
$$;
CREATE FUNCTION public.operaciones_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  v_hoy date := current_date;
  v_dias_libres int := 7;
  v_max_contenedores int := 150;
BEGIN
  WITH base AS (
    SELECT
      e.id, e.expediente, e.cliente_nombre, e.cliente_id,
      e.modo::text AS modo, e.tipo::text AS tipo, e.estado::text AS estado,
      e.etd, e.eta, e.operador, e.fecha_llegada_real, e.created_at,
      e.puerto_origen, e.puerto_destino,
      e.aeropuerto_origen, e.aeropuerto_destino,
      e.ciudad_origen, e.ciudad_destino,
      CASE
        -- Ola 4 · N10 (guard B-033): preservar Borrador para que no se
        -- cuente como Confirmado por derivación ETD/ETA.
        WHEN e.estado = 'Borrador' THEN 'Borrador'
        WHEN e.estado IN ('Arribo','En Aduana','Entregado','EIR','Por liquidar','Cerrado') THEN e.estado::text
        WHEN e.modo = 'Marítimo' AND e.tipo = 'Importación'
             AND e.etd IS NOT NULL AND e.eta IS NOT NULL THEN
          CASE
            WHEN v_hoy < e.etd THEN 'Confirmado'
            WHEN v_hoy >= e.etd AND v_hoy < e.eta THEN 'En Tránsito'
            WHEN v_hoy >= e.eta THEN 'Arribo'
            ELSE e.estado::text
          END
        ELSE e.estado::text
      END AS estado_real
    FROM embarques e
    WHERE e.deleted_at IS NULL                -- FIX C5
      AND (e.organization_id = public.org_scope())
  ),
  profit AS (
    SELECT p.embarque_id, p.venta_usd, p.costo_usd
    FROM profit_por_embarque() p
  ),
  enriched AS (
    SELECT
      b.*,
      COALESCE(p.venta_usd, 0) AS venta_usd,
      COALESCE(p.costo_usd, 0) AS costo_usd,
      COALESCE(p.venta_usd, 0) - COALESCE(p.costo_usd, 0) AS profit,
      COALESCE(NULLIF(b.operador, ''), 'Sin Asignar') AS operador_norm,
      CASE
        WHEN b.estado_real IN ('Arribo','En Aduana') AND b.eta IS NOT NULL THEN
          CASE WHEN (v_hoy - b.eta) > v_dias_libres THEN 'critico'
               ELSE 'en_puerto' END
        WHEN b.estado_real = 'En Tránsito' AND b.eta IS NOT NULL
             AND (b.eta - v_hoy) BETWEEN 0 AND 7 THEN 'por_arribar'
        ELSE 'ok'
      END AS riesgo,
      CASE
        WHEN b.estado_real IN ('Arribo','En Aduana') AND b.eta IS NOT NULL
        THEN GREATEST(v_hoy - b.eta, 0) ELSE 0
      END AS dias_en_puerto,
      -- Ola 4 · N10 (B-033): Borrador ya no cuenta como activo operativo.
      CASE
        WHEN b.estado_real NOT IN ('Borrador','EIR','Por liquidar','Cerrado','Cancelado') THEN true ELSE false
      END AS es_activo,
      -- Mapeo a llaves de UI
      CASE
        WHEN b.estado_real = 'Confirmado' THEN 'Confirmado'
        WHEN b.estado_real = 'En Tránsito' THEN 'En Tránsito'
        WHEN b.estado_real = 'Arribo' THEN 'Llegada'
        WHEN b.estado_real IN ('En Aduana','Entregado') THEN 'En Proceso'
        WHEN b.estado_real IN ('EIR','Por liquidar','Cerrado') THEN 'Cerrado'
        ELSE NULL
      END AS estado_ui,
      -- origen/destino con prioridad Port > Airport > City
      COALESCE(NULLIF(b.puerto_origen, ''), NULLIF(b.aeropuerto_origen, ''), NULLIF(b.ciudad_origen, ''), '') AS origen_txt,
      COALESCE(NULLIF(b.puerto_destino, ''), NULLIF(b.aeropuerto_destino, ''), NULLIF(b.ciudad_destino, ''), '') AS destino_txt
    FROM base b
    LEFT JOIN profit p ON p.embarque_id = b.id
  ),
  meses AS (
    SELECT n,
      to_char(date_trunc('month', v_hoy) - (n || ' months')::interval, 'TMMon') AS label,
      (date_trunc('month', v_hoy) - (n || ' months')::interval)::date AS inicio,
      (date_trunc('month', v_hoy) - (n || ' months')::interval + interval '1 month - 1 day')::date AS fin
    FROM generate_series(0, 5) n
  ),
  por_operador AS (
    SELECT
      operador_norm AS nombre,
      count(*) FILTER (WHERE es_activo) AS cargas_activas,
      count(*) FILTER (WHERE es_activo) AS contenedores,
      count(*) FILTER (
        WHERE COALESCE(etd, created_at::date) >= date_trunc('month', v_hoy)::date
          AND COALESCE(etd, created_at::date) <= (date_trunc('month', v_hoy) + interval '1 month - 1 day')::date
      ) AS este_mes,
      sum(profit) AS profit,
      count(*) FILTER (WHERE es_activo AND riesgo = 'critico') AS criticos,
      count(*) FILTER (WHERE es_activo AND riesgo = 'en_puerto') AS en_puerto,
      count(*) FILTER (WHERE es_activo AND riesgo = 'por_arribar') AS por_arribar,
      count(*) FILTER (
        WHERE estado_real = 'Arribo' AND eta IS NOT NULL AND (v_hoy - eta) > v_dias_libres
      ) AS demoras,
      count(*) FILTER (WHERE es_activo AND estado_real = 'Confirmado') AS conf,
      count(*) FILTER (WHERE es_activo AND estado_real = 'En Tránsito') AS trans,
      count(*) FILTER (WHERE es_activo AND estado_real = 'Arribo') AS llegada,
      count(*) FILTER (WHERE es_activo AND estado_real IN ('En Aduana','Entregado')) AS proceso,
      count(*) FILTER (WHERE estado_real IN ('EIR','Por liquidar','Cerrado')) AS cerrado
    FROM enriched
    GROUP BY operador_norm
  ),
  riesgos_por_op AS (
    SELECT operador_norm,
      jsonb_agg(
        jsonb_build_object(
          'id', id, 'expediente', expediente, 'cliente_nombre', cliente_nombre,
          'operador', operador_norm, 'estadoReal', estado_real,
          'nivelRiesgo', riesgo, 'eta', eta,
          'diasEnPuerto', dias_en_puerto, 'profit', profit
        )
        ORDER BY CASE riesgo WHEN 'critico' THEN 0 WHEN 'en_puerto' THEN 1 WHEN 'por_arribar' THEN 2 ELSE 3 END
      ) AS cargas
    FROM enriched
    WHERE es_activo AND riesgo != 'ok'
    GROUP BY operador_norm
  ),
  clientes_por_op AS (
    SELECT operador_norm,
      jsonb_agg(
        jsonb_build_object(
          'nombre', cliente_nombre,
          'cantidad', total,
          'desgloseEstados', jsonb_build_object(
            'Confirmado', conf, 'En Tránsito', trans,
            'Llegada', llegada, 'En Proceso', proceso, 'Cerrado', cerrado
          )
        ) ORDER BY total DESC
      ) AS clientes
    FROM (
      SELECT
        operador_norm, cliente_nombre,
        count(*) AS total,
        count(*) FILTER (WHERE estado_real = 'Confirmado') AS conf,
        count(*) FILTER (WHERE estado_real = 'En Tránsito') AS trans,
        count(*) FILTER (WHERE estado_real = 'Arribo') AS llegada,
        count(*) FILTER (WHERE estado_real IN ('En Aduana','Entregado')) AS proceso,
        count(*) FILTER (WHERE estado_real IN ('EIR','Por liquidar','Cerrado')) AS cerrado
      FROM enriched
      WHERE es_activo OR estado_real IN ('EIR','Por liquidar','Cerrado')
      GROUP BY operador_norm, cliente_nombre
    ) sub
    GROUP BY operador_norm
  ),
  historico_por_op AS (
    SELECT operador_norm,
      jsonb_agg(
        jsonb_build_object('mes', label, 'creados', creados, 'llegados', llegados)
        ORDER BY n DESC
      ) AS historico
    FROM (
      SELECT e.operador_norm, m.n, m.label,
        count(*) FILTER (
          WHERE COALESCE(e.etd, e.created_at::date) BETWEEN m.inicio AND m.fin
        ) AS creados,
        count(*) FILTER (
          WHERE COALESCE(
            e.fecha_llegada_real,
            CASE WHEN e.estado_real IN ('Entregado','EIR','Por liquidar','Cerrado') THEN e.eta END
          ) BETWEEN m.inicio AND m.fin
        ) AS llegados
      FROM enriched e CROSS JOIN meses m
      GROUP BY e.operador_norm, m.n, m.label
    ) sub
    GROUP BY operador_norm
  ),
  -- NUEVO: detalle de embarques por (operador, estado_ui), con tope por estado
  embarques_ranked AS (
    SELECT
      operador_norm, estado_ui, id, expediente, cliente_nombre,
      modo, tipo, origen_txt, destino_txt, etd, eta, estado_real,
      dias_en_puerto, fecha_llegada_real,
      CASE WHEN estado_real = 'En Tránsito' AND eta IS NOT NULL THEN (eta - v_hoy) ELSE NULL END AS dias_para_eta,
      ROW_NUMBER() OVER (
        PARTITION BY operador_norm, estado_ui
        ORDER BY
          CASE WHEN estado_ui = 'Cerrado' THEN COALESCE(fecha_llegada_real, eta) END DESC NULLS LAST,
          CASE WHEN estado_ui <> 'Cerrado' THEN eta END ASC NULLS LAST,
          expediente ASC
      ) AS rn,
      COUNT(*) OVER (PARTITION BY operador_norm, estado_ui) AS total_estado
    FROM enriched
    WHERE estado_ui IS NOT NULL
  ),
  embarques_filtrados AS (
    SELECT * FROM embarques_ranked
    WHERE (estado_ui = 'Cerrado' AND rn <= 50) OR (estado_ui <> 'Cerrado' AND rn <= 200)
  ),
  embarques_por_estado AS (
    SELECT
      operador_norm,
      jsonb_object_agg(estado_ui, payload) AS embarques_por_estado
    FROM (
      SELECT
        operador_norm, estado_ui,
        jsonb_build_object(
          'total', max(total_estado),
          'truncated', max(total_estado) > count(*),
          'items', jsonb_agg(
            jsonb_build_object(
              'id', id,
              'expediente', expediente,
              'clienteNombre', cliente_nombre,
              'modo', modo,
              'tipo', tipo,
              'origen', origen_txt,
              'destino', destino_txt,
              'etd', etd,
              'eta', eta,
              'estadoReal', estado_real,
              'diasEnPuerto', dias_en_puerto,
              'diasParaEta', dias_para_eta
            ) ORDER BY rn
          )
        ) AS payload
      FROM embarques_filtrados
      GROUP BY operador_norm, estado_ui
    ) sub
    GROUP BY operador_norm
  ),
  operadores_full AS (
    SELECT
      jsonb_agg(
        jsonb_build_object(
          'nombre', po.nombre,
          'cargasActivas', po.cargas_activas,
          'contenedores', po.contenedores,
          'cargasEsteMes', po.este_mes,
          'profit', po.profit,
          'demoras', po.demoras,
          'criticos', po.criticos,
          'enPuerto', po.en_puerto,
          'porArribar', po.por_arribar,
          'desgloseEstados', jsonb_build_object(
            'Confirmado', po.conf, 'En Tránsito', po.trans,
            'Llegada', po.llegada, 'En Proceso', po.proceso, 'Cerrado', po.cerrado
          ),
          'clientesDesglose', COALESCE(cpo.clientes, '[]'::jsonb),
          'cargasEnRiesgo', COALESCE(rpo.cargas, '[]'::jsonb),
          'historico', COALESCE(hpo.historico, '[]'::jsonb),
          'embarquesPorEstado', COALESCE(epe.embarques_por_estado, '{}'::jsonb)
        ) ORDER BY po.profit DESC
      ) AS val
    FROM por_operador po
    LEFT JOIN clientes_por_op cpo ON cpo.operador_norm = po.nombre
    LEFT JOIN riesgos_por_op rpo ON rpo.operador_norm = po.nombre
    LEFT JOIN historico_por_op hpo ON hpo.operador_norm = po.nombre
    LEFT JOIN embarques_por_estado epe ON epe.operador_norm = po.nombre
  ),
  global AS (
    SELECT jsonb_build_object(
      'totalActivas', count(*) FILTER (WHERE es_activo),
      'totalContenedores', count(*) FILTER (WHERE es_activo),
      'totalEsteMes', count(*) FILTER (
        WHERE COALESCE(etd, created_at::date) >= date_trunc('month', v_hoy)::date
          AND COALESCE(etd, created_at::date) <= (date_trunc('month', v_hoy) + interval '1 month - 1 day')::date
      ),
      'totalProfit', COALESCE(sum(profit), 0),
      'totalDemoras', count(*) FILTER (
        WHERE estado_real = 'Arribo' AND eta IS NOT NULL AND (v_hoy - eta) > v_dias_libres
      ),
      'totalCriticos', count(*) FILTER (WHERE es_activo AND riesgo = 'critico'),
      'totalEnPuerto', count(*) FILTER (WHERE es_activo AND riesgo = 'en_puerto'),
      'totalPorArribar', count(*) FILTER (WHERE es_activo AND riesgo = 'por_arribar'),
      'activasHoy', count(*) FILTER (WHERE es_activo),
      'maxContenedores', v_max_contenedores
    ) AS val
    FROM enriched
  ),
  historico_global AS (
    SELECT jsonb_agg(
      jsonb_build_object('mes', label, 'creadas', creadas, 'llegadas', llegadas)
      ORDER BY n DESC
    ) AS val
    FROM (
      SELECT m.n, m.label,
        count(*) FILTER (
          WHERE COALESCE(e.etd, e.created_at::date) BETWEEN m.inicio AND m.fin
        ) AS creadas,
        count(*) FILTER (
          WHERE COALESCE(
            e.fecha_llegada_real,
            CASE WHEN e.estado_real IN ('Entregado','EIR','Por liquidar','Cerrado') THEN e.eta END
          ) BETWEEN m.inicio AND m.fin
        ) AS llegadas
      FROM meses m LEFT JOIN enriched e ON true
      GROUP BY m.n, m.label
    ) sub
  ),
  meses_labels AS (
    SELECT jsonb_agg(label ORDER BY n DESC) AS val FROM meses
  )
  SELECT jsonb_build_object(
    'operadores', COALESCE(operadores_full.val, '[]'::jsonb),
    'global', global.val,
    'historicoGlobal', COALESCE(historico_global.val, '[]'::jsonb),
    'mesesLabels', meses_labels.val
  ) INTO result
  FROM operadores_full, global, historico_global, meses_labels;
  RETURN result;
END;
$$;
CREATE FUNCTION public.operadores_distintos() RETURNS TABLE(operador text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT e.operador
  FROM embarques e
  WHERE e.deleted_at IS NULL                  -- FIX C5
    AND e.operador IS NOT NULL AND e.operador != ''
    AND (e.organization_id = public.org_scope())
  ORDER BY e.operador;
$$;
CREATE FUNCTION public.org_requerida(p_org uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  v_org := COALESCE(p_org, public.current_user_org_id());
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_REQUERIDA: selecciona una organización para ver esta información'
      USING ERRCODE = '42501';
  END IF;
  RETURN v_org;
END;
$$;
CREATE FUNCTION public.org_scope() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN public.has_role(auth.uid(), 'super_admin')
      THEN (SELECT s.organization_id FROM public.super_admin_org_activa s WHERE s.user_id = auth.uid())
    ELSE public.current_user_org_id()
  END
$$;
CREATE FUNCTION public.pago_detalle(p_tipo text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org         uuid;
  v_super       boolean;
  v_pago        jsonb := NULL;
  v_mov         jsonb := NULL;
  v_aplic       jsonb := '[]'::jsonb;
  v_org_pago    uuid;
  v_lote        uuid := NULL;
  v_tipo        text;
BEGIN
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'LC_PAGO_DETALLE_PARAMS: falta el identificador del pago';
  END IF;
  v_tipo := lower(coalesce(p_tipo, ''));
  IF v_tipo NOT IN ('cobro','pago','anticipo','lote') THEN
    RAISE EXCEPTION 'LC_PAGO_DETALLE_TIPO: tipo de pago no soportado (%)', p_tipo;
  END IF;
  v_org := current_user_org_id();
  v_super := has_role(auth.uid(), 'super_admin');
  IF v_org IS NULL AND NOT v_super THEN
    RAISE EXCEPTION 'LC_PAGO_DETALLE_SIN_ORG: no se pudo determinar tu organización';
  END IF;
  IF v_tipo = 'cobro' THEN
    SELECT pf.organization_id,
           jsonb_build_object(
             'id', pf.id, 'tipo', 'cobro', 'fecha', pf.fecha_pago,
             'contraparte', c.nombre, 'contraparte_id', f.cliente_id,
             'moneda', pf.moneda::text, 'monto', COALESCE(pf.monto,0),
             'tipo_cambio', COALESCE(pf.tipo_cambio,1),
             'monto_mxn', CASE WHEN pf.moneda::text='MXN' THEN COALESCE(pf.monto,0)
                               ELSE COALESCE(pf.monto,0)*COALESCE(pf.tipo_cambio,1) END,
             'metodo_pago', pf.forma_pago, 'referencia', pf.referencia,
             'cuenta_bancaria_id', pf.cuenta_bancaria_id,
             'cuenta_alias', cb.alias, 'cuenta_banco', cb.banco,
             'notas', pf.notas, 'embarque_id', pf.embarque_id,
             'diferencia_cambiaria_mxn', COALESCE(pf.diferencia_cambiaria_mxn,0),
             'estado_rep', pf.estado_rep,
             'folio_rep', NULLIF(TRIM(COALESCE(pf.serie_rep,'')||COALESCE(pf.folio_rep::text,'')),''),
             'es_ajuste', false, 'lote_id', NULL::uuid,
             'created_by', pf.created_by, 'created_at', pf.created_at
           )
      INTO v_org_pago, v_pago
    FROM public.pagos_factura pf
    JOIN public.facturas f ON f.id = pf.factura_id
    LEFT JOIN public.clientes c ON c.id = f.cliente_id
    LEFT JOIN public.cuentas_bancarias cb ON cb.id = pf.cuenta_bancaria_id
    WHERE pf.id = p_id AND pf.deleted_at IS NULL;
  ELSIF v_tipo = 'pago' THEN
    SELECT pp.organization_id, pp.lote_id,
           jsonb_build_object(
             'id', pp.id, 'tipo', 'pago', 'fecha', pp.fecha_pago,
             'contraparte', pr.nombre, 'contraparte_id', pfa.proveedor_id,
             'moneda', pp.moneda::text, 'monto', COALESCE(pp.monto,0),
             'tipo_cambio', COALESCE(pp.tipo_cambio_usd,1),
             'monto_mxn', CASE WHEN pp.moneda::text='MXN' THEN COALESCE(pp.monto,0)
                               ELSE COALESCE(pp.monto,0)*COALESCE(pp.tipo_cambio_usd,1) END,
             'metodo_pago', pp.metodo_pago, 'referencia', pp.referencia,
             'cuenta_bancaria_id', pp.cuenta_bancaria_id,
             'cuenta_alias', cb.alias, 'cuenta_banco', cb.banco,
             'notas', pp.notas, 'embarque_id', pfa.embarque_id,
             'diferencia_cambiaria_mxn', COALESCE(pp.diferencia_cambiaria_mxn,0),
             'estado_rep', NULL::text, 'folio_rep', NULL::text,
             'es_ajuste', COALESCE(pp.es_ajuste,false), 'lote_id', pp.lote_id,
             'created_by', pp.created_by, 'created_at', pp.created_at
           )
      INTO v_org_pago, v_lote, v_pago
    FROM public.pagos_proveedor pp
    JOIN public.proveedor_facturas pfa ON pfa.id = pp.proveedor_factura_id
    LEFT JOIN public.proveedores pr ON pr.id = pfa.proveedor_id
    LEFT JOIN public.cuentas_bancarias cb ON cb.id = pp.cuenta_bancaria_id
    WHERE pp.id = p_id AND pp.deleted_at IS NULL;
  ELSIF v_tipo = 'lote' THEN
    v_lote := p_id;
    SELECT l.organization_id,
           jsonb_build_object(
             'id', l.id, 'tipo', 'lote', 'fecha', l.fecha_pago,
             'contraparte', pr.nombre, 'contraparte_id', l.proveedor_id,
             'moneda', l.moneda::text, 'monto', COALESCE(l.monto_total,0),
             'tipo_cambio', COALESCE(l.tipo_cambio_usd,1),
             'monto_mxn', CASE WHEN l.moneda::text='MXN' THEN COALESCE(l.monto_total,0)
                               ELSE COALESCE(l.monto_total,0)*COALESCE(l.tipo_cambio_usd,1) END,
             'metodo_pago', l.metodo_pago, 'referencia', l.referencia,
             'cuenta_bancaria_id', l.cuenta_bancaria_id,
             'cuenta_alias', cb.alias, 'cuenta_banco', cb.banco,
             'notas', l.notas, 'embarque_id', NULL::uuid,
             'diferencia_cambiaria_mxn', 0::numeric,
             'estado_rep', NULL::text, 'folio_rep', NULL::text,
             'es_ajuste', false, 'lote_id', l.id,
             'created_by', l.created_by, 'created_at', l.created_at
           )
      INTO v_org_pago, v_pago
    FROM public.pagos_proveedor_lote l
    LEFT JOIN public.proveedores pr ON pr.id = l.proveedor_id
    LEFT JOIN public.cuentas_bancarias cb ON cb.id = l.cuenta_bancaria_id
    WHERE l.id = p_id AND l.deleted_at IS NULL;
  ELSE
    SELECT ap.organization_id,
           jsonb_build_object(
             'id', ap.id, 'tipo', 'anticipo', 'fecha', ap.fecha_anticipo,
             'contraparte', pr.nombre, 'contraparte_id', ap.proveedor_id,
             'moneda', ap.moneda::text, 'monto', COALESCE(ap.monto,0),
             'tipo_cambio', COALESCE(ap.tipo_cambio_usd,1),
             'monto_mxn', CASE WHEN ap.moneda::text='MXN' THEN COALESCE(ap.monto,0)
                               ELSE COALESCE(ap.monto,0)*COALESCE(ap.tipo_cambio_usd,1) END,
             'metodo_pago', ap.metodo_pago, 'referencia', ap.referencia,
             'cuenta_bancaria_id', ap.cuenta_bancaria_id,
             'cuenta_alias', cb.alias, 'cuenta_banco', cb.banco,
             'notas', ap.notas, 'embarque_id', ap.embarque_id,
             'diferencia_cambiaria_mxn', 0::numeric,
             'estado_rep', NULL::text, 'folio_rep', NULL::text,
             'es_ajuste', false, 'lote_id', NULL::uuid,
             'estado', COALESCE(ap.estado,'Vigente'),
             'saldo_disponible', COALESCE(ap.saldo_disponible,0),
             'created_by', ap.created_by, 'created_at', ap.created_at
           )
      INTO v_org_pago, v_pago
    FROM public.anticipos_proveedor ap
    LEFT JOIN public.proveedores pr ON pr.id = ap.proveedor_id
    LEFT JOIN public.cuentas_bancarias cb ON cb.id = ap.cuenta_bancaria_id
    WHERE ap.id = p_id AND ap.deleted_at IS NULL;
  END IF;
  IF v_pago IS NULL THEN
    RAISE EXCEPTION 'LC_PAGO_DETALLE_NO_ENCONTRADO: el pago no existe o fue eliminado';
  END IF;
  IF NOT v_super AND v_org_pago IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'LC_PAGO_DETALLE_SIN_ACCESO: el pago pertenece a otra organización';
  END IF;
  SELECT jsonb_build_object(
           'id', m.id, 'fecha', m.fecha, 'concepto', m.concepto,
           'referencia', m.referencia, 'cargo', COALESCE(m.cargo,0), 'abono', COALESCE(m.abono,0),
           'saldo', m.saldo, 'estado_conciliacion', m.estado_conciliacion::text,
           'cuenta_bancaria_id', m.cuenta_bancaria_id,
           'cuenta_alias', cb.alias, 'cuenta_banco', cb.banco,
           'conciliado_por', m.conciliado_por, 'conciliado_at', m.conciliado_at
         )
    INTO v_mov
  FROM public.bbva_movimientos m
  LEFT JOIN public.cuentas_bancarias cb ON cb.id = m.cuenta_bancaria_id
  WHERE m.deleted_at IS NULL
    AND (v_super OR m.organization_id = v_org)
    AND (
      (v_tipo = 'cobro'    AND m.pago_factura_id = p_id)
      OR (v_tipo = 'pago'  AND (m.pago_proveedor_id = p_id
                                OR (v_lote IS NOT NULL AND m.pago_proveedor_lote_id = v_lote)))
      OR (v_tipo = 'lote'  AND m.pago_proveedor_lote_id = p_id)
      OR (v_tipo = 'anticipo' AND m.anticipo_proveedor_id = p_id)
    )
  ORDER BY m.fecha DESC
  LIMIT 1;
  IF v_tipo = 'cobro' THEN
    SELECT COALESCE(jsonb_agg(x), '[]'::jsonb) INTO v_aplic
    FROM (
      SELECT jsonb_build_object(
               'documento_id', f.id, 'documento_tipo', 'cliente',
               'folio', NULLIF(TRIM(COALESCE(f.serie,'')||COALESCE(f.numero::text,'')),''),
               'embarque_id', pf.embarque_id,
               'moneda', f.moneda::text,
               'monto_aplicado', COALESCE(pf.monto_aplicado_factura, pf.monto, 0),
               'total', COALESCE(f.total,0),
               'pagado', COALESCE((SELECT SUM(COALESCE(p2.monto_aplicado_factura, p2.monto, 0))
                                   FROM public.pagos_factura p2
                                   WHERE p2.factura_id = f.id AND p2.deleted_at IS NULL), 0)
             ) AS x
      FROM public.pagos_factura pf
      JOIN public.facturas f ON f.id = pf.factura_id
      WHERE pf.id = p_id AND pf.deleted_at IS NULL
    ) s;
  ELSIF v_tipo IN ('pago','lote') THEN
    SELECT COALESCE(jsonb_agg(x ORDER BY folio), '[]'::jsonb) INTO v_aplic
    FROM (
      SELECT COALESCE(pfa.folio_interno, pfa.folio_proveedor) AS folio,
             jsonb_build_object(
               'documento_id', pfa.id, 'documento_tipo', 'proveedor',
               'folio', COALESCE(pfa.folio_interno, pfa.folio_proveedor),
               'folio_proveedor', pfa.folio_proveedor,
               'embarque_id', pfa.embarque_id,
               'moneda', pfa.moneda::text,
               'monto_aplicado', COALESCE(pp.monto_en_moneda_factura, pp.monto, 0),
               'pago_id', pp.id,
               'total', COALESCE(pfa.total,0),
               'pagado', COALESCE((SELECT SUM(COALESCE(p2.monto_en_moneda_factura, p2.monto, 0))
                                   FROM public.pagos_proveedor p2
                                   WHERE p2.proveedor_factura_id = pfa.id AND p2.deleted_at IS NULL), 0)
             ) AS x
      FROM public.pagos_proveedor pp
      JOIN public.proveedor_facturas pfa ON pfa.id = pp.proveedor_factura_id
      WHERE pp.deleted_at IS NULL
        AND ((v_lote IS NOT NULL AND pp.lote_id = v_lote) OR (v_lote IS NULL AND pp.id = p_id))
    ) s;
  ELSE
    SELECT COALESCE(jsonb_agg(x ORDER BY folio), '[]'::jsonb) INTO v_aplic
    FROM (
      SELECT COALESCE(pfa.folio_interno, pfa.folio_proveedor) AS folio,
             jsonb_build_object(
               'documento_id', pfa.id, 'documento_tipo', 'proveedor',
               'folio', COALESCE(pfa.folio_interno, pfa.folio_proveedor),
               'folio_proveedor', pfa.folio_proveedor,
               'embarque_id', pfa.embarque_id,
               'moneda', COALESCE(aa.moneda_aplicada::text, pfa.moneda::text),
               'monto_aplicado', COALESCE(aa.monto_aplicado,0),
               'fecha_aplicacion', aa.fecha_aplicacion,
               'total', COALESCE(pfa.total,0),
               'pagado', COALESCE((SELECT SUM(COALESCE(p2.monto_en_moneda_factura, p2.monto, 0))
                                   FROM public.pagos_proveedor p2
                                   WHERE p2.proveedor_factura_id = pfa.id AND p2.deleted_at IS NULL), 0)
             ) AS x
      FROM public.anticipos_aplicaciones aa
      JOIN public.proveedor_facturas pfa ON pfa.id = aa.proveedor_factura_id
      WHERE aa.anticipo_id = p_id AND aa.deleted_at IS NULL
    ) s;
  END IF;
  RETURN jsonb_build_object(
    'tipo', v_tipo,
    'pago', v_pago,
    'movimiento', v_mov,
    'aplicaciones', v_aplic
  );
END;
$$;
CREATE FUNCTION public.pnl_financiero_embarque(_embarque_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _tc_usd numeric; _tc_eur numeric; _org uuid;
  _has_pf boolean; _has_seg boolean;
  _estado_costos text;
  _fecha_emb date;
  _base jsonb;
BEGIN
  SELECT COALESCE(tipo_cambio_usd,0), COALESCE(tipo_cambio_eur,0), organization_id,
         COALESCE(eta, fecha_llegada_real, etd, fecha_creacion::date)
    INTO _tc_usd, _tc_eur, _org, _fecha_emb
  FROM public.embarques WHERE id = _embarque_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Embarque % no encontrado', _embarque_id;
  END IF;
  IF NOT public.has_role(auth.uid(), 'super_admin'::app_role)
     AND _org IS DISTINCT FROM public.current_user_org_id() THEN
    RAISE EXCEPTION 'Sin acceso al embarque %', _embarque_id USING ERRCODE='42501';
  END IF;
  SELECT EXISTS(SELECT 1 FROM public.proveedor_facturas WHERE embarque_id=_embarque_id AND deleted_at IS NULL
                  AND estado::text NOT IN ('Borrador','Cancelada')) INTO _has_pf;
  SELECT EXISTS(SELECT 1 FROM public.seguros_embarque WHERE embarque_id=_embarque_id AND deleted_at IS NULL) INTO _has_seg;
  IF NOT _has_pf AND NOT _has_seg THEN
    _estado_costos := 'incompleto';
  ELSE
    _estado_costos := 'completo';
  END IF;
  WITH
  cv AS (
    SELECT lower(trim(coalesce(descripcion,'(sin concepto)'))) AS concepto,
           moneda::text AS moneda, coalesce(total,0)::numeric AS monto,
           (SELECT t.tc FROM public.tc_para_documento(_fecha_emb, moneda::text, NULL, CASE WHEN UPPER(moneda::text) = 'EUR' THEN _tc_eur ELSE _tc_usd END) t) AS tc_doc
    FROM public.conceptos_venta
    WHERE embarque_id = _embarque_id AND deleted_at IS NULL
  ),
  cc AS (
    SELECT lower(trim(coalesce(concepto,'(sin concepto)'))) AS concepto,
           moneda::text AS moneda, coalesce(monto,0)::numeric AS monto,
           proveedor_id, coalesce(proveedor_nombre,'(sin proveedor)') AS proveedor_nombre,
           (SELECT t.tc FROM public.tc_para_documento(_fecha_emb, moneda::text, NULL, CASE WHEN UPPER(moneda::text) = 'EUR' THEN _tc_eur ELSE _tc_usd END) t) AS tc_doc
    FROM public.conceptos_costo
    WHERE embarque_id = _embarque_id AND deleted_at IS NULL
  ),
  seg AS (
    SELECT 'seguro de carga'::text AS concepto, moneda::text AS moneda,
           coalesce(prima,0)::numeric AS monto,
           NULL::uuid AS proveedor_id, aseguradora AS proveedor_nombre,
           (SELECT t.tc FROM public.tc_para_documento(_fecha_emb, moneda::text, NULL, CASE WHEN UPPER(moneda::text) = 'EUR' THEN _tc_eur ELSE _tc_usd END) t) AS tc_doc
    FROM public.seguros_embarque
    WHERE embarque_id = _embarque_id AND deleted_at IS NULL
  ),
  f AS (
    SELECT id, coalesce(subtotal,0)::numeric AS subtotal, moneda::text AS moneda,
           estado::text AS estado, total::numeric AS total,
           (SELECT t.tc FROM public.tc_para_documento(fecha_emision, moneda::text, tipo_cambio, CASE WHEN UPPER(moneda::text) = 'EUR' THEN _tc_eur ELSE _tc_usd END) t) AS tc_doc
    FROM public.facturas
    WHERE embarque_id = _embarque_id AND deleted_at IS NULL
      AND estado::text NOT IN ('Borrador','Cancelada','Sustituida')
  ),
  fnc AS (
    SELECT n.factura_id, coalesce(n.monto,0)::numeric AS monto, n.moneda::text AS moneda
    FROM public.factura_notas_credito n
    JOIN f ON f.id = n.factura_id
    WHERE n.deleted_at IS NULL AND n.estado::text = 'Aplicada'
  ),
  f_neto AS (
    SELECT f.id, f.moneda, f.estado, f.tc_doc,
           f.subtotal - coalesce((SELECT sum(monto) FROM fnc WHERE factura_id = f.id),0) AS monto
    FROM f
  ),
  f_saldo AS (
    SELECT f.id, f.moneda, f.estado, f.tc_doc, public.saldo_factura(f.id) AS saldo FROM f
  ),
  pf AS (
    SELECT id, proveedor_id, coalesce(proveedor_nombre,'(sin proveedor)') AS proveedor_nombre,
           coalesce(NULLIF(total,0), subtotal, 0)::numeric AS total,
           -- Base gravable (sin IVA): subtotal si existe; si no, total menos
           -- impuestos capturados. Nunca negativa.
           GREATEST(
             coalesce(
               NULLIF(subtotal,0),
               coalesce(NULLIF(total,0),0) - coalesce(iva,0) + coalesce(retenciones,0),
               0
             )::numeric, 0)::numeric AS base_gravable,
           moneda::text AS moneda, estado::text AS estado,
           (SELECT t.tc FROM public.tc_para_documento(fecha_emision, moneda::text, tipo_cambio_usd, CASE WHEN UPPER(moneda::text) = 'EUR' THEN _tc_eur ELSE _tc_usd END) t) AS tc_doc
    FROM public.proveedor_facturas
    WHERE embarque_id = _embarque_id AND deleted_at IS NULL
      AND estado::text NOT IN ('Borrador','Cancelada')
  ),
  pnc AS (
    SELECT n.proveedor_factura_id, coalesce(n.monto,0)::numeric AS monto, n.moneda::text AS moneda
    FROM public.proveedor_notas_credito n JOIN pf ON pf.id = n.proveedor_factura_id
    WHERE n.deleted_at IS NULL AND n.estado::text = 'Aplicada'
  ),
  pf_neto AS (
    -- Costo real = base gravable menos notas de crédito prorrateadas a esa base.
    SELECT pf.id, pf.proveedor_id, pf.proveedor_nombre, pf.moneda, pf.estado, pf.tc_doc,
           pf.base_gravable
             - coalesce((SELECT sum(monto) FROM pnc WHERE proveedor_factura_id = pf.id),0)
               * CASE WHEN pf.total > 0 THEN pf.base_gravable / pf.total ELSE 1 END AS monto
    FROM pf
  ),
  pf_saldo AS (
    SELECT pf.id, pf.moneda, pf.estado, pf.tc_doc,
           (pf.total
              - coalesce((SELECT sum(monto) FROM pnc WHERE proveedor_factura_id = pf.id),0)
              - coalesce((SELECT sum(pp.monto_en_moneda_factura)
                          FROM public.pagos_proveedor pp
                          WHERE pp.proveedor_factura_id = pf.id AND pp.deleted_at IS NULL),0)
           ) AS saldo
    FROM pf
  ),
  totales AS (
    SELECT
      (SELECT coalesce(sum(public.a_mxn(monto, moneda, tc_doc, tc_doc)),0) FROM f_neto) AS venta_real_mxn,
      (SELECT coalesce(sum(public.a_mxn(monto, moneda, tc_doc, tc_doc)),0) FROM pf_neto)
        + (SELECT coalesce(sum(public.a_mxn(monto, moneda, tc_doc, tc_doc)),0) FROM seg) AS costo_real_mxn
  )
  SELECT jsonb_build_object(
    'embarque_id', _embarque_id,
    'tipo_cambio_usd', _tc_usd,
    'tipo_cambio_eur', _tc_eur,
    'estado_costos', _estado_costos,
    'tc_por_documento', true,
    'excluidos_sin_tc', (
      (SELECT count(*) FROM cv WHERE moneda <> 'MXN' AND tc_doc IS NULL)
      + (SELECT count(*) FROM cc WHERE moneda <> 'MXN' AND tc_doc IS NULL)
      + (SELECT count(*) FROM f_neto WHERE moneda <> 'MXN' AND tc_doc IS NULL)
      + (SELECT count(*) FROM pf_neto WHERE moneda <> 'MXN' AND tc_doc IS NULL)
    ),
    'venta', jsonb_build_object(
      'presupuestada_mxn', (SELECT coalesce(sum(public.a_mxn(monto, moneda, tc_doc, tc_doc)),0) FROM cv),
      'real_mxn', t.venta_real_mxn,
      'pdte_cobro_mxn', (SELECT coalesce(sum(public.a_mxn(saldo, moneda, tc_doc, tc_doc)),0)
                          FROM f_saldo WHERE estado IN ('Emitida','Vencida','Parcialmente pagada','Por timbrar'))
    ),
    'costo', jsonb_build_object(
      'presupuestado_mxn', (SELECT coalesce(sum(public.a_mxn(monto, moneda, tc_doc, tc_doc)),0) FROM cc),
      'real_mxn', t.costo_real_mxn,
      'pdte_pago_mxn', (SELECT coalesce(sum(public.a_mxn(saldo, moneda, tc_doc, tc_doc)),0)
                         FROM pf_saldo WHERE estado IN ('Vigente','Parcial','Por vencer','Vencida'))
    ),
    'utilidad_mxn', CASE
      WHEN _estado_costos = 'incompleto' THEN NULL
      ELSE round((t.venta_real_mxn - t.costo_real_mxn)::numeric, 2)
    END,
    'por_concepto', (
      SELECT coalesce(jsonb_agg(row_to_json(x) ORDER BY (x.presupuestada_mxn + x.real_mxn) DESC), '[]'::jsonb) FROM (
        SELECT concepto,
               coalesce(sum(presup),0) AS presupuestada_mxn,
               coalesce(sum(real),0) AS real_mxn
        FROM (
          SELECT concepto,
                 public.a_mxn(monto, moneda, tc_doc, tc_doc) AS presup,
                 0::numeric AS real FROM cv
          UNION ALL
          SELECT lower(trim(coalesce(NULLIF(fc.descripcion,''), '(sin concepto)'))),
                 0::numeric,
                 public.a_mxn(coalesce(fc.total,0), f.moneda, f.tc_doc, f.tc_doc)
          FROM public.conceptos_factura fc
          JOIN f ON f.id = fc.factura_id
          WHERE fc.deleted_at IS NULL
        ) u GROUP BY concepto
      ) x
    ),
    'por_concepto_costo', (
      SELECT coalesce(jsonb_agg(row_to_json(x) ORDER BY (x.presupuestado_mxn + x.real_mxn) DESC), '[]'::jsonb) FROM (
        SELECT concepto,
               coalesce(sum(presup),0) AS presupuestado_mxn,
               coalesce(sum(real),0) AS real_mxn
        FROM (
          SELECT concepto,
                 public.a_mxn(monto, moneda, tc_doc, tc_doc) AS presup,
                 0::numeric AS real FROM cc
          UNION ALL
          SELECT lower(trim(coalesce(NULLIF(pfc.descripcion,''), '(sin concepto)'))),
                 0::numeric,
                 public.a_mxn(coalesce(pfc.monto, 0), pf.moneda, pf.tc_doc, pf.tc_doc)
          FROM public.proveedor_facturas_conceptos pfc
          JOIN pf ON pf.id = pfc.proveedor_factura_id
          UNION ALL
          SELECT '(factura completa)'::text,
                 0::numeric,
                 public.a_mxn(pf_neto.monto, pf_neto.moneda, pf_neto.tc_doc, pf_neto.tc_doc)
          FROM pf_neto
          WHERE NOT EXISTS (SELECT 1 FROM public.proveedor_facturas_conceptos pfc
                              WHERE pfc.proveedor_factura_id = pf_neto.id)
          UNION ALL
          SELECT concepto, 0::numeric,
                 public.a_mxn(monto, moneda, tc_doc, tc_doc)
          FROM seg
        ) u GROUP BY concepto
      ) x
    ),
    'por_proveedor', (
      SELECT coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) FROM (
        SELECT proveedor_id, proveedor_nombre,
               coalesce(sum(presup_mxn),0) AS presupuestado_mxn,
               coalesce(sum(real_mxn),0) AS real_mxn,
               coalesce(sum(facturas_count),0) AS facturas_count
        FROM (
          SELECT proveedor_id, proveedor_nombre,
                 public.a_mxn(monto, moneda, tc_doc, tc_doc) AS presup_mxn,
                 0::numeric AS real_mxn, 0 AS facturas_count FROM cc
          UNION ALL SELECT proveedor_id, proveedor_nombre, 0::numeric,
                 public.a_mxn(monto, moneda, tc_doc, tc_doc), 1 FROM pf_neto
          UNION ALL SELECT proveedor_id, proveedor_nombre, 0::numeric,
                 public.a_mxn(monto, moneda, tc_doc, tc_doc), 1 FROM seg
        ) u GROUP BY proveedor_id, proveedor_nombre
      ) x
    )
  ) INTO _base FROM totales t;
  RETURN _base;
END;
$$;
CREATE FUNCTION public.portal_obtener_proforma_por_token(p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_proforma public.proformas%ROWTYPE;
  v_conceptos jsonb;
  v_estado_link text;
  v_rl jsonb;
  v_moneda_legacy text;
BEGIN
  v_rl := public.check_ratelimit(
    'rpc:portal_obtener_proforma_por_token:'
      || COALESCE(NULLIF(current_setting('request.headers', true)::jsonb->>'x-forwarded-for', ''), 'sin-ip')
      || ':' || COALESCE(auth.uid()::text, 'anon'),
    60, 30
  );
  IF (v_rl->>'ok') = 'false' THEN
    RAISE EXCEPTION 'Demasiadas solicitudes. Intenta de nuevo en % segundos.', COALESCE(v_rl->>'retry_after', '60')
      USING ERRCODE = 'P0001';
  END IF;
  IF p_token IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_proforma FROM public.proformas WHERE token_publico = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','token_invalido'); END IF;
  IF v_proforma.token_expira_at IS NOT NULL AND v_proforma.token_expira_at < now() THEN
    v_estado_link := 'expirado';
  ELSIF v_proforma.estado_cliente <> 'pendiente' THEN
    v_estado_link := 'respondida';
  ELSE
    v_estado_link := 'activo';
  END IF;
  -- BL-11 (migración 20260817142000): link no vigente → no exponer montos,
  -- conceptos ni datos del cliente; sólo el estado y el número.
  IF v_estado_link <> 'activo' THEN
    RETURN jsonb_build_object(
      'estado_link', v_estado_link,
      'proforma', jsonb_build_object(
        'id', v_proforma.id,
        'numero', v_proforma.numero
      ),
      'conceptos', '[]'::jsonb
    );
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', pcc.id,
    'descripcion', pcc.descripcion,
    'cantidad', pcc.cantidad,
    'precio_unitario', pcc.precio_unitario,
    'importe', pcc.total,
    'moneda', pcc.moneda
  ) ORDER BY pcc.created_at), '[]'::jsonb)
    INTO v_conceptos
    FROM public.proforma_conceptos_consolidados pcc
   WHERE pcc.proforma_id = v_proforma.id;
  -- FIX4 N-2: las columnas singulares ya no existen (multimoneda dual). Las
  -- claves legacy se derivan: MXN si hay subtotal_mxn o si ambos son cero
  -- (default histórico); si no, USD. El front nuevo usa los juegos duales.
  v_moneda_legacy := CASE
    WHEN v_proforma.subtotal_mxn > 0
      OR (v_proforma.subtotal_mxn = 0 AND v_proforma.subtotal_usd = 0)
    THEN 'MXN'
    ELSE 'USD'
  END;
  RETURN jsonb_build_object(
    'estado_link', v_estado_link,
    'proforma', jsonb_build_object(
      'id', v_proforma.id,
      'numero', v_proforma.numero,
      'cliente_nombre', v_proforma.cliente_nombre,
      'expediente', v_proforma.expediente,
      -- Juegos duales (fuente de verdad multimoneda)
      'subtotal_mxn', v_proforma.subtotal_mxn,
      'iva_mxn', v_proforma.iva_mxn,
      'total_mxn', v_proforma.total_mxn,
      'subtotal_usd', v_proforma.subtotal_usd,
      'iva_usd', v_proforma.iva_usd,
      'total_usd', v_proforma.total_usd,
      -- Claves legacy singulares derivadas (compat con el front publicado)
      'moneda', v_moneda_legacy,
      'subtotal', CASE WHEN v_moneda_legacy = 'MXN' THEN v_proforma.subtotal_mxn ELSE v_proforma.subtotal_usd END,
      'iva', CASE WHEN v_moneda_legacy = 'MXN' THEN v_proforma.iva_mxn ELSE v_proforma.iva_usd END,
      'total', CASE WHEN v_moneda_legacy = 'MXN' THEN v_proforma.total_mxn ELSE v_proforma.total_usd END,
      'estado_cliente', v_proforma.estado_cliente,
      'aceptada_at', v_proforma.aceptada_at,
      'rechazada_at', v_proforma.rechazada_at,
      'motivo_rechazo', v_proforma.motivo_rechazo,
      'created_at', v_proforma.created_at,
      'token_expira_at', v_proforma.token_expira_at
    ),
    'conceptos', v_conceptos
  );
END $$;
CREATE FUNCTION public.portal_responder_cotizacion(p_cotizacion_id uuid, p_respuesta text, p_comentario text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cotizacion cotizaciones%ROWTYPE;
  v_user_email text;
  v_now timestamptz := now();
  v_comentario text;
  v_titulo text;
  v_mensaje text;
  v_tipo text;
BEGIN
  IF p_respuesta NOT IN ('Aceptada', 'Rechazada') THEN
    RAISE EXCEPTION 'LC_RESPUESTA_INVALIDA: respuesta debe ser Aceptada o Rechazada' USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO v_cotizacion
  FROM cotizaciones
  WHERE id = p_cotizacion_id
    AND cliente_id IN (SELECT current_user_client_ids())
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_COT_NO_ENCONTRADA: cotización no encontrada o sin acceso' USING ERRCODE = 'P0002';
  END IF;
  IF v_cotizacion.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'LC_COT_ELIMINADA: esta cotización ya no está disponible' USING ERRCODE = 'P0001';
  END IF;
  IF v_cotizacion.estado IN ('Aceptada'::estado_cotizacion, 'Rechazada'::estado_cotizacion, 'En operación'::estado_cotizacion) THEN
    RETURN jsonb_build_object(
      'id', p_cotizacion_id,
      'estado', v_cotizacion.estado::text,
      'fecha_respuesta', COALESCE(v_cotizacion.fecha_aceptacion, v_cotizacion.fecha_rechazo),
      'idempotente', true
    );
  END IF;
  IF v_cotizacion.estado <> 'Enviada'::estado_cotizacion THEN
    RAISE EXCEPTION 'LC_COT_NO_RESPONDIBLE: solo se pueden responder cotizaciones en estado Enviada (actual: %)', v_cotizacion.estado USING ERRCODE = 'P0001';
  END IF;
  -- FIX-BL-05: rechazar si vigencia expiró (solo aplica a Aceptada).
  IF p_respuesta = 'Aceptada'
     AND v_cotizacion.fecha_vigencia IS NOT NULL
     AND v_cotizacion.fecha_vigencia < CURRENT_DATE THEN
    RAISE EXCEPTION 'LC_COTIZACION_VENCIDA: la cotización venció el % — solicita una actualización', v_cotizacion.fecha_vigencia
      USING ERRCODE = 'P0001';
  END IF;
  v_comentario := NULLIF(trim(p_comentario), '');
  UPDATE cotizaciones
  SET estado = p_respuesta::estado_cotizacion,
      comentario_cliente = v_comentario,
      fecha_aceptacion = CASE WHEN p_respuesta = 'Aceptada' THEN v_now ELSE fecha_aceptacion END,
      fecha_rechazo    = CASE WHEN p_respuesta = 'Rechazada' THEN v_now ELSE fecha_rechazo END,
      updated_at = v_now
  WHERE id = p_cotizacion_id;
  SELECT email INTO v_user_email FROM auth.users WHERE id = auth.uid();
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, accion, modulo,
    entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_cotizacion.organization_id,
    auth.uid(),
    COALESCE(v_user_email, ''),
    CASE WHEN p_respuesta = 'Aceptada' THEN 'cotizacion_aceptada' ELSE 'cotizacion_rechazada' END,
    'cotizaciones',
    p_cotizacion_id,
    COALESCE(v_cotizacion.folio, ''),
    jsonb_build_object(
      'cotizacion_id', p_cotizacion_id,
      'folio', v_cotizacion.folio,
      'cliente_id', v_cotizacion.cliente_id,
      'cliente_nombre', v_cotizacion.cliente_nombre,
      'estado_anterior', v_cotizacion.estado,
      'estado_nuevo', p_respuesta,
      'comentario_cliente', v_comentario,
      'origen', 'portal_cliente'
    )
  );
  v_tipo := CASE WHEN p_respuesta = 'Aceptada' THEN 'cotizacion_aceptada' ELSE 'cotizacion_rechazada' END;
  v_titulo := 'Cotización ' || COALESCE(v_cotizacion.folio, '') || ' ' ||
              CASE WHEN p_respuesta = 'Aceptada' THEN 'aceptada' ELSE 'rechazada' END;
  v_mensaje := 'Cliente: ' || COALESCE(v_cotizacion.cliente_nombre, 'N/D') ||
               CASE WHEN v_comentario IS NOT NULL THEN E'\nComentario: ' || v_comentario ELSE '' END;
  INSERT INTO public.notificaciones_internas (
    organization_id, usuario_id, tipo, titulo, mensaje, enlace, entidad_tipo, entidad_id
  )
  SELECT
    v_cotizacion.organization_id,
    om.user_id,
    v_tipo,
    v_titulo,
    v_mensaje,
    '/cotizaciones/' || p_cotizacion_id::text,
    'cotizacion',
    p_cotizacion_id
  FROM public.organization_members om
  WHERE om.organization_id = v_cotizacion.organization_id
    AND om.role IN ('admin'::app_role, 'operador'::app_role);
  RETURN jsonb_build_object(
    'id', p_cotizacion_id,
    'estado', p_respuesta,
    'fecha_respuesta', v_now,
    'idempotente', false
  );
END;
$$;
CREATE FUNCTION public.portal_responder_por_token(p_token uuid, p_respuesta text, p_motivo text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_proforma  public.proformas%ROWTYPE;
  v_now       timestamptz := now();
  v_motivo    text;
  v_titulo    text; v_mensaje text; v_tipo text;
  v_liberados integer := 0;
  v_rl        jsonb;
BEGIN
  v_rl := public.check_ratelimit(
    'rpc:portal_responder_por_token:'
      || COALESCE(NULLIF(current_setting('request.headers', true)::jsonb->>'x-forwarded-for', ''), 'sin-ip')
      || ':' || COALESCE(auth.uid()::text, 'anon'),
    60, 10
  );
  IF (v_rl->>'ok') = 'false' THEN
    RAISE EXCEPTION 'Demasiadas solicitudes. Intenta de nuevo en % segundos.', COALESCE(v_rl->>'retry_after', '60')
      USING ERRCODE = 'P0001';
  END IF;
  IF p_respuesta NOT IN ('aceptada','rechazada') THEN
    RAISE EXCEPTION 'Respuesta inválida.';
  END IF;
  -- fix3: FOR UPDATE serializa respuestas concurrentes del mismo token; la
  -- segunda espera el commit de la primera y ve el estado ya respondido.
  SELECT * INTO v_proforma FROM public.proformas WHERE token_publico = p_token FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Enlace inválido.'; END IF;
  IF v_proforma.token_expira_at IS NOT NULL AND v_proforma.token_expira_at < now() THEN
    RAISE EXCEPTION 'El enlace ha expirado. Solicita uno nuevo a tu ejecutivo.';
  END IF;
  IF v_proforma.estado_cliente <> 'pendiente' THEN
    RAISE EXCEPTION 'Esta proforma ya fue respondida (%).', v_proforma.estado_cliente;
  END IF;
  IF p_respuesta = 'rechazada' AND v_proforma.estado_proforma = 'facturada' THEN
    RAISE EXCEPTION 'No puedes rechazar una proforma que ya fue facturada.';
  END IF;
  -- fix3: motivo acotado a 1000 caracteres (se copia a bitácora,
  -- notificaciones y emails; antes era text sin límite).
  v_motivo := NULLIF(LEFT(btrim(COALESCE(p_motivo, '')), 1000), '');
  IF p_respuesta = 'rechazada' AND v_motivo IS NULL THEN
    RAISE EXCEPTION 'Es obligatorio indicar el motivo de rechazo.';
  END IF;
  -- fix3: compare-and-set atómico — si otra respuesta ganó la carrera entre
  -- el SELECT y este UPDATE, 0 filas y se reporta como ya respondida.
  UPDATE public.proformas
     SET estado_cliente = p_respuesta,
         aceptada_at    = CASE WHEN p_respuesta='aceptada'  THEN v_now ELSE aceptada_at END,
         rechazada_at   = CASE WHEN p_respuesta='rechazada' THEN v_now ELSE rechazada_at END,
         aceptada_por   = CASE WHEN p_respuesta='aceptada'  THEN 'cliente_portal_token'
                               WHEN p_respuesta='rechazada' THEN 'cliente_portal_token'
                               ELSE aceptada_por END,
         motivo_rechazo = CASE WHEN p_respuesta='rechazada' THEN v_motivo ELSE motivo_rechazo END,
         updated_at = v_now
   WHERE id = v_proforma.id
     AND estado_cliente = 'pendiente';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Esta proforma ya fue respondida por otra solicitud concurrente.';
  END IF;
  IF p_respuesta = 'rechazada' THEN
    v_liberados := public.liberar_conceptos_de_proforma(v_proforma.id);
  END IF;
  -- fix3: usuario sentinel en vez de NULL — bitacora_actividad.usuario_id es
  -- NOT NULL (20260301200638). Mismo patrón que otras escrituras de sistema
  -- ('00000000-…', ver 20260717025858).
  INSERT INTO public.bitacora_actividad (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
  VALUES (v_proforma.organization_id, '00000000-0000-0000-0000-000000000000'::uuid, 'cliente-portal-token',
          CASE WHEN p_respuesta='aceptada' THEN 'proforma_aceptada_cliente' ELSE 'proforma_rechazada_cliente' END,
          'proformas', v_proforma.id, COALESCE(v_proforma.numero,''),
          jsonb_build_object('proforma_id', v_proforma.id, 'numero', v_proforma.numero,
                             'cliente_id', v_proforma.cliente_id, 'cliente_nombre', v_proforma.cliente_nombre,
                             'respuesta', p_respuesta, 'motivo', v_motivo,
                             'conceptos_liberados', v_liberados,
                             'origen','portal_token'));
  v_tipo := CASE WHEN p_respuesta='aceptada' THEN 'proforma_aceptada' ELSE 'proforma_rechazada' END;
  v_titulo := 'Proforma ' || COALESCE(v_proforma.numero,'') || ' ' ||
              CASE WHEN p_respuesta='aceptada' THEN 'aceptada por el cliente' ELSE 'rechazada por el cliente' END;
  v_mensaje := 'Cliente: ' || COALESCE(v_proforma.cliente_nombre,'N/D') ||
               CASE WHEN v_motivo IS NOT NULL THEN E'\nMotivo: ' || v_motivo ELSE '' END ||
               CASE WHEN p_respuesta='rechazada' AND v_liberados > 0
                    THEN E'\nSe liberaron ' || v_liberados || ' concepto(s) para regenerar la proforma.'
                    ELSE '' END;
  INSERT INTO public.notificaciones_internas (organization_id, usuario_id, tipo, titulo, mensaje, enlace, entidad_tipo, entidad_id)
  SELECT v_proforma.organization_id, om.user_id, v_tipo, v_titulo, v_mensaje,
         '/proformas/' || v_proforma.id::text, 'proforma', v_proforma.id
    FROM public.organization_members om
   WHERE om.organization_id = v_proforma.organization_id
     AND om.role IN ('admin'::app_role, 'admin_org'::app_role, 'operador'::app_role, 'contador'::app_role);
  RETURN jsonb_build_object(
    'id', v_proforma.id,
    'estado_cliente', p_respuesta,
    'respondida_at', v_now,
    'conceptos_liberados', v_liberados
  );
END $$;
CREATE FUNCTION public.portal_responder_proforma(p_proforma_id uuid, p_respuesta text, p_motivo text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_proforma public.proformas%ROWTYPE;
  v_user_email text;
  v_now timestamptz := now();
  v_motivo text;
  v_titulo text; v_mensaje text; v_tipo text;
BEGIN
  IF p_respuesta NOT IN ('aceptada','rechazada') THEN
    RAISE EXCEPTION 'Respuesta inválida. Debe ser aceptada o rechazada.';
  END IF;
  SELECT * INTO v_proforma FROM public.proformas
   WHERE id = p_proforma_id AND cliente_id IN (SELECT current_user_client_ids());
  IF NOT FOUND THEN RAISE EXCEPTION 'Proforma no encontrada o no tienes acceso.'; END IF;
  IF v_proforma.estado_cliente <> 'pendiente' THEN
    RAISE EXCEPTION 'Esta proforma ya fue respondida (estado: %).', v_proforma.estado_cliente;
  END IF;
  v_motivo := NULLIF(trim(p_motivo), '');
  IF p_respuesta = 'rechazada' AND v_motivo IS NULL THEN
    RAISE EXCEPTION 'Es obligatorio indicar el motivo de rechazo.';
  END IF;
  SELECT email INTO v_user_email FROM auth.users WHERE id = auth.uid();
  UPDATE public.proformas
     SET estado_cliente = p_respuesta,
         aceptada_at    = CASE WHEN p_respuesta='aceptada'  THEN v_now ELSE aceptada_at END,
         rechazada_at   = CASE WHEN p_respuesta='rechazada' THEN v_now ELSE rechazada_at END,
         aceptada_por   = CASE WHEN p_respuesta='aceptada'  THEN COALESCE(v_user_email, auth.uid()::text) ELSE aceptada_por END,
         motivo_rechazo = CASE WHEN p_respuesta='rechazada' THEN v_motivo ELSE motivo_rechazo END,
         updated_at = v_now
   WHERE id = p_proforma_id;
  INSERT INTO public.bitacora_actividad (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
  VALUES (v_proforma.organization_id, auth.uid(), COALESCE(v_user_email,''),
          CASE WHEN p_respuesta='aceptada' THEN 'proforma_aceptada_cliente' ELSE 'proforma_rechazada_cliente' END,
          'proformas', p_proforma_id, COALESCE(v_proforma.numero,''),
          jsonb_build_object('proforma_id', p_proforma_id, 'numero', v_proforma.numero,
                             'cliente_id', v_proforma.cliente_id, 'cliente_nombre', v_proforma.cliente_nombre,
                             'respuesta', p_respuesta, 'motivo', v_motivo, 'origen','portal_cliente'));
  v_tipo := CASE WHEN p_respuesta='aceptada' THEN 'proforma_aceptada' ELSE 'proforma_rechazada' END;
  v_titulo := 'Proforma ' || COALESCE(v_proforma.numero,'') || ' ' ||
              CASE WHEN p_respuesta='aceptada' THEN 'aceptada por el cliente' ELSE 'rechazada por el cliente' END;
  v_mensaje := 'Cliente: ' || COALESCE(v_proforma.cliente_nombre,'N/D') ||
               CASE WHEN v_motivo IS NOT NULL THEN E'\nMotivo: ' || v_motivo ELSE '' END;
  INSERT INTO public.notificaciones_internas (organization_id, usuario_id, tipo, titulo, mensaje, enlace, entidad_tipo, entidad_id)
  SELECT v_proforma.organization_id, om.user_id, v_tipo, v_titulo, v_mensaje,
         '/proformas/' || p_proforma_id::text, 'proforma', p_proforma_id
    FROM public.organization_members om
   WHERE om.organization_id = v_proforma.organization_id
     AND om.role IN ('admin'::app_role, 'admin_org'::app_role, 'operador'::app_role, 'contador'::app_role);
  RETURN jsonb_build_object('id', p_proforma_id, 'estado_cliente', p_respuesta, 'respondida_at', v_now);
END $$;
CREATE FUNCTION public.portal_solicitar_cotizacion(p_cliente_id uuid, p_modo public.modo_transporte, p_tipo public.tipo_operacion, p_origen text, p_destino text, p_tipo_embarque text DEFAULT 'FCL'::text, p_tipo_contenedor text DEFAULT NULL::text, p_descripcion_mercancia text DEFAULT ''::text, p_notas text DEFAULT NULL::text) RETURNS TABLE(id uuid, folio text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_cliente_nombre text;
  v_num bigint;
  v_anio text := to_char(now() AT TIME ZONE 'America/Mexico_City', 'YYYY');
  v_folio text;
  v_id uuid;
  v_rl jsonb;
  -- fix3: caps de longitud (antes text sin límite).
  v_origen text := LEFT(btrim(COALESCE(p_origen, '')), 200);
  v_destino text := LEFT(btrim(COALESCE(p_destino, '')), 200);
  v_descripcion text := LEFT(COALESCE(p_descripcion_mercancia, ''), 2000);
  v_notas text := NULLIF(LEFT(btrim(COALESCE(p_notas, '')), 2000), '');
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'LC_NO_AUTENTICADO: sesión requerida';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.client_users cu
    WHERE cu.user_id = auth.uid() AND cu.cliente_id = p_cliente_id
  ) THEN
    RAISE EXCEPTION 'LC_CLIENTE_NO_VINCULADO: el usuario no pertenece a este cliente';
  END IF;
  -- fix3: rate limit por (cliente, usuario) — 10 solicitudes/hora.
  v_rl := public.check_ratelimit(
    'rpc:portal_solicitar_cotizacion:' || p_cliente_id::text || ':' || auth.uid()::text,
    3600, 10
  );
  IF (v_rl->>'ok') = 'false' THEN
    RAISE EXCEPTION 'Demasiadas solicitudes. Intenta de nuevo en % segundos.', COALESCE(v_rl->>'retry_after', '60')
      USING ERRCODE = 'P0001';
  END IF;
  IF v_origen = '' OR v_destino = '' THEN
    RAISE EXCEPTION 'LC_RUTA_REQUERIDA: origen y destino son obligatorios';
  END IF;
  SELECT c.organization_id, c.nombre INTO v_org, v_cliente_nombre
  FROM public.clientes c WHERE c.id = p_cliente_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_NO_RESUELTA: no se pudo determinar la organización';
  END IF;
  INSERT INTO public.folio_secuencias (organization_id, tipo, ultimo_numero)
  VALUES (v_org, 'cotizacion_' || v_anio, 1)
  ON CONFLICT (organization_id, tipo)
  DO UPDATE SET ultimo_numero = folio_secuencias.ultimo_numero + 1,
                updated_at = now()
  RETURNING ultimo_numero INTO v_num;
  v_folio := 'COT-' || v_anio || '-' || lpad(v_num::text, 4, '0');
  INSERT INTO public.cotizaciones (
    organization_id, folio, cliente_id, cliente_nombre, modo, tipo,
    origen, destino, tipo_embarque, tipo_contenedor,
    descripcion_mercancia, estado, notas, origen_portal
  ) VALUES (
    v_org, v_folio, p_cliente_id, coalesce(v_cliente_nombre, ''), p_modo, p_tipo,
    v_origen, v_destino, coalesce(nullif(LEFT(btrim(COALESCE(p_tipo_embarque, '')), 50), ''), 'FCL'),
    nullif(LEFT(btrim(coalesce(p_tipo_contenedor, '')), 100), ''),
    v_descripcion, 'Solicitada',
    '[Solicitud desde portal del cliente]' ||
      CASE WHEN v_notas IS NULL THEN '' ELSE E'\n' || v_notas END,
    true
  )
  RETURNING cotizaciones.id INTO v_id;
  RETURN QUERY SELECT v_id, v_folio;
END;
$$;
CREATE FUNCTION public.portal_update_contacto(_nombre text, _telefono text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  IF NOT public.has_role(_uid, 'cliente'::app_role) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;
  IF _nombre IS NULL OR length(btrim(_nombre)) = 0 OR length(_nombre) > 100 THEN
    RAISE EXCEPTION 'Nombre inválido';
  END IF;
  IF _telefono IS NOT NULL AND length(_telefono) > 30 THEN
    RAISE EXCEPTION 'Teléfono inválido';
  END IF;
  UPDATE public.clientes
     SET contacto = btrim(_nombre),
         telefono = COALESCE(btrim(_telefono), ''),
         updated_at = now()
   WHERE id IN (SELECT public.current_user_client_ids())
     AND deleted_at IS NULL;
END;
$$;
CREATE FUNCTION public.profit_por_cliente(_fecha_desde date DEFAULT NULL::date, _fecha_hasta date DEFAULT NULL::date, _modo text DEFAULT NULL::text) RETURNS TABLE(cliente_id uuid, cliente_nombre text, total_embarques bigint, venta_usd numeric, costo_usd numeric, venta_mxn numeric, costo_mxn numeric, embarques_sin_tc bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT
      e.id,
      e.cliente_id,
      e.cliente_nombre,
      COALESCE(
        NULLIF(e.tipo_cambio_usd, 0),
        (SELECT d.usd_mxn FROM public.tc_dof_vigente(COALESCE(e.eta, e.etd, e.created_at::date)) d)
      ) AS tc_usd,
      COALESCE(
        NULLIF(e.tipo_cambio_eur, 0),
        (SELECT d.eur_mxn FROM public.tc_dof_vigente(COALESCE(e.eta, e.etd, e.created_at::date)) d)
      ) AS tc_eur
    FROM public.embarques e
    WHERE e.deleted_at IS NULL
      AND (_fecha_desde IS NULL OR e.eta >= _fecha_desde)
      AND (_fecha_hasta IS NULL OR e.eta <= _fecha_hasta)
      AND (_modo IS NULL OR e.modo::text = _modo)
      AND (e.organization_id = public.org_scope())
  ),
  ventas AS (
    SELECT
      cv.embarque_id,
      SUM(public.a_mxn(cv.total, cv.moneda::text, b.tc_usd, b.tc_eur)) AS venta_mxn,
      COUNT(*) FILTER (
        WHERE public.a_mxn(cv.total, cv.moneda::text, b.tc_usd, b.tc_eur) IS NULL
      ) AS venta_sin_tc
    FROM public.conceptos_venta cv
    JOIN base b ON b.id = cv.embarque_id
    WHERE cv.deleted_at IS NULL
    GROUP BY cv.embarque_id
  ),
  -- M1 residual: notas de crédito aplicadas por embarque, convertidas a MXN
  -- con el mismo TC resuelto del embarque. Canon único:
  -- nc_aplicadas_en_moneda_factura (delegación a _nc_aplicadas_moneda_factura).
  ncs AS (
    SELECT
      fe.embarque_id,
      SUM(
        COALESCE(
          public.a_mxn(
            public.nc_aplicadas_en_moneda_factura(f.id),
            f.moneda::text, b.tc_usd, b.tc_eur
          ), 0)
      ) AS nc_mxn
    FROM public.factura_embarques fe
    JOIN base b ON b.id = fe.embarque_id
    JOIN public.facturas f ON f.id = fe.factura_id
    WHERE fe.activa IS TRUE
      AND f.deleted_at IS NULL
      AND f.estado <> 'Cancelada'::estado_factura
    GROUP BY fe.embarque_id
  ),
  costos AS (
    SELECT
      cc.embarque_id,
      SUM(public.a_mxn(cc.monto, cc.moneda::text, b.tc_usd, b.tc_eur)) AS costo_mxn,
      COUNT(*) FILTER (
        WHERE public.a_mxn(cc.monto, cc.moneda::text, b.tc_usd, b.tc_eur) IS NULL
      ) AS costo_sin_tc
    FROM public.conceptos_costo cc
    JOIN base b ON b.id = cc.embarque_id
    WHERE cc.deleted_at IS NULL
    GROUP BY cc.embarque_id
  ),
  neto AS (
    SELECT
      b.id,
      b.cliente_id,
      b.cliente_nombre,
      b.tc_usd,
      GREATEST(COALESCE(v.venta_mxn, 0) - COALESCE(nc.nc_mxn, 0), 0) AS venta_mxn,
      COALESCE(c.costo_mxn, 0) AS costo_mxn,
      COALESCE(v.venta_sin_tc, 0) AS venta_sin_tc,
      COALESCE(c.costo_sin_tc, 0) AS costo_sin_tc
    FROM base b
    LEFT JOIN ventas v ON v.embarque_id = b.id
    LEFT JOIN costos c ON c.embarque_id = b.id
    LEFT JOIN ncs   nc ON nc.embarque_id = b.id
  )
  SELECT
    n.cliente_id,
    MAX(n.cliente_nombre) AS cliente_nombre,
    COUNT(DISTINCT n.id) AS total_embarques,
    COALESCE(SUM(
      CASE WHEN COALESCE(n.tc_usd, 0) > 0
        THEN round(n.venta_mxn / n.tc_usd, 4) END
    ), 0) AS venta_usd,
    COALESCE(SUM(
      CASE WHEN COALESCE(n.tc_usd, 0) > 0
        THEN round(n.costo_mxn / n.tc_usd, 4) END
    ), 0) AS costo_usd,
    COALESCE(SUM(n.venta_mxn), 0) AS venta_mxn,
    COALESCE(SUM(n.costo_mxn), 0) AS costo_mxn,
    COUNT(DISTINCT n.id) FILTER (
      WHERE COALESCE(n.tc_usd, 0) <= 0
         OR n.venta_sin_tc > 0
         OR n.costo_sin_tc > 0
    ) AS embarques_sin_tc
  FROM neto n
  GROUP BY n.cliente_id;
$$;
CREATE FUNCTION public.profit_por_embarque() RETURNS TABLE(embarque_id uuid, venta_mxn numeric, costo_mxn numeric, venta_mxn_from_usd numeric, costo_mxn_from_usd numeric, venta_mxn_from_eur numeric, costo_mxn_from_eur numeric, venta_mxn_native numeric, costo_mxn_native numeric, venta_usd numeric, costo_usd numeric, tipo_cambio_usd numeric, tipo_cambio_eur numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH orgs AS (
    SELECT current_user_org_id() AS org,
           has_role(auth.uid(), 'super_admin'::app_role) AS is_super
  ),
  ventas AS (
    SELECT
      cv.embarque_id,
      SUM(CASE WHEN cv.moneda = 'USD' THEN cv.total ELSE 0 END) AS venta_usd_raw,
      SUM(CASE WHEN cv.moneda = 'EUR' THEN cv.total ELSE 0 END) AS venta_eur_raw,
      SUM(CASE WHEN cv.moneda = 'MXN' THEN cv.total ELSE 0 END) AS venta_mxn_raw
    FROM conceptos_venta cv
    JOIN embarques e0 ON e0.id = cv.embarque_id
    CROSS JOIN orgs
    WHERE cv.deleted_at IS NULL
      AND (orgs.is_super OR e0.organization_id = orgs.org)
    GROUP BY cv.embarque_id
  ),
  costos AS (
    SELECT
      cc.embarque_id,
      SUM(CASE WHEN cc.moneda = 'USD' THEN cc.monto ELSE 0 END) AS costo_usd_raw,
      SUM(CASE WHEN cc.moneda = 'EUR' THEN cc.monto ELSE 0 END) AS costo_eur_raw,
      SUM(CASE WHEN cc.moneda = 'MXN' THEN cc.monto ELSE 0 END) AS costo_mxn_raw
    FROM conceptos_costo cc
    JOIN embarques e0 ON e0.id = cc.embarque_id
    CROSS JOIN orgs
    WHERE cc.deleted_at IS NULL
      AND (orgs.is_super OR e0.organization_id = orgs.org)
    GROUP BY cc.embarque_id
  )
  SELECT
    e.id AS embarque_id,
    COALESCE(v.venta_usd_raw, 0) * COALESCE(e.tipo_cambio_usd, 0)
      + COALESCE(v.venta_eur_raw, 0) * COALESCE(e.tipo_cambio_eur, 0)
      + COALESCE(v.venta_mxn_raw, 0) AS venta_mxn,
    COALESCE(c.costo_usd_raw, 0) * COALESCE(e.tipo_cambio_usd, 0)
      + COALESCE(c.costo_eur_raw, 0) * COALESCE(e.tipo_cambio_eur, 0)
      + COALESCE(c.costo_mxn_raw, 0) AS costo_mxn,
    COALESCE(v.venta_usd_raw, 0) * COALESCE(e.tipo_cambio_usd, 0) AS venta_mxn_from_usd,
    COALESCE(c.costo_usd_raw, 0) * COALESCE(e.tipo_cambio_usd, 0) AS costo_mxn_from_usd,
    COALESCE(v.venta_eur_raw, 0) * COALESCE(e.tipo_cambio_eur, 0) AS venta_mxn_from_eur,
    COALESCE(c.costo_eur_raw, 0) * COALESCE(e.tipo_cambio_eur, 0) AS costo_mxn_from_eur,
    COALESCE(v.venta_mxn_raw, 0) AS venta_mxn_native,
    COALESCE(c.costo_mxn_raw, 0) AS costo_mxn_native,
    COALESCE(v.venta_usd_raw, 0) AS venta_usd,
    COALESCE(c.costo_usd_raw, 0) AS costo_usd,
    COALESCE(e.tipo_cambio_usd, 0) AS tipo_cambio_usd,
    COALESCE(e.tipo_cambio_eur, 0) AS tipo_cambio_eur
  FROM embarques e
  LEFT JOIN ventas v ON v.embarque_id = e.id
  LEFT JOIN costos c ON c.embarque_id = e.id
  WHERE e.deleted_at IS NULL
    AND (e.organization_id = public.org_scope())
    AND (
      COALESCE(v.venta_usd_raw, 0) > 0 OR COALESCE(v.venta_eur_raw, 0) > 0 OR COALESCE(v.venta_mxn_raw, 0) > 0
      OR COALESCE(c.costo_usd_raw, 0) > 0 OR COALESCE(c.costo_eur_raw, 0) > 0 OR COALESCE(c.costo_mxn_raw, 0) > 0
    );
$$;
CREATE FUNCTION public.promover_embarque_por_liquidar(p_embarque_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado text;
  v_org_id uuid;
BEGIN
  SELECT estado::text, organization_id INTO v_estado, v_org_id
    FROM embarques WHERE id = p_embarque_id;
  IF v_estado IS DISTINCT FROM 'EIR' THEN RETURN false; END IF;
  IF NOT public.embarque_operativo_completo(p_embarque_id) THEN RETURN false; END IF;
  UPDATE embarques
     SET estado = 'Por liquidar'::estado_embarque, updated_at = now()
   WHERE id = p_embarque_id;
  INSERT INTO notas_embarque (embarque_id, contenido, tipo, usuario, organization_id)
  VALUES (p_embarque_id,
          'Operación terminada: el embarque pasó automáticamente a "Por liquidar". Falta cobrar al cliente y/o pagar al proveedor.',
          'cambio_estado'::tipo_nota, 'sistema', v_org_id);
  RETURN true;
END;
$$;
CREATE FUNCTION public.proveedor_estado_cuenta(p_proveedor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_oid uuid := public.current_user_org_id();
  v_partidas jsonb;
  v_huerfanas jsonb;
  -- Ola 12 · R3BD-06: TC DOF vigente (patrón proveedor_inteligencia).
  v_usd numeric;
  v_eur numeric;
BEGIN
  IF v_oid IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_SIN_CONTEXTO: no hay organización activa' USING ERRCODE = '42501';
  END IF;
  SELECT t.usd_mxn, t.eur_mxn INTO v_usd, v_eur FROM public.tc_dof_vigente(CURRENT_DATE) t;
  WITH cc AS (
    SELECT c.id, c.concepto, c.monto, c.moneda::text AS moneda,
           c.estado_liquidacion::text AS estado_liquidacion,
           c.fecha_vencimiento, c.created_at,
           e.id AS embarque_id, e.expediente, e.cliente_nombre
    FROM public.conceptos_costo c
    LEFT JOIN public.embarques e ON e.id = c.embarque_id AND e.deleted_at IS NULL
    WHERE c.proveedor_id = p_proveedor_id
      AND c.organization_id = v_oid
      AND c.deleted_at IS NULL
  ),
  pfc_conv AS (
    SELECT pfc.concepto_costo_id,
           pfc.monto,
           pf.id AS factura_id, pf.folio_interno, pf.folio_proveedor,
           pf.estado::text AS estado, pf.estado_aprobacion::text AS estado_aprobacion,
           pf.fecha_emision, pf.fecha_vencimiento, pf.moneda::text AS moneda,
           pf.total,
           cc2.moneda::text AS moneda_concepto,
           CASE pf.moneda::text
             WHEN 'MXN' THEN 1::numeric
             WHEN 'USD' THEN COALESCE(NULLIF(pf.tipo_cambio_usd, 0), v_usd)
             WHEN 'EUR' THEN v_eur
             ELSE NULL
           END AS tc_factura,
           CASE cc2.moneda::text
             WHEN 'MXN' THEN 1::numeric
             WHEN 'USD' THEN v_usd
             WHEN 'EUR' THEN v_eur
             ELSE NULL
           END AS tc_concepto
    FROM public.proveedor_facturas_conceptos pfc
    JOIN public.proveedor_facturas pf ON pf.id = pfc.proveedor_factura_id
    JOIN public.conceptos_costo cc2
      ON cc2.id = pfc.concepto_costo_id AND cc2.deleted_at IS NULL
    WHERE pf.proveedor_id = p_proveedor_id
      AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL
      AND pf.estado <> 'Cancelada'
  ),
  fact AS (
    SELECT c.concepto_costo_id,
           SUM(CASE
                 WHEN c.moneda = c.moneda_concepto THEN c.monto
                 WHEN c.tc_factura IS NOT NULL AND c.tc_concepto IS NOT NULL
                      AND c.tc_concepto > 0
                   THEN c.monto * c.tc_factura / c.tc_concepto
                 ELSE NULL
               END) AS monto_facturado,
           COALESCE(bool_or(
             c.moneda <> c.moneda_concepto
             AND (c.tc_factura IS NULL OR c.tc_concepto IS NULL OR c.tc_concepto <= 0)
           ), false) AS moneda_mixta_sin_tc,
           SUM(CASE
                 WHEN c.moneda <> c.moneda_concepto
                      AND (c.tc_factura IS NULL OR c.tc_concepto IS NULL OR c.tc_concepto <= 0)
                 THEN c.monto
               END) AS monto_sin_tc,
           jsonb_agg(DISTINCT jsonb_build_object(
             'factura_id', c.factura_id,
             'folio_interno', c.folio_interno,
             'folio_proveedor', c.folio_proveedor,
             'estado', c.estado,
             'estado_aprobacion', c.estado_aprobacion,
             'fecha_emision', c.fecha_emision,
             'fecha_vencimiento', c.fecha_vencimiento,
             'moneda', c.moneda,
             'total', c.total
           )) AS facturas
    FROM pfc_conv c
    GROUP BY c.concepto_costo_id
  ),
  pagos_por_factura AS (
    -- Ola 12 · R3P-01: pagos convertidos a la moneda de la factura con el TC
    -- del pago; los cross-moneda sin TC quedan fuera (SUM ignora NULL).
    SELECT pp.proveedor_factura_id,
           SUM(public.monto_pago_en_moneda_factura(pp.monto, pp.moneda::text, pp.tipo_cambio_usd, pf.moneda::text)) AS pagado
    FROM public.pagos_proveedor pp
    JOIN public.proveedor_facturas pf ON pf.id = pp.proveedor_factura_id
    WHERE pf.proveedor_id = p_proveedor_id
      AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL
      AND pf.estado <> 'Cancelada'
      AND pp.deleted_at IS NULL
    GROUP BY pp.proveedor_factura_id
  ),
  pag AS (
    SELECT pfc.concepto_costo_id,
           SUM(
             COALESCE(ppf.pagado, 0)
             * CASE
                 WHEN COALESCE(pf.subtotal, 0) > 0
                   THEN LEAST(COALESCE(pfc.monto, 0) / pf.subtotal, 1)
                 WHEN COALESCE(pf.total, 0) > 0
                   THEN LEAST(COALESCE(pfc.monto, 0) / pf.total, 1)
                 ELSE 0
               END
           ) AS pagado_factura
    FROM public.proveedor_facturas_conceptos pfc
    JOIN public.proveedor_facturas pf ON pf.id = pfc.proveedor_factura_id
    LEFT JOIN pagos_por_factura ppf ON ppf.proveedor_factura_id = pf.id
    WHERE pf.proveedor_id = p_proveedor_id
      AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL
      AND pf.estado <> 'Cancelada'
    GROUP BY pfc.concepto_costo_id
  )
  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_partidas
  FROM (
    SELECT cc.id AS concepto_costo_id,
           cc.embarque_id, COALESCE(cc.expediente,'') AS expediente,
           COALESCE(cc.cliente_nombre,'') AS cliente_nombre,
           cc.concepto, cc.monto AS comprometido, cc.moneda,
           cc.estado_liquidacion, cc.fecha_vencimiento, cc.created_at,
           COALESCE(f.monto_facturado, 0) AS facturado,
           COALESCE(f.facturas, '[]'::jsonb) AS facturas,
           ROUND(COALESCE(p.pagado_factura, 0), 2) AS pagado,
           CASE
             WHEN COALESCE(f.monto_facturado,0) <= 0 AND cc.estado_liquidacion = 'Pagado'
               THEN 0::numeric
             ELSE GREATEST(cc.monto - COALESCE(f.monto_facturado,0), 0)
           END AS por_facturar,
           COALESCE(f.moneda_mixta_sin_tc, false) AS moneda_mixta_sin_tc,
           ROUND(COALESCE(f.monto_sin_tc, 0), 2) AS monto_sin_tc,
           CASE
             WHEN COALESCE(f.monto_facturado,0) <= 0 AND cc.estado_liquidacion = 'Pagado' THEN 'Pagado'
             WHEN COALESCE(f.moneda_mixta_sin_tc, false) THEN 'Moneda mixta'
             WHEN COALESCE(f.monto_facturado,0) <= 0 THEN 'Por facturar'
             WHEN COALESCE(f.monto_facturado,0) > cc.monto * 1.01 THEN 'Sobrefacturado'
             WHEN COALESCE(f.monto_facturado,0) < cc.monto * 0.99 THEN 'Facturado parcial'
             WHEN cc.estado_liquidacion = 'Pagado' THEN 'Pagado'
             ELSE 'Facturado'
           END AS estado_conciliacion
    FROM cc
    LEFT JOIN fact f ON f.concepto_costo_id = cc.id
    LEFT JOIN pag p ON p.concepto_costo_id = cc.id
  ) t;
  SELECT COALESCE(jsonb_agg(row_to_json(h) ORDER BY h.fecha_emision DESC), '[]'::jsonb)
  INTO v_huerfanas
  FROM (
    SELECT pf.id AS factura_id, pf.folio_interno, pf.folio_proveedor,
           pf.fecha_emision, pf.moneda::text AS moneda,
           SUM(pfc.monto) AS monto_sin_vincular,
           COUNT(*) AS partidas
    FROM public.proveedor_facturas pf
    JOIN public.proveedor_facturas_conceptos pfc ON pfc.proveedor_factura_id = pf.id
    LEFT JOIN public.conceptos_costo cc
      ON cc.id = pfc.concepto_costo_id AND cc.deleted_at IS NULL
    WHERE pf.proveedor_id = p_proveedor_id
      AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL
      AND pf.estado <> 'Cancelada'
      AND cc.id IS NULL
    GROUP BY pf.id, pf.folio_interno, pf.folio_proveedor, pf.fecha_emision, pf.moneda
  ) h;
  RETURN jsonb_build_object(
    'partidas', v_partidas,
    'facturas_huerfanas', v_huerfanas
  );
END;
$$;
CREATE FUNCTION public.proveedor_estado_cuenta_movimientos(p_proveedor_id uuid, p_desde date DEFAULT NULL::date, p_hasta date DEFAULT NULL::date, p_limite integer DEFAULT 1000, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_oid uuid := public.current_user_org_id();
  v_todos jsonb;
  v_movs_full jsonb;
  v_movs jsonb;
  v_apertura jsonb;
  v_aging jsonb;
  v_saldos jsonb;
  v_total integer;
  v_offset_efectivo integer;
  v_desde date := COALESCE(p_desde, '1900-01-01'::date);
  v_hasta date := COALESCE(p_hasta, '2999-12-31'::date);
  -- Sprint 04 · R3FE-04: tope defensivo (nunca se devuelven > 5000).
  v_limite integer := LEAST(GREATEST(COALESCE(p_limite, 1000), 1), 5000);
  -- R3P-10: fecha de negocio en America/Mexico_City. Antes CURRENT_DATE usaba
  -- la fecha UTC del servidor: entre las 18:00-23:59 CDMX los buckets del
  -- aging se calculaban "mañana".
  v_hoy_mx date := (now() AT TIME ZONE 'America/Mexico_City')::date;
BEGIN
  IF v_oid IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_SIN_CONTEXTO: no hay organización activa' USING ERRCODE = '42501';
  END IF;
  -- Universo completo de movimientos del proveedor (SIN filtro de periodo):
  -- se materializa una sola vez y de él se derivan el detalle del periodo,
  -- la apertura (S08 · R3FE-03) y los saldos globales.
  WITH facturas AS (
    SELECT pf.id, pf.folio_interno, pf.folio_proveedor, pf.fecha_emision,
           pf.fecha_vencimiento, pf.moneda::text AS moneda, pf.total,
           pf.estado::text AS estado, pf.embarque_id, e.expediente
    FROM public.proveedor_facturas pf
    LEFT JOIN public.embarques e ON e.id = pf.embarque_id AND e.deleted_at IS NULL
    WHERE pf.proveedor_id = p_proveedor_id
      AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL
      AND pf.estado <> 'Cancelada'
  ),
  notas AS (
    -- R3P-08: sólo NC aplicadas descuentan el estado de cuenta (regla única).
    SELECT nc.id, nc.folio_nc, nc.fecha, nc.monto, nc.moneda::text AS moneda,
           nc.proveedor_factura_id, f.folio_interno, f.expediente, f.embarque_id
    FROM public.proveedor_notas_credito nc
    JOIN facturas f ON f.id = nc.proveedor_factura_id
    WHERE nc.organization_id = v_oid
      AND nc.deleted_at IS NULL
      AND nc.estado = 'Aplicada'
  ),
  pagos AS (
    -- Ola 12 · R3P-06: el abono se convierte a la moneda de la factura; NULL = sin TC.
    SELECT pp.id, pp.fecha_pago,
           pp.monto AS monto_pago, pp.moneda::text AS moneda_pago,
           public.monto_pago_en_moneda_factura(pp.monto, pp.moneda::text, pp.tipo_cambio_usd, f.moneda) AS monto_factura,
           f.moneda AS moneda_factura,
           pp.referencia, pp.metodo_pago, pp.es_anticipo_aplicado,
           pp.proveedor_factura_id, f.folio_interno, f.expediente, f.embarque_id
    FROM public.pagos_proveedor pp
    JOIN facturas f ON f.id = pp.proveedor_factura_id
    WHERE pp.organization_id = v_oid
      AND pp.deleted_at IS NULL
  ),
  anticipos AS (
    SELECT a.id, a.fecha_anticipo, a.monto, a.moneda::text AS moneda,
           a.referencia, a.metodo_pago, a.embarque_id, e.expediente
    FROM public.anticipos_proveedor a
    LEFT JOIN public.embarques e ON e.id = a.embarque_id AND e.deleted_at IS NULL
    WHERE a.proveedor_id = p_proveedor_id
      AND a.organization_id = v_oid
      AND a.deleted_at IS NULL
      AND a.estado <> 'Cancelado'
  ),
  movs AS (
    SELECT f.fecha_emision AS fecha, 'Factura'::text AS tipo, f.id AS ref_id,
           COALESCE(f.folio_interno, f.folio_proveedor, 'Sin folio') AS folio,
           f.folio_proveedor AS referencia, COALESCE(f.expediente, '') AS expediente,
           f.embarque_id, f.moneda, COALESCE(f.total, 0) AS cargo, 0::numeric AS abono,
           f.estado AS detalle
    FROM facturas f
    UNION ALL
    SELECT n.fecha, 'Nota de crédito', n.id,
           COALESCE(n.folio_nc, 'NC'), n.folio_interno, COALESCE(n.expediente, ''),
           n.embarque_id, n.moneda, 0::numeric, COALESCE(n.monto, 0), NULL::text
    FROM notas n
    UNION ALL
    SELECT p.fecha_pago,
           CASE WHEN p.es_anticipo_aplicado THEN 'Anticipo aplicado' ELSE 'Pago' END,
           p.id, COALESCE(p.folio_interno, 'Pago'), p.referencia,
           COALESCE(p.expediente, ''), p.embarque_id,
           -- R3P-06: el abono se expresa en la moneda del cargo (factura).
           p.moneda_factura AS moneda,
           0::numeric,
           -- R3P-07: la aplicación de un anticipo es informativa (0/0); el
           -- abono ya se contó en la fila "Anticipo" al entregarlo.
           CASE WHEN p.es_anticipo_aplicado THEN 0::numeric ELSE COALESCE(p.monto_factura, 0) END,
           CASE
             WHEN p.es_anticipo_aplicado
               THEN COALESCE(p.metodo_pago, '') || ' · anticipo ya contado al entregarse'
             WHEN p.moneda_pago <> p.moneda_factura AND p.monto_factura IS NULL
               THEN COALESCE(p.metodo_pago, '') || ' · pagado en ' || p.moneda_pago || ' SIN TC (excluido del saldo)'
             WHEN p.moneda_pago <> p.moneda_factura
               THEN COALESCE(p.metodo_pago, '') || ' · pagado en ' || p.moneda_pago
             ELSE p.metodo_pago
           END
    FROM pagos p
    UNION ALL
    SELECT a.fecha_anticipo, 'Anticipo', a.id, 'Anticipo', a.referencia,
           COALESCE(a.expediente, ''), a.embarque_id, a.moneda,
           -- R3P-07: el anticipo entregado ES un abono (dinero al proveedor).
           0::numeric, COALESCE(a.monto, 0), a.metodo_pago
    FROM anticipos a
  )
  SELECT COALESCE(jsonb_agg(row_to_json(m) ORDER BY m.fecha, m.tipo, m.folio), '[]'::jsonb)
  INTO v_todos
  FROM movs m;
  -- Detalle del periodo (R3P-09): el filtro se aplica sobre el universo
  -- completo, en memoria, ANTES de paginar (R3FE-04). (Las fechas son
  -- columnas `date`; el casteo desde jsonb es seguro.)
  SELECT COALESCE(jsonb_agg(m ORDER BY m->>'fecha', m->>'tipo', m->>'folio'), '[]'::jsonb)
  INTO v_movs_full
  FROM jsonb_array_elements(v_todos) m
  WHERE (m->>'fecha')::date BETWEEN v_desde AND v_hasta;
  -- Sprint 04 · R3FE-04: paginación server-side. La lista es cronológica
  -- ascendente y el saldo corrido se arma en cliente sobre lo devuelto, así
  -- que el recorte por omisión conserva los movimientos MÁS RECIENTES del
  -- periodo.
  v_total := COALESCE(jsonb_array_length(v_movs_full), 0);
  -- Ola 13 · R4BD-05: p_offset se cuenta DESDE EL FINAL. Antes se SUMABA a la
  -- ventana por omisión y los renglones viejos quedaban inalcanzables.
  v_offset_efectivo := GREATEST(v_total - v_limite - GREATEST(COALESCE(p_offset, 0), 0), 0);
  SELECT COALESCE(jsonb_agg(pag.value ORDER BY pag.ord), '[]'::jsonb)
  INTO v_movs
  FROM (
    SELECT t.value, t.ord
    FROM jsonb_array_elements(v_movs_full) WITH ORDINALITY AS t(value, ord)
    ORDER BY t.ord
    OFFSET v_offset_efectivo
    LIMIT v_limite
  ) pag;
  -- Ola 12 · R3FE-03: saldo de apertura por moneda = movimientos anteriores
  -- al periodo. Mismo universo (v_todos) ⇒ cuadra con el corrido y con los
  -- saldos globales.
  SELECT COALESCE(jsonb_agg(row_to_json(a) ORDER BY a.moneda), '[]'::jsonb)
  INTO v_apertura
  FROM (
    SELECT m->>'moneda' AS moneda,
           SUM((m->>'cargo')::numeric) - SUM((m->>'abono')::numeric) AS saldo
    FROM jsonb_array_elements(v_todos) m
    WHERE (m->>'fecha')::date < v_desde
      AND m->>'moneda' IS NOT NULL
    GROUP BY m->>'moneda'
  ) a;
  -- Aging global (sin filtro de periodo; R3P-10: fecha de corte CDMX).
  WITH facturas AS (
    SELECT pf.id, pf.folio_interno, pf.folio_proveedor, pf.fecha_vencimiento,
           pf.moneda::text AS moneda, COALESCE(pf.total, 0) AS total,
           -- Ola 12 · R3BD-04: se necesita el estado para la regla 'Pagada'.
           pf.estado::text AS estado
    FROM public.proveedor_facturas pf
    WHERE pf.proveedor_id = p_proveedor_id
      AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL
      AND pf.estado <> 'Cancelada'
  ),
  saldo_factura AS (
    SELECT f.id, f.moneda, f.fecha_vencimiento,
           -- Ola 12 · R3BD-04: factura marcada 'Pagada' (legacy, sin pagos
           -- capturados) => saldo 0. Misma regla que proveedor_inteligencia.
           CASE WHEN f.estado = 'Pagada' THEN 0::numeric
                ELSE f.total
                  -- R3P-06: pagos convertidos a la moneda de la factura.
                  - COALESCE((SELECT SUM(public.monto_pago_en_moneda_factura(pp.monto, pp.moneda::text, pp.tipo_cambio_usd, f.moneda))
                              FROM public.pagos_proveedor pp
                              WHERE pp.proveedor_factura_id = f.id AND pp.deleted_at IS NULL), 0)
                  -- R3P-08: sólo NC 'Aplicada' (regla única del módulo).
                  - COALESCE((SELECT SUM(nc.monto) FROM public.proveedor_notas_credito nc
                              WHERE nc.proveedor_factura_id = f.id AND nc.deleted_at IS NULL
                                AND nc.estado = 'Aplicada'), 0)
           END AS saldo
    FROM facturas f
  ),
  clasificado AS (
    SELECT s.moneda, s.saldo,
           CASE
             WHEN s.fecha_vencimiento IS NULL OR s.fecha_vencimiento >= v_hoy_mx THEN 'Vigente'
             WHEN v_hoy_mx - s.fecha_vencimiento <= 30 THEN '1-30'
             WHEN v_hoy_mx - s.fecha_vencimiento <= 60 THEN '31-60'
             WHEN v_hoy_mx - s.fecha_vencimiento <= 90 THEN '61-90'
             ELSE '90+'
           END AS bucket
    FROM saldo_factura s
    WHERE s.saldo > 0.01
  )
  SELECT COALESCE(jsonb_agg(row_to_json(a) ORDER BY a.moneda, a.bucket), '[]'::jsonb)
  INTO v_aging
  FROM (
    SELECT c.moneda, c.bucket, SUM(c.saldo) AS saldo, COUNT(*) AS conteo
    FROM clasificado c
    GROUP BY c.moneda, c.bucket
  ) a;
  -- Saldos GLOBALES por moneda (R3P-09): mismo universo que el aging
  -- (v_todos), no el periodo filtrado ni la página recortada. La UI los
  -- etiqueta "Saldo global" (Paso 2 del sprint).
  SELECT COALESCE(jsonb_agg(row_to_json(s) ORDER BY s.moneda), '[]'::jsonb)
  INTO v_saldos
  FROM (
    SELECT m->>'moneda' AS moneda,
           SUM((m->>'cargo')::numeric) AS cargos,
           SUM((m->>'abono')::numeric) AS abonos,
           SUM((m->>'cargo')::numeric) - SUM((m->>'abono')::numeric) AS saldo
    FROM jsonb_array_elements(v_todos) m
    WHERE m->>'moneda' IS NOT NULL
    GROUP BY m->>'moneda'
  ) s;
  RETURN jsonb_build_object(
    'movimientos', v_movs,
    'saldo_apertura', v_apertura,
    'aging', v_aging,
    'saldos', v_saldos,
    'total_movimientos', v_total,
    -- R4BD-05: hay renglones ANTERIORES a la ventana (más viejos por ver).
    -- Con p_offset=0 el valor es idéntico al de la versión anterior.
    'hay_mas', v_offset_efectivo > 0
  );
END;
$$;
CREATE FUNCTION public.proveedor_facturas_assert_folio_unico() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_folio_norm text;
BEGIN
  v_folio_norm := upper(btrim(COALESCE(NEW.folio_proveedor, '')));
  IF v_folio_norm = '' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE'
     AND v_folio_norm = upper(btrim(COALESCE(OLD.folio_proveedor, '')))
     AND NEW.proveedor_id IS NOT DISTINCT FROM OLD.proveedor_id
     AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id THEN
    RETURN NEW;
  END IF;
  -- Serializa altas/ediciones del mismo folio dentro de la org.
  PERFORM pg_advisory_xact_lock(
    hashtext(NEW.organization_id::text || ':' || NEW.proveedor_id::text || ':' || v_folio_norm));
  IF EXISTS (
    SELECT 1 FROM public.proveedor_facturas pf
    WHERE pf.organization_id = NEW.organization_id
      AND pf.proveedor_id IS NOT DISTINCT FROM NEW.proveedor_id
      AND upper(btrim(pf.folio_proveedor)) = v_folio_norm
      AND pf.deleted_at IS NULL
      AND pf.estado <> 'Cancelada'::public.estado_proveedor_factura
      AND pf.id IS DISTINCT FROM NEW.id
  ) THEN
    RAISE EXCEPTION 'LC_CXP_FOLIO_DUPLICADO: ya existe una factura viva del proveedor con el folio %', v_folio_norm
      USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END
$$;
CREATE FUNCTION public.proveedor_facturas_dedupe_folio() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.deleted_at IS NOT NULL OR NEW.estado = 'Cancelada' THEN
    RETURN NEW;
  END IF;
  IF NEW.folio_proveedor IS NULL OR NEW.proveedor_id IS NULL THEN
    RETURN NEW;
  END IF;
  -- En UPDATE sólo se valida si la llave natural cambió: así los duplicados
  -- históricos siguen editables (cambios de estado, pagos, etc.).
  IF TG_OP = 'UPDATE'
     AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id
     AND NEW.proveedor_id IS NOT DISTINCT FROM OLD.proveedor_id
     AND NEW.folio_proveedor IS NOT DISTINCT FROM OLD.folio_proveedor THEN
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtext(NEW.organization_id::text || '|' || NEW.proveedor_id::text || '|' || lower(NEW.folio_proveedor))
  );
  IF EXISTS (
    SELECT 1 FROM public.proveedor_facturas pf
    WHERE pf.organization_id = NEW.organization_id
      AND pf.proveedor_id = NEW.proveedor_id
      AND pf.folio_proveedor = NEW.folio_proveedor
      AND pf.deleted_at IS NULL
      AND pf.estado <> 'Cancelada'
      AND pf.id IS DISTINCT FROM NEW.id
  ) THEN
    RAISE EXCEPTION 'LC_CXP_FOLIO_DUPLICADO: ya existe una factura viva del mismo proveedor con el folio %', NEW.folio_proveedor
      USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.proveedor_facturas_set_fecha_vencimiento() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Escape hatch documentado: SET LOCAL app.pf_vencimiento_override = '1'
  -- respeta el vencimiento capturado a mano (negociaciones puntuales).
  IF COALESCE(current_setting('app.pf_vencimiento_override', true), '') = '1' THEN
    RETURN NEW;
  END IF;
  IF NEW.fecha_emision IS NOT NULL THEN
    NEW.fecha_vencimiento := NEW.fecha_emision + COALESCE(NEW.dias_credito, 0);
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.proveedor_inteligencia(p_proveedor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_oid uuid := public.current_user_org_id();
  v_usd numeric;
  v_eur numeric;
  v_tipo text;
  v_scorecard jsonb;
  v_tendencia jsonb;
  v_comparativo jsonb;
  v_alertas jsonb;
BEGIN
  IF v_oid IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_SIN_CONTEXTO: no hay organización activa' USING ERRCODE = '42501';
  END IF;
  SELECT t.usd_mxn, t.eur_mxn INTO v_usd, v_eur FROM public.tc_dof_vigente(CURRENT_DATE) t;
  SELECT p.tipo::text INTO v_tipo
  FROM public.proveedores p
  WHERE p.id = p_proveedor_id AND p.organization_id = v_oid AND p.deleted_at IS NULL;
  IF v_tipo IS NULL AND NOT EXISTS (
    SELECT 1 FROM public.proveedores p
    WHERE p.id = p_proveedor_id AND p.organization_id = v_oid AND p.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'LC_PROVEEDOR_INEXISTENTE: el proveedor no existe en tu organización' USING ERRCODE = '42501';
  END IF;
  WITH cc AS (
    SELECT c.id, c.concepto, c.monto, c.moneda::text AS moneda, c.created_at,
           c.monto * COALESCE(CASE c.moneda::text WHEN 'USD' THEN v_usd WHEN 'EUR' THEN v_eur ELSE 1 END, 0) AS monto_mxn,
           e.expediente,
           COALESCE(NULLIF(e.puerto_origen, ''), NULLIF(e.aeropuerto_origen, ''), NULLIF(e.ciudad_origen, ''), '—') AS origen,
           COALESCE(NULLIF(e.puerto_destino, ''), NULLIF(e.aeropuerto_destino, ''), NULLIF(e.ciudad_destino, ''), '—') AS destino
    FROM public.conceptos_costo c
    LEFT JOIN public.embarques e ON e.id = c.embarque_id
    WHERE c.proveedor_id = p_proveedor_id AND c.organization_id = v_oid AND c.deleted_at IS NULL
  ),
  fact AS (
    SELECT pfc.concepto_costo_id,
           SUM(pfc.monto) AS facturado,
           MIN(COALESCE(pf.fecha_emision, pf.created_at::date)) AS primera_emision,
           MIN(pf.moneda::text) AS moneda_factura
    FROM public.proveedor_facturas_conceptos pfc
    JOIN public.proveedor_facturas pf ON pf.id = pfc.proveedor_factura_id
    WHERE pf.proveedor_id = p_proveedor_id AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada'
      AND pfc.concepto_costo_id IS NOT NULL
    GROUP BY pfc.concepto_costo_id
  ),
  part AS (
    SELECT cc.*, f.facturado, f.primera_emision,
           COALESCE(f.facturado, 0) * COALESCE(CASE COALESCE(f.moneda_factura, cc.moneda) WHEN 'USD' THEN v_usd WHEN 'EUR' THEN v_eur ELSE 1 END, 0) AS facturado_mxn
    FROM cc LEFT JOIN fact f ON f.concepto_costo_id = cc.id
  ),
  facs AS (
    SELECT COUNT(*)::int AS n,
           SUM(pf.total * COALESCE(CASE pf.moneda::text WHEN 'USD' THEN v_usd WHEN 'EUR' THEN v_eur ELSE 1 END, 0)) AS total_mxn
    FROM public.proveedor_facturas pf
    WHERE pf.proveedor_id = p_proveedor_id AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada'
  ),
  tops AS (
    SELECT COALESCE(jsonb_agg(x ORDER BY (x->>'monto_mxn')::numeric DESC), '[]'::jsonb) AS top_conceptos
    FROM (
      SELECT jsonb_build_object('concepto', concepto, 'monto_mxn', ROUND(SUM(monto_mxn), 2), 'partidas', COUNT(*)::int) AS x,
             SUM(monto_mxn) AS ord
      FROM part GROUP BY concepto ORDER BY ord DESC LIMIT 5
    ) s
  ),
  rutas AS (
    SELECT COALESCE(jsonb_agg(x ORDER BY (x->>'monto_mxn')::numeric DESC), '[]'::jsonb) AS top_rutas
    FROM (
      SELECT jsonb_build_object('ruta', origen || ' → ' || destino, 'monto_mxn', ROUND(SUM(monto_mxn), 2),
                                'embarques', COUNT(DISTINCT expediente)::int) AS x,
             SUM(monto_mxn) AS ord
      FROM part WHERE expediente IS NOT NULL GROUP BY origen, destino ORDER BY ord DESC LIMIT 5
    ) s
  )
  SELECT jsonb_build_object(
    'partidas_total', (SELECT COUNT(*)::int FROM part),
    'partidas_facturadas', (SELECT COUNT(*)::int FROM part WHERE facturado IS NOT NULL),
    'comprometido_mxn', (SELECT ROUND(COALESCE(SUM(monto_mxn), 0), 2) FROM part),
    'facturado_mxn', (SELECT ROUND(COALESCE(SUM(facturado_mxn), 0), 2) FROM part WHERE facturado IS NOT NULL),
    'comprometido_ligado_mxn', (SELECT ROUND(COALESCE(SUM(monto_mxn), 0), 2) FROM part WHERE facturado IS NOT NULL),
    'dias_facturacion_prom', (
      SELECT ROUND(AVG(primera_emision - created_at::date)::numeric, 1)
      FROM part
      WHERE primera_emision IS NOT NULL
        AND primera_emision >= created_at::date
    ),
    'facturas_count', (SELECT n FROM facs),
    'ticket_promedio_mxn', (SELECT CASE WHEN n > 0 THEN ROUND(COALESCE(total_mxn, 0) / n, 2) ELSE NULL END FROM facs),
    'top_conceptos', (SELECT top_conceptos FROM tops),
    'top_rutas', (SELECT top_rutas FROM rutas)
  ) INTO v_scorecard;
  WITH meses AS (
    SELECT to_char(d, 'YYYY-MM') AS mes, d::date AS ini, (d + interval '1 month')::date AS fin
    FROM generate_series(date_trunc('month', CURRENT_DATE) - interval '11 months', date_trunc('month', CURRENT_DATE), interval '1 month') d
  ),
  comp AS (
    SELECT to_char(c.created_at, 'YYYY-MM') AS mes,
           SUM(c.monto * COALESCE(CASE c.moneda::text WHEN 'USD' THEN v_usd WHEN 'EUR' THEN v_eur ELSE 1 END, 0)) AS monto
    FROM public.conceptos_costo c
    WHERE c.proveedor_id = p_proveedor_id AND c.organization_id = v_oid AND c.deleted_at IS NULL
    GROUP BY 1
  ),
  fac AS (
    SELECT to_char(pf.fecha_emision, 'YYYY-MM') AS mes,
           SUM(pf.total * COALESCE(CASE pf.moneda::text WHEN 'USD' THEN v_usd WHEN 'EUR' THEN v_eur ELSE 1 END, 0)) AS monto
    FROM public.proveedor_facturas pf
    WHERE pf.proveedor_id = p_proveedor_id AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada'
    GROUP BY 1
  ),
  pag AS (
    SELECT to_char(pp.fecha_pago, 'YYYY-MM') AS mes,
           SUM(pp.monto * COALESCE(CASE pp.moneda::text WHEN 'USD' THEN v_usd WHEN 'EUR' THEN v_eur ELSE 1 END, 0)) AS monto
    FROM public.pagos_proveedor pp
    JOIN public.proveedor_facturas pf ON pf.id = pp.proveedor_factura_id
    WHERE pf.proveedor_id = p_proveedor_id AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada' AND pp.deleted_at IS NULL
    GROUP BY 1
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'mes', m.mes,
           'comprometido', ROUND(COALESCE(c.monto, 0), 2),
           'facturado', ROUND(COALESCE(f.monto, 0), 2),
           'pagado', ROUND(COALESCE(p.monto, 0), 2)
         ) ORDER BY m.mes), '[]'::jsonb)
  INTO v_tendencia
  FROM meses m
  LEFT JOIN comp c ON c.mes = m.mes
  LEFT JOIN fac f ON f.mes = m.mes
  LEFT JOIN pag p ON p.mes = m.mes;
  WITH base AS (
    SELECT lower(btrim(c.concepto)) AS concepto_norm,
           c.concepto,
           c.moneda::text AS moneda,
           c.proveedor_id,
           c.monto
    FROM public.conceptos_costo c
    JOIN public.proveedores p ON p.id = c.proveedor_id
    WHERE c.organization_id = v_oid AND c.deleted_at IS NULL
      AND c.created_at >= CURRENT_DATE - interval '12 months'
      AND c.monto > 0
      AND p.deleted_at IS NULL
      AND p.tipo::text IS NOT DISTINCT FROM v_tipo
  ),
  propios AS (
    SELECT concepto_norm, MIN(concepto) AS concepto, moneda,
           AVG(monto) AS unitario, COUNT(*)::int AS ops
    FROM base WHERE proveedor_id = p_proveedor_id
    GROUP BY concepto_norm, moneda
  ),
  otros AS (
    SELECT concepto_norm, moneda, AVG(monto) AS unitario, COUNT(*)::int AS ops,
           COUNT(DISTINCT proveedor_id)::int AS proveedores
    FROM base WHERE proveedor_id <> p_proveedor_id
    GROUP BY concepto_norm, moneda
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'concepto', pr.concepto,
           'moneda', pr.moneda,
           'unitario_propio', ROUND(pr.unitario, 2),
           'ops_propias', pr.ops,
           'unitario_otros', ROUND(o.unitario, 2),
           'ops_otros', o.ops,
           'proveedores_comparados', o.proveedores
         ) ORDER BY pr.ops DESC), '[]'::jsonb)
  INTO v_comparativo
  FROM propios pr
  JOIN otros o ON o.concepto_norm = pr.concepto_norm AND o.moneda = pr.moneda
  WHERE pr.ops >= 1;
  WITH cerrados_sin_factura AS (
    SELECT COUNT(*)::int AS n,
           ROUND(COALESCE(SUM(c.monto * COALESCE(CASE c.moneda::text WHEN 'USD' THEN v_usd WHEN 'EUR' THEN v_eur ELSE 1 END, 0)), 0), 2) AS monto_mxn
    FROM public.conceptos_costo c
    JOIN public.embarques e ON e.id = c.embarque_id
    WHERE c.proveedor_id = p_proveedor_id AND c.organization_id = v_oid AND c.deleted_at IS NULL
      AND e.estado IN ('Cerrado', 'Entregado', 'Por liquidar')
      AND NOT EXISTS (
        SELECT 1 FROM public.proveedor_facturas_conceptos pfc
        JOIN public.proveedor_facturas pf ON pf.id = pfc.proveedor_factura_id
        WHERE pfc.concepto_costo_id = c.id AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada'
      )
  ),
  saldos AS (
    -- R3P-15: pagos convertidos a la moneda de la factura con el TC del
    -- pago (sin TC => el pago NO se descuenta) y NC sólo 'Aplicada'.
    SELECT pf.id, pf.fecha_vencimiento,
           (pf.total - COALESCE((
             SELECT SUM(
               CASE
                 WHEN pp.moneda::text = pf.moneda::text THEN pp.monto
                 WHEN COALESCE(pp.tipo_cambio_usd, 0) <= 0 THEN 0
                 WHEN pp.moneda::text = 'MXN' THEN pp.monto / pp.tipo_cambio_usd
                 WHEN pf.moneda::text = 'MXN' THEN pp.monto * pp.tipo_cambio_usd
                 ELSE 0
               END
             )
             FROM public.pagos_proveedor pp
             WHERE pp.proveedor_factura_id = pf.id AND pp.deleted_at IS NULL
           ), 0)
           - COALESCE((
             SELECT SUM(nc.monto) FROM public.proveedor_notas_credito nc
             WHERE nc.proveedor_factura_id = pf.id AND nc.deleted_at IS NULL
               AND nc.estado = 'Aplicada'
           ), 0)) * COALESCE(CASE pf.moneda::text WHEN 'USD' THEN v_usd WHEN 'EUR' THEN v_eur ELSE 1 END, 0) AS saldo_mxn
    FROM public.proveedor_facturas pf
    WHERE pf.proveedor_id = p_proveedor_id AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL AND pf.estado NOT IN ('Cancelada', 'Pagada')
  ),
  docs AS (
    SELECT
      COUNT(*) FILTER (WHERE d.fecha_vencimiento < CURRENT_DATE)::int AS vencidos,
      COUNT(*) FILTER (WHERE d.fecha_vencimiento >= CURRENT_DATE AND d.fecha_vencimiento <= CURRENT_DATE + 30)::int AS por_vencer
    FROM public.proveedor_documentos d
    WHERE d.proveedor_id = p_proveedor_id AND d.organization_id = v_oid
      AND d.deleted_at IS NULL AND d.fecha_vencimiento IS NOT NULL
  ),
  banco AS (
    SELECT p.origen_proveedor::text AS origen,
           (COALESCE(NULLIF(btrim(p.banco), ''), NULL) IS NULL) AS sin_banco,
           (COALESCE(NULLIF(btrim(p.clabe), ''), NULL) IS NULL) AS sin_clabe,
           (COALESCE(NULLIF(btrim(p.swift_bic), ''), NULLIF(btrim(p.iban), ''), NULLIF(btrim(p.aba_routing), '')) IS NULL) AS sin_ruta_intl,
           (COALESCE(NULLIF(btrim(p.beneficiario), ''), NULL) IS NULL) AS sin_beneficiario
    FROM public.proveedores p
    WHERE p.id = p_proveedor_id AND p.organization_id = v_oid
  )
  SELECT jsonb_build_object(
    'cerrados_sin_factura', jsonb_build_object('count', (SELECT n FROM cerrados_sin_factura), 'monto_mxn', (SELECT monto_mxn FROM cerrados_sin_factura)),
    'facturas_por_vencer', jsonb_build_object(
      'count', (SELECT COUNT(*)::int FROM saldos WHERE saldo_mxn > 0.005 AND fecha_vencimiento BETWEEN CURRENT_DATE AND CURRENT_DATE + 7),
      'monto_mxn', (SELECT ROUND(COALESCE(SUM(saldo_mxn), 0), 2) FROM saldos WHERE saldo_mxn > 0.005 AND fecha_vencimiento BETWEEN CURRENT_DATE AND CURRENT_DATE + 7)
    ),
    'facturas_vencidas', jsonb_build_object(
      'count', (SELECT COUNT(*)::int FROM saldos WHERE saldo_mxn > 0.005 AND fecha_vencimiento < CURRENT_DATE),
      'monto_mxn', (SELECT ROUND(COALESCE(SUM(saldo_mxn), 0), 2) FROM saldos WHERE saldo_mxn > 0.005 AND fecha_vencimiento < CURRENT_DATE)
    ),
    'saldo_pendiente_mxn', (SELECT ROUND(COALESCE(SUM(saldo_mxn), 0), 2) FROM saldos WHERE saldo_mxn > 0.005),
    'bancarios_incompletos', (
      -- R3P-14: una sola fuente de verdad — NULL = Nacional hasta que se
      -- capture lo contrario (idéntico criterio en la UI).
      SELECT CASE WHEN COALESCE(b.origen, 'Nacional') = 'Extranjero' THEN (b.sin_ruta_intl OR b.sin_beneficiario)
                  ELSE (b.sin_banco OR b.sin_clabe) END
      FROM banco b
    ),
    'documentos_vencidos', (SELECT vencidos FROM docs),
    'documentos_por_vencer', (SELECT por_vencer FROM docs)
  ) INTO v_alertas;
  RETURN jsonb_build_object(
    'tc', jsonb_build_object('usd_mxn', v_usd, 'eur_mxn', v_eur, 'faltante', (v_usd IS NULL OR v_eur IS NULL)),
    'tipo_proveedor', v_tipo,
    'scorecard', COALESCE(v_scorecard, '{}'::jsonb),
    'tendencia', COALESCE(v_tendencia, '[]'::jsonb),
    'comparativo', COALESCE(v_comparativo, '[]'::jsonb),
    'alertas', COALESCE(v_alertas, '{}'::jsonb)
  );
END;
$$;
CREATE FUNCTION public.proveedor_salud(p_proveedor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_oid uuid := public.current_user_org_id();
  v_usd numeric;
  v_eur numeric;
  v_faltante boolean := false;
  v_facturas_12m integer;
  v_monto_12m numeric;
  v_saldo numeric;
  v_dias_promedio numeric;
  v_pct_a_tiempo numeric;
  v_nc_count integer;
  v_nc_monto numeric;
  v_embarques_activos integer;
  v_mensual jsonb;
BEGIN
  SELECT t.usd_mxn, t.eur_mxn INTO v_usd, v_eur FROM public.tc_dof_vigente(CURRENT_DATE) t;
  SELECT COUNT(*),
         COALESCE(SUM(public.a_mxn(total, moneda::text, v_usd, v_eur)), 0),
         BOOL_OR(moneda::text <> 'MXN' AND public.a_mxn(total, moneda::text, v_usd, v_eur) IS NULL)
  INTO v_facturas_12m, v_monto_12m, v_faltante
  FROM public.proveedor_facturas
  WHERE proveedor_id = p_proveedor_id AND organization_id = v_oid
    AND deleted_at IS NULL AND estado <> 'Cancelada'
    AND fecha_emision >= (CURRENT_DATE - INTERVAL '12 months');
  -- Saldo: el saldo de cada factura se calcula en SU moneda (R3P-01) y luego
  -- se valúa a MXN; así no se mezclan divisas en la resta.
  WITH saldos AS (
    SELECT pf.moneda::text AS moneda,
           GREATEST(
             COALESCE(pf.total, 0)
             - COALESCE((SELECT SUM(public.monto_pago_en_moneda_factura(pp.monto, pp.moneda::text, pp.tipo_cambio_usd, pf.moneda::text))
                         FROM public.pagos_proveedor pp
                         WHERE pp.proveedor_factura_id = pf.id AND pp.deleted_at IS NULL), 0)
             - COALESCE((SELECT SUM(nc.monto) FROM public.proveedor_notas_credito nc
                         WHERE nc.proveedor_factura_id = pf.id AND nc.deleted_at IS NULL
                           AND nc.estado = 'Aplicada'), 0)
           , 0) AS saldo
    FROM public.proveedor_facturas pf
    WHERE pf.proveedor_id = p_proveedor_id AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada'
  )
  SELECT COALESCE(SUM(public.a_mxn(saldo, moneda, v_usd, v_eur)), 0),
         v_faltante OR COALESCE(BOOL_OR(moneda <> 'MXN' AND public.a_mxn(saldo, moneda, v_usd, v_eur) IS NULL), false)
  INTO v_saldo, v_faltante
  FROM saldos;
  WITH pagos_x_fact AS (
    SELECT pf.id, pf.fecha_emision, MAX(pp.fecha_pago) AS fecha_ultimo_pago,
           pf.fecha_vencimiento,
           SUM(public.monto_pago_en_moneda_factura(pp.monto, pp.moneda::text, pp.tipo_cambio_usd, pf.moneda::text)) AS pagado,
           pf.total
    FROM public.proveedor_facturas pf
    JOIN public.pagos_proveedor pp ON pp.proveedor_factura_id = pf.id AND pp.deleted_at IS NULL
    WHERE pf.proveedor_id = p_proveedor_id AND pf.organization_id = v_oid
      AND pf.deleted_at IS NULL
    GROUP BY pf.id, pf.fecha_emision, pf.fecha_vencimiento, pf.total
    HAVING SUM(public.monto_pago_en_moneda_factura(pp.monto, pp.moneda::text, pp.tipo_cambio_usd, pf.moneda::text)) >= pf.total - 0.01
  )
  SELECT
    AVG(fecha_ultimo_pago - fecha_emision)::numeric,
    CASE WHEN COUNT(*)=0 THEN NULL
         ELSE 100.0 * SUM(CASE WHEN fecha_vencimiento IS NULL OR fecha_ultimo_pago <= fecha_vencimiento THEN 1 ELSE 0 END) / COUNT(*) END
  INTO v_dias_promedio, v_pct_a_tiempo FROM pagos_x_fact;
  SELECT COUNT(*),
         COALESCE(SUM(public.a_mxn(nc.monto, nc.moneda::text, v_usd, v_eur)), 0),
         v_faltante OR COALESCE(BOOL_OR(nc.moneda::text <> 'MXN' AND public.a_mxn(nc.monto, nc.moneda::text, v_usd, v_eur) IS NULL), false)
  INTO v_nc_count, v_nc_monto, v_faltante
  FROM public.proveedor_notas_credito nc
  JOIN public.proveedor_facturas pf ON pf.id = nc.proveedor_factura_id
  WHERE pf.proveedor_id = p_proveedor_id AND pf.organization_id = v_oid
    AND nc.estado <> 'Cancelada';
  SELECT COUNT(DISTINCT e.id) INTO v_embarques_activos
  FROM public.embarques e
  WHERE e.organization_id = v_oid
    AND (e.naviera_id = p_proveedor_id OR e.agente_id = p_proveedor_id)
    AND COALESCE(e.estado::text,'') NOT IN ('Entregado','Cancelado','Cerrado');
  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY mes), '[]'::jsonb)
  INTO v_mensual
  FROM (
    SELECT to_char(date_trunc('month', fecha_emision), 'YYYY-MM') AS mes,
           SUM(public.a_mxn(total, moneda::text, v_usd, v_eur)) AS monto,
           COUNT(*) AS facturas
    FROM public.proveedor_facturas
    WHERE proveedor_id = p_proveedor_id AND organization_id = v_oid
      AND deleted_at IS NULL AND estado <> 'Cancelada'
      AND fecha_emision >= (CURRENT_DATE - INTERVAL '12 months')
    GROUP BY 1
  ) t;
  RETURN jsonb_build_object(
    'facturas_12m', v_facturas_12m,
    'monto_12m', ROUND(COALESCE(v_monto_12m, 0), 2),
    'saldo_actual', ROUND(COALESCE(v_saldo, 0), 2),
    'dias_promedio_pago', v_dias_promedio,
    'pct_pagadas_a_tiempo', v_pct_a_tiempo,
    'notas_credito_count', v_nc_count,
    'notas_credito_monto', ROUND(COALESCE(v_nc_monto, 0), 2),
    'embarques_activos', v_embarques_activos,
    'mensual', v_mensual,
    'moneda', 'MXN',
    'tc', jsonb_build_object('usd_mxn', v_usd, 'eur_mxn', v_eur, 'faltante', COALESCE(v_faltante, false))
  );
END;
$$;
CREATE FUNCTION public.proveedores_listado(p_organization_id uuid DEFAULT NULL::uuid, p_tipo text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50, p_origen text DEFAULT NULL::text, p_categoria text DEFAULT NULL::text, p_subtipo_gasto text DEFAULT NULL::text) RETURNS TABLE(id uuid, nombre text, tipo public.tipo_proveedor, rfc text, contacto text, moneda_preferida public.moneda, pais text, origen_proveedor text, categoria public.categoria_proveedor, subtipo_gasto public.subtipo_gasto_operativo, total_operaciones bigint, monto_pendiente numeric, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH filtered AS (
    SELECT p.*
    FROM proveedores p
    WHERE p.deleted_at IS NULL
      AND ( p_organization_id IS NULL OR p.organization_id = p_organization_id )
      AND ( p_tipo IS NULL OR p_tipo = '' OR p.tipo = p_tipo::tipo_proveedor )
      AND ( p_origen IS NULL OR p_origen = '' OR p_origen = 'todos' OR p.origen_proveedor::text = p_origen )
      AND ( p_categoria IS NULL OR p_categoria = '' OR p_categoria = 'todos' OR p.categoria::text = p_categoria )
      AND ( p_subtipo_gasto IS NULL OR p_subtipo_gasto = '' OR p.subtipo_gasto::text = p_subtipo_gasto )
      AND ( p_search IS NULL OR p_search = '' OR
            p.nombre   ILIKE '%' || p_search || '%' OR
            p.rfc      ILIKE '%' || p_search || '%' OR
            p.contacto ILIKE '%' || p_search || '%' OR
            p.email    ILIKE '%' || p_search || '%' )
  ),
  counted AS (
    SELECT f.*, count(*) OVER ()::bigint AS total_count
    FROM filtered f
    ORDER BY f.nombre ASC
    OFFSET p_offset LIMIT p_limit
  ),
  ops_agg AS (
    SELECT cc.proveedor_id,
           count(*)::bigint AS total_operaciones,
           COALESCE(sum(cc.monto) FILTER (WHERE cc.estado_liquidacion <> 'Pagado'), 0)::numeric AS monto_pendiente
    FROM conceptos_costo cc
    WHERE cc.proveedor_id IN (SELECT id FROM counted)
    GROUP BY cc.proveedor_id
  )
  SELECT c.id, c.nombre, c.tipo, c.rfc, c.contacto, c.moneda_preferida, c.pais,
         c.origen_proveedor::text,
         c.categoria, c.subtipo_gasto,
         COALESCE(oa.total_operaciones, 0),
         COALESCE(oa.monto_pendiente, 0),
         c.total_count
  FROM counted c
  LEFT JOIN ops_agg oa ON oa.proveedor_id = c.id
  ORDER BY c.nombre ASC;
$$;
CREATE FUNCTION public.provision_organization(p_nombre text, p_rfc text, p_owner_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_caller uuid := auth.uid();
  v_caller_email text;
  v_nombre text := btrim(coalesce(p_nombre, ''));
  v_rfc text := NULLIF(btrim(coalesce(p_rfc, '')), '');
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'No autenticado' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_role(v_caller, 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'Sólo super_admin puede aprovisionar organizaciones'
      USING ERRCODE = '42501';
  END IF;
  IF v_nombre = '' THEN
    RAISE EXCEPTION 'Nombre requerido' USING ERRCODE = '22023';
  END IF;
  IF length(v_nombre) > 200 THEN
    RAISE EXCEPTION 'Nombre demasiado largo (máx 200)' USING ERRCODE = '22023';
  END IF;
  IF p_owner_user_id IS NULL THEN
    RAISE EXCEPTION 'owner requerido' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_owner_user_id) THEN
    RAISE EXCEPTION 'Usuario owner no existe' USING ERRCODE = '22023';
  END IF;
  -- Ola 4 · N27: un usuario sólo puede pertenecer a UNA organización
  -- (organization_members_user_id_unique). Sin este chequeo, la org se
  -- creaba y la membresía se descartaba en silencio (org huérfana).
  IF EXISTS (SELECT 1 FROM public.organization_members WHERE user_id = p_owner_user_id) THEN
    RAISE EXCEPTION 'LC_OWNER_YA_ASIGNADO: El usuario elegido ya pertenece a una organización; elige otro o retíralo primero de la actual.'
      USING ERRCODE = '23505';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.organizations
    WHERE lower(nombre) = lower(v_nombre)
      AND (rfc IS NOT DISTINCT FROM v_rfc)
  ) THEN
    RAISE EXCEPTION 'Ya existe una organización con ese nombre/RFC'
      USING ERRCODE = '23505';
  END IF;
  INSERT INTO public.organizations (nombre, rfc)
  VALUES (v_nombre, v_rfc)
  RETURNING id INTO v_org_id;
  -- Rol moderno: 'admin_org' reemplaza al legacy 'admin' (bloqueado por trg_bloquear_rol_legacy_om desde v13.312.0)
  -- Ola 4 · N27: se conserva ON CONFLICT DO NOTHING sólo como defensa
  -- residual ante una carrera de aprovisionamientos concurrentes; la
  -- pre-validación de arriba es el camino normal.
  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (v_org_id, p_owner_user_id, 'admin_org'::app_role)
  ON CONFLICT DO NOTHING;
  SELECT email INTO v_caller_email FROM auth.users WHERE id = v_caller;
  INSERT INTO public.bitacora_actividad(
    usuario_id, usuario_email, accion, modulo,
    entidad_id, entidad_nombre, organization_id, detalles
  ) VALUES (
    v_caller,
    coalesce(v_caller_email, ''),
    'provision_organization',
    'admin_super',
    v_org_id,
    v_nombre,
    v_org_id,
    jsonb_build_object('owner_user_id', p_owner_user_id, 'rfc', v_rfc)
  );
  RETURN v_org_id;
END;
$$;
CREATE FUNCTION public.puede_escribir_cotizaciones(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _user_id IS NOT NULL AND (
    public.has_role(_user_id, 'super_admin'::app_role)
    OR public.has_role(_user_id, 'admin_org'::app_role)
    OR public.has_role(_user_id, 'admin'::app_role)
    OR public.has_role(_user_id, 'gerente_comercial'::app_role)
    OR public.has_role(_user_id, 'vendedor'::app_role)
    OR public.has_role(_user_id, 'ejecutivo_pricing'::app_role)
    -- v13.750.0: roles operativos habilitados para cotizar.
    OR public.has_role(_user_id, 'coordinador_logistico'::app_role)
    OR public.has_role(_user_id, 'gerente_operaciones'::app_role)
    OR public.has_role(_user_id, 'operador'::app_role)
    OR public.has_role(_user_id, 'customer_service'::app_role)
  )
$$;
CREATE FUNCTION public.puede_ver_costos_cotizacion(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _user_id IS NOT NULL AND public.has_any_role_efectivo(
    _user_id,
    ARRAY['admin','admin_org','super_admin',
          'gerente_operaciones','gerente_comercial','gerente_visor',
          'contador','tesorero','auxiliar_contable','ejecutivo_cobranza',
          'vendedor','ejecutivo_pricing']::app_role[]
  );
$$;
CREATE FUNCTION public.puede_ver_costos_cotizacion_propia(_cotizacion_id uuid, _user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _user_id IS NOT NULL
     AND _cotizacion_id IS NOT NULL
     AND public.has_any_role_efectivo(_user_id, ARRAY['vendedor']::app_role[])
     AND EXISTS (
       SELECT 1
       FROM public.cotizaciones c
       WHERE c.id = _cotizacion_id
         AND c.created_by = _user_id
         AND c.organization_id = public.current_user_org_id()
     );
