CREATE FUNCTION public.purgar_embarque_cascade(p_embarque_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_deleted_at timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  SELECT organization_id, deleted_at
    INTO v_org, v_deleted_at
    FROM public.embarques
   WHERE id = p_embarque_id AND deleted_at IS NOT NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Sólo embarques en papelera pueden purgarse';
  END IF;
  IF NOT (
    public.has_role(v_uid, 'super_admin'::app_role)
    OR (v_org = public.current_user_org_id() AND public.has_role(v_uid, 'admin'::app_role))
  ) THEN
    RAISE EXCEPTION 'Sólo admin / super_admin pueden purgar';
  END IF;
  -- Borrar físicamente hijos del mismo lote
  DELETE FROM public.conceptos_venta       WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  DELETE FROM public.conceptos_costo       WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  DELETE FROM public.documentos_embarque   WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  DELETE FROM public.notas_embarque        WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  DELETE FROM public.eventos_embarque      WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  DELETE FROM public.embarque_contenedores WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  DELETE FROM public.facturas              WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  DELETE FROM public.seguros_embarque      WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  DELETE FROM public.embarques WHERE id = p_embarque_id;
END;
$$;
CREATE FUNCTION public.purgar_facturapi_webhook_eventos() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  deleted integer;
BEGIN
  DELETE FROM public.facturapi_webhook_eventos
    WHERE received_at < now() - interval '60 days';
  GET DIAGNOSTICS deleted = ROW_COUNT;
  RETURN deleted;
END;
$$;
CREATE FUNCTION public.purge_app_logs_old() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_deleted integer;
begin
  delete from public.app_logs where ts < now() - interval '30 days';
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;
CREATE FUNCTION public.purge_record(_table text, _id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  _org uuid;
  _uid uuid := auth.uid();
BEGIN
  IF NOT public.is_soft_delete_table(_table) THEN
    RAISE EXCEPTION 'Tabla no permitida: %', _table;
  END IF;
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  IF _table = 'embarques' THEN
    PERFORM public.purgar_embarque_cascade(_id);
    RETURN;
  END IF;
  EXECUTE format('SELECT organization_id FROM public.%I WHERE id = $1 AND deleted_at IS NOT NULL', _table)
    INTO _org USING _id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'Sólo registros en papelera pueden purgarse';
  END IF;
  IF _org IS DISTINCT FROM public.org_scope() THEN
    RAISE EXCEPTION 'LC_ORG_FUERA_DE_SCOPE: el registro pertenece a otra organización';
  END IF;
  IF NOT (
    public.has_role(_uid, 'super_admin'::app_role)
    OR public.has_role(_uid, 'admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sólo admin / super_admin pueden purgar';
  END IF;
  EXECUTE format('DELETE FROM public.%I WHERE id = $1', _table)
    USING _id;
END;
$_$;
CREATE FUNCTION public.reabrir_embarque(p_embarque_id uuid, p_usuario_email text, p_motivo text, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_estado_actual text;
  v_resp jsonb;
  v_es_admin boolean;
  v_motivo text := NULLIF(trim(COALESCE(p_motivo, '')), '');
  v_actor_id uuid := auth.uid();
  v_actor_email text;
BEGIN
  SELECT email INTO v_actor_email FROM auth.users WHERE id = v_actor_id;
  v_actor_email := COALESCE(v_actor_email, 'usuario:' || COALESCE(v_actor_id::text, 'desconocido'));
  IF v_motivo IS NULL OR length(v_motivo) < 20 THEN
    RAISE EXCEPTION 'Motivo de reapertura requerido (mínimo 20 caracteres)';
  END IF;
  SELECT organization_id, estado::text
    INTO v_org_id, v_estado_actual
    FROM embarques
   WHERE id = p_embarque_id
     AND deleted_at IS NULL;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Embarque no encontrado';
  END IF;
  v_es_admin := public.has_role(auth.uid(), 'admin'::app_role)
             OR public.has_role(auth.uid(), 'super_admin'::app_role)
             OR public.has_role(auth.uid(), 'admin_org'::app_role);
  IF NOT v_es_admin THEN
    RAISE EXCEPTION 'Solo administradores pueden reabrir embarques cerrados';
  END IF;
  PERFORM public._assert_writer(v_org_id);
  IF v_estado_actual <> 'Cerrado' THEN
    RAISE EXCEPTION 'Solo embarques en estado Cerrado pueden reabrirse (estado actual: %)', v_estado_actual;
  END IF;
  v_resp := public.idempotency_claim(p_request_id, 'reabrir_embarque');
  IF v_resp IS NOT NULL THEN RETURN v_resp; END IF;
  PERFORM set_config('app.bypass_cierre','on', true);
  PERFORM set_config('app.bypass_transicion','on', true);
  UPDATE embarques
     SET estado = 'Por liquidar'::estado_embarque,
         cerrado_snapshot = NULL,
         reabierto_at = now(),
         reabierto_por = auth.uid(),
         reabierto_motivo = v_motivo,
         updated_at = now()
   WHERE id = p_embarque_id;
  PERFORM set_config('app.bypass_transicion','off', true);
  UPDATE comisiones_devengadas
     SET definitiva = false,
         pnl_base = NULL,
         calculo_snapshot = NULL,
         updated_at = now()
   WHERE embarque_id = p_embarque_id;
  PERFORM set_config('app.bypass_cierre','off', true);
  INSERT INTO notas_embarque (embarque_id, contenido, tipo, usuario, organization_id)
  VALUES (p_embarque_id, 'Embarque reabierto desde Cerrado a Por liquidar. Motivo: ' || v_motivo,
          'cambio_estado'::tipo_nota, v_actor_email, v_org_id);
  INSERT INTO eventos_embarque (embarque_id, tipo, descripcion, ubicacion, fecha, usuario, organization_id)
  VALUES (p_embarque_id, 'Otro'::tipo_evento_tracking, 'Embarque reabierto por administrador', '', now(), v_actor_email, v_org_id);
  BEGIN
    INSERT INTO cierre_embarque_log(embarque_id, organization_id, accion, usuario_id, motivo, snapshot)
    VALUES (p_embarque_id, v_org_id, 'reabrir', auth.uid(), v_motivo, NULL);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  PERFORM public.registrar_bitacora(
    'embarques', 'reabrir_embarque', p_embarque_id, '',
    jsonb_build_object('motivo', v_motivo), v_org_id, auth.uid()
  );
  v_resp := jsonb_build_object('id', p_embarque_id, 'estado', 'Por liquidar');
  PERFORM public.idempotency_store(p_request_id, v_resp);
  RETURN v_resp;
END;
$$;
CREATE FUNCTION public.reactivar_cotizacion_rpc(p_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado estado_cotizacion;
  v_anterior estado_cotizacion;
  v_org uuid;
  v_nuevo estado_cotizacion;
  v_vigencia date;
BEGIN
  SELECT estado, estado_anterior, organization_id, fecha_vigencia
    INTO v_estado, v_anterior, v_org, v_vigencia
  FROM public.cotizaciones WHERE id = p_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_COTIZACION_NO_ENCONTRADA';
  END IF;
  IF auth.uid() IS NOT NULL AND NOT public.is_org_member(v_org) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA';
  END IF;
  IF v_estado NOT IN ('Vencida'::estado_cotizacion, 'Archivada'::estado_cotizacion) THEN
    RAISE EXCEPTION 'LC_COTIZACION_NO_REACTIVABLE';
  END IF;
  v_nuevo := CASE
    WHEN v_anterior IS NOT NULL
     AND v_anterior NOT IN ('Vencida'::estado_cotizacion, 'Archivada'::estado_cotizacion)
    THEN v_anterior
    ELSE 'Borrador'::estado_cotizacion
  END;
  UPDATE public.cotizaciones
     SET estado = v_nuevo,
         estado_anterior = NULL,
         updated_at = now(),
         -- RG12: prórroga sólo si vuelve a 'Enviada' con vigencia vencida/nula.
         fecha_vigencia = CASE
           WHEN v_nuevo = 'Enviada'::estado_cotizacion
            AND (v_vigencia IS NULL OR v_vigencia < CURRENT_DATE)
           THEN CURRENT_DATE + 7
           ELSE fecha_vigencia
         END
   WHERE id = p_id;
  RETURN v_nuevo::text;
END;
$$;
CREATE FUNCTION public.reactivar_factura_entrante(p_documento_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid := public.current_user_org_id();
  v_doc public.embarque_facturas_entrantes%ROWTYPE;
  v_filas int := 0;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'operador')
          OR public.has_role(auth.uid(), 'contador')
          OR public.has_role(auth.uid(), 'auxiliar_contable')
          OR public.has_role(auth.uid(), 'admin')
          OR public.has_role(auth.uid(), 'super_admin')) THEN
    RAISE EXCEPTION 'LC_ENTRANTE_REACTIVAR_FORBIDDEN: sin permiso para devolver documentos al buzón';
  END IF;
  SELECT * INTO v_doc FROM public.embarque_facturas_entrantes
   WHERE id = p_documento_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'LC_NOT_FOUND: documento no encontrado'; END IF;
  IF v_doc.organization_id IS DISTINCT FROM v_caller_org AND NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: documento de otra organización';
  END IF;
  -- Ola 6 · RG5-4: condición dentro del UPDATE (ver retirar_factura_entrante).
  UPDATE public.embarque_facturas_entrantes
     SET estado = 'por_capturar',
         rechazo_motivo = NULL,
         capturado_por = NULL
   WHERE id = p_documento_id
     AND deleted_at IS NULL
     AND estado = 'rechazada'
     AND proveedor_factura_id IS NULL;
  GET DIAGNOSTICS v_filas = ROW_COUNT;
  IF v_filas = 0 THEN
    RAISE EXCEPTION 'LC_ENTRANTE_REACTIVAR_ESTADO: sólo un documento rechazado y sin factura vinculada puede volver a por capturar';
  END IF;
END;
$$;
CREATE FUNCTION public.reasignar_pago_factura(p_pago_id uuid, p_factura_destino_id uuid, p_caso_id uuid DEFAULT NULL::uuid, p_ordenante_nombre text DEFAULT NULL::text, p_ordenante_rfc text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_p public.pagos_factura%ROWTYPE;
  v_dest public.facturas%ROWTYPE;
  v_new_id uuid;
  v_saldo numeric;
  v_pagado numeric;
  v_ncs numeric;
  v_ord_nombre text := NULLIF(btrim(COALESCE(p_ordenante_nombre, '')), '');
  v_ord_rfc text := NULLIF(upper(btrim(COALESCE(p_ordenante_rfc, ''))), '');
BEGIN
  -- Ola v16 (1): dos reasignaciones simultáneas del MISMO pago (doble clic)
  -- leían la fila viva antes de que la otra la marcara como eliminada y
  -- duplicaban el importe en el destino. `FOR UPDATE` serializa a la segunda
  -- transacción; al liberarse el lock Postgres reevalúa el predicado
  -- `deleted_at IS NULL` y la segunda ya no encuentra el pago vivo.
  SELECT * INTO v_p FROM public.pagos_factura
   WHERE id = p_pago_id AND deleted_at IS NULL
     FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_PAGO_NO_ENCONTRADO' USING ERRCODE = 'P0002';
  END IF;
  -- Revalidación explícita post-lock (defensa en profundidad).
  IF v_p.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'LC_REFACT_PAGO_NO_ENCONTRADO' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public._assert_refacturador(v_p.organization_id);
  IF v_p.uuid_rep IS NOT NULL AND v_p.rep_cancelado_en IS NULL THEN
    RAISE EXCEPTION 'LC_REFACT_REP_VIVO: cancela el complemento de pago (REP) antes de reasignar el pago'
      USING ERRCODE = 'P0001';
  END IF;
  IF v_ord_nombre IS NULL THEN
    RAISE EXCEPTION 'LC_REFACT_ORDENANTE_REQUERIDO: captura el nombre de la empresa que realizó el depósito'
      USING ERRCODE = 'P0001';
  END IF;
  IF v_ord_rfc IS NOT NULL AND NOT public._rfc_valido(v_ord_rfc, true) THEN
    RAISE EXCEPTION 'LC_REFACT_RFC_INVALIDO: el RFC del ordenante (%) no tiene formato válido del SAT', v_ord_rfc
      USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO v_dest FROM public.facturas WHERE id = p_factura_destino_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_FACTURA_NO_ENCONTRADA' USING ERRCODE = 'P0002';
  END IF;
  IF v_dest.organization_id <> v_p.organization_id THEN
    RAISE EXCEPTION 'LC_REFACT_FACTURA_OTRA_ORG' USING ERRCODE = '42501';
  END IF;
  IF v_dest.uuid_fiscal IS NULL OR v_dest.estado IN ('Borrador','Cancelada','Sustituida') THEN
    RAISE EXCEPTION 'LC_REFACT_FACTURA_NO_TIMBRADA: la factura destino debe estar timbrada y vigente'
      USING ERRCODE = 'P0001';
  END IF;
  IF v_dest.moneda <> v_p.moneda THEN
    RAISE EXCEPTION 'LC_REFACT_MONEDA_INCONSISTENTE: el pago está en % y la factura destino en %', v_p.moneda, v_dest.moneda
      USING ERRCODE = 'P0001';
  END IF;
  IF v_dest.moneda <> 'MXN' AND COALESCE(v_p.tipo_cambio, 0) <= 0 THEN
    RAISE EXCEPTION 'LC_REFACT_TC_REQUERIDO: el pago en % requiere tipo de cambio', v_dest.moneda
      USING ERRCODE = 'P0001';
  END IF;
  SELECT COALESCE(SUM(monto_aplicado_factura), 0) INTO v_pagado
  FROM public.pagos_factura
  WHERE factura_id = p_factura_destino_id AND deleted_at IS NULL;
  -- Ola v16 (1): canon único de NC convertidas a la moneda de la factura
  -- (no sumar `monto` crudo, que mezcla monedas).
  v_ncs := public.nc_aplicadas_en_moneda_factura(p_factura_destino_id);
  v_saldo := COALESCE(v_dest.total, 0) - v_pagado - v_ncs;
  -- Tolerancia canónica del trigger de sobrepago: 0.005 (medio centavo).
  IF ROUND(v_p.monto_aplicado_factura, 2) > ROUND(v_saldo, 2) + 0.005 THEN
    RAISE EXCEPTION 'LC_REFACT_SOBREPAGO: el pago (%) excede el saldo de la factura destino (%)',
      v_p.monto_aplicado_factura, v_saldo USING ERRCODE = 'P0001';
  END IF;
  -- 1) Baja lógica del pago original.
  UPDATE public.pagos_factura
     SET deleted_at = now(), deleted_by = auth.uid(),
         notas = COALESCE(notas, '') || ' [Reasignado a factura ' || COALESCE(v_dest.numero, '') || ']',
         refacturacion_id = COALESCE(p_caso_id, refacturacion_id)
   WHERE id = p_pago_id;
  -- 2) Alta del pago equivalente en la factura destino.
  INSERT INTO public.pagos_factura (
    factura_id, organization_id, fecha_pago, monto, moneda, tipo_cambio,
    monto_aplicado_factura, forma_pago, referencia, notas,
    diferencia_cambiaria_mxn, embarque_id, cuenta_bancaria_id, created_by,
    ordenante_distinto, ordenante_nombre, ordenante_rfc, refacturacion_id
  ) VALUES (
    p_factura_destino_id, v_p.organization_id, v_p.fecha_pago, v_p.monto, v_p.moneda, v_p.tipo_cambio,
    v_p.monto_aplicado_factura, v_p.forma_pago, v_p.referencia,
    COALESCE(v_p.notas, '') || ' [Reasignado desde pago ' || p_pago_id::text || ']',
    COALESCE(v_p.diferencia_cambiaria_mxn, 0), v_dest.embarque_id, v_p.cuenta_bancaria_id, auth.uid(),
    true, v_ord_nombre, v_ord_rfc, p_caso_id
  )
  RETURNING id INTO v_new_id;
  -- 3) Traslado del movimiento bancario.
  UPDATE public.bbva_movimientos
     SET pago_factura_id = v_new_id,
         estado_conciliacion = 'Conciliado',
         conciliado_por = auth.uid(),
         conciliado_at = now()
   WHERE pago_factura_id = p_pago_id;
  IF p_caso_id IS NOT NULL THEN
    UPDATE public.refacturaciones
       SET pago_original_id = COALESCE(pago_original_id, p_pago_id),
           pago_nuevo_id = v_new_id,
           paso_actual = 5
     WHERE id = p_caso_id;
  END IF;
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_p.organization_id, auth.uid(),
    COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), ''),
    'refacturacion_pago_reasignado', 'facturacion', p_factura_destino_id,
    COALESCE(v_dest.numero, ''),
    jsonb_build_object('caso_id', p_caso_id, 'pago_original_id', p_pago_id,
                       'pago_nuevo_id', v_new_id, 'monto', v_p.monto, 'moneda', v_p.moneda,
                       'ordenante_nombre', v_ord_nombre)
  );
  RETURN v_new_id;
END;
$$;
CREATE FUNCTION public.recalc_factura_retenciones(p_factura_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.recalc_factura_totales(p_factura_id);
END;
$$;
CREATE FUNCTION public.recalc_factura_totales(p_factura_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_n        int;
  v_subtotal numeric;
  v_iva      numeric;
  v_isr      numeric;
  v_iva_ret  numeric;
BEGIN
  SELECT
    count(*),
    COALESCE(SUM(ROUND(COALESCE(c.cantidad, 1) * COALESCE(c.precio_unitario, 0), 2)), 0),
    COALESCE(SUM(ROUND(
        COALESCE(c.cantidad, 1) * COALESCE(c.precio_unitario, 0)
        * COALESCE(c.tasa_iva_aplicada,
                   CASE WHEN c.tipo_iva = 'gravado_16' THEN 0.16 ELSE 0 END),
        2)), 0),
    COALESCE(SUM(COALESCE(c.monto_ret_isr, 0)), 0),
    COALESCE(SUM(COALESCE(c.monto_ret_iva, 0)), 0)
  INTO v_n, v_subtotal, v_iva, v_isr, v_iva_ret
  FROM public.conceptos_factura c
  WHERE c.factura_id = p_factura_id
    AND c.deleted_at IS NULL;
  IF v_n = 0 THEN
    -- QA-R2 D-05: factura sin renglones vivos -> totales en cero (antes se
    -- conservaban subtotal/iva capturados y el total quedaba inflado).
    UPDATE public.facturas
       SET subtotal = 0,
           iva = 0,
           ret_isr = 0,
           ret_iva = 0,
           total = 0,
           updated_at = now()
     WHERE id = p_factura_id;
    RETURN;
  END IF;
  UPDATE public.facturas
     SET subtotal   = v_subtotal,
         iva        = v_iva,
         ret_isr    = v_isr,
         ret_iva    = v_iva_ret,
         total      = v_subtotal + v_iva - v_isr - v_iva_ret,
         updated_at = now()
   WHERE id = p_factura_id;
END;
$$;
CREATE FUNCTION public.recalcular_cobro_embarques(p_embarque_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emb uuid; v_total int; v_pagadas int; v_parciales int; v_nuevo text;
BEGIN
  IF p_embarque_ids IS NULL OR array_length(p_embarque_ids, 1) IS NULL THEN
    RETURN;
  END IF;
  PERFORM set_config('app.bypass_cierre', 'on', true);
  FOREACH v_emb IN ARRAY p_embarque_ids LOOP
    SELECT
      count(*) FILTER (WHERE f.estado NOT IN ('Cancelada','Sustituida','Borrador')),
      count(*) FILTER (WHERE f.estado = 'Pagada'::estado_factura),
      count(*) FILTER (WHERE f.estado = 'Parcialmente pagada'::estado_factura)
    INTO v_total, v_pagadas, v_parciales
    FROM public.factura_embarques fe
    JOIN public.facturas f ON f.id = fe.factura_id AND f.deleted_at IS NULL
    WHERE fe.embarque_id = v_emb;
    IF v_total = 0 THEN
      v_nuevo := 'pendiente';
    ELSIF v_pagadas = v_total THEN
      v_nuevo := 'pagado';
    ELSIF v_pagadas > 0 OR v_parciales > 0 THEN
      v_nuevo := 'parcial';
    ELSE
      v_nuevo := 'pendiente';
    END IF;
    UPDATE public.embarques
    SET cobro_cliente_status = v_nuevo,
        cobro_cliente_actualizado_at = now()
    WHERE id = v_emb
      AND cobro_cliente_status IS DISTINCT FROM v_nuevo;
  END LOOP;
END;
$$;
CREATE FUNCTION public.recalcular_estado_factura() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_factura_id uuid;
  v_total numeric;
  v_pagado numeric;
  v_ncs numeric;
  v_saldo numeric;
  v_vencimiento date;
  v_estado_actual estado_factura;
  v_nuevo_estado estado_factura;
  v_prev_flag text;
BEGIN
  v_factura_id := COALESCE(NEW.factura_id, OLD.factura_id);
  SELECT total, fecha_vencimiento, estado
    INTO v_total, v_vencimiento, v_estado_actual
  FROM facturas
  WHERE id = v_factura_id;
  IF v_estado_actual IN ('Cancelada', 'Borrador', 'Sustituida') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  SELECT COALESCE(SUM(monto_aplicado_factura), 0) INTO v_pagado
  FROM public.pagos_factura
  WHERE factura_id = v_factura_id AND deleted_at IS NULL;
  -- OLA 1 · C1: NC convertidas a la moneda de la factura (fuente única).
  v_ncs := public._nc_aplicadas_moneda_factura(v_factura_id);
  v_saldo := COALESCE(v_total, 0) - v_pagado - COALESCE(v_ncs, 0);
  IF v_saldo <= 0.01 THEN
    v_nuevo_estado := 'Pagada';
  ELSIF v_pagado > 0 THEN
    v_nuevo_estado := 'Parcialmente pagada';
  ELSIF v_vencimiento IS NOT NULL AND v_vencimiento < CURRENT_DATE THEN
    v_nuevo_estado := 'Vencida';
  ELSE
    v_nuevo_estado := 'Emitida';
  END IF;
  v_prev_flag := current_setting('app.recalc_estado_factura', true);
  PERFORM set_config('app.recalc_estado_factura', '1', true);
  UPDATE facturas
  SET estado = v_nuevo_estado, updated_at = now()
  WHERE id = v_factura_id AND estado IS DISTINCT FROM v_nuevo_estado;
  PERFORM set_config('app.recalc_estado_factura', COALESCE(v_prev_flag, ''), true);
  RETURN COALESCE(NEW, OLD);
END;
$$;
CREATE FUNCTION public.recalcular_estado_liquidacion_concepto(p_concepto_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pagado boolean;
  v_fecha date;
  v_bypass_prev text;
BEGIN
  IF p_concepto_id IS NULL THEN RETURN; END IF;
  SELECT
    EXISTS (
      SELECT 1 FROM proveedor_facturas_conceptos pfc
      JOIN proveedor_facturas pf ON pf.id = pfc.proveedor_factura_id
      WHERE pfc.concepto_costo_id = p_concepto_id
        AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada')
    AND NOT EXISTS (
      SELECT 1 FROM proveedor_facturas_conceptos pfc
      JOIN proveedor_facturas pf ON pf.id = pfc.proveedor_factura_id
      WHERE pfc.concepto_costo_id = p_concepto_id
        AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada'
        AND COALESCE(pf.total, 0) > COALESCE((
          SELECT SUM(pp.monto) FROM pagos_proveedor pp
          WHERE pp.proveedor_factura_id = pf.id AND pp.deleted_at IS NULL), 0) + 0.01)
  INTO v_pagado;
  SELECT MAX(pp.fecha_pago) INTO v_fecha
  FROM proveedor_facturas_conceptos pfc
  JOIN pagos_proveedor pp ON pp.proveedor_factura_id = pfc.proveedor_factura_id
  WHERE pfc.concepto_costo_id = p_concepto_id AND pp.deleted_at IS NULL;
  -- Bypass acotado: sólo alrededor del UPDATE de sincronización.
  v_bypass_prev := COALESCE(current_setting('app.bypass_cierre', true), 'off');
  BEGIN
    PERFORM set_config('app.bypass_cierre', 'on', true);
    UPDATE conceptos_costo
       SET estado_liquidacion = CASE WHEN v_pagado THEN 'Pagado' ELSE 'Pendiente' END::estado_liquidacion,
           fecha_pago = CASE WHEN v_pagado THEN v_fecha ELSE NULL END
     WHERE id = p_concepto_id;
    PERFORM set_config('app.bypass_cierre', v_bypass_prev, true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.bypass_cierre', v_bypass_prev, true);
    RAISE;
  END;
END $$;
CREATE FUNCTION public.recalcular_estado_liquidacion_factura(p_factura_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record;
BEGIN
  IF p_factura_id IS NULL THEN RETURN; END IF;
  FOR r IN
    SELECT DISTINCT concepto_costo_id FROM proveedor_facturas_conceptos
    WHERE proveedor_factura_id = p_factura_id AND concepto_costo_id IS NOT NULL
  LOOP
    PERFORM recalcular_estado_liquidacion_concepto(r.concepto_costo_id);
  END LOOP;
END $$;
CREATE FUNCTION public.recalcular_subtotal_cotizacion(p_cotizacion_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_moneda text;
  v_org    uuid;
  v_t      record;
  v_sub    numeric;
  v_n      int;
BEGIN
  SELECT c.moneda::text, c.organization_id,
         CASE WHEN jsonb_typeof(c.conceptos_venta) = 'array'
              THEN jsonb_array_length(c.conceptos_venta) ELSE 0 END
    INTO v_moneda, v_org, v_n
  FROM public.cotizaciones c
  WHERE c.id = p_cotizacion_id AND c.deleted_at IS NULL;
  IF v_moneda IS NULL THEN
    RAISE EXCEPTION 'Cotización no encontrada' USING ERRCODE = 'P0002';
  END IF;
  IF v_org IS DISTINCT FROM public.current_user_org_id() THEN
    RAISE EXCEPTION 'LC_ORG_MISMATCH: la cotización pertenece a otra organización'
      USING ERRCODE = '42501';
  END IF;
  IF v_n = 0 THEN
    RETURN (SELECT subtotal FROM public.cotizaciones WHERE id = p_cotizacion_id);
  END IF;
  SELECT t.* INTO v_t
  FROM public.cotizaciones c,
       LATERAL (SELECT * FROM public.cotizacion_totales_conceptos(c.conceptos_venta)) t
  WHERE c.id = p_cotizacion_id;
  v_sub := COALESCE(
    NULLIF(CASE WHEN v_moneda = 'USD' THEN v_t.subtotal_usd ELSE v_t.subtotal_mxn END, 0),
    NULLIF(CASE WHEN v_moneda = 'USD' THEN v_t.subtotal_mxn ELSE v_t.subtotal_usd END, 0),
    0
  );
  -- QA-R2 R-04: el recálculo deriva el subtotal de los conceptos; no es una
  -- edición comercial, bypass transaccional del guard de cotización congelada.
  PERFORM set_config('app.cotizacion_sync', '1', true);
  UPDATE public.cotizaciones
     SET subtotal = v_sub, updated_at = now()
   WHERE id = p_cotizacion_id;
  RETURN v_sub;
END;
$$;
CREATE FUNCTION public.rechazar_documento_embarque(_doc_id uuid, _motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc record;
  v_emb record;
  v_motivo text := btrim(coalesce(_motivo, ''));
BEGIN
  IF length(v_motivo) < 10 THEN
    RAISE EXCEPTION 'LC_MOTIVO_REQUERIDO: el motivo de rechazo debe tener al menos 10 caracteres'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO v_doc
  FROM public.documentos_embarque
  WHERE id = _doc_id
    AND deleted_at IS NULL
    AND organization_id = public.current_user_org_id();
  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'LC_DOC_INEXISTENTE: el documento no existe o no pertenece a tu organización'
      USING ERRCODE = 'no_data_found';
  END IF;
  PERFORM public._assert_writer(v_doc.organization_id);
  IF v_doc.estado = 'Validado'::public.estado_documento THEN
    RAISE EXCEPTION 'LC_DOC_VALIDADO: el documento ya fue validado; invalídalo antes de rechazarlo'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_doc.estado = 'Rechazado'::public.estado_documento THEN
    RAISE EXCEPTION 'LC_DOC_YA_RECHAZADO: el documento ya está rechazado'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT id, expediente, created_by, organization_id INTO v_emb
  FROM public.embarques
  WHERE id = v_doc.embarque_id;
  UPDATE public.documentos_embarque
  SET estado = 'Rechazado'::public.estado_documento,
      archivo = NULL,
      notas = left(
        coalesce(nullif(btrim(coalesce(notas, '')), '') || E'\n', '')
        || 'Rechazado ' || to_char(now(), 'DD/MM/YYYY HH24:MI') || ': ' || v_motivo,
        2000)
  WHERE id = _doc_id;
  IF v_emb.created_by IS NOT NULL THEN
    INSERT INTO public.notificaciones_internas (
      organization_id, usuario_id, tipo, titulo, mensaje, enlace, entidad_tipo, entidad_id
    ) VALUES (
      v_doc.organization_id,
      v_emb.created_by,
      'documento_rechazado',
      'Documento rechazado: ' || v_doc.nombre,
      'El documento "' || v_doc.nombre || '" del embarque ' || coalesce(v_emb.expediente, '') ||
        ' fue rechazado. Motivo: ' || v_motivo,
      '/embarques/' || v_doc.embarque_id::text,
      'embarque',
      v_doc.embarque_id
    );
  ELSE
    -- Fallback: sin created_by no había destinatario y el rechazo pasaba
    -- inadvertido. Se avisa a los administradores de la organización.
    INSERT INTO public.notificaciones_internas (
      organization_id, usuario_id, tipo, titulo, mensaje, enlace, entidad_tipo, entidad_id
    )
    SELECT DISTINCT
      v_doc.organization_id,
      om.user_id,
      'documento_rechazado',
      'Documento rechazado: ' || v_doc.nombre,
      'El documento "' || v_doc.nombre || '" del embarque ' || coalesce(v_emb.expediente, '') ||
        ' fue rechazado. Motivo: ' || v_motivo,
      '/embarques/' || v_doc.embarque_id::text,
      'embarque',
      v_doc.embarque_id
    FROM public.organization_members om
    WHERE om.organization_id = v_doc.organization_id
      AND om.role IN ('admin'::public.app_role, 'admin_org'::public.app_role);
  END IF;
  INSERT INTO public.bitacora_actividad (
    organization_id, usuario_id, usuario_email, modulo, accion, entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_doc.organization_id,
    COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(auth.email(), ''),
    'documentos',
    'rechazar_documento',
    _doc_id,
    v_doc.nombre,
    jsonb_build_object('motivo', v_motivo, 'embarque_id', v_doc.embarque_id)
  );
END;
$$;
CREATE FUNCTION public.rechazar_factura_entrante(p_documento_id uuid, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid := public.current_user_org_id();
  v_doc public.embarque_facturas_entrantes%ROWTYPE;
  v_expediente text;
  v_filas int;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'contador')
          OR public.has_role(auth.uid(), 'auxiliar_contable')
          OR public.has_role(auth.uid(), 'admin')
          OR public.has_role(auth.uid(), 'super_admin')) THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: sin permiso para rechazar facturas entrantes';
  END IF;
  IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
    RAISE EXCEPTION 'LC_MOTIVO_REQUERIDO: indica el motivo del rechazo';
  END IF;
  SELECT * INTO v_doc FROM public.embarque_facturas_entrantes
   WHERE id = p_documento_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'LC_NOT_FOUND: documento no encontrado'; END IF;
  IF v_doc.organization_id <> v_caller_org AND NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: documento de otra organización';
  END IF;
  UPDATE public.embarque_facturas_entrantes
     SET estado = 'rechazada',
         rechazo_motivo = btrim(p_motivo),
         capturado_por = auth.uid()
   WHERE id = p_documento_id
     AND deleted_at IS NULL
     AND estado = 'por_capturar';
  GET DIAGNOSTICS v_filas = ROW_COUNT;
  IF v_filas = 0 THEN
    RAISE EXCEPTION 'LC_ESTADO_INVALIDO: el documento ya fue procesado';
  END IF;
  SELECT e.expediente INTO v_expediente FROM public.embarques e WHERE e.id = v_doc.embarque_id;
  IF v_doc.subido_por IS NOT NULL AND v_doc.subido_por <> auth.uid() THEN
    INSERT INTO public.notificaciones_internas
      (organization_id, usuario_id, tipo, titulo, mensaje, enlace, entidad_tipo, entidad_id)
    VALUES (
      v_doc.organization_id,
      v_doc.subido_por,
      'cxp_entrante_rechazada',
      'Contabilidad rechazó una factura del buzón',
      COALESCE(v_expediente, 'Embarque') || ': ' || COALESCE(v_doc.nombre_archivo, 'documento')
        || ' — ' || btrim(p_motivo),
      '/embarques/' || v_doc.embarque_id::text,
      'embarque_factura_entrante',
      v_doc.id
    );
  END IF;
END;
$$;
CREATE FUNCTION public.recompute_embarque_tiene_proforma(p_embarque_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_embarque_id IS NULL THEN
    RETURN;
  END IF;
  PERFORM set_config('app.bypass_cierre', 'on', true);
  UPDATE public.embarques e
  SET tiene_proforma = EXISTS (
    SELECT 1
    FROM public.proformas p
    WHERE p.embarque_id = e.id
      AND (
        COALESCE(p.estado_aprobacion, 'aprobada') <> 'borrador'
        OR EXISTS (
          SELECT 1 FROM public.conceptos_venta cv
          WHERE cv.proforma_id = p.id
        )
      )
  )
  WHERE e.id = p_embarque_id;
END;
$$;
CREATE FUNCTION public.recotizar_cotizacion(p_cotizacion_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old INT;
  v_new INT;
  v_org UUID;
  v_folio TEXT;
  v_embarque_expediente TEXT;
BEGIN
  SELECT version, organization_id, folio INTO v_old, v_org, v_folio
  FROM cotizaciones WHERE id = p_cotizacion_id;
  IF v_old IS NULL THEN
    RAISE EXCEPTION 'Cotización no encontrada' USING ERRCODE='P0002';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM organization_members
    WHERE organization_id = v_org AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501';
  END IF;
  IF coalesce(trim(p_motivo),'') = '' THEN
    RAISE EXCEPTION 'Motivo requerido' USING ERRCODE='22023';
  END IF;
  -- Bug 15 guard: block re-versioning if there is any active shipment linked
  SELECT expediente INTO v_embarque_expediente
  FROM public.embarques
  WHERE cotizacion_id = p_cotizacion_id
    AND deleted_at IS NULL
  ORDER BY created_at ASC
  LIMIT 1;
  IF v_embarque_expediente IS NOT NULL THEN
    RAISE EXCEPTION 'LC_COTIZACION_CON_EMBARQUE'
      USING HINT = v_embarque_expediente,
            ERRCODE = 'P0001';
  END IF;
  PERFORM archivar_version_cotizacion(p_cotizacion_id, p_motivo);
  v_new := v_old + 1;
  UPDATE cotizaciones
     SET version = v_new, estado = 'Borrador', updated_at = now()
   WHERE id = p_cotizacion_id;
  INSERT INTO bitacora_actividad (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
  VALUES (
    v_org,
    auth.uid(),
    COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), ''),
    'cotizacion.versionada',
    'cotizaciones',
    p_cotizacion_id,
    COALESCE(v_folio, ''),
    jsonb_build_object('version_anterior', v_old, 'version_nueva', v_new, 'motivo', p_motivo)
  );
  RETURN jsonb_build_object('cotizacion_id', p_cotizacion_id, 'version_anterior', v_old, 'version_nueva', v_new);
END $$;
CREATE FUNCTION public.reemplazar_conceptos_entrante(p_documento_id uuid, p_conceptos jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid := public.current_user_org_id();
  v_doc public.embarque_facturas_entrantes%ROWTYPE;
  v_insertados int := 0;
BEGIN
  SELECT * INTO v_doc FROM public.embarque_facturas_entrantes
   WHERE id = p_documento_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'LC_NOT_FOUND: documento no encontrado'; END IF;
  IF v_doc.organization_id <> v_caller_org AND NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: documento de otra organización';
  END IF;
  IF v_doc.estado <> 'por_capturar' THEN
    RAISE EXCEPTION 'LC_ESTADO_INVALIDO: sólo se pueden corregir documentos por capturar';
  END IF;
  DELETE FROM public.embarque_facturas_entrantes_conceptos WHERE entrante_id = p_documento_id;
  INSERT INTO public.embarque_facturas_entrantes_conceptos
    (entrante_id, concepto_costo_id, organization_id, monto_sugerido)
  SELECT p_documento_id,
         (x->>'conceptoId')::uuid,
         v_doc.organization_id,
         NULLIF(x->>'monto', '')::numeric
    FROM jsonb_array_elements(COALESCE(p_conceptos, '[]'::jsonb)) AS x
   WHERE EXISTS (
     SELECT 1 FROM public.conceptos_costo cc
      WHERE cc.id = (x->>'conceptoId')::uuid
        AND cc.embarque_id = v_doc.embarque_id
        AND cc.organization_id = v_doc.organization_id
   )
  ON CONFLICT (entrante_id, concepto_costo_id) DO NOTHING;
  GET DIAGNOSTICS v_insertados = ROW_COUNT;
  RETURN v_insertados;
END;
$$;
CREATE FUNCTION public.reemplazar_conceptos_factura_proveedor(p_factura_id uuid, p_conceptos jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_f public.proveedor_facturas%ROWTYPE;
  v_pagado numeric := 0;
  v_insertados int := 0;
  v_subtotal numeric := 0;
  v_iva numeric := 0;
  v_ieps numeric := 0;
BEGIN
  SELECT * INTO v_f FROM public.proveedor_facturas
   WHERE id = p_factura_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_NOT_FOUND: la factura no existe' USING ERRCODE = 'P0002';
  END IF;
  IF v_f.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'LC_FACTURA_ELIMINADA: la factura está en la papelera' USING ERRCODE = '22023';
  END IF;
  IF NOT public.is_org_member(v_f.organization_id)
     AND NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: factura de otra organización' USING ERRCODE = '42501';
  END IF;
  IF NOT (public.has_role(auth.uid(), 'admin')
          OR public.has_role(auth.uid(), 'super_admin')
          OR public.has_role(auth.uid(), 'admin_org')
          OR public.has_role(auth.uid(), 'contador')
          OR public.has_role(auth.uid(), 'auxiliar_contable')
          OR public.has_role(auth.uid(), 'tesorero')) THEN
    RAISE EXCEPTION 'LC_CONCEPTOS_FORBIDDEN: sin permiso para editar los conceptos de la factura'
      USING ERRCODE = '42501';
  END IF;
  IF v_f.uuid_fiscal IS NOT NULL OR v_f.archivo_xml_url IS NOT NULL THEN
    RAISE EXCEPTION 'LC_CONCEPTOS_FISCALES: los conceptos vienen del XML del CFDI; vuelve a adjuntar el XML para cambiarlos'
      USING ERRCODE = '22023';
  END IF;
  IF v_f.estado = 'Cancelada'::public.estado_proveedor_factura THEN
    RAISE EXCEPTION 'LC_FACTURA_CANCELADA: la factura está cancelada' USING ERRCODE = '22023';
  END IF;
  SELECT COALESCE(SUM(monto), 0) INTO v_pagado
    FROM public.pagos_proveedor
   WHERE proveedor_factura_id = p_factura_id AND deleted_at IS NULL;
  IF v_pagado > 0 THEN
    RAISE EXCEPTION 'LC_FACTURA_CON_PAGOS: la factura tiene pagos aplicados por %; elimina los pagos antes de editar los conceptos', v_pagado
      USING ERRCODE = '22023';
  END IF;
  DELETE FROM public.proveedor_facturas_conceptos
   WHERE proveedor_factura_id = p_factura_id
     AND concepto_costo_id IS NULL;
  INSERT INTO public.proveedor_facturas_conceptos
    (proveedor_factura_id, organization_id, concepto_costo_id,
     descripcion, cantidad, clave_unidad, monto, iva, ieps)
  SELECT p_factura_id,
         v_f.organization_id,
         NULL,
         COALESCE(NULLIF(btrim(x->>'descripcion'), ''), '(Sin descripción)'),
         COALESCE(NULLIF(x->>'cantidad', '')::numeric, 1),
         NULLIF(btrim(COALESCE(x->>'clave_unidad', '')), ''),
         COALESCE(NULLIF(x->>'monto', '')::numeric, 0),
         COALESCE(NULLIF(x->>'iva', '')::numeric, 0),
         COALESCE(NULLIF(x->>'ieps', '')::numeric, 0)
    FROM jsonb_array_elements(COALESCE(p_conceptos, '[]'::jsonb)) AS x;
  GET DIAGNOSTICS v_insertados = ROW_COUNT;
  -- BUG-02 (auditoría 2026-08-18): la cabecera debe cuadrar con sus renglones.
  -- `guard_proveedor_factura_total` recalcula `total` a partir de estos campos.
  SELECT COALESCE(SUM(monto), 0), COALESCE(SUM(iva), 0), COALESCE(SUM(ieps), 0)
    INTO v_subtotal, v_iva, v_ieps
    FROM public.proveedor_facturas_conceptos
   WHERE proveedor_factura_id = p_factura_id;
  UPDATE public.proveedor_facturas
     SET subtotal = ROUND(v_subtotal, 2),
         iva      = ROUND(v_iva, 2),
         ieps     = ROUND(v_ieps, 2),
         estado_aprobacion = CASE
           WHEN estado_aprobacion = 'aprobada'::public.estado_aprobacion_factura_proveedor
             THEN 'pendiente'::public.estado_aprobacion_factura_proveedor
           ELSE estado_aprobacion END,
         aprobada_por = CASE
           WHEN estado_aprobacion = 'aprobada'::public.estado_aprobacion_factura_proveedor
             THEN NULL ELSE aprobada_por END,
         aprobada_at = CASE
           WHEN estado_aprobacion = 'aprobada'::public.estado_aprobacion_factura_proveedor
             THEN NULL ELSE aprobada_at END,
         updated_at = now()
   WHERE id = p_factura_id;
  RETURN v_insertados;
END;
$$;
CREATE FUNCTION public.refacturacion_expediente(p_caso_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_c public.refacturaciones%ROWTYPE;
  v_result jsonb;
BEGIN
  SELECT * INTO v_c FROM public.refacturaciones WHERE id = p_caso_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_CASO_NO_ENCONTRADO' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (
    v_c.organization_id = public.current_user_org_id()
    OR public.has_role(auth.uid(), 'super_admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'LC_ORG_FORBIDDEN: no tienes acceso a este caso' USING ERRCODE = '42501';
  END IF;
  SELECT jsonb_build_object(
    'caso', jsonb_build_object(
      'id', v_c.id,
      'estado', v_c.estado,
      'paso_actual', v_c.paso_actual,
      'ruta_fiscal', v_c.ruta_fiscal,
      'motivo', v_c.motivo,
      'created_at', v_c.created_at,
      'cerrado_at', v_c.cerrado_at,
      'creado_por_email', COALESCE((SELECT email FROM auth.users WHERE id = v_c.created_by), ''),
      'cliente_origen', (SELECT nombre FROM public.clientes WHERE id = v_c.cliente_origen_id),
      'cliente_destino', (SELECT nombre FROM public.clientes WHERE id = v_c.cliente_destino_id),
      'embarque_id', v_c.embarque_id,
      'embarque_expediente', (SELECT expediente FROM public.embarques WHERE id = v_c.embarque_id)
    ),
    'factura_original', (
      SELECT jsonb_build_object('id', f.id, 'numero', f.numero, 'estado', f.estado,
                                'uuid_fiscal', f.uuid_fiscal, 'total', f.total, 'moneda', f.moneda,
                                'cancelado_en', f.cancelado_en)
      FROM public.facturas f WHERE f.id = v_c.factura_original_id
    ),
    'factura_nueva', (
      SELECT jsonb_build_object('id', f.id, 'numero', f.numero, 'estado', f.estado,
                                'uuid_fiscal', f.uuid_fiscal, 'total', f.total, 'moneda', f.moneda,
                                'cancelado_en', f.cancelado_en)
      FROM public.facturas f WHERE f.id = v_c.factura_nueva_id
    ),
    'pagos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', p.id, 'factura_id', p.factura_id, 'fecha_pago', p.fecha_pago,
               'monto', p.monto, 'moneda', p.moneda, 'uuid_rep', p.uuid_rep,
               'estado_rep', p.estado_rep, 'rep_cancelado_en', p.rep_cancelado_en,
               'deleted_at', p.deleted_at, 'ordenante_nombre', p.ordenante_nombre,
               'ordenante_rfc', p.ordenante_rfc,
               'es_nuevo', (p.id = v_c.pago_nuevo_id)
             ) ORDER BY p.created_at)
      FROM public.pagos_factura p
      WHERE p.id IN (v_c.pago_original_id, v_c.pago_nuevo_id)
         OR p.refacturacion_id = v_c.id
    ), '[]'::jsonb),
    'eventos', COALESCE((
      SELECT jsonb_agg(e ORDER BY (e->>'ts'))
      FROM (
        SELECT jsonb_build_object(
                 'id', b.id,
                 'ts', b.created_at,
                 'accion', b.accion,
                 'usuario_email', COALESCE(NULLIF(b.usuario_email, ''),
                                           (SELECT email FROM auth.users WHERE id = b.usuario_id), ''),
                 'entidad_nombre', COALESCE(b.entidad_nombre, ''),
                 'detalles', COALESCE(b.detalles, '{}'::jsonb)
               ) AS e
        FROM public.bitacora_actividad b
        WHERE b.organization_id = v_c.organization_id
          AND (
            b.detalles->>'caso_id' = v_c.id::text
            OR (
              b.entidad_id IN (v_c.factura_original_id, v_c.factura_nueva_id)
              AND b.created_at >= v_c.created_at - interval '1 minute'
              AND b.accion IN (
                'refacturacion_abierta','refacturacion_borrador_creado',
                'refacturacion_pago_reasignado','refacturacion_completada','refacturacion_cancelada',
                'timbrar_factura','facturapi_emitida','actualizar_datos_timbrado_factura',
                'facturapi_cancelacion_solicitada','facturapi_cancelada','facturapi_cancelada_async',
                'facturapi_cancelar_failed','facturapi_rep_emitido','facturapi_rep_emitir_failed',
                'facturapi_rep_cancelacion_solicitada','facturapi_rep_cancelado',
                'facturapi_rep_cancelar_failed','facturapi_rep_cancelacion_rechazada',
                'registrar_pago','factura_enviada_email'
              )
            )
          )
      ) s
    ), '[]'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$$;
CREATE FUNCTION public.refacturacion_set_paso(p_caso_id uuid, p_paso smallint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.refacturaciones WHERE id = p_caso_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_REFACT_CASO_NO_ENCONTRADO' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public._assert_refacturador(v_org);
  IF p_paso < 1 OR p_paso > 5 THEN
    RAISE EXCEPTION 'LC_REFACT_PASO: paso fuera de rango' USING ERRCODE = 'P0001';
  END IF;
  UPDATE public.refacturaciones
     SET paso_actual = GREATEST(paso_actual, p_paso)
   WHERE id = p_caso_id AND estado = 'abierto';
END;
$$;
CREATE FUNCTION public.refacturacion_simular_paso(p_caso_id uuid, p_paso integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_c public.refacturaciones%ROWTYPE;
  v_old public.facturas%ROWTYPE;
  v_new public.facturas%ROWTYPE;
  v_pago public.pagos_factura%ROWTYPE;
  v_cancela jsonb := '[]'::jsonb;
  v_crea jsonb := '[]'::jsonb;
  v_bloqueos jsonb := '[]'::jsonb;
  v_pendientes jsonb := '[]'::jsonb;
  v_saldos jsonb := '[]'::jsonb;
  v_reasigna jsonb := NULL;
  v_saldo_old numeric := 0;
  v_saldo_new numeric := 0;
  v_aplicado numeric := 0;
  v_reps_bloq int := 0;
  v_reps_verif int := 0;
  v_cs text;
  v_moneda text;
BEGIN
  SELECT * INTO v_c FROM public.refacturaciones WHERE id = p_caso_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_CASO_NO_ENCONTRADO' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public._assert_refacturador(v_c.organization_id);
  SELECT * INTO v_old FROM public.facturas WHERE id = v_c.factura_original_id;
  v_moneda := COALESCE(v_old.moneda, 'MXN');
  v_saldo_old := public.saldo_factura(v_c.factura_original_id);
  v_cs := COALESCE(v_old.cancellation_status, '');
  IF v_c.factura_nueva_id IS NOT NULL THEN
    SELECT * INTO v_new FROM public.facturas WHERE id = v_c.factura_nueva_id;
    v_saldo_new := public.saldo_factura(v_c.factura_nueva_id);
  END IF;
  -- Pago de referencia: el elegido en el caso o el mayor aplicado a la original.
  IF v_c.pago_original_id IS NOT NULL THEN
    SELECT * INTO v_pago FROM public.pagos_factura WHERE id = v_c.pago_original_id;
  ELSE
    SELECT * INTO v_pago FROM public.pagos_factura
    WHERE factura_id = v_c.factura_original_id AND deleted_at IS NULL
    ORDER BY COALESCE(monto_aplicado_factura, monto) DESC NULLS LAST
    LIMIT 1;
  END IF;
  v_aplicado := COALESCE(v_pago.monto_aplicado_factura, v_pago.monto, 0);
  SELECT r.bloqueantes, r.en_verificacion
    INTO v_reps_bloq, v_reps_verif
  FROM public._refact_reps_bloqueantes(v_c.factura_original_id) r;
  IF p_paso = 2 THEN
    -- Cancelar los complementos de pago (REP) vivos de la factura original.
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'tipo', 'rep',
             'etiqueta', format('REP del pago del %s', to_char(pf.fecha_pago, 'DD/MM/YYYY')),
             'detalle', COALESCE(pf.uuid_rep, ''),
             'monto', COALESCE(pf.monto_aplicado_factura, pf.monto),
             'moneda', pf.moneda)), '[]'::jsonb)
      INTO v_cancela
    FROM public.pagos_factura pf
    WHERE pf.factura_id = v_c.factura_original_id
      AND pf.deleted_at IS NULL
      AND pf.uuid_rep IS NOT NULL
      AND pf.rep_cancelado_en IS NULL;
    IF v_reps_bloq > 0 THEN
      v_bloqueos := v_bloqueos || to_jsonb('LC_REFACT_REP_VIVO'::text);
    END IF;
    IF v_reps_verif > 0 THEN
      v_pendientes := v_pendientes || to_jsonb('LC_REFACT_REP_EN_VERIFICACION'::text);
    END IF;
    v_saldos := jsonb_build_array(jsonb_build_object(
      'concepto', format('Factura %s', COALESCE(v_old.numero, 'original')),
      'antes', v_saldo_old, 'despues', v_saldo_old, 'moneda', v_moneda,
      'nota', 'El pago sigue aplicado; sólo se invalida el complemento fiscal.'));
  ELSIF p_paso = 3 THEN
    IF v_c.factura_nueva_id IS NULL THEN
      v_crea := jsonb_build_array(jsonb_build_object(
        'tipo', 'factura',
        'etiqueta', 'Nueva factura (borrador) al receptor correcto',
        'detalle', 'Copia los conceptos, impuestos y moneda de la original',
        'monto', COALESCE(v_old.total, 0), 'moneda', v_moneda));
      v_bloqueos := v_bloqueos || to_jsonb('LC_REFACT_SIN_FACTURA_NUEVA'::text);
    ELSE
      v_crea := jsonb_build_array(jsonb_build_object(
        'tipo', 'factura',
        'etiqueta', format('Factura %s · %s', COALESCE(v_new.numero, 'nueva'), COALESCE(v_new.cliente_nombre, '')),
        'detalle', COALESCE(v_new.uuid_fiscal, 'Pendiente de timbrar'),
        'monto', COALESCE(v_new.total, 0), 'moneda', COALESCE(v_new.moneda, v_moneda)));
      IF v_new.uuid_fiscal IS NULL OR v_new.estado IN ('Borrador', 'Cancelada', 'Sustituida') THEN
        v_bloqueos := v_bloqueos || to_jsonb('LC_REFACT_NUEVA_NO_TIMBRADA'::text);
      END IF;
    END IF;
    IF v_reps_verif > 0 THEN
      v_pendientes := v_pendientes || to_jsonb('LC_REFACT_REP_EN_VERIFICACION'::text);
    END IF;
    v_saldos := jsonb_build_array(
      jsonb_build_object('concepto', format('Factura %s', COALESCE(v_new.numero, 'nueva')),
        'antes', v_saldo_new, 'despues', COALESCE(v_new.total, v_old.total, 0),
        'moneda', COALESCE(v_new.moneda, v_moneda),
        'nota', 'Nace sin pagos aplicados: queda con saldo por cobrar.'));
  ELSIF p_paso = 4 THEN
    v_cancela := jsonb_build_array(jsonb_build_object(
      'tipo', 'factura',
      'etiqueta', format('Factura %s · %s', COALESCE(v_old.numero, 'original'), COALESCE(v_old.cliente_nombre, '')),
      'detalle', CASE WHEN v_c.ruta_fiscal = '01'
                      THEN 'Motivo 01: sustituida por la nueva factura'
                      ELSE 'Motivo 02: cancelación sin relación' END,
      'monto', COALESCE(v_old.total, 0), 'moneda', v_moneda));
    IF v_reps_bloq > 0 THEN
      v_bloqueos := v_bloqueos || to_jsonb('LC_REFACT_REP_VIVO'::text);
    END IF;
    IF v_reps_verif > 0 THEN
      v_pendientes := v_pendientes || to_jsonb('LC_REFACT_REP_EN_VERIFICACION'::text);
    END IF;
    IF v_old.estado IN ('Cancelada', 'Sustituida') THEN
      v_bloqueos := v_bloqueos || to_jsonb('LC_REFACT_ORIGINAL_YA_CANCELADA'::text);
    ELSIF v_cs IN ('pending', 'verifying') THEN
      v_pendientes := v_pendientes || to_jsonb('LC_REFACT_ORIGINAL_EN_VERIFICACION'::text);
    ELSIF v_cs IN ('rejected', 'expired') THEN
      v_bloqueos := v_bloqueos || to_jsonb('LC_REFACT_ORIGINAL_CANCELACION_RECHAZADA'::text);
    END IF;
    v_saldos := jsonb_build_array(jsonb_build_object(
      'concepto', format('Factura %s', COALESCE(v_old.numero, 'original')),
      'antes', v_saldo_old, 'despues', 0, 'moneda', v_moneda,
      'nota', 'Al cancelarse deja de sumar a la cartera del cliente original.'));
  ELSIF p_paso = 5 THEN
    IF v_pago.id IS NOT NULL AND v_c.factura_nueva_id IS NOT NULL THEN
      v_reasigna := jsonb_build_object(
        'pago_fecha', v_pago.fecha_pago,
        'de', COALESCE(v_old.numero, 'original'),
        'a', COALESCE(v_new.numero, 'nueva'),
        'monto', v_aplicado,
        'moneda', v_pago.moneda,
        'ordenante_nombre', v_pago.ordenante_nombre,
        'ordenante_rfc', v_pago.ordenante_rfc);
      v_crea := jsonb_build_array(jsonb_build_object(
        'tipo', 'rep',
        'etiqueta', format('Nuevo REP de %s', COALESCE(v_new.numero, 'la nueva factura')),
        'detalle', 'Se timbra con el ordenante real del depósito',
        'monto', v_aplicado, 'moneda', v_pago.moneda));
    ELSE
      v_bloqueos := v_bloqueos || to_jsonb('LC_REFACT_SIN_FACTURA_NUEVA'::text);
    END IF;
    IF v_pago.moneda IS NOT NULL AND v_new.id IS NOT NULL AND v_pago.moneda <> COALESCE(v_new.moneda, v_pago.moneda) THEN
      v_bloqueos := v_bloqueos || to_jsonb('LC_REFACT_MONEDA_INCONSISTENTE'::text);
    END IF;
    -- En el paso 5 cualquier REP vivo (aun en verificación) impide mover el pago:
    -- el SAT reportaría el mismo depósito dos veces.
    IF v_reps_bloq + v_reps_verif > 0 THEN
      v_bloqueos := v_bloqueos || to_jsonb('LC_REFACT_REP_VIVO'::text);
    END IF;
    IF v_cs IN ('pending', 'verifying') AND v_old.estado NOT IN ('Cancelada', 'Sustituida') THEN
      v_pendientes := v_pendientes || to_jsonb('LC_REFACT_ORIGINAL_EN_VERIFICACION'::text);
    END IF;
    v_saldos := jsonb_build_array(
      jsonb_build_object('concepto', format('Factura %s', COALESCE(v_old.numero, 'original')),
        'antes', v_saldo_old, 'despues', 0, 'moneda', v_moneda,
        'nota', 'Cancelada: el pago deja de estar aplicado aquí.'),
      jsonb_build_object('concepto', format('Factura %s', COALESCE(v_new.numero, 'nueva')),
        'antes', v_saldo_new, 'despues', GREATEST(COALESCE(v_new.total, 0) - v_aplicado, 0),
        'moneda', COALESCE(v_new.moneda, v_moneda),
        'nota', 'Recibe el pago reasignado.'));
  ELSE
    -- Paso 1: sólo abre el expediente, no hay movimientos fiscales.
    v_saldos := jsonb_build_array(jsonb_build_object(
      'concepto', format('Factura %s', COALESCE(v_old.numero, 'original')),
      'antes', v_saldo_old, 'despues', v_saldo_old, 'moneda', v_moneda,
      'nota', 'Abrir el caso no modifica saldos ni CFDI.'));
  END IF;
  RETURN jsonb_build_object(
    'paso', p_paso,
    'cancela', v_cancela,
    'crea', v_crea,
    'reasigna', v_reasigna,
    'saldos', v_saldos,
    'bloqueos', v_bloqueos,
    'pendientes', v_pendientes
  );
END;
$$;
CREATE FUNCTION public.refacturacion_validar_consistencia(p_caso_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_c public.refacturaciones%ROWTYPE;
  v_old public.facturas%ROWTYPE;
  v_new public.facturas%ROWTYPE;
  v_h jsonb := '[]'::jsonb;
  v_sum_old numeric;
  v_sum_new numeric;
  v_dif int;
  v_pago numeric;
BEGIN
  SELECT * INTO v_c FROM public.refacturaciones WHERE id = p_caso_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_REFACT_CASO_NO_ENCONTRADO' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public._assert_refacturador(v_c.organization_id);
  SELECT * INTO v_old FROM public.facturas WHERE id = v_c.factura_original_id;
  IF v_c.factura_nueva_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'hallazgos', jsonb_build_array(jsonb_build_object(
        'codigo', 'LC_REFACT_SIN_FACTURA_NUEVA',
        'mensaje', 'Todavía no se ha generado la nueva factura.'))
    );
  END IF;
  SELECT * INTO v_new FROM public.facturas WHERE id = v_c.factura_nueva_id;
  -- Receptor
  IF NOT public._rfc_valido(v_new.rfc_cliente, false) THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_RFC_INVALIDO',
      'mensaje', 'El RFC del receptor de la nueva factura no tiene formato válido del SAT.');
  END IF;
  IF v_new.cliente_id IS DISTINCT FROM v_c.cliente_destino_id THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_RECEPTOR_INCOMPLETO',
      'mensaje', 'La nueva factura no está emitida al cliente destino del caso.');
  END IF;
  -- Moneda y tipo de cambio
  IF v_new.moneda <> v_old.moneda THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_MONEDA_INCONSISTENTE',
      'mensaje', format('La factura original está en %s y la nueva en %s.', v_old.moneda, v_new.moneda));
  END IF;
  IF v_new.moneda <> 'MXN' AND COALESCE(v_new.tipo_cambio, 0) <= 0 THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_TC_REQUERIDO',
      'mensaje', 'Falta el tipo de cambio de la nueva factura.');
  END IF;
  -- Importes
  IF ROUND(COALESCE(v_new.subtotal, 0), 2) <> ROUND(COALESCE(v_old.subtotal, 0), 2) THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_TOTAL_INCONSISTENTE',
      'mensaje', 'El subtotal de la nueva factura no coincide con el de la original.');
  END IF;
  IF ROUND(COALESCE(v_new.total, 0), 2) <> ROUND(COALESCE(v_old.total, 0), 2) THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_TOTAL_INCONSISTENTE',
      'mensaje', 'El total de la nueva factura no coincide con el de la original.');
  END IF;
  IF ROUND(COALESCE(v_new.iva, 0), 2) <> ROUND(COALESCE(v_old.iva, 0), 2)
     OR ROUND(COALESCE(v_new.ret_isr, 0), 2) <> ROUND(COALESCE(v_old.ret_isr, 0), 2)
     OR ROUND(COALESCE(v_new.ret_iva, 0), 2) <> ROUND(COALESCE(v_old.ret_iva, 0), 2) THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_IMPUESTOS_INCONSISTENTES',
      'mensaje', 'Los impuestos trasladados o las retenciones no coinciden con la factura original.');
  END IF;
  -- Conceptos: mismas claves SAT y tasas
  SELECT COALESCE(SUM(total), 0) INTO v_sum_old
  FROM public.conceptos_factura WHERE factura_id = v_old.id AND deleted_at IS NULL;
  SELECT COALESCE(SUM(total), 0) INTO v_sum_new
  FROM public.conceptos_factura WHERE factura_id = v_new.id AND deleted_at IS NULL;
  IF ROUND(v_sum_old, 2) <> ROUND(v_sum_new, 2) THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_TOTAL_INCONSISTENTE',
      'mensaje', 'La suma de los conceptos de la nueva factura no coincide con la original.');
  END IF;
  SELECT COUNT(*) INTO v_dif FROM (
    SELECT clave_sat, tipo_iva, tasa_iva_aplicada, tasa_ret_isr, tasa_ret_iva, COUNT(*) AS n
      FROM public.conceptos_factura WHERE factura_id = v_old.id AND deleted_at IS NULL
      GROUP BY 1,2,3,4,5
    EXCEPT
    SELECT clave_sat, tipo_iva, tasa_iva_aplicada, tasa_ret_isr, tasa_ret_iva, COUNT(*) AS n
      FROM public.conceptos_factura WHERE factura_id = v_new.id AND deleted_at IS NULL
      GROUP BY 1,2,3,4,5
  ) d;
  IF v_dif > 0 THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_IMPUESTOS_INCONSISTENTES',
      'mensaje', 'Las claves del SAT o las tasas de impuesto de los conceptos difieren de la factura original.');
  END IF;
  -- Ruta 01: relación de sustitución
  IF v_c.ruta_fiscal = '01' AND v_new.sustituye_a IS DISTINCT FROM v_old.id THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_SUSTITUCION_FALTANTE',
      'mensaje', 'La ruta de sustitución requiere relacionar la nueva factura con el CFDI original.');
  END IF;
  -- Depósito
  SELECT COALESCE(SUM(monto_aplicado_factura), 0) INTO v_pago
  FROM public.pagos_factura
  WHERE factura_id = v_new.id AND deleted_at IS NULL;
  IF ROUND(v_pago, 2) > ROUND(COALESCE(v_new.total, 0), 2) + 0.01 THEN
    v_h := v_h || jsonb_build_object('codigo', 'LC_REFACT_SOBREPAGO',
      'mensaje', 'El pago aplicado excede el total de la nueva factura.');
  END IF;
  RETURN jsonb_build_object(
    'ok', jsonb_array_length(v_h) = 0,
    'hallazgos', v_h,
    'factura_original', jsonb_build_object('numero', v_old.numero, 'moneda', v_old.moneda,
      'subtotal', v_old.subtotal, 'iva', v_old.iva, 'ret_isr', COALESCE(v_old.ret_isr, 0),
      'ret_iva', COALESCE(v_old.ret_iva, 0), 'total', v_old.total, 'tipo_cambio', v_old.tipo_cambio),
    'factura_nueva', jsonb_build_object('numero', v_new.numero, 'moneda', v_new.moneda,
      'subtotal', v_new.subtotal, 'iva', v_new.iva, 'ret_isr', COALESCE(v_new.ret_isr, 0),
      'ret_iva', COALESCE(v_new.ret_iva, 0), 'total', v_new.total, 'tipo_cambio', v_new.tipo_cambio),
    'pago_aplicado', v_pago
  );
END;
$$;
CREATE FUNCTION public.refrescar_garantia_desde_tarifa(p_embarque_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_naviera_nombre text;
  v_tarifa_id uuid;
  v_naviera_id uuid;
  v_cond record;
  v_carta_vigente boolean := false;
  v_monto numeric(12,2) := 0;
  v_estado text := 'pendiente';
  v_updated int := 0;
BEGIN
  SELECT e.organization_id, e.naviera, e.tarifa_id_aplicada
    INTO v_org, v_naviera_nombre, v_tarifa_id
  FROM public.embarques e WHERE e.id = p_embarque_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_EMBARQUE_NO_ENCONTRADO';
  END IF;
  IF NOT (v_org = public.org_scope()) THEN
    RAISE EXCEPTION 'LC_NO_AUTORIZADO';
  END IF;
  -- Resolver naviera desde tarifa o por nombre
  IF v_tarifa_id IS NOT NULL THEN
    SELECT t.naviera_id INTO v_naviera_id
    FROM public.costeo_tarifas t WHERE t.id = v_tarifa_id;
  END IF;
  IF v_naviera_id IS NULL AND v_naviera_nombre IS NOT NULL AND v_naviera_nombre <> '' THEN
    SELECT n.id INTO v_naviera_id FROM public.navieras n
    WHERE lower(n.name) = lower(v_naviera_nombre) LIMIT 1;
  END IF;
  IF v_naviera_id IS NULL THEN
    RETURN 0;
  END IF;
  SELECT * INTO v_cond FROM public.costeo_navieras_condiciones
  WHERE organization_id = v_org AND naviera_id = v_naviera_id LIMIT 1;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;
  v_carta_vigente := v_cond.tiene_carta_garantia
    AND (v_cond.carta_garantia_vigente_hasta IS NULL OR v_cond.carta_garantia_vigente_hasta >= CURRENT_DATE);
  IF v_carta_vigente THEN
    v_monto := 0;
    v_estado := 'liberado';
  ELSE
    v_monto := COALESCE(v_cond.deposito_contenedor_usd, 0);
    v_estado := 'pendiente';
  END IF;
  UPDATE public.embarque_garantias_contenedor g
     SET monto_deposito_usd = v_monto,
         tiene_carta_garantia = v_carta_vigente,
         naviera_id = v_naviera_id,
         estado = CASE WHEN v_carta_vigente THEN 'liberado' ELSE g.estado END
   WHERE g.embarque_id = p_embarque_id
     AND g.estado = 'pendiente';
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;
CREATE FUNCTION public.regenerar_movimiento_pago_proveedor(p_pago_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pago         public.pagos_proveedor;
  v_org          uuid;
  v_cuenta_mon   text;
  v_cargo        numeric;
  v_concepto     text;
  v_mov_id       uuid;
BEGIN
  SELECT * INTO v_pago
  FROM public.pagos_proveedor
  WHERE id = p_pago_id AND deleted_at IS NULL;
  IF v_pago.id IS NULL THEN
    RAISE EXCEPTION 'LC_MOVIMIENTO_PAGO_INEXISTENTE: el pago de proveedor no existe o está eliminado'
      USING ERRCODE = 'P0001';
  END IF;
  -- Ola 6 · RG5-1: fail-closed. Sin organización resuelta no hay forma de
  -- validar la pertenencia del pago: se niega.
  v_org := public.org_scope();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_SIN_ORG: no hay organización activa para validar el pago; selecciona una organización antes de regenerar el movimiento'
      USING ERRCODE = '42501';
  END IF;
  IF v_pago.organization_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'LC_ORG_MISMATCH: el pago pertenece a otra organización'
      USING ERRCODE = 'P0001';
  END IF;
  IF NOT (
    public.has_any_role(auth.uid(), ARRAY['tesorero','contador','admin','admin_org','super_admin']::app_role[])
  ) THEN
    RAISE EXCEPTION 'LC_MOVIMIENTO_SIN_PERMISO: se requiere permiso de tesorería para regenerar el movimiento bancario'
      USING ERRCODE = 'P0001';
  END IF;
  IF v_pago.cuenta_bancaria_id IS NULL THEN
    RAISE EXCEPTION 'LC_MOVIMIENTO_SIN_CUENTA: el pago no tiene cuenta bancaria, no hay movimiento que generar'
      USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.bbva_movimientos
    WHERE pago_proveedor_id = p_pago_id AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'LC_MOVIMIENTO_YA_EXISTE: el pago ya tiene un movimiento bancario vigente'
      USING ERRCODE = 'P0001';
  END IF;
  SELECT moneda::text INTO v_cuenta_mon
  FROM public.cuentas_bancarias
  WHERE id = v_pago.cuenta_bancaria_id AND deleted_at IS NULL;
  IF v_cuenta_mon IS NULL THEN
    RAISE EXCEPTION 'LC_MOVIMIENTO_SIN_CUENTA: la cuenta bancaria del pago no existe o está dada de baja'
      USING ERRCODE = 'P0001';
  END IF;
  -- El movimiento SIEMPRE se registra en la moneda de la cuenta.
  v_cargo := v_pago.monto;
  IF v_cuenta_mon IS DISTINCT FROM v_pago.moneda::text THEN
    -- Ola 11 · RBD-07 (clase BL-04): nunca 1:1 silencioso cross-moneda.
    IF COALESCE(v_pago.tipo_cambio_usd, 0) <= 0 THEN
      RAISE EXCEPTION 'LC_PAGO_TC_REQUERIDO: el pago es en % y la cuenta en %, pero el pago no tiene tipo de cambio registrado; captura el TC en el pago antes de regenerar el movimiento',
        v_pago.moneda, v_cuenta_mon
        USING ERRCODE = 'P0001';
    END IF;
    IF v_pago.moneda::text = 'USD' AND v_cuenta_mon = 'MXN' THEN
      v_cargo := v_pago.monto * v_pago.tipo_cambio_usd;
    ELSIF v_pago.moneda::text = 'MXN' AND v_cuenta_mon = 'USD' THEN
      v_cargo := v_pago.monto / v_pago.tipo_cambio_usd;
    END IF;
  END IF;
  SELECT 'Pago prov. '
         || COALESCE(NULLIF(pf.folio_proveedor, ''), NULLIF(pf.folio_interno, ''), 's/folio')
         || ' — ' || COALESCE(pr.nombre, pf.proveedor_nombre, 'proveedor')
    INTO v_concepto
  FROM public.proveedor_facturas pf
  LEFT JOIN public.proveedores pr ON pr.id = pf.proveedor_id
  WHERE pf.id = v_pago.proveedor_factura_id;
  INSERT INTO public.bbva_movimientos (
    organization_id, cuenta_bancaria_id, fecha, concepto, referencia,
    cargo, abono, hash_dedupe, estado_conciliacion, pago_proveedor_id,
    conciliado_por, conciliado_at, importado_por
  ) VALUES (
    v_pago.organization_id, v_pago.cuenta_bancaria_id, v_pago.fecha_pago,
    COALESCE(v_concepto, 'Pago a proveedor'), COALESCE(v_pago.referencia, ''),
    ROUND(v_cargo, 2), 0, 'pago-' || p_pago_id::text, 'Conciliado', p_pago_id,
    auth.uid(), now(), auth.uid()
  )
  RETURNING id INTO v_mov_id;
  RETURN v_mov_id;
END;
$$;
CREATE FUNCTION public.registrar_anticipo_proveedor(p_proveedor_id uuid, p_monto numeric, p_moneda public.moneda, p_fecha_anticipo date DEFAULT CURRENT_DATE, p_tipo_cambio_usd numeric DEFAULT NULL::numeric, p_metodo_pago text DEFAULT NULL::text, p_referencia text DEFAULT NULL::text, p_cuenta_bancaria_id uuid DEFAULT NULL::uuid, p_notas text DEFAULT NULL::text, p_embarque_id uuid DEFAULT NULL::uuid, p_request_id uuid DEFAULT NULL::uuid) RETURNS public.anticipos_proveedor
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.anticipos_proveedor;
  v_uid uuid := auth.uid();
  v_org uuid;
  v_email text;
  v_autorizado boolean;
  v_metodo text := COALESCE(NULLIF(TRIM(p_metodo_pago), ''), 'Transferencia');
  v_cuenta public.cuentas_bancarias;
  v_proveedor_nombre text;
  v_emb_org uuid;
  v_cached jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  -- O2.5: reclamo atómico de la llave (patrón bl05/bl08). Doble submit del
  -- diálogo ya no crea dos anticipos ni dos cargos bancarios conciliados.
  v_cached := public.idempotency_claim(p_request_id, 'registrar_anticipo_proveedor');
  IF v_cached IS NOT NULL THEN
    IF COALESCE((v_cached->>'__idempotency_pending')::boolean, false) THEN
      RAISE EXCEPTION 'LC_ANTICIPO_EN_PROCESO: Este anticipo ya se está registrando; espera unos segundos y verifica el listado antes de reintentar.'
        USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_row FROM public.anticipos_proveedor
    WHERE id = (v_cached->>'anticipo_id')::uuid;
    IF v_row.id IS NOT NULL THEN
      RETURN v_row;
    END IF;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid
      AND ur.role::text = ANY (ARRAY['admin','admin_org','super_admin','contador','tesorero'])
  ) INTO v_autorizado;
  IF NOT v_autorizado THEN
    RAISE EXCEPTION 'LC_ANTICIPO_SIN_ROL: Sólo administradores, contabilidad o tesorería pueden registrar anticipos.'
      USING ERRCODE = '42501';
  END IF;
  IF p_monto IS NULL OR p_monto <= 0 THEN
    RAISE EXCEPTION 'LC_ANTICIPO_MONTO_INVALIDO: El monto debe ser mayor a cero.';
  END IF;
  SELECT organization_id, nombre INTO v_org, v_proveedor_nombre
  FROM public.proveedores WHERE id = p_proveedor_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_ANTICIPO_PROVEEDOR_NO_EXISTE: El proveedor no existe.';
  END IF;
  IF v_org IS DISTINCT FROM public.current_user_org_id() AND NOT public.has_role(v_uid,'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_ANTICIPO_PROVEEDOR_OTRA_ORG: El proveedor pertenece a otra organización.';
  END IF;
  IF p_embarque_id IS NOT NULL THEN
    SELECT organization_id INTO v_emb_org FROM public.embarques WHERE id = p_embarque_id;
    IF v_emb_org IS NULL OR v_emb_org <> v_org THEN
      RAISE EXCEPTION 'LC_ANTICIPO_EMBARQUE_INVALIDO: El embarque no existe o pertenece a otra organización.';
    END IF;
  END IF;
  -- Sin cuenta bancaria el anticipo no genera movimiento conciliable.
  IF p_cuenta_bancaria_id IS NULL AND v_metodo <> 'Efectivo' THEN
    RAISE EXCEPTION 'LC_ANTICIPO_CUENTA_REQUERIDA: Selecciona la cuenta bancaria de donde sale el anticipo (sólo Efectivo puede omitirla).';
  END IF;
  IF p_cuenta_bancaria_id IS NOT NULL THEN
    SELECT * INTO v_cuenta FROM public.cuentas_bancarias
    WHERE id = p_cuenta_bancaria_id AND deleted_at IS NULL;
    IF v_cuenta.id IS NULL THEN
      RAISE EXCEPTION 'LC_ANTICIPO_CUENTA_INVALIDA: La cuenta bancaria no existe o está dada de baja.';
    END IF;
    IF v_cuenta.organization_id <> v_org THEN
      RAISE EXCEPTION 'LC_ANTICIPO_CUENTA_OTRA_ORG: La cuenta bancaria pertenece a otra organización.';
    END IF;
    IF v_cuenta.moneda <> p_moneda THEN
      RAISE EXCEPTION 'LC_ANTICIPO_CUENTA_DIVISA: La cuenta está en % y el anticipo en %.', v_cuenta.moneda, p_moneda;
    END IF;
  END IF;
  INSERT INTO public.anticipos_proveedor
    (organization_id, proveedor_id, fecha_anticipo, monto, moneda, tipo_cambio_usd,
     metodo_pago, referencia, cuenta_bancaria_id, notas,
     estado, saldo_disponible, created_by, embarque_id)
  VALUES
    (v_org, p_proveedor_id, p_fecha_anticipo, p_monto, p_moneda, p_tipo_cambio_usd,
     v_metodo, p_referencia, p_cuenta_bancaria_id, p_notas,
     'disponible', p_monto, v_uid, p_embarque_id)
  RETURNING * INTO v_row;
  -- Cargo bancario conciliado (el saldo de la cuenta baja de inmediato).
  IF p_cuenta_bancaria_id IS NOT NULL THEN
    INSERT INTO public.bbva_movimientos
      (organization_id, cuenta_bancaria_id, fecha, concepto, referencia,
       cargo, abono, hash_dedupe, estado_conciliacion,
       anticipo_proveedor_id, conciliado_por, conciliado_at, importado_por)
    VALUES
      (v_org, p_cuenta_bancaria_id, p_fecha_anticipo,
       'Anticipo — ' || COALESCE(v_proveedor_nombre, 'proveedor'),
       COALESCE(p_referencia, ''),
       p_monto, 0, 'anticipo-' || v_row.id::text, 'Conciliado',
       v_row.id, v_uid, now(), v_uid);
  END IF;
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (v_org, v_uid, COALESCE(v_email,''), 'registrar_anticipo_proveedor', 'cxp',
            v_row.id, 'Anticipo ' || v_row.id::text,
            jsonb_build_object('proveedor_id', p_proveedor_id, 'monto', p_monto, 'moneda', p_moneda,
                               'cuenta_bancaria_id', p_cuenta_bancaria_id, 'metodo_pago', v_metodo,
                               'embarque_id', p_embarque_id));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en registrar_anticipo_proveedor: % %', SQLSTATE, SQLERRM;
  END;
  PERFORM public.idempotency_store(p_request_id,
    jsonb_build_object('anticipo_id', v_row.id, 'monto', p_monto));
  RETURN v_row;
END;
$$;
CREATE FUNCTION public.registrar_bitacora(p_modulo text, p_accion text, p_entidad_id uuid DEFAULT NULL::uuid, p_entidad_nombre text DEFAULT ''::text, p_detalles jsonb DEFAULT '{}'::jsonb, p_organization_id uuid DEFAULT NULL::uuid, p_usuario_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := COALESCE(p_usuario_id, auth.uid());
  v_org uuid := p_organization_id;
  v_email text;
BEGIN
  -- FIX BL-02: con JWT de usuario solo se puede escribir con identidad propia y
  -- en una organización de la que el usuario sea miembro. service_role y
  -- llamadas internas sin JWT de usuario quedan fuera del guard.
  IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL THEN
    v_uid := auth.uid();
    IF v_org IS NOT NULL
       AND v_org IS DISTINCT FROM public.current_user_org_id()
       AND NOT EXISTS (
         SELECT 1 FROM public.organization_members om
          WHERE om.user_id = auth.uid() AND om.organization_id = v_org
       )
       AND NOT public.has_role(auth.uid(), 'super_admin'::app_role) THEN
      RAISE EXCEPTION 'LC_ORG_AJENA: no puedes registrar bitácora de otra organización'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  IF v_org IS NULL AND v_uid IS NOT NULL THEN
    SELECT organization_id INTO v_org
      FROM public.organization_members WHERE user_id = v_uid LIMIT 1;
  END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
  INSERT INTO public.bitacora_actividad(
    organization_id, usuario_id, usuario_email, accion, modulo,
    entidad_id, entidad_nombre, detalles
  ) VALUES (
    v_org, v_uid, COALESCE(v_email, ''), p_accion, p_modulo,
    p_entidad_id, COALESCE(p_entidad_nombre, ''), COALESCE(p_detalles, '{}'::jsonb)
  );
EXCEPTION
  WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
    RAISE WARNING 'registrar_bitacora falló (%): %', p_accion, SQLERRM;
END;
$$;
CREATE FUNCTION public.registrar_comision_pendiente(p_organization_id uuid, p_pago_factura_id uuid, p_etapa text, p_motivo text, p_sqlstate text, p_sqlerrm text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.comisiones_recalculo_pendiente
    (organization_id, pago_factura_id, etapa, motivo, sqlstate_code, sqlerrm_text)
  VALUES
    (p_organization_id, p_pago_factura_id, p_etapa,
     COALESCE(p_motivo, ''), COALESCE(p_sqlstate, ''), COALESCE(p_sqlerrm, ''))
  ON CONFLICT (pago_factura_id, etapa) WHERE resuelto_at IS NULL
  DO UPDATE SET
    intentos = public.comisiones_recalculo_pendiente.intentos + 1,
    sqlstate_code = EXCLUDED.sqlstate_code,
    sqlerrm_text = EXCLUDED.sqlerrm_text,
    updated_at = now();
END;
$$;
CREATE FUNCTION public.registrar_pago_cliente_lote(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_cliente_id uuid := (p_payload->>'cliente_id')::uuid;
  v_fecha date := COALESCE((p_payload->>'fecha_pago')::date, CURRENT_DATE);
  v_moneda public.moneda := (p_payload->>'moneda')::public.moneda;
  v_tc numeric := NULLIF(p_payload->>'tipo_cambio_usd','')::numeric;
  -- Ola 5 · RG4-5: importe real recibido del cliente (nuevo en el payload).
  v_importe numeric := NULLIF(p_payload->>'importe_recibido','')::numeric;
  v_forma text := COALESCE(NULLIF(TRIM(p_payload->>'forma_pago'), ''), '03');
  v_referencia text := COALESCE(NULLIF(TRIM(p_payload->>'referencia'), ''), '');
  v_cuenta_id uuid := NULLIF(p_payload->>'cuenta_bancaria_id','')::uuid;
  v_notas text := COALESCE(p_payload->>'notas','');
  -- Ola 11 · RNF-01: llave de idempotencia del cliente (opcional).
  v_request_id uuid := NULLIF(p_payload->>'request_id','')::uuid;
  v_cached jsonb;
  v_resp jsonb;
  v_cuenta public.cuentas_bancarias;
  v_cliente_nombre text;
  v_total numeric := 0;
  v_lote_id uuid;
  v_renglon jsonb;
  v_factura_id uuid;
  v_monto numeric;
  v_saldo numeric;
  v_fecha_emision date;
  v_pago_id uuid;
  v_n int := 0;
  v_pagos jsonb := '[]'::jsonb;
  v_email text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado' USING ERRCODE = '42501';
  END IF;
  -- Ola 11 · RNF-01: reclamo atómico de la llave. Reintento del mismo
  -- submit → respuesta almacenada; ejecución aún en vuelo → rechazo claro.
  v_cached := public.idempotency_claim(v_request_id, 'registrar_pago_cliente_lote');
  IF v_cached IS NOT NULL THEN
    IF COALESCE((v_cached->>'__idempotency_pending')::boolean, false) THEN
      RAISE EXCEPTION 'LC_COBRO_LOTE_EN_PROCESO: Este cobro en lote ya está en proceso; espera unos segundos y verifica el historial antes de reintentar.'
        USING ERRCODE = '42501';
    END IF;
    RETURN v_cached;
  END IF;
  SELECT organization_id, nombre INTO v_org, v_cliente_nombre
  FROM public.clientes WHERE id = v_cliente_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_COBRO_LOTE_CLIENTE_NO_EXISTE: El cliente no existe.';
  END IF;
  IF v_org <> public.current_user_org_id()
     AND NOT public.has_role(v_uid,'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_COBRO_LOTE_CLIENTE_OTRA_ORG: El cliente pertenece a otra organización.';
  END IF;
  -- Ola 8 + FIX B-6: rol financiero por membresía en la organización del
  -- cliente, con la lista EXACTA previa al piloto {admin, admin_org,
  -- super_admin, contador, tesorero} y SIN expansión de jerarquía:
  -- `auxiliar_contable` queda fuera por decisión conservadora.
  IF NOT public.has_any_role_in_org_exact(v_uid,
       ARRAY['admin','admin_org','super_admin','contador','tesorero']::public.app_role[],
       v_org) THEN
    RAISE EXCEPTION 'LC_COBRO_LOTE_SIN_ROL: Sólo administración, contabilidad o tesorería pueden registrar cobros en lote.'
      USING ERRCODE = '42501';
  END IF;
  -- Ola 11 · RFE-02/RNF-03: misma regla que el cobro individual (FE-03).
  IF v_fecha > CURRENT_DATE THEN
    RAISE EXCEPTION 'LC_COBRO_LOTE_FECHA_FUTURA: La fecha del cobro no puede ser futura.'
      USING ERRCODE = '42501';
  END IF;
  -- Ola 11 · RFE-03 (patrón FE-01): lote extranjero sin TC no se registra.
  IF v_moneda <> 'MXN'::public.moneda AND (v_tc IS NULL OR v_tc <= 0) THEN
    RAISE EXCEPTION 'LC_COBRO_LOTE_TC_REQUERIDO: No hay tipo de cambio disponible para un cobro en %; reintenta cuando el servicio de tipos de cambio responda.', v_moneda
      USING ERRCODE = '42501';
  END IF;
  IF v_cuenta_id IS NOT NULL THEN
    SELECT * INTO v_cuenta FROM public.cuentas_bancarias
    WHERE id = v_cuenta_id AND deleted_at IS NULL;
    IF v_cuenta.id IS NULL THEN
      RAISE EXCEPTION 'LC_COBRO_LOTE_CUENTA_INVALIDA: La cuenta bancaria no existe o está dada de baja.';
    END IF;
    IF v_cuenta.organization_id <> v_org THEN
      RAISE EXCEPTION 'LC_COBRO_LOTE_CUENTA_OTRA_ORG: La cuenta bancaria pertenece a otra organización.';
    END IF;
    IF v_cuenta.moneda <> v_moneda THEN
      RAISE EXCEPTION 'LC_COBRO_LOTE_CUENTA_DIVISA: La cuenta está en % y el cobro en %.', v_cuenta.moneda, v_moneda;
    END IF;
  END IF;
  -- Ola 5 · RG4-6: una misma factura no puede aparecer dos veces.
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(COALESCE(p_payload->'renglones','[]'::jsonb)) AS r
    GROUP BY (r->>'factura_id')
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'LC_COBRO_LOTE_FACTURA_DUPLICADA: Hay facturas repetidas en el lote; cada factura sólo puede aparecer una vez.'
      USING ERRCODE = '42501';
  END IF;
  -- Validación de renglones: tenancy, cliente, moneda y saldo real por factura.
  -- BL-13 (migración 20260817143000): los locks FOR UPDATE se toman en orden
  -- determinista (factura_id), no en el orden del payload; dos lotes
  -- concurrentes con las mismas facturas en orden distinto hacían deadlock.
  FOR v_renglon IN
    SELECT r FROM jsonb_array_elements(COALESCE(p_payload->'renglones','[]'::jsonb)) AS r
    ORDER BY (r->>'factura_id')::uuid
  LOOP
    v_factura_id := (v_renglon->>'factura_id')::uuid;
    v_monto := ROUND(COALESCE((v_renglon->>'monto')::numeric, 0), 2);
    IF v_monto <= 0 THEN
      RAISE EXCEPTION 'LC_COBRO_LOTE_MONTO_INVALIDO: Cada factura del lote debe tener un importe mayor a cero.';
    END IF;
    -- Ola 1: las notas de crédito se restan CONVERTIDAS a la moneda de la
    -- factura (canon `public.nc_aplicadas_en_moneda_factura`); antes se sumaba
    -- `nc.monto` en crudo y una NC en USD inflaba el saldo de una factura MXN.
    SELECT
      f.total
      - COALESCE((SELECT SUM(pf.monto_aplicado_factura) FROM public.pagos_factura pf
                   WHERE pf.factura_id = f.id AND pf.deleted_at IS NULL), 0)
      - public.nc_aplicadas_en_moneda_factura(f.id),
      f.fecha_emision
      INTO v_saldo, v_fecha_emision
    FROM public.facturas f
    WHERE f.id = v_factura_id
      AND f.deleted_at IS NULL
      AND f.organization_id = v_org
      AND f.cliente_id = v_cliente_id
      AND f.moneda = v_moneda
    FOR UPDATE OF f;
    IF v_saldo IS NULL THEN
      RAISE EXCEPTION 'LC_COBRO_LOTE_FACTURA_INVALIDA: Una de las facturas no existe, no es del cliente seleccionado o está en otra moneda.';
    END IF;
    -- Ola 11 · RFE-02/RNF-03: no cobros anteriores a la emisión (aging/REP).
    IF v_fecha < v_fecha_emision THEN
      RAISE EXCEPTION 'LC_COBRO_LOTE_FECHA_PREVIA_EMISION: La fecha del cobro es anterior a la emisión de una de las facturas del lote.'
        USING ERRCODE = '42501';
    END IF;
    -- BUG-15: tolerancia unificada con el trigger tg_pago_factura_no_sobrepago
    -- (0.005 = medio centavo). Antes 0.009 aquí y 0.005 en el trigger: la RPC
    -- aceptaba sobrepagos que el trigger luego rechazaba.
    IF v_monto > ROUND(v_saldo, 2) + 0.005 THEN
      RAISE EXCEPTION 'LC_COBRO_LOTE_EXCEDE_SALDO: El importe aplicado a una factura excede su saldo pendiente.';
    END IF;
    v_total := v_total + v_monto;
    v_n := v_n + 1;
  END LOOP;
  IF v_n < 2 THEN
    RAISE EXCEPTION 'LC_COBRO_LOTE_MINIMO_FACTURAS: Un cobro en lote requiere al menos dos facturas.';
  END IF;
  -- Ola 5 · RG4-5: el reparto debe cuadrar EXACTAMENTE con el importe recibido.
  IF v_importe IS NULL OR v_importe <= 0 THEN
    RAISE EXCEPTION 'LC_COBRO_LOTE_IMPORTE_REQUERIDO: Captura el importe recibido del cliente.'
      USING ERRCODE = '42501';
  END IF;
  -- Ola 11 · RNF-02: exacto tras ROUND a 2 decimales (antes tolerancia 0.01,
  -- discrepante con los 0.009 del cliente y con el mensaje "EXACTO").
  IF ROUND(v_importe, 2) IS DISTINCT FROM ROUND(v_total, 2) THEN
    RAISE EXCEPTION 'LC_COBRO_LOTE_IMPORTE_NO_CUADRA: El reparto (%) no cuadra con el importe recibido (%); no se permite sobrante sin asignar.', v_total, v_importe
      USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.pagos_factura_lote
    (organization_id, cliente_id, fecha_pago, moneda, monto_total, tipo_cambio_usd,
     forma_pago, referencia, cuenta_bancaria_id, notas, created_by)
  VALUES
    (v_org, v_cliente_id, v_fecha, v_moneda, v_total, v_tc,
     v_forma, v_referencia, v_cuenta_id, v_notas, v_uid)
  RETURNING id INTO v_lote_id;
  FOR v_renglon IN SELECT * FROM jsonb_array_elements(COALESCE(p_payload->'renglones','[]'::jsonb)) LOOP
    v_factura_id := (v_renglon->>'factura_id')::uuid;
    v_monto := ROUND(COALESCE((v_renglon->>'monto')::numeric, 0), 2);
    INSERT INTO public.pagos_factura
      (organization_id, factura_id, fecha_pago, monto, moneda, tipo_cambio,
       monto_aplicado_factura, forma_pago, referencia, notas, created_by, lote_id)
    VALUES
      -- Ola 11 · RBD-08: el pago individual guarda el TC del lote en moneda
      -- extranjera (garantizado > 0 por LC_COBRO_LOTE_TC_REQUERIDO); en MXN
      -- se conserva 1 como antes.
      (v_org, v_factura_id, v_fecha, v_monto, v_moneda,
       CASE WHEN v_moneda = 'MXN'::public.moneda THEN 1 ELSE v_tc END,
       v_monto, v_forma, v_referencia, v_notas, v_uid, v_lote_id)
    RETURNING id INTO v_pago_id;
    v_pagos := v_pagos || jsonb_build_object('pago_id', v_pago_id, 'factura_id', v_factura_id);
  END LOOP;
  IF v_cuenta_id IS NOT NULL THEN
    INSERT INTO public.bbva_movimientos
      (organization_id, cuenta_bancaria_id, fecha, concepto, referencia,
       cargo, abono, hash_dedupe, estado_conciliacion,
       pago_factura_lote_id, conciliado_por, conciliado_at, importado_por)
    VALUES
      (v_org, v_cuenta_id, v_fecha,
       'Cobro en lote (' || v_n || ' facturas) — ' || COALESCE(v_cliente_nombre, 'cliente'),
       v_referencia, 0, v_total, 'cobro-lote-' || v_lote_id::text, 'Conciliado',
       v_lote_id, v_uid, now(), v_uid);
  END IF;
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (v_org, v_uid, COALESCE(v_email,''), 'registrar_pago_cliente_lote', 'facturacion',
            v_lote_id, 'Cobro en lote ' || v_lote_id::text,
            jsonb_build_object('cliente_id', v_cliente_id, 'monto_total', v_total,
                               'importe_recibido', v_importe,
                               'moneda', v_moneda, 'facturas', v_n,
                               'cuenta_bancaria_id', v_cuenta_id, 'referencia', v_referencia));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en registrar_pago_cliente_lote: % %', SQLSTATE, SQLERRM;
  END;
  v_resp := jsonb_build_object('lote_id', v_lote_id, 'monto_total', v_total, 'pagos', v_pagos);
  -- Ola 11 · RNF-01: almacena la respuesta para los reintentos con la
  -- misma llave (no-op cuando request_id viene NULL).
  PERFORM public.idempotency_store(v_request_id, v_resp);
  RETURN v_resp;
END;
$$;
CREATE FUNCTION public.registrar_pago_liquidacion(p_liquidacion_id uuid, p_fecha_pago date, p_metodo_pago text, p_referencia text DEFAULT NULL::text, p_notas text DEFAULT NULL::text) RETURNS public.liquidaciones_comision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.liquidaciones_comision;
  v_email text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado' USING ERRCODE = '42501';
  END IF;
  -- YG-02: primero la fila (con candado), después la autorización por org.
  SELECT * INTO v_row FROM public.liquidaciones_comision
  WHERE id = p_liquidacion_id AND deleted_at IS NULL
  FOR UPDATE;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_NO_EXISTE: La liquidación no existe.';
  END IF;
  IF v_row.organization_id IS DISTINCT FROM public.current_user_org_id()
     AND NOT public.has_role(v_uid,'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_OTRA_ORG: La liquidación pertenece a otra organización.';
  END IF;
  -- YG-02: rol financiero POR MEMBRESÍA en la org dueña de la liquidación,
  -- lista exacta {admin, admin_org, super_admin, contador, tesorero}.
  IF NOT public.has_any_role_in_org_exact(v_uid,
       ARRAY['admin','admin_org','super_admin','contador','tesorero']::public.app_role[],
       v_row.organization_id) THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_SIN_ROL: Sólo administración, contabilidad o tesorería pueden pagar liquidaciones.'
      USING ERRCODE = '42501';
  END IF;
  IF v_row.estado = 'Cancelada' THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_CANCELADA: La liquidación está cancelada; genera una nueva.'
      USING ERRCODE = '42501';
  END IF;
  IF v_row.fecha_pago IS NOT NULL OR v_row.estado = 'Pagada' THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_YA_PAGADA: Esta liquidación ya tiene un pago registrado el %.', v_row.fecha_pago
      USING ERRCODE = '42501';
  END IF;
  IF p_fecha_pago IS NULL OR p_fecha_pago > CURRENT_DATE THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_FECHA_FUTURA: La fecha del pago no puede ser futura.'
      USING ERRCODE = '42501';
  END IF;
  UPDATE public.liquidaciones_comision
     SET fecha_pago = p_fecha_pago,
         metodo_pago = p_metodo_pago,
         referencia = COALESCE(p_referencia, referencia),
         notas = COALESCE(p_notas, notas),
         estado = 'Pagada',
         updated_at = now()
   WHERE id = p_liquidacion_id
     AND fecha_pago IS NULL
     AND estado = 'Generada'
  RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'LC_LIQUIDACION_YA_PAGADA: Esta liquidación ya tiene un pago registrado.'
      USING ERRCODE = '42501';
  END IF;
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (v_row.organization_id, v_uid, COALESCE(v_email,''), 'registrar_pago_liquidacion', 'comisiones',
            v_row.id, 'Liquidación ' || v_row.periodo,
            jsonb_build_object('fecha_pago', p_fecha_pago, 'metodo_pago', p_metodo_pago,
                               'total_mxn', v_row.total_mxn));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en registrar_pago_liquidacion: % %', SQLSTATE, SQLERRM;
  END;
  RETURN v_row;
END;
$$;
CREATE FUNCTION public.registrar_pago_proveedor_lote(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_proveedor_id uuid := (p_payload->>'proveedor_id')::uuid;
  v_fecha date := COALESCE((p_payload->>'fecha_pago')::date, CURRENT_DATE);
  v_moneda public.moneda := (p_payload->>'moneda')::public.moneda;
  v_tc numeric := NULLIF(p_payload->>'tipo_cambio_usd','')::numeric;
  -- Ola 11 · RNF-05: importe real de la transferencia (nuevo en el payload).
  v_importe numeric := NULLIF(p_payload->>'importe_recibido','')::numeric;
  v_metodo text := COALESCE(NULLIF(TRIM(p_payload->>'metodo_pago'), ''), 'Transferencia');
  v_referencia text := COALESCE(NULLIF(TRIM(p_payload->>'referencia'), ''), '');
  v_cuenta_id uuid := NULLIF(p_payload->>'cuenta_bancaria_id','')::uuid;
  v_notas text := COALESCE(p_payload->>'notas','');
  -- BL-02 · idempotencia (espejo RNF-01 de registrar_pago_cliente_lote):
  -- llave opcional del cliente para deduplicar dobles submits/reintentos.
  v_request_id uuid := NULLIF(p_payload->>'request_id','')::uuid;
  v_cached jsonb;
  v_cuenta public.cuentas_bancarias;
  v_proveedor_nombre text;
  v_total numeric := 0;
  v_lote_id uuid;
  v_renglon jsonb;
  v_fecha_emision date;
  -- Ola 12 · R3BD-03: moneda de la factura para el guard de paridad.
  v_moneda_factura public.moneda;
  -- BL-03: estado de la factura para el guard de vida.
  v_estado_factura public.estado_proveedor_factura;
  v_n int := 0;
  v_email text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado' USING ERRCODE = '42501';
  END IF;
  -- BL-02: reclamo atómico de la llave. Reintento del mismo submit →
  -- respuesta almacenada; ejecución aún en vuelo → rechazo claro.
  v_cached := public.idempotency_claim(v_request_id, 'registrar_pago_proveedor_lote');
  IF v_cached IS NOT NULL THEN
    IF COALESCE((v_cached->>'__idempotency_pending')::boolean, false) THEN
      RAISE EXCEPTION 'LC_LOTE_EN_PROCESO: Este pago en lote ya está en proceso; espera unos segundos y verifica el historial antes de reintentar.'
        USING ERRCODE = '42501';
    END IF;
    RETURN (v_cached->>'lote_id')::uuid;
  END IF;
  SELECT organization_id, nombre INTO v_org, v_proveedor_nombre
  FROM public.proveedores WHERE id = v_proveedor_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_LOTE_PROVEEDOR_NO_EXISTE: El proveedor no existe.';
  END IF;
  IF v_org <> public.current_user_org_id()
     AND NOT public.has_role(v_uid,'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_LOTE_PROVEEDOR_OTRA_ORG: El proveedor pertenece a otra organización.';
  END IF;
  -- Ola 8 + FIX B-6: el rol financiero debe venir de la membresía en ESTA
  -- organización (antes: EXISTS global sobre user_roles — un contador de la
  -- org A podía registrar pagos en la org B), con la lista EXACTA previa al
  -- piloto {admin, admin_org, super_admin, contador, tesorero} y SIN expansión
  -- de jerarquía: `auxiliar_contable` queda fuera por decisión conservadora.
  -- super_admin conserva su bypass de plataforma dentro del helper.
  IF NOT public.has_any_role_in_org_exact(v_uid,
       ARRAY['admin','admin_org','super_admin','contador','tesorero']::public.app_role[],
       v_org) THEN
    RAISE EXCEPTION 'LC_LOTE_SIN_ROL: Sólo administración, contabilidad o tesorería pueden registrar pagos en lote.'
      USING ERRCODE = '42501';
  END IF;
  -- Ola 11 · RFE-02/RNF-03: misma regla que el pago individual.
  IF v_fecha > CURRENT_DATE THEN
    RAISE EXCEPTION 'LC_LOTE_FECHA_FUTURA: La fecha del pago no puede ser futura.'
      USING ERRCODE = '42501';
  END IF;
  -- Ola 12 · R3BD-02 (espejo del guard CxC LC_COBRO_LOTE_TC_REQUERIDO de
  -- RFE-03, 20260821030800:97-100): un lote en USD/EUR sin tipo de cambio NO
  -- se registra. Antes el payload con tipo_cambio_usd NULL pasaba y la
  -- reportería MXN hacía COALESCE(pp.tipo_cambio_usd, 1) → 1:1 silencioso.
  IF v_moneda <> 'MXN'::public.moneda AND (v_tc IS NULL OR v_tc <= 0) THEN
    RAISE EXCEPTION 'LC_LOTE_TC_REQUERIDO: No hay tipo de cambio disponible para un pago en lote en %; reintenta cuando el servicio de tipos de cambio responda.', v_moneda
      USING ERRCODE = '42501';
  END IF;
  IF v_cuenta_id IS NULL AND v_metodo <> 'Efectivo' THEN
    RAISE EXCEPTION 'LC_LOTE_CUENTA_REQUERIDA: Selecciona la cuenta bancaria de donde sale el pago (sólo Efectivo puede omitirla).';
  END IF;
  IF v_cuenta_id IS NOT NULL THEN
    SELECT * INTO v_cuenta FROM public.cuentas_bancarias
    WHERE id = v_cuenta_id AND deleted_at IS NULL;
    IF v_cuenta.id IS NULL THEN
      RAISE EXCEPTION 'LC_LOTE_CUENTA_INVALIDA: La cuenta bancaria no existe o está dada de baja.';
    END IF;
    IF v_cuenta.organization_id <> v_org THEN
      RAISE EXCEPTION 'LC_LOTE_CUENTA_OTRA_ORG: La cuenta bancaria pertenece a otra organización.';
    END IF;
    IF v_cuenta.moneda <> v_moneda THEN
      RAISE EXCEPTION 'LC_LOTE_CUENTA_DIVISA: La cuenta está en % y el pago en %.', v_cuenta.moneda, v_moneda;
    END IF;
  END IF;
  -- Ola 11 · RNF-06 (espejo RG4-6): una misma factura no puede aparecer dos veces.
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(COALESCE(p_payload->'renglones','[]'::jsonb)) AS r
    GROUP BY (r->>'factura_id')
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'LC_LOTE_FACTURA_DUPLICADA: Hay facturas repetidas en el lote; cada factura sólo puede aparecer una vez.'
      USING ERRCODE = '42501';
  END IF;
  -- Validar renglones y calcular total.
  -- Ola 1 (espejo BL-13 de CxC): los locks se toman en orden determinista por
  -- factura_id, no en el orden del payload; dos lotes concurrentes con las
  -- mismas facturas en orden distinto hacían deadlock.
  FOR v_renglon IN
    SELECT r FROM jsonb_array_elements(COALESCE(p_payload->'renglones','[]'::jsonb)) AS r
    ORDER BY (r->>'factura_id')::uuid
  LOOP
    IF COALESCE((v_renglon->>'monto')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'LC_LOTE_MONTO_INVALIDO: Cada factura del lote debe tener un importe mayor a cero.';
    END IF;
    -- Ola 11 · RFE-02/RNF-03: el SELECT sirve doble — valida que la factura
    -- exista/sea del proveedor y trae fecha_emision para el guard de fecha.
    -- Ola 12 · R3BD-03: también trae la moneda para el guard de paridad.
    -- BL-03: también trae el estado para el guard de vida (paridad CxC).
    -- Ola 1: FOR UPDATE serializa el reparto contra pagos concurrentes.
    SELECT pf.fecha_emision, pf.moneda, pf.estado
      INTO v_fecha_emision, v_moneda_factura, v_estado_factura
    FROM public.proveedor_facturas pf
    WHERE pf.id = (v_renglon->>'factura_id')::uuid
      AND pf.deleted_at IS NULL
      AND pf.organization_id = v_org
      AND pf.proveedor_id = v_proveedor_id
    FOR UPDATE OF pf;
    IF v_fecha_emision IS NULL THEN
      RAISE EXCEPTION 'LC_LOTE_FACTURA_INVALIDA: Una de las facturas no existe o no pertenece al proveedor seleccionado.';
    END IF;
    -- BL-03: una factura Cancelada no admite pagos (el guard de aprobación
    -- no basta: cancelar_factura_proveedor conservaba estado_aprobacion).
    IF v_estado_factura = 'Cancelada'::public.estado_proveedor_factura THEN
      RAISE EXCEPTION 'LC_LOTE_FACTURA_NO_VIVA: Una de las facturas del lote está Cancelada y no admite pagos; retírala del reparto.'
        USING ERRCODE = '42501';
    END IF;
    -- Ola 12 · R3BD-03 (paridad CxC): la factura debe ser de la moneda del
    -- lote. Excepción: cruce de monedas permitido sólo con TC válido, porque
    -- el trigger convertir_monto_pago_a_factura convierte con ese TC.
    IF v_moneda_factura <> v_moneda AND (v_tc IS NULL OR v_tc <= 0) THEN
      RAISE EXCEPTION 'LC_LOTE_FACTURA_MONEDA: La factura está en % y el lote en %; captura el tipo de cambio o retira la factura del lote.', v_moneda_factura, v_moneda
        USING ERRCODE = '42501';
    END IF;
    IF v_fecha < v_fecha_emision THEN
      RAISE EXCEPTION 'LC_LOTE_FECHA_PREVIA_EMISION: La fecha del pago es anterior a la emisión de una de las facturas del lote.'
        USING ERRCODE = '42501';
    END IF;
    v_total := v_total + ROUND((v_renglon->>'monto')::numeric, 2);
    v_n := v_n + 1;
  END LOOP;
  IF v_n < 2 THEN
    RAISE EXCEPTION 'LC_LOTE_MINIMO_FACTURAS: Un pago en lote requiere al menos dos facturas.';
  END IF;
  -- Ola 11 · RNF-05 (espejo RG4-5): el reparto debe cuadrar EXACTAMENTE con
  -- la transferencia. Canon RNF-02: comparación exacta tras ROUND a 2
  -- decimales (sin tolerancia), igual que promete el mensaje.
  IF v_importe IS NULL OR v_importe <= 0 THEN
    RAISE EXCEPTION 'LC_LOTE_IMPORTE_REQUERIDO: Captura el importe total de la transferencia.'
      USING ERRCODE = '42501';
  END IF;
  IF ROUND(v_importe, 2) IS DISTINCT FROM ROUND(v_total, 2) THEN
    RAISE EXCEPTION 'LC_LOTE_IMPORTE_NO_CUADRA: El reparto (%) no cuadra con el importe de la transferencia (%); no se permite sobrante sin asignar.', v_total, v_importe
      USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.pagos_proveedor_lote
    (organization_id, proveedor_id, fecha_pago, moneda, monto_total, tipo_cambio_usd,
     metodo_pago, referencia, cuenta_bancaria_id, notas, created_by)
  VALUES
    (v_org, v_proveedor_id, v_fecha, v_moneda, v_total, v_tc,
     v_metodo, v_referencia, v_cuenta_id, v_notas, v_uid)
  RETURNING id INTO v_lote_id;
  FOR v_renglon IN SELECT * FROM jsonb_array_elements(COALESCE(p_payload->'renglones','[]'::jsonb)) LOOP
    INSERT INTO public.pagos_proveedor
      (organization_id, proveedor_factura_id, fecha_pago, monto, moneda, tipo_cambio_usd,
       metodo_pago, referencia, cuenta_bancaria_id, notas, created_by, lote_id)
    VALUES
      (v_org, (v_renglon->>'factura_id')::uuid, v_fecha,
       ROUND((v_renglon->>'monto')::numeric, 2), v_moneda, v_tc,
       v_metodo, v_referencia, v_cuenta_id, v_notas, v_uid, v_lote_id);
  END LOOP;
  IF v_cuenta_id IS NOT NULL THEN
    INSERT INTO public.bbva_movimientos
      (organization_id, cuenta_bancaria_id, fecha, concepto, referencia,
       cargo, abono, hash_dedupe, estado_conciliacion,
       pago_proveedor_lote_id, conciliado_por, conciliado_at, importado_por)
    VALUES
      (v_org, v_cuenta_id, v_fecha,
       'Pago en lote (' || v_n || ' facturas) — ' || COALESCE(v_proveedor_nombre, 'proveedor'),
       v_referencia, v_total, 0, 'lote-' || v_lote_id::text, 'Conciliado',
       v_lote_id, v_uid, now(), v_uid);
  END IF;
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (v_org, v_uid, COALESCE(v_email,''), 'registrar_pago_proveedor_lote', 'cxp',
            v_lote_id, 'Pago en lote ' || v_lote_id::text,
            jsonb_build_object('proveedor_id', v_proveedor_id, 'monto_total', v_total,
                               'importe_recibido', v_importe,
                               'moneda', v_moneda, 'facturas', v_n,
                               'cuenta_bancaria_id', v_cuenta_id, 'referencia', v_referencia));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en registrar_pago_proveedor_lote: % %', SQLSTATE, SQLERRM;
  END;
  -- BL-02: almacena la respuesta para los reintentos con la misma llave
  -- (no-op cuando request_id viene NULL).
  PERFORM public.idempotency_store(v_request_id,
    jsonb_build_object('lote_id', v_lote_id, 'monto_total', v_total, 'facturas', v_n));
  RETURN v_lote_id;
END;
$$;
CREATE FUNCTION public.registrar_traspaso_bancario(p_cuenta_origen_id uuid, p_cuenta_destino_id uuid, p_fecha date, p_monto_origen numeric, p_tipo_cambio numeric DEFAULT NULL::numeric, p_comision numeric DEFAULT 0, p_concepto text DEFAULT ''::text, p_referencia text DEFAULT ''::text, p_client_request_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_user_org_id();
  v_uid uuid := auth.uid();
  v_origen public.cuentas_bancarias%ROWTYPE;
  v_destino public.cuentas_bancarias%ROWTYPE;
  v_tc numeric;
  v_comision numeric := COALESCE(p_comision, 0);
  v_monto_destino numeric;
  v_folio text;
  v_org_eff uuid;
  v_id uuid;
  v_saldo_origen numeric;
  v_concepto text := COALESCE(NULLIF(TRIM(p_concepto), ''), 'Traspaso entre cuentas propias');
BEGIN
  IF p_cuenta_origen_id = p_cuenta_destino_id THEN
    RAISE EXCEPTION 'LC_TRASPASO_MISMA_CUENTA: la cuenta origen y destino deben ser distintas';
  END IF;
  IF COALESCE(p_monto_origen, 0) <= 0 THEN
    RAISE EXCEPTION 'LC_TRASPASO_MONTO_INVALIDO: el monto debe ser mayor a cero';
  END IF;
  IF v_comision < 0 THEN
    RAISE EXCEPTION 'LC_TRASPASO_COMISION_INVALIDA: la comisión no puede ser negativa';
  END IF;
  SELECT * INTO v_origen FROM public.cuentas_bancarias WHERE id = p_cuenta_origen_id;
  SELECT * INTO v_destino FROM public.cuentas_bancarias WHERE id = p_cuenta_destino_id;
  IF v_origen.id IS NULL OR v_destino.id IS NULL THEN
    RAISE EXCEPTION 'LC_TRASPASO_CUENTA_INEXISTENTE: no se encontró alguna de las cuentas';
  END IF;
  IF v_origen.organization_id <> v_destino.organization_id THEN
    RAISE EXCEPTION 'LC_TRASPASO_ORG_DISTINTA: las cuentas pertenecen a organizaciones diferentes';
  END IF;
  IF NOT v_origen.activa OR NOT v_destino.activa THEN
    RAISE EXCEPTION 'LC_TRASPASO_CUENTA_INACTIVA: ambas cuentas deben estar activas';
  END IF;
  IF v_origen.moneda = v_destino.moneda THEN
    v_tc := 1;
    v_monto_destino := ROUND(p_monto_origen, 2);
  ELSE
    IF p_tipo_cambio IS NULL OR p_tipo_cambio <= 0 THEN
      RAISE EXCEPTION 'LC_TRASPASO_TC_REQUERIDO: captura el tipo de cambio para un traspaso entre monedas distintas';
    END IF;
    v_tc := p_tipo_cambio;
    v_monto_destino := ROUND(p_monto_origen * v_tc, 2);
  END IF;
  -- B-6 (v14): monto + comisión no pueden exceder el saldo de la cuenta origen.
  v_saldo_origen := COALESCE(public.saldo_cuenta_bancaria(p_cuenta_origen_id), 0);
  IF ROUND(p_monto_origen, 2) + ROUND(v_comision, 2) > ROUND(v_saldo_origen, 2) + 0.005 THEN
    RAISE EXCEPTION 'LC_TRASPASO_SALDO_INSUFICIENTE: el saldo de la cuenta origen (%) no cubre el traspaso más la comisión (%).',
      ROUND(v_saldo_origen, 2), ROUND(p_monto_origen, 2) + ROUND(v_comision, 2)
      USING ERRCODE = '22023';
  END IF;
  v_org_eff := COALESCE(v_org, v_origen.organization_id);
  v_folio := public.siguiente_folio_traspaso(v_org_eff);
  INSERT INTO public.traspasos_bancarios(
    organization_id, folio, cuenta_origen_id, cuenta_destino_id, fecha,
    monto_origen, moneda_origen, monto_destino, moneda_destino,
    tipo_cambio, comision, concepto, referencia, created_by, client_request_id
  ) VALUES (
    v_org_eff, v_folio, p_cuenta_origen_id, p_cuenta_destino_id, p_fecha,
    ROUND(p_monto_origen, 2), v_origen.moneda, v_monto_destino, v_destino.moneda,
    v_tc, ROUND(v_comision, 2), v_concepto, COALESCE(p_referencia, ''), v_uid,
    p_client_request_id
  ) RETURNING id INTO v_id;
  INSERT INTO public.bbva_movimientos(
    organization_id, cuenta_bancaria_id, fecha, concepto, referencia,
    cargo, abono, hash_dedupe, estado_conciliacion, conciliado_por, conciliado_at,
    importado_por, traspaso_id
  ) VALUES (
    COALESCE(v_org, v_origen.organization_id), p_cuenta_origen_id, p_fecha,
    v_concepto || ' → ' || v_destino.banco || ' ' || v_destino.alias, COALESCE(p_referencia, ''),
    ROUND(p_monto_origen, 2), 0, 'traspaso-' || v_id::text || '-origen',
    'Conciliado'::estado_conciliacion, v_uid, now(), v_uid, v_id
  );
  INSERT INTO public.bbva_movimientos(
    organization_id, cuenta_bancaria_id, fecha, concepto, referencia,
    cargo, abono, hash_dedupe, estado_conciliacion, conciliado_por, conciliado_at,
    importado_por, traspaso_id
  ) VALUES (
    COALESCE(v_org, v_destino.organization_id), p_cuenta_destino_id, p_fecha,
    v_concepto || ' ← ' || v_origen.banco || ' ' || v_origen.alias, COALESCE(p_referencia, ''),
    0, v_monto_destino, 'traspaso-' || v_id::text || '-destino',
    'Conciliado'::estado_conciliacion, v_uid, now(), v_uid, v_id
  );
  IF ROUND(v_comision, 2) > 0 THEN
    INSERT INTO public.bbva_movimientos(
      organization_id, cuenta_bancaria_id, fecha, concepto, referencia,
      cargo, abono, hash_dedupe, estado_conciliacion, conciliado_por, conciliado_at,
      importado_por, traspaso_id
    ) VALUES (
      COALESCE(v_org, v_origen.organization_id), p_cuenta_origen_id, p_fecha,
      'Comisión bancaria por traspaso ' || v_folio, COALESCE(p_referencia, ''),
      ROUND(v_comision, 2), 0, 'traspaso-' || v_id::text || '-comision',
      'Conciliado'::estado_conciliacion, v_uid, now(), v_uid, v_id
    );
  END IF;
  RETURN v_id;
END;
$$;
CREATE FUNCTION public.reject_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION '%', COALESCE(TG_ARGV[0], 'LC_DELETE_PROHIBIDO: registro inmutable')
    USING ERRCODE = 'P0001';
END;
$$;
CREATE FUNCTION public.reportes_resumen(p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_modo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows jsonb;
  v_kpis jsonb;
BEGIN
  WITH base AS (
    SELECT * FROM public.profit_por_cliente(p_fecha_desde, p_fecha_hasta, p_modo)
  ),
  calc AS (
    SELECT
      cliente_id,
      cliente_nombre,
      total_embarques,
      venta_usd,
      costo_usd,
      (venta_usd - costo_usd) AS profit_usd,
      CASE WHEN venta_usd > 0
           THEN ((venta_usd - costo_usd) / venta_usd) * 100
           ELSE 0
      END AS margen
    FROM base
  )
  SELECT
    jsonb_agg(to_jsonb(c.*) ORDER BY c.profit_usd DESC),
    jsonb_build_object(
      'totalClientes', count(*),
      'revenue', COALESCE(sum(c.venta_usd), 0),
      'profit', COALESCE(sum(c.profit_usd), 0),
      'margenProm',
        CASE WHEN COALESCE(sum(c.venta_usd),0) > 0
             THEN ((sum(c.venta_usd) - sum(c.costo_usd)) / sum(c.venta_usd)) * 100
             ELSE 0
        END
    )
  INTO v_rows, v_kpis
  FROM calc c;
  RETURN jsonb_build_object(
    'clientes', COALESCE(v_rows, '[]'::jsonb),
    'kpis', v_kpis
  );
END;
$$;
CREATE FUNCTION public.reprocesar_comisiones_job() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_p integer;
  v_r integer;
  v_orgs integer := 0;
  v_procesadas integer := 0;
  v_resueltas integer := 0;
  v_fallos jsonb := '[]'::jsonb;
BEGIN
  FOR v_org IN
    SELECT DISTINCT organization_id
      FROM public.comisiones_recalculo_pendiente
     WHERE resuelto_at IS NULL
  LOOP
    v_orgs := v_orgs + 1;
    BEGIN
      SELECT r.procesadas, r.resueltas INTO v_p, v_r
        FROM public._reprocesar_comisiones_org(v_org) r;
      v_procesadas := v_procesadas + COALESCE(v_p, 0);
      v_resueltas  := v_resueltas  + COALESCE(v_r, 0);
    EXCEPTION WHEN OTHERS THEN
      v_fallos := v_fallos || jsonb_build_object('organization_id', v_org, 'error', SQLERRM);
    END;
  END LOOP;
  INSERT INTO public.app_logs (level, fn, msg, payload)
  VALUES (
    CASE WHEN jsonb_array_length(v_fallos) = 0 THEN 'info' ELSE 'error' END,
    'reprocesar_comisiones_job',
    'Reproceso diario de comisiones pendientes ejecutado',
    jsonb_build_object(
      'organizaciones', v_orgs,
      'procesadas',     v_procesadas,
      'resueltas',      v_resueltas,
      'pendientes',     GREATEST(v_procesadas - v_resueltas, 0),
      'fallos',         v_fallos
    )
  );
  RETURN jsonb_build_object(
    'organizaciones', v_orgs,
    'procesadas',     v_procesadas,
    'resueltas',      v_resueltas,
    'fallos',         v_fallos
  );
END;
$$;
CREATE FUNCTION public.reprocesar_comisiones_pendientes(p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(procesadas integer, resueltas integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := COALESCE(p_org, public.current_user_org_id());
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_INEXISTENTE: no hay organización activa'
      USING ERRCODE = '42501';
  END IF;
  IF NOT (public.has_role(auth.uid(), 'admin'::app_role)
          OR public.has_role(auth.uid(), 'super_admin'::app_role)) THEN
    RAISE EXCEPTION 'LC_NO_AUTORIZADO: sólo administración reprocesa comisiones'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public.rls_tenant_scope_ok(v_org) THEN
    RAISE EXCEPTION 'LC_TENANT_MISMATCH: organización fuera de alcance'
      USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT r.procesadas, r.resueltas
                 FROM public._reprocesar_comisiones_org(v_org) r;
END;
$$;
CREATE FUNCTION public.reseed_organization_catalogs(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_rows integer;
  v_out jsonb := '{}'::jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'No autenticado' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_role(v_caller, 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'Sólo super_admin puede reprocesar seeds' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id) THEN
    RAISE EXCEPTION 'Organización no existe' USING ERRCODE = '22023';
  END IF;
  -- factura_series
  IF NOT EXISTS (SELECT 1 FROM public.factura_series WHERE organization_id = p_org_id) THEN
    INSERT INTO public.factura_series (organization_id, codigo, prefijo, folio_actual, folio_inicial, activa, es_default, descripcion)
    VALUES (p_org_id, 'A', 'A', 0, 1, true, true, 'Serie por defecto');
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    PERFORM public._log_provisioning_step(p_org_id, 'reseed', 'seed_factura_series', 'factura_series', v_rows);
    v_out := v_out || jsonb_build_object('factura_series', v_rows);
  END IF;
  -- crm_etapas_pipeline
  IF NOT EXISTS (SELECT 1 FROM public.crm_etapas_pipeline WHERE organization_id = p_org_id) THEN
    INSERT INTO public.crm_etapas_pipeline (organization_id, nombre, orden, probabilidad_default, color, tipo) VALUES
      (p_org_id, 'Prospecto',    1, 10,  '#94a3b8', 'abierta'),
      (p_org_id, 'Calificado',   2, 25,  '#38bdf8', 'abierta'),
      (p_org_id, 'Propuesta',    3, 50,  '#6366f1', 'abierta'),
      (p_org_id, 'Negociación',  4, 75,  '#f59e0b', 'abierta'),
      (p_org_id, 'Ganada',       5, 100, '#10b981', 'ganada'),
      (p_org_id, 'Perdida',      6, 0,   '#ef4444', 'perdida');
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    PERFORM public._log_provisioning_step(p_org_id, 'reseed', 'seed_crm_etapas_pipeline', 'crm_etapas_pipeline', v_rows);
    v_out := v_out || jsonb_build_object('crm_etapas_pipeline', v_rows);
  END IF;
  -- crm_motivos_perdida
  IF NOT EXISTS (SELECT 1 FROM public.crm_motivos_perdida WHERE organization_id = p_org_id) THEN
    INSERT INTO public.crm_motivos_perdida (organization_id, nombre) VALUES
      (p_org_id, 'Precio'),
      (p_org_id, 'Tiempo de tránsito'),
      (p_org_id, 'Competencia'),
      (p_org_id, 'No responde'),
      (p_org_id, 'Otro');
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    PERFORM public._log_provisioning_step(p_org_id, 'reseed', 'seed_crm_motivos_perdida', 'crm_motivos_perdida', v_rows);
    v_out := v_out || jsonb_build_object('crm_motivos_perdida', v_rows);
  END IF;
  -- presupuesto_categorias
  IF NOT EXISTS (SELECT 1 FROM public.presupuesto_categorias WHERE organization_id = p_org_id) THEN
    INSERT INTO public.presupuesto_categorias (organization_id, nombre, orden, tipo_contable) VALUES
      (p_org_id, 'Ventas',           1, 'Venta'),
      (p_org_id, 'Costo directo',    2, 'CostoDirectoEmbarque'),
      (p_org_id, 'Administración',   3, 'Administracion');
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    PERFORM public._log_provisioning_step(p_org_id, 'reseed', 'seed_presupuesto_categorias', 'presupuesto_categorias', v_rows);
    v_out := v_out || jsonb_build_object('presupuesto_categorias', v_rows);
  END IF;
  RETURN v_out;
END;
$$;
CREATE FUNCTION public.reservar_folio_factura(_serie_id uuid) RETURNS TABLE(folio bigint, numero text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.factura_series%ROWTYPE;
  _next BIGINT;
BEGIN
  SELECT * INTO _row FROM public.factura_series
   WHERE id = _serie_id
     AND (organization_id = public.org_scope())
     AND activa = TRUE
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Serie no encontrada o inactiva';
  END IF;
  _next := GREATEST(_row.folio_actual + 1, _row.folio_inicial);
  UPDATE public.factura_series
     SET folio_actual = _next,
         updated_at = now()
   WHERE id = _serie_id;
  folio := _next;
  numero := _row.prefijo || _next::TEXT;
  RETURN NEXT;
END;
$$;
CREATE FUNCTION public.resolver_clave_sat(p_org uuid, p_descripcion text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT clave_sat
  FROM public.catalogo_claves_sat
  WHERE organization_id = p_org
    AND activo = true
    AND p_descripcion ILIKE '%' || patron || '%'
  ORDER BY prioridad ASC, length(patron) DESC
  LIMIT 1
$$;
CREATE FUNCTION public.resolver_expediente_por_bl(_bl_master text, _tipo_op text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_exp text;
BEGIN
  -- Determina la organización efectiva del caller (impersonación incluida).
  v_org := public.current_user_org_id();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'No hay organización activa para resolver el expediente por BL Master';
  END IF;
  SELECT expediente
    INTO v_exp
    FROM public.embarques
   WHERE bl_master = _bl_master
     AND organization_id = v_org
     AND deleted_at IS NULL
   LIMIT 1;
  IF v_exp IS NOT NULL THEN
    RETURN v_exp;
  END IF;
  RETURN public.generar_expediente(_tipo_op);
END;
$$;
CREATE FUNCTION public.resolver_porcentaje_comision(p_organization_id uuid, p_vendedora_id uuid, p_cliente_id uuid, p_embarque_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT e.porcentaje
       FROM public.comisiones_excepciones e
      WHERE e.organization_id = p_organization_id
        AND e.vendedora_id = p_vendedora_id
        AND e.activa = true AND e.deleted_at IS NULL
        AND ((p_embarque_id IS NOT NULL AND e.embarque_id = p_embarque_id)
          OR (p_cliente_id IS NOT NULL AND e.cliente_id = p_cliente_id))
      ORDER BY (e.embarque_id IS NOT NULL) DESC
      LIMIT 1),
    (SELECT COALESCE(vc.porcentaje_default, 0)
       FROM public.vendedora_config vc
      WHERE vc.organization_id = p_organization_id
        AND vc.user_id = p_vendedora_id
        AND vc.activa = true),
    0
  );
$$;
CREATE FUNCTION public.resolver_producto_sat(p_org uuid, p_nombre text) RETURNS TABLE(id uuid, nombre text, clave_sat text, tipo_iva text, tasa_iva_default numeric, clave_unidad_sat text, nombre_unidad text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT id, patron AS nombre, clave_sat, tipo_iva, tasa_iva_default, clave_unidad_sat, nombre_unidad
  FROM public.catalogo_claves_sat
  WHERE organization_id = p_org
    AND activo = true
    AND lower(patron) = lower(p_nombre)
  LIMIT 1
$$;
CREATE FUNCTION public.resolver_puerto_id(p_valor text) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT p.id
    FROM public.puertos p
   WHERE p_valor IS NOT NULL
     AND btrim(p_valor) <> ''
     AND (
       upper(btrim(p.code)) = upper(btrim(p_valor))
       OR lower(btrim(p.name)) = lower(btrim(p_valor))
     )
   ORDER BY (upper(btrim(p.code)) = upper(btrim(p_valor))) DESC
   LIMIT 1;
$$;
CREATE FUNCTION public.resolver_reaprobacion_tarifa(p_cotizacion_id uuid, p_decision text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cot        public.cotizaciones%ROWTYPE;
  v_caller_org UUID := current_user_org_id();
  v_is_super   BOOLEAN := has_role(auth.uid(),'super_admin'::app_role);
BEGIN
  IF p_decision NOT IN ('reaprobada','rechazada','recotizada') THEN
    RAISE EXCEPTION 'Decisión inválida: %', p_decision USING ERRCODE='P0001'; END IF;
  SELECT * INTO v_cot FROM public.cotizaciones WHERE id=p_cotizacion_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cotización no encontrada' USING ERRCODE='P0002'; END IF;
  IF NOT v_is_super AND v_cot.organization_id IS DISTINCT FROM v_caller_org THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
  IF v_cot.estado_revalidacion<>'pendiente_reaprobacion' THEN
    RAISE EXCEPTION 'La cotización no está pendiente de re-aprobación (estado: %)', v_cot.estado_revalidacion USING ERRCODE='P0001'; END IF;
  UPDATE public.cotizaciones
  SET estado_revalidacion=p_decision, revalidacion_resuelta_en=now(), updated_at=now()
  WHERE id=p_cotizacion_id;
  INSERT INTO public.bitacora_actividad(
    organization_id,usuario_id,usuario_email,modulo,accion,entidad_id,entidad_nombre,detalles)
  SELECT v_cot.organization_id, auth.uid(),
         COALESCE((SELECT email FROM auth.users WHERE id=auth.uid()),''),
         'Cotizaciones','reaprobacion_resuelta', v_cot.id, v_cot.folio,
         jsonb_build_object('decision',p_decision);
END;
$$;
CREATE FUNCTION public.resolver_sin_comision(p_embarque_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(e.sin_comision, c.sin_comision, false)
    FROM public.embarques e
    LEFT JOIN public.clientes c ON c.id = e.cliente_id
   WHERE e.id = p_embarque_id
$$;
CREATE FUNCTION public.resolver_tipo_contenedor_id(p_valor text) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT t.id
    FROM public.tipos_contenedor t
   WHERE p_valor IS NOT NULL
     AND btrim(p_valor) <> ''
     AND (
       upper(btrim(t.code)) = upper(btrim(p_valor))
       OR lower(btrim(t.name)) = lower(btrim(p_valor))
     )
   ORDER BY (upper(btrim(t.code)) = upper(btrim(p_valor))) DESC
   LIMIT 1;
$$;
CREATE FUNCTION public.restaurar_embarque_cascade(p_embarque_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_deleted_at timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  SELECT organization_id, deleted_at
    INTO v_org, v_deleted_at
    FROM public.embarques
   WHERE id = p_embarque_id AND deleted_at IS NOT NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Embarque no encontrado en papelera';
  END IF;
  IF NOT (
    public.has_role(v_uid, 'super_admin'::app_role)
    OR (v_org = public.current_user_org_id()
        AND (public.has_role(v_uid, 'admin'::app_role) OR public.has_role(v_uid, 'operador'::app_role)))
  ) THEN
    RAISE EXCEPTION 'Permisos insuficientes';
  END IF;
  -- D-01: puerta oficial de restauración.
  PERFORM set_config('app.papelera_restore', 'on', true);
  UPDATE public.conceptos_venta       SET deleted_at = NULL, deleted_by = NULL WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  UPDATE public.conceptos_costo       SET deleted_at = NULL, deleted_by = NULL WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  UPDATE public.documentos_embarque   SET deleted_at = NULL, deleted_by = NULL WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  UPDATE public.notas_embarque        SET deleted_at = NULL, deleted_by = NULL WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  UPDATE public.eventos_embarque      SET deleted_at = NULL, deleted_by = NULL WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  UPDATE public.embarque_contenedores SET deleted_at = NULL, deleted_by = NULL WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  UPDATE public.facturas              SET deleted_at = NULL, deleted_by = NULL WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  UPDATE public.seguros_embarque      SET deleted_at = NULL                    WHERE embarque_id = p_embarque_id AND deleted_at = v_deleted_at;
  UPDATE public.embarques SET deleted_at = NULL, deleted_by = NULL WHERE id = p_embarque_id;
  PERFORM set_config('app.papelera_restore', 'off', true);
END;
$$;
CREATE FUNCTION public.restore_record(_table text, _id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  _org uuid;
  _uid uuid := auth.uid();
BEGIN
  IF NOT public.is_soft_delete_table(_table) THEN
    RAISE EXCEPTION 'Tabla no permitida: %', _table;
  END IF;
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  IF _table = 'embarques' THEN
    PERFORM public.restaurar_embarque_cascade(_id);
    RETURN;
  END IF;
  EXECUTE format('SELECT organization_id FROM public.%I WHERE id = $1 AND deleted_at IS NOT NULL', _table)
    INTO _org USING _id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'Registro no encontrado en papelera';
  END IF;
  IF _org IS DISTINCT FROM public.org_scope() THEN
    RAISE EXCEPTION 'LC_ORG_FUERA_DE_SCOPE: el registro pertenece a otra organización';
  END IF;
  IF NOT (
    public.has_role(_uid, 'super_admin'::app_role)
    OR public.has_role(_uid, 'admin'::app_role)
    OR public.has_role(_uid, 'operador'::app_role)
  ) THEN
    RAISE EXCEPTION 'Permisos insuficientes';
  END IF;
  -- D-01: puerta oficial de restauración.
  PERFORM set_config('app.papelera_restore', 'on', true);
  EXECUTE format('UPDATE public.%I SET deleted_at = NULL, deleted_by = NULL WHERE id = $1', _table)
    USING _id;
  PERFORM set_config('app.papelera_restore', 'off', true);
END;
$_$;
CREATE FUNCTION public.retirar_factura_entrante(p_documento_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid := public.current_user_org_id();
  v_es_admin boolean := public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'super_admin');
  v_doc public.embarque_facturas_entrantes%ROWTYPE;
  v_filas int := 0;
BEGIN
  IF NOT (v_es_admin
          OR public.has_role(auth.uid(), 'operador')
          OR public.has_role(auth.uid(), 'contador')
          OR public.has_role(auth.uid(), 'auxiliar_contable')) THEN
    RAISE EXCEPTION 'LC_ENTRANTE_RETIRO_FORBIDDEN: sin permiso para retirar documentos del buzón';
  END IF;
  SELECT * INTO v_doc FROM public.embarque_facturas_entrantes
   WHERE id = p_documento_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'LC_NOT_FOUND: documento no encontrado'; END IF;
  IF v_doc.organization_id IS DISTINCT FROM v_caller_org AND NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'LC_FORBIDDEN: documento de otra organización';
  END IF;
  IF NOT v_es_admin AND v_doc.subido_por IS DISTINCT FROM auth.uid()
     AND v_doc.estado = 'por_capturar' THEN
    RAISE EXCEPTION 'LC_ENTRANTE_RETIRO_FORBIDDEN: sólo quien subió el archivo o un administrador puede retirarlo';
  END IF;
  -- Ola 6 · RG5-4: la validación de estado/vínculo viaja DENTRO del UPDATE
  -- para que una captura concurrente no se cuele entre el SELECT y el
  -- UPDATE (antes: check-then-act).
  UPDATE public.embarque_facturas_entrantes
     SET deleted_at = now()
   WHERE id = p_documento_id
     AND deleted_at IS NULL
     AND estado IN ('por_capturar', 'rechazada')
     AND proveedor_factura_id IS NULL;
  GET DIAGNOSTICS v_filas = ROW_COUNT;
  IF v_filas = 0 THEN
    RAISE EXCEPTION 'LC_ENTRANTE_RETIRO_CAPTURADA: el documento ya fue capturado como factura de proveedor';
  END IF;
END;
$$;
CREATE FUNCTION public.revalidar_tarifa_cotizacion(p_cotizacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cot             public.cotizaciones%ROWTYPE;
  v_caller_org      UUID := current_user_org_id();
  v_is_super        BOOLEAN := has_role(auth.uid(),'super_admin'::app_role);
  v_umbral_pct      NUMERIC;
  v_bloquea_vencida BOOLEAN;
  v_tarifa_vigente  BOOLEAN := FALSE;
  v_tarifa_vig_rec  RECORD;
  v_cambios         JSONB := '[]'::jsonb;
  v_max_delta_pct   NUMERIC := 0;
  v_severidad       TEXT;
  v_costo           RECORD;
  v_monto_actual    NUMERIC;
  v_delta_abs       NUMERIC;
  v_delta_pct       NUMERIC;
BEGIN
  SELECT * INTO v_cot FROM public.cotizaciones WHERE id=p_cotizacion_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cotización no encontrada' USING ERRCODE='P0002'; END IF;
  IF NOT v_is_super AND v_cot.organization_id IS DISTINCT FROM v_caller_org THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
  SELECT COALESCE((valor#>>'{}')::numeric,5) INTO v_umbral_pct
    FROM public.configuracion
    WHERE categoria='operaciones' AND clave='tarifa_revalidacion_umbral_pct';
  v_umbral_pct := COALESCE(v_umbral_pct,5);
  SELECT COALESCE((valor#>>'{}')::boolean,TRUE) INTO v_bloquea_vencida
    FROM public.configuracion
    WHERE categoria='operaciones' AND clave='tarifa_revalidacion_bloquea_si_vencida';
  v_bloquea_vencida := COALESCE(v_bloquea_vencida,TRUE);
  IF v_cot.tarifa_id IS NULL THEN
    RETURN jsonb_build_object(
      'tarifa_vigente',TRUE,'agente_sin_cupo',FALSE,'severidad','sin_cambios',
      'cambios','[]'::jsonb,'umbral_pct',v_umbral_pct,'max_delta_pct',0,
      'motivo','sin_tarifa_vinculada');
  END IF;
  SELECT * INTO v_tarifa_vig_rec FROM public.costeo_tarifas_vigentes_v WHERE id=v_cot.tarifa_id LIMIT 1;
  v_tarifa_vigente := FOUND;
  FOR v_costo IN
    SELECT cc.concepto, cc.moneda, cc.costo_unitario AS monto_anterior,
           cc.costeo_tarifa_id, cc.costeo_tarifa_recargo_id
    FROM public.cotizacion_costos cc
    WHERE cc.cotizacion_id=v_cot.id AND cc.deleted_at IS NULL
      AND (cc.costeo_tarifa_recargo_id IS NOT NULL OR cc.costeo_tarifa_id IS NOT NULL)
  LOOP
    IF v_costo.costeo_tarifa_recargo_id IS NOT NULL THEN
      SELECT monto INTO v_monto_actual FROM public.costeo_tarifa_recargos WHERE id=v_costo.costeo_tarifa_recargo_id;
    ELSE
      SELECT flete_base INTO v_monto_actual FROM public.costeo_tarifas WHERE id=v_costo.costeo_tarifa_id;
    END IF;
    IF v_monto_actual IS NULL THEN
      v_cambios := v_cambios || jsonb_build_object(
        'concepto',v_costo.concepto,'moneda',v_costo.moneda,
        'monto_anterior',v_costo.monto_anterior,'monto_actual',NULL,
        'delta_abs',NULL,'delta_pct',NULL,'motivo','eliminado');
      v_max_delta_pct := 100;
      CONTINUE;
    END IF;
    v_delta_abs := v_monto_actual - v_costo.monto_anterior;
    v_delta_pct := CASE WHEN v_costo.monto_anterior=0
                     THEN CASE WHEN v_delta_abs=0 THEN 0 ELSE 100 END
                     ELSE ROUND(ABS(v_delta_abs)/v_costo.monto_anterior*100,2) END;
    IF ABS(v_delta_abs) > 0.001 THEN
      v_cambios := v_cambios || jsonb_build_object(
        'concepto',v_costo.concepto,'moneda',v_costo.moneda,
        'monto_anterior',v_costo.monto_anterior,'monto_actual',v_monto_actual,
        'delta_abs',v_delta_abs,'delta_pct',v_delta_pct);
      IF v_delta_pct > v_max_delta_pct THEN v_max_delta_pct := v_delta_pct; END IF;
    END IF;
  END LOOP;
  IF NOT v_tarifa_vigente AND v_bloquea_vencida THEN v_severidad := 'bloqueante';
  ELSIF jsonb_array_length(v_cambios)=0 AND v_tarifa_vigente THEN v_severidad := 'sin_cambios';
  ELSIF v_max_delta_pct > v_umbral_pct THEN v_severidad := 'bloqueante';
  ELSE v_severidad := 'informativa';
  END IF;
  RETURN jsonb_build_object(
    'tarifa_vigente',v_tarifa_vigente,'agente_sin_cupo',FALSE,'severidad',v_severidad,
    'cambios',v_cambios,'umbral_pct',v_umbral_pct,'max_delta_pct',v_max_delta_pct,
    'tarifa_id_vigente',CASE WHEN v_tarifa_vigente THEN v_cot.tarifa_id ELSE NULL END);
END;
$$;
CREATE FUNCTION public.revertir_proforma_al_cancelar_sustitucion(p_factura_id uuid) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ids uuid[] := ARRAY[]::uuid[];
  v_id uuid;
  v_liberadas uuid[] := ARRAY[]::uuid[];
  v_facturas_vivas int;
  v_proforma_id_directa uuid;
  v_org uuid;
  v_uid uuid := auth.uid();
  v_email text := COALESCE(auth.email(), '');
BEGIN
  IF p_factura_id IS NULL THEN
    RAISE EXCEPTION 'LC_FACTURA_REQUERIDA: falta el identificador de la factura'
      USING ERRCODE = '22023';
  END IF;
  SELECT organization_id, proforma_id INTO v_org, v_proforma_id_directa
  FROM public.facturas WHERE id = p_factura_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_FACTURA_NO_EXISTE: la factura no existe' USING ERRCODE = 'P0002';
  END IF;
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'LC_NO_AUTORIZADO: sesión requerida' USING ERRCODE = '42501';
    END IF;
    IF public.is_org_member(v_org) IS NOT TRUE THEN
      RAISE EXCEPTION 'LC_ORG_FORBIDDEN: la factura pertenece a otra organización'
        USING ERRCODE = '42501';
    END IF;
    -- Rol financiero por organización: liberar proformas mueve dinero
    -- facturable, no basta con pertenecer a la organización.
    IF public.has_role(v_uid, 'super_admin'::public.app_role) IS NOT TRUE
       AND public.has_any_role_in_org(
             v_uid,
             ARRAY['admin','admin_org','contador','tesorero']::public.app_role[],
             v_org
           ) IS NOT TRUE THEN
      RAISE EXCEPTION 'LC_ROL_INSUFICIENTE: necesitas un rol financiero para liberar proformas'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  IF v_proforma_id_directa IS NOT NULL THEN
    v_ids := array_append(v_ids, v_proforma_id_directa);
  END IF;
  v_ids := v_ids || COALESCE(
    (SELECT array_agg(DISTINCT proforma_id_origen)
       FROM public.conceptos_factura
      WHERE factura_id = p_factura_id
        AND deleted_at IS NULL
        AND proforma_id_origen IS NOT NULL),
    ARRAY[]::uuid[]
  );
  v_ids := array(
    SELECT DISTINCT x FROM unnest(v_ids) AS x WHERE x IS NOT NULL
  );
  IF array_length(v_ids, 1) IS NULL THEN
    RETURN v_liberadas;
  END IF;
  FOREACH v_id IN ARRAY v_ids LOOP
    SELECT count(*) INTO v_facturas_vivas
    FROM public.facturas f
    WHERE f.estado NOT IN ('Cancelada','Sustituida')
      AND f.id <> p_factura_id
      AND (
        f.proforma_id = v_id
        OR EXISTS (
          SELECT 1 FROM public.conceptos_factura cf
           WHERE cf.factura_id = f.id
             AND cf.deleted_at IS NULL
             AND cf.proforma_id_origen = v_id
        )
      );
    IF v_facturas_vivas = 0 THEN
      UPDATE public.proformas
         SET estado_proforma   = 'pendiente',
             fecha_facturacion = NULL,
             updated_at        = now()
       WHERE id = v_id
         AND organization_id = v_org
         AND estado_proforma = 'facturada';
      IF FOUND THEN
        v_liberadas := array_append(v_liberadas, v_id);
        INSERT INTO public.bitacora_actividad (
          organization_id, usuario_id, usuario_email,
          accion, modulo, entidad_id, entidad_nombre, detalles
        ) VALUES (
          v_org, COALESCE(v_uid, '00000000-0000-0000-0000-000000000000'::uuid), v_email,
          'revertir_proforma_cancelacion_sustitucion', 'facturacion',
          v_id, NULL,
          jsonb_build_object('factura_id', p_factura_id)
        );
      END IF;
    END IF;
  END LOOP;
  RETURN v_liberadas;
END;
$$;
CREATE FUNCTION public.rls_tenant_scope_ok(_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN (SELECT public.has_role(auth.uid(), 'super_admin'::app_role))
      THEN _org IS NOT NULL AND _org = (SELECT public.org_scope())
    ELSE true
  END;
$$;
CREATE FUNCTION public.rol_efectivo(_user_id uuid, _org uuid) RETURNS public.app_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT om.role FROM public.organization_members om
      WHERE om.user_id = _user_id AND om.organization_id = _org
      LIMIT 1),
    (SELECT ur.role FROM public.user_roles ur
      WHERE ur.user_id = _user_id
      ORDER BY ur.role LIMIT 1)
  );
$$;
CREATE FUNCTION public.roles_jerarquia(_role public.app_role) RETURNS public.app_role[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE _role
    WHEN 'super_admin'::app_role THEN ARRAY['super_admin']::app_role[]
    WHEN 'admin'::app_role THEN ARRAY['admin','admin_org','super_admin']::app_role[]
    WHEN 'admin_org'::app_role THEN ARRAY['admin_org','super_admin']::app_role[]
    WHEN 'operador'::app_role THEN ARRAY['operador','coordinador_logistico','gerente_operaciones','admin','admin_org','super_admin']::app_role[]
    WHEN 'viewer'::app_role THEN ARRAY['viewer','customer_service','vendedor','contador','tesorero','auxiliar_contable','ejecutivo_cobranza','ejecutivo_pricing','gerente_operaciones','gerente_visor','gerente_comercial','coordinador_logistico','admin','admin_org','super_admin']::app_role[]
    WHEN 'vendedor'::app_role THEN ARRAY['vendedor','gerente_comercial','admin_org','super_admin']::app_role[]
    WHEN 'contador'::app_role THEN ARRAY['contador','auxiliar_contable','admin_org','super_admin']::app_role[]
    WHEN 'tesorero'::app_role THEN ARRAY['tesorero','admin_org','super_admin']::app_role[]
    WHEN 'auxiliar_contable'::app_role THEN ARRAY['auxiliar_contable','contador','admin_org','super_admin']::app_role[]
    WHEN 'ejecutivo_cobranza'::app_role THEN ARRAY['ejecutivo_cobranza','contador','admin_org','super_admin']::app_role[]
    ELSE ARRAY[_role]::app_role[]
  END
$$;
CREATE FUNCTION public.run_auditoria_backfill_legacy() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_conceptos jsonb;
  v_proformas jsonb;
  v_tot_conceptos bigint := 0;
  v_tot_embarques bigint := 0;
  v_tot_proformas bigint := 0;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_role(v_caller, 'super_admin') THEN
    RAISE EXCEPTION 'Solo super_admin puede ejecutar este backfill' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'organization_id', organization_id,
           'conceptos', conceptos_actualizados,
           'embarques', embarques_afectados
         )), '[]'::jsonb),
         COALESCE(SUM(conceptos_actualizados), 0),
         COALESCE(SUM(embarques_afectados), 0)
    INTO v_conceptos, v_tot_conceptos, v_tot_embarques
  FROM public.backfill_conceptos_venta_facturados();
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'organization_id', organization_id,
           'proformas', proformas_actualizadas
         )), '[]'::jsonb),
         COALESCE(SUM(proformas_actualizadas), 0)
    INTO v_proformas, v_tot_proformas
  FROM public.backfill_proformas_aceptadas();
  RETURN jsonb_build_object(
    'ejecutado_at', now(),
    'ejecutado_por', v_caller,
    'totales', jsonb_build_object(
      'conceptos_actualizados', v_tot_conceptos,
      'embarques_afectados', v_tot_embarques,
      'proformas_actualizadas', v_tot_proformas
    ),
    'por_organizacion_conceptos', v_conceptos,
    'por_organizacion_proformas', v_proformas
  );
END;
$$;
CREATE FUNCTION public.saldo_cuenta_bancaria(p_cuenta_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saldo numeric;
BEGIN
  -- Canon de estado_cuenta_bancario: saldo_inicial corresponde a
  -- fecha_saldo_inicial; los movimientos previos a ese corte NO se suman
  -- (ya están dentro del saldo inicial) y los borrados nunca cuentan.
  SELECT COALESCE(cb.saldo_inicial, 0)
       + COALESCE(SUM(COALESCE(m.abono, 0) - COALESCE(m.cargo, 0)), 0)
    INTO v_saldo
  FROM public.cuentas_bancarias cb
  LEFT JOIN public.bbva_movimientos m
    ON m.cuenta_bancaria_id = cb.id
   AND m.deleted_at IS NULL
   AND m.fecha >= cb.fecha_saldo_inicial
  WHERE cb.id = p_cuenta_id
  GROUP BY cb.id, cb.saldo_inicial;
  RETURN v_saldo;  -- NULL si la cuenta no existe: el caller valida.
END;
$$;
CREATE FUNCTION public.saldo_factura(p_factura_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric; v_estado estado_factura; v_org uuid;
  v_caller_org uuid; v_uid uuid; v_pagos numeric; v_ncs numeric;
  v_moneda text; v_tc numeric;
BEGIN
  SELECT total, estado, organization_id, moneda::text, tipo_cambio
    INTO v_total, v_estado, v_org, v_moneda, v_tc
  FROM public.facturas WHERE id = p_factura_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN 0; END IF;
  v_uid := auth.uid();
  v_caller_org := public.current_user_org_id();
  IF v_uid IS NOT NULL
     AND auth.role() <> 'service_role'
     AND NOT public.has_role(v_uid, 'super_admin'::app_role) THEN
    IF v_caller_org IS NULL OR v_org IS DISTINCT FROM v_caller_org THEN
      RETURN 0;
    END IF;
  END IF;
  -- BUG-2026-08-25: 'Pagada' también es terminal (facturas legacy sin pagos
  -- capturados generaban adeudo fantasma en el estado de cuenta).
  IF v_estado IN ('Cancelada', 'Sustituida', 'Borrador', 'Pagada') THEN RETURN 0; END IF;
  SELECT COALESCE(SUM(monto_aplicado_factura), 0) INTO v_pagos
  FROM public.pagos_factura
  WHERE factura_id = p_factura_id AND deleted_at IS NULL;
  -- BUG-04 (auditoría 2026-08-18): misma conversión que `cartera_pendiente`.
  -- Si la NC no se puede convertir (falta TC) NO se resta: preferimos un saldo
  -- mayor a marcar como Pagada una factura que no lo está.
  SELECT COALESCE(SUM(
      CASE
        WHEN nc.moneda::text = v_moneda THEN nc.monto
        WHEN v_moneda = 'MXN' AND nc.moneda::text <> 'MXN' AND nc.tipo_cambio > 1
          THEN nc.monto * nc.tipo_cambio
        WHEN v_moneda <> 'MXN' AND nc.moneda::text = 'MXN' AND v_tc > 1
          THEN nc.monto / v_tc
        WHEN v_moneda <> 'MXN' AND nc.moneda::text <> 'MXN'
             AND v_moneda <> nc.moneda::text
             AND nc.tipo_cambio > 1 AND v_tc > 1
          THEN (nc.monto * nc.tipo_cambio) / v_tc
        ELSE 0
      END), 0) INTO v_ncs
  FROM public.factura_notas_credito nc
  WHERE nc.factura_id = p_factura_id AND nc.deleted_at IS NULL AND nc.estado = 'Aplicada';
  RETURN COALESCE(v_total, 0) - v_pagos - v_ncs;
END;
$$;
CREATE FUNCTION public.saldo_factura_bruto(p_factura_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric; v_org uuid; v_uid uuid; v_caller_org uuid;
  v_pagos numeric; v_ncs numeric;
BEGIN
  SELECT f.total, f.organization_id INTO v_total, v_org
  FROM public.facturas f
  WHERE f.id = p_factura_id AND f.deleted_at IS NULL
    AND f.estado NOT IN ('Cancelada', 'Sustituida', 'Borrador');
  IF NOT FOUND THEN RETURN 0; END IF;
  v_uid := auth.uid();
  v_caller_org := public.current_user_org_id();
  IF v_uid IS NOT NULL
     AND auth.role() <> 'service_role'
     AND NOT public.has_role(v_uid, 'super_admin'::app_role) THEN
    IF v_caller_org IS NULL OR v_org IS DISTINCT FROM v_caller_org THEN
      RETURN 0;
    END IF;
  END IF;
  SELECT COALESCE(SUM(p.monto_aplicado_factura), 0) INTO v_pagos
  FROM public.pagos_factura p
  WHERE p.factura_id = p_factura_id AND p.deleted_at IS NULL;
  v_ncs := public._nc_aplicadas_moneda_factura(p_factura_id);
  RETURN COALESCE(v_total, 0) - v_pagos - COALESCE(v_ncs, 0);
END;
$$;
CREATE FUNCTION public.saldo_factura_proveedor(p_factura_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_oid uuid := public.current_user_org_id();
  v_f public.proveedor_facturas;
  v_pagado numeric;
  v_nc numeric;
  v_incompleto boolean;
  v_nc_incompleto boolean;
BEGIN
  IF v_oid IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_SIN_CONTEXTO: no hay organización activa' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_f
  FROM public.proveedor_facturas
  WHERE id = p_factura_id
    AND deleted_at IS NULL
    AND organization_id = v_oid
    AND estado <> 'Cancelada';
  IF v_f.id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT COALESCE(SUM(public.monto_pago_en_moneda_factura(pp.monto, pp.moneda::text, pp.tipo_cambio_usd, v_f.moneda::text)), 0),
         BOOL_OR(pp.moneda::text <> v_f.moneda::text AND COALESCE(pp.tipo_cambio_usd, 0) <= 0)
    INTO v_pagado, v_incompleto
  FROM public.pagos_proveedor pp
  WHERE pp.proveedor_factura_id = p_factura_id
    AND pp.deleted_at IS NULL;
  -- Ola 17 · H8-B: la NC se valúa en la moneda de la factura con su TC DOF.
  SELECT COALESCE(SUM(public.monto_pago_en_moneda_factura(nc.monto, nc.moneda::text, nc.tipo_cambio, v_f.moneda::text)), 0),
         BOOL_OR(nc.moneda::text <> v_f.moneda::text AND COALESCE(nc.tipo_cambio, 0) <= 0)
    INTO v_nc, v_nc_incompleto
  FROM public.proveedor_notas_credito nc
  WHERE nc.proveedor_factura_id = p_factura_id
    AND nc.deleted_at IS NULL
    AND nc.estado = 'Aplicada';
  RETURN jsonb_build_object(
    'factura_id', p_factura_id,
    'moneda', v_f.moneda::text,
    'total', COALESCE(v_f.total, 0),
    'pagado', ROUND(v_pagado, 2),
    'nc_aplicada', ROUND(v_nc, 2),
    'saldo', ROUND(GREATEST(COALESCE(v_f.total, 0) - v_pagado - v_nc, 0), 2),
    'flujo_incompleto', COALESCE(v_incompleto, false) OR COALESCE(v_nc_incompleto, false)
  );
END;
$$;
CREATE FUNCTION public.seed_demo_organization() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- M8: sólo service_role (edge `demo-access`) o super_admin explícito.
  IF coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') <> 'service_role'
     AND NOT public.has_role(auth.uid(), 'super_admin'::public.app_role) THEN
    RAISE EXCEPTION 'LC_SEED_DEMO_NO_AUTORIZADO: solo service_role o super_admin'
      USING ERRCODE = 'P0001';
  END IF;
  -- Candado de transacción: un solo re-sembrado a la vez.
  PERFORM pg_advisory_xact_lock(hashtext('seed_demo_organization'));
  -- Ola 4 (H7): antes el reseed fallaba por FK si alguien había operado en la
  -- demo (facturas/pagos generados después del último sembrado).
  PERFORM public._seed_demo_limpiar_financiero();
  PERFORM public.seed_demo_organization_core();
END;
$$;
