CREATE FUNCTION public.seed_demo_organization_guarded(p_skip_ms bigint DEFAULT 600000) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ultimo timestamptz;
BEGIN
  -- M8 (mismo guard que seed_demo_organization): sólo service_role
  -- (edge demo-access) o super_admin explícito.
  IF coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') <> 'service_role'
     AND NOT public.has_role(auth.uid(), 'super_admin'::public.app_role) THEN
    RAISE EXCEPTION 'LC_SEED_DEMO_NO_AUTORIZADO: solo service_role o super_admin'
      USING ERRCODE = 'P0001';
  END IF;
  -- REF-05: candado + chequeo de edad + seed + marcador en UNA transacción
  -- (el chequeo previo en la edge era check-then-act).
  PERFORM pg_advisory_xact_lock(hashtext('seed_demo_organization'));
  SELECT last_seeded_at INTO v_ultimo FROM public.demo_seed_state WHERE id = true;
  IF v_ultimo IS NOT NULL
     AND (extract(epoch FROM clock_timestamp()) - extract(epoch FROM v_ultimo)) * 1000 < p_skip_ms THEN
    RETURN false; -- sembrado recientemente: omitir
  END IF;
  PERFORM public.seed_demo_organization_core();
  INSERT INTO public.demo_seed_state (id, last_seeded_at)
  VALUES (true, clock_timestamp())
  ON CONFLICT (id) DO UPDATE SET last_seeded_at = excluded.last_seeded_at;
  RETURN true; -- se re-sembró
END;
$$;
CREATE FUNCTION public.seed_presupuesto_categorias(p_organization_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing INTEGER;
  v_org uuid;
  v_mantenimiento boolean;
BEGIN
  -- `pg_has_role(current_user,'service_role','MEMBER')` cubre los callers de
  -- mantenimiento (postgres/superuser, replay de migraciones y suites RLS del
  -- CI). `authenticated` NO es miembro de service_role.
  v_mantenimiento := public.has_role(auth.uid(), 'super_admin'::app_role)
     OR COALESCE(auth.role()::text, '') = 'service_role'
     OR pg_has_role(current_user, 'service_role', 'MEMBER');
  IF v_mantenimiento THEN
    v_org := p_organization_id;
  ELSE
    -- Guard de rol: espejo de presupuesto_categorias_admin_insert.
    IF NOT public.es_admin_catalogo(auth.uid()) THEN
      RAISE EXCEPTION 'LC_ROL_FORBIDDEN: solo un administrador puede sembrar las categorías de presupuesto'
        USING ERRCODE = '42501';
    END IF;
    v_org := public.current_user_org_id();
    IF v_org IS NULL OR p_organization_id IS DISTINCT FROM v_org THEN
      RAISE EXCEPTION 'LC_ORG_FORBIDDEN: no puedes sembrar categorías de otra organización'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  SELECT COUNT(*) INTO v_existing
  FROM public.presupuesto_categorias
  WHERE organization_id = v_org;
  IF v_existing > 0 THEN RETURN; END IF;
  INSERT INTO public.presupuesto_categorias (organization_id, nombre, tipo_contable, orden, activa) VALUES
    (v_org, 'Costos directos de embarque (COGS)', 'CostoDirectoEmbarque', 10, true),
    (v_org, 'Gastos de administración',           'Administracion',        20, true),
    (v_org, 'Gastos de venta',                    'Venta',                 30, true);
END;
$$;
CREATE FUNCTION public.seleccionar_lote_sat_semanal(p_max_orgs integer DEFAULT 5) RETURNS TABLE(organization_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- FOR UPDATE dentro del CTE + UPDATE en el mismo statement: dos corridas
  -- concurrentes no se llevan el mismo lote. Estampar al seleccionar (no al
  -- terminar) empuja la org al final de la fila aunque la edge muera a media
  -- corrida: se reintentará tras barrer el resto (cobertura garantizada).
  RETURN QUERY
  WITH lote AS (
    SELECT o.id
    FROM public.organizations o
    WHERE o.rfc IS NOT NULL AND btrim(o.rfc) <> ''
    ORDER BY o.sat_barrido_fecha ASC NULLS FIRST, o.created_at ASC, o.id ASC
    LIMIT GREATEST(p_max_orgs, 1)
    FOR UPDATE OF o
  )
  UPDATE public.organizations o
  SET sat_barrido_fecha = pg_catalog.now()
  FROM lote
  WHERE o.id = lote.id
  RETURNING o.id;
END;
$$;
CREATE FUNCTION public.set_auditoria_revisado_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado_revision = 'revisado' AND (OLD.estado_revision IS DISTINCT FROM 'revisado') THEN
    NEW.revisado_at = COALESCE(NEW.revisado_at, now());
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.set_embarque_created_by() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.created_by IS NULL THEN
    NEW.created_by := auth.uid();
  END IF;
  IF (NEW.created_by_email IS NULL OR NEW.created_by_email = '') AND NEW.created_by IS NOT NULL THEN
    SELECT email INTO NEW.created_by_email FROM auth.users WHERE id = NEW.created_by;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.set_embarque_fechas_originales() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.etd_original IS NULL THEN NEW.etd_original := NEW.etd; END IF;
  IF NEW.eta_original IS NULL THEN NEW.eta_original := NEW.eta; END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.set_estado_rep_pago() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_metodo text;
  v_uuid text;
BEGIN
  -- Sólo aplica al insertar (no recalculamos en update para no pisar estados ya timbrados)
  IF TG_OP <> 'INSERT' THEN
    RETURN NEW;
  END IF;
  SELECT metodo_pago, uuid_fiscal
    INTO v_metodo, v_uuid
  FROM public.facturas
  WHERE id = NEW.factura_id;
  -- Si la factura es PPD y ya está timbrada (tiene UUID), el pago requiere REP
  IF v_metodo = 'PPD' AND v_uuid IS NOT NULL THEN
    NEW.estado_rep := 'Pendiente';
  ELSE
    NEW.estado_rep := 'NoAplica';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.set_facturapi_api_key(p_org_id uuid, p_ambiente text, p_api_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'extensions'
    AS $$
DECLARE
  v_key text := btrim(coalesce(p_api_key, ''));
  v_prefix_ok boolean;
  v_new_id uuid;
  v_old_id uuid;
  v_last4 text;
  v_name text;
BEGIN
  PERFORM public._assert_facturapi_admin(p_org_id);
  IF p_ambiente NOT IN ('sandbox','live') THEN
    RAISE EXCEPTION 'ambiente_invalido' USING ERRCODE = '22023';
  END IF;
  IF length(v_key) < 16 THEN
    RAISE EXCEPTION 'api_key_invalida' USING ERRCODE = '22023';
  END IF;
  v_prefix_ok := (p_ambiente = 'sandbox' AND v_key LIKE 'sk_test_%')
              OR (p_ambiente = 'live'    AND v_key LIKE 'sk_live_%');
  IF NOT v_prefix_ok THEN
    RAISE EXCEPTION 'api_key_prefix_no_coincide_con_ambiente' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.facturapi_credenciales (organization_id, ambiente)
  VALUES (p_org_id, p_ambiente)
  ON CONFLICT (organization_id) DO NOTHING;
  v_last4 := right(v_key, 4);
  v_name  := 'facturapi:' || p_org_id::text || ':' || p_ambiente || ':' || gen_random_uuid()::text;
  v_new_id := vault.create_secret(v_key, v_name, 'FacturApi API key (' || p_ambiente || ') para org ' || p_org_id::text);
  IF p_ambiente = 'sandbox' THEN
    SELECT api_key_sandbox_vault_id INTO v_old_id FROM public.facturapi_credenciales WHERE organization_id = p_org_id;
    UPDATE public.facturapi_credenciales
       SET api_key_sandbox_vault_id = v_new_id,
           api_key_sandbox_last4    = v_last4,
           updated_at               = now()
     WHERE organization_id = p_org_id;
  ELSE
    SELECT api_key_live_vault_id INTO v_old_id FROM public.facturapi_credenciales WHERE organization_id = p_org_id;
    UPDATE public.facturapi_credenciales
       SET api_key_live_vault_id = v_new_id,
           api_key_live_last4    = v_last4,
           updated_at            = now()
     WHERE organization_id = p_org_id;
  END IF;
  IF v_old_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_old_id;
  END IF;
  INSERT INTO public.bitacora_actividad (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
  VALUES (
    p_org_id,
    auth.uid(),
    COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), ''),
    'facturapi_api_key_actualizada',
    'facturapi_credenciales',
    p_org_id,
    '',
    jsonb_build_object('ambiente', p_ambiente, 'last4', v_last4)
  );
END;
$$;
CREATE FUNCTION public.set_folio_interno_proveedor_factura() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.folio_interno IS NULL OR NEW.folio_interno = '' THEN
    NEW.folio_interno := public.siguiente_folio_proveedor(NEW.organization_id);
  END IF;
  RETURN NEW;
END;
$$;
CREATE TABLE public.embarque_garantias_contenedor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    embarque_id uuid NOT NULL,
    embarque_contenedor_id uuid NOT NULL,
    naviera_id uuid,
    monto_deposito_usd numeric(12,2) DEFAULT 0 NOT NULL,
    tiene_carta_garantia boolean DEFAULT false NOT NULL,
    estado text DEFAULT 'pendiente'::text NOT NULL,
    fecha_deposito date,
    fecha_liberacion date,
    notas text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    proveedor_factura_id uuid,
    referencia_deposito text,
    fecha_limite_devolucion date,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT embarque_garantias_contenedor_estado_check CHECK ((estado = ANY (ARRAY['pendiente'::text, 'depositado'::text, 'liberado'::text, 'retenido'::text]))),
    CONSTRAINT embarque_garantias_contenedor_monto_deposito_usd_check CHECK ((monto_deposito_usd >= (0)::numeric))
);
CREATE FUNCTION public.set_garantia_estado(p_id uuid, p_estado text DEFAULT NULL::text, p_fecha_deposito date DEFAULT NULL::date, p_fecha_liberacion date DEFAULT NULL::date, p_monto numeric DEFAULT NULL::numeric, p_referencia text DEFAULT NULL::text, p_notas text DEFAULT NULL::text) RETURNS public.embarque_garantias_contenedor
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.embarque_garantias_contenedor;
  v_org uuid;
BEGIN
  IF NOT (
    has_role(auth.uid(), 'admin'::app_role)
    OR has_role(auth.uid(), 'admin_org'::app_role)
    OR has_role(auth.uid(), 'operador'::app_role)
    OR has_role(auth.uid(), 'super_admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'LC_GARANTIA_SIN_ROL'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_row FROM public.embarque_garantias_contenedor WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'LC_GARANTIA_NO_ENCONTRADA' USING ERRCODE = 'no_data_found';
  END IF;
  v_org := current_user_org_id();
  IF v_row.organization_id <> v_org AND NOT has_role(auth.uid(), 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_GARANTIA_ORG_MISMATCH' USING ERRCODE = 'insufficient_privilege';
  END IF;
  UPDATE public.embarque_garantias_contenedor
     SET estado             = COALESCE(p_estado, estado),
         fecha_deposito     = COALESCE(p_fecha_deposito, fecha_deposito),
         fecha_liberacion   = COALESCE(p_fecha_liberacion, fecha_liberacion),
         monto_deposito_usd = COALESCE(p_monto, monto_deposito_usd),
         referencia_deposito= COALESCE(p_referencia, referencia_deposito),
         notas              = COALESCE(p_notas, notas),
         updated_at         = now()
   WHERE id = p_id
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;
CREATE FUNCTION public.set_super_admin_org(p_org uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'LC_NO_AUTORIZADO: sólo el super admin puede cambiar de organización';
  END IF;
  IF p_org IS NULL THEN
    DELETE FROM public.super_admin_org_activa WHERE user_id = auth.uid();
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = p_org) THEN
    RAISE EXCEPTION 'LC_ORG_INEXISTENTE: la organización no existe';
  END IF;
  INSERT INTO public.super_admin_org_activa (user_id, organization_id)
  VALUES (auth.uid(), p_org)
  ON CONFLICT (user_id) DO UPDATE SET organization_id = EXCLUDED.organization_id, updated_at = now();
END;
$$;
CREATE FUNCTION public.sidebar_alert_counts() RETURNS TABLE(embarques_demora bigint, facturas_vencidas bigint, garantias_atoradas bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    (SELECT count(*) FROM embarques e
     WHERE e.eta IS NOT NULL
       AND e.deleted_at IS NULL
       AND (current_date - e.eta) >= 7
       AND CASE
         WHEN e.estado IN ('Arribo','En Aduana','Entregado','EIR','Cerrado') THEN e.estado::text
         WHEN e.modo = 'Marítimo' AND e.tipo = 'Importación'
              AND e.etd IS NOT NULL AND e.eta IS NOT NULL THEN
           CASE
             WHEN current_date < e.etd THEN 'Confirmado'
             WHEN current_date >= e.etd AND current_date < e.eta THEN 'En Tránsito'
             WHEN current_date >= e.eta THEN 'Arribo'
             ELSE e.estado::text
           END
         ELSE e.estado::text
       END = 'Arribo'
       AND e.organization_id = public.org_scope()
    ) AS embarques_demora,
    (SELECT count(*) FROM facturas f
     WHERE f.estado = 'Vencida'
       AND f.deleted_at IS NULL
       AND f.organization_id = public.org_scope()
    ) AS facturas_vencidas,
    (SELECT count(*) FROM embarque_garantias_contenedor g
     JOIN embarques e ON e.id = g.embarque_id
     WHERE g.estado = 'depositado'
       AND g.deleted_at IS NULL
       AND e.deleted_at IS NULL
       AND g.fecha_deposito IS NOT NULL
       AND (current_date - g.fecha_deposito) > 30
       AND e.organization_id = public.org_scope()
    ) AS garantias_atoradas;
$$;
CREATE FUNCTION public.siguiente_folio_cotizacion() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := public.current_user_org_id();
  v_num bigint;
  v_anio text := to_char(now() AT TIME ZONE 'America/Mexico_City', 'YYYY');
  v_tipo text := 'cotizacion_' || v_anio;
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_NO_RESUELTA: no se pudo determinar la organización';
  END IF;
  INSERT INTO public.folio_secuencias (organization_id, tipo, ultimo_numero)
  VALUES (v_org, v_tipo, 1)
  ON CONFLICT (organization_id, tipo)
  DO UPDATE SET ultimo_numero = folio_secuencias.ultimo_numero + 1,
                updated_at = now()
  RETURNING ultimo_numero INTO v_num;
  RETURN 'COT-' || v_anio || '-' || lpad(v_num::text, 4, '0');
END;
$$;
