DECLARE
  v_org uuid := public.current_user_org_id();
  v_num bigint;
  v_anio text := to_char(now() AT TIME ZONE 'America/Mexico_City', 'YYYY');
  v_tipo text := 'cotizacion_prospecto_' || v_anio;
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_NO_RESUELTA: no se pudo determinar la organización';
  END IF;
  INSERT INTO public.folio_secuencias (organization_id, tipo, ultimo_numero)
  VALUES (v_org, v_tipo, 1)
  ON CONFLICT (organization_id, tipo)
  DO UPDATE SET ultimo_numero = folio_secuencias.ultimo_numero + 1,
                updated_at = now()
  RETURNING ultimo_numero INTO v_num;
  RETURN 'COT-P-' || v_anio || '-' || lpad(v_num::text, 4, '0');
END;
$$;
CREATE FUNCTION public.siguiente_folio_proveedor(p_org_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_num bigint;
BEGIN
  -- FIX BL-03: solo miembros de la organización (o super_admin, incluido en
  -- is_org_member) pueden consumir la secuencia de folios FP-.
  IF auth.uid() IS NOT NULL AND NOT public.is_org_member(p_org_id) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.folio_secuencias (organization_id, tipo, ultimo_numero)
  VALUES (p_org_id, 'factura_proveedor', 1)
  ON CONFLICT (organization_id, tipo)
  DO UPDATE SET ultimo_numero = folio_secuencias.ultimo_numero + 1,
                updated_at = now()
  RETURNING ultimo_numero INTO v_num;
  RETURN 'FP-' || lpad(v_num::text, 6, '0');
END;
$$;
CREATE FUNCTION public.siguiente_folio_traspaso(p_org_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_num bigint;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'LC_ORG_REQUERIDA' USING ERRCODE = '42501';
  END IF;
  IF auth.uid() IS NOT NULL AND NOT public.is_org_member(p_org_id) THEN
    RAISE EXCEPTION 'LC_ORG_AJENA' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.folio_secuencias (organization_id, tipo, ultimo_numero)
  VALUES (p_org_id, 'traspaso_bancario', 1)
  ON CONFLICT (organization_id, tipo)
  DO UPDATE SET ultimo_numero = folio_secuencias.ultimo_numero + 1,
                updated_at = now()
  RETURNING ultimo_numero INTO v_num;
  RETURN 'TR-' || lpad(v_num::text, 6, '0');
END;
$$;
CREATE TABLE public.embarque_contenedores (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    embarque_id uuid NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    numero_contenedor text DEFAULT ''::text NOT NULL,
    tipo_contenedor text DEFAULT ''::text NOT NULL,
    bl_house text DEFAULT ''::text,
    peso_kg numeric DEFAULT 0 NOT NULL,
    volumen_m3 numeric DEFAULT 0 NOT NULL,
    piezas integer DEFAULT 0 NOT NULL,
    orden integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    fecha_descarga date,
    fecha_devolucion date,
    dias_libres_override integer,
    CONSTRAINT embarque_contenedores_medidas_no_negativas CHECK (((COALESCE(peso_kg, (0)::numeric) >= (0)::numeric) AND (COALESCE(volumen_m3, (0)::numeric) >= (0)::numeric) AND (COALESCE(piezas, 0) >= 0)))
);
CREATE FUNCTION public.sincronizar_contenedores_embarque(p_embarque_id uuid, p_contenedores jsonb) RETURNS SETOF public.embarque_contenedores
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_input record;
  v_ids_conservados uuid[];
  v_orden integer := 0;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM public.embarques
  WHERE id = p_embarque_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Embarque no encontrado: %', p_embarque_id;
  END IF;
  PERFORM public._assert_writer(v_org_id);
  SELECT COALESCE(array_agg((elem->>'id')::uuid), ARRAY[]::uuid[]) INTO v_ids_conservados
  FROM jsonb_array_elements(p_contenedores) AS elem
  WHERE elem ? 'id' AND elem->>'id' IS NOT NULL AND elem->>'id' <> '';
  UPDATE public.embarque_contenedores
  SET deleted_at = now()
  WHERE embarque_id = p_embarque_id
    AND deleted_at IS NULL
    AND NOT (id = ANY(v_ids_conservados));
  FOR v_input IN
    SELECT
      (elem->>'id') AS id_str,
      (elem->>'numero_contenedor') AS numero_contenedor,
      (elem->>'tipo_contenedor') AS tipo_contenedor,
      NULLIF(elem->>'bl_house', '') AS bl_house,
      NULLIF(elem->>'peso_kg', '')::numeric AS peso_kg,
      NULLIF(elem->>'volumen_m3', '')::numeric AS volumen_m3,
      NULLIF(elem->>'piezas', '')::integer AS piezas,
      COALESCE(NULLIF(elem->>'orden', '')::integer, 0) AS orden,
      ord.rn AS pos
    FROM jsonb_array_elements(p_contenedores) WITH ORDINALITY AS ord(elem, rn)
    ORDER BY ord.rn
  LOOP
    v_orden := COALESCE(NULLIF(v_input.orden, 0), v_input.pos::integer);
    IF v_input.id_str IS NOT NULL AND v_input.id_str <> '' THEN
      UPDATE public.embarque_contenedores
      SET numero_contenedor = v_input.numero_contenedor,
          tipo_contenedor = v_input.tipo_contenedor,
          bl_house = v_input.bl_house,
          peso_kg = v_input.peso_kg,
          volumen_m3 = v_input.volumen_m3,
          piezas = v_input.piezas,
          orden = v_orden
      WHERE id = v_input.id_str::uuid
        AND embarque_id = p_embarque_id;
    ELSE
      INSERT INTO public.embarque_contenedores (
        embarque_id, numero_contenedor, tipo_contenedor, bl_house,
        peso_kg, volumen_m3, piezas, orden
      ) VALUES (
        p_embarque_id, v_input.numero_contenedor, v_input.tipo_contenedor, v_input.bl_house,
        v_input.peso_kg, v_input.volumen_m3, v_input.piezas, v_orden
      );
    END IF;
  END LOOP;
  RETURN QUERY
  SELECT *
  FROM public.embarque_contenedores
  WHERE embarque_id = p_embarque_id
    AND deleted_at IS NULL
  ORDER BY orden ASC, created_at ASC;
END;
$$;
CREATE FUNCTION public.snapshot_cotizacion_al_enviar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_next_version integer;
  v_costos jsonb;
  v_should_snapshot boolean := false;
BEGIN
  IF (OLD.estado IS DISTINCT FROM NEW.estado) THEN
    IF NEW.estado::text = 'Enviada' THEN
      v_should_snapshot := true;
    ELSIF NEW.estado::text = 'Aceptada' AND OLD.estado::text IN ('Borrador','Solicitada') THEN
      v_should_snapshot := true;
    END IF;
  END IF;
  IF v_should_snapshot THEN
    SELECT COALESCE(MAX(version_num), 0) + 1
      INTO v_next_version
      FROM public.cotizacion_versiones
     WHERE cotizacion_id = NEW.id;
    SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.created_at), '[]'::jsonb)
      INTO v_costos
      FROM public.cotizacion_costos c
     WHERE c.cotizacion_id = NEW.id;
    INSERT INTO public.cotizacion_versiones (
      cotizacion_id, organization_id, version_num, folio,
      estado_al_snapshot, snapshot, costos_snapshot, created_by
    ) VALUES (
      NEW.id, NEW.organization_id, v_next_version, NEW.folio,
      NEW.estado::text, to_jsonb(NEW), v_costos, auth.uid()
    );
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.soft_delete_pago_factura(p_pago_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_deleted timestamptz;
BEGIN
  SELECT organization_id, deleted_at INTO v_org, v_deleted
    FROM public.pagos_factura WHERE id = p_pago_id;
  -- No revelar existencia de IDs ajenos: mismo error para "no existe" y "otra org"
  IF NOT FOUND
     OR v_deleted IS NOT NULL
     OR (v_org IS DISTINCT FROM public.current_user_org_id()
         AND NOT public.has_role(auth.uid(),'super_admin'::app_role)) THEN
    RAISE EXCEPTION 'LC_PAGO_NO_ENCONTRADO' USING ERRCODE='P0002';
  END IF;
  IF NOT public.es_escritor_financiero(auth.uid()) THEN
    RAISE EXCEPTION 'LC_PAGO_SIN_PERMISO' USING ERRCODE='P0001';
  END IF;
  UPDATE public.pagos_factura
    SET deleted_at = now(), updated_at = now()
    WHERE id = p_pago_id;
END;
$$;
CREATE FUNCTION public.soft_delete_pago_proveedor(p_pago_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_deleted timestamptz;
BEGIN
  SELECT organization_id, deleted_at INTO v_org, v_deleted
    FROM public.pagos_proveedor WHERE id = p_pago_id;
  IF NOT FOUND
     OR v_deleted IS NOT NULL
     OR (v_org IS DISTINCT FROM public.current_user_org_id()
         AND NOT public.has_role(auth.uid(),'super_admin'::app_role)) THEN
    RAISE EXCEPTION 'LC_PAGO_NO_ENCONTRADO' USING ERRCODE='P0002';
  END IF;
  IF NOT public.es_escritor_financiero(auth.uid()) THEN
    RAISE EXCEPTION 'LC_PAGO_SIN_PERMISO' USING ERRCODE='P0001';
  END IF;
  UPDATE public.pagos_proveedor
    SET deleted_at = now(), updated_at = now()
    WHERE id = p_pago_id;
END;
$$;
CREATE FUNCTION public.soft_delete_proveedor_factura(p_factura_id uuid, p_deleted_by uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_factura public.proveedor_facturas%ROWTYPE;
  v_user_id uuid := auth.uid();
  v_is_allowed boolean;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'LC_AUTH_REQUIRED'
      USING ERRCODE = '28000';
  END IF;
  SELECT *
    INTO v_factura
    FROM public.proveedor_facturas
   WHERE id = p_factura_id
   FOR UPDATE;
  IF NOT FOUND OR v_factura.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'LC_FACTURA_PROVEEDOR_NOT_FOUND'
      USING ERRCODE = 'P0002';
  END IF;
  SELECT
    public.has_role(v_user_id, 'super_admin'::public.app_role)
    OR public.has_role(v_user_id, 'admin'::public.app_role)
    OR public.has_role(v_user_id, 'contador'::public.app_role)
    OR public.has_role(v_user_id, 'auxiliar_contable'::public.app_role)
    OR public.has_role(v_user_id, 'tesorero'::public.app_role)
    OR EXISTS (
      SELECT 1
      FROM public.organization_members om
      WHERE om.user_id = v_user_id
        AND om.organization_id = v_factura.organization_id
        AND om.role IN (
          'admin_org'::public.app_role,
          'admin'::public.app_role,
          'contador'::public.app_role,
          'auxiliar_contable'::public.app_role,
          'tesorero'::public.app_role
        )
    )
    INTO v_is_allowed;
  IF NOT v_is_allowed THEN
    RAISE EXCEPTION 'LC_FORBIDDEN_FACTURA_PROVEEDOR_DELETE'
      USING ERRCODE = '42501';
  END IF;
  UPDATE public.proveedor_facturas
     SET deleted_at = now(),
         deleted_by = COALESCE(p_deleted_by, v_user_id),
         updated_at = now()
   WHERE id = p_factura_id;
END;
$$;
CREATE FUNCTION public.soft_delete_record(_table text, _id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  _org uuid;
  _uid uuid := auth.uid();
  _deps bigint;
  _estado text;
BEGIN
  IF NOT public.is_soft_delete_table(_table) THEN
    RAISE EXCEPTION 'Tabla no permitida para soft delete: %', _table;
  END IF;
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  EXECUTE format('SELECT organization_id FROM public.%I WHERE id = $1 AND deleted_at IS NULL', _table)
    INTO _org USING _id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'Registro no encontrado o ya borrado';
  END IF;
  IF _org IS DISTINCT FROM public.org_scope() THEN
    RAISE EXCEPTION 'LC_ORG_FUERA_DE_SCOPE: el registro pertenece a otra organización';
  END IF;
  IF NOT (
    public.has_role(_uid, 'super_admin'::app_role)
    OR public.has_role(_uid, 'admin'::app_role)
    OR public.has_role(_uid, 'operador'::app_role)
  ) THEN
    RAISE EXCEPTION 'Permisos insuficientes';
  END IF;
  IF _table = 'clientes' THEN
    -- QA-R2 D-03: sólo estados vivos/no terminales cuentan como dependencia:
    -- embarques Cancelados y cotizaciones en Borrador no bloquean la baja.
    SELECT
      (SELECT count(*) FROM public.embarques e
        WHERE e.cliente_id = _id AND e.deleted_at IS NULL
          AND e.estado <> 'Cancelado')
      + (SELECT count(*) FROM public.facturas f WHERE f.cliente_id = _id AND f.deleted_at IS NULL)
      + (SELECT count(*) FROM public.cotizaciones c
        WHERE c.cliente_id = _id AND c.deleted_at IS NULL
          AND c.estado <> 'Borrador')
      INTO _deps;
  ELSIF _table = 'embarques' THEN
    SELECT
      (SELECT count(*) FROM public.facturas f WHERE f.embarque_id = _id AND f.deleted_at IS NULL)
      + (SELECT count(*) FROM public.proveedor_facturas pf
         WHERE pf.embarque_id = _id AND pf.deleted_at IS NULL AND pf.estado <> 'Cancelada')
      INTO _deps;
  ELSIF _table = 'facturas' THEN
    SELECT f.estado::text INTO _estado FROM public.facturas f WHERE f.id = _id;
    IF _estado IS DISTINCT FROM 'Borrador' THEN
      RAISE EXCEPTION 'LC_BAJA_CON_DEPENDENCIAS: sólo facturas en Borrador pueden eliminarse; cancela o sustituye el CFDI'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF COALESCE(_deps, 0) > 0 THEN
    RAISE EXCEPTION 'LC_BAJA_CON_DEPENDENCIAS: el registro tiene % dependencias vivas', _deps
      USING ERRCODE = 'P0001';
  END IF;
  EXECUTE format('UPDATE public.%I SET deleted_at = now(), deleted_by = $1 WHERE id = $2', _table)
    USING _uid, _id;
END
$_$;
CREATE FUNCTION public.solicitar_reaprobacion_tarifa(p_cotizacion_id uuid, p_delta_jsonb jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cot         public.cotizaciones%ROWTYPE;
  v_caller_org  UUID := current_user_org_id();
  v_is_super    BOOLEAN := has_role(auth.uid(),'super_admin'::app_role);
  v_operador_id UUID;
BEGIN
  SELECT * INTO v_cot FROM public.cotizaciones WHERE id=p_cotizacion_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cotización no encontrada' USING ERRCODE='P0002'; END IF;
  IF NOT v_is_super AND v_cot.organization_id IS DISTINCT FROM v_caller_org THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
  UPDATE public.cotizaciones
  SET estado_revalidacion='pendiente_reaprobacion',
      revalidacion_solicitada_en=now(),
      revalidacion_resuelta_en=NULL,
      revalidacion_delta_jsonb=p_delta_jsonb,
      updated_at=now()
  WHERE id=p_cotizacion_id;
  BEGIN v_operador_id := v_cot.operador::uuid;
  EXCEPTION WHEN others THEN v_operador_id := NULL; END;
  IF v_operador_id IS NOT NULL THEN
    INSERT INTO public.notificaciones_internas(
      organization_id,usuario_id,tipo,titulo,mensaje,enlace,entidad_tipo,entidad_id)
    VALUES (v_cot.organization_id, v_operador_id,'tarifa_reaprobacion_requerida',
            'Cotización requiere re-aprobación de tarifa',
            'La cotización '||v_cot.folio||' tiene cambios en la tarifa vigente. Revisa y decide.',
            '/cotizaciones/'||v_cot.id::text,'cotizacion',v_cot.id);
  END IF;
  INSERT INTO public.bitacora_actividad(
    organization_id,usuario_id,usuario_email,modulo,accion,entidad_id,entidad_nombre,detalles)
  SELECT v_cot.organization_id, auth.uid(),
         COALESCE((SELECT email FROM auth.users WHERE id=auth.uid()),''),
         'Cotizaciones','reaprobacion_solicitada', v_cot.id, v_cot.folio,
         jsonb_build_object('delta',p_delta_jsonb);
END;
$$;
CREATE FUNCTION public.sugerir_embarques_para_proveedor(_proveedor_id uuid, _organization_id uuid, _limit integer DEFAULT 10) RETURNS TABLE(embarque_id uuid, expediente text, cliente_nombre text, estado text, etd date, eta date, match_tipo text, score integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _prov_nombre text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members m
    WHERE m.organization_id = _organization_id AND m.user_id = auth.uid()
  ) THEN
    RETURN;
  END IF;
  SELECT lower(nombre) INTO _prov_nombre
  FROM public.proveedores
  WHERE id = _proveedor_id AND organization_id = _organization_id;
  IF _prov_nombre IS NULL THEN RETURN; END IF;
  RETURN QUERY
  WITH candidatos AS (
    SELECT
      e.id AS embarque_id,
      e.expediente,
      e.cliente_nombre,
      e.estado::text AS estado,
      e.etd,
      e.eta,
      'Nombre coincide (agente/naviera/transportista)'::text AS match_tipo,
      100 AS score
    FROM public.embarques e
    WHERE e.organization_id = _organization_id
      AND e.deleted_at IS NULL
      AND e.estado NOT IN ('Cerrado','Cancelado','Entregado')
      AND (
        lower(coalesce(e.agente,'')) = _prov_nombre
        OR lower(coalesce(e.naviera,'')) = _prov_nombre
        OR lower(coalesce(e.transportista,'')) = _prov_nombre
        OR lower(coalesce(e.aerolinea,'')) = _prov_nombre
      )
    UNION ALL
    SELECT
      e.id, e.expediente, e.cliente_nombre, e.estado::text, e.etd, e.eta,
      'Tarifa vinculada (agente)'::text,
      80
    FROM public.embarques e
    JOIN public.costeo_tarifas t ON t.id = e.tarifa_id_aplicada
    JOIN public.costeo_agentes a ON a.id = t.agente_id
    WHERE e.organization_id = _organization_id
      AND e.deleted_at IS NULL
      AND e.estado NOT IN ('Cerrado','Cancelado','Entregado')
      AND a.proveedor_id = _proveedor_id
    UNION ALL
    SELECT
      e.id, e.expediente, e.cliente_nombre, e.estado::text, e.etd, e.eta,
      'Tarifa vinculada (naviera)'::text,
      80
    FROM public.embarques e
    JOIN public.costeo_tarifas t ON t.id = e.tarifa_id_aplicada
    JOIN public.costeo_navieras_condiciones nc
      ON nc.naviera_id = t.naviera_id AND nc.organization_id = e.organization_id
    WHERE e.organization_id = _organization_id
      AND e.deleted_at IS NULL
      AND e.estado NOT IN ('Cerrado','Cancelado','Entregado')
      AND nc.proveedor_id = _proveedor_id
  )
  SELECT DISTINCT ON (c.embarque_id)
    c.embarque_id, c.expediente, c.cliente_nombre, c.estado, c.etd, c.eta, c.match_tipo, c.score
  FROM candidatos c
  ORDER BY c.embarque_id, c.score DESC, c.eta DESC NULLS LAST
  LIMIT _limit;
END;
$$;
CREATE FUNCTION public.sync_conceptos_venta_facturado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM set_config('app.bypass_cierre', 'on', true);
  IF TG_OP = 'UPDATE' AND NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
    UPDATE public.conceptos_venta
       SET estado_facturacion = 'pendiente',
           proforma_id = NULL
     WHERE proforma_id = NEW.id
       AND deleted_at IS NULL;
    PERFORM set_config('app.bypass_cierre', 'off', true);
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.estado_proforma IS DISTINCT FROM OLD.estado_proforma THEN
    IF NEW.estado_proforma = 'facturada' THEN
      UPDATE public.conceptos_venta
         SET estado_facturacion = 'facturado'
       WHERE proforma_id = NEW.id
         AND deleted_at IS NULL
         AND estado_facturacion <> 'facturado';
    ELSIF NEW.estado_proforma = 'pendiente' AND OLD.estado_proforma = 'facturada' THEN
      UPDATE public.conceptos_venta
         SET estado_facturacion = 'en_proforma'
       WHERE proforma_id = NEW.id
         AND deleted_at IS NULL
         AND estado_facturacion = 'facturado';
    END IF;
  END IF;
  PERFORM set_config('app.bypass_cierre', 'off', true);
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.sync_cotizacion_embarque_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    -- FIX4 N-1: la reversión 'En operación' → 'Aceptada' es housekeeping de
    -- la papelera, no un cambio de estado del flujo comercial; la GUC
    -- transaccional lo deja pasar por guard_estado_cotizacion (patrón
    -- app.bypass_cierre).
    PERFORM set_config('app.liberando_papelera', 'on', true);
    UPDATE public.cotizaciones
       SET embarque_id = NULL,
           estado = CASE
             WHEN estado = 'En operación'::estado_cotizacion
               THEN 'Aceptada'::estado_cotizacion
             ELSE estado
           END,
           updated_at = now()
     WHERE embarque_id = NEW.id
       AND organization_id = NEW.organization_id;
    PERFORM set_config('app.liberando_papelera', 'off', true);
    RETURN NEW;
  END IF;
  IF NEW.cotizacion_id IS NOT NULL THEN
    PERFORM 1
      FROM public.cotizaciones
     WHERE id = NEW.cotizacion_id
       AND organization_id = NEW.organization_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'LC_COTIZACION_OTRA_ORG: la cotización no existe o pertenece a otra organización'
        USING ERRCODE = '23514',
              HINT    = json_build_object(
                'cotizacion_id', NEW.cotizacion_id,
                'organization_id', NEW.organization_id
              )::text;
    END IF;
    UPDATE public.cotizaciones
    SET
      embarque_id = NEW.id,
      estado = CASE
        WHEN estado = 'Aceptada'::estado_cotizacion
             AND NEW.estado <> 'Borrador'::estado_embarque
        THEN 'En operación'::estado_cotizacion
        ELSE estado
      END,
      updated_at = now()
    WHERE id = NEW.cotizacion_id
      AND organization_id = NEW.organization_id
      AND (
        embarque_id IS DISTINCT FROM NEW.id
        OR (estado = 'Aceptada'::estado_cotizacion AND NEW.estado <> 'Borrador'::estado_embarque)
      );
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.sync_embarque_desde_contenedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- B-10 (auditoría v14): un contenedor puede REASIGNARSE de embarque. Antes
  -- sólo se recalculaba COALESCE(NEW, OLD).embarque_id, así que el embarque
  -- origen se quedaba con el peso/volumen/piezas del contenedor que ya no le
  -- pertenece. Ahora se recalculan ambos lados del movimiento.
  PERFORM public._recompute_totales_embarque(NEW.embarque_id);
  IF TG_OP <> 'INSERT' AND OLD.embarque_id IS DISTINCT FROM NEW.embarque_id THEN
    PERFORM public._recompute_totales_embarque(OLD.embarque_id);
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;
CREATE FUNCTION public.sync_embarque_tiene_proforma() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.recompute_embarque_tiene_proforma(OLD.embarque_id);
    RETURN OLD;
  END IF;
  PERFORM public.recompute_embarque_tiene_proforma(NEW.embarque_id);
  IF TG_OP = 'UPDATE' AND OLD.embarque_id IS DISTINCT FROM NEW.embarque_id THEN
    PERFORM public.recompute_embarque_tiene_proforma(OLD.embarque_id);
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.sync_embarque_tiene_proforma_from_concepto() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_embarque uuid;
  v_new_embarque uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.proforma_id IS NOT NULL THEN
      SELECT embarque_id INTO v_old_embarque FROM public.proformas WHERE id = OLD.proforma_id;
      PERFORM public.recompute_embarque_tiene_proforma(v_old_embarque);
    END IF;
    RETURN OLD;
  ELSIF TG_OP = 'INSERT' THEN
    IF NEW.proforma_id IS NOT NULL THEN
      SELECT embarque_id INTO v_new_embarque FROM public.proformas WHERE id = NEW.proforma_id;
      PERFORM public.recompute_embarque_tiene_proforma(v_new_embarque);
    END IF;
    RETURN NEW;
  ELSE
    IF OLD.proforma_id IS DISTINCT FROM NEW.proforma_id THEN
      IF OLD.proforma_id IS NOT NULL THEN
        SELECT embarque_id INTO v_old_embarque FROM public.proformas WHERE id = OLD.proforma_id;
        PERFORM public.recompute_embarque_tiene_proforma(v_old_embarque);
      END IF;
      IF NEW.proforma_id IS NOT NULL THEN
        SELECT embarque_id INTO v_new_embarque FROM public.proformas WHERE id = NEW.proforma_id;
        PERFORM public.recompute_embarque_tiene_proforma(v_new_embarque);
      END IF;
    END IF;
    RETURN NEW;
  END IF;
END;
$$;
CREATE FUNCTION public.sync_pago_factura_embarque() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.factura_id IS NOT NULL AND NEW.embarque_id IS NULL THEN
    SELECT embarque_id INTO NEW.embarque_id
    FROM public.facturas
    WHERE id = NEW.factura_id;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.tc_dof_cobertura_faltante() RETURNS TABLE(tabla text, documento_id uuid, fecha date, moneda text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH docs AS (
    SELECT 'facturas'::text AS tabla, f.id, f.fecha_emision AS fecha, f.moneda::text AS moneda,
           f.tipo_cambio AS tc_doc, f.organization_id
    FROM public.facturas f
    WHERE f.deleted_at IS NULL AND f.moneda::text <> 'MXN'
    UNION ALL
    SELECT 'proveedor_facturas'::text, pf.id, pf.fecha_emision, pf.moneda::text,
           pf.tipo_cambio_usd, pf.organization_id
    FROM public.proveedor_facturas pf
    WHERE pf.deleted_at IS NULL AND pf.moneda::text <> 'MXN'
  )
  SELECT d.tabla, d.id, d.fecha, d.moneda
  FROM docs d
  CROSS JOIN LATERAL public.tc_para_documento(d.fecha, d.moneda, d.tc_doc, NULL) t
  WHERE d.organization_id = public.current_user_org_id()
    AND t.origen = 'sin_tc'
  ORDER BY d.fecha NULLS FIRST, d.tabla;
$$;
CREATE FUNCTION public.tc_dof_moneda(p_fecha date, p_moneda text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN UPPER(COALESCE(p_moneda,'MXN')) = 'MXN' THEN 1::numeric
    ELSE (
      SELECT CASE WHEN UPPER(p_moneda) = 'USD' THEN NULLIF(d.usd_mxn, 0)
                  WHEN UPPER(p_moneda) = 'EUR' THEN NULLIF(d.eur_mxn, 0)
                  ELSE NULL END
        FROM public.tipos_cambio_dof d
       WHERE d.fecha <= p_fecha
         AND CASE WHEN UPPER(p_moneda) = 'USD' THEN NULLIF(d.usd_mxn,0)
                  WHEN UPPER(p_moneda) = 'EUR' THEN NULLIF(d.eur_mxn,0)
                  ELSE NULL END IS NOT NULL
       ORDER BY d.fecha DESC
       LIMIT 1
    )
  END;
$$;
CREATE FUNCTION public.tc_dof_upsert_manual(_fecha date, _usd numeric, _eur numeric DEFAULT NULL::numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_previo record;
  v_email text;
BEGIN
  IF NOT public.has_role(v_uid, 'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_TC_DOF_FORBIDDEN: el tipo de cambio DOF es un catálogo global de la plataforma; sólo un super administrador puede capturarlo'
      USING ERRCODE = '42501';
  END IF;
  IF _usd IS NULL OR _usd <= 0 THEN
    RAISE EXCEPTION 'LC_TC_DOF_INVALIDO: el tipo de cambio USD debe ser mayor a cero'
      USING ERRCODE = '22023';
  END IF;
  IF _fecha IS NULL OR _fecha > CURRENT_DATE THEN
    RAISE EXCEPTION 'LC_TC_DOF_FECHA_INVALIDA: la fecha del tipo de cambio no puede ser futura'
      USING ERRCODE = '22023';
  END IF;
  SELECT fecha, usd_mxn, eur_mxn INTO v_previo
  FROM public.tipos_cambio_dof WHERE fecha = _fecha;
  INSERT INTO public.tipos_cambio_dof (fecha, usd_mxn, eur_mxn, fuente, origen)
  VALUES (_fecha, _usd, NULLIF(_eur, 0), 'banxico_sie', 'manual')
  ON CONFLICT (fecha) DO UPDATE
    SET usd_mxn = EXCLUDED.usd_mxn,
        eur_mxn = COALESCE(EXCLUDED.eur_mxn, public.tipos_cambio_dof.eur_mxn),
        origen  = 'manual',
        updated_at = now();
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, modulo, accion, entidad_id, entidad_nombre, detalles)
    VALUES (
      public.current_user_org_id(), v_uid, COALESCE(v_email, ''),
      'catalogos', 'tc_dof_upsert_manual', NULL, _fecha::text,
      jsonb_build_object(
        'fecha', _fecha,
        'usd_mxn', _usd,
        'eur_mxn', NULLIF(_eur, 0),
        'usd_mxn_previo', v_previo.usd_mxn,
        'eur_mxn_previo', v_previo.eur_mxn,
        'alcance', 'global_plataforma'
      )
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en tc_dof_upsert_manual: % %', SQLSTATE, SQLERRM;
  END;
END;
$$;
CREATE FUNCTION public.tc_dof_vigente(_fecha date DEFAULT CURRENT_DATE) RETURNS TABLE(fecha date, usd_mxn numeric, eur_mxn numeric, fuente text, origen text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT t.fecha, t.usd_mxn, t.eur_mxn, t.fuente, t.origen
  FROM public.tipos_cambio_dof t
  WHERE t.fecha <= _fecha
  ORDER BY t.fecha DESC
  LIMIT 1
$$;
CREATE FUNCTION public.tc_para_documento(_fecha date, _moneda text, _tc_documento numeric DEFAULT NULL::numeric, _tc_embarque numeric DEFAULT NULL::numeric) RETURNS TABLE(tc numeric, origen text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_moneda text := UPPER(COALESCE(_moneda, 'MXN'));
  v_dof numeric;
BEGIN
  IF v_moneda = 'MXN' THEN
    RETURN QUERY SELECT 1::numeric, 'mxn'::text;
    RETURN;
  END IF;
  IF COALESCE(_tc_documento, 0) > 1 THEN
    RETURN QUERY SELECT _tc_documento::numeric, 'cfdi'::text;
    RETURN;
  END IF;
  IF _fecha IS NOT NULL THEN
    SELECT CASE WHEN v_moneda = 'USD' THEN d.usd_mxn
                WHEN v_moneda = 'EUR' THEN d.eur_mxn END
      INTO v_dof
    FROM public.tc_dof_vigente(_fecha) d;
    IF COALESCE(v_dof, 0) > 1 THEN
      RETURN QUERY SELECT v_dof::numeric, 'dof'::text;
      RETURN;
    END IF;
  END IF;
  IF COALESCE(_tc_embarque, 0) > 1 THEN
    RETURN QUERY SELECT _tc_embarque::numeric, 'embarque'::text;
    RETURN;
  END IF;
  RETURN QUERY SELECT NULL::numeric, 'sin_tc'::text;
END;
$$;
CREATE FUNCTION public.tg_anticipo_saldo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public._recalc_anticipo_saldo(OLD.anticipo_id);
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' AND NEW.anticipo_id IS DISTINCT FROM OLD.anticipo_id THEN
    PERFORM public._recalc_anticipo_saldo(OLD.anticipo_id);
    PERFORM public._recalc_anticipo_saldo(NEW.anticipo_id);
    RETURN NEW;
  ELSE
    PERFORM public._recalc_anticipo_saldo(NEW.anticipo_id);
    RETURN NEW;
  END IF;
END;
$$;
CREATE FUNCTION public.tg_bloquear_embarque_cerrado_self() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_setting('app.bypass_cierre', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF TG_OP = 'DELETE' AND OLD.estado::text = 'Cerrado' THEN
    RAISE EXCEPTION 'No se puede eliminar un embarque cerrado';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.estado::text = 'Cerrado' THEN
    RAISE EXCEPTION 'Embarque cerrado: usa reabrir_embarque para modificarlo';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;
CREATE FUNCTION public.tg_bloquear_si_embarque_cerrado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emb_id uuid;
  v_estado text;
BEGIN
  IF current_setting('app.bypass_cierre', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  v_emb_id := COALESCE(
    (CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN row_to_json(NEW)->>'embarque_id' ELSE NULL END)::uuid,
    (CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN row_to_json(OLD)->>'embarque_id' ELSE NULL END)::uuid
  );
  IF v_emb_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  SELECT estado::text INTO v_estado FROM embarques WHERE id = v_emb_id;
  IF v_estado = 'Cerrado' THEN
    RAISE EXCEPTION 'Embarque cerrado: edición bloqueada (tabla %)', TG_TABLE_NAME
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;
CREATE FUNCTION public.tg_catalogo_claves_sat_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.tg_factura_cancelada_comisiones() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado IN ('Cancelada','Sustituida')
     AND OLD.estado IS DISTINCT FROM NEW.estado THEN
    UPDATE public.comisiones_devengadas
    SET estado = 'Cancelada',
        nota = trim(both ' ' FROM
              COALESCE(nota,'') || ' [auto] factura ' || NEW.estado::text ||
              ' (núm. ' || COALESCE(NEW.numero, NEW.id::text) || ')'),
        updated_at = now()
    WHERE factura_id = NEW.id
      AND estado = 'Devengada';
    -- QA-R2 N-07: las comisiones ya liquidadas no se cancelan
    -- retroactivamente; se marcan para recuperacion en la siguiente
    -- liquidacion.
    UPDATE public.comisiones_devengadas
    SET estado = 'Por recuperar',
        nota = trim(both ' ' FROM
              COALESCE(nota,'') || ' [auto] factura ' || NEW.estado::text ||
              ' con comision liquidada (núm. ' || COALESCE(NEW.numero, NEW.id::text) || ')'),
        updated_at = now()
    WHERE factura_id = NEW.id
      AND estado = 'Liquidada';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.tg_facturas_link_proforma() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.proforma_id IS NOT NULL AND NEW.deleted_at IS NULL
     AND NEW.estado NOT IN ('Cancelada'::estado_factura,'Sustituida'::estado_factura) THEN
    UPDATE public.proformas
       SET factura_id = NEW.id
     WHERE id = NEW.proforma_id
       AND (factura_id IS NULL OR factura_id <> NEW.id)
       AND deleted_at IS NULL;
  END IF;
  RETURN NEW;
END $$;
CREATE FUNCTION public.tg_liberar_folio_proveedor_factura() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_num      bigint;
  v_max_vivo bigint;
BEGIN
  -- Sólo cuando pasa a borrado (soft delete). Ignora restore o updates normales.
  IF NEW.deleted_at IS NULL OR OLD.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  -- Extrae número: FP-000046 -> 46
  v_num := NULLIF(regexp_replace(COALESCE(NEW.folio_interno, ''), '\D', '', 'g'), '')::bigint;
  IF v_num IS NULL THEN
    RETURN NEW;
  END IF;
  -- MAX numérico de folios activos (no borrados) para esta org
  SELECT COALESCE(
           MAX(NULLIF(regexp_replace(folio_interno, '\D', '', 'g'), '')::bigint),
           0
         )
    INTO v_max_vivo
    FROM public.proveedor_facturas
   WHERE organization_id = NEW.organization_id
     AND deleted_at IS NULL;
  -- Sólo retrocede el contador si NO quedan folios activos con número mayor.
  -- Reusar sólo si borraste la última; cubre borrado en cadena de las últimas.
  UPDATE public.folio_secuencias
     SET ultimo_numero = v_max_vivo,
         updated_at    = now()
   WHERE organization_id = NEW.organization_id
     AND tipo            = 'factura_proveedor'
     AND ultimo_numero   > v_max_vivo;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.tg_pago_factura_no_sobrepago() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saldo numeric;
  v_delta numeric;
  v_factura_org uuid;
  v_caller_org uuid;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.deleted_at IS NULL THEN
    v_delta := COALESCE(NEW.monto_aplicado_factura,0) - COALESCE(OLD.monto_aplicado_factura,0);
  ELSE
    v_delta := COALESCE(NEW.monto_aplicado_factura,0);
  END IF;
  IF v_delta <= 0 THEN RETURN NEW; END IF;
  -- FIX-R4-04: lock de la factura para serializar pagos concurrentes.
  PERFORM 1 FROM public.facturas
    WHERE id = NEW.factura_id AND deleted_at IS NULL FOR UPDATE;
  SELECT organization_id INTO v_factura_org
  FROM public.facturas
  WHERE id = NEW.factura_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN NEW; END IF;
  IF NEW.organization_id IS DISTINCT FROM v_factura_org THEN
    RAISE EXCEPTION 'LC_TENANT_MISMATCH: el pago debe pertenecer a la misma organización que la factura'
      USING ERRCODE='23514';
  END IF;
  v_caller_org := public.current_user_org_id();
  IF v_caller_org IS NOT NULL
     AND NOT public.has_role(auth.uid(), 'super_admin'::app_role)
     AND v_factura_org IS DISTINCT FROM v_caller_org THEN
    RETURN NEW;
  END IF;
  -- BUG-2026-08-25: saldo BRUTO (no el "por cobrar") para no bloquear la
  -- captura de pagos históricos de facturas ya marcadas como Pagada.
  SELECT COALESCE(public.saldo_factura_bruto(NEW.factura_id), 0) INTO v_saldo;
  IF TG_OP = 'UPDATE' THEN
    v_saldo := v_saldo + COALESCE(OLD.monto_aplicado_factura,0);
  END IF;
  IF v_delta > v_saldo + 0.005 THEN
    RAISE EXCEPTION 'LC_PAGO_EXCEDE_SALDO: pago % excede el saldo disponible % de la factura',
      round(v_delta,2), round(v_saldo,2)
      USING ERRCODE='P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.tg_pagos_factura_monto_convertido() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fact_moneda public.moneda;
  v_fact_tc     numeric;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT moneda, tipo_cambio INTO v_fact_moneda, v_fact_tc
  FROM public.facturas
  WHERE id = NEW.factura_id;
  IF v_fact_moneda IS NULL THEN
    RAISE EXCEPTION 'LC_FACTURA_NO_ENCONTRADA: factura % no existe', NEW.factura_id
      USING ERRCODE = 'P0002';
  END IF;
  NEW.monto_aplicado_factura := public.convertir_monto_pago_a_factura(
    NEW.monto,
    NEW.moneda,
    CASE WHEN NEW.moneda <> v_fact_moneda AND NEW.tipo_cambio = 1
         THEN NULL ELSE NEW.tipo_cambio END,
    v_fact_moneda,
    v_fact_tc
  );
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.tg_pagos_proveedor_recalc_liq() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP IN ('INSERT','UPDATE') THEN
    PERFORM recalcular_estado_liquidacion_factura(NEW.proveedor_factura_id);
  END IF;
  IF TG_OP = 'DELETE' THEN
    PERFORM recalcular_estado_liquidacion_factura(OLD.proveedor_factura_id);
  ELSIF TG_OP = 'UPDATE' AND OLD.proveedor_factura_id IS DISTINCT FROM NEW.proveedor_factura_id THEN
    PERFORM recalcular_estado_liquidacion_factura(OLD.proveedor_factura_id);
  END IF;
  RETURN NULL;
END $$;
CREATE FUNCTION public.tg_pagos_proveedor_requiere_aprobacion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado text;
BEGIN
  SELECT estado_aprobacion::text INTO v_estado
  FROM public.proveedor_facturas
  WHERE id = NEW.proveedor_factura_id;
  IF v_estado IS NULL THEN
    RAISE EXCEPTION 'Factura de proveedor no encontrada';
  END IF;
  IF v_estado <> 'aprobada' THEN
    RAISE EXCEPTION 'La factura debe estar aprobada para registrar pagos (estado actual: %)', v_estado
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.tg_pfc_recalc_liq() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP IN ('INSERT','UPDATE') AND NEW.concepto_costo_id IS NOT NULL THEN
    PERFORM recalcular_estado_liquidacion_concepto(NEW.concepto_costo_id);
  END IF;
  IF TG_OP = 'DELETE' AND OLD.concepto_costo_id IS NOT NULL THEN
    PERFORM recalcular_estado_liquidacion_concepto(OLD.concepto_costo_id);
  ELSIF TG_OP = 'UPDATE' AND OLD.concepto_costo_id IS NOT NULL
        AND OLD.concepto_costo_id IS DISTINCT FROM NEW.concepto_costo_id THEN
    PERFORM recalcular_estado_liquidacion_concepto(OLD.concepto_costo_id);
  END IF;
  RETURN NULL;
END $$;
CREATE FUNCTION public.tg_proforma_eur_no_soportada() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.estado_proforma='facturada' AND (OLD.estado_proforma IS DISTINCT FROM 'facturada') THEN
    IF EXISTS (
      SELECT 1 FROM public.conceptos_venta cv
      WHERE cv.proforma_id=NEW.id AND cv.deleted_at IS NULL AND cv.moneda='EUR'::public.moneda
    ) OR EXISTS (
      SELECT 1 FROM public.proforma_conceptos_consolidados pcc
      WHERE pcc.proforma_id=NEW.id AND pcc.deleted_at IS NULL AND pcc.moneda='EUR'::public.moneda
    ) THEN
      RAISE EXCEPTION 'LC_MONEDA_NO_SOPORTADA: la conversión de proformas con conceptos en EUR aún no está soportada'
        USING ERRCODE='22023';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE FUNCTION public.tg_proveedor_facturas_recalc_liq() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (NEW.estado IS DISTINCT FROM OLD.estado)
     OR (NEW.total IS DISTINCT FROM OLD.total)
     OR (NEW.deleted_at IS DISTINCT FROM OLD.deleted_at) THEN
    PERFORM recalcular_estado_liquidacion_factura(NEW.id);
  END IF;
  RETURN NULL;
END $$;
CREATE FUNCTION public.tg_recalcular_estado_factura_proveedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_factura_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_factura_id := OLD.proveedor_factura_id;
  ELSE
    v_factura_id := NEW.proveedor_factura_id;
    IF TG_OP = 'UPDATE' AND OLD.proveedor_factura_id IS DISTINCT FROM NEW.proveedor_factura_id THEN
      PERFORM public._recalc_estado_proveedor_factura(OLD.proveedor_factura_id);
    END IF;
  END IF;
  IF v_factura_id IS NOT NULL THEN
    PERFORM public._recalc_estado_proveedor_factura(v_factura_id);
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;
CREATE FUNCTION public.tg_reverse_ajustes_factura_proveedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_should_reverse boolean := false;
BEGIN
  -- Transición a Cancelada (desde cualquier otro estado)
  IF NEW.estado = 'Cancelada' AND (OLD.estado IS DISTINCT FROM 'Cancelada') THEN
    v_should_reverse := true;
  END IF;
  -- Soft-delete de la factura
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
    v_should_reverse := true;
  END IF;
  IF v_should_reverse THEN
    UPDATE public.conceptos_costo cc
    SET deleted_at = now(),
        deleted_by = NEW.deleted_by
    WHERE cc.deleted_at IS NULL
      AND cc.origen = 'ajuste_factura_proveedor'
      AND cc.id IN (
        SELECT pfc.concepto_costo_id
        FROM public.proveedor_facturas_conceptos pfc
        WHERE pfc.proveedor_factura_id = NEW.id
          AND pfc.concepto_costo_id IS NOT NULL
      );
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.touch_auditoria_revisiones() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.transicion_embarque_valida(p_actual public.estado_embarque, p_nuevo public.estado_embarque) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_actual = p_nuevo THEN RETURN true; END IF;
  -- BUG-09 (auditoría 2026-08-18): la regla blanket de cancelación se evaluaba
  -- antes del CASE y permitía 'Cerrado' -> 'Cancelado' con comisiones
  -- definitivas y CxC/CxP liquidadas. Un embarque cerrado debe reabrirse
  -- primero ('Por liquidar' o 'EIR') y cancelarse desde ahí.
  IF p_nuevo = 'Cancelado' AND p_actual NOT IN ('Cancelado', 'Cerrado') THEN
    RETURN true;
  END IF;
  RETURN CASE p_actual
    WHEN 'Borrador'     THEN p_nuevo IN ('Confirmado')
    WHEN 'Cotización'   THEN p_nuevo IN ('Confirmado','Borrador')
    WHEN 'Confirmado'   THEN p_nuevo IN ('En Tránsito','Borrador')
    WHEN 'En Tránsito'  THEN p_nuevo IN ('Arribo','En Proceso')
    WHEN 'Arribo'       THEN p_nuevo IN ('En Aduana','En Tránsito')
    WHEN 'En Aduana'    THEN p_nuevo IN ('Entregado','Arribo')
    WHEN 'Llegada'      THEN p_nuevo IN ('Arribo','En Aduana')
    WHEN 'Entregado'    THEN p_nuevo IN ('EIR','En Aduana','Cerrado')
    WHEN 'EIR'          THEN p_nuevo IN ('Por liquidar','Cerrado','Entregado')
    WHEN 'Por liquidar' THEN p_nuevo IN ('Cerrado','EIR')
    WHEN 'Cerrado'      THEN p_nuevo IN ('Por liquidar','EIR')
    WHEN 'En Proceso'   THEN p_nuevo IN ('En Tránsito','Arribo','En Aduana')
    WHEN 'Cancelado'    THEN false
    ELSE false
  END;
END;
$$;
CREATE FUNCTION public.transicion_garantia_valida(prev text, next text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE prev
    WHEN 'pendiente'  THEN next IN ('pendiente','depositado','retenido')
    WHEN 'depositado' THEN next IN ('depositado','liberado','retenido')
    WHEN 'retenido'   THEN next IN ('retenido','liberado')
    WHEN 'liberado'   THEN next = 'liberado'
    ELSE FALSE
  END;
$$;
CREATE FUNCTION public.trg_agentes_propaga_nombre() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.nombre IS DISTINCT FROM OLD.nombre THEN
    UPDATE public.embarques
       SET agente = NEW.nombre
     WHERE agente_id = NEW.id
       AND agente IS DISTINCT FROM NEW.nombre
       AND estado::text <> 'Cerrado'
       AND deleted_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_clientes_normaliza_campos() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.nombre IS NOT NULL THEN
    NEW.nombre := btrim(NEW.nombre);
    IF NEW.nombre = '' THEN
      RAISE EXCEPTION 'LC_CLIENTE_NOMBRE_REQUERIDO: el nombre no puede estar vacío'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF NEW.email IS NOT NULL THEN
    NEW.email := btrim(lower(NEW.email));
  END IF;
  IF NEW.rfc IS NOT NULL THEN
    NEW.rfc := btrim(upper(NEW.rfc));
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_clientes_propaga_nombre() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.nombre IS NOT DISTINCT FROM OLD.nombre THEN
    RETURN NEW;
  END IF;
  UPDATE public.cotizaciones
     SET cliente_nombre = NEW.nombre
   WHERE cliente_id = NEW.id
     AND cliente_nombre IS DISTINCT FROM NEW.nombre
     AND deleted_at IS NULL;
  UPDATE public.embarques
     SET cliente_nombre = NEW.nombre
   WHERE cliente_id = NEW.id
     AND cliente_nombre IS DISTINCT FROM NEW.nombre
     AND estado::text <> 'Cerrado'
     AND deleted_at IS NULL;
  UPDATE public.facturas
     SET cliente_nombre = NEW.nombre
   WHERE cliente_id = NEW.id
     AND estado = 'Borrador'
     AND cliente_nombre IS DISTINCT FROM NEW.nombre
     AND deleted_at IS NULL;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_conceptos_factura_rollup() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.recalc_factura_retenciones(OLD.factura_id);
    RETURN OLD;
  ELSE
    PERFORM public.recalc_factura_retenciones(NEW.factura_id);
    IF TG_OP = 'UPDATE' AND OLD.factura_id IS DISTINCT FROM NEW.factura_id THEN
      PERFORM public.recalc_factura_retenciones(OLD.factura_id);
    END IF;
    RETURN NEW;
  END IF;
END;
$$;
CREATE FUNCTION public.trg_costeo_demoras_tarifa_sync_org() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  SELECT c.organization_id INTO NEW.organization_id
    FROM public.costeo_navieras_condiciones c WHERE c.id = NEW.naviera_condicion_id;
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'LC_COSTEO_DEMORA_SIN_PADRE: naviera_condicion_id % no existe', NEW.naviera_condicion_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_costeo_recargos_sync_org() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  SELECT t.organization_id INTO NEW.organization_id
    FROM public.costeo_tarifas t WHERE t.id = NEW.tarifa_id;
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'LC_COSTEO_RECARGO_SIN_PADRE: tarifa_id % no existe', NEW.tarifa_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_costeo_tarifas_estado_derivado() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.estado := public.costeo_tarifa_estado_actual(NEW.estado, NEW.vigente_hasta);
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_cotizacion_subtotal_server() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_t record;
  v_n int;
BEGIN
  v_n := CASE WHEN jsonb_typeof(NEW.conceptos_venta) = 'array'
              THEN jsonb_array_length(NEW.conceptos_venta) ELSE 0 END;
  IF v_n = 0 THEN
    RETURN NEW;
  END IF;
  SELECT * INTO v_t FROM public.cotizacion_totales_conceptos(NEW.conceptos_venta);
  NEW.subtotal := COALESCE(
    NULLIF(CASE WHEN NEW.moneda::text = 'USD' THEN v_t.subtotal_usd ELSE v_t.subtotal_mxn END, 0),
    NULLIF(CASE WHEN NEW.moneda::text = 'USD' THEN v_t.subtotal_mxn ELSE v_t.subtotal_usd END, 0),
    0
  );
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_embarques_sync_espejos() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.cliente_id IS NOT NULL THEN
    SELECT c.nombre INTO NEW.cliente_nombre
      FROM public.clientes c WHERE c.id = NEW.cliente_id;
  END IF;
  IF NEW.naviera_id IS NOT NULL THEN
    SELECT n.name INTO NEW.naviera
      FROM public.navieras n WHERE n.id = NEW.naviera_id;
  END IF;
  IF NEW.agente_id IS NOT NULL THEN
    SELECT a.nombre INTO NEW.agente
      FROM public.costeo_agentes a WHERE a.id = NEW.agente_id;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_factura_tc_extranjera_obligatorio() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.moneda IS NOT NULL
     AND NEW.moneda <> 'MXN'::public.moneda
     AND NEW.estado = 'Borrador'::estado_factura
     AND NEW.tipo_cambio IS NOT NULL
     AND NEW.tipo_cambio = 1 THEN
    NEW.tipo_cambio := NULL;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_facturas_estado_a_embarques() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ids uuid[];
BEGIN
  SELECT array_agg(DISTINCT embarque_id)
  INTO v_ids
  FROM public.factura_embarques
  WHERE factura_id = NEW.id;
  IF v_ids IS NOT NULL THEN
    PERFORM public.recalcular_cobro_embarques(v_ids);
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_fn_embarque_transicion_valida() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Bypass controlado para backfills / migraciones legítimas.
  IF current_setting('app.bypass_transicion', true) = 'on' THEN
    RETURN NEW;
  END IF;
  -- FIX-R3-08: la transición a 'Cerrado' sólo puede ejecutarla cerrar_embarque(),
  -- que corre validar_cierre_embarque() y setea app.bypass_cierre='on'.
  IF NEW.estado = 'Cerrado'
     AND (OLD.estado IS DISTINCT FROM 'Cerrado')
     AND COALESCE(current_setting('app.bypass_cierre', true), 'off') <> 'on' THEN
    RAISE EXCEPTION 'LC_CIERRE_SOLO_RPC: use cerrar_embarque() para cerrar embarques' USING ERRCODE = 'P0001';
  END IF;
  PERFORM public.assert_transicion_embarque(OLD.estado, NEW.estado, NEW.expediente);
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_navieras_propaga_nombre() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.name IS DISTINCT FROM OLD.name THEN
    UPDATE public.embarques
       SET naviera = NEW.name
     WHERE naviera_id = NEW.id
       AND naviera IS DISTINCT FROM NEW.name
       AND estado::text <> 'Cerrado'
       AND deleted_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_notificar_cotizacion_enviada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ruta text;
  v_detalles text;
BEGIN
  IF NEW.estado = 'Enviada'::estado_cotizacion
     AND (OLD.estado IS DISTINCT FROM 'Enviada'::estado_cotizacion)
     AND NEW.cliente_id IS NOT NULL
     AND NEW.organization_id IS NOT NULL THEN
    v_ruta := nullif(concat_ws(' → ', nullif(NEW.origen, ''), nullif(NEW.destino, '')), '');
    v_detalles := nullif(concat_ws(' · ', v_ruta, nullif(NEW.tipo::text, '')), '');
    IF NOT EXISTS (
      SELECT 1 FROM public.notificaciones_cliente n
      WHERE n.cliente_id = NEW.cliente_id
        AND n.tipo = 'cotizacion_enviada'
        AND n.url = '/portal/cotizaciones/' || NEW.id
    ) THEN
      INSERT INTO public.notificaciones_cliente
        (cliente_id, organization_id, tipo, titulo, mensaje, url)
      VALUES (
        NEW.cliente_id, NEW.organization_id, 'cotizacion_enviada',
        trim('Nueva cotización enviada ' || coalesce(NEW.folio, '')),
        coalesce(v_detalles || '. ', '') || 'Tienes una nueva cotización lista para revisar.',
        '/portal/cotizaciones/' || NEW.id
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_pago_factura_comision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM calcular_comision_pago(COALESCE(NEW.id, OLD.id));
  RETURN COALESCE(NEW, OLD);
END;
$$;
CREATE FUNCTION public.trg_recalcular_demoras_al_entregar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estado = 'Entregado'::estado_embarque AND OLD.estado IS DISTINCT FROM NEW.estado THEN
    PERFORM public.calcular_demoras_embarque(NEW.id);
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.trg_recalcular_demoras_contenedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (
    NEW.fecha_descarga IS DISTINCT FROM OLD.fecha_descarga
    OR NEW.fecha_devolucion IS DISTINCT FROM OLD.fecha_devolucion
    OR NEW.dias_libres_override IS DISTINCT FROM OLD.dias_libres_override
  ) THEN
    PERFORM public.calcular_demoras_embarque(NEW.embarque_id);
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.validar_captura_entrante(p_documento_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid := public.current_user_org_id();
  v_doc public.embarque_facturas_entrantes%ROWTYPE;
  v_motivos text[] := ARRAY[]::text[];
  v_dup jsonb := NULL;
  v_proveedor jsonb := NULL;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'contador')
          OR public.has_role(auth.uid(), 'auxiliar_contable')
          OR public.has_role(auth.uid(), 'admin')
          OR public.has_role(auth.uid(), 'admin_org')
          OR public.has_role(auth.uid(), 'super_admin')) THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'LC_FORBIDDEN',
      'motivos', to_jsonb(ARRAY['Tu rol no puede capturar facturas de proveedor.']));
  END IF;
  SELECT * INTO v_doc FROM public.embarque_facturas_entrantes
   WHERE id = p_documento_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'LC_NOT_FOUND',
      'motivos', to_jsonb(ARRAY['El documento ya no existe en el buzón.']));
  END IF;
  IF v_doc.organization_id IS DISTINCT FROM v_caller_org AND NOT public.has_role(auth.uid(), 'super_admin') THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'LC_FORBIDDEN',
      'motivos', to_jsonb(ARRAY['El documento pertenece a otra organización.']));
  END IF;
  IF v_doc.estado <> 'por_capturar' THEN
    v_motivos := v_motivos || format('El documento ya fue %s.', v_doc.estado);
  END IF;
  IF v_doc.uuid_fiscal IS NOT NULL THEN
    SELECT jsonb_build_object(
             'id', f.id, 'folio_interno', f.folio_interno,
             'folio_proveedor', f.folio_proveedor, 'proveedor_nombre', f.proveedor_nombre,
             'estado', f.estado)
      INTO v_dup
      FROM public.proveedor_facturas f
     WHERE upper(btrim(f.uuid_fiscal)) = upper(btrim(v_doc.uuid_fiscal))
       AND f.deleted_at IS NULL
       AND f.organization_id = v_doc.organization_id
     LIMIT 1;
    IF v_dup IS NOT NULL THEN
      v_motivos := v_motivos || 'Este CFDI ya está capturado en otra factura de proveedor.';
    END IF;
  END IF;
  IF v_doc.rfc_emisor IS NOT NULL THEN
    SELECT jsonb_build_object('id', p.id, 'nombre', p.nombre, 'rfc', p.rfc)
      INTO v_proveedor
      FROM public.proveedores p
     WHERE p.organization_id = v_doc.organization_id
       AND upper(btrim(p.rfc)) = upper(btrim(v_doc.rfc_emisor))
       AND p.deleted_at IS NULL
     LIMIT 1;
  END IF;
  IF v_doc.proveedor_id IS NOT NULL AND v_proveedor IS NULL THEN
    SELECT jsonb_build_object('id', p.id, 'nombre', p.nombre, 'rfc', p.rfc)
      INTO v_proveedor
      FROM public.proveedores p
     WHERE p.id = v_doc.proveedor_id AND p.deleted_at IS NULL;
  END IF;
  RETURN jsonb_build_object(
    'ok', cardinality(v_motivos) = 0,
    'codigo', CASE WHEN cardinality(v_motivos) = 0 THEN 'OK' ELSE 'LC_VALIDACION' END,
    'motivos', to_jsonb(v_motivos),
    'documento', jsonb_build_object(
      'id', v_doc.id,
      'embarque_id', v_doc.embarque_id,
      'estado', v_doc.estado,
      'uuid_fiscal', v_doc.uuid_fiscal,
      'rfc_emisor', v_doc.rfc_emisor,
      'folio_detectado', COALESCE(v_doc.folio_serie, v_doc.folio_detectado),
      'fecha_emision', v_doc.fecha_emision,
      'total_detectado', v_doc.total_detectado,
      'moneda_detectada', v_doc.moneda_detectada,
      'archivo_path', v_doc.archivo_path,
      'xml_path', v_doc.xml_path,
      'nombre_archivo', v_doc.nombre_archivo
    ),
    'proveedor', v_proveedor,
    'factura_duplicada', v_dup
  );
END;
$$;
CREATE FUNCTION public.validar_cierre_embarque(p_embarque_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emb embarques%ROWTYPE;
  v_checks jsonb := '[]'::jsonb; v_puede boolean := true; v_ok boolean;
  v_cxc_saldo numeric := 0; v_cxc_por_moneda jsonb := '[]'::jsonb;
  v_cxc_pagadas_sin_pago int := 0;
  v_cxp_saldo numeric := 0; v_cxp_por_moneda jsonb := '[]'::jsonb;
  v_docs_faltantes int;
  v_utilidad_mxn numeric; v_venta_mxn numeric; v_margen_min numeric; v_margen_pct numeric;
  v_pnl jsonb; v_com_count int;
  v_cont_incompletos int := 0; v_cont_ids uuid[] := ARRAY[]::uuid[];
  v_cont_sin_fechas int := 0; v_cont_fechas_ids uuid[] := ARRAY[]::uuid[];
  v_tiene_contenedores boolean := false;
  v_venta_pendientes int; v_venta_en_proforma int;
  v_costos_sin_factura int;
  v_rep_pendientes int := 0; v_rep_ids uuid[] := ARRAY[]::uuid[];
  v_ent_pendientes int := 0; v_ent_dias_max int := 0;
  v_ent_total int := 0; v_ent_vacio boolean := false;
  v_prov_sin_evidencia int := 0; v_prov_nombres text[] := ARRAY[]::text[];
  v_caller_org uuid; v_uid uuid; v_is_service boolean;
BEGIN
  SELECT * INTO v_emb FROM embarques WHERE id=p_embarque_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Embarque no encontrado'; END IF;
  v_uid := auth.uid();
  v_caller_org := public.current_user_org_id();
  v_is_service := (COALESCE(auth.role()::text,'') = 'service_role');
  IF NOT v_is_service AND NOT public.has_role(v_uid, 'super_admin'::app_role) THEN
    IF v_caller_org IS NULL OR v_emb.organization_id <> v_caller_org THEN
      RAISE EXCEPTION 'LC_ORG_FORBIDDEN: sin acceso al embarque' USING ERRCODE='42501';
    END IF;
  END IF;
  IF v_emb.modo='Marítimo' AND COALESCE(v_emb.tipo_carga,'') ILIKE 'FCL%' THEN
    SELECT COUNT(*), COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_cont_incompletos, v_cont_ids
    FROM embarque_contenedores WHERE embarque_id=p_embarque_id AND deleted_at IS NULL
      AND (peso_kg IS NULL OR peso_kg<=0 OR volumen_m3 IS NULL OR volumen_m3<=0);
    v_ok := (v_cont_incompletos=0); v_puede := v_puede AND v_ok;
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'regla','contenedores_datos_completos','ok',v_ok,
      'detalle', jsonb_build_object('contenedores_incompletos', v_cont_incompletos, 'ids', v_cont_ids)));
  END IF;
  SELECT EXISTS (SELECT 1 FROM embarque_contenedores
    WHERE embarque_id=p_embarque_id AND deleted_at IS NULL) INTO v_tiene_contenedores;
  IF v_tiene_contenedores THEN
    SELECT COUNT(*), COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_cont_sin_fechas, v_cont_fechas_ids
    FROM embarque_contenedores WHERE embarque_id=p_embarque_id AND deleted_at IS NULL
      AND (fecha_descarga IS NULL OR fecha_devolucion IS NULL);
    v_ok := (v_cont_sin_fechas=0); v_puede := v_puede AND v_ok;
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'regla','contenedores_fechas_completas','ok',v_ok,
      'detalle', jsonb_build_object('contenedores_sin_fechas', v_cont_sin_fechas, 'ids', v_cont_fechas_ids)));
  END IF;
  SELECT COUNT(*) INTO v_docs_faltantes FROM documentos_embarque de
   WHERE de.embarque_id=p_embarque_id AND de.deleted_at IS NULL
     AND (de.archivo IS NULL OR de.archivo='') AND de.estado<>'No aplica';
  v_ok := (v_docs_faltantes=0); v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','docs_completos','ok',v_ok,
    'detalle', jsonb_build_object('faltantes', v_docs_faltantes)));
  SELECT COUNT(*) INTO v_costos_sin_factura FROM conceptos_costo cc
   WHERE cc.embarque_id=p_embarque_id AND cc.deleted_at IS NULL
     AND NOT EXISTS (
       SELECT 1 FROM proveedor_facturas_conceptos pfc
       JOIN proveedor_facturas pf2 ON pf2.id=pfc.proveedor_factura_id
       WHERE pfc.concepto_costo_id=cc.id AND pf2.deleted_at IS NULL AND pf2.estado<>'Cancelada');
  v_ok := (v_costos_sin_factura=0); v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','costo_conceptos_con_factura','ok',v_ok,
    'detalle', jsonb_build_object('sin_factura', v_costos_sin_factura)));
  -- Buzón CxP: ningún invoice puede quedar sin capturar.
  SELECT COUNT(*),
         COALESCE(MAX(GREATEST(0, (now()::date - efe.created_at::date))), 0)
    INTO v_ent_pendientes, v_ent_dias_max
    FROM embarque_facturas_entrantes efe
   WHERE efe.embarque_id=p_embarque_id AND efe.deleted_at IS NULL
     AND COALESCE(efe.estado,'por_capturar')='por_capturar';
  SELECT COUNT(*) INTO v_ent_total
    FROM embarque_facturas_entrantes efe
   WHERE efe.embarque_id=p_embarque_id AND efe.deleted_at IS NULL
     AND COALESCE(efe.estado,'por_capturar')<>'rechazada';
  v_ent_vacio := (v_ent_total=0 AND v_costos_sin_factura>0);
  v_ok := (v_ent_pendientes=0 AND NOT v_ent_vacio); v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','facturas_entrantes_capturadas','ok',v_ok,
    'detalle', jsonb_build_object('pendientes', v_ent_pendientes, 'dias_max', v_ent_dias_max,
      'buzon_vacio', v_ent_vacio, 'costos_sin_factura', v_costos_sin_factura)));
  -- Evidencia: cada proveedor con costos debe tener al menos un archivo en el
  -- buzón. v13.820.4: un costo ya ligado a una factura de proveedor vigente
  -- cuenta como evidencia aunque la factura no haya entrado por el buzón
  -- (captura directa desde Costos); antes el paso 1 quedaba pendiente para
  -- siempre pese a que el paso 3 estaba completo.
  SELECT COUNT(*), COALESCE(array_agg(nombre ORDER BY nombre), ARRAY[]::text[])
    INTO v_prov_sin_evidencia, v_prov_nombres
    FROM (
      SELECT DISTINCT COALESCE(NULLIF(cc.proveedor_nombre,''), 'Proveedor sin nombre') AS nombre
        FROM conceptos_costo cc
       WHERE cc.embarque_id=p_embarque_id AND cc.deleted_at IS NULL
         AND cc.proveedor_id IS NOT NULL
         AND NOT EXISTS (
           SELECT 1 FROM embarque_facturas_entrantes efe
            WHERE efe.embarque_id=p_embarque_id AND efe.deleted_at IS NULL
              AND efe.proveedor_id=cc.proveedor_id
              AND COALESCE(efe.estado,'por_capturar')<>'rechazada')
         AND NOT EXISTS (
           SELECT 1 FROM proveedor_facturas_conceptos pfc
           JOIN proveedor_facturas pf3 ON pf3.id=pfc.proveedor_factura_id
            WHERE pfc.concepto_costo_id=cc.id
              AND pf3.deleted_at IS NULL AND pf3.estado<>'Cancelada')
      UNION
      SELECT 'Costos sin proveedor asignado' AS nombre
       WHERE EXISTS (
         SELECT 1 FROM conceptos_costo cc2
          WHERE cc2.embarque_id=p_embarque_id AND cc2.deleted_at IS NULL
            AND cc2.proveedor_id IS NULL
            AND NOT EXISTS (
              SELECT 1 FROM proveedor_facturas_conceptos pfc2
              JOIN proveedor_facturas pf4 ON pf4.id=pfc2.proveedor_factura_id
               WHERE pfc2.concepto_costo_id=cc2.id
                 AND pf4.deleted_at IS NULL AND pf4.estado<>'Cancelada'))
    ) faltantes;
  v_ok := (v_prov_sin_evidencia=0); v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','facturas_entrantes_evidencia','ok',v_ok,
    'detalle', jsonb_build_object('proveedores_sin_evidencia', v_prov_sin_evidencia, 'proveedores', v_prov_nombres)));
  -- N-BL-01: el pagado CxP se convierte a la moneda de la factura con
  -- monto_pago_en_moneda_factura (antes sumaba pp.monto en crudo: una factura
  -- USD pagada en MXN inflaba el pagado ~19x y permitía cerrar con CxP
  -- pendiente). Fail-closed consistente con saldo_factura_proveedor: un pago
  -- sin tipo de cambio con moneda distinta se EXCLUYE del pagado (nunca 1:1
  -- silencioso) y se reporta en pagos_sin_tipo_cambio.
  WITH agg AS (
    SELECT COALESCE(pf.moneda,'MXN') AS moneda, COALESCE(SUM(pf.total),0) AS total,
      COALESCE(SUM((SELECT COALESCE(SUM(public.monto_pago_en_moneda_factura(
          pp.monto, pp.moneda::text, pp.tipo_cambio_usd, pf.moneda::text)),0)
        FROM pagos_proveedor pp
        WHERE pp.proveedor_factura_id=pf.id AND pp.deleted_at IS NULL)),0) AS pagado,
      COUNT(*) FILTER (WHERE pf.total > COALESCE((
        SELECT SUM(public.monto_pago_en_moneda_factura(
          pp.monto, pp.moneda::text, pp.tipo_cambio_usd, pf.moneda::text))
        FROM pagos_proveedor pp
        WHERE pp.proveedor_factura_id=pf.id AND pp.deleted_at IS NULL),0) + 0.01) AS facturas_pendientes,
      COUNT(*) FILTER (WHERE EXISTS (
        SELECT 1 FROM pagos_proveedor pp
        WHERE pp.proveedor_factura_id=pf.id AND pp.deleted_at IS NULL
          AND pp.moneda::text <> COALESCE(pf.moneda::text,'MXN')
          AND COALESCE(pp.tipo_cambio_usd, 0) <= 0)) AS pagos_sin_tipo_cambio
    FROM proveedor_facturas pf
    WHERE pf.embarque_id=p_embarque_id AND pf.deleted_at IS NULL AND pf.estado<>'Cancelada'
    GROUP BY COALESCE(pf.moneda,'MXN'))
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'moneda',moneda,'total',total,'pagado',pagado,
      'saldo',GREATEST(total-pagado,0),'facturas_pendientes',facturas_pendientes,
      'pagos_sin_tipo_cambio',pagos_sin_tipo_cambio
    ) ORDER BY moneda),'[]'::jsonb), COALESCE(SUM(GREATEST(total-pagado,0)),0)
  INTO v_cxp_por_moneda, v_cxp_saldo FROM agg;
  -- BUG-13: el umbral se evalúa POR moneda; sumar saldos de monedas distintas
  -- mezcla unidades y puede pasar con USD pendiente compensado con MXN.
  v_ok := NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_cxp_por_moneda) m
    WHERE (m->>'saldo')::numeric > 0.01);
  v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','cxp_pagada','ok',v_ok,
    'detalle', jsonb_build_object('por_moneda', v_cxp_por_moneda, 'saldo_total', v_cxp_saldo)));
  SELECT COUNT(*) FILTER (WHERE estado_facturacion='pendiente'),
         COUNT(*) FILTER (WHERE estado_facturacion='en_proforma')
    INTO v_venta_pendientes, v_venta_en_proforma
    FROM conceptos_venta WHERE embarque_id=p_embarque_id AND deleted_at IS NULL;
  v_ok := (v_venta_pendientes=0 AND v_venta_en_proforma=0); v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','venta_conceptos_facturados','ok',v_ok,
    'detalle', jsonb_build_object('pendientes', v_venta_pendientes, 'en_proforma', v_venta_en_proforma)));
  -- CxC: una factura con estado 'Pagada' se considera saldo 0 aunque no tenga
  -- pagos capturados (facturas históricas conciliadas fuera del sistema).
  SELECT COUNT(*) INTO v_cxc_pagadas_sin_pago
    FROM facturas f
   WHERE f.embarque_id=p_embarque_id AND f.deleted_at IS NULL AND f.estado='Pagada'
     AND public.saldo_factura(f.id) > 0.01;
  WITH agg AS (
    SELECT COALESCE(f.moneda,'MXN') AS moneda, COALESCE(SUM(f.total),0) AS total,
      COALESCE(SUM(CASE WHEN f.estado='Pagada' THEN 0
                        ELSE public.saldo_factura(f.id) END),0) AS saldo,
      COALESCE(SUM((SELECT COALESCE(SUM(pf.monto_aplicado_factura),0) FROM pagos_factura pf
        WHERE pf.factura_id=f.id AND pf.deleted_at IS NULL)),0) AS pagado,
      COALESCE(SUM((SELECT COALESCE(SUM(nc.monto),0) FROM factura_notas_credito nc
        WHERE nc.factura_id=f.id AND nc.deleted_at IS NULL AND nc.estado='Aplicada')),0) AS notas_credito,
      COUNT(*) FILTER (WHERE f.estado<>'Pagada' AND public.saldo_factura(f.id) > 0.01) AS facturas_pendientes
    FROM facturas f
    WHERE f.embarque_id=p_embarque_id AND f.deleted_at IS NULL
      AND f.estado NOT IN ('Cancelada','Sustituida','Borrador')
    GROUP BY COALESCE(f.moneda,'MXN'))
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'moneda',moneda,'total',total,'pagado',pagado,'notas_credito',notas_credito,
      'saldo',GREATEST(saldo,0),'facturas_pendientes',facturas_pendientes
    ) ORDER BY moneda),'[]'::jsonb), COALESCE(SUM(GREATEST(saldo,0)),0)
  INTO v_cxc_por_moneda, v_cxc_saldo FROM agg;
  -- BUG-13: el umbral se evalúa POR moneda; sumar saldos de monedas distintas
  -- mezcla unidades y puede pasar con USD pendiente compensado con MXN.
  v_ok := NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_cxc_por_moneda) m
    WHERE (m->>'saldo')::numeric > 0.01);
  v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','cxc_cobrada','ok',v_ok,
    'detalle', jsonb_build_object('por_moneda', v_cxc_por_moneda, 'saldo_total', v_cxc_saldo,
      'pagadas_sin_pago_registrado', v_cxc_pagadas_sin_pago)));
  SELECT COUNT(*), COALESCE(array_agg(pf.id), ARRAY[]::uuid[]) INTO v_rep_pendientes, v_rep_ids
    FROM pagos_factura pf JOIN facturas f ON f.id=pf.factura_id
   WHERE f.embarque_id=p_embarque_id AND f.deleted_at IS NULL
     AND f.estado NOT IN ('Cancelada','Sustituida','Borrador')
     AND pf.deleted_at IS NULL AND f.metodo_pago='PPD'
     AND COALESCE(pf.estado_rep,'Pendiente') NOT IN ('Timbrado','No aplica');
  v_ok := (v_rep_pendientes=0); v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','rep_timbrados','ok',v_ok,
    'detalle', jsonb_build_object('pendientes', v_rep_pendientes, 'ids', v_rep_ids)));
  -- Ola 2 · O2.2: se bloquea por pendientes REALES (nota de pendiente o
  -- cola de recálculo), no por la bandera `definitiva` que sólo se marca al
  -- cerrar (círculo vicioso que obligaba a "forzar" todos los cierres).
  SELECT COUNT(*) INTO v_com_count FROM comisiones_devengadas cd
   WHERE cd.embarque_id=p_embarque_id
     AND cd.estado='Devengada' AND cd.deleted_at IS NULL
     AND cd.nota IS NOT NULL;
  IF EXISTS (SELECT 1 FROM comisiones_recalculo_pendiente crp
               JOIN pagos_factura pf2 ON pf2.id = crp.pago_factura_id
               JOIN facturas f2 ON f2.id = pf2.factura_id
              WHERE f2.embarque_id = p_embarque_id
                AND crp.resuelto_at IS NULL) THEN
    v_com_count := v_com_count + 1;
  END IF;
  v_ok := (v_com_count=0); v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','comisiones_definitivas','ok',v_ok,
    'detalle', jsonb_build_object('no_definitivas', v_com_count)));
  BEGIN
    v_pnl := public.pnl_financiero_embarque(p_embarque_id);
    v_utilidad_mxn := COALESCE((v_pnl->>'utilidad_mxn')::numeric, 0);
    v_venta_mxn := COALESCE(
      (v_pnl->'venta'->>'real_mxn')::numeric,
      (v_pnl->>'venta_mxn')::numeric, 0);
  EXCEPTION WHEN OTHERS THEN
    v_utilidad_mxn := 0; v_venta_mxn := 0;
  END;
  SELECT COALESCE((SELECT valor::numeric FROM configuracion_global
     WHERE categoria='fiscal' AND clave='pnl_margen_minimo_cierre' LIMIT 1), 0) INTO v_margen_min;
  v_margen_pct := CASE WHEN v_venta_mxn>0 THEN ROUND(v_utilidad_mxn/v_venta_mxn*100.0,2) ELSE NULL END;
  v_ok := (v_margen_pct IS NOT NULL) AND (v_margen_pct >= v_margen_min);
  v_puede := v_puede AND v_ok;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'regla','margen_minimo','ok',v_ok,
    'detalle', jsonb_build_object(
      'utilidad_mxn', v_utilidad_mxn, 'venta_mxn', v_venta_mxn,
      'margen_pct', v_margen_pct, 'minimo_pct', v_margen_min)));
  RETURN jsonb_build_object('puede_cerrar', v_puede, 'checks', v_checks);
END $$;
CREATE FUNCTION public.validar_snooze_auditoria() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dias int;
BEGIN
  IF NEW.snoozed_until IS NULL THEN
    RETURN NEW;
  END IF;
  v_dias := (NEW.snoozed_until - CURRENT_DATE);
  IF v_dias < 0 THEN
    RAISE EXCEPTION 'No se puede silenciar un hallazgo en el pasado (snoozed_until=%).', NEW.snoozed_until
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_dias > 30 AND COALESCE(length(trim(NEW.snooze_motivo)), 0) < 20 THEN
    RAISE EXCEPTION 'Snooze mayor a 30 días requiere motivo justificado (al menos 20 caracteres). Días=% , motivo=%',
      v_dias, COALESCE(length(trim(NEW.snooze_motivo)), 0)
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.validate_cotizacion_informativa() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.tipo_documento = 'informativa' THEN
    IF NEW.vigencia_desde IS NULL OR NEW.vigencia_hasta IS NULL THEN
      RAISE EXCEPTION 'Cotización informativa requiere vigencia_desde y vigencia_hasta';
    END IF;
    IF NEW.vigencia_desde > NEW.vigencia_hasta THEN
      RAISE EXCEPTION 'vigencia_desde no puede ser posterior a vigencia_hasta';
    END IF;
    IF jsonb_array_length(COALESCE(NEW.tarifas_informativas, '[]'::jsonb)) < 1 THEN
      RAISE EXCEPTION 'Cotización informativa requiere al menos una tarifa';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE FUNCTION public.venta_embarque_mxn_neta(p_embarque_id uuid, p_tc_usd numeric, p_tc_eur numeric) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT GREATEST(
    COALESCE((
      SELECT SUM(public.convertir_a_mxn(cv.total, cv.moneda::text,
                                        NULLIF(p_tc_usd,0), NULLIF(p_tc_eur,0)))
      FROM public.conceptos_venta cv
      WHERE cv.embarque_id = p_embarque_id AND cv.deleted_at IS NULL), 0)
    - COALESCE((
      SELECT SUM(public.convertir_a_mxn(
               public.nc_aplicadas_en_moneda_factura(f.id), f.moneda::text,
               NULLIF(p_tc_usd,0), NULLIF(p_tc_eur,0)))
      FROM public.facturas f
      WHERE f.embarque_id = p_embarque_id AND f.deleted_at IS NULL
        AND f.estado NOT IN ('Cancelada','Sustituida','Borrador')), 0)
  , 0)::numeric;
$$;
CREATE FUNCTION public.vincular_anticipo_embarque(p_id uuid, p_embarque_id uuid DEFAULT NULL::uuid) RETURNS public.anticipos_proveedor
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.anticipos_proveedor;
  v_uid uuid := auth.uid();
  v_email text;
  v_autorizado boolean;
  v_emb_org uuid;
  v_anterior uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid
      AND ur.role::text = ANY (ARRAY['admin','admin_org','super_admin','contador','tesorero'])
  ) INTO v_autorizado;
  IF NOT v_autorizado THEN
    RAISE EXCEPTION 'LC_ANTICIPO_SIN_ROL: Sólo administradores, contabilidad o tesorería pueden vincular anticipos.'
      USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_row FROM public.anticipos_proveedor
  WHERE id = p_id AND deleted_at IS NULL;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'LC_ANTICIPO_NO_EXISTE: El anticipo no existe.';
  END IF;
  IF v_row.organization_id IS DISTINCT FROM public.current_user_org_id()
     AND NOT public.has_role(v_uid,'super_admin'::app_role) THEN
    RAISE EXCEPTION 'LC_ANTICIPO_OTRA_ORG: El anticipo pertenece a otra organización.';
  END IF;
  IF v_row.estado = 'cancelado' THEN
    RAISE EXCEPTION 'LC_ANTICIPO_CANCELADO: No se puede vincular un anticipo cancelado.';
  END IF;
  IF p_embarque_id IS NOT NULL THEN
    SELECT organization_id INTO v_emb_org FROM public.embarques WHERE id = p_embarque_id;
    IF v_emb_org IS NULL OR v_emb_org <> v_row.organization_id THEN
      RAISE EXCEPTION 'LC_ANTICIPO_EMBARQUE_INVALIDO: El embarque no existe o pertenece a otra organización.';
    END IF;
  END IF;
  v_anterior := v_row.embarque_id;
  UPDATE public.anticipos_proveedor
     SET embarque_id = p_embarque_id, updated_at = now()
   WHERE id = p_id
  RETURNING * INTO v_row;
  BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
    INSERT INTO public.bitacora_actividad
      (organization_id, usuario_id, usuario_email, accion, modulo, entidad_id, entidad_nombre, detalles)
    VALUES (v_row.organization_id, v_uid, COALESCE(v_email,''),
            CASE WHEN p_embarque_id IS NULL THEN 'desvincular_anticipo_embarque'
                 ELSE 'vincular_anticipo_embarque' END,
            'cxp', v_row.id, 'Anticipo ' || v_row.id::text,
            jsonb_build_object('embarque_id_anterior', v_anterior, 'embarque_id', p_embarque_id));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'bitacora insert failed en vincular_anticipo_embarque: % %', SQLSTATE, SQLERRM;
  END;
  RETURN v_row;
END;
$$;
CREATE TABLE public.agente_users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    agente_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE public.alertas_sistema (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    severity text DEFAULT 'warning'::text NOT NULL,
    source text NOT NULL,
    message text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb,
    dedupe_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    acknowledged_at timestamp with time zone,
    acknowledged_by uuid
);
CREATE TABLE public.app_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ts timestamp with time zone DEFAULT now() NOT NULL,
    level text NOT NULL,
    fn text NOT NULL,
    request_id uuid,
    user_id uuid,
    organization_id uuid,
    msg text NOT NULL,
    payload jsonb,
    latency_ms integer,
    status_code integer,
    CONSTRAINT app_logs_level_check CHECK ((level = ANY (ARRAY['info'::text, 'warn'::text, 'error'::text])))
);
CREATE TABLE public.auditoria_comentarios (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    revision_id uuid NOT NULL,
    autor_id uuid NOT NULL,
    autor_email text DEFAULT ''::text NOT NULL,
    contenido text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE public.auditoria_revisiones (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    embarque_id uuid NOT NULL,
    regla text NOT NULL,
    detalle_hash text NOT NULL,
    detalle text DEFAULT ''::text NOT NULL,
    accion_tomada text,
    revisado_por uuid,
    revisado_por_email text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    responsable_id uuid,
    responsable_email text DEFAULT ''::text NOT NULL,
    asignado_por uuid,
    asignado_por_email text DEFAULT ''::text NOT NULL,
    asignado_at timestamp with time zone,
    fecha_limite date,
    estado_revision public.estado_hallazgo_revision DEFAULT 'pendiente'::public.estado_hallazgo_revision NOT NULL,
    snoozed_until date,
    snooze_motivo text,
    revisado_at timestamp with time zone
);
CREATE TABLE public.auditoria_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    fecha date DEFAULT CURRENT_DATE NOT NULL,
    total_hallazgos integer DEFAULT 0 NOT NULL,
    total_pendientes integer DEFAULT 0 NOT NULL,
    criticos integer DEFAULT 0 NOT NULL,
    altos integer DEFAULT 0 NOT NULL,
    medios integer DEFAULT 0 NOT NULL,
    por_regla jsonb DEFAULT '{}'::jsonb NOT NULL,
    score integer DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE public.bbva_movimientos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    cuenta_bancaria_id uuid NOT NULL,
    fecha date NOT NULL,
    concepto text DEFAULT ''::text NOT NULL,
    referencia text DEFAULT ''::text NOT NULL,
    cargo numeric DEFAULT 0 NOT NULL,
    abono numeric DEFAULT 0 NOT NULL,
    saldo numeric,
    hash_dedupe text NOT NULL,
    estado_conciliacion public.estado_conciliacion DEFAULT 'Pendiente'::public.estado_conciliacion NOT NULL,
    pago_factura_id uuid,
    pago_proveedor_id uuid,
    motivo_ignorar text DEFAULT ''::text NOT NULL,
    conciliado_por uuid,
    conciliado_at timestamp with time zone,
    importado_por uuid,
    importado_en timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    anticipo_proveedor_id uuid,
    pago_proveedor_lote_id uuid,
    pago_factura_lote_id uuid,
    traspaso_id uuid,
    CONSTRAINT bbva_movimientos_cargo_abono_check CHECK (((cargo >= (0)::numeric) AND (abono >= (0)::numeric) AND ((((cargo > (0)::numeric))::integer + ((abono > (0)::numeric))::integer) = 1)))
);
ALTER TABLE ONLY public.bbva_movimientos FORCE ROW LEVEL SECURITY;
CREATE TABLE public.bitacora_actividad (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    usuario_id uuid,
    usuario_email text DEFAULT ''::text NOT NULL,
    accion text NOT NULL,
    modulo text NOT NULL,
    entidad_id uuid,
    entidad_nombre text DEFAULT ''::text,
    detalles jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id()
);
CREATE TABLE public.catalogo_claves_sat (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patron text NOT NULL,
    clave_sat text NOT NULL,
    prioridad integer DEFAULT 100 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    notas text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tipo_iva text DEFAULT 'gravado_16'::text NOT NULL,
    tasa_iva_default numeric,
    clave_unidad_sat text DEFAULT 'E48'::text NOT NULL,
    nombre_unidad text,
    CONSTRAINT catalogo_claves_sat_clave_len CHECK ((length(TRIM(BOTH FROM clave_sat)) >= 6)),
    CONSTRAINT catalogo_claves_sat_patron_len CHECK ((length(TRIM(BOTH FROM patron)) > 0)),
    CONSTRAINT catalogo_claves_sat_tipo_iva_chk CHECK ((tipo_iva = ANY (ARRAY['gravado_16'::text, 'gravado_8'::text, 'tasa_0'::text, 'exento'::text])))
);
CREATE TABLE public.cierre_embarque_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    embarque_id uuid NOT NULL,
    organization_id uuid,
    accion text NOT NULL,
    usuario_id uuid,
    motivo text,
    snapshot jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT cierre_embarque_log_accion_check CHECK ((accion = ANY (ARRAY['cerrar'::text, 'cerrar_forzado'::text, 'cerrar_automatico'::text, 'reabrir'::text])))
);
CREATE TABLE public.client_users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now()
);
CREATE TABLE public.cliente_documentos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    tipo text NOT NULL,
    nombre text NOT NULL,
    archivo text NOT NULL,
    mime_type text,
    tamano_bytes bigint,
    fecha_documento date,
    fecha_vencimiento date,
    notas text,
    uploaded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
