CREATE TABLE public.cotizacion_costos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cotizacion_id uuid NOT NULL,
    concepto text NOT NULL,
    moneda text NOT NULL,
    proveedor text DEFAULT ''::text NOT NULL,
    cantidad numeric DEFAULT 1 NOT NULL,
    costo_unitario numeric DEFAULT 0 NOT NULL,
    costo_total numeric GENERATED ALWAYS AS ((cantidad * costo_unitario)) STORED,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    precio_venta numeric DEFAULT 0 NOT NULL,
    precio_total numeric GENERATED ALWAYS AS ((cantidad * precio_venta)) STORED,
    profit numeric GENERATED ALWAYS AS (((cantidad * precio_venta) - (cantidad * costo_unitario))) STORED,
    porcentaje_profit numeric GENERATED ALWAYS AS (
CASE
    WHEN ((cantidad * precio_venta) = (0)::numeric) THEN (0)::numeric
    ELSE round(((((cantidad * precio_venta) - (cantidad * costo_unitario)) / (cantidad * precio_venta)) * (100)::numeric), 2)
END) STORED,
    unidad_medida text DEFAULT 'Contenedor'::text NOT NULL,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    notas text DEFAULT ''::text NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    costeo_tarifa_id uuid,
    costeo_tarifa_recargo_id uuid,
    CONSTRAINT cotizacion_costos_cantidad_pos CHECK ((cantidad >= (1)::numeric)),
    CONSTRAINT cotizacion_costos_costo_unit_nonneg CHECK ((costo_unitario >= (0)::numeric)),
    CONSTRAINT cotizacion_costos_moneda_check CHECK ((moneda = ANY (ARRAY['USD'::text, 'MXN'::text]))),
    CONSTRAINT cotizacion_costos_precio_venta_nonneg CHECK ((precio_venta >= (0)::numeric))
);
