    aeropuerto_destino text,
    aerolinea text,
    mawb text,
    hawb text,
    ciudad_origen text,
    ciudad_destino text,
    transportista text,
    carta_porte text,
    etd date,
    eta date,
    fecha_llegada_real date,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    tipo_cambio_usd numeric,
    tipo_cambio_eur numeric,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tipo_carga text DEFAULT 'Carga General'::text NOT NULL,
    msds_archivo text,
    agente text,
    cotizacion_id uuid,
    organization_id uuid DEFAULT public.current_user_org_id() NOT NULL,
    tiene_proforma boolean DEFAULT false NOT NULL,
    etd_original date,
    eta_original date,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    created_by uuid,
    created_by_email text,
    vendedora_id uuid,
    tarifa_id uuid,
    carta_garantia boolean DEFAULT false NOT NULL,
    dias_libres_destino integer DEFAULT 0 NOT NULL,
    dias_almacenaje integer DEFAULT 0 NOT NULL,
    seguro boolean DEFAULT false NOT NULL,
    valor_seguro_usd numeric(14,2),
    notas text,
    cerrado_at timestamp with time zone,
    cerrado_por uuid,
    cerrado_snapshot jsonb,
    reabierto_at timestamp with time zone,
    reabierto_por uuid,
    reabierto_motivo text,
    tarifa_id_original uuid,
    tarifa_id_aplicada uuid,
    tarifa_delta_jsonb jsonb,
    tarifa_decision text,
    tarifa_revalidada_en timestamp with time zone,
    tarifa_revalidada_por uuid,
    facturado_historico boolean DEFAULT false NOT NULL,
    cobro_cliente_status text DEFAULT 'pendiente'::text NOT NULL,
    cobro_cliente_actualizado_at timestamp with time zone,
    agente_id uuid,
    naviera_id uuid,
    sin_comision boolean,
    CONSTRAINT embarques_cobro_cliente_status_check CHECK ((cobro_cliente_status = ANY (ARRAY['pendiente'::text, 'parcial'::text, 'pagado'::text]))),
    CONSTRAINT embarques_eta_after_etd CHECK (((etd IS NULL) OR (eta IS NULL) OR (eta >= etd))),
    CONSTRAINT embarques_medidas_no_negativas CHECK (((COALESCE(peso_kg, (0)::numeric) >= (0)::numeric) AND (COALESCE(volumen_m3, (0)::numeric) >= (0)::numeric) AND (COALESCE(piezas, 0) >= 0))),
    CONSTRAINT embarques_peso_kg_nonneg CHECK ((peso_kg >= (0)::numeric)),
    CONSTRAINT embarques_piezas_nonneg CHECK ((piezas >= 0)),
    CONSTRAINT embarques_tarifa_decision_chk CHECK (((tarifa_decision IS NULL) OR (tarifa_decision = ANY (ARRAY['sin_cambios'::text, 'mantenida_por_operaciones'::text, 'refrescada'::text, 'sustituida'::text, 'reaprobada_ventas'::text])))),
    CONSTRAINT embarques_tc_eur_pos CHECK ((tipo_cambio_eur > (0)::numeric)),
    CONSTRAINT embarques_tc_usd_pos CHECK ((tipo_cambio_usd > (0)::numeric)),
    CONSTRAINT embarques_volumen_nonneg CHECK ((volumen_m3 >= (0)::numeric))
);
CREATE VIEW public.embarques_interno_v WITH (security_invoker='true') AS
 SELECT id,
    organization_id,
    cerrado_snapshot,
    tarifa_delta_jsonb,
    reabierto_motivo,
    created_by_email
   FROM public.embarques_internos_src() e(id, organization_id, cerrado_snapshot, tarifa_delta_jsonb, reabierto_motivo, created_by_email)
  WHERE (public.is_org_member(organization_id) AND (NOT public.has_role(( SELECT auth.uid() AS uid), 'cliente'::public.app_role)) AND (NOT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role)));
