CREATE POLICY "Admin catalog delete clientes" ON public.clientes FOR DELETE TO authenticated USING ((((organization_id = ( SELECT public.current_user_org_id() AS current_user_org_id)) OR ( SELECT public.has_role(( SELECT auth.uid() AS uid), 'super_admin'::public.app_role) AS has_role)) AND public.es_admin_catalogo(( SELECT auth.uid() AS uid))));
CREATE POLICY "Admin catalog delete proveedores" ON public.proveedores FOR DELETE TO authenticated USING ((((organization_id = ( SELECT public.current_user_org_id() AS current_user_org_id)) OR ( SELECT public.has_role(( SELECT auth.uid() AS uid), 'super_admin'::public.app_role) AS has_role)) AND public.es_admin_catalogo(( SELECT auth.uid() AS uid))));
CREATE POLICY "Admin delete proveedor_alias" ON public.proveedor_alias FOR DELETE TO authenticated USING ((((organization_id = ( SELECT public.current_user_org_id() AS current_user_org_id)) OR ( SELECT public.has_role(( SELECT auth.uid() AS uid), 'super_admin'::public.app_role) AS has_role)) AND public.es_admin_catalogo(( SELECT auth.uid() AS uid))));
CREATE POLICY "Agente CRUD own demoras tabulador" ON public.costeo_naviera_demoras_tarifa TO authenticated USING ((( SELECT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AS has_role) AND (EXISTS ( SELECT 1
   FROM public.costeo_navieras_condiciones nc
  WHERE ((nc.id = costeo_naviera_demoras_tarifa.naviera_condicion_id) AND (nc.organization_id = public.current_agente_org()) AND (nc.proveedor_id = public.current_agente_proveedor_id())))))) WITH CHECK ((( SELECT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AS has_role) AND (EXISTS ( SELECT 1
   FROM public.costeo_navieras_condiciones nc
  WHERE ((nc.id = costeo_naviera_demoras_tarifa.naviera_condicion_id) AND (nc.organization_id = public.current_agente_org()) AND (nc.proveedor_id = public.current_agente_proveedor_id()))))));
CREATE POLICY "Agente CRUD own naviera condiciones" ON public.costeo_navieras_condiciones TO authenticated USING ((( SELECT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AS has_role) AND (organization_id = public.current_agente_org()) AND (proveedor_id = public.current_agente_proveedor_id()))) WITH CHECK ((( SELECT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AS has_role) AND (organization_id = public.current_agente_org()) AND (proveedor_id = public.current_agente_proveedor_id())));
CREATE POLICY "Agente CRUD own recargos" ON public.costeo_tarifa_recargos TO authenticated USING ((( SELECT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AS has_role) AND (EXISTS ( SELECT 1
   FROM public.costeo_tarifas t
  WHERE ((t.id = costeo_tarifa_recargos.tarifa_id) AND (t.agente_id = ( SELECT public.current_agente_id() AS current_agente_id))))))) WITH CHECK ((( SELECT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AS has_role) AND (EXISTS ( SELECT 1
   FROM public.costeo_tarifas t
  WHERE ((t.id = costeo_tarifa_recargos.tarifa_id) AND (t.agente_id = ( SELECT public.current_agente_id() AS current_agente_id)))))));
CREATE POLICY "Agente borra solo tarifas no aprobadas" ON public.costeo_tarifas AS RESTRICTIVE FOR DELETE TO authenticated USING (((NOT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role)) OR (estado_aprobacion = ANY (ARRAY['borrador'::text, 'rechazada'::text]))));
CREATE POLICY "Agente escribe own tarifas" ON public.costeo_tarifas TO authenticated USING ((public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AND (agente_id = public.current_agente_id()) AND (organization_id = public.current_agente_org()))) WITH CHECK ((public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AND (agente_id = public.current_agente_id()) AND (organization_id = public.current_agente_org()) AND (estado_aprobacion = ANY (ARRAY['borrador'::text, 'rechazada'::text]))));
CREATE POLICY "Agente read org rutas" ON public.costeo_rutas FOR SELECT TO authenticated USING ((( SELECT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AS has_role) AND (organization_id = public.current_agente_org())));
CREATE POLICY "Agente read own documentos" ON public.documentos_embarque FOR SELECT USING ((( SELECT public.has_role(( SELECT auth.uid() AS uid), 'agente_carga'::public.app_role) AS has_role) AND (EXISTS ( SELECT 1
   FROM public.embarques e
  WHERE ((e.id = documentos_embarque.embarque_id) AND (e.organization_id = public.current_agente_org()) AND (e.agente_id IS NOT NULL) AND (e.agente_id = public.current_agente_id()))))));
