CREATE POLICY "Anyone can insert demo leads" ON public.demo_leads FOR INSERT TO anon, authenticated WITH CHECK (((nombre IS NOT NULL) AND ((length(btrim(nombre)) >= 2) AND (length(btrim(nombre)) <= 120)) AND (empresa IS NOT NULL) AND ((length(btrim(empresa)) >= 2) AND (length(btrim(empresa)) <= 160)) AND (email IS NOT NULL) AND (email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text) AND (length(email) <= 200) AND (telefono_e164 IS NOT NULL) AND (telefono_e164 ~ '^\+[1-9][0-9]{6,14}$'::text) AND ((user_agent IS NULL) OR (length(user_agent) <= 500))));
