-- ---------------------------------------------------------------------------
-- 3) Suplemento fuera de `public`: buckets y políticas de storage.
--    (Regenerado desde la base viva; `storage` no lo cubre el volcado public.)
-- ---------------------------------------------------------------------------
DO $STORAGE$
BEGIN
  IF to_regclass('storage.buckets') IS NULL THEN
    RAISE NOTICE 'storage no disponible: se omiten buckets';
    RETURN;
  END IF;
  INSERT INTO storage.buckets (id, name, public, file_size_limit)
  SELECT b, b, false, 25000000
    FROM unnest(ARRAY[
      'agente-cartas-garantia','cotizaciones-pdf','cxp-inbox','documentos',
      'facturas','facturas-pdf','reportes-feedback'
    ]) AS b
   WHERE NOT EXISTS (SELECT 1 FROM storage.buckets x WHERE x.id = b);
END
$STORAGE$;

-- Políticas de storage.objects (se omiten si el esquema no existe).
-- Requiere que `storage.objects` exista (Supabase real, o los stubs de
-- supabase/tests/rls/_ci_bootstrap.sql en CI).
DROP POLICY IF EXISTS "Admin/operador delete documentos" ON storage.objects;
CREATE POLICY "Admin/operador delete documentos" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated
  USING (((bucket_id = 'documentos'::text) AND (auth.uid() IS NOT NULL) AND can_manage_document_object(name)));
DROP POLICY IF EXISTS "Admin/operador update documentos" ON storage.objects;
CREATE POLICY "Admin/operador update documentos" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated
  USING (((bucket_id = 'documentos'::text) AND (auth.uid() IS NOT NULL) AND can_manage_document_object(name)))
  WITH CHECK (((bucket_id = 'documentos'::text) AND (auth.uid() IS NOT NULL) AND can_manage_document_object(name)));
