  WHERE ((om.user_id = auth.uid()) AND (om.role = ANY (ARRAY['admin'::app_role, 'admin_org'::app_role, 'gerente_operaciones'::app_role, 'coordinador_logistico'::app_role, 'ejecutivo_pricing'::app_role, 'operador'::app_role])) AND ((a.id)::text = (storage.foldername(objects.name))[1])))) OR (has_role(auth.uid(), 'agente_carga'::app_role) AND ((storage.foldername(name))[1] = (current_agente_id())::text)))));
