-- ---------------------------------------------------------------------------
-- 4) Suplemento: agendas de pg_cron. Se omiten con NOTICE si pg_cron no está
--    instalado (CI usa stubs). Los jobs HTTP copian sus encabezados de un job
--    existente para no versionar secretos.
-- ---------------------------------------------------------------------------
DO $CRONALL$
DECLARE
  v_tiene_cron boolean;
  v_jobid   bigint;
  v_cmd     text;
  v_headers text;
  v_base    text;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'cron' AND p.proname = 'schedule'
  ) INTO v_tiene_cron;

  IF NOT v_tiene_cron THEN
    RAISE NOTICE 'pg_cron no disponible: se omiten los agendados';
    RETURN;
  END IF;

  -- Facturas vencidas: 06:05 UTC (00:05 MX).
  SELECT jobid INTO v_jobid FROM cron.job WHERE jobname = 'marcar_facturas_vencidas_diario';
  IF v_jobid IS NOT NULL THEN PERFORM cron.unschedule(v_jobid); END IF;
  PERFORM cron.schedule(
    'marcar_facturas_vencidas_diario',
    '5 6 * * *',
    $CRON$ SELECT public.marcar_facturas_vencidas(); $CRON$
  );

  -- Reproceso de comisiones: 06:20 UTC (00:20 MX).
  SELECT jobid INTO v_jobid FROM cron.job WHERE jobname = 'reprocesar_comisiones_diario';
  IF v_jobid IS NOT NULL THEN PERFORM cron.unschedule(v_jobid); END IF;
  PERFORM cron.schedule(
    'reprocesar_comisiones_diario',
    '20 6 * * *',
    $CRON$ SELECT public.reprocesar_comisiones_job(); $CRON$
  );

  -- Purga de app_logs: 07:30 UTC (01:30 MX).
  SELECT jobid INTO v_jobid FROM cron.job WHERE jobname = 'purge_app_logs_diario';
  IF v_jobid IS NOT NULL THEN PERFORM cron.unschedule(v_jobid); END IF;
  PERFORM cron.schedule(
    'purge_app_logs_diario',
    '30 7 * * *',
    $CRON$ SELECT public.purge_app_logs_old(); $CRON$
  );

  -- Verificación SAT semanal (lunes 14:00 UTC ≈ 08:00 MX).
  SELECT command INTO v_cmd
    FROM cron.job
   WHERE jobname IN ('tc-dof-diario', 'rep-retry-nocturno')
   ORDER BY jobname
   LIMIT 1;

  IF v_cmd IS NULL THEN
    RAISE NOTICE 'Sin job HTTP de referencia: se omite verificar_sat_semanal';
    RETURN;
  END IF;

  v_headers := substring(v_cmd from 'headers := ''(\{.*\})''::jsonb');
  v_base    := substring(v_cmd from 'url := ''(https://[^/]+)/functions/v1/');

  IF v_headers IS NULL OR v_base IS NULL THEN
    RAISE NOTICE 'Encabezados ilegibles: se omite verificar_sat_semanal';
    RETURN;
  END IF;

  SELECT jobid INTO v_jobid FROM cron.job WHERE jobname = 'verificar_sat_semanal';
  IF v_jobid IS NOT NULL THEN PERFORM cron.unschedule(v_jobid); END IF;
  PERFORM cron.schedule(
    'verificar_sat_semanal',
    '0 14 * * 1',
    format(
      $CRON$SELECT net.http_post(url := %L, headers := %L::jsonb, body := jsonb_build_object('trigger','cron','at', now())) AS request_id;$CRON$,
      v_base || '/functions/v1/verificar-sat-semanal',
      v_headers
    )
  );
END
$CRONALL$;


--
-- v13.821.3 — Trigger de alta de usuarios (esquema `auth`).
--
-- El squash se generó con `pg_dump --schema=public`, así que el trigger que
-- corona al primer usuario y provisiona su membresía se quedó fuera y las
-- bases limpias arrancaban sin él (producción sí lo tiene, creado por
-- 20260616232751). Se recrea aquí de forma idempotente.
--
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user_signup();
